fn wrapBuiltin_htmlentities(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 1) return error.InvalidArgumentCount;
    const opt1 = if (args.len >= 2) args[1] else Value.initInt(11);
