pub fn php_func_get_args(args: []const Value, allocator: Allocator) !Value {
    if (args.len != 0) return error.InvalidArgumentCount;
    const arr = try PHPArray.init(allocator);
    if (current_call_args) |call_args| {
        for (call_args, 0..) |arg, i| {
            try arr.set(allocator, ArrayKey{ .integer = @intCast(i) }, arg);
        }
    }
    return Value.initArray(arr);
}

pub fn php_func_get_arg(index_val: Value) !Value {
    if (!index_val.isInt()) return error.InvalidArgument;
    const call_args = current_call_args orelse return Value.initBool(false);
    const index = index_val.asInt();
    if (index < 0) return Value.initBool(false);
    const idx: usize = @intCast(index);
    if (idx >= call_args.len) return Value.initBool(false);
    return call_args[idx];
}

pub fn php_func_num_args() !Value {
    const call_args = current_call_args orelse return Value.initInt(0);
    return Value.initInt(@intCast(call_args.len));
}

pub fn php_memory_get_usage(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (args.len > 1) return error.InvalidArgumentCount;
    return Value.initInt(@intCast(alloc_counters.live_bytes));
}

pub fn php_memory_get_peak_usage(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (args.len > 1) return error.InvalidArgumentCount;
    return Value.initInt(@intCast(alloc_counters.peak_live_bytes));
}

/// shell_exec - 执行shell命令并返回完整输出
extern "c" fn popen(command: [*:0]const u8, mode: [*:0]const u8) ?*anyopaque;
extern "c" fn pclose(stream: ?*anyopaque) c_int;
extern "c" fn fread(ptr: [*]u8, size: usize, nmemb: usize, stream: ?*anyopaque) usize;

pub fn php_shell_exec(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return Value.initNull();

    const cmd_val = args[0];
    if (!cmd_val.isString()) return Value.initNull();

    const cmd_str = cmd_val.asString().data;

    // ★批次十七①：Zig 0.17 移除 Child.run；std.process.run 在模板 getIo()（single_threaded Io）下
    //   spawn 返回错误（直调 shell_exec 实测 NULL）。改走 libc popen/fread/pclose（与既有 extern
    //   fork/waitpid 同族，产物链接行自带 -lc）。
    const cmd_z = allocator.dupeSentinel(u8, cmd_str, 0) catch return Value.initNull();
    defer allocator.free(cmd_z);
    const pipe = popen(cmd_z.ptr, "r") orelse return Value.initNull();
    defer _ = pclose(pipe);

    var out = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer out.deinit(allocator);
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = fread(rbuf[0..].ptr, 1, rbuf.len, pipe);
        if (n == 0) break;
        try out.appendSlice(allocator, rbuf[0..n]);
    }

    const output = try PHPString.init(allocator, out.items);
    return Value.initString(output);
}

/// exec - 执行命令并返回输出数组
/// PHP签名: exec(string $command, array &$output = null, int &$result_code = null): string|false
pub fn php_exec(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return Value.initNull();

    const cmd_val = args[0];
    if (!cmd_val.isString()) return Value.initNull();

    const cmd_str = cmd_val.asString().data;

    // ★批次十九·Q3：Zig 0.17 移除 Child.run ⇒ 迁 libc popen/fread/pclose（与 php_shell_exec 同族）；
    //   pclose 返回 wait 状态，退出码 = (status >> 8) & 0xFF（POSIX WEXITSTATUS）。
    const cmd_z = allocator.dupeSentinel(u8, cmd_str, 0) catch return Value.initBool(false);
    defer allocator.free(cmd_z);
    const pipe = popen(cmd_z.ptr, "r") orelse return Value.initBool(false);
    var out = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer out.deinit(allocator);
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = fread(rbuf[0..].ptr, 1, rbuf.len, pipe);
        if (n == 0) break;
        try out.appendSlice(allocator, rbuf[0..n]);
    }
    const wait_status = pclose(pipe);
    const exit_code: i64 = @intCast(@as(u32, @bitCast(wait_status)) >> 8 & 0xFF);

    // 将输出按行分割成数组
    const arr = try PHPArray.init(allocator);
    var lines = std.mem.splitScalar(u8, out.items, '\n');
    var idx: i64 = 0;
    var last_line: []const u8 = "";
    while (lines.next()) |line| {
        if (line.len == 0 and lines.peek() == null) break; // 跳过最后的空行
        last_line = line;
        const line_str = try PHPString.init(allocator, line);
        try arr.set(allocator, ArrayKey{ .integer = idx }, Value.initString(line_str));
        idx += 1;
    }

    // 如果有第二个参数（&$output引用），写回输出数组
    if (args.len >= 2) {
        const output_ref = args[1];
        if (output_ref.isRef()) {
            const ptr = output_ref.asRef();
            // 如果引用指向的是数组，追加到现有数组；否则替换为新数组
            if (ptr.isArray()) {
                const existing_arr = ptr.asArray();
                // 追加新行到现有数组
                var new_lines = std.mem.splitScalar(u8, out.items, '\n');
                while (new_lines.next()) |line| {
                    if (line.len == 0 and new_lines.peek() == null) break;
                    const line_str = try PHPString.init(allocator, line);
                    try existing_arr.push(allocator, Value.initString(line_str));
                }
            } else {
                // 替换为新数组
                ptr.release(allocator);
                _ = Value.initArray(arr).retain();
                ptr.* = Value.initArray(arr);
            }
        }
    }

    // 如果有第三个参数（&$return_code引用），写回返回码
    if (args.len >= 3) {
        const return_code_ref = args[2];
        if (return_code_ref.isRef()) {
            const ptr = return_code_ref.asRef();
            ptr.release(allocator);
            ptr.* = Value.initInt(exit_code);
        }
    }

    // 返回最后一行输出
    if (last_line.len > 0) {
        const last_str = try PHPString.init(allocator, last_line);
        return Value.initString(last_str);
    }
    return Value.initString(try PHPString.init(allocator, ""));
}

/// system - 执行命令，输出到stdout，返回最后一行
/// PHP签名: system(string $command, int &$result_code = null): string|false
pub fn php_system(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return Value.initNull();

    const cmd_val = args[0];
    if (!cmd_val.isString()) return Value.initNull();

    const cmd_str = cmd_val.asString().data;

    // ★批次十九·Q3：Zig 0.17 移除 Child.run ⇒ 迁 libc popen/fread/pclose（与 php_shell_exec 同族）
    const cmd_z = allocator.dupeSentinel(u8, cmd_str, 0) catch return Value.initBool(false);
    defer allocator.free(cmd_z);
    const pipe = popen(cmd_z.ptr, "r") orelse return Value.initBool(false);
    var out = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer out.deinit(allocator);
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = fread(rbuf[0..].ptr, 1, rbuf.len, pipe);
        if (n == 0) break;
        try out.appendSlice(allocator, rbuf[0..n]);
    }
    const wait_status = pclose(pipe);
    const exit_code: i64 = @intCast(@as(u32, @bitCast(wait_status)) >> 8 & 0xFF);

    // 输出到stdout（模拟PHP的system行为）
    if (out.items.len > 0) {
        fileWriteAll(1, out.items);
    }

    // 如果有第二个参数（&$return_var引用），写回返回码
    if (args.len >= 2) {
        const return_var_ref = args[1];
        if (return_var_ref.isRef()) {
            const ptr = return_var_ref.asRef();
            ptr.release(allocator);
            ptr.* = Value.initInt(exit_code);
        }
    }

    // 返回最后一行
    if (out.items.len == 0) return Value.initBool(false);

    var lines = std.mem.splitScalar(u8, out.items, '\n');
    var last_line: []const u8 = "";
    while (lines.next()) |line| {
        if (line.len > 0) last_line = line;
    }

    const last_str = try PHPString.init(allocator, last_line);
    return Value.initString(last_str);
}

/// escapeshellarg - 转义shell参数
/// PHP签名: escapeshellarg(string $arg): string
pub fn php_escapeshellarg(arg_val: Value, allocator: Allocator) !Value {
    if (!arg_val.isString()) {
        const str = try arg_val.toString(allocator);
        defer str.release(allocator);
        return php_escapeshellarg(Value.initString(str), allocator);
    }

    const arg = arg_val.asString().data;

    // 计算结果长度：每个单引号需要转义为 '\''，加上首尾的单引号
    var result_len: usize = 2; // 首尾单引号
    for (arg) |c| {
        if (c == '\'') {
            result_len += 4; // '\''
        } else {
            result_len += 1;
        }
    }

    const result = try allocator.alloc(u8, result_len);
    var pos: usize = 0;
    result[pos] = '\'';
    pos += 1;

    for (arg) |c| {
        if (c == '\'') {
            // 替换 ' 为 '\''
            result[pos] = '\'';
            result[pos + 1] = '\\';
            result[pos + 2] = '\'';
            result[pos + 3] = '\'';
            pos += 4;
        } else {
            result[pos] = c;
            pos += 1;
        }
    }

    result[pos] = '\'';

    const php_str = try PHPString.init(allocator, result);
    allocator.free(result);
    return Value.initString(php_str);
}

/// escapeshellcmd - 转义shell命令中的特殊字符
/// PHP签名: escapeshellcmd(string $command): string
pub fn php_escapeshellcmd(cmd_val: Value, allocator: Allocator) !Value {
    if (!cmd_val.isString()) {
        const str = try cmd_val.toString(allocator);
        defer str.release(allocator);
        return php_escapeshellcmd(Value.initString(str), allocator);
    }

    const cmd = cmd_val.asString().data;

    // 需要转义的字符: &#;`|*?~<>^()[]{}$\, \x0A, \xFF, 以及未配对的引号
    const special_chars = "&#;`|*?~<>^()[]{}$\\";

    // 计算结果长度
    var result_len: usize = 0;
    var single_quote_count: usize = 0;
    var double_quote_count: usize = 0;

    for (cmd) |c| {
        if (c == '\'') single_quote_count += 1;
        if (c == '"') double_quote_count += 1;

        var is_special = false;
        for (special_chars) |sc| {
            if (c == sc) {
                is_special = true;
                break;
            }
        }
        if (is_special or c == '\n' or c == 0xFF) {
            result_len += 2; // 添加反斜杠
        } else {
            result_len += 1;
        }
    }

    // 处理未配对的引号
    const escape_single = (single_quote_count % 2) == 1;
    const escape_double = (double_quote_count % 2) == 1;
    if (escape_single) result_len += single_quote_count;
    if (escape_double) result_len += double_quote_count;

    const result = try allocator.alloc(u8, result_len);
    var pos: usize = 0;

    for (cmd) |c| {
        // 检查是否是特殊字符
        var is_special = false;
        for (special_chars) |sc| {
            if (c == sc) {
                is_special = true;
                break;
            }
        }

        if (c == '\'' and escape_single) {
            result[pos] = '\\';
            result[pos + 1] = '\'';
            pos += 2;
        } else if (c == '"' and escape_double) {
            result[pos] = '\\';
            result[pos + 1] = '"';
            pos += 2;
        } else if (is_special or c == '\n' or c == 0xFF) {
            result[pos] = '\\';
            result[pos + 1] = c;
            pos += 2;
        } else {
            result[pos] = c;
            pos += 1;
        }
    }

    const php_str = try PHPString.init(allocator, result[0..pos]);
    allocator.free(result);
    return Value.initString(php_str);
}

/// substr_replace - 替换字符串的子串
pub fn php_substr_replace(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();

    // ★F-62f（R-255）：#1/#2 `array|string`；#3/#4 `array|int(|null)`；对象按 PHP 文案拒绝。
    const str_val = requireArrayOrStringParam("substr_replace", 1, "string", args[0]) orelse return Value.initNull();
    const replacement_val = requireArrayOrStringParam("substr_replace", 2, "replace", args[1]) orelse return Value.initNull();
    if (args.len >= 3) {
        if (args[2].isArray() and str_val.isString()) {
            throwThrowableDiscardCatch("TypeError", "substr_replace(): Argument #3 ($offset) cannot be an array when working on a single string", runtime_allocator);
            return Value.initNull();
        }
        _ = requireArrayOrIntParam("substr_replace", 3, "offset", "array|int", args[2]) orelse return Value.initNull();
    }
    if (args.len >= 4) {
        if (args[3].isArray() and str_val.isString()) {
            throwThrowableDiscardCatch("TypeError", "substr_replace(): Argument #4 ($length) cannot be an array when working on a single string", runtime_allocator);
            return Value.initNull();
        }
        _ = requireArrayOrIntParam("substr_replace", 4, "length", "array|int|null", args[3]) orelse return Value.initNull();
    }

    const start_arg: Value = if (args.len >= 3) args[2] else Value.initNull();
    const length_arg: Value = if (args.len >= 4) args[3] else Value.initNull();

    // ★F-162（R-257）：数组形 $string ⇒ 逐元素替换并保留键；标量 $string + 数组 $replace 取首元素。
    if (str_val.isArray()) {
        const out = try PHPArray.init(allocator);
        var it = str_val.asArray().elements.iterator();
        var idx: usize = 0;
        while (it.next()) |entry| : (idx += 1) {
            if (!entry.value_ptr.*.isString()) continue;
            const repl = substrReplaceReplacement(replacement_val, idx);
            const start = substrReplaceOffset(start_arg, idx);
            const length = substrReplaceLength(length_arg, idx);
            const v = try substrReplaceString(entry.value_ptr.*.asString().data, repl, start, length, allocator);
            defer v.release(allocator);
            const key = entry.key_ptr.*;
            if (key == .string) {
                const ks = try PHPString.init(allocator, key.string.data);
                defer ks.release(allocator);
                try out.set(allocator, .{ .string = ks }, v);
            } else {
                try out.set(allocator, key, v);
            }
        }
        return Value.initArray(out);
    }
    if (!str_val.isString()) return Value.initNull();

    const repl = substrReplaceReplacement(replacement_val, 0);
    return substrReplaceString(str_val.asString().data, repl, substrReplaceOffset(start_arg, 0), substrReplaceLength(length_arg, 0), allocator);
}

/// ★F-162（R-257）：数组形实参按**位置序**取第 idx 个元素（PHP 实测按序配对，不看键）。
fn arrayNthValue(arr: *PHPArray, idx: usize) ?Value {
    var it = arr.elements.iterator();
    var i: usize = 0;
    while (it.next()) |entry| : (i += 1) {
        if (i == idx) return entry.value_ptr.*;
    }
    return null;
}

fn substrReplaceReplacement(replacement: Value, idx: usize) []const u8 {
    if (replacement.isString()) return replacement.asString().data;
    if (replacement.isArray()) {
        if (arrayNthValue(replacement.asArray(), idx)) |v| {
            if (v.isString()) return v.asString().data;
        }
    }
    return "";
}

fn substrReplaceOffset(offset: Value, idx: usize) i64 {
    if (offset.isArray()) {
        if (arrayNthValue(offset.asArray(), idx)) |v| return v.toInt();
        return 0;
    }
    return offset.toInt();
}

fn substrReplaceLength(length: Value, idx: usize) ?i64 {
    if (length.isArray()) {
        if (arrayNthValue(length.asArray(), idx)) |v| return v.toInt();
        return null;
    }
    if (length.isNull()) return null;
    return length.toInt();
}

fn substrReplaceString(str: []const u8, replacement: []const u8, start: i64, length_in: ?i64, allocator: Allocator) !Value {
    const length = length_in orelse @as(i64, @intCast(str.len));

    // 处理负数索引
    const actual_start = if (start < 0)
        @max(0, @as(i64, @intCast(str.len)) + start)
    else
        @min(start, @as(i64, @intCast(str.len)));

    const actual_length = if (length < 0)
        @max(0, @as(i64, @intCast(str.len)) - actual_start + length)
    else
        @min(length, @as(i64, @intCast(str.len)) - actual_start);

    const start_idx = @as(usize, @intCast(actual_start));
    const end_idx = @as(usize, @intCast(actual_start + actual_length));

    // 构建结果字符串
    var result = try std.ArrayList(u8).initCapacity(allocator, str.len + replacement.len);
    errdefer result.deinit(allocator);

    try result.appendSlice(allocator, str[0..start_idx]);
    try result.appendSlice(allocator, replacement);
    if (end_idx < str.len) {
        try result.appendSlice(allocator, str[end_idx..]);
    }

    const output = try PHPString.init(allocator, try result.toOwnedSlice(allocator));
    return Value.initString(output);
}

// ============================================================================
// ★M2-2：协程感知 IO（NetPoller 让出）——流族 read/write 的统一出入口
//   设计：docs/design/2026-11-08-go-style-coroutine-design.md §M2 / §3.4
//   - 普通文件恒就绪 ⇒ 不做任何 poll（零开销；file/php://memory/temp/input 全走此路）；
//   - 管道/终端/stdio ⇒ poll(POLLIN/POLLOUT) 就绪后再 syscall（poll 保证随后 syscall 不长阻塞）；
//   - socket 对（O_NONBLOCK）⇒ syscall 先试，EAGAIN 再挂 NetPoller 让出重试（快路径零 poll）。
//   仅在协程体系活跃（ioYieldActive）时让出；无协程程序与原实现逐字节等价。
// ============================================================================

/// 阻塞 fd 的单次写块上限：POSIX 保证 poll(POLLOUT) 后可无阻塞写入 PIPE_BUF（各平台最小 512）。
const Q4_IO_CHUNK: usize = 512;

/// fd 阻塞类别判定（fstat；普通文件恒就绪，跳过 poll）。
fn q4ClassifyFd(fd: std.posix.fd_t) Value.PHPResource.WaitMode {
    var st: std.c.Stat = undefined;
    if (std.c.fstat(fd, &st) != 0) return .blocking;
    return if (st.mode & std.c.S.IFMT == std.c.S.IFREG) .always_ready else .blocking;
}

/// 协程感知读（**底层**，绕过用户态缓冲）：返回实际读字节数（0=EOF/超时/非阻塞无数据）。
/// 上层一律经 `q4BufferedRead` / `q4BufferedByte`——缓冲解决 stream_get_line 回滚、fscanf 回推，
/// 并把 fgets/fgetc 的「每字节一次 syscall」摊薄为「每 8KB 一次」。
/// ★M2-2-b 读超时：等待截止 ⇒ 置 res.timed_out 并返回 0（调用方据此返回 false/部分内容）；
///   成功读（含 EOF 的 0 字节）复位 timed_out（PHP 实测口径）。
/// ★M2-2-c 非阻塞：`stream_set_blocking(false)` 或 `(0,0)` 超时 ⇒ 不挂 NetPoller、不置 timed_out，
///   置 res.would_block 并返回 0（调用方据此区分 EOF 与「暂无数据」）。
fn q4ReadFh(res: *Value.PHPResource, fh: *std.Io.File, buf: []u8) !usize {
    res.would_block = false;
    // 非阻塞读判定：显式 set_blocking(false)，或零超时（(0,0)——PHP 实测与 set_blocking(false) 同效）
    const nonblocking_read = !res.blocked or (if (res.read_timeout_ms) |ms| ms == 0 else false);
    if (res.wait_mode == .nonblocking) {
        while (true) {
            const n = std.posix.read(fh.handle, buf) catch |err| switch (err) {
                error.WouldBlock => {
                    if (nonblocking_read) {
                        res.would_block = true;
                        return 0;
                    }
                    const t = res.read_timeout_ms;
                    if (!concurrency.waitFd(fh.handle, concurrency.IO_READABLE, t)) {
                        res.timed_out = true;
                        return 0;
                    }
                    continue;
                },
                else => return err,
            };
            res.timed_out = false;
            return n;
        }
    }
    // 阻塞类 fd（普通文件恒就绪 / 管道/终端）：非阻塞读用 poll(0) 快检，不占用调度器
    if (nonblocking_read and res.wait_mode != .always_ready) {
        if (!concurrency.waitFd(fh.handle, concurrency.IO_READABLE, 0)) {
            res.would_block = true;
            return 0;
        }
    } else if (res.wait_mode == .blocking and concurrency.ioYieldActive()) {
        const t = res.read_timeout_ms; // 当前仅 socket 流有超时（管道/终端恒 null）
        if (!concurrency.waitFd(fh.handle, concurrency.IO_READABLE, t)) {
            res.timed_out = true;
            return 0;
        }
    }
    const n = try std.posix.read(fh.handle, buf);
    res.timed_out = false;
    return n;
}

/// 协程感知写：返回累计写入字节数；阻塞口径下 EAGAIN/部分写按让出重试，错误上抛。
/// ★M2-2-c 非阻塞写（stream_set_blocking(false)）：单次试写，EAGAIN ⇒ 0、部分写 ⇒ 实际字节数
///   （PHP 8.5.8 实测：满缓冲 fwrite 返 0，部分写返部分长度）；普通文件恒就绪 ⇒ 仍写全量。
fn q4WriteFh(res: *Value.PHPResource, fh: *std.Io.File, bytes: []const u8) !usize {
    if (!res.blocked and res.wait_mode != .always_ready) {
        if (res.wait_mode == .blocking) {
            // 阻塞 fd（管道/终端）：逻辑非阻塞须先 poll(0) 快检——否则满缓冲 write 会真阻塞；
            // 可写 ⇒ 至多 PIPE_BUF 一次写（POSIX 保证 poll(POLLOUT) 后该量不阻塞）。
            if (!concurrency.waitFd(fh.handle, concurrency.IO_WRITABLE, 0)) return 0;
            const chunk = bytes[0..@min(bytes.len, Q4_IO_CHUNK)];
            while (true) {
                const n = q4WriteFd(fh.handle, chunk) catch |err| switch (err) {
                    error.Interrupted => continue,
                    error.WouldBlock => return 0,
                    else => return err,
                };
                return n;
            }
        }
        // O_NONBLOCK fd（socket 对）：直接试写，EAGAIN ⇒ 0、部分写 ⇒ 实际字节数
        while (true) {
            const n = q4WriteFd(fh.handle, bytes) catch |err| switch (err) {
                error.Interrupted => continue,
                error.WouldBlock => return 0,
                else => return err,
            };
            return n;
        }
    }
    const yielding = res.wait_mode != .always_ready and concurrency.ioYieldActive();
    var written: usize = 0;
    while (written < bytes.len) {
        const rest = bytes[written..];
        // 阻塞 fd：分块 + 先等 POLLOUT（poll 保证随后整块写不长阻塞）；
        // 非阻塞 fd：整段试写，EAGAIN 再等（快路径零 poll）。
        const chunk = if (res.wait_mode == .blocking and yielding) rest[0..@min(rest.len, Q4_IO_CHUNK)] else rest;
        if (res.wait_mode == .blocking and yielding) _ = concurrency.waitFd(fh.handle, concurrency.IO_WRITABLE, null);
        const n = q4WriteFd(fh.handle, chunk) catch |err| switch (err) {
            error.Interrupted => continue,
            error.WouldBlock => {
                _ = concurrency.waitFd(fh.handle, concurrency.IO_WRITABLE, null);
                continue;
            },
            else => return err,
        };
        if (n == 0) break;
        written += n;
    }
    return written;
}

/// 单次 write(2)（Zig 0.17 无 std.posix.write ⇒ libc 直调 + errno 归类）。
fn q4WriteFd(fd: std.posix.fd_t, bytes: []const u8) !usize {
    const n = std.c.write(fd, bytes.ptr, bytes.len);
    if (n >= 0) return @intCast(n);
    return switch (std.c._errno().*) {
        @intFromEnum(std.c.E.AGAIN) => error.WouldBlock,
        @intFromEnum(std.c.E.INTR) => error.Interrupted,
        @intFromEnum(std.c.E.PIPE) => error.BrokenPipe,
        @intFromEnum(std.c.E.BADF) => error.NotOpenForWriting,
        @intFromEnum(std.c.E.NOSPC) => error.NoSpaceLeft,
        else => error.WriteFailed,
    };
}

// ---- ★M2-2-h 用户态读缓冲（仅非普通文件：管道/终端/socket） ----

/// 缓冲填充块大小（同 PHP 的 chunk_size 默认值）。
const Q4_BUF_CHUNK: usize = 8192;
/// 回推安全阀：单次回推超过该量即丢弃（不可 seek 流与 PHP 的 seek 失败丢数据同径，防内存爆）。
const Q4_BUF_UNREAD_MAX: usize = 8 * 1024 * 1024;

inline fn q4BufEnabled(res: *Value.PHPResource) bool {
    // 普通文件直读：用户态预读会让 ftell/fseek 位置失真，且无回滚/回推需求。
    return res.wait_mode != .always_ready;
}

inline fn q4BufAvail(res: *Value.PHPResource) usize {
    return res.read_buf.items.len - res.read_pos;
}

/// 消费 n 字节；全部消费完即重置（容量保留复用）。
fn q4BufConsume(res: *Value.PHPResource, n: usize) void {
    res.read_pos += n;
    if (res.read_pos >= res.read_buf.items.len) {
        res.read_buf.clearRetainingCapacity();
        res.read_pos = 0;
    }
}

/// 把 bytes 放回未消费区间头部（bytes 在前、原有未消费在后）。
fn q4BufUnread(res: *Value.PHPResource, allocator: Allocator, bytes: []const u8) void {
    if (bytes.len == 0 or bytes.len > Q4_BUF_UNREAD_MAX) return;
    res.read_buf.insertSlice(allocator, res.read_pos, bytes) catch {};
}

/// 协程感知**缓冲**读：先取用户态缓冲；缓冲空则走底层（含超时/非阻塞/NetPoller 让出）。
fn q4BufferedRead(res: *Value.PHPResource, fh: *std.Io.File, dst: []u8) !usize {
    if (!q4BufEnabled(res)) return q4ReadFh(res, fh, dst);
    const avail = q4BufAvail(res);
    if (avail > 0) {
        const take = @min(avail, dst.len);
        @memcpy(dst[0..take], res.read_buf.items[res.read_pos..][0..take]);
        q4BufConsume(res, take);
        // 本次确实取到数据 ⇒ 清「无数据」与「超时」状态（PHP 口径：成功读复位 timed_out；
        //   would_block 若不复位，会把上一次 fscanf/stream_get_line 的遗留态误带给调用方）
        res.would_block = false;
        res.timed_out = false;
        return take;
    }
    return q4ReadFh(res, fh, dst);
}

/// 取一字节（fgets/fgetc/csv/get_line 共用）：缓冲空时按 8KB 块填充再弹出。
/// 返回 1＝取到（写 *out）；0＝无字节（据 res.timed_out/would_block 区分超时/非阻塞，否则为 EOF）。
fn q4BufferedByte(res: *Value.PHPResource, fh: *std.Io.File, allocator: Allocator, out: *u8) !usize {
    if (!q4BufEnabled(res)) {
        var one: [1]u8 = undefined;
        const n = try q4ReadFh(res, fh, &one);
        if (n == 0) return 0;
        out.* = one[0];
        return 1;
    }
    if (q4BufAvail(res) == 0) {
        var tmp: [Q4_BUF_CHUNK]u8 = undefined;
        const n = try q4ReadFh(res, fh, &tmp);
        if (n == 0) return 0;
        try res.read_buf.appendSlice(allocator, tmp[0..n]);
    }
    out.* = res.read_buf.items[res.read_pos];
    q4BufConsume(res, 1);
    res.would_block = false; // 取到数据 ⇒ 清遗留「无数据」态
    res.timed_out = false;
    return 1;
}

/// echo/print/printf 的输出口（★M2-2）：协程活跃期对管道/终端分块 + POLLOUT 让出，
/// stdout 背压（慢消费者）不再卡死整个调度器；无协程或重定向到普通文件 ⇒ 一次直写（等价旧路径）。
/// 诊断/致命路径仍走 fileWriteAll —— 那里让出会把 fatal 打印挂进调度器。
fn q4OutputWrite(bytes: []const u8) void {
    if (!concurrency.ioYieldActive() or q4StdFdAlwaysReady(1)) {
        _ = std.posix.system.write(1, bytes.ptr, bytes.len);
        return;
    }
    var written: usize = 0;
    while (written < bytes.len) {
        const chunk = bytes[written..][0..@min(bytes.len - written, Q4_IO_CHUNK)];
        _ = concurrency.waitFd(1, concurrency.IO_WRITABLE, null);
        const n = q4WriteFd(1, chunk) catch break;
        if (n == 0) break;
        written += n;
    }
}

/// 标准 fd 恒就绪缓存（-1 未探测）：重定向到普通文件 ⇒ 直写；管道/终端 ⇒ 让出治理。
var q4_std_fd_ready: [2]i8 = .{ -1, -1 };
fn q4StdFdAlwaysReady(fd: std.posix.fd_t) bool {
    const idx: usize = if (fd == 1) 0 else 1;
    var v = q4_std_fd_ready[idx];
    if (v < 0) {
        v = if (q4ClassifyFd(fd) == .always_ready) 1 else 0;
        q4_std_fd_ready[idx] = v;
    }
    return v == 1;
}

// ============================================================================
// 文件I/O函数
// ============================================================================

/// file_put_contents - PHP 契约：filename, data, flags=0, context=null
///   ★R-274：补 `FILE_APPEND`(8)（原实现恒截断）；`LOCK_EX` 与 context 未建模（仅吞下）。
pub fn php_file_put_contents(filename: Value, data: Value, flags: Value, context: Value, allocator: Allocator) !Value {
    _ = context;
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;

    const content_str = if (data.isString())
        data.asString().data
    else blk: {
        const temp = try data.toString(allocator);
        defer temp.release(allocator);
        break :blk temp.data;
    };

    const flag_bits = flags.toInt();
    const append = (flag_bits & 8) != 0;
    if (append) {
        var ofile = std.Io.Dir.cwd().openFile(getIo(), fname, .{ .mode = .write_only }) catch {
            // PHP 实测：FILE_APPEND 下文件不存在则创建
            const nf = std.Io.Dir.cwd().createFile(getIo(), fname, .{}) catch return Value.initBool(false);
            defer nf.close(getIo());
            fileWriteAll(nf.handle, content_str);
            return Value.initInt(@intCast(content_str.len));
        };
        defer ofile.close(getIo());
        _ = streamLseek(&ofile, 0, 2) catch return Value.initBool(false);
        fileWriteAll(ofile.handle, content_str);
        return Value.initInt(@intCast(content_str.len));
    }

    const file = std.Io.Dir.cwd().createFile(getIo(), fname, .{}) catch return Value.initBool(false);
    defer file.close(getIo());
    fileWriteAll(file.handle, content_str);
    return Value.initInt(@intCast(content_str.len));
}

/// file_get_contents - PHP 契约：filename, use_include_path=false, context=null, offset=0, length=null
///   ★F-173（R-270）：补 offset（负值自尾部）/length（null＝至末尾、0＝空串、负数 ValueError）与 seek 失败告警；
///   `use_include_path`/`context` 未建模（AOT 无 include_path、无 stream context）⇒ 仅吞下。
pub fn php_file_get_contents(filename: Value, use_include_path: Value, context: Value, offset: Value, length: Value, allocator: Allocator) !Value {
    _ = use_include_path;
    _ = context;
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;

    // ★批次二十六：php:// 流委托 fopen 同一承载路径（memory/temp/input/stdin/stdout 统一），
    //   读取经 stream_get_contents（offset 语义同：显式 ⇒ seek；length null ⇒ 至 EOF）。
    if (std.mem.startsWith(u8, fname, "php://")) {
        const h = try php_fopen(filename, Value.initString(PHPString.initStatic("r")), allocator);
        if (!h.isResource()) return Value.initBool(false);
        defer {
            var hv = h;
            hv.release(allocator);
        }
        // file_get_contents 的负 offset＝自尾部（SEEK_END）；stream_get_contents 的 offset 仅 SEEK_SET ⇒ 先自行 seek
        if (offset.isInt() and offset.asInt() < 0) {
            if (h.asResource().file_handle) |fh2| {
                _ = streamLseek(fh2, offset.asInt(), 2) catch return Value.initBool(false);
            }
            return php_stream_get_contents(h, length, Value.initMissing(), allocator);
        }
        return php_stream_get_contents(h, length, offset, allocator);
    }

    const content = std.Io.Dir.cwd().readFileAlloc(getIo(), fname, allocator, .limited(10 * 1024 * 1024)) catch |err| {
        warnOpenStream("file_get_contents", fname, err);
        return Value.initBool(false);
    };
    defer allocator.free(content); // ★原有代码未释放（PHPString.init 会拷贝）

    const off = offset.toInt();
    var start: usize = 0;
    if (off < 0) {
        const len_i: i64 = @intCast(content.len);
        if (len_i + off < 0) {
            var mbuf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&mbuf, "file_get_contents(): Failed to seek to position {d} in the stream", .{off}) catch return Value.initBool(false);
            emitWarning(msg);
            return Value.initBool(false);
        }
        start = @intCast(len_i + off);
    } else if (off > 0) {
        const off_u: u64 = @intCast(off);
        start = if (off_u >= content.len) content.len else @intCast(off_u);
    }

    var end: usize = content.len;
    if (!length.isNull()) {
        const len_arg = length.toInt();
        if (len_arg < 0) {
            return throwThrowable("ValueError", "file_get_contents(): Argument #5 ($length) must be greater than or equal to 0", runtime_allocator);
        }
        const len_u: u64 = @intCast(len_arg);
        const remain = content.len - start;
        end = if (len_u >= remain) content.len else start + @as(usize, @intCast(len_u));
    }

    const output = try PHPString.init(allocator, content[start..end]);
    return Value.initString(output);
}

/// ★批次二十九：meta 归一化 mode 构造（字母 + +? + b?；force_b 由 php:// 子协议决定）。
///   返回值归调用方（资源 uri/mode 字段生命周期与资源同）。
fn q4CanonMode(allocator: Allocator, letter: u8, plus: bool, binary: bool) ![]const u8 {
    var buf: [3]u8 = undefined;
    var n: usize = 1;
    buf[0] = letter;
    if (plus) {
        buf[n] = '+';
        n += 1;
    }
    if (binary) {
        buf[n] = 'b';
        n += 1;
    }
    return allocator.dupe(u8, buf[0..n]);
}

/// fopen - ★R-275：补齐 r+/w+/a+/x/x+/c/c+ 与 `b`/`t` 后缀；打开失败发 PHP 措辞 Warning。
///   语义要点（PHP 实测）：`a`/`a+` 每次写前定位末尾（读位置仍在 0）；`c` 不截断；`x` 排他创建。
///   ★批次二十九：mode 全量解析——字母必为 rwaxc（非法 ⇒ PHP 措辞 Warning+false）；
///   标志位 `+`/`b`/`t`/`e`/`n` 字母后任意序（e=CLOEXEC、n=非阻塞：AOT 无 exec 子进程语义，
///   受理不承载）；meta 的 mode 为归一化形「字母 + +? + b?」（memory/temp/input/output 恒带 b，
///   stdout/stderr/stdin/真实文件按实参）。
pub fn php_fopen(filename: Value, mode: Value, allocator: Allocator) !Value {
    if (!filename.isString() or !mode.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const raw_mode = mode.asString().data;
    var mode_letter: u8 = 0;
    var mode_plus = false;
    var mode_binary = false;
    var mode_ok = raw_mode.len > 0;
    if (mode_ok) {
        mode_letter = raw_mode[0];
        switch (mode_letter) {
            'r', 'w', 'a', 'x', 'c' => {},
            else => mode_ok = false,
        }
        for (raw_mode[1..]) |c| {
            switch (c) {
                '+' => mode_plus = true,
                'b', 't' => mode_binary = true,
                'e', 'n' => {}, // CLOEXEC / nonblock 标志：受理即剥离（AOT 无 exec；阻塞语义走流层）
                else => mode_ok = false,
            }
        }
    }
    if (!mode_ok) {
        var mbuf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "fopen({s}): Failed to open stream: `{s}' is not a valid mode for fopen", .{ fname, raw_mode }) catch return Value.initBool(false);
        emitWarning(msg);
        return Value.initBool(false);
    }
    // 归一化两字符形（"r"/"r+"/"w"…）供既有分派串比较复用
    var nbuf: [2]u8 = undefined;
    var nlen: usize = 1;
    nbuf[0] = mode_letter;
    if (mode_plus) {
        nbuf[1] = '+';
        nlen = 2;
    }
    const fmode = nbuf[0..nlen];

    // 特殊处理php://流
    if (std.mem.startsWith(u8, fname, "php://")) {
        const sub = fname[6..];
        // ★批次二十六：php://memory / php://temp（含 /maxmemory:NN 阈值形）⇒ 匿名临时文件承载
        //   （mkstemp + 立即 unlink）：真 fd ⇒ 全族流函数（fread/fwrite/fseek/ftell/fstat/
        //   ftruncate/fgets/fgetc/fscanf/stream_get_contents…）与真实文件**同一套分派**，
        //   不造内存流第二套语义。temp 阈值的「内存段」仅是介质选择（PHP 文档语义），
        //   对外读写/定位/fstat 行为与文件介质无差 ⇒ 恒走文件介质。
        if (std.mem.eql(u8, sub, "memory") or std.mem.eql(u8, sub, "temp") or std.mem.startsWith(u8, sub, "temp/")) {
            const tmp_dir: []const u8 = if (std.c.getenv("TMPDIR")) |td| std.mem.span(td) else "/tmp";
            const tmpl = std.fmt.allocPrintSentinel(allocator, "{s}/q4memXXXXXX", .{tmp_dir}, 0) catch return Value.initBool(false);
            defer allocator.free(tmpl);
            const fd = q4Mkstemp(tmpl.ptr);
            if (fd < 0) return Value.initBool(false);
            // ★批次二十六：'r'（无 +）⇒ O_RDONLY 降级重开（须在 unlink 前——路径尚在）——
            //   PHP 实测 'r' 开 memory 后 fwrite 静默 false（写拒绝由 access mode 承载，
            //   fwrite 的 std.c.write 自查命中 EBADF）。
            var opened = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
            if (std.mem.eql(u8, fmode, "r")) {
                const ro = std.Io.Dir.cwd().openFile(getIo(), tmpl, .{}) catch {
                    opened.close(getIo());
                    return Value.initBool(false);
                };
                opened.close(getIo());
                opened = ro;
            }
            // 立即 unlink ⇒ 对外不可见（语义等价内存流）；fd 保持可用
            std.Io.Dir.cwd().deleteFile(getIo(), tmpl) catch {};
            // 错误清理走 File.close（与 php_fclose 同路径；std.posix.close 在 0.17 已收）
            const handle = allocator.create(std.Io.File) catch {
                opened.close(getIo());
                return Value.initBool(false);
            };
            handle.* = opened;
            const res = allocator.create(Value.PHPResource) catch {
                var tmpf = handle.*;
                tmpf.close(getIo());
                allocator.destroy(handle);
                return Value.initBool(false);
            };
            res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .wait_mode = q4ClassifyFd(handle.handle) };
            // ★批次二十九：meta 承载（uri=原始入参全文；mode 强制带 b——PHP 实测 memory/temp 恒 "w+b" 形）
            res.uri = allocator.dupe(u8, fname) catch "";
            res.mode = q4CanonMode(allocator, mode_letter, mode_plus, true) catch "";
            return Value.initResource(res);
        }
        // ★批次二十六：php://stdout/stderr/stdin ⇒ dup 标准 fd（fclose 关 dup 副本，
        //   不动进程标准流——PHP 实测 fclose($stdout) 后 echo 照常）。
        const std_fd: ?std.posix.fd_t = if (std.mem.eql(u8, sub, "stdout"))
            1
        else if (std.mem.eql(u8, sub, "stderr"))
            2
        else if (std.mem.eql(u8, sub, "stdin"))
            0
        else
            null;
        if (std_fd) |sfd| {
            const fd = q4Dup(sfd) catch return Value.initBool(false);
            const handle = allocator.create(std.Io.File) catch {
                var tmpf = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
                tmpf.close(getIo());
                return Value.initBool(false);
            };
            handle.* = .{ .handle = fd, .flags = .{ .nonblocking = false } };
            const res = allocator.create(Value.PHPResource) catch {
                var tmpf = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
                tmpf.close(getIo());
                allocator.destroy(handle);
                return Value.initBool(false);
            };
            res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .wait_mode = q4ClassifyFd(handle.handle) };
            // ★批次二十九：stdio 族 mode 按实参（PHP 实测 'w' 不强制 b）
            res.uri = allocator.dupe(u8, fname) catch "";
            res.mode = q4CanonMode(allocator, mode_letter, mode_plus, mode_binary) catch "";
            return Value.initResource(res);
        }
        // ★批次二十九：php://output ⇒ dup(1)（PHP 实测等同 stdout 语义但 meta 归一化带 b、
        //   stream_type=Output；fwrite 真实落进程标准输出）。
        if (std.mem.eql(u8, sub, "output")) {
            const fd = q4Dup(1) catch return Value.initBool(false);
            const handle = allocator.create(std.Io.File) catch {
                var tmpf = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
                tmpf.close(getIo());
                return Value.initBool(false);
            };
            handle.* = .{ .handle = fd, .flags = .{ .nonblocking = false } };
            const res = allocator.create(Value.PHPResource) catch {
                var tmpf = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
                tmpf.close(getIo());
                allocator.destroy(handle);
                return Value.initBool(false);
            };
            res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .wait_mode = q4ClassifyFd(handle.handle) };
            res.uri = allocator.dupe(u8, fname) catch "";
            res.mode = q4CanonMode(allocator, mode_letter, mode_plus, true) catch "";
            return Value.initResource(res);
        }
        // ★批次二十六：php://input（CLI ⇒ 空**只读**请求体流；PHP 8.5.8 实测：
        //   file_get_contents ⇒ ""、fgets ⇒ false 且 feof 读后 true、fwrite ⇒ false 写拒绝）。
        //   承载：mkstemp 空文件 ⇒ O_RDONLY 重开（写拒绝由 access mode 承载）⇒ unlink。
        if (std.mem.eql(u8, sub, "input")) {
            const tmp_dir: []const u8 = if (std.c.getenv("TMPDIR")) |td| std.mem.span(td) else "/tmp";
            const tmpl = std.fmt.allocPrintSentinel(allocator, "{s}/q4memXXXXXX", .{tmp_dir}, 0) catch return Value.initBool(false);
            defer allocator.free(tmpl);
            const fd0 = q4Mkstemp(tmpl.ptr);
            if (fd0 < 0) return Value.initBool(false);
            var tmpf0 = std.Io.File{ .handle = fd0, .flags = .{ .nonblocking = false } };
            tmpf0.close(getIo());
            const ro_file = std.Io.Dir.cwd().openFile(getIo(), tmpl, .{}) catch return Value.initBool(false);
            std.Io.Dir.cwd().deleteFile(getIo(), tmpl) catch {};
            const handle = allocator.create(std.Io.File) catch {
                var tmpf = ro_file;
                tmpf.close(getIo());
                return Value.initBool(false);
            };
            handle.* = ro_file;
            const res = allocator.create(Value.PHPResource) catch {
                var tmpf2 = handle.*;
                tmpf2.close(getIo());
                allocator.destroy(handle);
                return Value.initBool(false);
            };
            res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .wait_mode = q4ClassifyFd(handle.handle) };
            // ★批次二十九：input 的 meta mode 强制带 b（PHP 实测 "rb"）
            res.uri = allocator.dupe(u8, fname) catch "";
            res.mode = q4CanonMode(allocator, mode_letter, mode_plus, true) catch "";
            return Value.initResource(res);
        }
        // ★批次二十九：未知 php:// 子协议（filter 等）⇒ 诚实失败（PHP 实测措辞）——
        //   旧空壳（file_handle=null 假资源）属「静默假成功」红线病，废止。
        {
            var mbuf: [1024]u8 = undefined;
            const msg = std.fmt.bufPrint(&mbuf, "fopen({s}): Failed to open stream: operation failed", .{fname}) catch return Value.initBool(false);
            emitWarning(msg);
            return Value.initBool(false);
        }
    }

    const io = getIo();
    const cwd = std.Io.Dir.cwd();
    var file: std.Io.File = undefined;
    var append = false;
    if (std.mem.eql(u8, fmode, "r")) {
        file = cwd.openFile(io, fname, .{}) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "r+")) {
        file = cwd.openFile(io, fname, .{ .mode = .read_write }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "w")) {
        file = cwd.createFile(io, fname, .{}) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "w+")) {
        file = cwd.createFile(io, fname, .{ .read = true }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "a")) {
        file = cwd.createFile(io, fname, .{ .truncate = false }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
        append = true;
    } else if (std.mem.eql(u8, fmode, "a+")) {
        file = cwd.createFile(io, fname, .{ .truncate = false, .read = true }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
        append = true;
    } else if (std.mem.eql(u8, fmode, "x")) {
        file = cwd.createFile(io, fname, .{ .exclusive = true }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "x+")) {
        file = cwd.createFile(io, fname, .{ .exclusive = true, .read = true }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "c")) {
        file = cwd.createFile(io, fname, .{ .truncate = false }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else if (std.mem.eql(u8, fmode, "c+")) {
        file = cwd.createFile(io, fname, .{ .truncate = false, .read = true }) catch |err| {
            warnPf("fopen", fname, err);
            return Value.initBool(false);
        };
    } else {
        return Value.initBool(false);
    }

    const handle = allocator.create(std.Io.File) catch return Value.initBool(false);
    handle.* = file;
    const res = allocator.create(Value.PHPResource) catch {
        allocator.destroy(handle);
        return Value.initBool(false);
    };
    res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .append = append, .wait_mode = q4ClassifyFd(handle.handle) };
    // ★批次二十九：真实文件的 meta 承载（uri=路径原文；mode=归一化形，b 按实参）
    res.uri = allocator.dupe(u8, fname) catch "";
    res.mode = q4CanonMode(allocator, mode_letter, mode_plus, mode_binary) catch "";
    return Value.initResource(res);
}

/// stream_socket_pair - PHP 契约：返回两枚互通流资源（[0]/[1]），fread/fwrite/fclose 与
///   普通流同一套分派。★M2-2：承载为 socketpair(2) + O_NONBLOCK（新建 fd，独占 open file
///   description，改标志不与任何既有描述符共享）⇒ 读写经 NetPoller 让出，是协程 echo 的
///   标准探针通道。meta 形状对齐 PHP 8.5.8：stream_type=generic_socket、mode=r+、seekable=false。
pub fn php_stream_socket_pair(domain: Value, sock_type: Value, protocol: Value, allocator: Allocator) !Value {
    const d: c_int = @intCast(domain.toInt());
    const t: c_int = @intCast(sock_type.toInt());
    const p: c_int = @intCast(protocol.toInt());
    var sv: [2]c_int = .{ -1, -1 };
    if (socketpair(d, t, p, &sv) != 0) return Value.initBool(false);
    q4SetNonblock(sv[0]);
    q4SetNonblock(sv[1]);
    const arr = try PHPArray.init(allocator);
    var i: usize = 0;
    while (i < 2) : (i += 1) {
        const v = q4WrapSocketStream(sv[i], allocator) orelse {
            // 未包装的 fd 直接关（已入列者随 arr.release 关闭）
            arr.release(allocator);
            var j: usize = i;
            while (j < 2) : (j += 1) _ = close(sv[j]);
            return Value.initBool(false);
        };
        arr.push(allocator, v) catch {
            var vv = v;
            vv.release(allocator); // 关当前 fd
            arr.release(allocator); // 关已入列 fd
            var j: usize = i + 1;
            while (j < 2) : (j += 1) _ = close(sv[j]);
            return Value.initBool(false);
        };
    }
    return Value.initArray(arr);
}

/// 置 O_NONBLOCK（F_GETFL|F_SETFL；保留既有标志位）。
fn q4SetNonblock(fd: std.posix.fd_t) void {
    const fl = std.c.fcntl(fd, std.c.F.GETFL);
    if (fl < 0) return;
    const OInt = @Int(.unsigned, @bitSizeOf(std.c.O));
    const nb: OInt = @bitCast(@as(std.c.O, .{ .NONBLOCK = true }));
    _ = std.c.fcntl(fd, std.c.F.SETFL, @as(c_int, @intCast(fl | @as(c_int, @intCast(nb)))));
}

/// socket fd ⇒ stream 资源（type_name=stream；wait_mode=nonblocking；sock=true）。
fn q4WrapSocketStream(fd: std.posix.fd_t, allocator: Allocator) ?Value {
    const handle = allocator.create(std.Io.File) catch return null;
    handle.* = .{ .handle = fd, .flags = .{ .nonblocking = true } };
    const res = allocator.create(Value.PHPResource) catch {
        handle.close(getIo());
        allocator.destroy(handle);
        return null;
    };
    res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .wait_mode = .nonblocking, .sock = true, .read_timeout_ms = 60_000 };
    res.uri = "";
    res.mode = allocator.dupe(u8, "r+") catch "";
    return Value.initResource(res);
}

/// ★R-275：文件系统失败文案（PHP 措辞的公共 reason 表）。
fn fsErrText(err: anyerror) []const u8 {
    return switch (err) {
        error.FileNotFound => "No such file or directory",
        error.PathAlreadyExists => "File exists",
        error.DirNotEmpty => "Directory not empty",
        error.AccessDenied => "Permission denied",
        error.NotDir => "Not a directory",
        error.IsDir => "Is a directory",
        else => @errorName(err),
    };
}

/// ★R-275：`fopen`/`copy` 共用 `{fn}({path}): Failed to open stream: {reason}`。
fn warnPf(func_name: []const u8, fname: []const u8, err: anyerror) void {
    var mbuf: [1024]u8 = undefined;
    const msg = std.fmt.bufPrint(&mbuf, "{s}({s}): Failed to open stream: {s}", .{ func_name, fname, fsErrText(err) }) catch return;
    emitWarning(msg);
}

pub fn php_fwrite(handle: Value, data: Value, allocator: Allocator) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initInt(0); // 虚拟句柄

    // ★R-275：a/a+ 的每次写都定位到末尾
    if (res.append) {
        _ = streamLseek(fh, 0, 2) catch return Value.initBool(false);
    }

    const content = if (data.isString()) data.asString().data else blk: {
        const temp = try data.toString(allocator);
        defer temp.release(allocator);
        break :blk temp.data;
    };

    // ★批次二十六：写结果自查（旧走 fileWriteAll 吞错误 ⇒ 只读 fd/满盘场景恒返全长）。
    //   PHP 口径：写失败 ⇒ false；部分写 ⇒ 实际字节数。
    // ★M2-2：经 NetPoller 让出（管道/socket 背压时让出调度器；普通文件直写不变）。
    const written = q4WriteFh(res, fh, content) catch return Value.initBool(false);
    return Value.initInt(@intCast(written));
}

pub fn php_fread(handle: Value, length: Value, allocator: Allocator) !Value {
    if (!handle.isResource() or !length.isInt()) return Value.initBool(false);
    const res = handle.asResource();
    if (res.file_handle == null) return Value.initString(try PHPString.init(allocator, "")); // 虚拟句柄

    // ★R-274：PHP 8 的 fread length 必须 > 0（0/-1 抛 ValueError）；到达 EOF 返回 ""（不是 false）
    const len = length.asInt();
    if (len <= 0) {
        return throwThrowable("ValueError", "fread(): Argument #2 ($length) must be greater than 0", runtime_allocator);
    }
    const fh = res.file_handle.?;
    const buffer = allocator.alloc(u8, @intCast(len)) catch return Value.initBool(false);
    defer allocator.free(buffer);
    // ★M2-2：经 NetPoller 让出（管道/终端/socket 对；普通文件恒就绪走原直读）
    // ★M2-2-h：缓冲优先（socket/管道上上次 fscanf/stream_get_line 回推的字节在此可见）
    const bytes_read = q4BufferedRead(res, fh, buffer) catch return Value.initBool(false);
    // ★M2-2-b：读超时 ⇒ false（PHP 实测；EOF 标志不置位）
    if (res.timed_out) return Value.initBool(false);
    // ★M2-2-c：非阻塞无数据 ⇒ ""（PHP 实测；不算 EOF）
    if (res.would_block) return Value.initString(try PHPString.init(allocator, ""));
    // ★M2-2：EOF 口径对齐 PHP——socket/管道只在 read=0 时置 EOF（短读＝当前可用数据读完，
    //   不意味流结束）；普通文件保持「短读即 EOF」（read(2) 对普通文件除 EOF 外不会短读）。
    if (bytes_read == 0 or (bytes_read < buffer.len and res.wait_mode == .always_ready)) res.eof = true;
    const output = try PHPString.init(allocator, buffer[0..bytes_read]);
    return Value.initString(output);
}

pub fn php_fclose(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    if (res.file_handle) |fh| {
        fh.close(getIo());
        // ★F-180：fclose 是该 File 结构的最后一站（置 null 后归零路径不会再 destroy 它）。
        //   旧写只 close 不 destroy ⇒ 每次 fopen+fclose 恒漏 8B+1alloc（40B 的 PHPResource
        //   由 F-180 的 Value.release 修复另行归零）。
        runtime_allocator.destroy(fh);
        res.file_handle = null;
    }
    // ★批次二十九：tmpfile() 口径——fclose 即删除（PHP 实测 after close exists=false）
    if (res.unlink_on_close and res.uri.len > 0) {
        std.Io.Dir.cwd().deleteFile(getIo(), res.uri) catch {};
        res.unlink_on_close = false;
    }
    res.closed = true;
    return Value.initBool(true);
}

/// fflush - AOT 写路径为 fd 直写（posix.write，无用户态缓冲）⇒ 恒成功语义。
///   PHP 8.5.8 实测：资源 ⇒ true。
pub fn php_fflush(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    return Value.initBool(!res.closed);
}

fn wrapBuiltin_fflush(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 1) return error.InvalidArgumentCount;
    return php_fflush(q3Deref(args[0]));
}

pub fn php_is_resource(val: Value) !Value {
    return Value.initBool(val.isResource());
}

/// fgets - PHP 契约：fgets($h, ?int $length = null)；EOF 返回 false，并置 feof。
///   `$length` 给定时最多读 `length - 1` 字节（PHP 实测：fgets($f,3) ⇒ 2 字节）。
pub fn php_fgets(handle: Value, length: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);

    var limit: usize = 4096;
    if (!length.isNull()) {
        const l = length.toInt();
        if (l <= 0) return Value.initBool(false);
        limit = @intCast(@min(l - 1, 4096));
    }

    var buf: [4096]u8 = undefined;
    var pos: usize = 0;

    while (pos < limit) {
        var b: u8 = undefined;
        // ★M2-2-h：缓冲取字节（底层按 8KB 块填充，syscall 摊薄）
        const got = q4BufferedByte(res, fh, runtime_allocator, &b) catch break;
        if (got == 0) {
            // ★M2-2-b：超时 ⇒ 返回已读部分（PHP 实测）；EOF 标志不置位
            // ★M2-2-c：非阻塞无数据 ⇒ 同样返回已读部分，不算 EOF
            if (res.timed_out or res.would_block) break;
            res.eof = true;
            break;
        }
        buf[pos] = b;
        pos += 1;
        if (b == '\n') break;
    }

    if (pos == 0) return Value.initBool(false);

    // 该字符串会进入 Value 生命周期，必须由 runtime 唯一所有者分配：
    // init 内部本就 `alloc+memcpy` 复制入参，直接传栈缓冲即可。
    // ★F-189（门 C328 a3）：旧写先 `dupe` 再传 init ⇒ dupe 的那份无人释放，
    //   每次 fgets 恒漏 1 alloc（1 字节串时即 +1B，读写周期 N=3000 实测 +2000/+2000）。
    const global_alloc = runtime_allocator;
    const output = try PHPString.init(global_alloc, buf[0..pos]);
    return Value.initString(output);
}

/// fgetc - 读 1 字节；EOF 返回 false 并置 feof。
pub fn php_fgetc(handle: Value, allocator: Allocator) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    var buf: [1]u8 = undefined;
    // ★M2-2-h：缓冲取字节（与 fgets 同一层，避免逐字节 syscall）
    const got = q4BufferedByte(res, fh, allocator, &buf[0]) catch return Value.initBool(false);
    if (got == 0) {
        if (!res.timed_out and !res.would_block) res.eof = true; // ★M2-2-b/c：超时/非阻塞无数据不算 EOF
        return Value.initBool(false);
    }
    return Value.initString(try PHPString.init(allocator, &buf));
}

/// feof - 仅当一次读尝试已触到 EOF 后为 true（PHP 实测：未读前恒 false）。
pub fn php_feof(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    return Value.initBool(res.closed or res.eof);
}

/// stream_get_contents - 从当前位读至 EOF（或 length 字节）。
/// PHP 8.5.8 实测口径：length null/<0 ⇒ 读至 EOF；0 ⇒ ""；offset **缺省 ⇒ 不 seek**、
///   显式（含 0）⇒ seek(offset) 再读（missing 哨兵区分缺省与显式 0）。
pub fn php_stream_get_contents(handle: Value, length: Value, offset: Value, allocator: Allocator) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    if (!offset.isMissing() and !offset.isNull()) {
        const off = offset.toInt();
        if (off >= 0) {
            _ = streamLseek(fh, off, 0) catch return Value.initBool(false); // SEEK_SET
            res.eof = false;
        }
    }
    var want: ?usize = null;
    if (length.isInt()) {
        const l = length.asInt();
        if (l == 0) return Value.initString(try PHPString.init(allocator, ""));
        if (l > 0) want = @intCast(l);
    }
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    defer buf.deinit(allocator);
    var chunk: [8192]u8 = undefined;
    while (true) {
        const room: usize = if (want) |w| @min(chunk.len, w -| buf.items.len) else chunk.len;
        if (room == 0) break;
        const n = q4BufferedRead(res, fh, chunk[0..room]) catch break;
        if (n == 0) {
            // ★M2-2-b/c：超时或非阻塞无数据 ⇒ 返回已收内容（PHP 实测 ""）；不算 EOF
            if (!res.timed_out and !res.would_block) res.eof = true;
            break;
        }
        try buf.appendSlice(allocator, chunk[0..n]);
    }
    return Value.initString(try PHPString.init(allocator, buf.items));
}

fn wrapBuiltin_stream_get_contents(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 1) return error.InvalidArgumentCount;
    const h = q3Deref(args[0]);
    const length = if (args.len >= 2) q3Deref(args[1]) else Value.initNull();
    const offset = if (args.len >= 3) q3Deref(args[2]) else Value.initMissing();
    return php_stream_get_contents(h, length, offset, allocator);
}

// ★批次二十九：流族收面 wrappers
fn wrapBuiltin_stream_get_meta_data(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 1) return error.InvalidArgumentCount;
    return php_stream_get_meta_data(q3Deref(args[0]), allocator);
}
fn wrapBuiltin_stream_set_blocking(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 2) return error.InvalidArgumentCount;
    return php_stream_set_blocking(q3Deref(args[0]), q3Deref(args[1]));
}
fn wrapBuiltin_stream_set_timeout(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 2) return error.InvalidArgumentCount;
    const usec = if (args.len >= 3) q3Deref(args[2]) else Value.initInt(0);
    return php_stream_set_timeout(q3Deref(args[0]), q3Deref(args[1]), usec);
}
fn wrapBuiltin_stream_get_line(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 2) return error.InvalidArgumentCount;
    const ending = if (args.len >= 3) q3Deref(args[2]) else Value.initString(try PHPString.init(allocator, ""));
    return php_stream_get_line(q3Deref(args[0]), q3Deref(args[1]), ending, allocator);
}
fn wrapBuiltin_tmpfile(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    _ = args;
    return php_tmpfile(allocator);
}
fn wrapBuiltin_stream_get_wrappers(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    _ = args;
    return php_stream_get_wrappers(allocator);
}
fn wrapBuiltin_stream_context_create(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    const options = if (args.len >= 1) q3Deref(args[0]) else Value.initNull();
    return php_stream_context_create(options, allocator);
}
fn wrapBuiltin_stream_context_set_option(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 2) return error.InvalidArgumentCount;
    const a3 = if (args.len >= 3) q3Deref(args[2]) else Value.initNull();
    const a4 = if (args.len >= 4) q3Deref(args[3]) else Value.initNull();
    return php_stream_context_set_option(q3Deref(args[0]), q3Deref(args[1]), a3, a4, allocator);
}
fn wrapBuiltin_stream_context_get_options(ctx: Value, args: []const Value, allocator: Allocator) !Value {
    _ = ctx;
    if (args.len < 1) return error.InvalidArgumentCount;
    return php_stream_context_get_options(q3Deref(args[0]), allocator);
}

/// lseek 封装（Zig 0.16 的 Io.File 无 seek 方法；经 libc lseek 走 fd）。
fn streamLseek(fh: *std.Io.File, offset: i64, whence: c_int) !u64 {
    const r = std.c.lseek(fh.handle, @intCast(offset), whence);
    if (r < 0) return error.SeekFailed;
    return @intCast(r);
}

/// ftell - 返回当前读写位置（SEEK_CUR 查询，不改位置）。
pub fn php_ftell(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    // ★M2-2：socket 对流不可 seek，但 PHP 8.5.8 实测 ftell 返 0（流层位置恒 0）且不发警告。
    if (res.sock) return Value.initInt(0);
    const pos = streamLseek(fh, 0, 1) catch return Value.initBool(false);
    return Value.initInt(@intCast(pos));
}

/// fseek - PHP 契约：fseek($h, $offset, $whence = SEEK_SET) ⇒ 成功 0 / 失败 -1；成功后清除 EOF 标志。
pub fn php_fseek(handle: Value, offset: Value, whence: Value) !Value {
    if (!handle.isResource() or !offset.isInt()) return Value.initInt(-1);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initInt(-1);
    // ★M2-2：socket 对流不可 seek（PHP 8.5.8 实测：Warning「Stream does not support seeking」+ -1）
    if (res.sock) {
        emitWarning("fseek(): Stream does not support seeking");
        return Value.initInt(-1);
    }

    const off = offset.asInt();
    const w = if (whence.isInt()) whence.asInt() else 0;
    const whence_c: c_int = switch (w) {
        0 => 0, // SEEK_SET
        1 => 1, // SEEK_CUR
        2 => 2, // SEEK_END
        else => return Value.initInt(-1),
    };
    _ = streamLseek(fh, off, whence_c) catch return Value.initInt(-1);
    res.eof = false;
    return Value.initInt(0);
}

/// scandir - ★R-275（F-176）：返回 `["." , "..", …siblings]` 且按**字节序升序**（PHP 默认 SCANDIR_SORT_ASCENDING）；
///   打开失败按 PHP 打**两条**警告（`scandir(<path>): Failed to open directory: …` 与 `scandir(): (errno N): …`）。
pub fn php_scandir(dir: Value, allocator: Allocator) !Value {
    if (!dir.isString()) return Value.initBool(false);
    const dirname = dir.asString().data;

    var dir_handle = std.Io.Dir.cwd().openDir(getIo(), dirname, .{ .iterate = true }) catch |err| {
        const text = fsErrText(err);
        var b1: [1024]u8 = undefined;
        const m1 = std.fmt.bufPrint(&b1, "scandir({s}): Failed to open directory: {s}", .{ dirname, text }) catch "";
        emitWarning(m1);
        const errno: u32 = switch (err) {
            error.FileNotFound => 2,
            error.AccessDenied => 13,
            error.NotDir => 20,
            else => 0,
        };
        var b2: [512]u8 = undefined;
        const m2 = std.fmt.bufPrint(&b2, "scandir(): (errno {d}): {s}", .{ errno, text }) catch "";
        emitWarning(m2);
        return Value.initBool(false);
    };
    defer dir_handle.close(getIo());

    var names = std.ArrayList([]const u8).empty;
    defer {
        for (names.items) |n| allocator.free(n);
        names.deinit(allocator);
    }
    try names.append(allocator, try allocator.dupe(u8, "."));
    try names.append(allocator, try allocator.dupe(u8, ".."));

    var iter = dir_handle.iterate();
    while (iter.next(getIo()) catch null) |entry| {
        try names.append(allocator, try allocator.dupe(u8, entry.name));
    }
    std.mem.sort([]const u8, names.items, {}, struct {
        fn lt(_: void, a: []const u8, b: []const u8) bool {
            return std.mem.order(u8, a, b) == .lt;
        }
    }.lt);

    var arr = try PHPArray.init(allocator);
    for (names.items) |name| {
        const str = try PHPString.init(allocator, name);
        try arr.push(allocator, Value.initString(str));
    }
    return Value.initArray(arr);
}

// ============================================================================
// ★F-177（R-276）：stat 族与剩余文件系统 API（普查 C321 揭示 17 枚缺失）
// ============================================================================

/// stat/lstat 原始结构（失败返回 null，由调用方决定告警文案）。
fn fsStatRaw(allocator: Allocator, path: []const u8, nofollow: bool) ?std.c.Stat {
    const z = allocator.dupeSentinel(u8, path, 0) catch return null;
    defer allocator.free(z);
    var st: std.c.Stat = undefined;
    const flags: u32 = if (nofollow) @intCast(std.c.AT.SYMLINK_NOFOLLOW) else 0;
    if (std.c.fstatat(std.c.AT.FDCWD, z, &st, flags) != 0) return null;
    return st;
}

/// PHP `stat()` 的 26 键结构：0..12 与同名串键（dev/ino/mode/nlink/uid/gid/rdev/size/atime/mtime/ctime/blksize/blocks）。
fn phpStatValue(st: std.c.Stat, allocator: Allocator) !Value {
    const names = [13][]const u8{ "dev", "ino", "mode", "nlink", "uid", "gid", "rdev", "size", "atime", "mtime", "ctime", "blksize", "blocks" };
    const vals = [13]i64{
        @intCast(st.dev),     @intCast(st.ino),      @intCast(st.mode),
        @intCast(st.nlink),   @intCast(st.uid),      @intCast(st.gid),
        @intCast(st.rdev),    @intCast(st.size),     @intCast(st.atime().sec),
        @intCast(st.mtime().sec), @intCast(st.ctime().sec), @intCast(st.blksize),
        @intCast(st.blocks),
    };
    const arr = try PHPArray.init(allocator);
    for (0..13) |i| {
        try arr.set(allocator, ArrayKey{ .integer = @intCast(i) }, Value.initInt(vals[i]));
        try arr.set(allocator, ArrayKey{ .string = try PHPString.init(allocator, names[i]) }, Value.initInt(vals[i]));
    }
    return Value.initArray(arr);
}

pub fn php_stat(filename: Value, allocator: Allocator) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const path = filename.asString().data;
    const st = fsStatRaw(allocator, path, false) orelse {
        var b: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "stat(): stat failed for {s}", .{path}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };
    return phpStatValue(st, allocator);
}

pub fn php_lstat(filename: Value, allocator: Allocator) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const path = filename.asString().data;
    const st = fsStatRaw(allocator, path, true) orelse {
        var b: [1024]u8 = undefined;
        // ★PHP 实测：这里是大写 L（`lstat(): Lstat failed for …`）
        const msg = std.fmt.bufPrint(&b, "lstat(): Lstat failed for {s}", .{path}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };
    return phpStatValue(st, allocator);
}

pub fn php_filetype(filename: Value, allocator: Allocator) !Value {
    if (!filename.isString()) return Value.initBool(false);
    // PHP 的 filetype 走 lstat 语义（符号链接 ⇒ "link"）
    const st = fsStatRaw(allocator, filename.asString().data, true) orelse return Value.initBool(false);
    const fmt: u32 = @as(u32, @intCast(st.mode)) & std.c.S.IFMT;
    const name: []const u8 = if (fmt == std.c.S.IFREG)
        "file"
    else if (fmt == std.c.S.IFDIR)
        "dir"
    else if (fmt == std.c.S.IFLNK)
        "link"
    else if (fmt == std.c.S.IFIFO)
        "fifo"
    else if (fmt == std.c.S.IFCHR)
        "char"
    else if (fmt == std.c.S.IFBLK)
        "block"
    else if (fmt == std.c.S.IFSOCK)
        "socket"
    else
        "unknown";
    return Value.initString(try PHPString.init(allocator, name));
}

pub fn php_fileperms(filename: Value, allocator: Allocator) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const st = fsStatRaw(allocator, filename.asString().data, false) orelse return Value.initBool(false);
    return Value.initInt(@intCast(st.mode));
}

pub fn php_is_link(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const st = fsStatRaw(runtime_allocator, filename.asString().data, true) orelse return Value.initBool(false);
    const fmt: u32 = @as(u32, @intCast(st.mode)) & std.c.S.IFMT;
    return Value.initBool(fmt == std.c.S.IFLNK);
}

pub fn php_chmod(filename: Value, permissions: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const path = filename.asString().data;
    const mode: std.c.mode_t = if (permissions.isInt()) @intCast(permissions.asInt() & 0o7777) else 0o666;
    const z = runtime_allocator.dupeSentinel(u8, path, 0) catch return Value.initBool(false);
    defer runtime_allocator.free(z);
    if (std.c.chmod(z, mode) != 0) {
        var b: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "chmod(): {s}", .{"Operation not permitted"}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    }
    return Value.initBool(true);
}

pub fn php_readfile(filename: Value, allocator: Allocator) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const path = filename.asString().data;
    const content = std.Io.Dir.cwd().readFileAlloc(getIo(), path, allocator, .limited(64 * 1024 * 1024)) catch |err| {
        warnPf("readfile", path, err);
        return Value.initBool(false);
    };
    defer allocator.free(content);
    fileWriteAll(1, content);
    return Value.initInt(@intCast(content.len));
}

pub fn php_fpassthru(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initInt(0);
    var buf: [8192]u8 = undefined;
    var total: usize = 0;
    while (true) {
        const n = q4BufferedRead(res, fh, &buf) catch return Value.initBool(false);
        if (n == 0) {
            // ★M2-2-b：读超时 ⇒ -1（PHP 8.5.8 实测：copy_to_stream 失败返回 -1）
            if (res.timed_out) return Value.initInt(-1);
            // ★M2-2-c：非阻塞无数据 ⇒ 返回已转发字节数（PHP 实测 0）；不算 EOF
            if (res.would_block) break;
            res.eof = true;
            break;
        }
        fileWriteAll(1, buf[0..n]);
        total += n;
    }
    return Value.initInt(@intCast(total));
}

pub fn php_fstat(handle: Value, allocator: Allocator) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    var st: std.c.Stat = undefined;
    if (std.c.fstat(fh.handle, &st) != 0) return Value.initBool(false);
    return phpStatValue(st, allocator);
}

pub fn php_ftruncate(handle: Value, size: Value) !Value {
    if (!handle.isResource() or !size.isInt()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    return Value.initBool(std.c.ftruncate(fh.handle, @intCast(size.asInt())) == 0);
}

pub fn php_fsync(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    return Value.initBool(std.c.fsync(fh.handle) == 0);
}

// ============================================================================
// ★批次二十九：流族收面（stream_get_meta_data / set_blocking / set_timeout /
//   get_line / tmpfile / get_wrappers / context 族 / flock 修正 / wrapper 诚实失败）
// ============================================================================

/// 流资源的 wrapper_type/stream_type 推导（uri 方案为单一事实源，禁第二份判定）。
fn q4StreamKinds(uri: []const u8) struct { wrapper: []const u8, stype: []const u8 } {
    if (std.mem.startsWith(u8, uri, "php://")) {
        const sub = uri[6..];
        if (std.mem.eql(u8, sub, "memory")) return .{ .wrapper = "PHP", .stype = "MEMORY" };
        if (std.mem.startsWith(u8, sub, "temp")) return .{ .wrapper = "PHP", .stype = "TEMP" };
        if (std.mem.eql(u8, sub, "input")) return .{ .wrapper = "PHP", .stype = "Input" };
        if (std.mem.eql(u8, sub, "output")) return .{ .wrapper = "PHP", .stype = "Output" };
        return .{ .wrapper = "PHP", .stype = "STDIO" }; // stdin/stdout/stderr
    }
    return .{ .wrapper = "plainfile", .stype = "STDIO" };
}

/// 流形参 ZPP/函数体双口径（PHP 8.5.8 实测）：非 resource ⇒ 「must be of type resource, X given」；
/// 已关闭/空壳 resource ⇒ 「must be an open stream resource」（fgetcsv 同款双口径）。
/// 返回联合：ok=资源指针；thrown=异常值（与 `return throwThrowable(...)` 同语义——
///   异常已 setException 挂旗，调用方原样 return 即可，**禁止**当 Zig error 传播）。
const Q4StreamArg = union(enum) { ok: *Value.PHPResource, thrown: Value };

fn q4StreamArgCheck(fn_name: []const u8, handle: Value) !Q4StreamArg {
    if (!handle.isResource()) {
        if (handle.hasResourceType()) {
            return .{ .thrown = try throwThrowable("TypeError", std.fmt.bufPrint(&q4_te_buf, "{s}(): Argument #1 ($stream) must be an open stream resource", .{fn_name}) catch "", runtime_allocator) };
        }
        const tname = if (Value_isObject(handle)) Value_asObject(handle).class_name else valueTypeName(handle);
        return .{ .thrown = try throwThrowable("TypeError", std.fmt.bufPrint(&q4_te_buf, "{s}(): Argument #1 ($stream) must be of type resource, {s} given", .{ fn_name, tname }) catch "", runtime_allocator) };
    }
    const res = handle.asResource();
    if (res.closed or res.file_handle == null) {
        return .{ .thrown = try throwThrowable("TypeError", std.fmt.bufPrint(&q4_te_buf, "{s}(): Argument #1 ($stream) must be an open stream resource", .{fn_name}) catch "", runtime_allocator) };
    }
    return .{ .ok = res };
}
var q4_te_buf: [256]u8 = undefined;
// （编译产物单线程运行；若未来启用协程再改 threadlocal——当前无并发写者）

/// stream_get_meta_data - PHP 8.5.8 实测键序：timed_out, blocked, eof, wrapper_type,
///   stream_type, mode, unread_bytes, seekable, uri。全键恒在（无 crypto/wrapper_data——
///   二者仅 SSL/http 包装器存在，AOT 不支持该两族 ⇒ 不出键即诚实）。
pub fn php_stream_get_meta_data(handle: Value, allocator: Allocator) !Value {
    const res = switch (try q4StreamArgCheck("stream_get_meta_data", handle)) {
        .ok => |r| r,
        .thrown => |v| return v,
    };
    const kinds = q4StreamKinds(res.uri);
    const arr = try PHPArray.init(allocator);
    const Put = struct {
        fn str(a: *PHPArray, al: Allocator, k: []const u8, v: []const u8) !void {
            try a.set(al, ArrayKey{ .string = try PHPString.init(al, k) }, Value.initString(try PHPString.init(al, v)));
        }
        fn b(a: *PHPArray, al: Allocator, k: []const u8, v: bool) !void {
            try a.set(al, ArrayKey{ .string = try PHPString.init(al, k) }, Value.initBool(v));
        }
        fn i(a: *PHPArray, al: Allocator, k: []const u8, v: i64) !void {
            try a.set(al, ArrayKey{ .string = try PHPString.init(al, k) }, Value.initInt(v));
        }
    };
    try Put.b(arr, allocator, "timed_out", res.timed_out);
    try Put.b(arr, allocator, "blocked", res.blocked);
    try Put.b(arr, allocator, "eof", res.eof);
    // ★M2-2：socket 对流（stream_socket_pair）的 meta 形状对齐 PHP 8.5.8——
    //   仅 7 键（无 wrapper_type/uri），stream_type=generic_socket、seekable=false。
    if (res.sock) {
        try Put.str(arr, allocator, "stream_type", "generic_socket");
        try Put.str(arr, allocator, "mode", res.mode);
        try Put.i(arr, allocator, "unread_bytes", @intCast(q4BufAvail(res))); // ★M2-2-h：用户态缓冲未读量（PHP 同口径）
        try Put.b(arr, allocator, "seekable", false);
        return Value.initArray(arr);
    }
    try Put.str(arr, allocator, "wrapper_type", kinds.wrapper);
    try Put.str(arr, allocator, "stream_type", kinds.stype);
    try Put.str(arr, allocator, "mode", res.mode);
    try Put.i(arr, allocator, "unread_bytes", @intCast(q4BufAvail(res))); // ★M2-2-h：用户态缓冲未读量（普通文件恒 0）
    try Put.b(arr, allocator, "seekable", true); // AOT 全部流种均为 STDIO 语义承载（PHP 同报 true）
    try Put.str(arr, allocator, "uri", res.uri);
    return Value.initArray(arr);
}

/// stream_set_blocking - PHP 8.5.8 实测分族：真实文件/stdout/stderr/output/socket 受理并记账
///   （meta blocked 随置位）；php://memory/temp/input **忽略非阻塞标志**（blocked 恒 true——
///   内存族与只读请求体无非阻塞语义）。返回值全族恒 true。
/// ★M2-2-c：socket 流（O_NONBLOCK 承载，供 NetPoller）不改 fd 标志，由 res.blocked 逻辑分流——
///   false ⇒ 读侧 poll(0) 快检/试读、无数据置 would_block；写侧单次试写（EAGAIN ⇒ 0）。
pub fn php_stream_set_blocking(handle: Value, enabled: Value) !Value {
    const res = switch (try q4StreamArgCheck("stream_set_blocking", handle)) {
        .ok => |r| r,
        .thrown => |v| return v,
    };
    const st = q4StreamKinds(res.uri).stype;
    const ignorable = !res.sock and (std.mem.eql(u8, st, "MEMORY") or std.mem.eql(u8, st, "TEMP") or std.mem.eql(u8, st, "Input"));
    if (!ignorable) {
        res.blocked = enabled.toBool();
    }
    return Value.initBool(true);
}

/// stream_set_timeout - ★M2-2-b：socket 流受理并建模读超时（秒+微秒；0,0 ⇒ 非阻塞读；
///   负值 ⇒ 无限等）；普通文件流 / php://memory / php://input 仍恒 false（PHP 实测口径）。
///   超时效果：fread/fscanf/fgetcsv/stream_get_line ⇒ false；fgets ⇒ 已读部分；
///   stream_get_contents ⇒ 已收内容；fpassthru ⇒ -1；meta timed_out 置位（成功读后复位）。
pub fn php_stream_set_timeout(handle: Value, seconds: Value, microseconds: Value) !Value {
    const res = switch (try q4StreamArgCheck("stream_set_timeout", handle)) {
        .ok => |r| r,
        .thrown => |v| return v,
    };
    if (!res.sock) return Value.initBool(false);
    const sec = seconds.toInt();
    const usec = microseconds.toInt();
    if (sec < 0 or usec < 0) {
        // 负值 ⇒ 无限等（PHP 实测：负超时等同未设置）
        res.read_timeout_ms = null;
        return Value.initBool(true);
    }
    const sec_ms = std.math.mul(u64, @as(u64, @intCast(sec)), 1000) catch std.math.maxInt(u64);
    const usec_u: u64 = @intCast(usec);
    const usec_ms: u64 = usec_u / 1000 + @intFromBool(usec_u % 1000 != 0); // 微秒向上取整到毫秒
    res.read_timeout_ms = std.math.add(u64, sec_ms, usec_ms) catch std.math.maxInt(u64);
    return Value.initBool(true);
}

/// stream_get_line - PHP 8.5.8 实测口径：length 0 ⇒ 不限（读至 EOF/分隔符）；
///   length <0 ⇒ ValueError；命中分隔符 ⇒ 返回其前内容（分隔符消耗不返回）；
///   无分隔符 ⇒ 至多 length 字节；EOF 且未读到任何字节 ⇒ false。
pub fn php_stream_get_line(handle: Value, length: Value, ending: Value, allocator: Allocator) !Value {
    const res = switch (try q4StreamArgCheck("stream_get_line", handle)) {
        .ok => |r| r,
        .thrown => |v| return v,
    };
    const fh = res.file_handle.?; // q4StreamArgCheck 已保证非空
    res.would_block = false; // 本函数末尾据「本次是否非阻塞无数据」判 false
    var limit: usize = 0; // 0 = 不限
    if (length.isInt()) {
        const l = length.asInt();
        if (l < 0) {
            return throwThrowable("ValueError", "stream_get_line(): Argument #2 ($length) must be greater than or equal to 0", runtime_allocator);
        }
        limit = @intCast(l);
    }
    const delim: []const u8 = if (ending.isString()) ending.asString().data else "";
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    defer buf.deinit(allocator);
    // 分隔符路径逐字节读（命中即停、不回读）；无分隔符路径分块读（无超读，无需回 seek）
    if (delim.len > 0) {
        var byte: [1]u8 = undefined;
        var matched: usize = 0;
        while (limit == 0 or buf.items.len < limit) {
            const got = q4BufferedByte(res, fh, allocator, &byte[0]) catch break;
            if (got == 0) {
                // ★M2-2-b/c：超时/非阻塞无数据不算 EOF
                if (!res.timed_out and !res.would_block) res.eof = true;
                break;
            }
            if (byte[0] == delim[matched]) {
                matched += 1;
                if (matched == delim.len) break; // 命中：分隔符消耗不返回
            } else {
                // 失配：已积累的前缀字节与当前字节全部归入结果
                if (matched > 0) {
                    try buf.appendSlice(allocator, delim[0..matched]);
                    matched = 0;
                    // 当前字节可能重新开始一轮匹配
                    if (byte[0] == delim[0]) {
                        matched = 1;
                        if (matched == delim.len) break;
                        continue;
                    }
                }
                try buf.append(allocator, byte[0]);
            }
        }
        // ★M2-2-h：非阻塞且未命中分隔符 ⇒ 已读字节全部放回缓冲、返回 false（PHP 实测口径：
        //   下次调用续读并拼接）。插入语义是「插到未消费区头部」，故先插前缀、后插正文
        //   ⇒ 最终顺序 [正文][部分匹配前缀]（读入顺序）。
        if (res.would_block) {
            if (matched > 0) q4BufUnread(res, allocator, delim[0..matched]);
            q4BufUnread(res, allocator, buf.items);
            return Value.initBool(false);
        }
    } else {
        var chunk: [8192]u8 = undefined;
        while (limit == 0 or buf.items.len < limit) {
            const room = if (limit == 0) chunk.len else @min(chunk.len, limit - buf.items.len);
            const n = q4BufferedRead(res, fh, chunk[0..room]) catch break;
            if (n == 0) {
                // ★M2-2-b/c：超时/非阻塞无数据不算 EOF
                if (!res.timed_out and !res.would_block) res.eof = true;
                break;
            }
            try buf.appendSlice(allocator, chunk[0..n]);
        }
        // ★M2-2-h：非阻塞且无内容 ⇒ 放回已读字节、返回 false（PHP 实测口径）
        if (res.would_block) {
            q4BufUnread(res, allocator, buf.items);
            return Value.initBool(false);
        }
    }
    // ★M2-2-b/c：超时/非阻塞无数据且无任何内容 ⇒ false（PHP 实测）
    if (buf.items.len == 0 and (res.eof or res.timed_out or res.would_block)) return Value.initBool(false);
    return Value.initString(try PHPString.init(allocator, buf.items));
}

/// tmpfile - PHP 实测：真实临时文件（存在至 fclose）、mode=r+b、meta wrapper=plainfile、
///   get_resource_type=stream。承载：mkstemp 保留路径（不即时 unlink），fclose/归零时删除。
pub fn php_tmpfile(allocator: Allocator) !Value {
    // ★批次二十九：uri 按 PHP 实测取 realpath（macOS 的 TMPDIR 是 /var/… 软链 ⇒ /private/var/…），
    //   且裁掉尾斜杠（TMPDIR 自带尾 "/"，拼路径不再叠 "//"）。
    var tmp_dir: []const u8 = if (std.c.getenv("TMPDIR")) |td| std.mem.span(td) else "/tmp";
    var rp_buf: [std.posix.PATH_MAX]u8 = undefined;
    const tmp_dir_z = try allocator.dupeSentinel(u8, tmp_dir, 0);
    defer allocator.free(tmp_dir_z);
    if (std.c.realpath(tmp_dir_z.ptr, &rp_buf)) |rp| {
        tmp_dir = std.mem.span(rp);
    }
    if (tmp_dir.len > 1 and tmp_dir[tmp_dir.len - 1] == '/') tmp_dir = tmp_dir[0 .. tmp_dir.len - 1];
    const tmpl = std.fmt.allocPrintSentinel(allocator, "{s}/q4tmpXXXXXX", .{tmp_dir}, 0) catch return Value.initBool(false);
    defer allocator.free(tmpl);
    const fd = q4Mkstemp(tmpl.ptr);
    if (fd < 0) return Value.initBool(false);
    const handle = allocator.create(std.Io.File) catch {
        var tmpf = std.Io.File{ .handle = fd, .flags = .{ .nonblocking = false } };
        tmpf.close(getIo());
        std.Io.Dir.cwd().deleteFile(getIo(), tmpl) catch {};
        return Value.initBool(false);
    };
    handle.* = .{ .handle = fd, .flags = .{ .nonblocking = false } };
    const res = allocator.create(Value.PHPResource) catch {
        var tmpf = handle.*;
        tmpf.close(getIo());
        allocator.destroy(handle);
        std.Io.Dir.cwd().deleteFile(getIo(), tmpl) catch {};
        return Value.initBool(false);
    };
    res.* = .{ .ref_count = 1, .file_handle = handle, .type_name = "stream", .unlink_on_close = true, .wait_mode = q4ClassifyFd(handle.handle) };
    res.uri = allocator.dupe(u8, tmpl) catch "";
    res.mode = allocator.dupe(u8, "r+b") catch "";
    return Value.initResource(res);
}

/// stream_get_wrappers - 诚实能力表：AOT 实际支持的包装器（file/php）。谎报全量即红线病。
pub fn php_stream_get_wrappers(allocator: Allocator) !Value {
    const arr = try PHPArray.init(allocator);
    try arr.set(allocator, ArrayKey{ .integer = 0 }, Value.initString(try PHPString.init(allocator, "php")));
    try arr.set(allocator, ArrayKey{ .integer = 1 }, Value.initString(try PHPString.init(allocator, "file")));
    return Value.initArray(arr);
}

/// stream_context_create - 选项表资源（type_name="stream-context"）。
///   PHP 8.5.8：create() ⇒ 空表；create(array) ⇒ 预填。
pub fn php_stream_context_create(options: Value, allocator: Allocator) !Value {
    const res = try allocator.create(Value.PHPResource);
    res.* = .{ .ref_count = 1, .file_handle = null, .type_name = "stream-context" };
    const opts = try PHPArray.init(allocator);
    res.context_options = opts;
    if (options.isArray()) {
        // 值语义复制（set 内 retain + 共享数组 COW 浅拷贝，与 PHP 值语义一致）
        const src = options.asArray();
        var it = src.elements.iterator();
        while (it.next()) |entry| {
            try opts.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        }
    }
    return Value.initResource(res);
}

/// stream_context_set_option - PHP 8.5.8 实测双形：
///   (ctx, array) 两参形 ⇒ **Deprecated**「Calling stream_context_set_option() with
///   2 arguments is deprecated, use stream_context_set_options() instead」（PHP 原文）+ 合并嵌套表 true；
///   (ctx, wrapper, option, value) 四参形 ⇒ 静默受理 true（不告警）。
pub fn php_stream_context_set_option(ctx_val: Value, a2: Value, a3: Value, a4: Value, allocator: Allocator) !Value {
    if (!ctx_val.isResource()) return Value.initBool(false);
    const res = ctx_val.asResource();
    const opts = res.context_options orelse return Value.initBool(false);
    if (a2.isArray()) {
        // ★两参数组形（PHP 8.5 已 Deprecated，原文措辞复刻）
        emitDeprecated("Calling stream_context_set_option() with 2 arguments is deprecated, use stream_context_set_options() instead");
        var it = a2.asArray().elements.iterator();
        while (it.next()) |entry| {
            // 同名 wrapper 且新旧值皆为表 ⇒ 合并进旧表（PHP set_options 语义）
            if (entry.value_ptr.*.isArray()) {
                if (opts.get(entry.key_ptr.*)) |old| {
                    if (old.isArray()) {
                        var sub_it = entry.value_ptr.*.asArray().elements.iterator();
                        while (sub_it.next()) |se| {
                            try old.asArray().set(allocator, se.key_ptr.*, se.value_ptr.*);
                        }
                        continue;
                    }
                }
            }
            try opts.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        }
        return Value.initBool(true);
    }
    // 四参形（不告警）
    if (!a2.isString() or !a3.isString()) return Value.initBool(false);
    const wrapper_key = ArrayKey{ .string = try PHPString.init(allocator, a2.asString().data) };
    var sub_arr: *PHPArray = undefined;
    if (opts.get(wrapper_key)) |old| {
        if (old.isArray()) {
            sub_arr = old.asArray();
        } else {
            sub_arr = try PHPArray.init(allocator);
            try opts.set(allocator, wrapper_key, Value.initArray(sub_arr));
        }
    } else {
        sub_arr = try PHPArray.init(allocator);
        try opts.set(allocator, wrapper_key, Value.initArray(sub_arr));
    }
    try sub_arr.set(allocator, ArrayKey{ .string = try PHPString.init(allocator, a3.asString().data) }, a4);
    return Value.initBool(true);
}

/// stream_context_get_options - 返回上下文选项表（PHP 实测：空上下文 ⇒ array(0)）。
pub fn php_stream_context_get_options(ctx_val: Value, allocator: Allocator) !Value {
    if (!ctx_val.isResource()) return Value.initBool(false);
    const res = ctx_val.asResource();
    const opts = res.context_options orelse return Value.initBool(false);
    _ = allocator;
    return Value.initArray(opts);
}

/// flock - ★批次二十九修正：PHP 常量到 POSIX flock(2) 的真实映射
///   （PHP LOCK_UN=3 ⇒ POSIX LOCK_UN=8；低两位 0/1/2 直通；LOCK_NB=4 同值）；
///   PHP 实测 op=99 ⇒ 掩 &7 ⇒ UN ⇒ true。关流/非资源 ⇒ TypeError 双口径。
pub fn php_flock(handle: Value, operation: Value) !Value {
    const res = switch (try q4StreamArgCheck("flock", handle)) {
        .ok => |r| r,
        .thrown => |v| return v,
    };
    if (!operation.isInt()) {
        const tname = if (Value_isObject(operation)) Value_asObject(operation).class_name else valueTypeName(operation);
        return throwThrowable("TypeError", std.fmt.bufPrint(&q4_te_buf, "flock(): Argument #2 ($operation) must be of type int, {s} given", .{tname}) catch "", runtime_allocator);
    }
    const fh = res.file_handle.?;
    const op = operation.asInt();
    const low2: i64 = op & 3;
    const base: c_int = if (low2 == 3) 8 else @intCast(low2); // PHP LOCK_UN=3 ⇒ POSIX LOCK_UN=8
    const nb: c_int = @intCast(op & 4); // LOCK_NB 同值
    return Value.initBool(std.c.flock(fh.handle, base | nb) == 0);
}

pub fn php_umask(mode: Value) !Value {
    if (mode.isNull()) {
        // 查询：先置 0 取旧值，再恢复（无全局状态破坏）
        const old = std.c.umask(0);
        _ = std.c.umask(old);
        return Value.initInt(@intCast(old));
    }
    const m: std.c.mode_t = if (mode.isInt()) @intCast(mode.asInt() & 0o777) else 0;
    const old = std.c.umask(m);
    return Value.initInt(@intCast(old));
}

pub fn php_symlink(target: Value, linkpath: Value) !Value {
    if (!target.isString() or !linkpath.isString()) return Value.initBool(false);
    const zt = runtime_allocator.dupeSentinel(u8, target.asString().data, 0) catch return Value.initBool(false);
    defer runtime_allocator.free(zt);
    const zl = runtime_allocator.dupeSentinel(u8, linkpath.asString().data, 0) catch return Value.initBool(false);
    defer runtime_allocator.free(zl);
    if (std.c.symlink(zt, zl) != 0) {
        var b: [1024]u8 = undefined;
        // 以「目标已存在」区分 EEXIST（避免依赖 errno API 的平台差异）
        const reason = if (fsStatRaw(runtime_allocator, linkpath.asString().data, true) != null) "File exists" else "Operation not permitted";
        const msg = std.fmt.bufPrint(&b, "symlink(): {s}", .{reason}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    }
    return Value.initBool(true);
}

pub fn php_readlink(path: Value, allocator: Allocator) !Value {
    if (!path.isString()) return Value.initBool(false);
    const z = allocator.dupeSentinel(u8, path.asString().data, 0) catch return Value.initBool(false);
    defer allocator.free(z);
    var buf: [4096]u8 = undefined;
    const n = std.c.readlink(z, &buf, buf.len);
    if (n < 0) {
        var b: [512]u8 = undefined;
        const reason = if (fsStatRaw(allocator, path.asString().data, true) == null) "No such file or directory" else "Invalid argument";
        const msg = std.fmt.bufPrint(&b, "readlink(): {s}", .{reason}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    }
    return Value.initString(try PHPString.init(allocator, buf[0..@intCast(n)]));
}

/// clearstatcache - AOT 不做 stat 缓存 ⇒ 纯 no-op（参数按 PHP 签名吞下）。
pub fn php_clearstatcache(clear_realpath: Value, filename: Value) !Value {
    _ = clear_realpath;
    _ = filename;
    return Value.initNull();
}

// ============================================================================
// ★F-178（R-277）：CSV 族（fgetcsv / fputcsv）
//   参数以 null 作「未提供」哨兵：$escape 未提供时 PHP 8.5 会发 E_DEPRECATED 并沿用 "\\"。
// ============================================================================

fn csvParamChar(v: Value, default: u8) u8 {
    if (v.isString() and v.asString().data.len > 0) return v.asString().data[0];
    return default;
}

/// 读一条 CSV 逻辑行（引号内的换行不算行尾）。返回 0 表示 EOF（无内容）。
fn csvReadLine(res: *Value.PHPResource, fh: *std.Io.File, encl: u8, out: *std.ArrayList(u8), allocator: Allocator) !usize {
    var in_quotes = false;
    while (true) {
        var b: [1]u8 = undefined;
        const got = q4BufferedByte(res, fh, allocator, &b[0]) catch return error.ReadFailed;
        if (got == 0) {
            if (res.timed_out) return error.ReadFailed; // ★M2-2-b：fgetcsv 超时 ⇒ false
            if (res.would_block) {
                // ★M2-2-c：非阻塞无数据 ⇒ false；已读部分照常成行（PHP 实测口径）
                if (out.items.len == 0) return error.ReadFailed;
                break;
            }
            if (out.items.len == 0) return 0;
            break;
        }
        try out.append(allocator, b[0]);
        if (b[0] == encl) in_quotes = !in_quotes;
        if (b[0] == '\n' and !in_quotes) break;
    }
    return out.items.len;
}

/// 解析一行到字段数组（空行 ⇒ `[null]`，与 PHP 一致）。
fn csvParseLine(line: []const u8, sep: u8, encl: u8, esc: ?u8, allocator: Allocator) !Value {
    var body = line;
    if (body.len > 0 and body[body.len - 1] == '\n') body = body[0 .. body.len - 1];
    if (body.len > 0 and body[body.len - 1] == '\r') body = body[0 .. body.len - 1];

    const arr = try PHPArray.init(allocator);
    if (body.len == 0) {
        try arr.push(allocator, Value.initNull());
        return Value.initArray(arr);
    }

    var i: usize = 0;
    while (true) {
        var field = std.ArrayList(u8).empty;
        defer field.deinit(allocator);

        if (i < body.len and body[i] == encl) {
            i += 1;
            while (i < body.len) {
                if (esc) |e| {
                    if (body[i] == e and i + 1 < body.len) {
                        const nxt = body[i + 1];
                        if (nxt == encl or nxt == e) {
                            try field.append(allocator, nxt);
                            i += 2;
                            continue;
                        }
                    }
                }
                if (body[i] == encl) {
                    if (i + 1 < body.len and body[i + 1] == encl) {
                        try field.append(allocator, encl);
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                try field.append(allocator, body[i]);
                i += 1;
            }
            // 收尾引号之后、分隔符之前的残余字面量（PHP 语义）
            while (i < body.len and body[i] != sep) : (i += 1) try field.append(allocator, body[i]);
        } else {
            while (i < body.len and body[i] != sep) : (i += 1) try field.append(allocator, body[i]);
        }

        try arr.push(allocator, Value.initString(try PHPString.init(allocator, field.items)));
        if (i < body.len and body[i] == sep) {
            i += 1;
            continue;
        }
        break;
    }
    return Value.initArray(arr);
}

/// fgetcsv - PHP 契约：fgetcsv($stream, ?int $length = null, string $separator = ",", string $enclosure = '"', string $escape = "\\")
pub fn php_fgetcsv(handle: Value, length: Value, separator: Value, enclosure: Value, escape: Value, allocator: Allocator) !Value {
    // ★PHP 8.5：**非 resource** 与**已关闭 resource** 是两套措辞（ZPP vs 函数体）
    if (!handle.isResource()) {
        if (handle.hasResourceType()) {
            return throwThrowable("TypeError", "fgetcsv(): Argument #1 ($stream) must be an open stream resource", runtime_allocator);
        }
        var ebuf: [256]u8 = undefined;
        const tname = if (Value_isObject(handle)) Value_asObject(handle).class_name else valueTypeName(handle);
        const msg = std.fmt.bufPrint(&ebuf, "fgetcsv(): Argument #1 ($stream) must be of type resource, {s} given", .{tname}) catch "fgetcsv(): Argument #1 ($stream) must be of type resource";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    const res = handle.asResource();
    if (res.closed or res.file_handle == null) {
        return throwThrowable("TypeError", "fgetcsv(): Argument #1 ($stream) must be an open stream resource", runtime_allocator);
    }
    var esc_opt: ?u8 = null;
    if (escape.isNull()) {
        // ★PHP 8.5：省略 $escape 会逐次调用发 E_DEPRECATED，行为仍用 "\\"
        emitDeprecated("fgetcsv(): the $escape parameter must be provided as its default value will change");
        esc_opt = '\\';
    } else if (escape.isString() and escape.asString().data.len > 0) {
        esc_opt = escape.asString().data[0];
    }
    const sep = csvParamChar(separator, ',');
    const encl = csvParamChar(enclosure, '"');
    const fh = res.file_handle.?;

    var line = std.ArrayList(u8).empty;
    defer line.deinit(allocator);
    const n = csvReadLine(res, fh, encl, &line, allocator) catch return Value.initBool(false);
    if (n == 0) {
        res.eof = true;
        return Value.initBool(false);
    }
    // $length 给定时截断（PHP：最多读 length 字节）
    var effective = line.items;
    if (!length.isNull()) {
        const lim = length.toInt();
        if (lim > 0 and @as(usize, @intCast(lim)) < effective.len) effective = effective[0..@intCast(lim)];
    }
    return csvParseLine(effective, sep, encl, esc_opt, allocator);
}

/// fputcsv - PHP 契约：fputcsv($stream, array $fields, string $separator = ",", string $enclosure = '"', string $escape = "\\", string $eol = "\n")
pub fn php_fputcsv(handle: Value, fields: Value, separator: Value, enclosure: Value, escape: Value, eol: Value, allocator: Allocator) !Value {
    // ★PHP 8.5：**非 resource** 与**已关闭 resource** 是两套措辞（ZPP vs 函数体）
    if (!handle.isResource()) {
        if (handle.hasResourceType()) {
            return throwThrowable("TypeError", "fputcsv(): Argument #1 ($stream) must be an open stream resource", runtime_allocator);
        }
        var ebuf: [256]u8 = undefined;
        const tname = if (Value_isObject(handle)) Value_asObject(handle).class_name else valueTypeName(handle);
        const msg = std.fmt.bufPrint(&ebuf, "fputcsv(): Argument #1 ($stream) must be of type resource, {s} given", .{tname}) catch "fputcsv(): Argument #1 ($stream) must be of type resource";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    const res = handle.asResource();
    if (res.closed or res.file_handle == null) {
        return throwThrowable("TypeError", "fputcsv(): Argument #1 ($stream) must be an open stream resource", runtime_allocator);
    }
    if (!fields.isArray()) return Value.initBool(false);
    var esc_opt: ?u8 = null;
    if (escape.isNull()) {
        emitDeprecated("fputcsv(): the $escape parameter must be provided as its default value will change");
        esc_opt = '\\';
    } else if (escape.isString() and escape.asString().data.len > 0) {
        esc_opt = escape.asString().data[0];
    }
    const sep = csvParamChar(separator, ',');
    const encl = csvParamChar(enclosure, '"');
    const eol_str: []const u8 = if (eol.isString()) eol.asString().data else "\n";
    const fh = res.file_handle.?;

    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);

    const arr = fields.asArray();
    var idx: usize = 0;
    while (idx < arr.count()) : (idx += 1) {
        if (idx > 0) try out.append(allocator, sep);
        const val = arr.get(ArrayKey{ .integer = @intCast(idx) }) orelse Value.initNull();
        const s = if (val.isString()) val.asString().data else blk: {
            const tmp = val.toString(allocator) catch break :blk "";
            defer tmp.release(allocator);
            break :blk try allocator.dupe(u8, tmp.data);
        };
        defer if (!val.isString() and s.len > 0) allocator.free(s);

        var needs_quote = false;
        for (s) |c| {
            if (c == sep or c == encl or c == '\n' or c == '\r' or c == '\t' or c == ' ') {
                needs_quote = true;
                break;
            }
            if (esc_opt) |e| {
                if (c == e) {
                    needs_quote = true;
                    break;
                }
            }
        }
        if (needs_quote) {
            try out.append(allocator, encl);
            for (s) |c| {
                if (c == encl) try out.append(allocator, encl);
                try out.append(allocator, c);
            }
            try out.append(allocator, encl);
        } else {
            try out.appendSlice(allocator, s);
        }
    }
    try out.appendSlice(allocator, eol_str);
    // ★M2-2：经 NetPoller 让出（与 fwrite 同口径；写失败 ⇒ false）
    const written = q4WriteFh(res, fh, out.items) catch return Value.initBool(false);
    return Value.initInt(@intCast(written));
}

// ============================================================================
// ★R-278（F-178 第二段）：目录句柄族 opendir / readdir / rewinddir / closedir
//   PHP 实测：readdir 含 "." 与 ".."（原始目录项顺序）；rewinddir/closedir 返回 NULL。
// ============================================================================

const PhpDirHandle = struct {
    dir: std.Io.Dir,
    iter: std.Io.Dir.Iterator,
    /// 0 ⇒ 下一个返回 "."；1 ⇒ ".."；2 ⇒ 交给真实迭代器
    dot_state: u8 = 0,
};

/// ★F-178-b：`readdir/rewinddir/closedir(null)` 回退到「最后打开的目录流」。
///   PHP 实测：该回退流**不随用户引用归零而释放**（`unset($h)` 后 `readdir(null)` 仍返回下一项）
///   ⇒ 注册表自己持一个引用；`closedir`（含 null 形）或新的 `opendir` 才摘掉。
var last_opened_dir: ?*Value.PHPResource = null;

fn setLastOpenedDir(res: *Value.PHPResource) void {
    if (last_opened_dir) |old| {
        if (old == res) return;
        old.release(runtime_allocator);
    }
    res.retain();
    last_opened_dir = res;
}

/// 摘掉注册表引用。★调用后不得再触碰 `res`（可能是最后一个引用）。
fn clearLastOpenedDir(res: *Value.PHPResource) void {
    if (last_opened_dir == res) {
        last_opened_dir = null;
        res.release(runtime_allocator);
    }
}

/// ★R-278：目录句柄实参三档分诊（PHP 实测三套措辞）：
///   非 resource ⇒ ZPP「must be of type resource or null, {type} given」；
///   已关闭     ⇒ 「must be an open stream resource」；
///   非目录资源 ⇒ 「must be a valid Directory resource」。
const DirArg = union(enum) {
    res: *Value.PHPResource,
    thrown: Value,
};

fn dirArgCheck(handle: Value, fn_name: []const u8) DirArg {
    // ★F-178-b：null ⇒ Deprecated（原文无 `parameter #1` 段）＋回退最后打开的目录流；无流 ⇒ TypeError。
    if (handle.isNull()) {
        var b: [320]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "{s}(): Passing null is deprecated, instead the last opened directory stream should be provided", .{fn_name}) catch "";
        emitDeprecated(msg);
        const last = last_opened_dir orelse
            return .{ .thrown = throwThrowable("TypeError", "No resource supplied", runtime_allocator) catch Value.initNull() };
        return .{ .res = last };
    }
    if (!handle.isResource()) {
        var b: [256]u8 = undefined;
        if (handle.hasResourceType()) {
            const msg = std.fmt.bufPrint(&b, "{s}(): Argument #1 ($dir_handle) must be an open stream resource", .{fn_name}) catch "";
            return .{ .thrown = throwThrowable("TypeError", msg, runtime_allocator) catch Value.initNull() };
        }
        const tname = if (Value_isObject(handle)) Value_asObject(handle).class_name else valueTypeName(handle);
        const msg = std.fmt.bufPrint(&b, "{s}(): Argument #1 ($dir_handle) must be of type resource or null, {s} given", .{ fn_name, tname }) catch "";
        return .{ .thrown = throwThrowable("TypeError", msg, runtime_allocator) catch Value.initNull() };
    }
    const res = handle.asResource();
    if (res.closed) {
        var b: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "{s}(): Argument #1 ($dir_handle) must be an open stream resource", .{fn_name}) catch "";
        return .{ .thrown = throwThrowable("TypeError", msg, runtime_allocator) catch Value.initNull() };
    }
    if (res.dir_handle == null) {
        var b: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "{s}(): Argument #1 ($dir_handle) must be a valid Directory resource", .{fn_name}) catch "";
        return .{ .thrown = throwThrowable("TypeError", msg, runtime_allocator) catch Value.initNull() };
    }
    return .{ .res = res };
}

/// opendir - PHP 契约：opendir(string $directory, ?resource $context = null): resource|false
pub fn php_opendir(dirname: Value, context: Value, allocator: Allocator) !Value {
    _ = context;
    _ = allocator; // 句柄与资源对象统一用 runtime_allocator（与 closedir/release 配对）
    if (!dirname.isString()) return Value.initBool(false);
    const path = dirname.asString().data;
    const dir = std.Io.Dir.cwd().openDir(getIo(), path, .{ .iterate = true }) catch |err| {
        var b: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&b, "opendir({s}): Failed to open directory: {s}", .{ path, fsErrText(err) }) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };
    const dh = runtime_allocator.create(PhpDirHandle) catch {
        dir.close(getIo());
        return Value.initBool(false);
    };
    dh.* = .{ .dir = dir, .iter = dir.iterate(), .dot_state = 0 };
    const res = runtime_allocator.create(Value.PHPResource) catch {
        dir.close(getIo());
        runtime_allocator.destroy(dh);
        return Value.initBool(false);
    };
    res.* = .{ .ref_count = 1, .file_handle = null, .type_name = "stream", .dir_handle = dh };
    setLastOpenedDir(res);
    return Value.initResource(res);
}

/// readdir - 逐个返回条目（先 "." 与 ".."）；读完返回 false。
pub fn php_readdir(handle: Value, allocator: Allocator) !Value {
    const res = switch (dirArgCheck(handle, "readdir")) {
        .thrown => |v| return v,
        .res => |r| r,
    };
    const dh = res.dir_handle.?;
    if (dh.dot_state == 0) {
        dh.dot_state = 1;
        return Value.initString(try PHPString.init(allocator, "."));
    }
    if (dh.dot_state == 1) {
        dh.dot_state = 2;
        return Value.initString(try PHPString.init(allocator, ".."));
    }
    if (dh.iter.next(getIo()) catch null) |entry| {
        return Value.initString(try PHPString.init(allocator, entry.name));
    }
    return Value.initBool(false);
}

/// rewinddir - 游标回到开头（返回 NULL，与 PHP 一致）。
pub fn php_rewinddir(handle: Value) !Value {
    const res = switch (dirArgCheck(handle, "rewinddir")) {
        .thrown => |v| return v,
        .res => |r| r,
    };
    const dh = res.dir_handle.?;
    dh.iter = dh.dir.iterate();
    dh.dot_state = 0;
    return Value.initNull();
}

// ============================================================================
// ★F-178 尾（R-279）：disk_free_space / disk_total_space
//   平台差异：macOS 用 `statfs`（f_bsize 为 u32），Linux 用 `statvfs`（f_bsize 为 c_ulong）。
//   结构体只声明所需前缀 + 尾部填充（≥ 真实 sizeof），避免布局错误越界。
// ============================================================================

const StatFsDarwin = extern struct {
    f_bsize: u32,
    f_iosize: i32,
    f_blocks: u64,
    f_bfree: u64,
    f_bavail: u64,
    // 前缀 32B + 尾部 2144B = 2176B ≥ macOS 真实 sizeof(struct statfs)=2168B。
    // 尾部必须 ≥ 真实尺寸：statfs 会写满整个结构，少 1 字节即越界踩栈帧。
    _tail: [2144]u8,
};

const StatVfsLinux = extern struct {
    f_bsize: c_ulong,
    f_frsize: c_ulong,
    f_blocks: c_ulong,
    f_bfree: c_ulong,
    f_bavail: c_ulong,
    // 前缀 40B + 尾部 112B = 152B ≥ Linux x86_64 真实 sizeof(struct statvfs)=112B。
    _tail: [112]u8,
};

extern "c" fn statfs(path: [*:0]const u8, buf: *StatFsDarwin) c_int;
extern "c" fn statvfs(path: [*:0]const u8, buf: *StatVfsLinux) c_int;

const DiskSpace = struct { total: f64, free: f64 };
const DiskQuery = union(enum) { ok: DiskSpace, skip, fail: c_int };

extern "c" fn strerror(errnum: c_int) [*:0]const u8;

fn diskQuery(path: []const u8) DiskQuery {
    if (path.len == 0) return .skip;
    const z = runtime_allocator.dupeSentinel(u8, path, 0) catch return .skip;
    defer runtime_allocator.free(z);
    if (comptime builtin.os.tag == .macos or builtin.os.tag == .ios) {
        var buf: StatFsDarwin = undefined;
        if (statfs(z, &buf) != 0) return .{ .fail = std.c._errno().* };
        const unit: f64 = @floatFromInt(@as(u64, buf.f_bsize));
        return .{ .ok = .{ .total = unit * @as(f64, @floatFromInt(buf.f_blocks)), .free = unit * @as(f64, @floatFromInt(buf.f_bavail)) } };
    } else {
        var buf: StatVfsLinux = undefined;
        if (statvfs(z, &buf) != 0) return .{ .fail = std.c._errno().* };
        const frs: u64 = if (buf.f_frsize != 0) @intCast(buf.f_frsize) else @intCast(buf.f_bsize);
        const unit: f64 = @floatFromInt(frs);
        return .{ .ok = .{ .total = unit * @as(f64, @floatFromInt(buf.f_blocks)), .free = unit * @as(f64, @floatFromInt(buf.f_bavail)) } };
    }
}

/// disk_* 共用实现（PHP 8.5.8 实测口径）：
///   · 形参 `$directory` weak string：标量强转、stringable 对象取 __toString、其它类型 TypeError；
///   · null ⇒ `Passing null … of type string is deprecated` 后按空串处理；
///   · 空路径 ⇒ **静默** false（PHP 不打 Warning）；statfs 失败 ⇒ `Warning: <fn>(): <strerror>` + false。
fn diskSpaceValue(fn_name: []const u8, directory: Value, want_total: bool) !Value {
    var v = directory;
    while (v.isRef()) v = v.asRef().*;
    _ = requireStringParamWeak(fn_name, 1, "directory", v) orelse return Value.initNull();
    var tmp: ?*PHPString = null;
    defer if (tmp) |t| t.release(runtime_allocator);
    const path: []const u8 = if (v.isString()) v.asString().data else blk: {
        if (v.isNull()) {
            emitDeprecatedPassingNull(fn_name, 1, "directory", "string");
            break :blk "";
        }
        tmp = try v.toString(runtime_allocator);
        break :blk tmp.?.data;
    };
    switch (diskQuery(path)) {
        .skip => return Value.initBool(false),
        .fail => |e| {
            var mbuf: [512]u8 = undefined;
            const msg = std.fmt.bufPrint(&mbuf, "{s}(): {s}", .{ fn_name, std.mem.span(strerror(e)) }) catch return Value.initBool(false);
            emitWarning(msg);
            return Value.initBool(false);
        },
        .ok => |ds| return Value.initFloat(if (want_total) ds.total else ds.free),
    }
}

/// disk_free_space - 返回可用字节数（float）；失败措辞见 diskSpaceValue。
pub fn php_disk_free_space(directory: Value) !Value {
    return diskSpaceValue("disk_free_space", directory, false);
}

/// disk_total_space - 返回总字节数（float）；失败措辞见 diskSpaceValue。
pub fn php_disk_total_space(directory: Value) !Value {
    return diskSpaceValue("disk_total_space", directory, true);
}

/// closedir - 关闭目录句柄（返回 NULL）。
pub fn php_closedir(handle: Value) !Value {
    const res = switch (dirArgCheck(handle, "closedir")) {
        .thrown => |v| return v,
        .res => |r| r,
    };
    const dh = res.dir_handle.?;
    dh.dir.close(getIo());
    runtime_allocator.destroy(dh);
    res.dir_handle = null;
    res.closed = true;
    // ★F-178-b：摘注册表引用必须是最后一步（res 可能因此被释放）
    clearLastOpenedDir(res);
    return Value.initNull();
}

// ============================================================================
// 系统信息函数
// ============================================================================

pub fn php_getcwd(allocator: Allocator) !Value {
    // ★R-274：Zig 0.16 的 Dir 无 `realpathAlloc`（旧 API）；改走 `realPathFileAlloc(io, path, alloc)`。
    const cwd = std.Io.Dir.cwd().realPathFileAlloc(getIo(), ".", allocator) catch return Value.initBool(false);
    defer allocator.free(cwd);
    const output = try PHPString.init(allocator, cwd);
    return Value.initString(output);
}

pub fn php_sapi_name(allocator: Allocator) !Value {
    const output = try PHPString.init(allocator, try allocator.dupe(u8, "cli"));
    return Value.initString(output);
}

pub fn php_uname(allocator: Allocator) !Value {
    const uname_info = if (builtin.os.tag == .macos)
        "Darwin"
    else if (builtin.os.tag == .linux)
        "Linux"
    else if (builtin.os.tag == .windows)
        "Windows"
    else
        "Unknown";

    const output = try PHPString.init(allocator, try allocator.dupe(u8, uname_info));
    return Value.initString(output);
}

pub fn php_unlink(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    std.Io.Dir.cwd().deleteFile(getIo(), fname) catch |err| {
        var mbuf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "unlink({s}): {s}", .{ fname, fsErrText(err) }) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };
    return Value.initBool(true);
}

pub fn php_filesize(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    // ★R-275：PHP 走 stat；失败文案是 `filesize(): stat failed for <path>`
    const st = std.Io.Dir.cwd().statFile(getIo(), fname, .{}) catch {
        var mbuf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "filesize(): stat failed for {s}", .{fname}) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };
    return Value.initInt(@intCast(st.size));
}

pub fn php_is_file(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const stat = std.Io.Dir.cwd().statFile(getIo(), fname, .{}) catch return Value.initBool(false);
    return Value.initBool(stat.kind == .file);
}

pub fn php_is_dir(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    var dir = std.Io.Dir.cwd().openDir(getIo(), fname, .{}) catch return Value.initBool(false);
    dir.close(getIo());
    return Value.initBool(true);
}

pub fn php_is_readable(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const file = std.Io.Dir.cwd().openFile(getIo(), fname, .{}) catch return Value.initBool(false);
    file.close(getIo());
    return Value.initBool(true);
}

pub fn php_is_writable(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const file = std.Io.Dir.cwd().createFile(getIo(), fname, .{ .truncate = false }) catch return Value.initBool(false);
    file.close(getIo());
    return Value.initBool(true);
}

/// filemtime - 获取文件修改时间
pub fn php_filemtime(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const file = std.Io.Dir.cwd().openFile(getIo(), fname, .{}) catch return Value.initBool(false);
    defer file.close(getIo());
    const stat = file.stat(getIo()) catch return Value.initBool(false);
    // 返回Unix时间戳
    return Value.initInt(@intCast(std.Io.Timestamp.toSeconds(stat.mtime)));
}

/// fileatime - 获取文件访问时间
pub fn php_fileatime(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const file = std.Io.Dir.cwd().openFile(getIo(), fname, .{}) catch return Value.initBool(false);
    defer file.close(getIo());
    const stat = file.stat(getIo()) catch return Value.initBool(false);
    return Value.initInt(@intCast(if (stat.atime) |a| std.Io.Timestamp.toSeconds(a) else 0));
}

/// filectime - 获取文件创建时间（Unix下为inode修改时间）
pub fn php_filectime(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;
    const file = std.Io.Dir.cwd().openFile(getIo(), fname, .{}) catch return Value.initBool(false);
    defer file.close(getIo());
    const stat = file.stat(getIo()) catch return Value.initBool(false);
    return Value.initInt(@intCast(std.Io.Timestamp.toSeconds(stat.ctime)));
}

// ============================================================================
// 错误处理函数
// ============================================================================

// 全局错误处理器存储
threadlocal var global_error_handler: ?Value = null;
/// ★F-140：`set_error_handler($h, $mask)` 的第二形参是**处理器掩码**，与 `error_reporting` 无关。
///   旧实现把它写进 `global_error_types` ⇒ 既误改报告级别，又让掩码外的诊断仍调处理器（门 ERRH h7 红）。
threadlocal var global_error_handler_mask: i64 = E_ALL;
const ErrorHandlerFrame = struct {
    handler: ?Value,
    mask: i64,
};
threadlocal var error_handler_stack: std.ArrayListUnmanaged(ErrorHandlerFrame) = .empty;
threadlocal var global_error_types: i64 = E_ALL;
threadlocal var global_exception_handler: ?Value = null;

// 错误级别常量
pub const E_ERROR: i64 = 1;
pub const E_WARNING: i64 = 2;
pub const E_PARSE: i64 = 4;
pub const E_NOTICE: i64 = 8;
pub const E_CORE_ERROR: i64 = 16;
pub const E_CORE_WARNING: i64 = 32;
pub const E_COMPILE_ERROR: i64 = 64;
pub const E_COMPILE_WARNING: i64 = 128;
pub const E_USER_ERROR: i64 = 256;
pub const E_USER_WARNING: i64 = 512;
pub const E_USER_NOTICE: i64 = 1024;
pub const E_STRICT: i64 = 2048;
pub const E_RECOVERABLE_ERROR: i64 = 4096;
pub const E_DEPRECATED: i64 = 8192;
pub const E_USER_DEPRECATED: i64 = 16384;
pub const E_ALL: i64 = 30719;

/// set_error_handler - 设置用户自定义错误处理函数
/// ★F-140：第二形参是**处理器掩码**（默认 E_ALL），不是 error_reporting；且 restore 要恢复上一层的处理器与掩码。
pub fn php_set_error_handler(handler: Value, error_types: Value, allocator: Allocator) !Value {
    _ = allocator;
    // 返回之前设置的错误处理器（沿用既有借用语义，不额外 retain）
    const prev_handler = if (global_error_handler) |h| h else Value.initNull();

    // 嵌套栈：保存当前处理器与掩码。★沿用既有“处理器永不释放”的所有权约定（见 F-140-b）。
    error_handler_stack.append(runtime_allocator, .{
        .handler = global_error_handler,
        .mask = global_error_handler_mask,
    }) catch {};

    if (handler.isNull()) {
        // F-140-b：清空处理器时释放当前持有的引用（set 时 retain 过），不再沿用
        //「永不释放」的净+1 漏洞。
        if (global_error_handler) |cur| cur.release(runtime_allocator);
        global_error_handler = null;
    } else {
        _ = handler.retain();
        global_error_handler = handler;
    }
    global_error_handler_mask = if (error_types.isNull()) E_ALL else error_types.toInt();
    return prev_handler;
}

/// restore_error_handler - 恢复上一层的处理器与掩码；PHP 返回 bool(true)（实测，含空栈）。
pub fn php_restore_error_handler() !Value {
    // F-140-b：被替换下的当前处理器释放其引用（set 时 retain 的净+1），
    // 栈帧里的上一层处理器是转移持有的既有引用（不再 retain），回装为当前。
    if (global_error_handler) |cur| cur.release(runtime_allocator);
    if (error_handler_stack.pop()) |frame| {
        global_error_handler = frame.handler;
        global_error_handler_mask = frame.mask;
    } else {
        global_error_handler = null;
        global_error_handler_mask = E_ALL;
    }
    return Value.initBool(true);
}

/// set_exception_handler - 设置用户自定义异常处理函数
pub fn php_set_exception_handler(handler: Value, allocator: Allocator) !Value {
    _ = allocator;
    const prev = if (global_exception_handler) |h| h else Value.initNull();
    if (handler.isNull()) {
        global_exception_handler = null;
    } else {
        _ = handler.retain();
        global_exception_handler = handler;
    }
    return prev;
}

/// restore_exception_handler - 恢复之前的异常处理函数
pub fn php_restore_exception_handler() !Value {
    const prev = if (global_exception_handler) |h| h else Value.initNull();
    global_exception_handler = null;
    return prev;
}

/// trigger_error - 触发用户错误
/// ★F-92（R-180）：与引擎诊断**共用同一分发口**。旧实现自成一套，四处偏差逐条修：
///   ①实参序 `message` 在前 ⇒ 用户处理器里 `$no`/`$str` 互换（PHP 是 `(errno, errstr, errfile, errline)`）；
///   ②结构 `if (handler) { 掩码内调用 } else { 打印 }` ⇒ **掩码不匹配时 PHP 照打、AOT 彻底静默**；
///   ③`_ = closure(...) catch {}` 丢掉返回值 ⇒ 处理器 `return false` 该补的标准打印补不上；
///   ④无处理器分支用 `std.debug.print`（只走 stderr 一行、缺 `PHP Warning:  ` 首行与 `in 文件 on line N`）。
/// ★F-105/F-106（R-223）：`E_USER_ERROR` 在 PHP 8.4+ **先**发一条 E_DEPRECATED，无处理器时再发 Fatal、
///   打印同款栈帧、执行 shutdown 并以 255 退出；有处理器且返回非 false 时继续执行 rc=0（实测）。
pub fn php_trigger_error(message: Value, error_type: Value, allocator: Allocator) !Value {
    _ = allocator;
    if (!message.isString()) return Value.initBool(false);

    const err_type: i64 = if (error_type.isNull()) E_USER_NOTICE else error_type.toInt();
    const msg = message.asString().data;

    const loc = diagLoc();
    if (err_type == E_USER_ERROR) {
        emitDeprecated("Passing E_USER_ERROR to trigger_error() is deprecated since 8.4, throw an exception or call exit with a string message instead");
        restoreDiagLoc(loc);
    }
    if (dispatchToUserHandler(err_type, msg)) |handled| {
        if (handled) return Value.initBool(true); // C4：处理器接管 ⇒ 不打任何字
    }
    restoreDiagLoc(loc);
    // C3／C5／没设处理器 ⇒ 标准处理（两行两流，与引擎诊断同一套文案规则）
    switch (err_type) {
        E_USER_ERROR => printUserErrorFatalAndExit(msg),
        E_USER_WARNING => standardPrint("PHP Warning:  ", "\nWarning: ", msg, E_USER_WARNING),
        E_USER_NOTICE => standardPrint("PHP Notice:  ", "\nNotice: ", msg, E_USER_NOTICE),
        E_USER_DEPRECATED => standardPrint("PHP Deprecated:  ", "\nDeprecated: ", msg, E_USER_DEPRECATED),
        else => {
            var buf: [1024]u8 = undefined;
            const old = std.fmt.bufPrint(&buf, "Error: {s}\n", .{msg}) catch return Value.initBool(true);
            fileWriteAll(2, old);
        },
    }

    return Value.initBool(true);
}

/// ★F-105/F-106：`E_USER_ERROR` 的 Fatal 面。PHP 实测：
///   - 显示受 `error_reporting & E_USER_ERROR` 门控（不是 E_ERROR 位），但 **`@` 不抑制 Fatal**（实测）；
///   - stdout 是 `\nFatal error: …`、stderr 是 `PHP Fatal error:  …`（两空格），两边都跟同款栈帧；
///   - 栈帧首参按 PHP 的渲染规则：反斜杠加倍、换行写成 `\n`，单引号**不转义**（实测）；
///   - 无论是否显示、是否有 shutdown，rc=255 且 shutdown 函数执行。
fn printUserErrorFatalAndExit(msg: []const u8) noreturn {
    if ((E_USER_ERROR & global_error_types) != 0) {
        var ebuf: [1024]u8 = undefined;
        const eline: []const u8 = std.fmt.bufPrint(&ebuf, "PHP Fatal error:  {s} in {s} on line {d}\n", .{ msg, src_file, src_line }) catch "";
        fileWriteAll(2, eline);
        var obuf: [1024]u8 = undefined;
        const oline: []const u8 = std.fmt.bufPrint(&obuf, "\nFatal error: {s} in {s} on line {d}\n", .{ msg, src_file, src_line }) catch "";
        fileWriteAll(1, oline);

        var esc_buf: [512]u8 = undefined;
        var esc_len: usize = 0;
        for (msg) |c| {
            const piece: []const u8 = switch (c) {
                '\\' => "\\\\",
                '\n' => "\\n",
                else => "",
            };
            if (piece.len > 0) {
                if (esc_len + piece.len > esc_buf.len) break;
                @memcpy(esc_buf[esc_len..][0..piece.len], piece);
                esc_len += piece.len;
            } else {
                if (esc_len + 1 > esc_buf.len) break;
                esc_buf[esc_len] = c;
                esc_len += 1;
            }
        }
        var tbuf: [2048]u8 = undefined;
        const trace: []const u8 = std.fmt.bufPrint(&tbuf,
            "Stack trace:\n#0 {s}({d}): trigger_error('{s}', 256)\n#1 {{main}}\n",
            .{ src_file, src_line, esc_buf[0..esc_len] }) catch "";
        fileWriteAll(2, trace);
        fileWriteAll(1, trace);
    }
    php_run_shutdown_functions();
    std.process.exit(255);
}

/// error_reporting - 设置或获取错误报告级别
pub fn php_error_reporting(level: Value) !Value {
    const prev_level = global_error_types;
    if (!level.isNull()) {
        global_error_types = level.toInt();
    }
    return Value.initInt(prev_level);
}

pub fn php_sys_get_temp_dir(allocator: Allocator) !Value {
    const tmp_dir = if (builtin.os.tag == .windows) "C:\\Windows\\Temp" else "/tmp";
    const output = try PHPString.init(allocator, try allocator.dupe(u8, tmp_dir));
    return Value.initString(output);
}

/// file - PHP 契约：filename, flags=0, context=null
///   ★F-173（R-270）：支持 `FILE_IGNORE_NEW_LINES`(2)／`FILE_SKIP_EMPTY_LINES`(4)；
///   ★行尾语义：末行**无换行**时不补 `\n`（PHP 实测 `"a\nbc"` ⇒ `["a\n","bc"]`）；
///   `FILE_USE_INCLUDE_PATH`(1) 与 context 未建模 ⇒ 仅吞下。
pub fn php_file(filename: Value, flags: Value, context: Value, allocator: Allocator) !Value {
    _ = context;
    if (!filename.isString()) return Value.initBool(false);
    const fname = filename.asString().data;

    // ★R-269：同 `php_file_get_contents`——补 `Io.Limit`（原裸 int 只有实例化时才编译失败）
    const content = std.Io.Dir.cwd().readFileAlloc(getIo(), fname, allocator, .limited(10 * 1024 * 1024)) catch |err| {
        warnOpenStream("file", fname, err);
        return Value.initBool(false);
    };
    defer allocator.free(content);

    const flag_bits = flags.toInt();
    const ignore_new_lines = (flag_bits & 2) != 0;
    const skip_empty_lines = (flag_bits & 4) != 0;

    const arr = try PHPArray.init(allocator);
    var idx: i64 = 0;
    var pos: usize = 0;
    while (pos < content.len) {
        const nl = std.mem.indexOfScalarPos(u8, content, pos, '\n');
        const line_end = nl orelse content.len;
        const line = content[pos..line_end];
        const had_newline = nl != null;
        pos = if (had_newline) line_end + 1 else content.len;

        // ★PHP 实测：FILE_SKIP_EMPTY_LINES **只在**同时忽略换行（或行本身为空）时才生效——
        //   单独使用时空白行仍以 "\n" 返回（`["\n","\n","a\n","\n"]`），两标志同用 ⇒ 只剩 "a"。
        if (skip_empty_lines and ignore_new_lines and line.len == 0) continue;

        if (!ignore_new_lines and had_newline) {
            const line_with_newline = try std.fmt.allocPrint(allocator, "{s}\n", .{line});
            const line_str = try PHPString.init(allocator, line_with_newline);
            allocator.free(line_with_newline);
            try arr.set(allocator, ArrayKey{ .integer = idx }, Value.initString(line_str));
        } else {
            try arr.set(allocator, ArrayKey{ .integer = idx }, Value.initString(try PHPString.init(allocator, line)));
        }
        idx += 1;
    }
    return Value.initArray(arr);
}

pub fn php_function_exists(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (args.len != 1) return error.InvalidArgumentCount;
    if (!args[0].isString()) return Value.initBool(false);
    return Value.initBool(lookupBuiltinFunction(args[0].asString().data) != null);
}

pub fn php_gc_enable(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (args.len != 0) return error.InvalidArgumentCount;
    gc_enabled = true;
    return Value.initNull();
}

pub fn php_gc_collect_cycles(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (args.len != 0) return error.InvalidArgumentCount;
    return Value.initInt(@intCast(php_collect_cycles()));
}

pub fn php_ini_get(args: []const Value, allocator: Allocator) !Value {
    if (args.len != 1) return error.InvalidArgumentCount;
    if (!args[0].isString()) return Value.initBool(false);

    const option = args[0].asString().data;
    const value: ?[]const u8 = if (std.mem.eql(u8, option, "display_errors"))
        "1"
    else if (std.mem.eql(u8, option, "error_reporting"))
        "30719"
    else if (std.mem.eql(u8, option, "max_execution_time"))
        "0"
    else if (std.mem.eql(u8, option, "memory_limit"))
        "128M"
    else if (std.mem.eql(u8, option, "post_max_size"))
        "8M"
    else if (std.mem.eql(u8, option, "upload_max_filesize"))
        "2M"
    else
        null;

    if (value) |s| return Value.initString(try PHPString.init(allocator, s));
    return Value.initBool(false);
}

pub fn php_getrusage(args: []const Value, allocator: Allocator) !Value {
    if (args.len > 1) return error.InvalidArgumentCount;

    const arr = try PHPArray.init(allocator);
    const key = try PHPString.init(allocator, "ru_utime.tv_sec");
    defer key.release(allocator);
    try arr.set(allocator, ArrayKey{ .string = key }, Value.initInt(0));
    return Value.initArray(arr);
}

