/// Convert PHPValue to ArrayKey
fn valueToArrayKey(val: Value, allocator: Allocator) !ArrayKey {
    _ = allocator;
    if (val.isInt()) {
        return ArrayKey{ .integer = val.asInt() };
    } else if (val.isString()) {
        const str = val.asString();
        // Try to parse as integer
        const int_val = std.fmt.parseInt(i64, str.data, 10) catch {
            return ArrayKey{ .string = str };
        };
        return ArrayKey{ .integer = int_val };
    } else if (val.isNull()) {
        return ArrayKey{ .integer = 0 };
    } else if (val.isBool()) {
        return ArrayKey{ .integer = if (val.asBool()) 1 else 0 };
    } else if (val.isFloat()) {
        // ★F-69：原先这里直接 `@intFromFloat(val.asFloat())` **无范围守卫** ⇒ 越界／NAN 键是 Zig 非法行为；
        //   改成与 `normalizeArrayKeyFromValue` 同一条规则＋同一套诊断（两条键路径此前口径不一致）。
        const f = val.asFloat();
        warnFloatToIntNotRepresentable(val);
        const loses_precision = if (std.math.isNan(f)) true else !floatNotRepresentableAsInt(f) and f != @trunc(f);
        if (loses_precision) emitDeprecatedFloatToInt(f);
        return ArrayKey{ .integer = floatToIntPHP(f) };
    }
    return ArrayKey{ .integer = 0 };
}

/// 缺失数组键的 PHP 同款告警：整数键裸写、字符串键带双引号（格式化用**归一后**的键）。
fn emitUndefinedArrayKey(key: ArrayKey) void {
    var buf: [512]u8 = undefined;
    const msg = switch (key) {
        .integer => |i| std.fmt.bufPrint(&buf, "Undefined array key {d}", .{i}) catch "Undefined array key",
        .string => |s| std.fmt.bufPrint(&buf, "Undefined array key \"{s}\"", .{s.data}) catch "Undefined array key",
    };
    emitWarning(msg);
}

/// null 数组键的 E_DEPRECATED（通用措辞；array_key_exists 有自己的专用措辞）。
fn emitNullArrayOffsetDeprecated() void {
    emitDeprecated("Using null as an array offset is deprecated, use an empty string instead");
}

pub fn php_array_get(arr_val: Value, key_val: Value, allocator: Allocator) !Value {
    // 解引用：如果值是引用类型，先解引用获取实际值
    var arr_resolved = arr_val;
    if (arr_resolved.isRef()) {
        arr_resolved = arr_resolved.asRef().*;
    }
    if (Value_isObject(arr_resolved)) {
        const obj = Value_asObject(arr_resolved);
        const has_get = if (obj.class_meta) |meta| meta.findMethod("offsetGet") != null else false;
        if (!has_get) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Cannot use object of type {s} as array", .{obj.class_name}) catch "Cannot use object as array";
            return throwThrowable("Error", msg, runtime_allocator);
        }
        return php_object_call(arr_val, "offsetGet", &[_]Value{key_val});
    }

    if (arr_resolved.isString()) {
        const str = arr_resolved.asString();
        // PHP：float/bool/null 键读字符串偏移先发 E_WARNING「String offset cast occurred」
        if (key_val.isFloat() or key_val.isBool() or key_val.isNull()) {
            emitWarning("String offset cast occurred");
        }
        // 非整数型字符串键（'k'/'1.0'/'1.5x'/''/溢出）⇒ PHP 8.5 TypeError
        const idx_i64 = stringOffsetIndexFromValue(key_val, true) orelse {
            return throwThrowable("TypeError", "Cannot access offset of type string on string", runtime_allocator);
        };
        const len: i64 = @intCast(str.length);
        const real: i64 = if (idx_i64 < 0) len + idx_i64 else idx_i64;
        if (real < 0 or real >= len) {
            var wbuf: [128]u8 = undefined;
            const wmsg = std.fmt.bufPrint(&wbuf, "Uninitialized string offset {d}", .{idx_i64}) catch "Uninitialized string offset";
            emitWarning(wmsg);
            return Value.initString(try PHPString.init(allocator, ""));
        }
        const idx = @as(usize, @intCast(real));
        const ch_slice = str.data[idx..@min(idx + 1, str.data.len)];
        return Value.initString(try PHPString.init(allocator, ch_slice));
    }

    if (arr_resolved.isArray()) {
        if (key_val.isNull()) emitNullArrayOffsetDeprecated();
        const key = normalizeArrayKeyFromValue(key_val);
        // ★F-139c：get → 内部已 retain；此处不再 retain（否则每次读自有元素漏一份）。
        if (arr_resolved.asArray().get(key)) |val| {
            return val;
        }
        emitUndefinedArrayKey(key);
        return Value.initNull();
    }

    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "Trying to access array offset on {s}",
        .{phpArgTypeWord(arr_resolved)},
    ) catch "Trying to access array offset";
    emitWarning(msg);

    return Value.initNull();
}

/// ★F-86-b：`isset($x[$k])` / `$x[$k] ?? 默认` 的元素读（PHP 的 BP_VAR_IS 语义）。
/// 与 `php_array_get` 的差别只在“无效/越界/非数组基一律静默给 null”，并补 PHP 的
/// string offset 规则（整数前缀、负下标、非整数前缀告警）与 ArrayAccess 的 offsetExists 门。
/// 返回值所有权同 `php_array_get`（数组元素 retain；string offset 新建；offsetGet 结果直接返回）。
pub fn php_array_get_coalesce(arr_val: Value, key_val: Value, allocator: Allocator) !Value {
    var arr_resolved = arr_val;
    if (arr_resolved.isRef()) {
        arr_resolved = arr_resolved.asRef().*;
    }
    if (Value_isObject(arr_resolved)) {
        const obj = Value_asObject(arr_resolved);
        const has_offset = if (obj.class_meta) |meta| meta.findMethod("offsetExists") != null else false;
        if (!has_offset) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Cannot use object of type {s} as array", .{obj.class_name}) catch "Cannot use object as array";
            return throwThrowable("Error", msg, runtime_allocator);
        }
        const exists = try php_object_call(arr_val, "offsetExists", &[_]Value{key_val});
        defer exists.release(runtime_allocator);
        if (!exists.toBool()) return Value.initNull();
        return php_object_call(arr_val, "offsetGet", &[_]Value{key_val});
    }
    if (arr_resolved.isString()) {
        const str = arr_resolved.asString();
        const idx = stringOffsetIndexFromValue(key_val, true) orelse return Value.initNull();
        const len: i64 = @intCast(str.length);
        const real = if (idx < 0) len + idx else idx;
        if (real < 0 or real >= len) return Value.initNull();
        const u: usize = @intCast(real);
        return Value.initString(try PHPString.init(allocator, str.data[u..@min(u + 1, str.data.len)]));
    }
    if (arr_resolved.isArray()) {
        if (key_val.isNull()) emitNullArrayOffsetDeprecated();
        return arr_resolved.asArray().getByValue(key_val) orelse Value.initNull();
    }
    return Value.initNull();
}

/// PHP string offset 的键解析（`zend_get_string_offset` 口径）：
/// int/float/bool/null 走 zval 转换；string 取整数前缀——'1abc'/'0x10'/'1 2' 用前缀值并告警
/// `Illegal string offset "…"`；浮点前缀（'1.0'/'1e1'/'1.5x'）、整数溢出、无数字前缀一律无效（null）。
fn stringOffsetIndexFromValue(key_val: Value, emit_illegal: bool) ?i64 {
    if (key_val.isRef()) return stringOffsetIndexFromValue(key_val.asRef().*, emit_illegal);
    if (key_val.isInt()) return key_val.asInt();
    if (key_val.isFloat()) return floatToIntPHP(key_val.asFloat());
    if (key_val.isBool()) return if (key_val.asBool()) 1 else 0;
    if (key_val.isNull()) return 0;
    if (!key_val.isString()) return 0;
    const s = key_val.asString().data;
    var i: usize = 0;
    while (i < s.len and std.ascii.isWhitespace(s[i])) i += 1;
    var neg = false;
    if (i < s.len and (s[i] == '-' or s[i] == '+')) {
        neg = s[i] == '-';
        i += 1;
    }
    const digits_start = i;
    var mag: u64 = 0;
    var overflow = false;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
        const d: u64 = s[i] - '0';
        if (mag > (std.math.maxInt(u64) - d) / 10) {
            overflow = true;
            break;
        }
        mag = mag * 10 + d;
    }
    if (i == digits_start) return null;
    if (overflow) return null;
    const int_max_u64: u64 = @intCast(std.math.maxInt(i64));
    if (mag > int_max_u64 + (if (neg) @as(u64, 1) else @as(u64, 0))) return null;
    // 浮点前缀 ⇒ is_numeric_string 返回 IS_DOUBLE ⇒ string offset 无效。
    // '.' 一律视为浮点（'1.'/'1.5x' 实测都是 TypeError）；'e'/'E' 只有后随合法指数才算浮点，
    // 否则按“整数前缀+垃圾”处理（'1e' 实测 = Illegal 告警 + 索引 1）。
    if (i < s.len) {
        if (s[i] == '.') return null;
        if (s[i] == 'e' or s[i] == 'E') {
            var k = i + 1;
            if (k < s.len and (s[k] == '+' or s[k] == '-')) k += 1;
            const exp_start = k;
            while (k < s.len and s[k] >= '0' and s[k] <= '9') k += 1;
            if (k > exp_start) return null;
        }
    }
    var j = i;
    while (j < s.len and std.ascii.isWhitespace(s[j])) j += 1;
    if (j < s.len) {
        // 普通读：整数前缀+垃圾 ⇒ Illegal 告警并用前缀；isset：整键必须整数型（PHP 对 '1abc' 返回 false 且不告警）
        if (!emit_illegal) return null;
        var wbuf: [512]u8 = undefined;
        const wmsg = std.fmt.bufPrint(&wbuf, "Illegal string offset \"{s}\"", .{s}) catch "Illegal string offset";
        emitWarning(wmsg);
    }
    if (neg) {
        if (mag == int_max_u64 + 1) return std.math.minInt(i64);
        return -@as(i64, @intCast(mag));
    }
    return @intCast(mag);
}

/// isset($arr[$key]) - 检查数组键是否存在且非null（不产生警告）
/// 对非数组值返回 false（与 PHP isset 语义一致）
pub fn php_array_isset(arr_val: Value, key_val: Value) !Value {
    var arr_resolved = arr_val;
    if (arr_resolved.isRef()) {
        arr_resolved = arr_resolved.asRef().*;
    }
    if (Value_isObject(arr_resolved)) {
        const obj = Value_asObject(arr_resolved);
        const has_exists = if (obj.class_meta) |meta| meta.findMethod("offsetExists") != null else false;
        if (!has_exists) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Cannot use object of type {s} as array", .{obj.class_name}) catch "Cannot use object as array";
            return throwThrowable("Error", msg, runtime_allocator);
        }
        const result = try php_object_call(arr_val, "offsetExists", &[_]Value{key_val});
        defer result.release(runtime_allocator);
        return Value.initBool(result.toBool());
    }
    if (arr_resolved.isString()) {
        const str = arr_resolved.asString();
        // float 键：PHP isset 仍发「隐式转 int 丢精度」Deprecated；bool/null 静默转
        if (key_val.isFloat()) {
            const f = key_val.asFloat();
            warnFloatToIntNotRepresentable(key_val);
            const loses_precision = if (std.math.isNan(f)) true else !floatNotRepresentableAsInt(f) and f != @trunc(f);
            if (loses_precision) emitDeprecatedFloatToInt(f);
        }
        const idx_i64 = stringOffsetIndexFromValue(key_val, false) orelse return Value.initBool(false);
        const len: i64 = @intCast(str.length);
        const real: i64 = if (idx_i64 < 0) len + idx_i64 else idx_i64;
        return Value.initBool(real >= 0 and real < len);
    }
    if (arr_resolved.isArray()) {
        if (key_val.isNull()) emitNullArrayOffsetDeprecated();
        if (arr_resolved.asArray().getByValue(key_val)) |val| {
            // ★F-139c：getByValue 返回的是已 retain 的所有权值，不还就每次 isset 漏一份。
            defer val.release(runtime_allocator);
            return Value.initBool(!val.isNull());
        }
        return Value.initBool(false);
    }
    return Value.initBool(false);
}

/// ★R-339（§264 数组元素引用）：产物侧全局槽 Ref 化钩子（main.zig 模板初始化时挂载）。
///   global_vars 表是产物侧状态（nlk 生成），运行库无法直接触达——与 q4_global_lookup
///   同款的产物侧→运行库反向钩子。
pub var q4_global_make_ref_hook: ?*const fn (name: []const u8, allocator: Allocator) ?Value = null;

/// ★R-339：`[&$g]` / `$a[] =& $g`（main/全局源）——全局变量槽 Ref 化。
///   未定义变量按 PHP by-ref 语境静默 vivify 为 null（批十五口径，由产物侧实现保证）。
///   返回指向全局槽 cell 的 Ref；槽重定向后 global.get 读自动 deref、global.set 写穿。
pub fn php_global_make_ref(name_val: Value, allocator: Allocator) !Value {
    if (!name_val.isString()) return error.InvalidArgument;
    const name = name_val.asString().data;
    if (q4_global_make_ref_hook) |f| {
        if (f(name, allocator)) |v| return v;
    }
    // 钩子未挂载（不可能：init 恒挂载）或常量名冲突——诚实失败，不静默假成功
    return error.InvalidArgument;
}

/// ★R-339：多维下钻中间层数组化（`$b['new']['deep'] =& $n` / `$a['x'][] =& $m`）。
///   PHP auto-vivify 契约：中间层 null ⇒ 静默 vivify 为 []；已数组 ⇒ 直通；
///   非标量（int/string 等）⇒ "Trying to access array offset on {type}" 警告 + 原样
///   返回（后续 set/push_keep_ref deref 非数组静默拒 ⇒ 绑定不成立，与 PHP 同形）。
///   与 php_array_elem_ref_vivify 入参 Ref 支（:12536）同逻辑，独立成枚供 IR 下钻链逐层调用。
pub fn php_array_ref_vivify_middle(v: Value, allocator: Allocator) !Value {
    if (!v.isRef()) return error.InvalidArgument;
    const cell = v.asRef();
    if (cell.isArray()) return v;
    if (cell.isNull()) {
        cell.* = Value.initArray(try PHPArray.init(allocator));
        return v;
    }
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Trying to access array offset on {s}", .{phpArgTypeWord(cell.*)}) catch "Trying to access array offset";
    emitWarning(msg);
    return v;
}

/// 获取数组元素的引用（用于引用返回）
/// 参数：array, key
/// 返回：指向「已装进元素槽的引用单元」的 Ref（值形态为 Value.initRef(堆 cell)）
pub fn php_array_get_ref(arr_val: Value, key_val: Value, allocator: Allocator) !Value {
    // 解引用：跟随完整引用链，取到实际数组
    var arr_resolved = arr_val;
    if (arr_resolved.isRef()) {
        arr_resolved = derefVal(arr_resolved);
    }
    if (!arr_resolved.isArray()) return error.InvalidArgument;
    const arr = arr_resolved.asArray();
    return arrayElemRefInner(arr, key_val, allocator);
}

/// ★批次十五：by-ref 实参的数组元素引用（嵌套下钻形）——PHP auto-vivify 契约：
///   中间层槽为 null/非数组 ⇒ 原地 vivify 为 []（`byref($b['new']['deep'])` 的 $b['new'] 变数组）；
///   未定义元素不告警、静默建 null 槽。返回元素槽的稳定 Ref（装槽语义同 php_array_get_ref）。
pub fn php_array_elem_ref_vivify(arr_val: Value, key_val: Value, allocator: Allocator) !Value {
    var arr_resolved = arr_val;
    if (arr_resolved.isRef()) {
        // 中间层：Ref 槽值非数组 ⇒ vivify 为 []（写穿 cell）
        const cell = arr_resolved.asRef();
        if (!cell.isArray()) {
            cell.release(allocator);
            cell.* = Value.initArray(try PHPArray.init(allocator));
        }
        arr_resolved = cell.*;
    }
    if (!arr_resolved.isArray()) return error.InvalidArgument;
    const arr = arr_resolved.asArray();
    return arrayElemRefInner(arr, key_val, allocator);
}

fn arrayElemRefInner(arr: *PHPArray, key_val: Value, allocator: Allocator) !Value {

    const key = normalizeArrayKeyFromValue(key_val);

    // 获取或创建数组元素槽
    const slot = arr.getPtr(key) orelse blk: {
        try arr.set(allocator, key, Value.initNull());
        break :blk arr.getPtr(key).?;
    };

    // 引用装槽（复用 make_ref）：返回的 Ref 指向**稳定堆单元**而非容器槽地址。
    // 直接把 slot 指针交给调用方会在数组扩容搬迁桶数组后悬垂——写入落在已释放内存（UAF），
    // 且写不回容器。装槽后容器槽自身存 Ref，扩容只搬迁这个 Ref 值，单元地址永不变，
    // 因此也无需 has_active_refs / convertToMixed 那套「锚住槽地址」的补救。
    return make_ref(slot, allocator);
}

/// AOT-CODEGEN-012 R-138：沿继承链按声明序收集方法名（自身 → 祖先，逐类按 method_order）。
/// 同名去重保首位 ⇒ 子类覆写沿用其在自身表中的位次（PHP 函数表行为）。
/// public_only=true 供 get_class_methods（仅 public）；false 供 ReflectionClass::getMethods（全可见性）。
fn collectMethodNamesInOrder(
    meta: *const ClassMeta,
    public_only: bool,
    allocator: Allocator,
) !std.ArrayList([]const u8) {
    var out: std.ArrayList([]const u8) = .empty;
    errdefer out.deinit(allocator);
    var seen = std.StringHashMap(void).init(allocator);
    defer seen.deinit();

    var cur: ?*const ClassMeta = meta;
    while (cur) |m| {
        for (m.method_order.items) |mname| {
            if (seen.contains(mname)) continue;
            if (public_only) {
                const cm = m.methods.get(mname) orelse continue;
                if (!cm.is_public) continue;
            }
            try seen.put(mname, {});
            try out.append(allocator, mname);
        }
        cur = m.parent;
    }
    return out;
}

/// AOT-CODEGEN-012 R-138：沿继承链按声明序收集属性名（自身 → 祖先），同名去重保首位。
/// 供 ReflectionClass::getProperties（PHP 含继承属性、全可见性）。
fn collectPropertyNamesInOrder(meta: *const ClassMeta, allocator: Allocator) !std.ArrayList([]const u8) {
    var out: std.ArrayList([]const u8) = .empty;
    errdefer out.deinit(allocator);
    var seen = std.StringHashMap(void).init(allocator);
    defer seen.deinit();

    var cur: ?*const ClassMeta = meta;
    while (cur) |m| {
        for (m.property_order.items) |pname| {
            if (seen.contains(pname)) continue;
            try seen.put(pname, {});
            try out.append(allocator, pname);
        }
        cur = m.parent;
    }
    return out;
}

/// AOT-CODEGEN-012 R-138：Reflection 族只读属性面（PHP 真值实测）。
/// 一处共享支覆盖全部构造点（ReflectionClass/Method/Property/ClassConstant 共 8 个 new 站点）：
///   读 name / class ⇒ 由内部 __class_name / __method_name / __prop_name 派生；
///   其余名字 ⇒ 复刻 PHP 的 Undefined property 告警（因 __get 接管后原生告警支不再触发）。
fn reflectionRoGet(ctx: Value, args: []const Value, alloc: Allocator) anyerror!Value {
    if (!Value_isObject(ctx) or args.len == 0) return Value.initNull();
    const obj = Value_asObject(ctx);
    const pname = if (args[0].isString()) args[0].asString().data else return Value.initNull();
    const owner: []const u8 = if (obj.class_meta) |m| m.name else obj.class_name;
    const cn: []const u8 = if (obj.getPropertyDirect("__class_name")) |v| (if (v.isString()) v.asString().data else "") else "";
    const mn: []const u8 = if (obj.getPropertyDirect("__method_name")) |v| (if (v.isString()) v.asString().data else "") else "";
    const pn: []const u8 = if (obj.getPropertyDirect("__prop_name")) |v| (if (v.isString()) v.asString().data else "") else "";

    // PHP 真值：ReflectionClass->$name=类名；ReflectionMethod->$name=方法名、->$class=类名；
    // ReflectionProperty->$name=属性名、->$class=类名。
    var derived: []const u8 = "";
    if (std.mem.eql(u8, pname, "name")) {
        if (std.mem.eql(u8, owner, "ReflectionMethod")) {
            derived = mn;
        } else if (std.mem.eql(u8, owner, "ReflectionProperty")) {
            derived = pn;
        } else {
            derived = cn;
        }
    } else if (std.mem.eql(u8, pname, "class") and !std.mem.eql(u8, owner, "ReflectionClass")) {
        derived = cn;
    }

    if (derived.len == 0) {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Undefined property: {s}::${s}", .{ owner, pname }) catch
            "Undefined property";
        emitWarning(msg);
        return Value.initNull();
    }
    const s = try PHPString.init(alloc, derived);
    return Value.initString(s);
}

/// AOT-CODEGEN-012 R-138：写只读属性 ⇒ PHP ReflectionException
/// 「Cannot set read-only property ReflectionMethod::$class」（真值实测）。
fn reflectionRoSet(ctx: Value, args: []const Value, alloc: Allocator) anyerror!Value {
    if (!Value_isObject(ctx) or args.len < 2) return Value.initBool(false);
    const obj = Value_asObject(ctx);
    const owner: []const u8 = if (obj.class_meta) |m| m.name else obj.class_name;
    const pname = if (args[0].isString()) args[0].asString().data else return Value.initBool(false);
    if (std.mem.eql(u8, pname, "name") or std.mem.eql(u8, pname, "class")) {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Cannot set read-only property {s}::${s}", .{ owner, pname }) catch
            "Cannot set read-only property";
        // 必须是「置异常 + 返回异常 Value」的既有 F-9 形态（见 :19937 等），
        // 不能 `return error.X`：发射点在 `try` 之后才查 `hasException()`，
        // Zig error 会直接冒过 `try` ⇒ 绕过 catch 路由 ⇒ 实测不可捕获（门 P r10）。
        // 值本身被上层丢弃（`php_object_set` → `tryMagicSet` 只取 bool，返回 initNull），
        // 故不会形成 RUNTIME-002 G3 那类「异常对象入槽」脏写。
        return throwThrowable("ReflectionException", msg, alloc);
    }
    // 非只读名：PHP 对 Reflection* 的未知属性赋值同样落告警支，这里交回动态属性创建路径
    try obj.setProperty(pname, args[1]);
    return Value.initBool(true);
}

/// AOT-CODEGEN-012 R-138：为 Reflection 元数据挂只读属性面（三枚 meta 共用两支）
fn attachReflectionReadOnlyProps(meta: *ClassMeta) !void {
    try meta.addMethod(.{
        .name = "__get",
        .func = reflectionRoGet,
        .is_static = false,
    });
    try meta.addMethod(.{
        .name = "__set",
        .func = reflectionRoSet,
        .is_static = false,
    });
}

/// AOT-CODEGEN-012 R-138：接口列表的传递闭包判定（含接口的父接口）。`target` 传入**规范名**
/// （调用侧已经 findClass 归一 ⇒ 天然 CI，且 class_alias 的同 meta 双键亦命中）。
/// depth 上限防接口环（PHP 禁止循环继承，此处为编译器不可证明的运行时不变量兜底）。
fn interfaceListHas(ifaces: []const []const u8, target: []const u8, depth: u8) bool {
    if (depth > 16) return false;
    for (ifaces) |raw| {
        const meta = findClass(raw) orelse {
            if (std.ascii.eqlIgnoreCase(raw, target)) return true;
            continue;
        };
        if (std.mem.eql(u8, meta.name, target)) return true;
        if (interfaceListHas(meta.interfaces, target, depth + 1)) return true;
    }
    return false;
}

/// AOT-CODEGEN-012 R-138：类/接口是否实现（或继承）给定接口 —— 沿类链逐层的 interfaces 求闭包。
fn classImplementsInterfaceNamed(cmeta: *const ClassMeta, target: []const u8) bool {
    var cur: ?*const ClassMeta = cmeta;
    var depth: u8 = 0;
    while (cur) |m| : (depth += 1) {
        if (depth > 64) return false;
        if (interfaceListHas(m.interfaces, target, 0)) return true;
        cur = m.parent;
    }
    return false;
}

/// AOT-CODEGEN-012 R-138：PHP 的实参类型词（此族消息用 true/false 而非 bool）
fn phpArgTypeWord(v: Value) []const u8 {
    if (v.isBool()) return if (v.toBool()) "true" else "false";
    return valueTypeName(v);
}

fn php_get_class_methods(class_name_val: Value, allocator: Allocator) !Value {
    // PHP 签名：get_class_methods(object|string $object_or_class): array
    // 非对象且字符串未注册为类 ⇒ TypeError「must be an object or a valid class name, {type} given」
    var meta_opt: ?*const ClassMeta = null;
    if (class_name_val.isString()) {
        meta_opt = findClass(class_name_val.asString().data);
    } else if (Value_isObject(class_name_val)) {
        const obj = Value_asObject(class_name_val);
        meta_opt = obj.class_meta orelse findClass(obj.class_name);
    }
    const meta = meta_opt orelse {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "get_class_methods(): Argument #1 ($object_or_class) must be an object or" ++
                " a valid class name, {s} given",
            .{phpArgTypeWord(class_name_val)},
        ) catch "get_class_methods(): Argument #1 must be an object or a valid class name";
        return throwThrowable("TypeError", msg, allocator);
    };

    var names = try collectMethodNamesInOrder(meta, true, allocator);
    defer names.deinit(allocator);

    const res_arr = try PHPArray.init(allocator);
    for (names.items) |mname| {
        const s = try PHPString.init(allocator, mname);
        const v = Value.initString(s);
        try res_arr.push(allocator, v);
        v.release(allocator);
    }

    return Value.initArray(res_arr);
}

fn php_get_class_vars(class_name_val: Value, allocator: Allocator) !Value {
    // PHP 签名：get_class_vars(string $class): array —— 未注册类名 ⇒ TypeError（消息用**值**而非类型词）
    const display_val = blk: {
        if (class_name_val.isString()) break :blk class_name_val.asString().data;
        if (class_name_val.isNull()) break :blk "";
        if (class_name_val.isArray()) break :blk "Array";
        const s = class_name_val.toString(allocator) catch break :blk valueTypeName(class_name_val);
        break :blk s.data;
    };
    const meta_opt: ?*const ClassMeta = if (class_name_val.isString())
        findClass(class_name_val.asString().data)
    else if (Value_isObject(class_name_val)) blk: {
        const obj = Value_asObject(class_name_val);
        break :blk obj.class_meta orelse findClass(obj.class_name);
    } else null;

    const meta = meta_opt orelse {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "get_class_vars(): Argument #1 ($class) must be a valid class name, {s} given",
            .{display_val},
        ) catch "get_class_vars(): Argument #1 must be a valid class name";
        return throwThrowable("TypeError", msg, allocator);
    };

    const res_arr = try PHPArray.init(allocator);

    // PHP 真值实测口径（R-138）：先「实例属性 pass」沿链（自身→祖先），再「静态属性 pass」沿链，
    // 每趟逐类按 property_order（声明序）；仅 public。混合声明（static 在实例之前）亦成立。
    var pass: u8 = 0;
    while (pass < 2) : (pass += 1) {
        const want_static = pass == 1;
        var cur: ?*const ClassMeta = meta;
        while (cur) |m| {
            for (m.property_order.items) |pname| {
                const prop = m.properties.get(pname) orelse continue;
                if (prop.is_static != want_static) continue;
                if (!prop.is_public) continue;
                const val = if (want_static)
                    (m.static_properties.get(pname) orelse prop.default_value orelse Value.initNull())
                else
                    (prop.default_value orelse Value.initNull());
                const key_str = try PHPString.init(allocator, pname);
                try res_arr.set(allocator, ArrayKey{ .string = key_str }, val);
                key_str.release(allocator);
            }
            cur = m.parent;
        }
    }

    return Value.initArray(res_arr);
}

fn php_get_object_vars(obj_val: Value, allocator: Allocator) !Value {
    if (!Value_isObject(obj_val)) return error.InvalidArgument;
    const obj = Value_asObject(obj_val);

    const res_arr = try PHPArray.init(allocator);

    // PHP 真值实测口径（R-138）：
    //   1) 顺序 = 声明属性沿链**根→叶**（对象属性表按祖先先初始化），其后为动态属性（插入序）；
    //   2) 可见性按**调用作用域**过滤：全局/函数作用域仅 public，类方法内 private/protected 可见
    //     （复用 checkPropertyAccess，含 trait 上下文语义）。
    var printed = std.StringHashMap(void).init(allocator);
    defer printed.deinit();

    // 先把链收集成数组，再反向遍历（根→叶）
    var chain: std.ArrayList(*const ClassMeta) = .empty;
    defer chain.deinit(allocator);
    var cur: ?*const ClassMeta = obj.class_meta;
    while (cur) |m| {
        try chain.append(allocator, m);
        cur = m.parent;
    }
    var idx = chain.items.len;
    while (idx > 0) {
        idx -= 1;
        const m = chain.items[idx];
        const obj_meta = obj.class_meta orelse break;
        for (m.property_order.items) |pname| {
            if (printed.contains(pname)) continue;
            const decl = findPropertyDeclaringClass(obj_meta, pname) orelse continue;
            if (decl.prop.is_static) continue;
            if (!checkPropertyAccess(decl.class, decl.prop)) continue;
            const val = obj.properties.get(pname) orelse continue;
            try printed.put(pname, {});
            const key_str = try PHPString.init(allocator, pname);
            try res_arr.set(allocator, ArrayKey{ .string = key_str }, val);
            key_str.release(allocator);
        }
    }

    // 余下动态属性：PHP 保插入序，AOT 的 obj.properties 为 StringHashMap（无插入序）⇒
    // 单枚动态属性等值，多枚动态属性的相对序属已知残留（工单登记，需对象级插入序字段）。
    var it = obj.properties.iterator();
    while (it.next()) |entry| {
        if (printed.contains(entry.key_ptr.*)) continue;
        // 已声明但被可见性过滤掉的属性不得从动态支漏出
        if (obj.class_meta) |meta| {
            if (findPropertyDeclaringClass(meta, entry.key_ptr.*)) |decl| {
                if (!checkPropertyAccess(decl.class, decl.prop)) continue;
            }
        }
        try printed.put(entry.key_ptr.*, {});
        const key_str = try PHPString.init(allocator, entry.key_ptr.*);
        try res_arr.set(allocator, ArrayKey{ .string = key_str }, entry.value_ptr.*);
        key_str.release(allocator);
    }
    return Value.initArray(res_arr);
}

fn php_get_public_object_vars_snapshot(obj_val: Value, allocator: Allocator) !Value {
    if (!Value_isObject(obj_val)) return error.InvalidArgument;
    const obj = Value_asObject(obj_val);

    const res_arr = try PHPArray.init(allocator);
    var iter = obj.properties.iterator();
    while (iter.next()) |entry| {
        if (obj.class_meta) |meta| {
            if (meta.properties.get(entry.key_ptr.*)) |prop| {
                if (prop.is_static or !prop.is_public) continue;
            }
        }

        const key_str = try PHPString.init(allocator, entry.key_ptr.*);
        try res_arr.set(allocator, ArrayKey{ .string = key_str }, entry.value_ptr.*);
        key_str.release(allocator);
    }
    return Value.initArray(res_arr);
}

/// Go 式 select 核心（组4 验收重写）：cases = [[channel, op, ?value], ...]（op 0=recv 1=send），
/// timeout 毫秒（null 无限等，0 ≈ Go 的 default 立即返回）。
/// 就绪判定走 Channel.canRecv/canSend 非消费查询（N:1 单线程，查询与随后消费间无竞态）；
/// 多 case 就绪时均匀随机选一枚（Go pollorder 公平性对齐，取代原「迭代序第一个」的确定性偏置）；
/// 无就绪时 yieldNow 让出调度器（M1 自旋让出；真挂起唤醒属 M2；原 std.Thread.yield 忙等漏项一并修）。
/// closed channel：recv case 即就绪（返 [index, null]，Go ok=false 口径）；send case 不就绪（防选中即炸）。
fn php_select(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return error.MissingArgument;
    const cases_arg = args[0];
    if (!cases_arg.isArray()) return error.InvalidArgument;

    var timeout: ?i64 = null;
    if (args.len > 1 and !args[1].isNull()) {
        timeout = args[1].toInt();
    }

    const array = cases_arg.asArray();
    const start_time = milliTimestamp();

    var ready_list = std.ArrayListUnmanaged(usize).empty;
    defer ready_list.deinit(allocator);

    while (true) {
        // 第一遍：非消费查询收集就绪 case 下标
        ready_list.clearRetainingCapacity();
        var iter = array.elements.iterator();
        var index: usize = 0;
        while (iter.next()) |entry| : (index += 1) {
            const case_val = entry.value_ptr.*;
            if (!case_val.isArray()) continue;
            const case_arr = case_val.asArray();
            const ch_val = case_arr.get(ArrayKey{ .integer = 0 }) orelse continue;
            const op_val = case_arr.get(ArrayKey{ .integer = 1 }) orelse continue;
            if (!Value_isObject(ch_val)) continue;
            const ch_obj = Value_asObject(ch_val);
            if (ch_obj.getProperty("_ptr")) |ptr_val| {
                const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));
                const op = op_val.toInt();
                if (op == 0) {
                    if (channel.canRecv()) try ready_list.append(allocator, index);
                } else if (op == 1) {
                    if (channel.canSend()) try ready_list.append(allocator, index);
                }
            }
        }

        if (ready_list.items.len > 0) {
            // 就绪集内均匀随机（Go pollorder；用项目既有 getRandomIntRange，Zig 0.16 兼容）
            const picked = ready_list.items[getRandomIntRange(usize, 0, ready_list.items.len - 1)];
            var iter2 = array.elements.iterator();
            var idx2: usize = 0;
            while (iter2.next()) |entry| : (idx2 += 1) {
                if (idx2 != picked) continue;
                const case_val = entry.value_ptr.*;
                const case_arr = case_val.asArray();
                const ch_val = case_arr.get(ArrayKey{ .integer = 0 }).?;
                const op_val = case_arr.get(ArrayKey{ .integer = 1 }).?;
                const ch_obj = Value_asObject(ch_val);
                const ptr_val = ch_obj.getProperty("_ptr").?;
                const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));
                if (op_val.toInt() == 0) {
                    const res_arr = try PHPArray.init(allocator);
                    try res_arr.push(allocator, Value.initInt(@intCast(picked)));
                    if (channel.tryRecv()) |val| {
                        try res_arr.push(allocator, val);
                    } else {
                        // closed 空 channel：就绪因 closed，取零值（Go 的 ok=false 口径）
                        try res_arr.push(allocator, Value.initNull());
                    }
                    return Value.initArray(res_arr);
                } else {
                    const send_val = case_arr.get(ArrayKey{ .integer = 2 }) orelse Value.initNull();
                    _ = send_val.retain();
                    const ok = channel.trySend(send_val) catch |err| {
                        send_val.release(allocator);
                        // ★D-2 裁决（2026-11-09）：closed 通道的 send case 视为就绪 ⇒ 选中即抛
                        //   可捕获 Error（对齐 Go 的 panic），不再无限重扫。
                        if (err == error.ChannelClosed) {
                            return throwThrowable("Error", "send on closed channel", allocator);
                        }
                        break; // 其余错误：防御性重扫（落到 timeout/yieldNow）
                    };
                    if (ok) {
                        return Value.initInt(@intCast(picked));
                    }
                    send_val.release(allocator);
                    break; // 防御：就绪后消费未果，落到 timeout/yieldNow 重扫
                }
            }
        }

        if (timeout) |t| {
            if (milliTimestamp() - start_time >= t) {
                return Value.initNull();
            }
        }
        concurrency.yieldNow();
    }
}

// Closure::bind/bindTo 绑定的 $this 栈（支持嵌套调用）
threadlocal var closure_bound_this_stack: Value = Value.initNull();

/// 获取当前 Closure::bind 绑定的 $this（供 getGlobalVar("$this") 使用）
pub fn getClosureBoundThis() Value {
    return closure_bound_this_stack;
}

pub fn php_invoke_callable(callback: Value, args: []const Value, allocator: Allocator) !Value {
    // 引用透明：闭包自引用场景中 callback 可能是 Ref(cell)
    var actual_cb = if (callback.isRef()) callback.asRef().* else callback;

    // 多层Ref解引用：捕获的闭包可能被多次包装
    while (actual_cb.isRef()) {
        actual_cb = actual_cb.asRef().*;
    }

    if (actual_cb.isFunction()) {
        const closure = actual_cb.asFunction();
        // Closure::bind/bindTo: 如果有 bound_this，临时设置全局 $this
        if (!closure.bound_this.isNull()) {
            const prev_this = closure_bound_this_stack;
            closure_bound_this_stack = closure.bound_this;
            defer closure_bound_this_stack = prev_this;
            // 同时设置 bound_scope（bindTo 的第二个参数指定的作用域类）
            if (closure.bound_scope) |scope_meta| {
                const prev_scope = getCurrentScopeClass();
                setCurrentScopeClass(scope_meta);
                defer setCurrentScopeClass(prev_scope);
                return closure.func(actual_cb, args, allocator);
            }
            return closure.func(actual_cb, args, allocator);
        }
        // 闭包在类方法内定义时自动绑定作用域（无 bound_this 但有 bound_scope）
        if (closure.bound_scope) |scope_meta| {
            const prev_scope = getCurrentScopeClass();
            setCurrentScopeClass(scope_meta);
            defer setCurrentScopeClass(prev_scope);
            return closure.func(actual_cb, args, allocator);
        }
        return closure.func(actual_cb, args, allocator);
    }
    if (Value_isObject(actual_cb)) {
        const obj_ptr = Value_asObject(actual_cb);
        return obj_ptr.callMethod("__invoke", args) catch |err| switch (err) {
            error.MethodNotFound => return Value.initBool(false),
            else => return Value.initBool(false),
        };
    }
    if (actual_cb.isString()) {
        const func_name = actual_cb.asString().data;
        // ★P2-3：missing 分流全调用面只做一次（hook→内建→CI 下落链共享同一 norm；
        //   重复分流会二次消费 FIFO 注名 ⇒ take 空 ⇒ missing 原样漏进 handler）。
        // ★Deprecated-null（批次二十四续）：归一同样全链一次（shared_dep）——
        //   否则 hook 未命中落内建支时 null 位重复告警。
        var shared_norm: ?[]Value = null;
        defer if (shared_norm) |sn| allocator.free(sn);
        var shared_split_done = false;
        var shared_dep: ?[]Value = null;
        defer if (shared_dep) |sd| allocator.free(sd);
        var shared_dep_done = false;
        // AOT hook 优先：支持所有 AOT 注册的函数（包括内置函数分发）
        if (aot_callable_hook) |hook| {
            // ★P2-3：missing 分流（hook 覆盖用户函数直调——不入此支告警/vivify 全丢）
            shared_norm = try q4SplitMissingArgs(func_name, args, allocator);
            shared_split_done = true;
            const hook_raw = if (shared_norm) |n| n else args;
            shared_dep = try q4NormalizeBuiltinArgs(func_name, hook_raw, allocator);
            shared_dep_done = true;
            const hook_args = if (shared_dep) |d| d else hook_raw;
            if (hook(func_name, hook_args, allocator)) |result| {
                return result;
            } else |err| {
                // AOT hook 返回错误则尝试其他路径
                if (err != error.UnknownFunction) return err;
            }
        }
        if (lookupBuiltinFunction(func_name)) |func| {
            // ★Q2-b（F-41）：变量调用面 arity 真值守卫——欠参/超填 ⇒ 可捕获 ArgumentCountError
            //  （原裸 error.InvalidArgumentCount 冒顶进程死；措辞与直调面共用 php_arity_error 单一来源）。
            //   函数名 CI ⇒ 措辞用规范小写名。
            if (builtin_param_table.arityOf(func_name)) |info| {
                const given = args.len;
                if (given < info.min or (!info.has_variadic and given > info.max)) {
                    var lbuf: [64]u8 = undefined;
                    const canon: []const u8 = if (builtin_param_table.table.get(func_name) != null or func_name.len > 64)
                        func_name
                    else
                        std.ascii.lowerString(&lbuf, func_name);
                    return php_arity_error(canon, @intCast(info.min), @intCast(info.max), @intCast(given), info.has_variadic, allocator);
                }
            }
            // ★Q3 + P2-3 + Deprecated-null：missing 分流 → 入参归一（by-value Ref deref + null 弱转）共享管线。
            //   归一必要性（Ref 位/null 应警位）由 q4NormalizeBuiltinArgs 内部判定 ⇒ null 返回＝零分配直传。
            const split: ?[]Value = if (shared_split_done) shared_norm else try q4SplitMissingArgs(func_name, args, allocator);
            if (!shared_split_done) shared_norm = split;
            const eff_args = if (split) |sp| sp else args;
            const dep_norm: ?[]Value = if (shared_dep_done) shared_dep else try q4NormalizeBuiltinArgs(func_name, eff_args, allocator);
            if (!shared_dep_done) shared_dep = dep_norm;
            return func(Value.initNull(), if (dep_norm) |dn| dn else eff_args, allocator);
        }
        // §8 #6：用户函数名 CI（$f = "dyn"; $f() 跨大小写动态调用）
        if (lookupUserFunctionCI(func_name)) |func| {
            // ★P2-3：missing 分流（共享核；hook 已拦的用户函数到不了这里——CI 名义兜特例）
            const ci_norm: ?[]Value = if (shared_split_done) shared_norm else try q4SplitMissingArgs(func_name, args, allocator);
            if (!shared_split_done) shared_norm = ci_norm;
            const ci_args = if (ci_norm) |n| n else args;
            return func(Value.initNull(), ci_args, allocator);
        }
        // ★批次十六①：PHP 8.5.8 实测——未定义/未登记函数的变量调用抛**可捕获** Error：
        //   `Call to undefined function xxx()`（旧注释「warning 并返回 false」为错误描述，
        //   PHP 8 无此行为；静默 false 会吞掉全部未登记缺口）。throwThrowable 内含
        //   setException，生成码 hasException 通道接管；未捕获走既有未捕获通道 fatal。
        var ubuf: [512]u8 = undefined;
        const umsg = std.fmt.bufPrint(&ubuf, "Call to undefined function {s}()", .{func_name}) catch "Call to undefined function";
        return try throwThrowable("Error", umsg, allocator);
    }
    if (actual_cb.isArray()) {
        const arr = actual_cb.asArray();
        if (arr.elements.count() != 2) return Value.initBool(false);

        const key0 = ArrayKey{ .integer = 0 };
        const key1 = ArrayKey{ .integer = 1 };

        const val0 = arr.elements.get(key0) orelse return Value.initBool(false);
        const val1 = arr.elements.get(key1) orelse return Value.initBool(false);

        if (!val1.isString()) return Value.initBool(false);
        const method_name = val1.asString().data;

        if (Value_isObject(val0)) {
            const obj_ptr = Value_asObject(val0);
            return obj_ptr.callMethod(method_name, args) catch Value.initBool(false);
        }
        if (val0.isString()) {
            return php_call_static(val0.asString().data, method_name, args, allocator) catch Value.initBool(false);
        }
        return Value.initBool(false);
    }
    return Value.initBool(false);
}

pub fn php_args_append_spread(dest: Value, src: Value, allocator: Allocator) !Value {
    if (!dest.isArray()) {
        return throwThrowable("Error", "php_args_append_spread: destination is not an array", allocator);
    }

    // ★F-134：PHP 8 的 `...$x` 只接受 array 与 Traversable，其余抛 TypeError。
    // 旧实现把非数组交给 php_array_iter_init ⇒ 发一条 foreach 口径的 Warning 后**静默吞掉**实参（f(...5) 变 f()）。
    const unpackable = src.isArray() or (Value_isObject(src) and blk: {
        const meta = Value_asObject(src).class_meta orelse break :blk false;
        break :blk (meta.findMethod("rewind") != null and meta.findMethod("valid") != null and
            meta.findMethod("current") != null and meta.findMethod("key") != null and
            meta.findMethod("next") != null) or meta.findMethod("getIterator") != null;
    });
    if (!unpackable) {
        return throwUnpackTypeError(src, allocator);
    }

    const dest_arr = dest.asArray();
    const iter_val = try php_array_iter_init(src, allocator);
    defer _ = php_array_iter_free(iter_val, allocator) catch {};

    while ((try php_array_iter_valid(iter_val)).toBool()) {
        // ★批次十七②：字符串键 ⇒ 命名实参，键保留进参数包（PHP 8.1+ 展开语义）；
        //   整数键按位置顺序追加（键值本身丢弃，与 PHP 位置铺开一致）。
        const key_val = try php_array_iter_key(iter_val, allocator);
        defer key_val.release(allocator);
        const value = try php_array_iter_value(iter_val);
        defer value.release(allocator);
        if (key_val.isString()) {
            const ks = key_val.asString();
            _ = ks.retain();
            try dest_arr.set(allocator, .{ .string = ks }, value);
        } else {
            try dest_arr.push(allocator, value);
        }

        const next_iter = try php_array_iter_next(iter_val);
        next_iter.release(allocator);
    }
    return dest;
}

/// ★F-134b（R-328）：`?->` 空接收者短路版解包。PHP 实测 `$x=null; $x?->foo(...5)` ⇒ NULL
/// 且实参完全不求值；发射器在 safe 调用路径上把本函数替换 php_args_append_spread，
/// 接收者非对象时静默空转（不产生 TypeError），调用本体随后短路为 NULL。
pub fn php_args_append_spread_safe(dest: Value, src: Value, obj_val: Value, allocator: Allocator) !Value {
    if (!Value_isObject(obj_val)) return dest;
    return php_args_append_spread(dest, src, allocator);
}

/// ★F-134b（R-328）：方法调用「解析 vs 实参解包」顺序守卫。
/// PHP 8.5.8 实测顺序：① 方法名字符串检查 → ② 接收者检查 → ③ 方法解析（含 __call）
/// → ④ 实参求值（解包 TypeError）。发射器在构建实参数组（php_args_append_spread
/// 可能抛 TypeError）之前调用本函数，使「未定义方法 Error」先于解包错误抛出。
/// nullsafe=true（`?->`）时：接收者非对象 ⇒ 静默返回（短路，不查方法）；
/// 接收者是对象时仍按 ③ 做解析检查（`$o?->nope(...)` ⇒ Error，PHP 实测）。
pub fn php_method_call_precheck(obj_val: Value, method_name_val: Value, nullsafe_val: Value, allocator: Allocator) !Value {
    const nullsafe = nullsafe_val.toBool();
    if (!method_name_val.isString()) {
        return throwThrowable("Error", "Method name must be a string", allocator);
    }
    const method_name = method_name_val.asString().data;
    if (!Value_isObject(obj_val)) {
        if (nullsafe) return Value.initNull();
        var nbuf: [256]u8 = undefined;
        const nmsg = std.fmt.bufPrint(&nbuf, "Call to a member function {s}() on {s}", .{
            method_name, phpArgTypeWord(obj_val),
        }) catch "Call to a member function on a non-object";
        return throwThrowable("Error", nmsg, allocator);
    }
    const obj = Value_asObject(obj_val);
    const meta = obj.class_meta orelse return Value.initNull(); // 内部对象无 meta：交调用本体
    if (meta.findMethodLookup(method_name) != null) return Value.initNull();
    if (meta.findMethodLookup("__call") != null) return Value.initNull();
    // Closure 的方法表在 Closure meta（__invoke/Closure::call 等由 php_object_call 特例分发）
    if (std.mem.eql(u8, meta.name, "Closure")) return Value.initNull();
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Call to undefined method {s}::{s}()", .{ meta.name, method_name }) catch
        "Call to undefined method";
    return throwThrowable("Error", msg, allocator);
}

/// ★批次十七②：命名实参包信标类名（未注册 ⇒ 用户态 `new` 不到，不可伪造碰撞）。
///   展开（...）里的字符串键在 PHP 8.1+ 是命名实参；调用 ABI 是 `[]const Value` 切片（不带键），
///   命名包只能以信标对象携带穿过切片通道，被调方变参收集器拆信标并保键合并。
const NAMED_PACK_CLASS = "Zig\\NamedArgsPack";

/// 把「命名实参包」（关联数组）包成信标对象
pub fn php_named_pack(pack: Value, allocator: Allocator) !Value {
    const obj = try PHPObject.init(allocator, NAMED_PACK_CLASS);
    const v = Value_initObject(obj);
    try obj.setProperty("pack", pack);
    return v;
}

/// 拆信标：是命名包 ⇒ 返回包数组；否则 null
pub fn php_namedPackUnwrap(v: Value) ?Value {
    if (!Value_isObject(v)) return null;
    const obj = Value_asObject(v);
    if (!std.mem.eql(u8, obj.class_name, NAMED_PACK_CLASS)) return null;
    return obj.getProperty("pack");
}

/// 命名包并入变参收集数组：字符串键保留，整数键防御性位置追加
pub fn php_namedPackMergeInto(dest: *PHPArray, pack: Value, allocator: Allocator) !void {
    if (!pack.isArray()) return;
    const arr = pack.asArray();
    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        switch (entry.key_ptr.*) {
            .integer => try dest.push(allocator, entry.value_ptr.*),
            .string => |ks| {
                _ = ks.retain();
                try dest.set(allocator, .{ .string = ks }, entry.value_ptr.*);
            },
        }
    }
}

/// ★批次十八①：直调命名实参重复填充（PHP 8.5.8 实测措辞；发射点在实参全部求值后、调用前）
pub fn php_throw_named_overwrite(name: Value) !Value {
    const n = if (name.isString()) name.asString().data else "";
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Named parameter ${s} overwrites previous argument", .{n}) catch "Named parameter overwrites previous argument";
    return throwThrowable("Error", msg, runtime_allocator);
}

/// ★批次十八①：直调命名实参未知名且无变参出口（PHP 8.5.8 实测措辞）
pub fn php_throw_unknown_named(name: Value) !Value {
    const n = if (name.isString()) name.asString().data else "";
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{n}) catch "Unknown named parameter";
    return throwThrowable("Error", msg, runtime_allocator);
}

/// ★Q2-a/b（F-41 甲型）：内建 arity 真值守卫的运行侧（直调编译期发射点 + 变量调用分发共用）。
///   措辞（PHP 8.5.8 实测 K4/K9/K13）：欠参 `expects exactly R`（无可选且非变参）/ `at least R`；
///   超填 `expects exactly T` / `at most T`；单复数 argument(s) 按数。
///   返回约定＝本族通道惯例「**异常 Value 正常返回 + pending 旗标**」（生成码在调用后走
///   hasException 路由；Zig error 通道会绕过局部 catch——批次十九②实测钉死）。
pub fn php_arity_error(name: []const u8, min: i64, max: i64, given: i64, has_variadic: bool, allocator: Allocator) Value {
    var buf: [320]u8 = undefined;
    const msg = if (given < min) blk: {
        const exact = (!has_variadic and min == max);
        const word: []const u8 = if (exact) "exactly" else "at least";
        const plural: []const u8 = if (min == 1) "" else "s";
        break :blk std.fmt.bufPrint(&buf, "{s}() expects {s} {d} argument{s}, {d} given", .{ name, word, min, plural, given }) catch "expects more arguments";
    } else blk: {
        const word: []const u8 = if (min == max) "exactly" else "at most";
        const plural: []const u8 = if (max == 1) "" else "s";
        break :blk std.fmt.bufPrint(&buf, "{s}() expects {s} {d} argument{s}, {d} given", .{ name, word, max, plural, given }) catch "expects fewer arguments";
    };
    return throwThrowable("ArgumentCountError", msg, allocator) catch Value.initNull();
}

/// ★Q2-c：用户函数/方法欠参（位置通道）的 ArgumentCountError（PHP 8.5.8 实测措辞）。
///   消息内嵌调用点 file/line（运行期 src_file/src_line＝调用语句位置，与 PHP「N passed in F on line L」同位）。
///   exactly＝无可选且非变参；否则 at least。返回约定同 php_arity_error（异常值+pending）。
pub fn php_userfn_arity_too_few(display_name: []const u8, given: i64, required: i64, total: i64, has_variadic: bool, allocator: Allocator) Value {
    const word: []const u8 = if (!has_variadic and required == total) "exactly" else "at least";
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Too few arguments to function {s}(), {d} passed in {s} on line {d} and {s} {d} expected", .{
        display_name, given, src_file, src_line, word, required,
    }) catch "Too few arguments";
    return throwThrowable("ArgumentCountError", msg, allocator) catch Value.initNull();
}

/// ★Q2-c：编译期直调命名面的欠参助手（Value 形参版，供 IR .call 发射；措辞同 php_userfn_arity_too_few）
pub fn php_arity_too_few_v(name: Value, given: Value, required: Value, total: Value, variadic: Value) !Value {
    const n = if (name.isString()) name.asString().data else "?";
    return php_userfn_arity_too_few(n, given.toInt(), required.toInt(), total.toInt(), variadic.toBool(), runtime_allocator);
}

/// ★Q2-c：必填洞（命名跳过必填）措辞——`{name}(): Argument #i ($p) not passed`（PHP 8.5.8 实测）
pub fn php_arity_not_passed_v(name: Value, index: Value, pname: Value) !Value {
    const n = if (name.isString()) name.asString().data else "?";
    const p = if (pname.isString()) pname.asString().data else "?";
    var buf: [320]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "{s}(): Argument #{d} (${s}) not passed", .{ n, index.toInt(), p }) catch "required argument not passed";
    return throwThrowable("ArgumentCountError", msg, runtime_allocator) catch Value.initNull();
}

pub fn php_invoke_callable_args_array(callback: Value, args_array: Value, allocator: Allocator) !Value {
    if (!args_array.isArray()) {
        // 常规入口由 php_call_user_func_array 先审查（带函数专有措辞）；此处兜内部调用方。
        return throwUnpackTypeError(args_array, allocator);
    }

    const arr = args_array.asArray();
    // ★批次十七②：包含字符串键 ⇒ 命名实参通道（PHP 8.1+ 展开/call_user_func_array 语义）
    if (arr.hasStringKeys()) return php_invoke_callable_named_pack(callback, arr, allocator);

    const max_count: usize = @intCast(arr.next_index);
    const tmp_args = try allocator.alloc(Value, max_count);
    defer allocator.free(tmp_args);

    var used: usize = 0;
    var i: usize = 0;
    while (i < max_count) : (i += 1) {
        const key = ArrayKey{ .integer = @intCast(i) };
        // ★R-339（§264 数组元素引用）：保留 Ref 元素——Q3 协议「数组元素是引用 ⇒
        //   by-ref 位直通写回」（q4NormalizeBuiltinArgs :235）。arr.get 读出即解引用
        //   （值消费路径 :3093），会把 [&$v] 的 Ref 在收集时剥成纯值 ⇒ 下游误判
        //   "must be passed by reference, value given" 警告断链。getPtr 取原始槽。
        if (arr.getPtr(key)) |slot| {
            tmp_args[used] = slot.*;
            _ = tmp_args[used].retain();
            used += 1;
        }
    }
    return php_invoke_callable(callback, tmp_args[0..used], allocator);
}

/// ★批次十八①：命名绑定共享核心（函数/方法/静态三路复用；PHP 8.5.8 实测语义）。
///   位置值按序填声明形参槽（未填＝missing 哨兵，被调 prologue 补默认值）→ 命名按名绑
///  （重复填充＝`Named parameter $x overwrites previous argument`）→ 未知名：变参收信标包
///  （保字符串键）/ 非变参 `Unknown named parameter $x`。位置余量尾随、信标永远最后。
const NamedBindOut = struct {
    final_args: []Value,
    marker: ?Value,
    fn deinit(self: NamedBindOut, allocator: Allocator) void {
        allocator.free(self.final_args);
        // 信标必须活到调用返回——defer 挂调用方函数级（挂 if 块级会在调用前 release ⇒ use-after-free）
        if (self.marker) |m| m.release(allocator);
    }
};

fn phpBindNamedArgs(
    positional: []const Value,
    named_keys: []const *PHPString,
    named_vals: []const Value,
    param_names: []const []const u8,
    variadic_index: u16,
    required_params: u16,
    display_name: []const u8,
    allocator: Allocator,
) !NamedBindOut {
    const n_declared: u16 = if (variadic_index != 0xFFFF) variadic_index else @as(u16, @intCast(param_names.len));
    const slots = try allocator.alloc(Value, n_declared);
    defer allocator.free(slots);
    const filled = try allocator.alloc(bool, n_declared);
    defer allocator.free(filled);
    for (slots, 0..) |*s, idx| {
        s.* = Value.initMissing();
        filled[idx] = false;
    }

    var extra_positional = std.ArrayListUnmanaged(Value).empty;
    defer extra_positional.deinit(allocator);
    var pack: ?Value = null; // 变参命名包（懒建）
    defer if (pack) |p| p.release(allocator);

    for (positional, 0..) |v, pi| {
        if (pi < n_declared) {
            slots[pi] = v;
            filled[pi] = true;
        } else {
            try extra_positional.append(allocator, v);
        }
    }

    for (named_keys, named_vals) |nk, nv| {
        const name = nk.data;
        var hit: ?u16 = null;
        for (param_names[0..n_declared], 0..) |pn, idx| {
            if (std.mem.eql(u8, pn, name)) {
                hit = @intCast(idx);
                break;
            }
        }
        if (hit) |hi| {
            if (filled[hi]) {
                var buf: [256]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Named parameter ${s} overwrites previous argument", .{name}) catch "Named parameter overwrites previous argument";
                // 异常惯例：throwThrowable 设 pending + 返回异常 Value（setException 已持有份额，
                // 本地份额 release 配平）；控制流用 error.RuntimeError（生成码 hasException 路由同款）。
                const ex = throwThrowable("Error", msg, allocator) catch |e| return e;
                ex.release(allocator);
                return error.RuntimeError;
            }
            slots[hi] = nv;
            filled[hi] = true;
        } else if (variadic_index != 0xFFFF) {
            if (pack == null) pack = Value.initArray(try PHPArray.init(allocator));
            _ = nk.retain();
            try pack.?.asArray().set(allocator, .{ .string = nk }, nv);
        } else {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{name}) catch "Unknown named parameter";
            const ex = throwThrowable("Error", msg, allocator) catch |e| return e;
            ex.release(allocator);
            return error.RuntimeError;
        }
    }

    var final_args = std.ArrayListUnmanaged(Value).empty;
    errdefer final_args.deinit(allocator);

    // ★Q2-c：必填洞检（PHP 8.5.8 实测分流：洞位后有已填 ⇒ `Argument #i ($x) not passed`；
    //   纯尾部短 ⇒ `Too few arguments ... N passed ... exactly|at least R expected`）
    {
        var last_filled: i64 = -1;
        for (filled, 0..) |f, i| {
            if (f) last_filled = @intCast(i);
        }
        var first_missing: ?usize = null;
        const req_n: usize = @min(required_params, n_declared);
        for (0..req_n) |i| {
            if (!filled[i]) {
                first_missing = i;
                break;
            }
        }
        if (first_missing) |mi| {
            const given = positional.len + named_vals.len;
            if (last_filled > @as(i64, @intCast(mi))) {
                var buf: [320]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "{s}(): Argument #{d} (${s}) not passed", .{ display_name, mi + 1, param_names[mi] }) catch "required argument not passed";
                const ex = throwThrowable("ArgumentCountError", msg, allocator) catch |e| return e;
                ex.release(allocator);
                return error.RuntimeError;
            }
            _ = php_userfn_arity_too_few(display_name, @intCast(given), required_params, n_declared, variadic_index != 0xFFFF, allocator);
            return error.RuntimeError;
        }
    }

    try final_args.appendSlice(allocator, slots);
    try final_args.appendSlice(allocator, extra_positional.items);
    var marker: ?Value = null;
    if (pack) |p| {
        marker = try php_named_pack(p, allocator);
        try final_args.append(allocator, marker.?);
    }
    return .{ .final_args = try final_args.toOwnedSlice(allocator), .marker = marker };
}

/// 拆分实参数组：位置（整数键按出现序）/ 命名（字符串键按出现序）
fn splitPositionalNamed(
    arr: *PHPArray,
    positional: *std.ArrayListUnmanaged(Value),
    named_keys: *std.ArrayListUnmanaged(*PHPString),
    named_vals: *std.ArrayListUnmanaged(Value),
    allocator: Allocator,
) !void {
    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        switch (entry.key_ptr.*) {
            .integer => try positional.append(allocator, entry.value_ptr.*),
            .string => |ks| {
                try named_keys.append(allocator, ks);
                try named_vals.append(allocator, entry.value_ptr.*);
            },
        }
    }
}

/// ClassMethod 的变参下标（param_variadic 平行数组扫 true；无 ⇒ 0xFFFF）
fn methodVariadicIndex(m: *const ClassMethod) u16 {
    for (m.param_variadic, 0..) |v, i| {
        if (v) return @intCast(i);
    }
    return 0xFFFF;
}

/// 数组通道 ⇒ 共享绑定核心（方法/静态两路复用）
fn phpBindNamedValueArray(arr: *PHPArray, param_names: []const []const u8, variadic_index: u16, required_params: u16, display_name: []const u8, allocator: Allocator) !NamedBindOut {
    var positional = std.ArrayListUnmanaged(Value).empty;
    defer positional.deinit(allocator);
    var named_keys = std.ArrayListUnmanaged(*PHPString).empty;
    defer named_keys.deinit(allocator);
    var named_vals = std.ArrayListUnmanaged(Value).empty;
    defer named_vals.deinit(allocator);
    try splitPositionalNamed(arr, &positional, &named_keys, &named_vals, allocator);
    return phpBindNamedArgs(positional.items, named_keys.items, named_vals.items, param_names, variadic_index, required_params, display_name, allocator);
}

/// ★批次十七②：命名实参绑定器（PHP 8.5.8 实测语义）。批次十八①起绑定逻辑下沉共享核心
///   phpBindNamedArgs；本函数只留「回调形态 → 形参元数据」解析。
///   内建函数与本族方法（"Class::m"/数组形回调）无运行期形参名表 ⇒ 命名项显式抛
///   `Unknown named parameter`（PHP 对内建按名绑定，此为本族能力边界的**响亮**口径，登记在案）。
fn php_invoke_callable_named_pack(callback: Value, arr: *PHPArray, allocator: Allocator) !Value {
    // 1) 切分：位置值（整数键按出现序）与命名项（字符串键按出现序）
    var positional = std.ArrayListUnmanaged(Value).empty;
    defer positional.deinit(allocator);
    var named_keys = std.ArrayListUnmanaged(*PHPString).empty;
    defer named_keys.deinit(allocator);
    var named_vals = std.ArrayListUnmanaged(Value).empty;
    defer named_vals.deinit(allocator);
    try splitPositionalNamed(arr, &positional, &named_keys, &named_vals, allocator);

    // 2) 取被调形参元数据（用户函数经注册表 CI 查；闭包自带同构元数据）
    var param_names: []const []const u8 = &.{};
    var variadic_index: u16 = 0xFFFF;
    var required_params: u16 = 0;
    var display_name: []const u8 = "{closure}";
    var resolvable = false;
    if (callback.isString()) {
        const name = callback.asString().data;
        if (std.mem.indexOf(u8, name, "::") == null) {
            if (lookupUserFunctionCI(name) != null) {
                if (function_meta_registry) |*reg| {
                    var reg_it = reg.iterator();
                    while (reg_it.next()) |e| {
                        if (std.ascii.eqlIgnoreCase(e.key_ptr.*, name)) {
                            param_names = e.value_ptr.param_names;
                            variadic_index = e.value_ptr.variadic_index;
                            required_params = e.value_ptr.required_params;
                            display_name = e.key_ptr.*;
                            resolvable = true;
                            break;
                        }
                    }
                }
            }
            // 未知名不在用户表 ⇒ 可能是内建/静态方法/未知——统一走下方 !resolvable 响亮报错
        }
    } else if (callback.isFunction()) {
        const cl = callback.asFunction();
        param_names = cl.param_names;
        variadic_index = cl.variadic_index;
        required_params = cl.required_params;
        resolvable = true;
    }

    if (!resolvable) {
        // ★批次十九①：内建函数 ⇒ 反射形参名表真绑定（K1-K17 真值；BLT 边界据实销账）
        if (callback.isString()) {
            const name = callback.asString().data;
            if (std.mem.indexOf(u8, name, "::") == null) {
                if (lookupBuiltinFunction(name) != null) {
                    return phpInvokeBuiltinNamed(name, positional.items, named_keys.items, named_vals.items, allocator);
                }
                // PHP 顺序：函数解析先于命名绑定 ⇒ 用户表/内建表均无 ⇒ 交原通道报 undefined function（而非 Unknown named）
                if (lookupUserFunctionCI(name) == null) {
                    return php_invoke_callable(callback, positional.items, allocator);
                }
            }
        }
        // 静态方法字符串/数组形回调：有命名项 ⇒ 响亮报错（能力边界，登记在案）
        if (named_keys.items.len > 0) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{named_keys.items[0].data}) catch "Unknown named parameter";
            return try throwThrowable("Error", msg, allocator);
        }
        // 纯位置（理论到不了：hasStringKeys 已保证有命名项）兜底走原通道
        return php_invoke_callable(callback, positional.items, allocator);
    }

    // 3) 共享核心绑定 → 调用（final_args 切片/beacon 的所有权随 NamedBindOut，活到调用返回）
    const bind = try phpBindNamedArgs(positional.items, named_keys.items, named_vals.items, param_names, variadic_index, required_params, display_name, allocator);
    defer bind.deinit(allocator);
    return php_invoke_callable(callback, bind.final_args, allocator);
}

/// ★批次十九①：内建函数命名实参绑定（PHP 8.5.8 实测口径；形参表＝反射自动导出，禁手抄）。
///   真值要点（probe_b19_truth*.php）：
///   - 形参名大小写敏感（K12）、函数名 CI（表键小写，此处折叠查）；
///   - 重复填充 ⇒ Error `Named parameter $x overwrites previous argument`（K3）；
///   - 未知名：非变参 ⇒ Error `Unknown named parameter $x`（K2）；变参内建 ⇒
///     ArgumentCountError `{name}() does not accept unknown named parameters`（K6/K14，变参不收命名）；
///   - 命名指向 by-ref 形参 ⇒ 响亮 Error 边界（defer-12 写回通道不存在，不发明兜底；K7 的 PHP 行为是写回）；
///   - 缺必填：given < required ⇒ ArgumentCountError `{name}() expects exactly R argument(s), P given`
///     （无可选且非变参 ⇒ exactly，否则 at least；K4）；given ≥ required 但必填有洞 ⇒
///     `{name}(): Argument #i ($name) not passed`（K5b）；
///   - 位置超填（非变参）⇒ `expects exactly T`（无可选）/ `at most T`（K13）；变参位置溢出正常尾随（K15）；
///   - 可选缺省：表内默认值物化（null/bool/int/float/str）；.unknown（如实标注：不可反射）⇒
///     尾部可截断则截（包装器自带缺省接管），中段不可位置表达 ⇒ 响亮 Error 边界。
fn phpInvokeBuiltinNamed(name: []const u8, positional: []const Value, named_keys: []const *PHPString, named_vals: []const Value, allocator: Allocator) !Value {
    // 表键小写（K12：函数名 CI、形参名大小写敏感）——≤64 栈缓冲，同 lookupBuiltinFunction 折叠口径
    var lbuf: [64]u8 = undefined;
    var canon: []const u8 = name;
    const params = builtin_param_table.table.get(name) orelse blk: {
        if (name.len > 64) break :blk null;
        canon = std.ascii.lowerString(&lbuf, name);
        break :blk builtin_param_table.table.get(canon);
    };
    const ps = params orelse {
        // 表全量 2143 覆盖内建全集，理论不到；防御维持登记边界
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{if (named_keys.len > 0) named_keys[0].data else ""}) catch "Unknown named parameter";
        return try throwThrowable("Error", msg, allocator);
    };
    // 报错文案用规范名（PHP 内建名注册即小写；`STR_REPEAT()` 的措辞仍为 str_repeat()）
    const name_c = canon;

    var has_variadic = false;
    var required: usize = 0;
    var decl_total: usize = 0;
    for (ps) |p| {
        if (p.variadic) {
            has_variadic = true;
        } else {
            decl_total += 1;
            if (!p.optional) required += 1;
        }
    }

    // 声明槽位（变参不占位）；decl_of[di] = 形参表下标
    const slots = try allocator.alloc(Value, decl_total);
    defer allocator.free(slots);
    const filled = try allocator.alloc(bool, decl_total);
    defer allocator.free(filled);
    const decl_of = try allocator.alloc(usize, decl_total);
    defer allocator.free(decl_of);
    {
        var di: usize = 0;
        for (ps, 0..) |p, pi| {
            if (p.variadic) continue;
            slots[di] = Value.initMissing();
            filled[di] = false;
            decl_of[di] = pi;
            di += 1;
        }
    }

    var extra = std.ArrayListUnmanaged(Value).empty;
    defer extra.deinit(allocator);
    for (positional, 0..) |v, pi| {
        if (pi < decl_total) {
            slots[pi] = v;
            filled[pi] = true;
        } else {
            try extra.append(allocator, v);
        }
    }

    for (named_keys, named_vals) |nk, nv| {
        const nname = nk.data;
        var hit_di: ?usize = null;
        var di: usize = 0;
        for (ps) |p| {
            if (p.variadic) continue;
            const cur = di;
            di += 1;
            if (std.mem.eql(u8, p.name, nname)) {
                hit_di = cur;
                break;
            }
        }
        if (hit_di == null) {
            if (has_variadic) {
                var buf: [256]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "{s}() does not accept unknown named parameters", .{name_c}) catch "does not accept unknown named parameters";
                return try throwThrowable("ArgumentCountError", msg, allocator);
            }
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{nname}) catch "Unknown named parameter";
            return try throwThrowable("Error", msg, allocator);
        }
        const di2 = hit_di.?;
        if (filled[di2]) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Named parameter ${s} overwrites previous argument", .{nname}) catch "Named parameter overwrites previous argument";
            return try throwThrowable("Error", msg, allocator);
        }
        if (ps[decl_of[di2]].by_ref) {
            // ★Q3：by-ref 命名命中——Ref ⇒ 直通写回（PHP R5 真值）；非 Ref ⇒ PHP 实测警告 +
            //   隔离 Ref 槽（写回丢弃、包装器不重复告警；批十九①的 Error 边界按真值改正）
            if (nv.isRef()) {
                slots[di2] = nv;
            } else {
                q3WarnByRefValue(name_c, di2 + 1, nname);
                slots[di2] = try php_make_ref_from_value(nv);
            }
        } else {
            slots[di2] = nv;
        }
        filled[di2] = true;
    }

    const provided = positional.len + named_vals.len;

    // 缺必填：given 口径＝用户实参总数（命名亦计，K4）
    var missing_req: ?usize = null;
    for (filled, 0..) |f, di| {
        if (!f and !ps[decl_of[di]].optional) {
            missing_req = di;
            break;
        }
    }
    if (missing_req) |di| {
        if (provided < required) {
            const word: []const u8 = if (!has_variadic and required == decl_total) "exactly" else "at least";
            const plural: []const u8 = if (required == 1) "" else "s";
            var buf: [320]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "{s}() expects {s} {d} argument{s}, {d} given", .{ name_c, word, required, plural, provided }) catch "expects more arguments";
            return try throwThrowable("ArgumentCountError", msg, allocator);
        }
        const p = ps[decl_of[di]];
        var buf: [320]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "{s}(): Argument #{d} (${s}) not passed", .{ name_c, di + 1, p.name }) catch "required argument not passed";
        return try throwThrowable("ArgumentCountError", msg, allocator);
    }

    // 位置超填（非变参）：K13/K9
    if (!has_variadic and extra.items.len > 0) {
        const word: []const u8 = if (required == decl_total) "exactly" else "at most";
        const plural: []const u8 = if (decl_total == 1) "" else "s";
        var buf: [320]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "{s}() expects {s} {d} argument{s}, {d} given", .{ name_c, word, decl_total, plural, provided }) catch "expects fewer arguments";
        return try throwThrowable("ArgumentCountError", msg, allocator);
    }

    // 可选缺省物化：尾部 unknown 截断（包装器自带缺省接管）；中段 unknown 不可位置表达 ⇒ 响亮边界。
    // by-ref 未填位不截断（隔离 Ref 槽：写穿至隔离槽＝不写回、不告警）
    var final_len = decl_total;
    while (final_len > 0 and !filled[final_len - 1] and !ps[decl_of[final_len - 1]].by_ref and ps[decl_of[final_len - 1]].default.kind == .unknown) final_len -= 1;

    var final = std.ArrayListUnmanaged(Value).empty;
    defer final.deinit(allocator);
    for (0..final_len) |di| {
        if (filled[di]) {
            try final.append(allocator, slots[di]);
            continue;
        }
        const p = ps[decl_of[di]];
        if (p.by_ref) {
            // 未提供的 by-ref 可选形参 ⇒ 隔离 Ref 槽（包装器写穿至隔离槽＝不写回、不告警）
            try final.append(allocator, try php_make_ref_from_value(Value.initNull()));
            continue;
        }
        switch (p.default.kind) {
            .none => unreachable, // 必填洞已在上方拦截
            .unknown => {
                var buf: [320]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "{s}(): default value of ${s} is not reflectable (AOT boundary)", .{ name_c, p.name }) catch "default value not reflectable";
                return try throwThrowable("Error", msg, allocator);
            },
            .null_ => try final.append(allocator, Value.initNull()),
            .boolean => try final.append(allocator, Value.initBool(p.default.b)),
            .int => try final.append(allocator, Value.initInt(p.default.i)),
            .float => try final.append(allocator, Value.initFloat(p.default.f)),
            .str => try final.append(allocator, Value.initString(try PHPString.init(allocator, p.default.s))),
        }
    }
    // 变参内建：位置余量尾随（K15）
    if (has_variadic) try final.appendSlice(allocator, extra.items);

    const cb = Value.initString(try PHPString.init(allocator, canon));
    defer cb.release(allocator);
    return php_invoke_callable(cb, final.items, allocator);
}

/// Closure::bind / $closure->bindTo — 创建新闭包并绑定 $this 和作用域
pub fn php_closure_bind(closure_val: Value, new_this: Value, scope_val: Value) !Value {
    if (!closure_val.isFunction()) return Value.initNull();
    const orig = closure_val.asFunction();

    // PHP: Cannot bind an instance to a static closure → warning + return null
    if (orig.is_static and !new_this.isNull()) {
        fileWriteAll(2, "PHP Warning:  Cannot bind an instance to a static closure\n");
        return Value.initNull();
    }

    const bound_this = if (orig.is_static or new_this.isNull()) Value.initNull() else brk: {
        _ = new_this.retain();
        break :brk new_this;
    };

    const bound_scope: ?*const ClassMeta = blk: {
        if (scope_val.isNull()) break :blk orig.bound_scope;
        if (scope_val.isString()) {
            const class_name = scope_val.asString().data;
            if (std.mem.eql(u8, class_name, "static")) break :blk orig.bound_scope;
            if (findClass(class_name)) |meta| break :blk meta;
        }
        break :blk orig.bound_scope;
    };

    const new_closure = try allocPHPClosure(runtime_allocator);
    const caps = try runtime_allocator.alloc(Value, orig.captures.len);
    @memcpy(caps, orig.captures);
    for (caps) |c| {
        _ = c.retain();
    }

    new_closure.* = .{
        .func = orig.func,
        .captures = caps,
        .ref_count = 1,
        .gc_info = .{},
        .allocator = runtime_allocator,
        .param_count = orig.param_count,
        .required_params = orig.required_params,
        // AOT-CODEGEN-012 F-12b：bindTo/bind 派生闭包必须保留形参名
        //（PHPClosure 新字段有默认值 &.{} ⇒ 漏写就是静默丢名字，ReflectionFunction 退回 param{i}）
        .param_names = orig.param_names,
        // ★F-155：bind 派生闭包同样保留默认值元数据（否则反射 getDefaultValue 静默退化）
        .param_default_values = orig.param_default_values,
        .param_default_known = orig.param_default_known,
        .param_default_factories = orig.param_default_factories,
        .variadic_index = orig.variadic_index,
        .bound_this = bound_this,
        .bound_scope = bound_scope,
        .is_static = orig.is_static or new_this.isNull(),
    };

    alloc_counters.php_closure_objects += 1;
    alloc_counters.php_closure_live_objects += 1;
    alloc_counters.php_closure_peak_live_objects = @max(
        alloc_counters.php_closure_peak_live_objects,
        alloc_counters.php_closure_live_objects,
    );

    return Value.initFunction(new_closure);
}

/// Closure::call($closure, $newThis, ...$args) — 临时绑定 $this 并调用
/// PHP 语义：Closure::call 自动将作用域设为 $newThis 的类，允许访问 private/protected 成员
pub fn php_closure_call(closure_val: Value, new_this: Value, args_array: Value, allocator: Allocator) !Value {
    // Closure::call 将 scope 设为 new_this 的类
    var scope_val = Value.initNull();
    var created_scope = false;
    if (Value_isObject(new_this)) {
        const obj = Value_asObject(new_this);
        if (obj.class_meta) |meta| {
            scope_val = Value.initString(try PHPString.init(allocator, meta.name));
            created_scope = true;
        }
    }
    defer if (created_scope) scope_val.release(allocator);
    const bound = try php_closure_bind(closure_val, new_this, scope_val);
    defer bound.release(allocator);
    return php_invoke_callable_args_array(bound, args_array, allocator);
}

pub fn php_object_call_safe_args_array(obj_val: Value, method_name_val: Value, args_array: Value, allocator: Allocator) !Value {
    if (!Value_isObject(obj_val)) {
        return Value.initNull();
    }
    // 实测：`$x=null; $x?->$m()` 短路为 NULL（不查方法名）；但接收者是对象时非字符串方法名抛 Error。
    if (!method_name_val.isString()) {
        return throwThrowable("Error", "Method name must be a string", allocator);
    }
    if (!args_array.isArray()) {
        return throwUnpackTypeError(args_array, allocator);
    }

    const arr = args_array.asArray();
    // ★批次十八①：含字符串键 ⇒ 命名绑定通道（`?->` 非空接收者与 `->` 同语义）
    if (arr.hasStringKeys()) {
        return callObjectMethodNamedChecked(obj_val, method_name_val.asString().data, arr, allocator);
    }
    const max_count: usize = @intCast(arr.next_index);
    const tmp_args = try allocator.alloc(Value, max_count);
    defer allocator.free(tmp_args);

    var used: usize = 0;
    var i: usize = 0;
    while (i < max_count) : (i += 1) {
        const key = ArrayKey{ .integer = @intCast(i) };
        if (arr.get(key)) |v| {
            tmp_args[used] = v;
            used += 1;
        }
    }

    return php_object_call(obj_val, method_name_val.asString().data, tmp_args[0..used]);
}

pub fn php_object_call_args_array(obj_val: Value, method_name_val: Value, args_array: Value, allocator: Allocator) !Value {
    // 实测（$x=null; $m=1; $x->$m()）：方法名检查先于接收者检查。
    if (!method_name_val.isString()) {
        return throwThrowable("Error", "Method name must be a string", allocator);
    }
    if (!Value_isObject(obj_val)) {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Call to a member function {s}() on {s}", .{
            method_name_val.asString().data, phpArgTypeWord(obj_val),
        }) catch "Call to a member function on a non-object";
        return throwThrowable("Error", msg, allocator);
    }
    if (!args_array.isArray()) {
        return throwUnpackTypeError(args_array, allocator);
    }

    const arr = args_array.asArray();
    // ★批次十八①：含字符串键 ⇒ 命名绑定通道（`->` 展开/命名实参）
    if (arr.hasStringKeys()) {
        return callObjectMethodNamedChecked(obj_val, method_name_val.asString().data, arr, allocator);
    }
    const max_count: usize = @intCast(arr.next_index);
    const tmp_args = try allocator.alloc(Value, max_count);
    defer allocator.free(tmp_args);

    var used: usize = 0;
    var i: usize = 0;
    while (i < max_count) : (i += 1) {
        const key = ArrayKey{ .integer = @intCast(i) };
        if (arr.get(key)) |v| {
            tmp_args[used] = v;
            used += 1;
        }
    }

    return php_object_call(obj_val, method_name_val.asString().data, tmp_args[0..used]);
}

/// 使用命名参数调用对象方法（★批次十八①：原桩「假设参数顺序正确」违宪 ⇒ 真绑定重写）。
/// args_array 包含位置参数（整数键）和命名参数（字符串键）
pub fn php_object_call_named_args(obj_val: Value, method_name_val: Value, args_array: Value, allocator: Allocator) !Value {
    // 实测（$x=null; $m=1; $x->$m()）：方法名检查先于接收者检查。
    if (!method_name_val.isString()) {
        return throwThrowable("Error", "Method name must be a string", allocator);
    }
    if (!Value_isObject(obj_val)) {
        var nbuf: [256]u8 = undefined;
        const nmsg = std.fmt.bufPrint(&nbuf, "Call to a member function {s}() on {s}", .{
            method_name_val.asString().data, phpArgTypeWord(obj_val),
        }) catch "Call to a member function on a non-object";
        return throwThrowable("Error", nmsg, allocator);
    }
    if (!args_array.isArray()) {
        // 命名实参数组由发射器构造，非数组属内部不变量；仍用 TypeError 保持可捕获。
        return throwThrowable("TypeError", "Arguments must be an array", allocator);
    }
    return callObjectMethodNamedChecked(obj_val, method_name_val.asString().data, args_array.asArray(), allocator);
}

/// ★批次十八①：命名方法调用的共享落点（-> / ?-> / 显式命名三路汇聚）。
///   未命中方法且无 __call ⇒ 与 php_object_call 同口径的可捕获 Error。
fn callObjectMethodNamedChecked(obj_val: Value, method_name: []const u8, arr: *PHPArray, allocator: Allocator) !Value {
    _ = allocator;
    const obj = Value_asObject(obj_val);
    return obj.callMethodNamed(method_name, arr) catch |err| {
        if (err == error.MethodNotFound) {
            const class_name = if (obj.class_meta) |m| m.name else "unknown";
            var buf: [512]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Call to undefined method {s}::{s}()", .{ class_name, method_name }) catch
                "Call to undefined method";
            return throwThrowable("Error", msg, obj.allocator);
        }
        return err;
    };
}

// ============================================================================
// 算术运算符
// ============================================================================

/// 尝试将 Value 转为 i64（PHP 类型推导语义）
/// int → 原值；bool → 1/0；null → 0；纯整数字符串 → 解析值；其他 → null
fn tryAsInt(val: Value) ?i64 {
    if (val.isInt()) return val.asInt();
    if (val.isBool()) return if (val.asBool()) 1 else 0;
    if (val.isNull()) return 0;
    if (val.isString()) {
        const s = val.asString();
        const data = s.data[0..s.length];
        // 纯整数字符串：^[+-]?[0-9]+$
        if (data.len == 0) return null;
        var start: usize = 0;
        if (data[0] == '+' or data[0] == '-') start = 1;
        if (start >= data.len) return null;
        for (data[start..]) |c| {
            if (c < '0' or c > '9') return null;
        }
        return std.fmt.parseInt(i64, data, 10) catch null;
    }
    return null;
}

/// 加法运算（PHP语义）
/// ★F-55（R-171）：**二元算术**专用的宽松判据。
/// 实测 PHP 8.5.8 对 `+ - * / % **` 与 `pow()` 的结果类型由**数字前缀的字面语法**决定，
/// 且**允许尾部垃圾与首尾空白**（此时另由 `emitArithmeticStringWarningIfNeeded` 打
/// `Warning: A non-numeric value encountered`，本函数不管警告）：
///   `'5abc' + 2` = **int 7**、`' 5' + 1` = int 6、`'5 ' + 1` = int 6、`'0x10' + 1` = int 1（前缀只吃到 `0`）
///   `'5.5abc' + 2` = double 7.5、`'5e2' + 1` = double 501.0、`'5.0' + 1` = double 6.0（★有 `.`／指数就是 float，与数值是否为整无关）
/// 越界（`parseInt` 失败）⇒ 返回 null ⇒ 走 float 路（实测 `'99999999999999999999' + 1` = double）
/// ★与 `tryAsInt`（严格：整串必须是 `^[+-]?\d+$`）**刻意并存**：内置函数的形参走的是**严格**口径
///   （实测 `abs(' 5')` = int 5 但 `abs('5abc')`、`abs('0x10')` 直接 `TypeError`）⇒ 不可把两者合并。
fn tryAsIntLoose(val: Value) ?i64 {
    if (val.isString()) {
        const s = val.asString();
        const data = s.data[0..s.length];
        var i: usize = 0;
        while (i < data.len and std.ascii.isWhitespace(data[i])) : (i += 1) {}
        var end = i;
        if (end < data.len and (data[end] == '+' or data[end] == '-')) end += 1;
        const first_digit = end;
        while (end < data.len and data[end] >= '0' and data[end] <= '9') : (end += 1) {}
        if (end == first_digit) return null; // 没有数字前缀，或前缀以 `.`／指数开头 ⇒ 交浮点路
        // 前缀之后若紧跟 `.`／`e`／`E` 则是 float 语法
        if (end < data.len and (data[end] == '.' or data[end] == 'e' or data[end] == 'E')) return null;
        return std.fmt.parseInt(i64, data[i..end], 10) catch null;
    }
    return tryAsInt(val);
}

pub fn php_add(lhs: Value, rhs: Value) !Value {
    // 数组联合运算：$a + $b（保留左侧值，右侧不存在的键才加入）
    if (lhs.isArray() and rhs.isArray()) {
        return php_array_union(lhs, rhs, runtime_allocator);
    }
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwUnsupportedOperandError(lhs, rhs, "+");
    }
    // PHP 类型推导：int/bool/null/整数字符串 之间运算 → int
    // ★F-55（R-171）：二元算术用**宽松**前缀判据（实测 `'5abc' + 2` 在 PHP 是 int 7，AOT 旧落 float 得 7.0）
    if (tryAsIntLoose(lhs)) |a| {
        if (tryAsIntLoose(rhs)) |b| {
            const result = @addWithOverflow(a, b);
            if (result[1] != 0) {
                return Value.initFloat(@as(f64, @floatFromInt(a)) + @as(f64, @floatFromInt(b)));
            }
            return Value.initInt(result[0]);
        }
    }

    // 其他情况：转为浮点数
    const a = lhs.toFloat();
    const b = rhs.toFloat();
    return Value.initFloat(a + b);
}

/// 减法运算（PHP语义）
pub fn php_sub(lhs: Value, rhs: Value) !Value {
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwUnsupportedOperandError(lhs, rhs, "-");
    }
    // ★F-55（R-171）：二元算术用**宽松**前缀判据（实测 `'5abc' + 2` 在 PHP 是 int 7，AOT 旧落 float 得 7.0）
    if (tryAsIntLoose(lhs)) |a| {
        if (tryAsIntLoose(rhs)) |b| {
            const result = @subWithOverflow(a, b);
            if (result[1] != 0) {
                return Value.initFloat(@as(f64, @floatFromInt(a)) - @as(f64, @floatFromInt(b)));
            }
            return Value.initInt(result[0]);
        }
    }

    const a = lhs.toFloat();
    const b = rhs.toFloat();
    return Value.initFloat(a - b);
}

/// Perl-style string increment (用于 ++$str / $str++)
fn perlStringIncrement(val: Value) !Value {
    const str = val.asString();
    const data = str.data[0..str.length];

    // 空字符串 → 1（整数）
    if (data.len == 0) return Value.initInt(1);

    // 创建可变副本
    var bytes = try runtime_allocator.alloc(u8, data.len);
    defer runtime_allocator.free(bytes);
    @memcpy(bytes, data);

    const first = bytes[0];
    var carry: bool = false;
    var i: usize = bytes.len - 1;

    // 递增最后一个字符
    const last = bytes[i];
    if (last >= 'a' and last <= 'z') {
        if (last == 'z') {
            bytes[i] = 'a';
            carry = true;
        } else {
            bytes[i] = last + 1;
        }
    } else if (last >= 'A' and last <= 'Z') {
        if (last == 'Z') {
            bytes[i] = 'A';
            carry = true;
        } else {
            bytes[i] = last + 1;
        }
    } else if (last >= '0' and last <= '9') {
        if (last == '9') {
            bytes[i] = '0';
            carry = true;
        } else {
            bytes[i] = last + 1;
        }
    } else {
        // 非字母数字字符：停止
        carry = false;
    }

    // 进位传播
    while (carry and i > 0) {
        i -= 1;
        if (bytes[i] >= 'a' and bytes[i] <= 'z') {
            if (bytes[i] == 'z') {
                bytes[i] = 'a';
                carry = true;
            } else {
                bytes[i] += 1;
                carry = false;
            }
        } else if (bytes[i] >= 'A' and bytes[i] <= 'Z') {
            if (bytes[i] == 'Z') {
                bytes[i] = 'A';
                carry = true;
            } else {
                bytes[i] += 1;
                carry = false;
            }
        } else if (bytes[i] >= '0' and bytes[i] <= '9') {
            if (bytes[i] == '9') {
                bytes[i] = '0';
                carry = true;
            } else {
                bytes[i] += 1;
                carry = false;
            }
        } else {
            // 非字母数字：停止进位
            carry = false;
        }
    }

    if (carry) {
        // 基于首字符类型决定前置字符
        const new_bytes = try runtime_allocator.alloc(u8, bytes.len + 1);
        var prepend: u8 = '1';
        if (first >= 'a' and first <= 'z') {
            prepend = 'a';
        } else if (first >= 'A' and first <= 'Z') {
            prepend = 'A';
        } else if (first >= '0' and first <= '9') {
            prepend = '1';
        }
        new_bytes[0] = prepend;
        @memcpy(new_bytes[1..], bytes);
        const result = try PHPString.init(runtime_allocator, new_bytes);
        runtime_allocator.free(new_bytes);
        return Value.initString(result);
    }

    return Value.initString(try PHPString.init(runtime_allocator, bytes));
}

/// 递增运算（PHP 语义：++$var / $var++）
/// 整数/浮点：数值递增
/// 数字字符串：转为数字后递增
/// 非数字字母字符串：Perl 风格字符递增
/// null：变为 1
pub fn php_increment(val: Value) !Value {
    if (val.isInt()) {
        return try php_add(val, Value.initInt(1));
    }
    if (val.isFloat()) {
        return Value.initFloat(val.asFloat() + 1.0);
    }
    if (val.isNull()) {
        return Value.initInt(1);
    }
    if (val.isBool()) {
        // ★F-61（R-331）：bool 增量 PHP 8.5.8 实测＝Warning「Increment on type bool has no
        //   effect…」＋**值不变**（旧误返 int 2/1）。
        emitWarning("Increment on type bool has no effect, this will change in the next major version of PHP");
        return val;
    }
    if (val.isString()) {
        const str = val.asString();
        const data = str.data[0..str.length];
        if (data.len == 0) return Value.initInt(1);
        if (isNumericString(data)) {
            const f = val.toFloat();
            const int_val: i64 = @intFromFloat(f);
            if (@as(f64, @floatFromInt(int_val)) == f) {
                return Value.initInt(int_val + 1);
            }
            return Value.initFloat(f + 1.0);
        }
        return perlStringIncrement(val);
    }
    // ★F-59（R-169）：对象走自己的措辞，**不能**落到 `php_add`（那边现在也拒对象，但措辞是 `Foo + int`，不是 PHP 的 `Cannot increment Foo`）
    if (Value_isObject(val)) return throwCannotIncDecError(val, "increment");
    // ★F-61（R-331）：数组增量措辞＝「Cannot increment array」（operandTypeName(array)="array"，
    //   与对象支同一 helper；旧落到 php_add ⇒ 错措辞「Unsupported operand types: array + int」）。
    if (val.isArray()) return throwCannotIncDecError(val, "increment");
    return try php_add(val, Value.initInt(1));
}

/// 递减运算（PHP 语义：--$var / $var--）
/// 整数/浮点：数值递减
/// 数字字符串：转为数字后递减
/// 非数字字符串：无操作（PHP 行为）
/// null：无操作（PHP 行为）
pub fn php_decrement(val: Value) !Value {
    if (val.isInt()) {
        return try php_sub(val, Value.initInt(1));
    }
    if (val.isFloat()) {
        return Value.initFloat(val.asFloat() - 1.0);
    }
    if (val.isNull()) {
        return val;
    }
    if (val.isBool()) {
        // ★F-61（R-331）：bool 递减同族（「Decrement on type bool…」Warning + 值不变）。
        emitWarning("Decrement on type bool has no effect, this will change in the next major version of PHP");
        return val;
    }
    if (val.isString()) {
        const str = val.asString();
        const data = str.data[0..str.length];
        if (data.len == 0) return val;
        if (isNumericString(data)) {
            const f = val.toFloat();
            const int_val: i64 = @intFromFloat(f);
            if (@as(f64, @floatFromInt(int_val)) == f) {
                return Value.initInt(int_val - 1);
            }
            return Value.initFloat(f - 1.0);
        }
        // 非数字字符串：递减是 no-op
        return val;
    }
    // ★F-59（R-169）：同 `php_increment`——对象必须走 `Cannot decrement <类名>`，不能落到 `php_sub` 的算术措辞上
    if (Value_isObject(val)) return throwCannotIncDecError(val, "decrement");
    // ★F-61（R-331）：数组递减同族（「Cannot decrement array」）。
    if (val.isArray()) return throwCannotIncDecError(val, "decrement");
    return try php_sub(val, Value.initInt(1));
}

/// Negate a value (unary minus)
pub fn php_neg(val: Value) !Value {
    // ★F-46（R-165）：数组／非数字字符串取负在 PHP 是可捕获 TypeError（实测 `-[1]` ⇒ `array * int`）
    if (!checkArithmeticOperand(val)) return throwNegateOperandError(val);
    if (val.isInt()) {
        const a = val.asInt();
        // i64 最小值取负会溢出
        if (a == std.math.minInt(i64)) {
            return Value.initFloat(-@as(f64, @floatFromInt(a)));
        }
        return Value.initInt(-a);
    }
    return Value.initFloat(-val.toFloat());
}

/// 乘法运算（PHP语义）
pub fn php_mul(lhs: Value, rhs: Value) !Value {
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwUnsupportedOperandError(lhs, rhs, "*");
    }
    // ★F-55（R-171）：二元算术用**宽松**前缀判据（实测 `'5abc' + 2` 在 PHP 是 int 7，AOT 旧落 float 得 7.0）
    if (tryAsIntLoose(lhs)) |a| {
        if (tryAsIntLoose(rhs)) |b| {
            const result = @mulWithOverflow(a, b);
            if (result[1] != 0) {
                return Value.initFloat(@as(f64, @floatFromInt(a)) * @as(f64, @floatFromInt(b)));
            }
            return Value.initInt(result[0]);
        }
    }

    const a = lhs.toFloat();
    const b = rhs.toFloat();
    return Value.initFloat(a * b);
}

/// 除法运算（PHP语义）
pub fn php_div(lhs: Value, rhs: Value) !Value {
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwUnsupportedOperandError(lhs, rhs, "/");
    }
    // PHP 将 null/bool 视为整数参与整除判断
    // ★F-55（R-171）：这里原来只看 `isInt/isNull/isBool` ⇒ `'6' / 2` 落 float 得 `3.0`，
    //   而 PHP 按**字面语法**判定：`6/2`＝int 3、`'6'/2`＝int 3、`'6.0'/2`＝double 3.0、`5/2.5`＝double 2.0。
    //   整除与 INT48 范围的判断保持原样（下面的 `@mod` 与范围检查一字未动）。
    const lhs_is_int = tryAsIntLoose(lhs) != null;
    const rhs_is_int = tryAsIntLoose(rhs) != null;
    if (lhs_is_int and rhs_is_int) {
        const a = lhs.toInt();
        const b = rhs.toInt();
        if (b == 0) {
            try throwThrowableDiscard("DivisionByZeroError", "Division by zero", runtime_allocator);
            return Value.initNull();
        }
        if (@mod(a, b) == 0) {
            const result = @divTrunc(a, b);
            if (result >= Value.INT48_MIN and result <= Value.INT48_MAX) {
                return Value.initInt(result);
            }
        }
    }

    const a = lhs.toFloat();
    const b = rhs.toFloat();
    if (b == 0.0) {
        try throwThrowableDiscard("DivisionByZeroError", "Division by zero", runtime_allocator);
        return Value.initNull();
    }
    return Value.initFloat(a / b);
}

/// 取模运算（PHP语义）
pub fn php_mod(lhs: Value, rhs: Value) !Value {
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwUnsupportedOperandError(lhs, rhs, "%");
    }
    // PHP 8.1+: float→int 隐式转换精度丢失时输出 Deprecated
    // ★R-167（F-58）：这两段逐字节抽出为 `emitFloatToIntDeprecatedIfNeeded`，与位运算族共用同一口径（DRY），
    //   形为不变（门 OPS 的 o4/o9/g8 与门 MSR 的 m12/g8 同时守护这条回边）。
    emitImplicitFloatToIntDiagnostics(lhs);
    emitImplicitFloatToIntDiagnostics(rhs);
    const a = lhs.toInt();
    const b = rhs.toInt();
    if (b == 0) {
        try throwThrowableDiscard("DivisionByZeroError", "Modulo by zero", runtime_allocator);
        return Value.initNull();
    }
    return Value.initInt(@rem(a, b));
}

/// ★F-58（R-167）：位运算／移位／取反族的**操作数类型名**。
/// 实测 PHP 在操作数消息里用**类名**而不是 "object"：`1 & new stdClass()` ⇒ `stdClass & int`、
/// `~new stdClass()` ⇒ `Cannot perform bitwise not on stdClass`。
/// ⇒ 不能直接用 `valueTypeName`（它对对象返回 "object"，那是别处消息的口径，改动它会波及全族 ⇒ 规则 30）。
fn operandTypeName(v: Value) []const u8 {
    if (Value_isObject(v)) return Value_asObject(v).class_name;
    return valueTypeName(v);
}

/// ★F-58：float 参与整数语义运算时的 Deprecated 诊断（`%` 与位运算族同口径，从 `php_mod` 的内联形
///   抽成 helper 供本族复用；判据仍是「转整后回浮不等」＝精度丢失）。
/// ★**隐式** float→int 站点（`%`／位运算族／`~`）的两条诊断，按 PHP 8.5.8 实测的**组合规则**发（工单 §54.1）：
///   ① 越界**有限**值 ⇒ **只**发 `The float … is not representable as an int, cast occurred`；
///   ② 界内非整值 ⇒ **只**发 `Implicit conversion from float … to int loses precision`；
///   ③ **NAN ⇒ 两条叠发**（唯一叠发形，Warn 在前）；④ 显式站点永远只发 Warn ⇒ 它们不调本函数。
///   ★旧谓词 `@floatFromInt(v.toInt()) != f` 在 `toInt()` 从饱和改回绕后会把越界有限值判成"丢精度"⇒ 多发一条
///     Deprecated（F2I 修前基线实测 `dep_over=8` 就是它）⇒ 判定必须与**值型规则解耦**。
///   ★改名理由：本函数现在同时管 Warn 与 Deprecated，旧名 `…DeprecatedIfNeeded` 会误导读者以为只管一种。
fn emitImplicitFloatToIntDiagnostics(v: Value) void {
    if (!v.isFloat()) return;
    warnFloatToIntNotRepresentable(v);
    const f = v.asFloat();
    const loses_precision = if (std.math.isNan(f)) true else !floatNotRepresentableAsInt(f) and f != @trunc(f);
    if (loses_precision) emitDeprecatedFloatToInt(f);
}

const BitOpKind = enum { bit_and, bit_or, bit_xor, shl, shr };

/// 二元位运算/移位的操作数错误。★实测两条措辞口径（照抄，不自创）：
///   · 对象**恒排在前面**：`new Foo() & 1` 与 `1 & new Foo()` 都印 `Foo & int`；
///   · array/string 用自然顺序：`[1] & 2` ⇒ `array & int`，`2 & [1]` ⇒ `int & array`。
/// （另注：PHP 自身在 `1 & (array)1` 这一支上印成 `array & int`，与字面数组相反 ⇒ 属 PHP 侧不一致，
///   本实现按字面数组的自然顺序口径，不复刻该反常。见工单 §41.6。）
fn throwBitwiseOperandError(lhs: Value, rhs: Value, op: []const u8) Value {
    const swap = Value_isObject(rhs) and !Value_isObject(lhs);
    const first: Value = if (swap) rhs else lhs;
    const second: Value = if (swap) lhs else rhs;
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "Unsupported operand types: {s} {s} {s}",
        .{ operandTypeName(first), op, operandTypeName(second) },
    ) catch "Unsupported operand types";
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★F-58：一元 `~` 的操作数错误，消息族不同：`Cannot perform bitwise not on <X>`。
/// 实测 <X> 口径：array⇒"array"、null⇒"null"、bool⇒**值文本 "true"/"false"**、对象⇒类名。
fn throwBitNotError(v: Value) Value {
    const kind: []const u8 = if (v.isBool()) (if (v.asBool()) "true" else "false") else operandTypeName(v);
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Cannot perform bitwise not on {s}", .{kind}) catch "Cannot perform bitwise not";
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★F-58：负移位计数 ⇒ 可捕获 `ArithmeticError: Bit shift by negative number`（实测 `1 << -1`、`8 >> -1`）。
fn throwBitShiftNegativeError() Value {
    throwThrowableDiscardCatch("ArithmeticError", "Bit shift by negative number", runtime_allocator);
    return Value.initNull();
}

const ByteBitOp = enum { byte_and, byte_or, byte_xor };

/// ★F-58：string × string 的逐字节位运算（**PHP 合法**运算，当前 AOT 一律给 int 0）。
/// 实测 8.5.8 的长度口径：`&`／`^` 结果长度取**较短者**；`|` 取**较长者**并把短者右侧补 `\0`。
///   `"abcdef" & "abc"` = "abc"(len 3)、`"ab" ^ "abc"` = 两枚 NUL、`"ab" | "a"` = "ab"(len 2)。
fn bitwiseStringResult(lhs: Value, rhs: Value, op: ByteBitOp) !Value {
    const l = lhs.asString();
    const r = rhs.asString();
    const lb = l.data[0..l.length];
    const rb = r.data[0..r.length];
    const n: usize = if (op == .byte_or) @max(lb.len, rb.len) else @min(lb.len, rb.len);
    const buf = try runtime_allocator.alloc(u8, n);
    errdefer runtime_allocator.free(buf);
    for (buf, 0..) |*slot, i| {
        const x: u8 = if (i < lb.len) lb[i] else 0;
        const y: u8 = if (i < rb.len) rb[i] else 0;
        slot.* = switch (op) {
            .byte_and => x & y,
            .byte_or => x | y,
            .byte_xor => x ^ y,
        };
    }
    return Value.initString(try PHPString.init(runtime_allocator, buf));
}

/// ★F-58（R-167）：位运算/移位族的统一实现，取代发射器里的裸 Zig 整数运算。
/// 收口的五面（全部实测定档，门 MSR b1..b46）：
///   ① 操作数类型检查（array／无数字前缀字符串／对象 ⇒ 可捕获 TypeError，消息带运算符与真实类型名）
///   ② string × string 逐字节（返回 **string**，连 `'5' & '3'` 都是字符串 "1" 而非 int 1）
///   ③ 有数字前缀的非数字串 ⇒ 先 `A non-numeric value encountered` Warning（与算术族同口径，复用
///      `emitArithmeticStringWarningIfNeeded` + `checkArithmeticOperand`，不另造窄判据 ⇒ 规则 30）
///   ④ float ⇒ Deprecated 隐式转整
///   ⑤ 移位计数：负数 ⇒ ArithmeticError；≥64 ⇒ shl 得 0、shr 得符号填充；shl 走 i128 截断复刻位回绕
fn php_bitwise(lhs: Value, rhs: Value, kind: BitOpKind) !Value {
    // ② string × string 先判：`"abc" << 2` 这类移位**不**逐字节，实测走数值路径 ⇒ 抛 `string << int`
    if (lhs.isString() and rhs.isString()) {
        const byte_op: ?ByteBitOp = switch (kind) {
            .bit_and => .byte_and,
            .bit_or => .byte_or,
            .bit_xor => .byte_xor,
            .shl, .shr => null,
        };
        if (byte_op) |bb| return bitwiseStringResult(lhs, rhs, bb);
    }

    const symbol: []const u8 = switch (kind) {
        .bit_and => "&",
        .bit_or => "|",
        .bit_xor => "^",
        .shl => "<<",
        .shr => ">>",
    };

    // ① 对象在此**提前**进操作数错误：不是因为 `checkArithmeticOperand` 放行对象（R-169 起它也拒对象），
    //   而是位运算族的消息口径是「对象恒排前」（`1 & new Foo()` ⇒ `Foo & int`），
    //   与算术族的自然顺序不同 ⇒ 必须走 `throwBitwiseOperandError`，不能落到下面的通用检查上（R-167 门 MSR b26/b27）。
    if (Value_isObject(lhs) or Value_isObject(rhs)) return throwBitwiseOperandError(lhs, rhs, symbol);

    // ③ 数值路径：与算术族共用口径
    emitArithmeticStringWarningIfNeeded(lhs);
    emitArithmeticStringWarningIfNeeded(rhs);
    if (!checkArithmeticOperand(lhs) or !checkArithmeticOperand(rhs)) {
        return throwBitwiseOperandError(lhs, rhs, symbol);
    }

    // ④ float ⇒ Deprecated
    emitImplicitFloatToIntDiagnostics(lhs);
    emitImplicitFloatToIntDiagnostics(rhs);

    const a = lhs.toInt();
    const b = rhs.toInt();
    return switch (kind) {
        .bit_and => Value.initInt(a & b),
        .bit_or => Value.initInt(a | b),
        .bit_xor => Value.initInt(a ^ b),
        .shl => shiftLeftValue(a, b),
        .shr => shiftRightValue(a, b),
    };
}

/// ⑤ 实测 `1 << 64` = 0、`PHP_INT_MAX << 1` = -2（位回绕）、`1 << -1` ⇒ ArithmeticError
fn shiftLeftValue(a: i64, count: i64) Value {
    if (count < 0) return throwBitShiftNegativeError();
    if (count >= 64) return Value.initInt(0);
    const widened: i128 = a;
    return Value.initInt(@truncate(widened << @intCast(castShift(count))));
}

/// ⑤ 实测 `-1 >> 64` = -1（符号填充）、`8 >> 65` = 0、`-8 >> 1` = -4；Zig 的 `>>` 对有符号数即算术右移
fn shiftRightValue(a: i64, count: i64) Value {
    if (count < 0) return throwBitShiftNegativeError();
    if (count >= 64) return Value.initInt(if (a < 0) @as(i64, -1) else 0);
    return Value.initInt(a >> @intCast(castShift(count)));
}

/// 计数已在上游保证 `0 <= count < 64` ⇒ 这里的 @intCast 恒安全（集中一处，避免两条分支各写一遍范围判断）
fn castShift(count: i64) u6 {
    return @intCast(count);
}

pub fn php_bit_and(lhs: Value, rhs: Value) !Value {
    return php_bitwise(lhs, rhs, .bit_and);
}

pub fn php_bit_or(lhs: Value, rhs: Value) !Value {
    return php_bitwise(lhs, rhs, .bit_or);
}

pub fn php_bit_xor(lhs: Value, rhs: Value) !Value {
    return php_bitwise(lhs, rhs, .bit_xor);
}

pub fn php_shl(lhs: Value, rhs: Value) !Value {
    return php_bitwise(lhs, rhs, .shl);
}

pub fn php_shr(lhs: Value, rhs: Value) !Value {
    return php_bitwise(lhs, rhs, .shr);
}

/// ★F-58：一元 `~`。实测三处与二元族**不同**，故独立成支：
///   · string（含数字串）**一律**逐字节取反并返回 **string**（`~"abc"`、`~'5'` 都是字符串）
///   · null／bool 也拒（二元族接受）⇒ `Cannot perform bitwise not on null`／`... on true`
///   · 只有 int／float 进数值路径（float 先 Deprecated）
pub fn php_bit_not(val: Value) !Value {
    if (val.isString()) {
        const s = val.asString();
        const src = s.data[0..s.length];
        const buf = try runtime_allocator.alloc(u8, src.len);
        errdefer runtime_allocator.free(buf);
        for (buf, 0..) |*slot, i| slot.* = ~src[i];
        return Value.initString(try PHPString.init(runtime_allocator, buf));
    }
    if (!val.isInt() and !val.isFloat()) return throwBitNotError(val);
    emitImplicitFloatToIntDiagnostics(val);
    return Value.initInt(~val.toInt());
}

/// 检查字符串是否为 PHP 数字字符串
fn isNumericString(data: []const u8) bool {
    if (data.len == 0) return false;
    var i: usize = 0;
    while (i < data.len and std.ascii.isWhitespace(data[i])) : (i += 1) {}
    if (i < data.len and (data[i] == '+' or data[i] == '-')) i += 1;
    if (i >= data.len) return false;
    var has_digits = false;
    while (i < data.len and std.ascii.isDigit(data[i])) : (i += 1) {
        has_digits = true;
    }
    if (i < data.len and data[i] == '.') {
        i += 1;
        while (i < data.len and std.ascii.isDigit(data[i])) : (i += 1) {
            has_digits = true;
        }
    }
    if (!has_digits) return false;
    if (i < data.len and (data[i] == 'e' or data[i] == 'E')) {
        i += 1;
        if (i < data.len and (data[i] == '+' or data[i] == '-')) i += 1;
        if (i >= data.len or !std.ascii.isDigit(data[i])) return false;
        while (i < data.len and std.ascii.isDigit(data[i])) : (i += 1) {}
    }
    while (i < data.len and std.ascii.isWhitespace(data[i])) : (i += 1) {}
    return i >= data.len;
}

fn numericPrefixLength(data: []const u8) usize {
    if (data.len == 0) return 0;
    var i: usize = 0;
    while (i < data.len and std.ascii.isWhitespace(data[i])) : (i += 1) {}
    if (i < data.len and (data[i] == '+' or data[i] == '-')) i += 1;
    const start_digits = i;
    while (i < data.len and std.ascii.isDigit(data[i])) : (i += 1) {}
    var has_digits = i > start_digits;
    if (i < data.len and data[i] == '.') {
        i += 1;
        const frac_start = i;
        while (i < data.len and std.ascii.isDigit(data[i])) : (i += 1) {}
        if (i > frac_start) has_digits = true;
    }
    if (!has_digits) return 0;
    if (i < data.len and (data[i] == 'e' or data[i] == 'E')) {
        var j = i + 1;
        if (j < data.len and (data[j] == '+' or data[j] == '-')) j += 1;
        const exp_start = j;
        while (j < data.len and std.ascii.isDigit(data[j])) : (j += 1) {}
        if (j > exp_start) i = j;
    }
    return i;
}

fn hasNumericPrefix(data: []const u8) bool {
    return numericPrefixLength(data) > 0;
}

fn emitArithmeticStringWarningIfNeeded(v: Value) void {
    if (!v.isString()) return;
    const str = v.asString().data[0..v.asString().length];
    if (hasNumericPrefix(str) and !isNumericString(str)) {
        emitWarning("A non-numeric value encountered");
    }
}

/// 检查 Value 是否可参与算术运算（PHP 8.x）
/// PHP 8.x: 无数字前缀的字符串参与算术运算时抛 TypeError
/// ★F-59（R-169，门 OBJ 逐枚实测）：对象同样**不能**参与算术，且**带 `__toString` 也一样抛**
///   （`Strable + 1` ⇒ `Unsupported operand types: Strable + int`）。
///   ★我先前担心的 DateInterval 特例经实测**不存在**：`$d1 - $d2`（DateTime − DateTime）在 PHP 8.5.8 就是抛
///   `Unsupported operand types: DateTime - DateTime`（取差要靠 `diff()`）⇒ 「对象一律拒」就是 PHP 正确行为。
///   改前的症状是对象被 NaN-boxing 兜底成 0.0 ⇒ `$o + 1` 静默得 **float 1.0**（门 OBJ o1..o9/o11..o15 十七枚红）。
fn checkArithmeticOperand(v: Value) bool {
    // 字符串：只有有数字前缀的才是合法算术操作数
    if (v.isString()) {
        const str = v.asString().data[0..v.asString().length];
        return hasNumericPrefix(str);
    }
    // ★F-59：对象不能参与算术运算（PHP 抛可捕获 TypeError，措辞用**类名**）
    if (Value_isObject(v)) return false;
    // 数组不能参与算术运算（会抛TypeError）
    return !v.isArray();
}

/// 输出 PHP Warning 到 stdout 和 stderr
/// AOT-CODEGEN-012 R-133：类是否携带 #[AllowDynamicProperties]（发射器将类注解
/// 存入 __attributes 静态属性，元素为 ReflectionAttribute 形态对象，__name 为注解名）
fn hasAllowDynamicProperties(meta: *const ClassMeta) bool {
    const attrs_val = meta.getStaticProperty("__attributes") orelse return false;
    if (!attrs_val.isArray()) return false;
    var it = attrs_val.asArray().elements.iterator();
    while (it.next()) |entry| {
        const v = entry.value_ptr.*;
        if (!Value_isObject(v)) continue;
        const attr_obj = Value_asObject(v);
        if (attr_obj.getPropertyDirect("__name")) |name_val| {
            if (name_val.isString() and std.ascii.eqlIgnoreCase(name_val.asString().data, "AllowDynamicProperties")) return true;
        }
    }
    return false;
}

/// ★F-92（R-180）：引擎诊断的**唯一分发口**。PHP 契约（工单 §73.3 实测七条里的 C1…C5）：
///   C1 设了处理器 ⇒ **先调处理器**（★F-95 更正：与 error_reporting 掩码无关，PHP 实测 0 掩码仍调用）；
///   C2 `@` 只抑制"标准显示"，**不抑制处理器被调用**（旧实现把 `isErrorSuppressed()` 放在最前面＝连处理器一起挡掉）；
///   C3 处理器返回 `false` ⇒ 追加标准处理；
///   C4 返回非 false（实测返回 `"not-a-bool"` 这种非布尔值也一样）⇒ **一个字都不打**；
///   C5 没设处理器 ⇒ 直接走标准处理；掩码只决定标准显示是否静默（standardPrint 内判定）。
/// 返回＝`null`（交给标准处理）／`.?==true`（处理器已接管）／`.?==false`（处理器要求再走标准处理）。
/// ★两条**本批刻意不做**的面（另立条目，不在文档里假装等价）：
///   F-98＝处理器内抛异常时 PHP 让它向上传播（实测 `CAUGHT:RuntimeException|in-handler`），而 `emitWarning` 是
///        `void`、改成可抛出要动数百个调用点 ⇒ 这里 `catch` 后按"处理器已接管"处理；
///   F-97＝`error_get_last()` 在 AOT 未实现（同族缺 `error_reporting()`/`register_shutdown_function()`＝F-95/F-96，
///        见任务 #113）⇒ C3/C4 的"last-error 是否更新"那半轴无从观测，ERRH 的 `l1/l2` 臂待其落地后补。
/// ★F-97：error_get_last() 账本。PHP 实测：**所有**诊断都记录（`@`、handler 接管、error_reporting 掩码静默都不例外）；
/// message 为裸消息（无 "PHP Warning:" 前缀），file/line 取诊断发生点。
/// ★F-95-d：裸常量标识符未定义 ⇒ PHP 8 的 `Error: Undefined constant "NAME"`（未捕获即 fatal，rc=255）。
/// 注意：可捕获性（try/catch(Error)）需要 global_get 调用点的异常路由，本函数先给未捕获等价形。
pub fn php_undefined_constant(name: []const u8) noreturn {
    if (fatalDisplayEnabled()) {
        var ebuf: [1024]u8 = undefined;
        const emsg = std.fmt.bufPrint(
            &ebuf,
            "PHP Fatal error:  Uncaught Error: Undefined constant \"{s}\" in {s}:{d}\nStack trace:\n#0 {{main}}\n  thrown in {s} on line {d}\n",
            .{ name, src_file, src_line, src_file, src_line },
        ) catch "";
        fileWriteAll(2, emsg);
        var buf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "\nFatal error: Uncaught Error: Undefined constant \"{s}\" in {s}:{d}\nStack trace:\n#0 {{main}}\n  thrown in {s} on line {d}\n",
            .{ name, src_file, src_line, src_file, src_line },
        ) catch "";
        fileWriteAll(1, msg);
    }
    php_run_shutdown_functions();
    std.process.exit(255);
}

const LastError = struct { type: i64, message: []u8, file: []u8, line: u32 };
var last_error: ?LastError = null;

fn recordLastError(level: i64, msg: []const u8) void {
    if (last_error) |old| {
        runtime_allocator.free(old.message);
        runtime_allocator.free(old.file);
    }
    const m = runtime_allocator.dupe(u8, msg) catch return;
    const f = runtime_allocator.dupe(u8, src_file) catch {
        runtime_allocator.free(m);
        return;
    };
    last_error = .{ .type = level, .message = m, .file = f, .line = src_line };
}

pub fn php_error_get_last(allocator: Allocator) !Value {
    const le = last_error orelse return Value.initNull();
    const arr = try PHPArray.init(allocator);
    errdefer arr.release(allocator);
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "type")), Value.initInt(le.type));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "message")), Value.initString(try PHPString.init(allocator, le.message)));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "file")), Value.initString(try PHPString.init(allocator, le.file)));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "line")), Value.initInt(le.line));
    return Value.initArray(arr);
}

pub fn php_error_clear_last() !Value {
    if (last_error) |old| {
        runtime_allocator.free(old.message);
        runtime_allocator.free(old.file);
        last_error = null;
    }
    return Value.initNull();
}

fn dispatchToUserHandler(level: i64, msg: []const u8) ?bool {
    const handler = global_error_handler orelse {
        recordLastError(level, msg); // ★F-97-b：无处理器 ⇒ 记账
        return null;
    };
    // ★F-140：处理器掩码（set_error_handler 第二形参）之外的级别不调处理器，走标准处理并记账。
    if ((level & global_error_handler_mask) == 0) {
        recordLastError(level, msg);
        return null;
    }
    // ★F-95：PHP 实测**处理器不受 error_reporting 掩码影响**（error_reporting(0) 下仍收到 E_WARNING）；
    //   掩码只作用于标准显示（见 standardPrint）。
    // ★★必须走 `php_invoke_callable`，**不能**判 `handler.isFunction()`：AOT 里注册进来的可调用值是
    //   "函数名字符串"（`set_error_handler("h")`）或**闭包对象**（门 V 的"闭包=对象"面），两者都不是 `TYPE_FUNCTION`
    //   ⇒ 旧 `php_trigger_error` 那套 `isFunction()+asFunction()` 对绝大多数真实处理器**根本不触发**（R-180 实测：
    //   只打标准两行、`[ECHO]/[FW]` 全无）。这也是为什么"两套口径并存"其实是一套半失效。
    // ★`php_is_callable` 返回 `!Value` ⇒ 先落成 Value 再取布尔，别把 `!`/`catch` 混在一个表达式里（优先级会读错）。
    const callable = php_is_callable(handler) catch Value.initBool(false);
    if (!callable.toBool()) {
        recordLastError(level, msg); // 不可调用 ⇒ 走标准处理，等价无处理器
        return null;
    }
    const msg_str = PHPString.init(runtime_allocator, msg) catch return true;
    const file_str = PHPString.init(runtime_allocator, src_file) catch msg_str;
    var args = [_]Value{
        Value.initInt(level), // ★偏差①：`errno` 在前（旧 `php_trigger_error` 把 message 放第一位 ⇒ 处理器里 $no/$str 互换）
        Value.initString(msg_str),
        Value.initString(file_str),
        Value.initInt(@intCast(src_line)),
    };
    const ret = php_invoke_callable(handler, args[0..], runtime_allocator) catch return true; // ★F-98
    if (ret.isBool() and !ret.asBool()) {
        recordLastError(level, msg); // ★F-97-b：处理器 return false ⇒ 标准处理补打，且记账
        return false; // C3
    }
    // ★F-97-b：处理器 return null/true（非 false）接管 ⇒ 不记账（PHP 实测 error_get_last 保持 null）
    return true; // C4
}

/// 标准处理＝PHP 的两行两流。★文案与改动前**逐字节相同**（修前基线里"无处理器/无诊断"的臂本来就全绿）：
///   stderr `PHP <Label>:  {msg} in {file} on line {N}`（**两个**空格、无前导空行）；
///   stdout `{前导}\n<Label>: {msg} …`（**一个**空格）。★`Deprecated` 的 stdout 行历史上就没有前导空行
///   ⇒ 用 `out_label` 参数原样带上，不在本批"顺手统一"。
/// F-95：PHP 的 fatal 显示同样受 error_reporting 的 E_ERROR 位控制（掩掉后完全静默，rc 仍 255）。
fn fatalDisplayEnabled() bool {
    return (E_ERROR & global_error_types) != 0;
}

fn standardPrint(err_label: []const u8, out_label: []const u8, msg: []const u8, level: i64) void {
    if (isErrorSuppressed()) return; // ★C2：抑制只作用在这一层
    if ((level & global_error_types) == 0) return; // ★F-95：error_reporting 掩码只静默标准显示
    var ebuf: [1024]u8 = undefined;
    const emsg = std.fmt.bufPrint(&ebuf, "{s}{s} in {s} on line {d}\n", .{ err_label, msg, src_file, src_line }) catch return;
    fileWriteAll(2, emsg);
    var buf: [1024]u8 = undefined;
    const smsg = std.fmt.bufPrint(&buf, "{s}{s} in {s} on line {d}\n", .{ out_label, msg, src_file, src_line }) catch return;
    fileWriteAll(1, smsg);
}

/// ★F-131-e：用户 handler 是生成的闭包，执行时会把全局 src_file/src_line 推进到**闭包内**的语句；
///   诊断的标准打印发生在 dispatch **之后**，必须用"诊断发生时"的位置，否则行号/文件会指到 handler 里。
const DiagLoc = struct { file: []const u8, line: u32 };
fn diagLoc() DiagLoc {
    return .{ .file = src_file, .line = src_line };
}
fn restoreDiagLoc(loc: DiagLoc) void {
    src_file = loc.file;
    src_line = loc.line;
}

/// AOT-CODEGEN-012 R-132：PHP 8.2+ Deprecated 诊断（动态属性创建等）
pub fn emitDeprecated(msg: []const u8) void {
    const loc = diagLoc();
    if (dispatchToUserHandler(E_DEPRECATED, msg)) |handled| {
        if (handled) return; // C4
    }
    restoreDiagLoc(loc);
    // ★F-130：与同契约的另 6 处（Warning/Notice/E_USER_*）一致，stdout 支必须带**前导换行**。
    standardPrint("PHP Deprecated:  ", "\nDeprecated: ", msg, E_DEPRECATED);
}

pub fn emitWarning(msg: []const u8) void {
    const loc = diagLoc();
    if (dispatchToUserHandler(E_WARNING, msg)) |handled| {
        if (handled) return; // C4
    }
    restoreDiagLoc(loc);
    standardPrint("PHP Warning:  ", "\nWarning: ", msg, E_WARNING);
}

pub fn emitDeprecatedStrGetcsvEscape() void {
    // ★F-125：直写路径须补齐 standardPrint 的两件事——
    //   ① 先路由用户处理器（PHP 实测：`@` 下处理器**仍被调用**，抑制只作用于标准打印）；
    //   ② 再查抑制位（C2 规则，fileWriteAll 直写不会自动生效）。
    const loc = diagLoc();
    if (dispatchToUserHandler(E_DEPRECATED, "str_getcsv(): the $escape parameter must be provided as its default value will change")) |handled| {
        if (handled) return;
    }
    restoreDiagLoc(loc);
    if (isErrorSuppressed()) return;
    if ((E_DEPRECATED & global_error_types) == 0) return; // ★F-95：掩码静默标准显示
    // PHP 输出顺序：先 stderr，再 stdout
    var ebuf: [1024]u8 = undefined;
    const emsg = std.fmt.bufPrint(
        &ebuf,
        "PHP Deprecated:  str_getcsv(): the $escape parameter must be provided as its default value will change in {s} on line {d}\n",
        .{ src_file, src_line },
    ) catch "";
    fileWriteAll(2, emsg);
    var buf: [1024]u8 = undefined;
    const wmsg = std.fmt.bufPrint(
        &buf,
        "\nDeprecated: str_getcsv(): the $escape parameter must be provided as its default value will change in {s} on line {d}\n",
        .{ src_file, src_line },
    ) catch "";
    fileWriteAll(1, wmsg);
}

pub fn emitUndefinedVariableWarning(name: []const u8) void {
    // ★F-125：同上——先路由处理器（`@` 不阻止处理器），再查抑制位。
    var mbuf: [512]u8 = undefined;
    const hmsg = std.fmt.bufPrint(&mbuf, "Undefined variable {s}", .{name}) catch "Undefined variable";
    const loc = diagLoc();
    if (dispatchToUserHandler(E_WARNING, hmsg)) |handled| {
        if (handled) return;
    }
    restoreDiagLoc(loc);
    if (isErrorSuppressed()) return;
    if ((E_WARNING & global_error_types) == 0) return; // ★F-95：掩码静默标准显示
    // PHP 输出顺序：先 stderr，再 stdout
    var ebuf: [1024]u8 = undefined;
    const emsg = std.fmt.bufPrint(
        &ebuf,
        "PHP Warning:  Undefined variable {s} in {s} on line {d}\n",
        .{ name, src_file, src_line },
    ) catch "";
    fileWriteAll(2, emsg);
    var buf: [1024]u8 = undefined;
    const wmsg = std.fmt.bufPrint(
        &buf,
        "\nWarning: Undefined variable {s} in {s} on line {d}\n",
        .{ name, src_file, src_line },
    ) catch "";
    fileWriteAll(1, wmsg);
}

/// ★Deprecated-null（批次二十四续）：内建**非 nullable** 形参收 null ⇒
///   Deprecated「{fn}(): Passing null to parameter #N ($name) of type T is deprecated」+ 弱转标量。
///   口径（PHP 8.5.8 实测矩阵 p0b*）：仅内建函数（用户函数同点走 TypeError）；
///   nullable/mixed/无类型不警；类型须含标量成员（纯 array/对象形参同点走 TypeError 域）；
///   联合类型措辞取原文（"int|float"/"array|string"），弱转目标＝文本序首个标量成员。
///   非 null ⇒ 原样返回（零开销快路径）。nlk 直调面 writeBuiltinArgs 与
///   php_invoke_callable 变量调用面共用本枚。
pub fn q4DepNull(v: Value, fn_name: []const u8, idx1: usize, pname: []const u8, ptype: []const u8, allocator: Allocator) Value {
    if (!v.isNull()) return v;
    // 弱转目标：文本序首个标量成员；无标量成员 ⇒ 不警不转（TypeError 域，非本机制）
    const weak: Value = blk: {
        var it = std.mem.splitScalar(u8, ptype, '|');
        while (it.next()) |m| {
            if (std.mem.eql(u8, m, "string")) break :blk Value.initString(PHPString.initStatic(""));
            if (std.mem.eql(u8, m, "int")) break :blk Value.initInt(0);
            if (std.mem.eql(u8, m, "float")) break :blk Value.initFloat(0.0);
            if (std.mem.eql(u8, m, "bool")) break :blk Value.initBool(false);
        }
        return v; // 非标量族 ⇒ 原样（不警）
    };
    // Deprecated 发射（emitDeprecatedStrGetcsvEscape 同族三段式：处理器 → 抑制 → 掩码）
    var mbuf: [512]u8 = undefined;
    const hmsg = std.fmt.bufPrint(&mbuf, "{s}(): Passing null to parameter #{d} (${s}) of type {s} is deprecated", .{ fn_name, idx1, pname, ptype }) catch "Passing null is deprecated";
    const loc = diagLoc();
    if (dispatchToUserHandler(E_DEPRECATED, hmsg)) |handled| {
        if (handled) {
            restoreDiagLoc(loc);
            return weak;
        }
    }
    restoreDiagLoc(loc);
    if (isErrorSuppressed()) return weak;
    if ((E_DEPRECATED & global_error_types) == 0) return weak;
    var ebuf: [1024]u8 = undefined;
    const emsg = std.fmt.bufPrint(
        &ebuf,
        "PHP Deprecated:  {s} in {s} on line {d}\n",
        .{ hmsg, src_file, src_line },
    ) catch "";
    fileWriteAll(2, emsg);
    var buf: [1024]u8 = undefined;
    const wmsg = std.fmt.bufPrint(
        &buf,
        "\nDeprecated: {s} in {s} on line {d}\n",
        .{ hmsg, src_file, src_line },
    ) catch "";
    fileWriteAll(1, wmsg);
    _ = allocator;
    return weak;
}

/// ★F-46（R-165）：操作数类型错误改为**可捕获**的 TypeError。
/// 旧实现是 `noreturn` + `std.process.exit(255)`：消息文本本来就对，但**绕过了整条异常路由**
/// ⇒ `try { [1] + 2; } catch (TypeError)` 永远接不住（门 OPS 的 12 枚 `aot_exit255=yes` 臂就是它）。
/// 现形与 `php_intdiv` 的 R-159 先例同构：置 `throwThrowable` 后返回 null，由调用点的
/// `hasException()` 路由去 catch／未捕获上报（未捕获文本面另有 F-39-ii，不在本面）。
fn throwUnsupportedOperandError(lhs: Value, rhs: Value, op: []const u8) Value {
    var buf: [512]u8 = undefined;
    // ★F-59（R-169）：算术族的消息口径＝**自然顺序 ＋ 类名**（实测 `1 + new Foo()` ⇒ `int + Foo`、
    //   `new Foo() + 1` ⇒ `Foo + int`）⇒ 这里把 `valueTypeName`（对象给 "object"）换成 `operandTypeName`。
    //   ★与位运算族**不同**：那族是「对象恒排前 ＋ 类名」（`throwBitwiseOperandError`），两套不合并。
    //   `valueTypeName` 的其余调用点（`count()` 的 "must be of type array, object given" 等）措辞本来就是 "object" ⇒ **不动**。
    const msg = std.fmt.bufPrint(
        &buf,
        "Unsupported operand types: {s} {s} {s}",
        .{ operandTypeName(lhs), op, operandTypeName(rhs) },
    ) catch "Unsupported operand types";
    // 置异常失败只可能是分配失败：此时仍然返回 null，绝不回退成 exit(255)（那就退回旧缺陷形态）
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★一元取负的操作数面：PHP 的措辞是 `{type} * int`（实测 `-[1]` ⇒ `Unsupported operand types: array * int`），
/// 照抄该措辞，不自创 "array * -1" 之类的形式。
fn throwNegateOperandError(val: Value) Value {
    var buf: [512]u8 = undefined;
    // ★F-59（R-169）：同样改走 `operandTypeName` ⇒ 实测 `-$o` ⇒ `Unsupported operand types: Foo * int`（类名）。
    const msg = std.fmt.bufPrint(
        &buf,
        "Unsupported operand types: {s} * int",
        .{operandTypeName(val)},
    ) catch "Unsupported operand types";
    // 置异常失败只可能是分配失败：此时仍然返回 null，绝不回退成 exit(255)（那就退回旧缺陷形态）
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★F-59（R-169）：增量/自减对**对象**用的是**第三套措辞**（实测四形 pre/post 同文本）：
///   `++$o`／`$o++` ⇒ `Cannot increment Foo`；`--$o`／`$o--` ⇒ `Cannot decrement Foo`（都是可捕获 TypeError）。
///   类型名同样取**类名**（走 `operandTypeName`）。
///   ★必要性有实测证据：只改 `checkArithmeticOperand` 而不在 `php_increment/php_decrement` 末路拦对象时，
///   这五形会被通用算术检查接成 `Unsupported operand types: Foo + int`＝**把一种错换成另一种错**
///   （门 OBJ 中间态实测 i1..i5 全为此形）。
fn throwCannotIncDecError(val: Value, action: []const u8) Value {
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "Cannot {s} {s}",
        .{ action, operandTypeName(val) },
    ) catch "Cannot increment";
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★F-62（R-172 乙型）：内置函数**数值形参**的参数类型校验＝PHP 的**第四套措辞**（不是操作数措辞）。
///   逐枚实测口径（真值资产 `/tmp/r172/f62_param_truth{,2,3,4}_tmp.php` 与 `f62_names_tmp.php`）：
///   · 对象**一律拒**且 given 用**类名**——带 `__toString` 的也拒（实测 `abs($b)` ⇒ `Bar given`，而 `bcadd($b,"1")` 却静默转成 '6'
///     ⇒ string 形参要的是「stringable 感知」拒绝，另立 F-62b，本 helper 只管数值形参）；array ⇒ `array given`；
///   · 字符串只接受**完整数值串**（`"5"`／`"+5"`／`" 5 "`／`"5.0"`／`"1e3"`），**前导数值串拒**（`"5abc"`、`"0x1A"` ⇒ `string given`）
///     ⇒ 与二元算术的宽松口径（`tryAsIntLoose`，R-171）**刻意相反**，两者不可合并；
///   · bool 静默强转（`abs(true)`=int 1、`sqrt(true)`=1.0）；null ⇒ `Deprecated: <fn>(): Passing null to parameter #N ($p) of type <T> is deprecated`
///     后按 0 继续（实测 `abs(null)`=int 0、`sqrt(null)`=0.0、`exp(null)`=1.0）；
///   · `int` 形参吃 float：整值且在 i64 域内 ⇒ 静默；非整值 ⇒ `Deprecated: Implicit conversion from float 5.9 to int loses precision` 后**向零截断**
///     （实测 `intdiv(-5.9,2)`=int -2）；NAN/INF/越界（`1e19`）⇒ `TypeError …, float given`；
///   · `int` 形参吃数值串：整值语法 ⇒ int；非整值 ⇒ 同句式但写作 `float-string "5.5"`（★带引号的原文，与 float 版**不同**）；越界（`"1e19"`）⇒ `string given`；
///   · `float` 形参吃 int ⇒ 静默加宽。
const NumParamKind = enum { int_param, nullable_int_param, float_param, num_param };

fn numParamExpectedText(kind: NumParamKind) []const u8 {
    return switch (kind) {
        .int_param => "int",
        .nullable_int_param => "?int",
        .float_param => "float",
        .num_param => "int|float",
    };
}

/// 通用参数类型校验措辞：`<fn>(): Argument #N ($p) must be of type <T>, <given> given`
/// 置 TypeError 并返回 null ⇒ 调用方 `orelse return Value.initNull()`，让发射器的 hasException 路由接手。
fn rejectParamType(
    fn_name: []const u8,
    arg_no: usize,
    param_name: []const u8,
    expected: []const u8,
    val: Value,
) ?Value {
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given",
        .{ fn_name, arg_no, param_name, expected, operandTypeName(val) },
    ) catch "TypeError";
    throwThrowableDiscardCatch("TypeError", msg, runtime_allocator);
    return null;
}

/// 去掉首尾空白（与 `isNumericString`／`numericPrefixLength` 的空白容忍保持一致）
fn trimNumericWhitespace(data: []const u8) []const u8 {
    var start: usize = 0;
    while (start < data.len and std.ascii.isWhitespace(data[start])) : (start += 1) {}
    var end = data.len;
    while (end > start and std.ascii.isWhitespace(data[end - 1])) : (end -= 1) {}
    return data[start..end];
}

/// 完整整数语法（允许首尾空白与前导 `+`/`-`）⇒ i64；非整语法或越界 ⇒ null
fn strictIntFromTrimmed(data: []const u8) ?i64 {
    const t = trimNumericWhitespace(data);
    if (t.len == 0) return null;
    var i: usize = 0;
    if (t[0] == '+' or t[0] == '-') i = 1;
    if (i >= t.len) return null;
    for (t[i..]) |c| {
        if (c < '0' or c > '9') return null;
    }
    return std.fmt.parseInt(i64, t, 10) catch null;
}

/// 数值前缀的 PHP 口径值：前缀是整语法 ⇒ int，含 `.`／指数 ⇒ float（与 R-171 二元算术的结果类型口径同源）
fn numericPrefixValue(data: []const u8) ?Value {
    const len = numericPrefixLength(data);
    if (len == 0) return null;
    const t = trimNumericWhitespace(data[0..len]);
    if (std.mem.indexOfScalar(u8, t, '.') != null or std.mem.indexOfScalar(u8, t, 'e') != null or
        std.mem.indexOfScalar(u8, t, 'E') != null)
    {
        return Value.initFloat(std.fmt.parseFloat(f64, t) catch 0.0);
    }
    return Value.initInt(std.fmt.parseInt(i64, t, 10) catch 0);
}

fn emitDeprecatedPassingNull(
    fn_name: []const u8,
    arg_no: usize,
    param_name: []const u8,
    type_text: []const u8,
) void {
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "{s}(): Passing null to parameter #{d} (${s}) of type {s} is deprecated",
        .{ fn_name, arg_no, param_name, type_text },
    ) catch return;
    emitDeprecated(msg);
}

/// `int` 形参吃**非整值 float-string** 的措辞：`Implicit conversion from float-string "5.5" to int loses precision`
/// （★与 `emitDeprecatedFloatToInt` 的 float 版差在 `float-string "<原文>"` 这一段，实测不可混用）
fn emitDeprecatedFloatStrToInt(s: []const u8) void {
    var buf: [320]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "Implicit conversion from float-string \"{s}\" to int loses precision",
        .{s},
    ) catch return;
    emitDeprecated(msg);
}

/// float／数值串 → i64 的 `int` 形参口径：通过返回强转值；越界或非有限返回 null 交调用方拒；非整值就地打 Deprecated 后向零截断
fn intParamFromFloat(f: f64) ?i64 {
    if (!std.math.isFinite(f)) return null;
    const min_f: f64 = @floatFromInt(std.math.minInt(i64));
    const max_f: f64 = @floatFromInt(std.math.maxInt(i64));
    if (f > max_f or f < min_f) return null;
    if (@floor(f) != f) {
        emitDeprecatedFloatToInt(f);
        return @intFromFloat(@trunc(f));
    }
    return @intFromFloat(f);
}

/// 内置数值形参的**校验＋强转**。通过 ⇒ 返回 PHP 口径的 int／float Value（Deprecated 已就地打出）；
/// 不通过 ⇒ 置 TypeError 并返回 null。
/// `null_type`＝`Passing null` 消息里的类型文本，多数函数与 `expected` 相同，仅 `number_format` 的 `$num`
/// 不同（实测其 TypeError 写 `int|float` 而 Passing-null 写 `float`）⇒ 由调用点显式给出，不内置推断。
fn requireNumParamAs(
    fn_name: []const u8,
    arg_no: usize,
    param_name: []const u8,
    kind: NumParamKind,
    val: Value,
    null_type: ?[]const u8,
) ?Value {
    const expected = numParamExpectedText(kind);
    const is_int_kind = kind == .int_param or kind == .nullable_int_param;

    if (val.isInt()) return val;

    if (val.isFloat()) {
        if (!is_int_kind) return val;
        const i = intParamFromFloat(val.asFloat()) orelse
            return rejectParamType(fn_name, arg_no, param_name, expected, val);
        return Value.initInt(i);
    }

    if (val.isBool()) return Value.initInt(if (val.asBool()) 1 else 0);

    if (val.isNull()) {
        emitDeprecatedPassingNull(fn_name, arg_no, param_name, null_type orelse expected);
        return Value.initInt(0);
    }

    if (val.isString()) {
        const s = val.asString();
        const data = s.data[0..s.length];
        if (!isNumericString(data)) return rejectParamType(fn_name, arg_no, param_name, expected, val);
        if (strictIntFromTrimmed(data)) |i| return Value.initInt(i);
        const t = trimNumericWhitespace(data);
        const f = std.fmt.parseFloat(f64, t) catch
            return rejectParamType(fn_name, arg_no, param_name, expected, val);
        if (!is_int_kind) return Value.initFloat(f);
        // `int` 形参吃非整值语法的数值串：越界／非有限 ⇒ `string given`；非整值 ⇒ float-string Deprecated 后向零截断
        const min_f: f64 = @floatFromInt(std.math.minInt(i64));
        const max_f: f64 = @floatFromInt(std.math.maxInt(i64));
        if (!std.math.isFinite(f) or f > max_f or f < min_f) {
            return rejectParamType(fn_name, arg_no, param_name, expected, val);
        }
        if (@floor(f) != f) {
            emitDeprecatedFloatStrToInt(t);
            return Value.initInt(@intFromFloat(@trunc(f)));
        }
        return Value.initInt(@intFromFloat(f));
    }

    // array／object／其余 ⇒ 拒（对象给类名，见 `operandTypeName`）
    return rejectParamType(fn_name, arg_no, param_name, expected, val);
}

fn requireNumParam(
    fn_name: []const u8,
    arg_no: usize,
    param_name: []const u8,
    kind: NumParamKind,
    val: Value,
) ?Value {
    return requireNumParamAs(fn_name, arg_no, param_name, kind, val, null);
}

/// **可选**数值形参（PHP 侧带默认值，如 `round` 的 `$precision`、`number_format` 的 `$decimals`）。
/// ★门 BLT b72 实测：省略的可选形参在本运行时的调用约定里同样是 **null**（发射器补空参的形态），
///   与显式 null 无从区分 ⇒ 若在此打 Passing-null Deprecated，`round(null)` 会替没写的 `$precision` 多印一行，
///   语料里 `number_format($x)`／`round($x)` 这类省略写法（round 12 处、number_format 25 处）会整片多输出。
///   ⇒ 可选形只做**类型拒**（对象／array／坏串 ⇒ TypeError），null 与 missing 一律当「未提供」原样透传、不打 Deprecated。
///   代价留字：显式 `round(1.5, null)` 的 `#2 ($precision)` Deprecated 本实现不发（PHP 发），属可登记的措辞缺口，不是静默错值。
fn requireOptionalNumParam(
    fn_name: []const u8,
    arg_no: usize,
    param_name: []const u8,
    kind: NumParamKind,
    val: Value,
) ?Value {
    if (val.isNull() or val.isMissing()) return val;
    return requireNumParamAs(fn_name, arg_no, param_name, kind, val, null);
}

/// `array_sum`／`array_product`／`max`／`min` 的容器形参：非数组 ⇒ `<fn>(): Argument #N ($p) must be of type array, <类名> given`
fn requireArrayParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    if (val.isArray()) return val;
    return rejectParamType(fn_name, arg_no, param_name, "array", val);
}

/// ★F-62f（R-261）：`string` 形参的 weak 口径（标量与带 `__toString` 对象放行，其余按原文案拒）。
fn requireStringParamWeak(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    var v = val;
    while (v.isRef()) v = v.asRef().*;
    if (v.isString() or v.isInt() or v.isFloat() or v.isBool() or v.isNull()) return v;
    if (Value_isObject(v) and valueHasToStringMethod(v)) return v;
    return rejectParamType(fn_name, arg_no, param_name, "string", v);
}

/// ★F-62f（R-261）：`string|int|null` 槽（password 族 `$algo`）；float/bool 走 weak 转 int。
fn requireStringOrIntOrNullParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    var v = val;
    while (v.isRef()) v = v.asRef().*;
    if (v.isString() or v.isInt() or v.isNull() or v.isFloat() or v.isBool()) return v;
    if (Value_isObject(v) and valueHasToStringMethod(v)) return v;
    return rejectParamType(fn_name, arg_no, param_name, "string|int|null", v);
}

/// ★F-62f（R-261）：PHP options 关联数组按字符串键取值。
fn phpArrayGetStringOption(arr: *PHPArray, name: []const u8) ?Value {
    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        if (entry.key_ptr.* == .string and std.mem.eql(u8, entry.key_ptr.string.data, name)) return entry.value_ptr.*;
    }
    return null;
}

/// 选项值的弱 int 口径（PHP 实测：int；float 截断；bool 1/0；数值串解析；非数值串 ⇒ 0）。
fn phpOptionToInt(v: Value) i64 {
    var val = v;
    while (val.isRef()) val = val.asRef().*;
    if (val.isInt()) return val.asInt();
    if (val.isFloat()) {
        const f = val.asFloat();
        if (!std.math.isFinite(f)) return 0;
        return @intFromFloat(@trunc(f));
    }
    if (val.isBool()) return if (val.asBool()) 1 else 0;
    if (val.isString()) {
        const data = val.asString().data;
        if (strictIntFromTrimmed(data)) |i| return i;
        const t = trimNumericWhitespace(data);
        const f = std.fmt.parseFloat(f64, t) catch return 0;
        if (!std.math.isFinite(f)) return 0;
        return @intFromFloat(@trunc(f));
    }
    return 0;
}

/// 选项里的 bcrypt cost；缺省 12（PHP 8.5 默认）。
fn passwordBcryptCost(options_val: Value) i64 {
    if (options_val.isArray()) {
        if (phpArrayGetStringOption(options_val.asArray(), "cost")) |cv| return phpOptionToInt(cv);
    }
    return 12;
}

const PasswordAlgoKind = enum { bcrypt, argon2i, argon2id, invalid };
fn passwordAlgoKind(algo: Value) PasswordAlgoKind {
    if (algo.isNull()) return .bcrypt;
    if (algo.isBool()) return .bcrypt;
    if (algo.isInt()) {
        return switch (algo.asInt()) {
            0, 1 => .bcrypt,
            2 => .argon2i,
            3 => .argon2id,
            else => .invalid,
        };
    }
    if (algo.isFloat()) {
        const f = algo.asFloat();
        if (!std.math.isFinite(f)) return .invalid;
        return passwordAlgoKind(Value.initInt(@intFromFloat(@trunc(f))));
    }
    if (algo.isString()) {
        const s = algo.asString().data;
        if (std.mem.eql(u8, s, "2y")) return .bcrypt;
        if (std.mem.eql(u8, s, "argon2i")) return .argon2i;
        if (std.mem.eql(u8, s, "argon2id")) return .argon2id;
    }
    return .invalid;
}

/// ★F-168（R-263）：argon2 的 options（PHP 缺省 m=65536,t=4,p=1）。
const Argon2ParamsOpt = struct { m: i64, t: i64, p: i64 };

fn passwordArgon2Params(options_val: Value) Argon2ParamsOpt {
    var m: i64 = 65536;
    var t: i64 = 4;
    var p: i64 = 1;
    if (options_val.isArray()) {
        const arr = options_val.asArray();
        if (phpArrayGetStringOption(arr, "memory_cost")) |v| m = phpOptionToInt(v);
        if (phpArrayGetStringOption(arr, "time_cost")) |v| t = phpOptionToInt(v);
        if (phpArrayGetStringOption(arr, "threads")) |v| p = phpOptionToInt(v);
    }
    return .{ .m = m, .t = t, .p = p };
}

/// 从 `$argon2x$v=19$m=..,t=..,p=..$...` 解析参数；格式不符 ⇒ null。
fn passwordArgon2StoredParams(hash_str: []const u8) ?Argon2ParamsOpt {
    var idx: usize = 0;
    var dollars: usize = 0;
    while (idx < hash_str.len) : (idx += 1) {
        if (hash_str[idx] == '$') {
            dollars += 1;
            if (dollars == 3) break;
        }
    }
    if (dollars != 3) return null;
    const start = idx + 1;
    var end = start;
    while (end < hash_str.len and hash_str[end] != '$') end += 1;
    if (end >= hash_str.len) return null;

    var m: i64 = 0;
    var t: i64 = 0;
    var p: i64 = 0;
    var found_m = false;
    var found_t = false;
    var found_p = false;
    var it = std.mem.splitScalar(u8, hash_str[start..end], ',');
    while (it.next()) |kv| {
        const eq = std.mem.indexOfScalar(u8, kv, '=') orelse continue;
        const n = std.fmt.parseInt(i64, kv[eq + 1 ..], 10) catch continue;
        if (std.mem.eql(u8, kv[0..eq], "m")) {
            m = n;
            found_m = true;
        } else if (std.mem.eql(u8, kv[0..eq], "t")) {
            t = n;
            found_t = true;
        } else if (std.mem.eql(u8, kv[0..eq], "p")) {
            p = n;
            found_p = true;
        }
    }
    if (!found_m or !found_t or !found_p) return null;
    return .{ .m = m, .t = t, .p = p };
}
/// ★F-62f（R-255）：`array|string` 联合槽（substr_replace #1/#2）。
///   string/array/null 放行；对象等按 PHP 文案拒绝（数组形语义另案）。
fn requireArrayOrStringParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    if (val.isString() or val.isArray() or val.isNull()) return val;
    return rejectParamType(fn_name, arg_no, param_name, "array|string", val);
}

/// ★F-62f（R-255）：`string|int|float` 联合槽（range #1/#2）。
///   数值/字符串/bool/null 走原 weak 口径；数组/对象按 PHP 文案拒绝。
fn requireRangeBoundParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    if (val.isInt() or val.isFloat() or val.isString() or val.isBool() or val.isNull()) return val;
    return rejectParamType(fn_name, arg_no, param_name, "string|int|float", val);
}

/// ★F-62f（R-255）：`array|int` / `array|int|null` 联合槽（substr_replace #3/#4）。
///   数组与 null 放行；数值/字符串/bool 保留原 weak 口径；对象等按文案拒绝。
fn requireArrayOrIntParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, expected: []const u8, val: Value) ?Value {
    if (val.isArray() or val.isNull()) return val;
    if (val.isInt() or val.isFloat() or val.isBool() or val.isString()) return val;
    return rejectParamType(fn_name, arg_no, param_name, expected, val);
}

/// ★F-149（R-238）：bool 形参族的校验＋弱模式强转。
///   实测（PHP 8.5.8）：bool/int/float/string 按 PHP 真值（`""` 与 `"0"` 为 false）；
///   array/object ⇒ TypeError；非 nullable 的 null ⇒ Passing-null Deprecated ＋ false；`?bool` 的 null 合法。
fn requireBoolParamAs(fn_name: []const u8, arg_no: usize, param_name: []const u8, expected: []const u8, val: Value) ?Value {
    if (val.isBool()) return val;
    if (val.isInt()) return Value.initBool(val.toInt() != 0);
    if (val.isFloat()) return Value.initBool(val.asFloat() != 0.0);
    if (val.isString()) {
        const s = val.asString();
        const truth = !(s.length == 0 or (s.length == 1 and s.data[0] == '0'));
        return Value.initBool(truth);
    }
    if (val.isNull()) {
        emitDeprecatedPassingNull(fn_name, arg_no, param_name, expected);
        return Value.initBool(false);
    }
    return rejectParamType(fn_name, arg_no, param_name, expected, val);
}

fn requireBoolParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    return requireBoolParamAs(fn_name, arg_no, param_name, "bool", val);
}

fn requireNullableBoolParam(fn_name: []const u8, arg_no: usize, param_name: []const u8, val: Value) ?Value {
    if (val.isNull()) return val;
    return requireBoolParamAs(fn_name, arg_no, param_name, "?bool", val);
}

/// ★F-62 元素族（c 段）：`array_sum`／`array_product` 的**元素级**口径（真值 `/tmp/r172/f62_param_truth3_tmp.php`）：
///   · int／float ⇒ 原样计入；bool／null ⇒ **静默**计入 1／0；
///   · 完整数值串 ⇒ 按 int／float 语法计入；**前导数值串** ⇒ `Warning: A non-numeric value encountered` 后计入前缀（实测 `array_sum([1,"5a",2])`=8）；
///   · 非数值串 ⇒ `Warning: <fn>(): Addition|Multiplication is not supported on type string` 后**计入 0**（实测 `array_product([2,"abc"])`=0）；
///   · array／object ⇒ 同句式（`on type array`／`on type <类名>`）但**整枚跳过**（实测 `array_product([2,[1]])`=2、`array_sum([1,$o,2])`=3）。
///   ★这一族 PHP **只 Warning 不抛**，把它改成抛异常就是 over-fatal（与 R-155 的 count() 面同型陷阱）。
const ArrayNumElem = union(enum) { use: Value, skip: void };

fn classifyArrayNumElem(fn_name: []const u8, action: []const u8, val: Value) ArrayNumElem {
    if (val.isInt() or val.isFloat()) return .{ .use = val };
    if (val.isBool()) return .{ .use = Value.initInt(if (val.asBool()) 1 else 0) };
    if (val.isNull()) return .{ .use = Value.initInt(0) };

    if (val.isString()) {
        const s = val.asString();
        const data = s.data[0..s.length];
        if (isNumericString(data)) {
            if (strictIntFromTrimmed(data)) |i| return .{ .use = Value.initInt(i) };
            const t = trimNumericWhitespace(data);
            return .{ .use = Value.initFloat(std.fmt.parseFloat(f64, t) catch 0.0) };
        }
        if (numericPrefixValue(data)) |pv| {
            emitWarning("A non-numeric value encountered");
            return .{ .use = pv };
        }
        arrayElementNotSupported(fn_name, action, "string");
        return .{ .use = Value.initInt(0) };
    }

    if (Value_isObject(val)) {
        arrayElementNotSupported(fn_name, action, operandTypeName(val));
        return .skip;
    }
    if (val.isArray()) {
        arrayElementNotSupported(fn_name, action, "array");
        return .skip;
    }
    // 其余（指针等）按跳过处理，与 array 同句式
    arrayElementNotSupported(fn_name, action, valueTypeName(val));
    return .skip;
}

fn arrayElementNotSupported(fn_name: []const u8, action: []const u8, type_text: []const u8) void {
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "{s}(): {s} is not supported on type {s}",
        .{ fn_name, action, type_text },
    ) catch return;
    emitWarning(msg);
}

/// ★F-62 比较族（d 段）与 F-77 显式转换族**共用**的措辞（一条措辞两个严重度，实测禁互抄）：
///   `Object of class <X> could not be converted to int|float`
fn objectToNumberMsg(val: Value, target: []const u8, buf: []u8) ?[]const u8 {
    return std.fmt.bufPrint(
        buf,
        "Object of class {s} could not be converted to {s}",
        .{ operandTypeName(val), target },
    ) catch null;
}

/// F-62 比较族：object 与数值比较 ⇒ **Notice** 后 PHP 把对象当 **1**（对 int）／**1.0**（对 float）继续。
/// 实测措辞随另一侧类型变（`$o > 0.5` 印 `to float`）。
fn emitObjectToNumberNotice(val: Value, target: []const u8) void {
    var buf: [256]u8 = undefined;
    const msg = objectToNumberMsg(val, target, &buf) orelse return;
    emitNotice(msg);
}

/// ★F-77：`(int)$o`／`(float)$o`／`intval`／`floatval`／`settype($v,"int"|"float")` ⇒ **Warning**（不是比较族的
///   Notice）后给 **1／1.0**。实测（工单 §101）：带 `__toString` 的对象**同样**告警 ⇒ 转换**不**走 `__toString`，
///   禁把 stringable 当豁免；属性个数无关（空类也是 1）。
fn emitObjectToNumberWarning(val: Value, target: []const u8) void {
    var buf: [256]u8 = undefined;
    const msg = objectToNumberMsg(val, target, &buf) orelse return;
    emitWarning(msg);
}

/// ★F-77 判定用：对象可能包在 ref 里，而 `Value_isObject` **不**解引用 ⇒ 先解一层再判。
/// 只用于"是不是对象"这一判定，非对象路径一律原样交给既有转换（不改任何既有语义）。
fn derefForNumberProbe(val: Value) Value {
    if (val.isRef()) return val.asRef().*;
    return val;
}

/// `Notice` 诊断（模板此前只有 Warning／Deprecated；比较族是第一条 Notice 站点）
fn emitNotice(msg: []const u8) void {
    const loc = diagLoc();
    if (dispatchToUserHandler(E_NOTICE, msg)) |handled| {
        if (handled) return; // C4
    }
    restoreDiagLoc(loc);
    standardPrint("PHP Notice:  ", "\nNotice: ", msg, E_NOTICE);
}

/// 获取 Value 的 PHP 类型名称
fn valueTypeName(v: Value) []const u8 {
    if (v.isNull()) return "null";
    if (v.isBool()) return "bool";
    if (v.isInt()) return "int";
    if (v.isFloat()) return "float";
    if (v.isString()) return "string";
    if (v.isArray()) return "array";
    if (Value_isObject(v)) return "object";
    return "unknown";
}

/// 输出 PHP Fatal TypeError 并终止执行
fn emitTypeFatalError(func_name: []const u8, arg_num: u32, expected: []const u8, got: []const u8) noreturn {
    if (!fatalDisplayEnabled()) {
        php_run_shutdown_functions();
        std.process.exit(255);
    }
    // PHP 输出顺序：先 stderr，再 stdout
    var ebuf: [1024]u8 = undefined;
    const stderr_msg = std.fmt.bufPrint(
        &ebuf,
        "PHP Fatal error:  Uncaught TypeError: {s}(): Argument" ++
            " #{d} ($array) must be of type {s}, {s} given" ++
            " in {s}:{d}\nStack trace:\n#0 {{main}}\n" ++
            "  thrown in {s} on line {d}\n",
        .{
            func_name, arg_num,  expected, got,
            src_file,  src_line, src_file, src_line,
        },
    ) catch {
        std.process.exit(255);
    };
    fileWriteAll(2, stderr_msg);
    var buf: [1024]u8 = undefined;
    const stdout_msg = std.fmt.bufPrint(
        &buf,
        "\nFatal error: Uncaught TypeError: {s}(): Argument" ++
            " #{d} ($array) must be of type {s}, {s} given" ++
            " in {s}:{d}\nStack trace:\n#0 {{main}}\n" ++
            "  thrown in {s} on line {d}\n",
        .{
            func_name, arg_num,  expected, got,
            src_file,  src_line, src_file, src_line,
        },
    ) catch {
        fileWriteAll(1, "\nFatal error: TypeError\n");
        std.process.exit(255);
    };
    fileWriteAll(1, stdout_msg);
    php_run_shutdown_functions();
    std.process.exit(255);
}

/// 参数类型检查：当参数类型与声明不匹配时抛出 TypeError
/// PHP 8 语义：非 nullable 类型参数收到 null 时抛 TypeError
pub fn php_check_param_type(
    func_name: []const u8,
    arg_index: usize,
    arg: Value,
    expected_type: []const u8,
    is_nullable: bool,
    param_name: []const u8,
) !void {
    // 空类型声明 = 无类型约束
    if (expected_type.len == 0) return;

    // AOT-CODEGEN-010 §8 #4：参数名元数据自带 `$` 前缀，下方消息格式串又补一个 `$`
    // ⇒ 渲染成 `($$a)` 双 `$`。剥掉前导 `$` 后无论元数据带不带均正确。
    const bare_param_name = if (param_name.len > 0 and param_name[0] == '$') param_name[1..] else param_name;

    // mixed 类型隐含 nullable（PHP 8 语义：mixed 等价于所有类型含 null）
    if (containsTypeComponent(expected_type, "mixed")) return;

    // null 检查
    if (arg.isNull()) {
        if (is_nullable) return;
        // 非 nullable 类型收到 null → TypeError
        const got_type = "null";
        var buf: [768]u8 = undefined;
        const msg = paramTypeErrorText(&buf, func_name, arg_index, bare_param_name, expected_type, got_type);
        try throwThrowableDiscard("TypeError", msg, runtime_allocator);
        return;
    }

    // 类型匹配检查
    const got_type = phpGetValueTypeName(arg);
    const matches = checkTypeMatch(expected_type, got_type, arg);
    if (!matches) {
        var buf: [768]u8 = undefined;
        const msg = paramTypeErrorText(&buf, func_name, arg_index, bare_param_name, expected_type, got_type);
        try throwThrowableDiscard("TypeError", msg, runtime_allocator);
        return;
    }
}

/// ★R-281（F-182）：用户函数/方法的形参 TypeError 措辞带调用点后缀。
///   PHP 实测：`f(): Argument #1 ($x) must be of type Throwable, int given, called in <file> on line <N>`
///   —— 后缀只在**用户函数/方法**的形参校验里出现（内置函数的 ZPP 错误没有）。
///   `src_file/src_line` 在调用语句处由发射器写入，形参校验发生在被调函数第一条语句之前 ⇒ 仍是调用点。
fn paramTypeErrorText(
    buf: []u8,
    func_name: []const u8,
    arg_index: usize,
    param_name: []const u8,
    expected_type: []const u8,
    got_type: []const u8,
) []const u8 {
    if (src_file.len > 0 and src_line > 0) {
        return std.fmt.bufPrint(buf, "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given, called in {s} on line {d}", .{
            func_name, arg_index + 1, param_name, expected_type, got_type, src_file, src_line,
        }) catch "TypeError";
    }
    return std.fmt.bufPrint(buf, "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given", .{
        func_name, arg_index + 1, param_name, expected_type, got_type,
    }) catch "TypeError";
}

/// 弱类型模式下的值强制转换（PHP 非严格模式）
/// 仅对标量类型（int/float/bool/string）执行转换，其他类型原样返回
pub fn php_coerce_value(val: Value, expected_type: []const u8, allocator: Allocator) Value {
    // 组合类型不做值转换（只做类型检查）
    if (std.mem.indexOfScalar(u8, expected_type, '|') != null) return val;
    if (std.mem.indexOfScalar(u8, expected_type, '&') != null) return val;

    if (std.mem.eql(u8, expected_type, "int")) {
        if (val.isInt()) return val;
        if (val.isFloat() or val.isBool() or val.isNull() or val.isString())
            return Value.initInt(val.toInt());
        return val;
    }
    if (std.mem.eql(u8, expected_type, "float")) {
        if (val.isFloat()) return val;
        if (val.isInt() or val.isBool() or val.isNull() or val.isString())
            return Value.initFloat(val.toFloat());
        return val;
    }
    if (std.mem.eql(u8, expected_type, "bool")) {
        if (val.isBool()) return val;
        return Value.initBool(val.toBool());
    }
    if (std.mem.eql(u8, expected_type, "string")) {
        if (val.isString()) return val;
        if (val.isInt() or val.isFloat() or val.isBool() or val.isNull()) {
            const s = val.toString(allocator) catch return val;
            return Value.initString(s);
        }
        return val;
    }
    return val;
}

/// ★F-35（R-334）：返回值类型校验＋coerce（PHP 8.5.8 真值矩阵＝工单 §234.3）。
///   与 `php_coerce_value`（静默强转旧面，参数弱化等既有调用点不动）分工：
///   本函数是 ret 收口点的 PHP 语义完备版——先精确匹配（`checkTypeMatch` 含类名 CI/继承链/union 各支），
///   失败按 strict/coerce 分流：strict 仅放行 int→float 拓宽；coerce 覆盖四标量强转＋
///   float→int 精度损失 Deprecated；仍不符 ⇒ TypeError「{fn}(): Return value must be of type {decl}, {got} returned」。
///   strict 位＝编译期常量（nlk 从 Module.strict_types 挂载直写字面量）；静态快速路径在发射侧
///   （编译期类型已精确匹配的返回点不生成对本函数的调用——零运行期开销）。
pub fn php_check_return_type(fn_name: []const u8, val: Value, type_decl: []const u8, nullable: bool, strict: bool) !Value {
    if (type_decl.len == 0) return val;
    if (containsTypeComponent(type_decl, "mixed")) return val;

    // null：nullable／union 含 null ⇒ 放行；否则 TE「…, null returned」
    if (val.isNull()) {
        if (nullable or containsTypeComponent(type_decl, "null")) return val;
        return throwReturnTypeError(fn_name, type_decl, nullable, "null");
    }

    const got = phpGetValueTypeName(val);
    // 精确匹配（严格版：标量互通宽松支是参数面「可弱转」语义，返回面须先精确再决定转/抛）
    if (checkReturnTypeStrict(type_decl, got, val)) return val;

    // strict：仅 int→float 拓宽豁免（f35b 实测 float(5) 放行）
    if (strict) {
        if (std.mem.eql(u8, type_decl, "float") and val.isInt()) {
            return Value.initFloat(@floatFromInt(val.asInt()));
        }
        return throwReturnTypeError(fn_name, type_decl, nullable, got);
    }

    // coerce：四标量强转（单类型声明；union 非精确支按 PHP 弱转优先级面超出本批钉板范围 ⇒ TE 兜底）
    if (std.mem.eql(u8, type_decl, "int")) {
        if (val.isFloat()) {
            const f = val.asFloat();
            if (std.math.isFinite(f) and f != @trunc(f)) emitDeprecatedFloatToInt(f);
            return Value.initInt(val.toInt());
        }
        if (val.isString()) {
            const data = val.asString().data;
            // 严格整串（"5"）直转；浮点数字串（"5.5"）Deprecated+截断；非数字 ⇒ TE
            if (tryAsInt(val)) |i| return Value.initInt(i);
            if (isNumericString(data)) {
                emitDeprecatedFloatStrToInt(data);
                const f = std.fmt.parseFloat(f64, data) catch
                    return throwReturnTypeError(fn_name, type_decl, nullable, got);
                return Value.initInt(@intFromFloat(@trunc(f)));
            }
            return throwReturnTypeError(fn_name, type_decl, nullable, got);
        }
        if (val.isBool()) return Value.initInt(if (val.asBool()) 1 else 0);
        return throwReturnTypeError(fn_name, type_decl, nullable, got);
    }
    if (std.mem.eql(u8, type_decl, "float")) {
        if (val.isInt()) return Value.initFloat(@floatFromInt(val.asInt()));
        if (val.isString() and isNumericString(val.asString().data)) return Value.initFloat(val.toFloat());
        if (val.isBool()) return Value.initFloat(if (val.asBool()) 1.0 else 0.0);
        return throwReturnTypeError(fn_name, type_decl, nullable, got);
    }
    if (std.mem.eql(u8, type_decl, "string")) {
        if (val.isInt() or val.isFloat() or val.isBool()) {
            const s = val.toString(runtime_allocator) catch
                return throwReturnTypeError(fn_name, type_decl, nullable, got);
            return Value.initString(s);
        }
        return throwReturnTypeError(fn_name, type_decl, nullable, got);
    }
    if (std.mem.eql(u8, type_decl, "bool")) {
        if (val.isInt() or val.isFloat() or val.isString()) return Value.initBool(val.toBool());
        return throwReturnTypeError(fn_name, type_decl, nullable, got);
    }
    // object/array/类名/iterable/callable/resource 等：不可强转 ⇒ TE
    return throwReturnTypeError(fn_name, type_decl, nullable, got);
}

/// F-35：返回值 TypeError 单点构造（措辞实测：「{fn}(): Return value must be of type {decl}, {got} returned」；
/// nullable 声明在 PHP 措辞里带 `?` 前缀）。
fn throwReturnTypeError(fn_name: []const u8, type_decl: []const u8, nullable: bool, got: []const u8) !Value {
    var buf: [768]u8 = undefined;
    const msg = if (nullable)
        std.fmt.bufPrint(&buf, "{s}(): Return value must be of type ?{s}, {s} returned", .{ fn_name, type_decl, got }) catch "Return value must be of declared type"
    else
        std.fmt.bufPrint(&buf, "{s}(): Return value must be of type {s}, {s} returned", .{ fn_name, type_decl, got }) catch "Return value must be of declared type";
    try throwThrowableDiscard("TypeError", msg, runtime_allocator);
    return Value.initNull();
}

/// ★F-35（R-334）：返回值面的**严格精确**匹配。
///   与 `checkSingleType` 的差异：后者 9360-9390 六支标量互通是**参数面**「可弱转」语义
///   （调用点随后做值转换）；返回面必须先精确判定、再自行决定强转或 TypeError ⇒
///   互通支在此不存在。类名继承/接口/union/intersection/伪类型各支照 checkSingleType 精确口径。
fn checkReturnTypeStrict(type_decl: []const u8, got: []const u8, val: Value) bool {
    var exp = std.mem.trim(u8, type_decl, " ");
    while (exp.len > 0 and exp[0] == '\\') exp = exp[1..];
    if (exp.len == 0) return true;

    // union 逐支（含 intersection 成员）
    if (std.mem.indexOfScalar(u8, exp, '|') != null) {
        var it = std.mem.splitScalar(u8, exp, '|');
        while (it.next()) |part| {
            if (checkReturnTypeStrict(part, got, val)) return true;
        }
        return false;
    }
    // intersection：仅对象面（逐支类名/接口）
    if (std.mem.indexOfScalar(u8, exp, '&') != null) {
        if (!Value_isObject(val)) return false;
        var it = std.mem.splitScalar(u8, exp, '&');
        while (it.next()) |part| {
            if (!checkReturnTypeStrict(part, got, val)) return false;
        }
        return true;
    }

    // 单类型
    if (std.mem.eql(u8, exp, got)) return true;
    if (std.mem.eql(u8, exp, "mixed")) return true;
    if (std.mem.eql(u8, exp, "null")) return val.isNull();
    if (std.mem.eql(u8, exp, "object")) return Value_isObject(val) or val.isFunction();
    if (std.mem.eql(u8, exp, "iterable")) {
        if (val.isArray()) return true;
        if (Value_isObject(val)) {
            const obj = Value_asObject(val);
            if (obj.class_meta) |meta| {
                if (meta.implementsInterface("Traversable")) return true;
            }
        }
        return false;
    }
    if (std.mem.eql(u8, exp, "callable")) {
        if (val.isFunction()) return true;
        const result = php_is_callable(val) catch return false;
        return result.isBool() and result.asBool();
    }
    if (std.mem.eql(u8, exp, "Closure")) {
        if (val.isFunction()) return true;
        if (Value_isObject(val)) {
            const obj = Value_asObject(val);
            if (obj.class_meta) |meta| {
                if (std.mem.eql(u8, meta.name, "Closure")) return true;
            }
        }
        return false;
    }
    if (std.mem.eql(u8, exp, "static")) {
        if (!Value_isObject(val)) return false;
        const obj = Value_asObject(val);
        if (obj.class_meta) |meta| {
            if (getCurrentCalledClass()) |called_class| {
                if (meta.isSubclassOf(called_class.name)) return true;
            }
        }
        return false;
    }
    // 类名：继承链 + 接口
    if (Value_isObject(val)) {
        const obj = Value_asObject(val);
        if (obj.class_meta) |meta| {
            if (meta.isSubclassOf(exp)) return true;
            if (meta.implementsInterface(exp)) return true;
        }
    }
    return false;
}

/// 获取 Value 的 PHP 类型名称
fn phpGetValueTypeName(val: Value) []const u8 {
    if (val.isNull()) return "null";
    if (val.isBool()) return "bool";
    if (val.isInt()) return "int";
    if (val.isFloat()) return "float";
    if (val.isString()) return "string";
    if (val.isArray()) return "array";
    if (Value_isObject(val)) {
        if (Value_asObject(val).class_meta) |meta| return meta.name;
        return "object";
    }
    if (val.isFunction()) return "Closure";
    if (val.isRef()) {
        return phpGetValueTypeName(val.asRef().*);
    }
    return "unknown";
}

/// 检查类型声明中是否包含某个类型名作为完整组件（按 | 和 & 分割）
fn containsTypeComponent(type_str: []const u8, target: []const u8) bool {
    var it = std.mem.tokenizeAny(u8, type_str, "|&() ");
    while (it.next()) |part| {
        var n = part;
        while (n.len > 0 and n[0] == '\\') n = n[1..];
        if (std.mem.eql(u8, n, target)) return true;
    }
    return false;
}

/// 检查类型是否匹配（PHP 8 类型系统，支持 union/intersection/DNF/命名空间前缀）
fn checkTypeMatch(expected: []const u8, got: []const u8, arg: Value) bool {
    // 去掉空格和前导反斜杠
    var exp = std.mem.trim(u8, expected, " ");
    while (exp.len > 0 and exp[0] == '\\') exp = exp[1..];

    // 空类型 = 无约束
    if (exp.len == 0) return true;

    // union 类型（包含 |）
    if (std.mem.indexOfScalar(u8, exp, '|') != null) {
        return checkUnionType(exp, got, arg);
    }

    // intersection 类型（包含 &）
    if (std.mem.indexOfScalar(u8, exp, '&') != null) {
        return checkIntersectionType(exp, got, arg);
    }

    // 单一类型
    return checkSingleType(exp, got, arg);
}

/// 去掉类型名前导反斜杠和空格
fn normalizeTypeName(name: []const u8) []const u8 {
    var n = std.mem.trim(u8, name, " ");
    while (n.len > 0 and n[0] == '\\') n = n[1..];
    return n;
}

/// union 类型检查：匹配任一成员即可（如 "int|string|null"）
fn checkUnionType(expected: []const u8, got: []const u8, arg: Value) bool {
    var it = std.mem.splitScalar(u8, expected, '|');
    while (it.next()) |part| {
        const normalized = normalizeTypeName(part);
        if (normalized.len == 0) continue;

        // 每个成员可能是 intersection 类型
        if (std.mem.indexOfScalar(u8, normalized, '&') != null) {
            if (checkIntersectionType(normalized, got, arg)) return true;
        } else {
            if (checkSingleType(normalized, got, arg)) return true;
        }
    }
    return false;
}

/// intersection 类型检查：必须匹配所有成员（如 "Cacheable&Loggable"）
fn checkIntersectionType(expected: []const u8, got: []const u8, arg: Value) bool {
    // 对非对象类型，intersection 无意义
    if (!Value_isObject(arg)) return false;

    var it = std.mem.splitScalar(u8, expected, '&');
    while (it.next()) |part| {
        const normalized = normalizeTypeName(part);
        if (normalized.len == 0) continue;
        if (!checkSingleType(normalized, got, arg)) return false;
    }
    return true;
}

/// 单一类型检查
fn checkSingleType(expected: []const u8, got: []const u8, arg: Value) bool {
    // 精确匹配
    if (std.mem.eql(u8, expected, got)) return true;

    // int/float 兼容（PHP 弱类型）
    if (std.mem.eql(u8, expected, "float") and std.mem.eql(u8, got, "int")) return true;

    // bool → int/float（PHP 弱类型）
    if ((std.mem.eql(u8, expected, "int") or std.mem.eql(u8, expected, "float")) and
        std.mem.eql(u8, got, "bool"))
        return true;

    // float → int（PHP 弱类型，可能有精度损失警告但允许）
    if (std.mem.eql(u8, expected, "int") and std.mem.eql(u8, got, "float")) return true;

    // bool 接受 int（PHP 弱类型）
    if (std.mem.eql(u8, expected, "bool") and std.mem.eql(u8, got, "int")) return true;

    // PHP 弱类型：数字字符串可转为 int/float
    if ((std.mem.eql(u8, expected, "int") or std.mem.eql(u8, expected, "float")) and
        std.mem.eql(u8, got, "string") and arg.isString())
    {
        const s = arg.asString();
        if (isNumericString(s.data[0..s.length])) return true;
    }

    // PHP 弱类型：int/float/bool 可转为 string
    if (std.mem.eql(u8, expected, "string") and
        (std.mem.eql(u8, got, "int") or std.mem.eql(u8, got, "float") or std.mem.eql(u8, got, "bool")))
        return true;

    // PHP 弱类型：bool 接受 float/string
    if (std.mem.eql(u8, expected, "bool")) {
        if (std.mem.eql(u8, got, "float")) return true;
        if (std.mem.eql(u8, got, "string")) return true;
    }

    // mixed 接受任何类型
    if (std.mem.eql(u8, expected, "mixed")) return true;

    // static: 后期静态绑定（运行时类名）
    if (std.mem.eql(u8, expected, "static")) {
        if (!Value_isObject(arg)) return false;
        const obj = Value_asObject(arg);
        if (obj.class_meta) |meta| {
            if (getCurrentCalledClass()) |called_class| {
                if (meta.isSubclassOf(called_class.name)) return true;
            }
        }
        return false;
    }

    // null 类型
    if (std.mem.eql(u8, expected, "null")) return arg.isNull();

    // object 伪类型：接受任何对象实例（闭包在 PHP 侧就是 Closure 实例 ⇒ 一并接受）
    if (std.mem.eql(u8, expected, "object")) {
        return Value_isObject(arg) or arg.isFunction();
    }

    // callable: 深度验证（复用 php_is_callable）
    if (std.mem.eql(u8, expected, "callable")) {
        // Closure 直接通过
        if (arg.isFunction()) return true;
        // 复用 php_is_callable 做深度验证（函数名存在性、array 格式、__invoke 等）
        const result = php_is_callable(arg) catch return false;
        return result.isBool() and result.asBool();
    }

    // iterable 伪类型：array 或实现 Traversable 的对象（PHP 语义；AOT-CODEGEN-010 §8 #4 ——
    // 原先无此分支落到类名检查 ⇒ `iterable` 参数收到数组被拒 TypeError）
    if (std.mem.eql(u8, expected, "iterable")) {
        if (arg.isArray()) return true;
        if (Value_isObject(arg)) {
            const obj = Value_asObject(arg);
            if (obj.class_meta) |meta| {
                if (meta.implementsInterface("Traversable")) return true;
            }
        }
        return false;
    }

    // Closure 类型
    if (std.mem.eql(u8, expected, "Closure")) {
        if (arg.isFunction()) return true;
        if (Value_isObject(arg)) {
            const obj = Value_asObject(arg);
            if (obj.class_meta) |meta| {
                if (std.mem.eql(u8, meta.name, "Closure")) return true;
            }
        }
        return false;
    }

    // 类类型检查：父类/接口
    if (Value_isObject(arg)) {
        const obj = Value_asObject(arg);
        if (obj.class_meta) |meta| {
            // 检查类名匹配（含继承）
            if (meta.isSubclassOf(expected)) return true;
            // 检查接口实现
            if (meta.implementsInterface(expected)) return true;
        }
    }

    return false;
}

/// ★R-342（§269）：调用未定义函数 ⇒ **可捕获** Error「Call to undefined function X()」
///   （throwThrowable 契约：setException 置旗 + 返回异常 Value 非 Zig error）——与批次十六①
///   变量调用面（:13086）同口径；未捕获走既有未捕获 fatal 通道（输出形态与 PHP 一致）。
///   旧实现 noreturn+exit(255) 绕过整条 catch 路由（try/catch 里调用未定义函数被硬终止）。
pub fn php_call_undefined_function(name: []const u8, allocator: Allocator) !Value {
    var ubuf: [512]u8 = undefined;
    const umsg = std.fmt.bufPrint(&ubuf, "Call to undefined function {s}()", .{name}) catch "Call to undefined function";
    return throwThrowable("Error", umsg, allocator);
}

/// 输出 PHP 8.1+ Deprecated 警告到 stdout（匹配 display_errors=On）
// ============================================================================
// F-69：float→int 的 PHP 语义。★**值型规则与诊断刻意分家**——
//   `native_linker` 会把 `.toInt()` 直接写进生成码的 `switch`／`!`／赋值／形参装填位
//   （:19458/:19492/:20269/:21416/:22116/:22188 一类站点），那些位置 PHP 不发任何诊断
//   ⇒ **取值函数必须纯净**，告警一律挂在"确实发生 PHP 转换"的调用点。
// 规格与逐位等价证明＝工单 §54.1／§56 ＋ 资产 `c069_float_to_int_equiv_tmp.zig`（430 枚 PHP 真值：bad_val=0 bad_warn=0 bad_dep=0 bad_mod=0）。
// ============================================================================

/// 界闭下开上 `[-2^63, 2^63)` ⇒ 向零截断；界外 ⇒ 该 double 整数值的 **mod 2^64 补码回绕**。
/// ★实测否证「`|v| ≥ 2^64` ⇒ 恒 0」这条区制：`(int)1e20` = `7766279631452241920`（＝1e20 − 5·2^64）；
///   `2^65`／`±1e308` 给 0 只是"恰为 2^64 整数倍"的自然结果，不是一条独立区制。
/// ★全程只用 IEEE 位型，**不碰越界 `@intFromFloat`**（那是 Zig 非法行为；本仓另有 8 处这么写，见工单 §56.3 的三种契约分类）。
fn floatToIntPHP(f: f64) i64 {
    const two_pow_63: f64 = @floatFromInt(std.math.maxInt(i64));
    if (f >= -two_pow_63 and f < two_pow_63) return @intFromFloat(f);
    const bits: u64 = @bitCast(f);
    const exp11: u32 = @intCast((bits >> 52) & 0x7FF);
    if (exp11 == 0) return 0; // 次正规必在界内，到不了这里 ⇒ 防御性归零
    const m: u128 = @as(u128, (1 << 52) | (bits & ((@as(u64, 1) << 52) - 1)));
    const s: i32 = @as(i32, @intCast(exp11)) - 1075; // f = m × 2^s
    if (s >= 64) return 0; // `m << s` 的低 64 位必为 0 ⇒ INF／-INF／NAN 自然落到这里（与实测同值）
    const low: u64 = if (s <= 0) @truncate(m) else @truncate(m << @intCast(s));
    const wrapped: u64 = if (bits >> 63 == 1) (~low) +% 1 else low;
    return @bitCast(wrapped);
}

/// ★告警条件是**闭下界、开上界**：恰 `-2^63` 界内不告警，`+2^63` 越界告警（实测）；NAN 与任何比较都是 false ⇒ 天然判越界。
fn floatNotRepresentableAsInt(f: f64) bool {
    const two_pow_63: f64 = @floatFromInt(std.math.maxInt(i64));
    return !(f >= -two_pow_63 and f < two_pow_63);
}

/// PHP 8.5.8 实测原句：`The float <repr> is not representable as an int, cast occurred`
///   · repr 走**最短往返（序列化）口径 ＋ 大写 E**：`1.0E+19`／`1.5E+19`／`9.223372036854776E+18`／`INF`／`-INF`／`NAN`；
///   · 显式站点（`(int)`／`intval`／`%d %u %x %X %o %b %c`／`settype`）**与**隐式算术／数组键站点都发（§54.1 四条组合），
///     且**每次转换各发一条**（实测 sprintf 七枚 specifier 扫一遍＝7 条）。
fn warnFloatToIntNotRepresentable(v: Value) void {
    if (!v.isFloat()) return; // ★与既有 emitFloatToIntDeprecatedIfNeeded 同局限：ref 包 float 不在本批扩面（F-78）
    const f = v.asFloat();
    if (!floatNotRepresentableAsInt(f)) return;
    var rbuf: [64]u8 = undefined;
    const repr = phpFormatFloatSerialize(&rbuf, f, true, true);
    var mbuf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&mbuf, "The float {s} is not representable as an int, cast occurred", .{repr}) catch return;
    emitWarning(msg);
}

/// sprintf／printf 的 int 族 specifier 共用：先按 PHP 发「不可表示」告警，再取 int 值。
fn castIntArgWithWarn(arg: Value) i64 {
    warnFloatToIntNotRepresentable(arg);
    return arg.toInt();
}

fn emitDeprecatedFloatToInt(f: f64) void {
    // ★F-115 同族收口（由 R-193 接线暴露）：本函数**直写** fd2/fd1，绕过了 `standardPrint` 的 C2 抑制位
    //   ⇒ 修前 `@str_repeat("a", 2.5)` 照打两行 Deprecated，而 PHP 8.5.8 实测 `@` 下一行不打（门 F2I g8 由 SAME 转 DIFF 抓住）。
    //   此处只补抑制位，**不改** 措辞／两行格式／顺序（`{d}` 与序列化口径是 F-69 实测档，动不得）。
    //   ★F-125-d：同族另两站点已在 R-208 接线（先 dispatchToUserHandler，再 isErrorSuppressed）；
    //     本函数此前仍绕过 handler ⇒ `set_error_handler` 收不到这条 E_DEPRECATED（PHP 实测在 `@` 下也调用 handler）。
    // 警告信息中使用完整精度（PHP serialize_precision），不是 echo 的 precision=14
    var fbuf: [64]u8 = undefined;
    // ★F-69：`{d}` 把 NAN 印成**小写** `nan`，而 PHP 8.5.8 实测发大写原词 `NAN`（`INF`／`-INF` 同理）
    //   ⇒ 非有限值改走序列化口径（`renderFloatPHP` 对非有限直接返回 `NAN`／`INF`／`-INF`）。
    //   有限值**仍用 `{d}`**：它就是最短往返十进制，且界内非整值（如 `2.5`）的既有语料读数逐字不能动。
    const fstr = if (std.math.isFinite(f))
        std.fmt.bufPrint(&fbuf, "{d}", .{f}) catch "?"
    else
        phpFormatFloatSerialize(&fbuf, f, false, true);
    // ★F-125-d：handler 先于抑制（PHP 在 @ 下仍调用 handler）；processor 收到的是裸消息。
    var hbuf: [512]u8 = undefined;
    const hmsg = std.fmt.bufPrint(&hbuf, "Implicit conversion from float {s} to int loses precision", .{fstr}) catch "Implicit conversion from float to int loses precision";
    const loc = diagLoc();
    if (dispatchToUserHandler(E_DEPRECATED, hmsg)) |handled| {
        if (handled) return;
    }
    restoreDiagLoc(loc);
    if (isErrorSuppressed()) return;
    if ((E_DEPRECATED & global_error_types) == 0) return; // ★F-95：掩码静默标准显示
    // PHP 输出顺序：先 stderr，再 stdout
    var err_buf: [512]u8 = undefined;
    const stderr_msg = std.fmt.bufPrint(
        &err_buf,
        "PHP Deprecated:  Implicit conversion from" ++
            " float {s} to int loses precision in {s}" ++
            " on line {d}\n",
        .{ fstr, src_file, src_line },
    ) catch return;
    fileWriteAll(2, stderr_msg);
    var msg_buf: [512]u8 = undefined;
    const stdout_msg = std.fmt.bufPrint(
        &msg_buf,
        "\nDeprecated: Implicit conversion from float" ++
            " {s} to int loses precision in {s} on line" ++
            " {d}\n",
        .{ fstr, src_file, src_line },
    ) catch return;
    fileWriteAll(1, stdout_msg);
}

/// 幂运算（PHP语义：两 int 操作数且结果不溢出 i64 时返回 int）
pub fn php_pow(base: Value, exp: Value) !Value {
    // ★F-55（R-171）：`**` 与 `pow()` 此前**漏发** `A non-numeric value encountered`（门 NST n15 实测：
    //   PHP 侧两行 Warning 齐全，AOT 只给了正确的值 `25` 却没有警告），而 add/sub/mul/div/mod 都发了。
    //   次序照 PHP：先警告、再操作数类型检查。
    emitArithmeticStringWarningIfNeeded(base);
    emitArithmeticStringWarningIfNeeded(exp);
    // ★F-46（R-165）：幂运算同样要过操作数类型检查（实测 `[1] ** 2` ⇒ `array ** int`、`2 ** [1]` ⇒ `int ** array`）
    if (!checkArithmeticOperand(base) or !checkArithmeticOperand(exp)) {
        return throwUnsupportedOperandError(base, exp, "**");
    }
    // 两 int 操作数：尝试整數幂
    // ★F-55（R-171）：旧条件 `base.isInt() and exp.isInt()` ⇒ `'5' ** 2` 落 float 得 `25.0`（PHP 是 int 25）。
    //   改走宽松前缀判据，且**必须用判据解析出的值**——原来的 `base.asInt()` 对字符串寄存器是 NaN-boxing 兜底（读成 0）。
    if (tryAsIntLoose(base)) |b| {
        if (tryAsIntLoose(exp)) |e| {
        // 负指数 → 浮点
        if (e < 0) {
            return Value.initFloat(libmPow(@floatFromInt(b), @floatFromInt(e)));
        }
        // 0^0 = 1, 0^n = 0
        if (e == 0) return Value.initInt(1);
        if (b == 0) return Value.initInt(0);
        // ★R-170 边界：下面的逐次乘法只靠「溢出」退出，而 |b| == 1 **永不溢出**
        //   ⇒ `1 ** 1000000000000`／`(-1) ** 1000000000000` 会循环一万亿次（挂死）。
        //   |b| >= 2 时最多 63 步即溢出，所以下面的循环本身是有界的；只需把 ±1 提前收掉（PHP 亦为 int 1/±1）。
        if (b == 1) return Value.initInt(1);
        if (b == -1) return Value.initInt(if (@mod(e, 2) == 0) @as(i64, 1) else @as(i64, -1));
        // 逐次乘法 + 溢出检测
        var result: i64 = 1;
        var i: i64 = 0;
        while (i < e) : (i += 1) {
            const mul_res = @mulWithOverflow(result, b);
            if (mul_res[1] != 0) {
                // 溢出 → 浮点
                return Value.initFloat(libmPow(@floatFromInt(b), @floatFromInt(e)));
            }
            result = mul_res[0];
        }
        return Value.initInt(result);
        }
    }
    const b = base.toFloat();
    const e = exp.toFloat();
    return Value.initFloat(libmPow(b, e));
}

// ============================================================================
// 比较运算符
// ============================================================================

/// 等于运算（PHP语义：类型转换后比较）
pub fn php_eq(lhs: Value, rhs: Value) !Value {
    const actual_lhs = if (lhs.isRef()) lhs.asRef().* else lhs;
    const actual_rhs = if (rhs.isRef()) rhs.asRef().* else rhs;

    if (actual_lhs.isArray() and actual_rhs.isArray()) {
        const a = actual_lhs.asArray();
        const b = actual_rhs.asArray();
        if (a.elements.count() != b.elements.count()) return Value.initBool(false);

        var iter = a.elements.iterator();
        while (iter.next()) |entry| {
            const key = entry.key_ptr.*;
            const val = entry.value_ptr.*;
            const other_val = b.elements.get(key) orelse return Value.initBool(false);
            const eq = try php_eq(val, other_val);
            if (!eq.asBool()) return Value.initBool(false);
        }
        return Value.initBool(true);
    }

    if (Value_isObject(actual_lhs) and Value_isObject(actual_rhs)) {
        return Value.initBool(Value_asObject(actual_lhs) == Value_asObject(actual_rhs));
    }

    return Value.initBool(phpCompare(actual_lhs, actual_rhs) == 0);
}

// 辅助函数：字符串转数字（PHP 语义）
fn stringToNumber(str: []const u8) f64 {
    if (str.len == 0) return 0.0;

    // 跳过前导空格
    var i: usize = 0;
    while (i < str.len and std.ascii.isWhitespace(str[i])) : (i += 1) {}
    if (i == str.len) return 0.0;

    const trimmed = str[i..];

    // 尝试解析为整数或浮点数
    if (std.fmt.parseInt(i64, trimmed, 10)) |int_val| {
        return @floatFromInt(int_val);
    } else |_| {
        if (std.fmt.parseFloat(f64, trimmed)) |float_val| {
            return float_val;
        } else |_| {
            // PHP: 非数字字符串转为 0
            return 0.0;
        }
    }
}

/// 不等于运算
pub fn php_ne(lhs: Value, rhs: Value) !Value {
    const result = try php_eq(lhs, rhs);
    return Value.initBool(!result.asBool());
}

/// 全等运算（PHP语义：类型和值都相等）
fn php_array_key_identical(lhs: ArrayKey, rhs: ArrayKey) bool {
    return switch (lhs) {
        .integer => |li| switch (rhs) {
            .integer => |ri| li == ri,
            else => false,
        },
        .string => |ls| switch (rhs) {
            .string => |rs| std.mem.eql(u8, ls.data, rs.data),
            else => false,
        },
    };
}

fn php_array_identical(lhs: *PHPArray, rhs: *PHPArray) anyerror!bool {
    if (lhs.elements.count() != rhs.elements.count()) return false;

    var lhs_iter = lhs.elements.iterator();
    var rhs_iter = rhs.elements.iterator();
    while (true) {
        const lhs_entry = lhs_iter.next();
        const rhs_entry = rhs_iter.next();
        if (lhs_entry == null or rhs_entry == null) {
            return lhs_entry == null and rhs_entry == null;
        }

        const l = lhs_entry.?;
        const r = rhs_entry.?;
        if (!php_array_key_identical(l.key_ptr.*, r.key_ptr.*)) return false;
        if (!(try php_identical(l.value_ptr.*, r.value_ptr.*)).toBool()) return false;
    }
}

pub fn php_identical(lhs: Value, rhs: Value) !Value {
    // 类型不同
    if (lhs.isNull() != rhs.isNull()) return Value.initBool(false);
    if (lhs.isBool() != rhs.isBool()) return Value.initBool(false);
    if (lhs.isInt() != rhs.isInt()) return Value.initBool(false);
    if (lhs.isFloat() != rhs.isFloat()) return Value.initBool(false);
    if (lhs.isString() != rhs.isString()) return Value.initBool(false);
    if (lhs.isArray() != rhs.isArray()) return Value.initBool(false);

    // 类型相同，比较值
    if (lhs.isNull()) return Value.initBool(true);
    if (lhs.isBool()) return Value.initBool(lhs.asBool() == rhs.asBool());
    if (lhs.isInt()) return Value.initBool(lhs.asInt() == rhs.asInt());
    if (lhs.isFloat()) return Value.initBool(lhs.asFloat() == rhs.asFloat());
    if (lhs.isString()) {
        const a = lhs.asString();
        const b = rhs.asString();
        return Value.initBool(std.mem.eql(u8, a.data, b.data));
    }
    if (lhs.isArray()) {
        return Value.initBool(try php_array_identical(lhs.asArray(), rhs.asArray()));
    }

    // Object: 同一引用才 identical（指针比较）
    if (Value_isObject(lhs) and Value_isObject(rhs)) {
        return Value.initBool(Value_asObject(lhs) == Value_asObject(rhs));
    }

    return Value.initBool(false);
}

/// 不全等运算
pub fn php_not_identical(lhs: Value, rhs: Value) !Value {
    const result = try php_identical(lhs, rhs);
    return Value.initBool(!result.asBool());
}

/// PHP 8 比较核心：返回 -1, 0, 1
fn phpCompare(lhs: Value, rhs: Value) i2 {
    // PHP 8 comparison table (in priority order):
    // 1. null|string vs string → null→"", string comparison
    // 2. bool|null vs anything → both→bool, false < true
    // 3. int vs int → integer comparison
    // 4. number vs number (at least one float) → float comparison
    // 5. string vs string → numeric strings: number cmp, else lexicographic
    // 6. string vs number → convert string to number
    // 7. array vs non-array → array is always greater

    // Rule 1: null|string vs string → string comparison
    if ((lhs.isNull() or lhs.isString()) and rhs.isString()) {
        if (lhs.isNull()) {
            const r = rhs.asString();
            if (r.length == 0) return 0;
            return -1;
        }
        // both string → fall through to Rule 5
    } else if (lhs.isString() and (rhs.isNull() or rhs.isString())) {
        if (rhs.isNull()) {
            const l = lhs.asString();
            if (l.length == 0) return 0;
            return 1;
        }
        // both string → fall through to Rule 5
    } else if (lhs.isNull() or lhs.isBool() or rhs.isNull() or rhs.isBool()) {
        // Rule 2: bool|null vs non-string → bool comparison
        const lb = lhs.toBool();
        const rb = rhs.toBool();
        if (!lb and rb) return -1;
        if (lb and !rb) return 1;
        return 0;
    }

    // Rule 2b（★F-62 d 段，R-172）：object 与**数值**比较 ⇒ PHP 先打 Notice，再把对象当 **1**（另一侧为 int）／**1.0**（另一侧为 float）继续。
    //   实测：`$o > 0`＝true、`$o == 1`＝true、`$o == 2`＝false、`$o <=> 2`＝-1、`1 < $o`＝false、`$o >= 1`＝true、`$o <= 0`＝false，
    //   而 `$o > 0.5`＝true 且措辞换成 `could not be converted to float` ⇒ 措辞随另一侧类型，见 `emitObjectToNumberNotice`。
    //   ★必须排在 Rule 2 之后：`$o > true` 走 bool 比较且**无 Notice**（实测 false）。
    if (Value_isObject(lhs) and (rhs.isInt() or rhs.isFloat())) {
        emitObjectToNumberNotice(lhs, if (rhs.isFloat()) "float" else "int");
        const r = rhs.toFloat();
        if (@as(f64, 1) < r) return -1;
        if (@as(f64, 1) > r) return 1;
        return 0;
    }
    if (Value_isObject(rhs) and (lhs.isInt() or lhs.isFloat())) {
        emitObjectToNumberNotice(rhs, if (lhs.isFloat()) "float" else "int");
        const l = lhs.toFloat();
        if (l < @as(f64, 1)) return -1;
        if (l > @as(f64, 1)) return 1;
        return 0;
    }

    // Rule 2c（同段）：object vs string／array ⇒ **对象恒大于**且**无 Notice**。
    //   实测：`$o > "abc"`＝true、`"abc" > $o`＝false、`$o > [1]`＝true、`[1] > $o`＝false、`$o <=> "a"`＝1、`$o <=> [1]`＝1、`$o == ""`＝false
    //   ⇒ 与下面 Rule 7「array 恒大于非 array」相冲，本支必须先拦截 object 那一侧。
    if (Value_isObject(lhs) and (rhs.isString() or rhs.isArray())) return 1;
    if (Value_isObject(rhs) and (lhs.isString() or lhs.isArray())) return -1;

    // Rule 3: int vs int
    if (lhs.isInt() and rhs.isInt()) {
        const l = lhs.asInt();
        const r = rhs.asInt();
        if (l < r) return -1;
        if (l > r) return 1;
        return 0;
    }

    // Rule 6 (PHP 8): number vs string
    // PHP 8: numeric string → compare as numbers
    //        non-numeric string → convert number to string, compare as strings
    if ((lhs.isInt() or lhs.isFloat()) and rhs.isString()) {
        const rs = rhs.asString();
        const r_data = rs.data[0..rs.length];
        if (isNumericString(r_data)) {
            const l = lhs.toFloat();
            const r = rhs.toFloat();
            if (l < r) return -1;
            if (l > r) return 1;
            return 0;
        }
        var num_buf: [64]u8 = undefined;
        const num_str = if (lhs.isInt())
            std.fmt.bufPrint(&num_buf, "{d}", .{lhs.asInt()}) catch "0"
        else
            phpFormatFloat(&num_buf, lhs.asFloat());
        return switch (std.mem.order(u8, num_str, r_data)) {
            .lt => -1,
            .gt => 1,
            .eq => 0,
        };
    }
    if (lhs.isString() and (rhs.isInt() or rhs.isFloat())) {
        const ls = lhs.asString();
        const l_data = ls.data[0..ls.length];
        if (isNumericString(l_data)) {
            const l = lhs.toFloat();
            const r = rhs.toFloat();
            if (l < r) return -1;
            if (l > r) return 1;
            return 0;
        }
        var num_buf: [64]u8 = undefined;
        const num_str = if (rhs.isInt())
            std.fmt.bufPrint(&num_buf, "{d}", .{rhs.asInt()}) catch "0"
        else
            phpFormatFloat(&num_buf, rhs.asFloat());
        return switch (std.mem.order(u8, l_data, num_str)) {
            .lt => -1,
            .gt => 1,
            .eq => 0,
        };
    }

    // Rule 5: string vs string
    if (lhs.isString() and rhs.isString()) {
        const ls = lhs.asString();
        const rs = rhs.asString();
        if (isNumericString(ls.data[0..ls.length]) and
            isNumericString(rs.data[0..rs.length]))
        {
            const lf = lhs.toFloat();
            const rf = rhs.toFloat();
            if (lf < rf) return -1;
            if (lf > rf) return 1;
            return 0;
        }
        const cmp = std.mem.order(
            u8,
            ls.data[0..ls.length],
            rs.data[0..rs.length],
        );
        return switch (cmp) {
            .lt => -1,
            .gt => 1,
            .eq => 0,
        };
    }

    // Rule 7a: array vs array — PHP 逐元素比较，短数组更小
    if (lhs.isArray() and rhs.isArray()) {
        const la = lhs.asArray();
        const ra = rhs.asArray();
        var lit = la.elements.iterator();
        var rit = ra.elements.iterator();
        while (true) {
            const l_entry = lit.next();
            const r_entry = rit.next();
            if (l_entry == null and r_entry == null) return 0;
            if (l_entry == null) return -1;
            if (r_entry == null) return 1;
            const cmp = phpCompare(l_entry.?.value_ptr.*, r_entry.?.value_ptr.*);
            if (cmp != 0) return cmp;
        }
    }

    // Rule 7: array vs non-array
    if (lhs.isArray() and !rhs.isArray()) return 1;
    if (!lhs.isArray() and rhs.isArray()) return -1;

    // Rule 4/6: numeric comparison (fallback)
    const l = lhs.toFloat();
    const r = rhs.toFloat();
    if (l < r) return -1;
    if (l > r) return 1;
    return 0;
}

/// 小于运算
pub fn php_lt(lhs: Value, rhs: Value) !Value {
    return Value.initBool(phpCompare(lhs, rhs) < 0);
}

/// 小于等于运算
pub fn php_le(lhs: Value, rhs: Value) !Value {
    return Value.initBool(phpCompare(lhs, rhs) <= 0);
}

/// 大于运算
pub fn php_gt(lhs: Value, rhs: Value) !Value {
    return Value.initBool(phpCompare(lhs, rhs) > 0);
}

/// 大于等于运算
pub fn php_ge(lhs: Value, rhs: Value) !Value {
    return Value.initBool(phpCompare(lhs, rhs) >= 0);
}

/// Spaceship 运算符 (<=>)
/// 返回 -1 (lhs < rhs), 0 (lhs == rhs), 1 (lhs > rhs)
pub fn php_spaceship(lhs: Value, rhs: Value) !Value {
    // ★F-62（R-172）：本函数自成一套分支，object 操作数会落到末路 `toFloat()`（对象⇒0）⇒ 与 `<`/`>` 族**不同口径**：
    //   实测 `$o <=> 1`＝int 0 且带 `Notice: Object of class Foo could not be converted to int`，旧写法给 -1 且无 Notice（门 BLT b119）。
    //   object 参与比较的规则在本模板里只有一份（`phpCompare` 的 Rule 2b／2c）⇒ 这里直接交它，避免第二套实现漂移。
    if (Value_isObject(lhs) or Value_isObject(rhs)) return Value.initInt(@intCast(phpCompare(lhs, rhs)));
    if (lhs.isInt() and rhs.isInt()) {
        const l = lhs.asInt();
        const r = rhs.asInt();
        if (l < r) return Value.initInt(-1);
        if (l > r) return Value.initInt(1);
        return Value.initInt(0);
    }
    if (lhs.isString() and rhs.isString()) {
        const l = lhs.asString();
        const r = rhs.asString();
        const cmp = std.mem.order(u8, l.data[0..l.length], r.data[0..r.length]);
        return Value.initInt(switch (cmp) {
            .lt => -1,
            .gt => 1,
            .eq => 0,
        });
    }
    // 数组比较：先比元素个数，再逐元素比较
    if (lhs.isArray() and rhs.isArray()) {
        const la = lhs.asArray();
        const ra = rhs.asArray();
        if (la.elements.count() != ra.elements.count()) {
            return Value.initInt(if (la.elements.count() < ra.elements.count()) -1 else 1);
        }
        var it = la.elements.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            const lval = entry.value_ptr.*;
            const rval = ra.elements.get(key) orelse return Value.initInt(1); // key not in right → left is greater
            const sub = try php_spaceship(lval, rval);
            const sv = sub.asInt();
            if (sv != 0) return Value.initInt(sv);
        }
        return Value.initInt(0);
    }
    const l = lhs.toFloat();
    const r = rhs.toFloat();
    if (l < r) return Value.initInt(-1);
    if (l > r) return Value.initInt(1);
    return Value.initInt(0);
}

// ============================================================================
// 逻辑运算符
// ============================================================================

/// 逻辑与运算
pub fn php_and(lhs: Value, rhs: Value) !Value {
    return Value.initBool(lhs.toBool() and rhs.toBool());
}

/// 逻辑或运算
pub fn php_or(lhs: Value, rhs: Value) !Value {
    return Value.initBool(lhs.toBool() or rhs.toBool());
}

/// 布尔或运算（用于 match 表达式多条件合并）
pub fn php_bool_or(lhs: Value, rhs: Value) Value {
    return Value.initBool(lhs.toBool() or rhs.toBool());
}

/// 逻辑异或运算
pub fn php_xor(lhs: Value, rhs: Value) !Value {
    const l = lhs.toBool();
    const r = rhs.toBool();
    return Value.initBool((l and !r) or (!l and r));
}

/// 逻辑非运算
pub fn php_not(val: Value) !Value {
    return Value.initBool(!val.toBool());
}

/// 逻辑异或运算 (xor)
pub fn php_logical_xor(lhs: Value, rhs: Value) !Value {
    return Value.initBool(lhs.toBool() != rhs.toBool());
}

// ============================================================================
// 字符串运算符
// ============================================================================

/// 字符串连接运算
pub fn php_concat(lhs: Value, rhs: Value, allocator: Allocator) !Value {
    // 快速路径：两个都是字符串
    if (lhs.isString() and rhs.isString()) {
        const result = try lhs.asString().concat(rhs.asString(), allocator);
        return Value.initString(result);
    }

    // 慢速路径：需要类型转换
    const rhs_str = rhs.toString(allocator) catch {
        // 类型转换失败（如数组转字符串），异常已设置
        return Value.initString(try PHPString.init(allocator, ""));
    };
    defer rhs_str.release(allocator);

    const lhs_str = lhs.toString(allocator) catch {
        // 类型转换失败（如数组转字符串），异常已设置
        // 返回空字符串以继续执行（异常会在后续被检查）
        return Value.initString(try PHPString.init(allocator, ""));
    };
    defer lhs_str.release(allocator);

    const result = try lhs_str.concat(rhs_str, allocator);
    return Value.initString(result);
}

pub fn php_concat_with_undef(lhs: Value, rhs: Value, lhs_undef: bool, lhs_name: []const u8, rhs_undef: bool, rhs_name: []const u8, allocator: Allocator) !Value {
    if (!lhs_undef and !rhs_undef) {
        return php_concat(lhs, rhs, allocator);
    }

    const rhs_str = blk: {
        if (rhs_undef) emitUndefinedVariableWarning(rhs_name);
        break :blk rhs.toString(allocator) catch {
            return Value.initString(try PHPString.init(allocator, ""));
        };
    };
    defer rhs_str.release(allocator);

    const lhs_str = blk: {
        if (lhs_undef) emitUndefinedVariableWarning(lhs_name);
        break :blk lhs.toString(allocator) catch {
            return Value.initString(try PHPString.init(allocator, ""));
        };
    };
    defer lhs_str.release(allocator);

    const result = try lhs_str.concat(rhs_str, allocator);
    return Value.initString(result);
}

// ============================================================================
// 输出函数
// ============================================================================

/// ★F-63（R-173）：浮点→字符串的**唯一核心**（本仓原另有四套实现，见工单 §47.3）。
///   PHP 是**两套完全不同的口径**（逐值实测件 `fuzzy_scripts_720/tmp/c052_truth_float_matrix_tmp.php`，37 值 × 7 路径）：
///   · `.display`＝`precision ini=14` ⇒ 14 位有效、与 C 的 `%.14G` 同舍入，科学计数切换 **`exp >= 14` 或 `exp <= -5`**
///   · `.serialize`＝`serialize_precision ini=-1` ⇒ **最短往返**，切换 **`exp >= 17` 或 `exp <= -5`**
///     （实测 `1e16` 在序列化侧仍出**小数** `10000000000000000`、到 `1e17` 才出 `1.0E+17`；显示侧 `1e14` 就已出 `1.0E+14`）
///   ★两套都能直接由 Zig 0.16 的 `std.fmt.float.render(.scientific)` 给出：`precision=13`＝14 位有效，
///   `precision=null`＝最短往返（逐值 `std.fmt.parseFloat` 回读全等实测）⇒ **不需要「逐位数试算＋回读」的循环**。
///   `dot_zero`＝只有 `var_export` 对整值补 `.0`（实测 `var_dump(0.0)`＝`float(0)`、`var_dump(1e16)`＝`float(10000000000000000)` 都**不补**）；
///   `upper_e`＝`var_dump`/`var_export` 用大写 `E`，`json_encode` 用小写 `e`（实测 `1.0e+17`）。
///   ★旧实现三处实测错在本核心一并根除：① 十进制支把 300 位小数塞进 `[64]u8` ⇒ `error: NoSpaceLeft`（门 FLT d6，症状是后续输出**整段丢失**）；
///   ② 科学支先除幂再 `{d:.13}` ⇒ **二次舍入**（门 b5：AOT `1.2345678901235E+14` vs PHP `1.2345678901234E+14`）；
///   ③ 三个序列化站点（`php_var_dump`/`exportValue`/`jsonEncodeValue`）各自 `{}`／`{d}` 直出 ⇒ **根本没有 E 切换**（门 b7..f5 共 16 枚红）。
const FloatFmtKind = enum { display, serialize };

/// `10^k` 的 f128 值。**只在**「最短往返位恰停在 14 位舍入的中点附近」这一支用到（见 `renderFloatPHP`）。
/// 用量：`|k| ≤ 321`，二元快速幂 ≤ 9 次乘法；f128 的相对误差 ~1e-34，而需要分辨的间距 ≥ 一个 double ulp（~1e-16 相对）
/// ⇒ 判向安全。真正的**恰好平分**只可能出现在 `k ∈ [0, 3]`（此时 `(2D+1)·5^k ≤ 2^53` 才是某个 double），
/// 而这几档的 10^k 在 f128 里是**精确**的 ⇒ 「相等⇒取偶」那一支也成立。
fn pow10F128(k: i32) f128 {
    var n: u32 = if (k >= 0) @intCast(k) else @intCast(-k);
    var acc: f128 = 1;
    var base: f128 = 10;
    while (n > 0) {
        if ((n & 1) != 0) acc *= base;
        base *= base;
        n >>= 1;
    }
    return if (k >= 0) acc else 1 / acc;
}

fn renderFloatPHP(buf: []u8, f: f64, kind: FloatFmtKind, dot_zero: bool, upper_e: bool) []const u8 {
    if (buf.len < 64) return "0"; // 调用方约定 `buf.len >= 64`；不满足宁可不格式化也不能越界写

    if (std.math.isNan(f)) return "NAN";
    if (std.math.isInf(f)) return if (f > 0) "INF" else "-INF";

    var o: usize = 0;
    if (f == 0.0) {
        if (std.math.signbit(f)) {
            buf[o] = '-';
            o += 1;
        }
        buf[o] = '0';
        o += 1;
        if (dot_zero) {
            buf[o] = '.';
            buf[o + 1] = '0';
            o += 2;
        }
        return buf[0..o];
    }

    // 一次 render 同时拿到「有效数字」与「十进制指数」：科学计数串形如 [-]D[.DDD]e[-]NN
    // ★两套都取 `precision=null`（最短往返）：序列化口径直接用它；显示口径在下面自己舍到 14 位。
    //   不能向 Zig 要 `precision=13`：实测它把 `123456789012345.0` 舍成 `1.2345678901235e14`（**half-away**），
    //   而 PHP 的 `%.14G` 走 glibc 的**平分取偶**给 `1.2345678901234E+14`（门 FLT b5 实测）。
    var scratch: [128]u8 = undefined;
    const sci = std.fmt.float.render(&scratch, f, .{ .mode = .scientific, .precision = null }) catch return "0";

    var i: usize = 0;
    var neg = false;
    if (sci.len > 0 and sci[0] == '-') {
        neg = true;
        i = 1;
    }
    var digits: [24]u8 = undefined;
    var nd: usize = 0;
    while (i < sci.len and sci[i] != 'e' and sci[i] != 'E') : (i += 1) {
        const c = sci[i];
        if (c == '.') continue;
        if (nd >= digits.len) return "0";
        digits[nd] = c;
        nd += 1;
    }
    var exp: i32 = 0;
    if (i < sci.len) {
        i += 1;
        exp = std.fmt.parseInt(i32, sci[i..], 10) catch 0;
    }
    if (nd == 0) return "0";

    // ★显示口径：自己舍到 14 位有效。PHP 的 `%.14G`（glibc）在**真平分**时取偶，其余按真值的第 15 位方向舍。
    //   最短往返位与真值相差 ≤ 半个 ulp（≤ 1.1e-16 相对），因此**只有**「最短位恰为 15 位且第 15 位是 5」时方向才不可知
    //   （门 t6 实测：`0.0000123456789012345` 的最短位是 15 位、末位 5，而真值偏上 ⇒ PHP 舍入、按平分取偶会舍错）
    //   ⇒ 该支用 f128 与精确中点 `M = (D14 + 0.5) × 10^(exp-13)` 比大小；其余支直接读第 15 位。
    if (kind == .display and nd > 14) {
        const d15 = digits[14];
        // 最短往返数**末尾必非零** ⇒ 第 15 位是 5 且总位数 > 15 时，其后仍有非零位 ⇒ 一律入（门 b6/c5/c6）
        var round_up = d15 >= '5';
        if (d15 == '5' and nd == 15) {
            const D = std.fmt.parseInt(u64, digits[0..14], 10) catch 0;
            const m128: f128 = @as(f128, @floatFromInt(D)) + @as(f128, 0.5);
            const M = m128 * pow10F128(exp - 13);
            const v128: f128 = @floatCast(f);
            if (v128 > M) round_up = true else if (v128 < M) round_up = false
            else round_up = (digits[13] % 2) == 1; // 真平分 ⇒ 取偶（`123456789012345.0` 即此支，门 b5/t2）
        }
        if (round_up) {
            var j: usize = 14;
            var carry = true;
            while (carry and j > 0) {
                j -= 1;
                if (digits[j] < '9') {
                    digits[j] += 1;
                    carry = false;
                } else digits[j] = '0';
            }
            if (carry) {
                // 999…9 进位成 1000…0 ⇒ 有效位缩回 1 位、指数 +1（门 t3：`999999999999995.0` ⇒ `1.0E+15`）
                digits[0] = '1';
                nd = 1;
                exp += 1;
            } else nd = 14;
        } else nd = 14;
    }

    // `%.14G` 与最短往返都要去尾零（至少留一位），如 `1.0000000000000e16` ⇒ "1"
    while (nd > 1 and digits[nd - 1] == '0') : (nd -= 1) {}

    if (neg) {
        buf[o] = '-';
        o += 1;
    }

    const sci_threshold: i32 = if (kind == .display) 14 else 17;
    if (exp >= sci_threshold or exp <= -5) {
        buf[o] = digits[0];
        o += 1;
        buf[o] = '.';
        o += 1;
        if (nd > 1) {
            @memcpy(buf[o .. o + nd - 1], digits[1..nd]);
            o += nd - 1;
        } else {
            buf[o] = '0';
            o += 1;
        }
        buf[o] = if (upper_e) 'E' else 'e';
        o += 1;
        if (exp >= 0) {
            buf[o] = '+';
            o += 1;
        } else {
            buf[o] = '-';
            o += 1;
            exp = -exp;
        }
        var ebuf: [12]u8 = undefined;
        const es = std.fmt.bufPrint(&ebuf, "{d}", .{exp}) catch return buf[0..o];
        @memcpy(buf[o .. o + es.len], es);
        o += es.len;
        return buf[0..o];
    }

    // 十进制支：长度由上面的切换阈值锁死（显示 ≤14 位整数、序列化 ≤17 位整数，前导零 ≤3 个）⇒ 结构上不可能再 NoSpaceLeft
    if (exp >= 0) {
        const ip: usize = @as(usize, @intCast(exp + 1));
        if (ip >= nd) {
            @memcpy(buf[o .. o + nd], digits[0..nd]);
            o += nd;
            var k: usize = nd;
            while (k < ip) : (k += 1) {
                buf[o] = '0';
                o += 1;
            }
        } else {
            @memcpy(buf[o .. o + ip], digits[0..ip]);
            o += ip;
            buf[o] = '.';
            o += 1;
            @memcpy(buf[o .. o + nd - ip], digits[ip..nd]);
            o += nd - ip;
        }
    } else {
        buf[o] = '0';
        o += 1;
        buf[o] = '.';
        o += 1;
        var z: i32 = -1;
        while (z > exp) : (z -= 1) {
            buf[o] = '0';
            o += 1;
        }
        @memcpy(buf[o .. o + nd], digits[0..nd]);
        o += nd;
    }

    if (dot_zero and std.mem.indexOfScalar(u8, buf[0..o], '.') == null) {
        buf[o] = '.';
        buf[o + 1] = '0';
        o += 2;
    }
    return buf[0..o];
}

/// 显示口径：`echo`／`print`／`(string)`／插值／`print_r`，以及 `phpCompare` 的 number-vs-string 两支
/// @pre buf.len >= 64
/// @post 返回 buf 中的有效切片
pub fn phpFormatFloat(buf: []u8, f: f64) []const u8 {
    return renderFloatPHP(buf, f, .display, false, true);
}

/// 序列化口径：`var_dump`（`dot_zero=false`）／`var_export`（`true`）／`json_encode`（`upper_e=false`）
/// @pre buf.len >= 64
fn phpFormatFloatSerialize(buf: []u8, f: f64, dot_zero: bool, upper_e: bool) []const u8 {
    return renderFloatPHP(buf, f, .serialize, dot_zero, upper_e);
}

fn phpStripTrailingZeros(s: []u8) []const u8 {
    var has_dot = false;
    for (s) |c| {
        if (c == '.') {
            has_dot = true;
            break;
        }
    }
    if (!has_dot) return s;

    var end = s.len;
    while (end > 0 and s[end - 1] == '0') : (end -= 1) {}
    if (end > 0 and s[end - 1] == '.') end -= 1;
    return s[0..end];
}

/// echo语句
fn php_output_write(bytes: []const u8) !void {
    ensureObInit();
    if (ob_stack.items.len > 0) {
        const level = &ob_stack.items[ob_stack.items.len - 1];
        try level.buffer.appendSlice(runtime_allocator, bytes);
        return;
    }

    q4OutputWrite(bytes);
}

pub fn php_echo(value: Value) !void {
    if (value.isNull()) {
        // null不输出任何内容
        return;
    } else if (value.isBool()) {
        if (value.asBool()) {
            try php_output_write("1");
        }
        // false不输出任何内容
    } else if (value.isInt()) {
        var buf: [64]u8 = undefined;
        const str = try std.fmt.bufPrint(&buf, "{d}", .{value.asInt()});
        try php_output_write(str);
    } else if (value.isFloat()) {
        var buf: [64]u8 = undefined;
        const fv = value.asFloat();
        // ★F-168（R-319）：NAN 字符串化告警（与 Value.toString 同口径；INF 不发）
        if (std.math.isNan(fv)) emitWarning("unexpected NAN value was coerced to string");
        const str = phpFormatFloat(&buf, fv);
        try php_output_write(str);
    } else if (value.isString()) {
        const str = value.asString();
        try php_output_write(str.data);
    } else if (value.isArray()) {
        // PHP Warning: Array to string conversion
        var wbuf: [512]u8 = undefined;
        const wmsg = std.fmt.bufPrint(
            &wbuf,
            "\nWarning: Array to string conversion in" ++
                " {s} on line {d}\n",
            .{ src_file, src_line },
        ) catch "";
        if (wmsg.len > 0) {
            fileWriteAll(1, wmsg);
            var ebuf: [512]u8 = undefined;
            const emsg = std.fmt.bufPrint(
                &ebuf,
                "PHP Warning:  Array to string conversion in" ++
                    " {s} on line {d}\n",
                .{ src_file, src_line },
            ) catch "";
            if (emsg.len > 0) fileWriteAll(2, emsg);
        }
        try php_output_write("Array");
    } else if (Value_isObject(value)) {
        // ★F-184（R-281 收口，门 C327 t1/t5 实测）：对象 echo 走 __toString
        //（异常族 `RuntimeException: m in file:line\nStack trace:\n#0 {main}`）；
        // 无 __toString ⇒ 抛可 catch 的 Error（PHP 8：Object of class X could not
        // be converted to string）。旧版无对象分支 ⇒ 静默输出空串。
        const obj = Value_asObject(value);
        var has_to_string = false;
        if (obj.class_meta) |meta| {
            // 与 php_instanceof 的 Stringable 特判同口径（两谓词共用，禁另造）
            has_to_string = meta.magic_toString != null or meta.methods.get("__toString") != null;
        }
        if (has_to_string) {
            if (obj.toString(runtime_allocator)) |s| {
                // toString 按 +1 契约返回，写完归还
                defer s.release(runtime_allocator);
                try php_output_write(s.data);
            } else |_| {}
        } else {
            var ebuf: [256]u8 = undefined;
            const emsg = std.fmt.bufPrint(
                &ebuf,
                "Object of class {s} could not be converted to string",
                .{obj.class_name},
            ) catch "Object of class could not be converted to string";
            // setException 后正常返回：由调用点的 hasException 轮询接管分派
            throwThrowableDiscardCatch("Error", emsg, runtime_allocator);
        }
    }
}

/// print语句（返回1）
pub fn php_print(value: Value) !Value {
    try php_echo(value);
    return Value.initInt(1);
}

/// var_dump函数
pub fn php_var_dump(value: Value) !Value {
    if (value.isNull()) {
        fileWriteAll(1, "NULL\n");
    } else if (value.isBool()) {
        var buf: [32]u8 = undefined;
        const str = try std.fmt.bufPrint(&buf, "bool({})\n", .{value.asBool()});
        fileWriteAll(1, str);
    } else if (value.isInt()) {
        var buf: [64]u8 = undefined;
        const str = try std.fmt.bufPrint(&buf, "int({})\n", .{value.asInt()});
        fileWriteAll(1, str);
    } else if (value.isFloat()) {
        // ★F-63（R-173）：旧写 `float({})` 走 Zig general ⇒ **永不出 E**、`inf`/`nan` 小写、位数是 Zig 的 16 位上限。
        //   `var_dump` 属序列化口径，且实测**不**补 `.0`（`float(0)`、`float(100000000000000)`、`float(1.0E+17)`）。
        var num: [64]u8 = undefined;
        const fs = phpFormatFloatSerialize(&num, value.asFloat(), false, true);
        var buf: [96]u8 = undefined;
        const str = std.fmt.bufPrint(&buf, "float({s})\n", .{fs}) catch "float(0)\n";
        fileWriteAll(1, str);
    } else if (value.isString()) {
        const str = value.asString();
        var buf: [256]u8 = undefined;
        const msg = try std.fmt.bufPrint(&buf, "string({}) \"{s}\"\n", .{ str.length, str.data });
        fileWriteAll(1, msg);
    } else if (value.isArray()) {
        const arr = value.asArray();
        var buf: [64]u8 = undefined;
        const msg = try std.fmt.bufPrint(&buf, "array({d}) {{\n", .{arr.count()});
        fileWriteAll(1, msg);
        // 遍历数组
        var iter = arr.elements.iterator();
        while (iter.next()) |entry| {
            fileWriteAll(1, "  ");
            switch (entry.key_ptr.*) {
                .integer => |i| {
                    const key_msg = try std.fmt.bufPrint(&buf, "[{d}]", .{i});
                    fileWriteAll(1, key_msg);
                },
                .string => |s| {
                    var key_buf: [256]u8 = undefined;
                    const key_msg = try std.fmt.bufPrint(&key_buf, "[\"{s}\"]", .{s.data});
                    fileWriteAll(1, key_msg);
                },
            }
            fileWriteAll(1, "=>\n  ");
            _ = php_var_dump(entry.value_ptr.*) catch {};
        }
        fileWriteAll(1, "}\n");
    } else if (Value_isObject(value)) {
        const obj = Value_asObject(value);
        var buf: [256]u8 = undefined;

        // ★批次十二：SplDoublyLinkedList 家族特判——flags/dllist 是 internal_data 的
        //   live 内部状态（不挂实例属性表），PHP 真值 var_dump 补出两枚私有声明属性
        //   `["flags":"SplDoublyLinkedList":private]`/`["dllist":...]`，且动态属性序在前。
        if (splDllFamilyOf(obj)) {
            if (splDllDataOf(obj)) |data| {
                const header = try std.fmt.bufPrint(&buf, "object({s})#{d} ({d}) {{\n", .{ obj.class_name, obj.id, obj.properties.count() + 2 });
                fileWriteAll(1, header);
                var it = obj.properties.iterator();
                while (it.next()) |entry| {
                    fileWriteAll(1, "  [\"");
                    fileWriteAll(1, entry.key_ptr.*);
                    fileWriteAll(1, "\"]=>\n  ");
                    _ = php_var_dump(entry.value_ptr.*) catch {};
                }
                fileWriteAll(1, "  [\"flags\":\"SplDoublyLinkedList\":private]=>\n  ");
                _ = php_var_dump(Value.initInt(data.mode)) catch {};
                fileWriteAll(1, "  [\"dllist\":\"SplDoublyLinkedList\":private]=>\n  ");
                _ = php_var_dump(Value.initArray(data.elements)) catch {};
                fileWriteAll(1, "}\n");
                return Value.initNull();
            }
        }

        // 通用分支（★批次十二：对齐 PHP 真值——声明属性沿链**根→叶**按声明序输出并带
        // 可见性标记：`["name":"DeclClass":private]`/`["name":protected]`/`["name"]`；
        // 动态属性随后无标记。var_dump 不做可见性过滤——私有属性照出，仅标记归属）。
        const header = try std.fmt.bufPrint(&buf, "object({s})#{d} ({d}) {{\n", .{ obj.class_name, obj.id, obj.properties.count() });
        fileWriteAll(1, header);
        var printed = std.StringHashMap(void).init(runtime_allocator);
        defer printed.deinit();
        if (obj.class_meta) |obj_meta| {
            var chain: std.ArrayList(*const ClassMeta) = .empty;
            defer chain.deinit(runtime_allocator);
            var cur: ?*const ClassMeta = obj_meta;
            while (cur) |m| {
                try chain.append(runtime_allocator, m);
                cur = m.parent;
            }
            var idx = chain.items.len;
            while (idx > 0) {
                idx -= 1;
                const m = chain.items[idx];
                for (m.property_order.items) |pname| {
                    if (printed.contains(pname)) continue;
                    const decl = findPropertyDeclaringClass(obj_meta, pname) orelse continue;
                    if (decl.prop.is_static) continue;
                    const val = obj.properties.get(pname) orelse continue;
                    try printed.put(pname, {});
                    if (decl.prop.is_private) {
                        fileWriteAll(1, "  [\"");
                        fileWriteAll(1, pname);
                        fileWriteAll(1, "\":\"");
                        fileWriteAll(1, decl.class.name);
                        fileWriteAll(1, "\":private]=>\n  ");
                    } else if (decl.prop.is_protected) {
                        fileWriteAll(1, "  [\"");
                        fileWriteAll(1, pname);
                        fileWriteAll(1, "\":protected]=>\n  ");
                    } else {
                        fileWriteAll(1, "  [\"");
                        fileWriteAll(1, pname);
                        fileWriteAll(1, "\"]=>\n  ");
                    }
                    _ = php_var_dump(val) catch {};
                }
            }
        }
        // 动态属性（恒 public 无标记；StringHashMap 序——单枚等值，多枚序属已知残留，
        //   与 get_object_vars 7161 登记的同一限制）。
        var it = obj.properties.iterator();
        while (it.next()) |entry| {
            if (printed.contains(entry.key_ptr.*)) continue;
            fileWriteAll(1, "  [\"");
            fileWriteAll(1, entry.key_ptr.*);
            fileWriteAll(1, "\"]=>\n  ");
            _ = php_var_dump(entry.value_ptr.*) catch {};
        }
        fileWriteAll(1, "}\n");
    }
    return Value.initNull();
}

pub fn var_dump(value: Value) !Value {
    try php_var_dump(value);
    return Value.initNull();
}

pub fn print_r(value: Value, return_output: Value) !Value {
    const want_return = return_output.toBool();
    var aw = std.Io.Writer.Allocating.initCapacity(runtime_allocator, 256) catch return error.OutOfMemory;
    defer aw.deinit();

    try printValue(&aw.writer, value, 0, false);

    if (want_return) {
        return Value.initString(try PHPString.init(runtime_allocator, aw.written()));
    }
    fileWriteAll(1, aw.written());
    return Value.initBool(true);
}

pub fn var_export(value: Value, return_output: Value) !Value {
    const want_return = return_output.toBool();
    var aw = std.Io.Writer.Allocating.initCapacity(runtime_allocator, 256) catch return error.OutOfMemory;
    defer aw.deinit();

    try exportValue(&aw.writer, value, 0);

    if (want_return) {
        return Value.initString(try PHPString.init(runtime_allocator, aw.written()));
    }
    fileWriteAll(1, aw.written());
    return Value.initNull();
}

fn writeIndent(writer: anytype, indent: usize) !void {
    var i: usize = 0;
    while (i < indent * 4) : (i += 1) { // 4空格缩进 (print_r)
        try writer.writeByte(' ');
    }
}

fn writeExportIndent(writer: anytype, indent: usize) !void {
    var i: usize = 0;
    while (i < indent * 2) : (i += 1) { // 2空格缩进 (var_export)
        try writer.writeByte(' ');
    }
}

fn writeExportStrKey(writer: anytype, s: []const u8) !void {
    try writer.writeAll("'");
    for (s) |c| {
        if (c == '\'') {
            try writer.writeAll("\\'");
        } else if (c == '\\') {
            try writer.writeAll("\\\\");
        } else {
            try writer.writeByte(c);
        }
    }
    try writer.writeAll("'");
}

fn printValue(writer: anytype, value: Value, indent: usize, is_nested: bool) !void {
    if (value.isNull()) {
        // null不输出任何内容（PHP行为）
        return;
    }
    if (value.isBool()) {
        // bool输出1或空（PHP行为）
        if (value.asBool()) {
            try writer.writeByte('1');
        }
        return;
    }
    if (value.isInt()) {
        try writer.print("{d}", .{value.asInt()});
        return;
    }
    if (value.isFloat()) {
        var buf: [64]u8 = undefined;
        const fv = value.asFloat();
        // ★F-168（R-319）：print_r 走本函数，NAN 同样发一条告警（PHP 实测发；var_dump 不走这里）
        if (std.math.isNan(fv)) emitWarning("unexpected NAN value was coerced to string");
        try writer.writeAll(phpFormatFloat(&buf, fv));
        return;
    }
    if (value.isString()) {
        try writer.writeAll(value.asString().data);
        return;
    }
    if (value.isArray()) {
        const arr = value.asArray();

        // 数组开始
        try writer.writeAll("Array\n");
        if (is_nested) {
            try writeIndent(writer, indent + 1);
        } else {
            try writeIndent(writer, indent);
        }
        try writer.writeAll("(\n");

        // 遍历元素
        var iter = arr.elements.iterator();
        while (iter.next()) |entry| {
            const elem_indent = if (is_nested) indent + 2 else indent + 1;
            try writeIndent(writer, elem_indent);
            switch (entry.key_ptr.*) {
                .integer => |i| try writer.print("[{d}] => ", .{i}),
                .string => |s| try writer.print("[{s}] => ", .{s.data}),
            }

            const val = entry.value_ptr.*;
            const is_complex = val.isArray() or Value_isObject(val);

            if (is_complex) {
                try printValue(writer, val, elem_indent, true);
                try writer.writeByte('\n');
            } else {
                try printValue(writer, val, elem_indent, false);
                try writer.writeByte('\n');
            }
        }

        if (is_nested) {
            try writeIndent(writer, indent + 1);
        } else {
            try writeIndent(writer, indent);
        }
        try writer.writeAll(")\n");
        return;
    }
    if (Value_isObject(value)) {
        const obj = Value_asObject(value);

        // 对象开始
        try writer.print("{s} Object\n", .{obj.class_name});
        if (is_nested) {
            try writeIndent(writer, indent + 1);
        } else {
            try writeIndent(writer, indent);
        }
        try writer.writeAll("(\n");

        // __debugInfo 魔术方法：返回数组替代默认属性输出
        if (obj.class_meta) |meta| {
            if (meta.magic_debugInfo) |debug_fn| {
                const debug_val = debug_fn(value, &.{}, runtime_allocator) catch Value.initNull();
                if (debug_val.isArray()) {
                    const arr = debug_val.asArray();
                    var it = arr.elements.iterator();
                    while (it.next()) |entry| {
                        const elem_indent = if (is_nested) indent + 2 else indent + 1;
                        try writeIndent(writer, elem_indent);
                        switch (entry.key_ptr.*) {
                            .integer => |i| try writer.print("[{d}] => ", .{i}),
                            .string => |s| try writer.print("[{s}] => ", .{s.data}),
                        }
                        const val = entry.value_ptr.*;
                        const is_complex = val.isArray() or Value_isObject(val);
                        if (is_complex) {
                            try printValue(writer, val, elem_indent, true);
                            try writer.writeByte('\n');
                        } else {
                            try printValue(writer, val, elem_indent, false);
                            try writer.writeByte('\n');
                        }
                    }
                }
                debug_val.release(runtime_allocator);

                if (is_nested) {
                    try writeIndent(writer, indent + 1);
                } else {
                    try writeIndent(writer, indent);
                }
                try writer.writeAll(")\n");
                return;
            }
        }

        // DateTime 对象特殊处理: 输出 PHP 格式
        if (std.mem.eql(u8, obj.class_name, "DateTime")) {
            const elem_indent = if (is_nested) indent + 2 else indent + 1;
            if (obj.getProperty("timestamp")) |ts_val| {
                const ts = ts_val.toInt();
                const usecs: u64 = if (obj.getProperty("microseconds")) |us_val| @intCast(us_val.toInt()) else 0;
                // 格式化日期时间字符串 (Y-m-d H:i:s.u)
                const epoch_secs: u64 = @intCast(ts);
                const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_secs };
                const day_secs = epoch.getDaySeconds();
                const year_day = epoch.getEpochDay().calculateYearDay();
                const month_day = year_day.calculateMonthDay();
                try writeIndent(writer, elem_indent);
                try writer.print("[date] => {d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2}.{d:0>6}\n", .{
                    year_day.year,
                    month_day.month.numeric(),
                    month_day.day_index + 1,
                    day_secs.getHoursIntoDay(),
                    day_secs.getMinutesIntoHour(),
                    day_secs.getSecondsIntoMinute(),
                    usecs,
                });
                try writeIndent(writer, elem_indent);
                try writer.writeAll("[timezone_type] => 3\n");
                try writeIndent(writer, elem_indent);
                try writer.writeAll("[timezone] => UTC\n");
            }
        } else {
            // 按声明顺序遍历属性（property_order），再遍历剩余动态属性
            var printed = std.StringHashMap(void).init(runtime_allocator);
            defer printed.deinit();

            if (obj.class_meta) |meta| {
                var current: ?*const ClassMeta = meta;
                while (current) |m| {
                    for (m.property_order.items) |prop_name| {
                        if (printed.contains(prop_name)) continue;
                        if (obj.properties.get(prop_name)) |val| {
                            try printed.put(prop_name, {});
                            const elem_indent = if (is_nested) indent + 2 else indent + 1;
                            try writeIndent(writer, elem_indent);
                            try writer.print("[{s}] => ", .{prop_name});

                            const is_complex = val.isArray() or Value_isObject(val);
                            if (is_complex) {
                                try printValue(writer, val, elem_indent, true);
                                try writer.writeByte('\n');
                            } else {
                                try printValue(writer, val, elem_indent, false);
                                try writer.writeByte('\n');
                            }
                        }
                    }
                    current = m.parent;
                }
            }

            // 遍历剩余动态属性
            var it = obj.properties.iterator();
            while (it.next()) |entry| {
                if (printed.contains(entry.key_ptr.*)) continue;
                const elem_indent = if (is_nested) indent + 2 else indent + 1;
                try writeIndent(writer, elem_indent);

                const prop_name = entry.key_ptr.*;
                try writer.print("[{s}] => ", .{prop_name});

                const val = entry.value_ptr.*;
                const is_complex = val.isArray() or Value_isObject(val);

                if (is_complex) {
                    try printValue(writer, val, elem_indent, true);
                    try writer.writeByte('\n');
                } else {
                    try printValue(writer, val, elem_indent, false);
                    try writer.writeByte('\n');
                }
            }
        }

        if (is_nested) {
            try writeIndent(writer, indent + 1);
        } else {
            try writeIndent(writer, indent);
        }
        try writer.writeAll(")\n");
        return;
    }

    // 其他类型（资源等）
    try writer.writeAll("Resource");
}

fn exportValue(writer: anytype, value: Value, indent: usize) !void {
    if (value.isNull()) {
        try writer.writeAll("NULL");
        return;
    }
    if (value.isBool()) {
        try writer.writeAll(if (value.asBool()) "true" else "false");
        return;
    }
    if (value.isInt()) {
        // ★F-85（R-189）：PHP 的 `var_export` 十进制转换取不到 `-(2^63)` 的绝对值 ⇒ `PHP_INT_MIN` 实测产物是
        //   `-9223372036854775807-1`（直调、`true` 形、数组元素、键值对四形同此，见门 VAR 的 v1…v4）。
        //   ★按 `maxInt` 现拼而不是把字面量抄进代码（宪法 §四-3 禁硬编码本应计算的值）：
        //   文本＝`-` + `maxInt(i64)` 的十进制 + `-1`，正是 PHP 那次溢出转换的形状本身。
        //   ★只此一支特殊：`var_dump`／`print_r`／字符串插值实测都是正常形 `-9223372036854775808`（门 VAR 的 g1…g3
        //   是反向守卫，走另一支 `printValue`），把它们也改成 `-…-1` 就是改错面。
        const n = value.asInt();
        if (n == std.math.minInt(i64)) {
            var mag_buf: [32]u8 = undefined;
            const mag = std.fmt.bufPrint(&mag_buf, "{d}", .{std.math.maxInt(i64)}) catch {
                try writer.print("{d}", .{n});
                return;
            };
            try writer.writeByte('-');
            try writer.writeAll(mag);
            try writer.writeAll("-1");
            return;
        }
        try writer.print("{d}", .{n});
        return;
    }
    if (value.isFloat()) {
        // ★F-63（R-173）：旧写 `{d}`＋手写 `e→E` 换算 ⇒ **没有 E 切换阈值**（`1e19` 直出 20 位小数、`1e-5` 直出 `0.00001`），
        //   位数与 `.0` 规则也各自一套。现收敛到 `renderFloatPHP` 单点：`var_export` ＝序列化口径＋整值补 `.0`＋大写 E。
        //   NAN/INF 的大小写由核心统一给（实测 `var_export(NAN)`＝`NAN`、`var_export(INF)`＝`INF`，与旧写一致 ⇒ 不新增行为）。
        var buf: [64]u8 = undefined;
        try writer.writeAll(phpFormatFloatSerialize(&buf, value.asFloat(), true, true));
        return;
    }
    if (value.isString()) {
        try writer.writeAll("'");
        const s = value.asString().data;
        for (s) |c| {
            if (c == '\'') {
                try writer.writeAll("\\'");
            } else if (c == '\\') {
                try writer.writeAll("\\\\");
            } else {
                try writer.writeByte(c);
            }
        }
        try writer.writeAll("'");
        return;
    }
    if (value.isArray()) {
        const arr = value.asArray();
        try writer.writeAll("array (\n");
        var iter = arr.elements.iterator();
        while (iter.next()) |entry| {
            try writeExportIndent(writer, indent + 1);
            switch (entry.key_ptr.*) {
                .integer => |i| try writer.print("{d}", .{i}),
                .string => |k| {
                    try writer.writeAll("'");
                    for (k.data) |c| {
                        if (c == '\'') {
                            try writer.writeAll("\\'");
                        } else if (c == '\\') {
                            try writer.writeAll("\\\\");
                        } else {
                            try writer.writeByte(c);
                        }
                    }
                    try writer.writeAll("'");
                },
            }
            try writer.writeAll(" => ");
            // PHP var_export: 数组/对象值换行后同级缩进
            if (entry.value_ptr.*.isArray() or Value_isObject(entry.value_ptr.*)) {
                try writer.writeAll("\n");
                try writeExportIndent(writer, indent + 1);
            }
            try exportValue(writer, entry.value_ptr.*, indent + 1);
            try writer.writeAll(",\n");
        }
        try writeExportIndent(writer, indent);
        try writer.writeAll(")");
        return;
    }
    if (Value_isObject(value)) {
        const obj = Value_asObject(value);
        // PHP var_export: \ClassName::__set_state(array(...))
        const class_name = if (obj.class_meta) |m| m.name else "stdClass";
        try writer.writeAll("\\");
        try writer.writeAll(class_name);
        try writer.writeAll("::__set_state(array(\n");

        var exported = std.StringHashMap(void).init(runtime_allocator);
        defer exported.deinit();

        if (obj.class_meta) |meta| {
            var current: ?*const ClassMeta = meta;
            while (current) |m| {
                for (m.property_order.items) |prop_name| {
                    if (exported.contains(prop_name)) continue;
                    if (obj.properties.get(prop_name)) |val| {
                        try exported.put(prop_name, {});
                        try writeExportIndent(writer, indent + 1);
                        try writer.writeByte(' ');
                        try writeExportStrKey(writer, prop_name);
                        try writer.writeAll(" => ");
                        if (val.isArray() or Value_isObject(val)) {
                            try writer.writeAll("\n");
                            try writeExportIndent(writer, indent + 1);
                        }
                        try exportValue(writer, val, indent + 1);
                        try writer.writeAll(",\n");
                    }
                }
                current = m.parent;
            }
        }

        var it = obj.properties.iterator();
        while (it.next()) |entry| {
            if (exported.contains(entry.key_ptr.*)) continue;
            try writeExportIndent(writer, indent + 1);
            try writer.writeByte(' ');
            try writeExportStrKey(writer, entry.key_ptr.*);
            try writer.writeAll(" => ");
            if (entry.value_ptr.*.isArray() or Value_isObject(entry.value_ptr.*)) {
                try writer.writeAll("\n");
                try writeExportIndent(writer, indent + 1);
            }
            try exportValue(writer, entry.value_ptr.*, indent + 1);
            try writer.writeAll(",\n");
        }

        try writeExportIndent(writer, indent);
        try writer.writeAll("))");
        return;
    }
    try writer.writeAll("NULL");
}

// ============================================================================
// 常量函数
// ============================================================================

/// 注册所有PHP预定义常量
pub fn registerPHPPredefinedConstants(allocator: Allocator) !void {
    const IntConst = struct { name: []const u8, value: i64 };
    const FloatConst = struct { name: []const u8, value: f64 };
    const StrConst = struct { name: []const u8, value: []const u8 };
    const BoolConst = struct { name: []const u8, value: bool };

    // 整数常量
    const int_consts = [_]IntConst{
        // 数组
        .{ .name = "COUNT_NORMAL", .value = 0 },
        .{ .name = "COUNT_RECURSIVE", .value = 1 },
        .{ .name = "ARRAY_FILTER_USE_BOTH", .value = 1 },
        .{ .name = "ARRAY_FILTER_USE_KEY", .value = 2 },
        .{ .name = "ARRAY_UNIQUE_REGULAR", .value = 0 },
        .{ .name = "SORT_REGULAR", .value = 0 },
        .{ .name = "SORT_NUMERIC", .value = 1 },
        .{ .name = "SORT_STRING", .value = 2 },
        .{ .name = "SORT_ASC", .value = 4 },
        .{ .name = "SORT_DESC", .value = 3 },
        .{ .name = "SORT_NATURAL", .value = 6 },
        .{ .name = "SORT_FLAG_CASE", .value = 8 },
        // JSON
        .{ .name = "JSON_PRETTY_PRINT", .value = 128 },
        .{ .name = "JSON_UNESCAPED_UNICODE", .value = 256 },
        .{ .name = "JSON_UNESCAPED_SLASHES", .value = 64 },
        .{ .name = "JSON_THROW_ON_ERROR", .value = 4194304 },
        .{ .name = "JSON_FORCE_OBJECT", .value = 16 },
        .{ .name = "JSON_HEX_TAG", .value = 1 },
        .{ .name = "JSON_HEX_AMP", .value = 2 },
        .{ .name = "JSON_HEX_APOS", .value = 4 },
        .{ .name = "JSON_HEX_QUOT", .value = 8 },
        .{ .name = "JSON_NUMERIC_CHECK", .value = 32 },
        .{ .name = "JSON_BIGINT_AS_STRING", .value = 512 },
        .{ .name = "JSON_PARTIAL_OUTPUT_ON_ERROR", .value = 1024 },
        .{ .name = "JSON_INVALID_UTF8_IGNORE", .value = 1048576 },
        .{ .name = "JSON_INVALID_UTF8_SUBSTITUTE", .value = 2097152 },
        // ★Q4：JSON_ERROR_* 错误码族（json_last_error/json_validate 对照常量）
        .{ .name = "JSON_ERROR_NONE", .value = 0 },
        .{ .name = "JSON_ERROR_DEPTH", .value = 1 },
        .{ .name = "JSON_ERROR_STATE_MISMATCH", .value = 2 },
        .{ .name = "JSON_ERROR_CTRL_CHAR", .value = 3 },
        .{ .name = "JSON_ERROR_SYNTAX", .value = 4 },
        .{ .name = "JSON_ERROR_UTF8", .value = 5 },
        .{ .name = "JSON_ERROR_RECURSION", .value = 6 },
        .{ .name = "JSON_ERROR_INF_OR_NAN", .value = 7 },
        .{ .name = "JSON_ERROR_UNSUPPORTED_TYPE", .value = 8 },
        .{ .name = "JSON_ERROR_INVALID_PROPERTY_NAME", .value = 9 },
        .{ .name = "JSON_ERROR_UTF16", .value = 10 },
        .{ .name = "JSON_ERROR_NON_BACKED_ENUM", .value = 11 },
        // 错误级别
        .{ .name = "E_ERROR", .value = 1 },
        .{ .name = "E_WARNING", .value = 2 },
        .{ .name = "E_PARSE", .value = 4 },
        .{ .name = "E_NOTICE", .value = 8 },
        .{ .name = "E_CORE_ERROR", .value = 16 },
        .{ .name = "E_CORE_WARNING", .value = 32 },
        .{ .name = "E_COMPILE_ERROR", .value = 64 },
        .{ .name = "E_COMPILE_WARNING", .value = 128 },
        .{ .name = "E_USER_ERROR", .value = 256 },
        .{ .name = "E_USER_WARNING", .value = 512 },
        .{ .name = "E_USER_NOTICE", .value = 1024 },
        .{ .name = "E_STRICT", .value = 2048 },
        .{ .name = "E_RECOVERABLE_ERROR", .value = 4096 },
