        .{ .name = "SEEK_END", .value = 2 },
        .{ .name = "FILE_APPEND", .value = 8 },
        .{ .name = "FILE_USE_INCLUDE_PATH", .value = 1 },
        .{ .name = "FILE_IGNORE_NEW_LINES", .value = 2 },
