/// atan2 - 两个参数的反正切
pub fn php_atan2(y: Value, x: Value) !Value {
    const yy = requireNumParam("atan2", 1, "y", .float_param, y) orelse return Value.initNull();
    const xx = requireNumParam("atan2", 2, "x", .float_param, x) orelse return Value.initNull();
    return Value.initFloat(std.math.atan2(yy.toFloat(), xx.toFloat()));
}

/// sinh - 双曲正弦
pub fn php_sinh(val: Value) !Value {
    const num = requireNumParam("sinh", 1, "num", .float_param, val) orelse return Value.initNull();
    const x = num.toFloat();
    return Value.initFloat((std.math.exp(x) - std.math.exp(-x)) / 2.0);
}

/// cosh - 双曲余弦
pub fn php_cosh(val: Value) !Value {
    const num = requireNumParam("cosh", 1, "num", .float_param, val) orelse return Value.initNull();
    const x = num.toFloat();
    return Value.initFloat((std.math.exp(x) + std.math.exp(-x)) / 2.0);
}

/// tanh - 双曲正切
pub fn php_tanh(val: Value) !Value {
    const num = requireNumParam("tanh", 1, "num", .float_param, val) orelse return Value.initNull();
    const x = num.toFloat();
    const ex = std.math.exp(x);
    const emx = std.math.exp(-x);
    return Value.initFloat((ex - emx) / (ex + emx));
}

/// dechex - 十进制转十六进制字符串
pub fn php_dechex(val: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b165）：实测 `dechex(): Argument #1 ($num) must be of type int, Foo given`。
    //   b178（`dechex("255")`='ff'）是**反向守卫**：完整数值串的弱强转必须继续可用 ⇒ 走 helper 的 string 支路而非直接拒。
    const num_ok = requireNumParam("dechex", 1, "num", .int_param, val) orelse return Value.initNull();
    const n = num_ok.toInt();
    const un: u64 = @bitCast(n);
    const str = try std.fmt.allocPrint(allocator, "{x}", .{un});
    defer allocator.free(str);
    const php_str = try PHPString.init(allocator, str);
    return Value.initString(php_str);
}

/// decoct - 十进制转八进制字符串
pub fn php_decoct(val: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b166）：与 dechex 同族、同措辞（`Argument #1 ($num) must be of type int, Foo given`）。
    //   ★站点普查教训复用：两枚函数体都写 `const n = val.toInt();`，按文本匹配会串台 ⇒ 用签名行做唯一锚。
    const num_ok = requireNumParam("decoct", 1, "num", .int_param, val) orelse return Value.initNull();
    const n = num_ok.toInt();
    const un: u64 = @bitCast(n);
    const str = try std.fmt.allocPrint(allocator, "{o}", .{un});
    defer allocator.free(str);
    const php_str = try PHPString.init(allocator, str);
    return Value.initString(php_str);
}

/// bindec - 二进制字符串转十进制
pub fn php_bindec(val: Value) !Value {
    if (!val.isString()) return Value.initInt(0);
    const s = val.asString().data;
    var result: i64 = 0;
    for (s) |c| {
        if (c == '0' or c == '1') {
            result = result * 2 + @as(i64, c - '0');
        }
    }
    return Value.initInt(result);
}

/// hexdec - 十六进制字符串转十进制
pub fn php_hexdec(val: Value) !Value {
    if (!val.isString()) return Value.initInt(0);
    const s = val.asString().data;
    var result: i64 = 0;
    for (s) |c| {
        const digit: i64 = if (c >= '0' and c <= '9')
            @as(i64, c - '0')
        else if (c >= 'a' and c <= 'f')
            @as(i64, c - 'a' + 10)
        else if (c >= 'A' and c <= 'F')
            @as(i64, c - 'A' + 10)
        else
            break;
        result = result * 16 + digit;
    }
    return Value.initInt(result);
}

/// octdec - 八进制字符串转十进制
pub fn php_octdec(val: Value) !Value {
    if (!val.isString()) return Value.initInt(0);
    const s = val.asString().data;
    var result: i64 = 0;
    for (s) |c| {
        if (c >= '0' and c <= '7') {
            result = result * 8 + @as(i64, c - '0');
        } else break;
    }
    return Value.initInt(result);
}

/// log - 自然对数
pub fn php_log(val: Value) !Value {
    // ★F-62（R-172）：PHP 的 `log($num, $base = M_E)` 是两枚 float 形参，本实现只接一枚 ⇒ `$base` 面属 arity 缺口（另立 F-62e）。
    const num = requireNumParam("log", 1, "num", .float_param, val) orelse return Value.initNull();
    return Value.initFloat(@log(num.toFloat()));
}

/// log10 - 以10为底的对数
pub fn php_log10(val: Value) !Value {
    const num = requireNumParam("log10", 1, "num", .float_param, val) orelse return Value.initNull();
    return Value.initFloat(@log10(num.toFloat()));
}

/// log2 - 以2为底的对数
pub fn php_log2(val: Value) !Value {
    // 注：PHP 8.5.8 无 `log2()`（实测 `Call to undefined function log2()`）⇒ 本函数是 AOT 侧多出的实现，
    //   这里只按同族口径补校验以保持入口一致，**不**与 PHP 对表（对表面属 F-62e 的「多余内置」登记）。
    const num = requireNumParam("log2", 1, "num", .float_param, val) orelse return Value.initNull();
    return Value.initFloat(@log2(num.toFloat()));
}

/// exp - e的x次方
pub fn php_exp(val: Value) !Value {
    const num = requireNumParam("exp", 1, "num", .float_param, val) orelse return Value.initNull();
    return Value.initFloat(@exp(num.toFloat()));
}

/// pow - 幂运算
pub fn php_pow_func(base: Value, exponent: Value) !Value {
    // ★F-59 的漏网面（R-170）：`$a ** $b` 走 `php_pow`，而内置函数形式 `pow($a, $b)` 走的是这里
    //   （`native_linker.zig:4288` 把内置名 `pow` 映射到 `php_pow_func`）。旧体**没有操作数检查**，
    //   末路直接 `std.math.pow(f64, toFloat(), toFloat())` ⇒ `pow($o,2)`/`pow([1],2)`/`pow("abc",2)` 静默给 0.0/1.0；
    //   而 PHP 两种写法**同一措辞** `Unsupported operand types: Foo ** int`（门 BLT b17/b21/b22/b23，对照臂 b26 `2 ** [1]` 已绿）。
    //   旧体还有第二处错：`0 <= e < 64` 用**无溢出检测**的逐次乘法 ⇒ 有符号回绕，
    //   实测 `pow(2,63)` AOT 给 `integer -9223372036854775808`、`pow(10,19)` 给 `integer -8446744073709551616`，
    //   而 PHP 两者都给 float（b27/b28）。`php_pow` 用 `@mulWithOverflow` 溢出即转 float ⇒ 正确。
    //   ⇒ 修法＝**委托 `php_pow`**（同一语义只留一份实现，DRY；不在此重抄检查与溢出逻辑）。
    //   ★F-62 侧：`pow()` 的形参消息**不走**参数校验措辞，实测仍是 `Unsupported operand types: Foo ** int`
    //   ⇒ 本函数**不加** `requireNumParam`，交给 `php_pow` 的操作数检查（加了就变成两套措辞）。
    return php_pow(base, exponent);
}

/// fmod - 浮点数取模（结果符号与被除数相同，匹配 C/PHP fmod）
pub fn php_fmod(x: Value, y: Value) !Value {
    const xx = requireNumParam("fmod", 1, "num1", .float_param, x) orelse return Value.initNull();
    const yy = requireNumParam("fmod", 2, "num2", .float_param, y) orelse return Value.initNull();
    const xv = xx.toFloat();
    const yv = yy.toFloat();
    if (yv == 0.0) return Value.initFloat(std.math.nan(f64));
    return Value.initFloat(xv - yv * @trunc(xv / yv));
}

/// intdiv - 整数除法
pub fn php_intdiv(dividend: Value, divisor: Value) !Value {
    // ★F-62（R-172）：`$num1`／`$num2` 都是 **int** 形参 ⇒ 校验必须**先于**除零与 minInt/-1 判定
    //   （实测 `intdiv($o, 0)` ⇒ 参数类型错而非 DivisionByZeroError；`intdiv(5, null)` ⇒ 先 Passing-null Deprecated 再 DivisionByZeroError）。
    const dv = requireNumParam("intdiv", 1, "num1", .int_param, dividend) orelse return Value.initNull();
    const iv = requireNumParam("intdiv", 2, "num2", .int_param, divisor) orelse return Value.initNull();
    const a = dv.asInt();
    const b = iv.asInt();
    if (b == 0) {
        // 旧写法 `return error.DivisionByZero` 是 Zig error 外逸（门 Y y5：打 `error: DivisionByZero`
        // 且 rc=1，未捕获面连后续语句都不跑）；PHP 侧是可捕获 DivisionByZeroError。
        // 形态照搬本文件既有的 `/`、`%` 支（:5962/:5976/:6003）。
        try throwThrowableDiscard("DivisionByZeroError", "Division by zero", runtime_allocator);
        return Value.initNull();
    }
    if (b == -1 and a == std.math.minInt(i64)) {
        // 商不可表示为 int：PHP 给 ArithmeticError。旧写法直接 @divTrunc 会**静默回绕**回
        // minInt 本身（门 Y y6 实测 AOT `Y6=RET`、rc=0）。minInt(i64) 即 :494 登记的 PHP_INT_MIN。
        try throwThrowableDiscard("ArithmeticError", "Division of PHP_INT_MIN by -1 is not an integer", runtime_allocator);
        return Value.initNull();
    }
    return Value.initInt(@divTrunc(a, b));
}

/// fdiv - 浮点除法（PHP 8.0+，除以零返回 INF/NAN）
/// ★F-62（R-172）：签名由 `Value` 改为 `!Value` 以承载参数类型校验 ⇒ 发射器侧的
///   `builtin_map["fdiv"].may_raise` 必须同批由 false 翻成 true（`native_linker.zig:4312`），
///   否则生成码既不带 `try` 也不带 hasException 路由 ⇒ 编译不过／异常丢失。
pub fn php_fdiv(dividend: Value, divisor: Value) !Value {
    const dv = requireNumParam("fdiv", 1, "num1", .float_param, dividend) orelse return Value.initNull();
    const iv = requireNumParam("fdiv", 2, "num2", .float_param, divisor) orelse return Value.initNull();
    const a = dv.toFloat();
    const b = iv.toFloat();
    // fdiv 的除零不抛异常，返回 INF/-INF/NAN
    return Value.initFloat(a / b);
}

/// hypot - 计算直角三角形斜边长度
pub fn php_hypot(x: Value, y: Value) !Value {
    const xx = requireNumParam("hypot", 1, "x", .float_param, x) orelse return Value.initNull();
    const yy = requireNumParam("hypot", 2, "y", .float_param, y) orelse return Value.initNull();
    return Value.initFloat(std.math.hypot(xx.toFloat(), yy.toFloat()));
}

/// base_convert - 在任意进制之间转换数字
pub fn php_base_convert(number: Value, frombase: Value, tobase: Value, allocator: Allocator) !Value {
    // ★F-62f 接线第四批（门 BLT 段 I b181/b182，R-195）：#2/#3 实测都是**裸 `int`** ⇒ 现形制 helper 直接可用，零新措辞维。
    //   ★形参名以实测为准：PHP 写 **`$from_base`／`$to_base`（带下划线）**，而模板变量名是 `frombase`/`tobase` ⇒ 禁照变量名印。
    //   ★位置在 `!number.isString()` 早退**之上**（PHP 参数类型检查先于函数体；否则 `base_convert(123, $o, 10)` 会被早退吞成 "0"）。
    //   ★**只接类型拒**：下面 `@min(@max(_,2),36)` 的夹取是另一枚面——实测 PHP 对底数 0/1/37/负数给
    //   `ValueError: base_convert(): Argument #2 ($from_base) must be between 2 and 36 (inclusive)`（＝F-126 第五套措辞族，#142），本批不动。
    const frombase_ok = requireNumParam("base_convert", 2, "from_base", .int_param, frombase) orelse return Value.initNull();
    const tobase_ok = requireNumParam("base_convert", 3, "to_base", .int_param, tobase) orelse return Value.initNull();
    if (!number.isString()) return Value.initString(try PHPString.init(allocator, "0"));

    const num_str = number.asString().data;
    // ★F-126（R-229）：底数越界是 ValueError（原先 @min(@max(...)) 静默夹取）
    const from_raw = frombase_ok.toInt();
    if (from_raw < 2 or from_raw > 36) {
        return throwThrowable("ValueError", "base_convert(): Argument #2 ($from_base) must be between 2 and 36 (inclusive)", runtime_allocator);
    }
    const to_raw = tobase_ok.toInt();
    if (to_raw < 2 or to_raw > 36) {
        return throwThrowable("ValueError", "base_convert(): Argument #3 ($to_base) must be between 2 and 36 (inclusive)", runtime_allocator);
    }
    const from: u8 = @intCast(from_raw);
    const to: u8 = @intCast(to_raw);

    // 先将源进制转为十进制整数
    var decimal: u64 = 0;
    for (num_str) |c| {
        const digit: u64 = if (c >= '0' and c <= '9')
            c - '0'
        else if (c >= 'a' and c <= 'z')
            c - 'a' + 10
        else if (c >= 'A' and c <= 'Z')
            c - 'A' + 10
        else
            continue;
        if (digit >= from) continue;
        decimal = decimal * from + digit;
    }

    // 十进制转目标进制
    if (decimal == 0) return Value.initString(try PHPString.init(allocator, "0"));

    const digits = "0123456789abcdefghijklmnopqrstuvwxyz";
    var buf: [65]u8 = undefined;
    var pos: usize = buf.len;
    var val = decimal;
    while (val > 0) {
        pos -= 1;
        buf[pos] = digits[@intCast(@rem(val, to))];
        val /= to;
    }

    return Value.initString(try PHPString.init(allocator, buf[pos..]));
}

/// gc_enabled - 检查 GC 是否启用
pub fn php_gc_enabled() Value {
    return Value.initBool(gc_enabled);
}

/// deg2rad - 角度转弧度
pub fn php_deg2rad(degrees: Value) !Value {
    const dv = requireNumParam("deg2rad", 1, "num", .float_param, degrees) orelse return Value.initNull();
    const rad = dv.toFloat() * std.math.pi / 180.0;
    return Value.initFloat(rad);
}

/// rad2deg - 弧度转角度
pub fn php_rad2deg(radians: Value) !Value {
    const rv = requireNumParam("rad2deg", 1, "num", .float_param, radians) orelse return Value.initNull();
    const deg = rv.toFloat() * 180.0 / std.math.pi;
    return Value.initFloat(deg);
}

/// pi - 返回圆周率
pub fn php_pi() !Value {
    return Value.initFloat(std.math.pi);
}

/// intval - 转换为整数
pub fn php_intval(val: Value, base: Value) !Value {
    // 使用完整的 PHP intval 语义
    // ★R-242：`intval($value, $base = 10)`——base 只作用于字符串，其余类型一律忽略 base。
    // ★F-77：对象 ⇒ Warning＋1（与 `(int)$o` 同口径，实测 `__toString` 不豁免）
    const probe = derefForNumberProbe(val);
    if (Value_isObject(probe)) {
        emitObjectToNumberWarning(probe, "int");
        return Value.initInt(1);
    }
    if (val.isInt()) return val;
    if (val.isFloat()) {
        // ★F-69：这里原先把 `toInt()` 的饱和逻辑**逐字抄了第三遍**（且**没有** `isNan` 守卫 ⇒ `intval(NAN)` 走
        //   越界 `@intFromFloat`＝Zig 非法行为；PHP 实测给 `0` ＋ 告警）。改成单点 helper ＋ 显式站点告警。
        warnFloatToIntNotRepresentable(val);
        return Value.initInt(floatToIntPHP(val.asFloat()));
    }
    if (val.isBool()) return Value.initInt(if (val.asBool()) @as(i64, 1) else @as(i64, 0));
    if (val.isArray()) {
        const arr = val.asArray();
        return Value.initInt(if (arr.elements.count() > 0) @as(i64, 1) else @as(i64, 0));
    }
    if (val.isString()) {
        const str = val.asString().data;

        // 非法 base（非 0 且不在 2..36）⇒ PHP 直接给 0，不抛异常（实测 1/37/-1 全 0）
        const base_i = base.toInt();
        if (!(base_i == 0 or (base_i >= 2 and base_i <= 36))) return Value.initInt(0);

        // 内联 intval 逻辑
        if (str.len == 0) return Value.initInt(0);

        var s = std.mem.trim(u8, str, " \t\n\r");
        if (s.len == 0) return Value.initInt(0);

        var negative = false;
        if (s[0] == '-') {
            negative = true;
            s = s[1..];
        } else if (s[0] == '+') {
            s = s[1..];
        }

        if (s.len == 0) return Value.initInt(0);

        // ★R-242：显式 base=10 走既有十进制／浮点串／科学记法子路（逐字保留；
        //   注意 base=0 的十进制**不**识别指数与小数点，实测 intval("1e3",0)=1、intval("0.5",0)=0）。
        if (base_i == 10) {
            // 如果包含小数点或科学记数法，先解析为浮点数
            if (std.mem.indexOf(u8, s, ".") != null or
                std.mem.indexOf(u8, s, "e") != null or
                std.mem.indexOf(u8, s, "E") != null)
            {
                if (std.fmt.parseFloat(f64, if (negative) str else s)) |float_val| {
                    const max_as_float: f64 = @floatFromInt(std.math.maxInt(i64));
                    const min_as_float: f64 = @floatFromInt(std.math.minInt(i64));
                    // ★F-80 同族第二处（`intval` 的"串含小数点/科学记法 ⇒ 先 parseFloat"子路）：按符号饱和、零告警。
                    //   ★纯数字溢出路本来就是按符号饱和的，禁一并改动（工单 §64.1 已点名）。
                    if (float_val >= max_as_float or float_val < min_as_float) return Value.initInt(if (float_val < 0) std.math.minInt(i64) else std.math.maxInt(i64));
                    return Value.initInt(@intFromFloat(float_val));
                } else |_| {}
            }

            // 手动解析整数（仅接受 0-9，不接受下划线，处理溢出）
            var result: i64 = 0;
            var overflow = false;
            for (s) |c| {
                if (c >= '0' and c <= '9') {
                    if (result > 922337203685477580) {
                        overflow = true;
                        break;
                    }
                    result = result * 10 + (c - '0');
                    if (result < 0) {
                        overflow = true;
                        break;
                    }
                } else {
                    break;
                }
            }

            if (overflow) {
                return Value.initInt(if (negative) -9223372036854775808 else 9223372036854775807);
            }
            return Value.initInt(if (negative) -result else result);
        }

        // ★R-242：base=0 与前缀识别（0x/0X ⇒ 16、0b/0B ⇒ 2、其余前导 0 ⇒ 8；PHP 不认 0o）。
        //   显式 base=16/2 同样剥掉对应前缀（实测 intval("0b11",2)=3、intval("0x1A",16)=26）。
        var eff_base: u64 = if (base_i == 0) 10 else @intCast(base_i);
        var digits = s;
        if (base_i == 0) {
            if (digits.len >= 2 and digits[0] == '0' and (digits[1] == 'x' or digits[1] == 'X')) {
                eff_base = 16;
                digits = digits[2..];
            } else if (digits.len >= 2 and digits[0] == '0' and (digits[1] == 'b' or digits[1] == 'B')) {
                eff_base = 2;
                digits = digits[2..];
            } else if (digits.len >= 2 and digits[0] == '0') {
                eff_base = 8;
            }
        } else if (base_i == 16 and digits.len >= 2 and digits[0] == '0' and (digits[1] == 'x' or digits[1] == 'X')) {
            digits = digits[2..];
        } else if (base_i == 2 and digits.len >= 2 and digits[0] == '0' and (digits[1] == 'b' or digits[1] == 'B')) {
            digits = digits[2..];
        }
        return intvalParseDigits(digits, eff_base, negative);
    }
    return Value.initInt(0);
}

/// `intval` 的 2..36 进制 digit 值；非法字符返回 null 交调用方截断。
fn intvalDigitValue(c: u8) ?u64 {
    if (c >= '0' and c <= '9') return c - '0';
    if (c >= 'a' and c <= 'z') return 10 + (c - 'a');
    if (c >= 'A' and c <= 'Z') return 10 + (c - 'A');
    return null;
}

/// 非十进制 digit 解析：遇非法 digit 停止；无任何 digit ⇒ 0；溢出按符号饱和（实测）。
fn intvalParseDigits(digits: []const u8, base: u64, negative: bool) Value {
    const limit: u64 = if (negative) (@as(u64, 1) << 63) else @as(u64, std.math.maxInt(i64));
    var mag: u64 = 0;
    var any = false;
    for (digits) |c| {
        const d = intvalDigitValue(c) orelse break;
        if (d >= base) break;
        any = true;
        if (mag > (limit - d) / base) {
            mag = limit;
            break;
        }
        mag = mag * base + d;
    }
    if (!any) return Value.initInt(0);
    if (negative) {
        if (mag >= (@as(u64, 1) << 63)) return Value.initInt(std.math.minInt(i64));
        return Value.initInt(-@as(i64, @intCast(mag)));
    }
    if (mag > @as(u64, @intCast(std.math.maxInt(i64)))) return Value.initInt(std.math.maxInt(i64));
    return Value.initInt(@intCast(mag));
}

/// floatval - 转换为浮点数
pub fn php_floatval(val: Value) !Value {
    // ★F-77：对象 ⇒ Warning＋1.0（措辞尾词随目标类型＝`to float`）
    const probe = derefForNumberProbe(val);
    if (Value_isObject(probe)) {
        emitObjectToNumberWarning(probe, "float");
        return Value.initFloat(1.0);
    }
    return Value.initFloat(val.toFloat());
}

/// boolval - 转换为布尔值
pub fn php_boolval(val: Value) !Value {
    return Value.initBool(val.toBool());
}

// ============================================================================
// 类型检查函数
// ============================================================================

/// is_null - 检查是否为null
pub fn php_is_null(val: Value) !Value {
    return Value.initBool(val.isNull());
}

/// is_bool - 检查是否为布尔值
pub fn php_is_bool(val: Value) !Value {
    return Value.initBool(val.isBool());
}

/// is_int - 检查是否为整数
pub fn php_is_int(val: Value) !Value {
    return Value.initBool(val.isInt());
}

/// is_float - 检查是否为浮点数
pub fn php_is_float(val: Value) !Value {
    return Value.initBool(val.isFloat());
}

/// is_string - 检查是否为字符串
pub fn php_is_string(val: Value) !Value {
    return Value.initBool(val.isString());
}

/// is_array - 检查是否为数组
pub fn php_is_array(val: Value) !Value {
    return Value.initBool(val.isArray());
}

/// is_numeric - 检查是否为数字或数字字符串
pub fn php_is_numeric(val: Value) !Value {
    if (val.isInt() or val.isFloat()) return Value.initBool(true);
    if (val.isString()) {
        const str = val.asString();
        // 尝试解析为数字
        _ = std.fmt.parseInt(i64, str.data, 10) catch {
            _ = std.fmt.parseFloat(f64, str.data) catch {
                return Value.initBool(false);
            };
        };
        return Value.initBool(true);
    }
    return Value.initBool(false);
}

/// AOT-CODEGEN-010 §8 #6：用户函数注册表大小写不敏感查找 —— 精确命中优先，
/// 未命中回落 CI 线性扫描（PHP 函数名不区分大小写；注册表规模 = 用户函数数，可接受）。
fn lookupUserFunctionCI(name: []const u8) ?*const fn (ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    const reg_ptr = user_function_registry orelse return null;
    if (reg_ptr.get(name)) |func| return func;
    var it = reg_ptr.iterator();
    while (it.next()) |entry| {
        if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, name)) return entry.value_ptr.*;
    }
    return null;
}

/// is_callable - 检查是否可调用（简化实现）
pub fn php_is_callable(val: Value) !Value {
    const actual_val = if (val.isRef()) val.asRef().* else val;
    if (actual_val.isFunction()) return Value.initBool(true);
    if (actual_val.isString()) {
        // ★F-96-c：绝不能借 `aot_callable_hook` 探测——hook 会**真的执行**目标（`is_callable("C::m")` 跑一次方法）。
        //   改用无副作用的静态判定：内置名 ∪ 用户函数（CI）∪ `Class::method`。
        return Value.initBool(isCallableNoInvoke(actual_val));
    }
    if (actual_val.isArray()) {
        // [obj/class, method] 形式
        const arr = actual_val.asArray();
        if (arr.elements.count() == 2) {
            const k0 = ArrayKey{ .integer = 0 };
            const k1 = ArrayKey{ .integer = 1 };
            const elem0 = arr.elements.get(k0) orelse return Value.initBool(false);
            const elem1 = arr.elements.get(k1) orelse return Value.initBool(false);
            // 第二个元素必须是字符串（方法名）
            if (!elem1.isString()) return Value.initBool(false);
            const method_name = elem1.asString().data;
            // 第一个元素是对象：检查方法是否存在
            if (Value_isObject(elem0)) {
                const obj = Value_asObject(elem0);
                if (obj.class_meta) |meta| {
                    return Value.initBool(meta.findMethodLookup(method_name) != null);
                }
                return Value.initBool(false);
            }
            // 第一个元素是字符串（类名）：检查静态方法是否存在
            if (elem0.isString()) {
                // ★F-1-b：`self`/`parent`/`static` 作用域限定符须按当前类上下文解析
                //   （否则类内 `is_callable(['self','m'])` / `go self::m(...)` 误判不可调用）。
                const meta = resolveClassQualifierName(elem0.asString().data) orelse return Value.initBool(false);
                return Value.initBool(meta.findMethodLookup(method_name) != null);
            }
            return Value.initBool(false);
        }
        return Value.initBool(false);
    }
    if (Value_isObject(actual_val)) {
        const obj = Value_asObject(actual_val);
        if (obj.class_meta) |meta| {
            return Value.initBool(meta.findMethod("__invoke") != null);
        }
    }
    return Value.initBool(false);
}

/// is_scalar - 检查是否为标量类型（int, float, string, bool）
pub fn php_is_scalar(val: Value) !Value {
    return Value.initBool(val.isInt() or val.isFloat() or val.isString() or val.isBool());
}

/// is_infinite - 检查浮点数是否为无穷大
pub fn php_is_infinite(val: Value) !Value {
    if (!val.isFloat()) return Value.initBool(false);
    const f = val.asFloat();
    return Value.initBool(std.math.isInf(f));
}

/// is_nan - 检查浮点数是否为NaN
pub fn php_is_nan(val: Value) !Value {
    if (!val.isFloat()) return Value.initBool(false);
    const f = val.asFloat();
    return Value.initBool(std.math.isNan(f));
}

/// is_finite - 检查浮点数是否为有限值
pub fn php_is_finite(val: Value) !Value {
    if (!val.isFloat()) return Value.initBool(true); // 非浮点数视为有限
    const f = val.asFloat();
    return Value.initBool(!std.math.isInf(f) and !std.math.isNan(f));
}

/// is_countable - 检查是否可计数（数组或实现Countable接口的对象）
pub fn php_is_countable(val: Value) !Value {
    // 数组总是可计数的
    if (val.isArray()) return Value.initBool(true);

    // 对象需要实现Countable接口
    if (Value_isObject(val)) {
        const obj = Value_asObject(val);
        if (obj.class_meta) |meta| {
            // 检查是否实现了Countable接口（有count方法）
            return Value.initBool(meta.findMethod("count") != null);
        }
    }

    return Value.initBool(false);
}

/// is_iterable - 检查是否可迭代（数组或实现Traversable接口的对象）
pub fn php_is_iterable(val: Value) !Value {
    // 数组总是可迭代的
    if (val.isArray()) return Value.initBool(true);

    // 对象需要实现Traversable接口（Iterator或IteratorAggregate）
    if (Value_isObject(val)) {
        const obj = Value_asObject(val);
        if (obj.class_meta) |meta| {
            // 检查是否有迭代器方法
            const has_current = meta.findMethod("current") != null;
            const has_key = meta.findMethod("key") != null;
            const has_next = meta.findMethod("next") != null;
            const has_rewind = meta.findMethod("rewind") != null;
            const has_valid = meta.findMethod("valid") != null;
            const has_getiterator = meta.findMethod("getIterator") != null;

            // Iterator接口需要5个方法，IteratorAggregate需要getIterator
            return Value.initBool((has_current and has_key and has_next and has_rewind and has_valid) or has_getiterator);
        }
    }

    return Value.initBool(false);
}

/// unset - 删除变量（立即释放引用）
pub fn php_unset(args: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    for (args) |val| {
        val.release(runtime_allocator);
    }
    return Value.initNull();
}

/// clone - 克隆对象
pub fn php_clone(val: Value, allocator: Allocator) !Value {
    if (!Value_isObject(val)) {
        return error.InvalidArgument;
    }

    const orig_obj = Value_asObject(val);

    // 创建新对象
    const new_obj = try PHPObject.init(allocator, orig_obj.class_name);

    // 复制属性 — PHP 语义：数组属性做浅拷贝（复制数组结构），对象属性共享引用
    var iter = orig_obj.properties.iterator();
    while (iter.next()) |entry| {
        const key = entry.key_ptr.*;
        const value = entry.value_ptr.*;
        if (value.isArray()) {
            // 数组是值类型，clone 时应复制一份（浅拷贝）
            const cloned_arr = try value.asArray().cloneShallow(allocator);
            try new_obj.putProperty(key, Value.initArray(cloned_arr));
        } else {
            try new_obj.putProperty(key, value.retain());
        }
    }

    // 复制class_meta
    new_obj.class_meta = orig_obj.class_meta;

    const new_val = Value_initObject(new_obj);

    // 调用__clone魔术方法
    if (new_obj.class_meta) |meta| {
        if (meta.findMethodLookup("__clone")) |lookup| {
            const guard = ClassContext.init(meta, lookup.owner);
            defer guard.deinit();
            // PHP 8.1+: __clone 中允许重新初始化 readonly 属性
            in_clone_context = true;
            defer in_clone_context = false;
            _ = try lookup.method.func(new_val, &.{}, allocator);
        }
    }

    return new_val;
}

/// 将引用推入数组
/// 用于 $arr[] = &$var 语法
pub fn php_array_push_ref(arr_val: Value, ref_val: Value, _: Value) !void {
    if (!arr_val.isArray()) return;
    const arr = arr_val.asArray();
    try arr.pushRef(ref_val);
}

/// 将引用设置到数组
/// 用于 $arr[$key] = &$var 语法
pub fn php_array_set_ref(arr_val: Value, key_val: Value, ref_val: Value, _: Value) !void {
    if (!arr_val.isArray()) return;
    const arr = arr_val.asArray();
    const key = normalizeArrayKeyFromValue(key_val);
    try arr.setRef(key, ref_val);
}

/// 从值创建引用（用于全局变量的引用）
pub fn php_make_ref_from_value(val: Value) !Value {
    // 创建真正的引用：分配堆单元，将值放入，返回 Ref 指向该单元
    // 调用方负责将返回的 Ref 存入目标变量，同时将源变量也更新为同一 Ref
    const cell = try runtime_allocator.create(Value);
    cell.* = val;
    _ = cell.retain();
    return Value.initRef(cell);
}

// ============================================================================
// 字符串插值函数
// ============================================================================

/// php_interpolate - 字符串插值（将多个值连接成字符串）
///
/// 这个函数接收一个Value数组，将每个值转换为字符串并连接起来。
/// 这是PHP字符串插值的核心实现，例如：
/// ```php
/// $name = "Alice";
/// $age = 30;
/// echo "Hello, $name! You are $age years old.";
/// ```
///
/// @param parts 要插值的值数组
/// @param allocator 内存分配器
/// @return 插值后的字符串Value
pub fn php_interpolate(parts: []const Value, allocator: Allocator) !Value {
    if (parts.len == 0) {
        // 空数组，返回空字符串
        return Value.initString(try PHPString.init(allocator, ""));
    }

    if (parts.len == 1) {
        // 单个值，直接转换为字符串
        const str = try parts[0].toString(allocator);
        return Value.initString(str);
    }

    // 多个值，需要连接
    // 首先计算总长度
    var total_length: usize = 0;
    var temp_strings = try allocator.alloc(*PHPString, parts.len);
    defer {
        // 释放临时字符串
        for (temp_strings) |str| {
            str.release(allocator);
        }
        allocator.free(temp_strings);
    }

    // 将每个值转换为字符串
    for (parts, 0..) |part, i| {
        const str = try part.toString(allocator);
        temp_strings[i] = str;
        total_length += str.length;
    }

    // 分配结果缓冲区
    const result_data = try allocator.alloc(u8, total_length);
    errdefer allocator.free(result_data);

    // 连接所有字符串
    var offset: usize = 0;
    for (temp_strings) |str| {
        if (str.length > 0) {
            @memcpy(result_data[offset .. offset + str.length], str.data[0..str.length]);
            offset += str.length;
        }
    }

    // 创建结果字符串
    const result = try allocPHPString(allocator);
    errdefer destroyPHPString(result, allocator);

    result.data = result_data;
    result.length = total_length;
    result.ref_count = 1;
    result.is_static = false;

    return Value.initString(result);
}

// ============================================================================
// PHP类元数据和对象类型
// ============================================================================

/// 方法签名类型
pub const MethodFn = *const fn (this: Value, args: []const Value, allocator: Allocator) anyerror!Value;

/// 类方法定义
pub const ClassMethod = struct {
    name: []const u8,
    func: MethodFn,
    is_static: bool = false,
    is_public: bool = true,
    is_protected: bool = false,
    is_private: bool = false,
    is_abstract: bool = false,
    is_final: bool = false,
    param_count: u16 = 0,
    required_params: u16 = 0,
    param_names: []const []const u8 = &.{},
    /// 参数类型字符串列表，与 param_names 一一对应（无类型声明时为空字符串）
    param_types: []const []const u8 = &.{},
    /// 参数是否允许 null（nullable 类型或无类型声明）
    param_nullable: []const bool = &.{},
    /// ★F-155：参数是否变参（与 param_names 同序）
    param_variadic: []const bool = &.{},
    /// AOT-CODEGEN-012 F-118：形参默认值（与 `param_names` 同序）。
    /// ★拆成「值数组 + 可知位数组」两条平行数组，而非 `[]?Value`——模板里今天没有
    ///   `&[_]?Value{…}` 的发射先例，上一版那样发会让 string 默认值读回成 `float(2.1e-314)`（工单 §99）。
    param_default_values: []const Value = &.{},
    /// `param_default_known[i]` ＝ true 表示 `param_default_values[i]` 是**编译期折叠出来**的真默认值；
    /// false 表示「有默认值但折叠不出常量」或「根本没有默认值」——两者都由反射侧按 PHP 口径抛异常，禁当成 null。
    param_default_known: []const bool = &.{},
    /// ★F-118b（R-246）：`param_default_factories[i]` 非空 ⇒ 该形参默认值不可编译期折叠
    ///（如 `new stdClass`），反射每次 `getDefaultValue()` 调用它重新求值（PHP 每人一份新实例）。
    param_default_factories: []const ?MethodFn = &.{},
    /// 返回类型字符串（无返回类型声明时为 null）
    return_type: ?[]const u8 = null,
    /// 返回类型是否 nullable
    return_nullable: bool = false,
    /// PHP attributes (#[...]) — 存储为 PHPArray of ReflectionAttribute 对象
    attributes: ?Value = null,
};

/// 类属性定义
pub const ClassProperty = struct {
    name: []const u8,
    default_value: ?Value = null,
    is_static: bool = false,
    is_public: bool = true,
    is_protected: bool = false,
    is_private: bool = false,
    is_readonly: bool = false,
    /// 属性类型字符串（无类型声明时为 null）
    type_name: ?[]const u8 = null,
    /// 属性类型是否 nullable
    type_nullable: bool = false,
    /// 是否有默认值（class body 中声明了默认值）
    has_default: bool = false,
    /// PHP attributes (#[...]) — 存储为 PHPArray of ReflectionAttribute 对象
    attributes: ?Value = null,
};

/// 类元数据
/// 存储类的完整定义，包括方法、属性、继承关系、接口等
/// ★F-163（R-324）：类常量可见性枚举。常量值仍存 static_properties，
/// const_visibility 兼作「这个名字是常量」的权威名单（F-169：常量与静态属性同表，
/// 须用名单区分命名空间）。
pub const ConstVisibility = enum { public, protected, private };

pub const ClassMeta = struct {
    name: []const u8,
    parent: ?*const ClassMeta = null,
    interfaces: []const []const u8 = &.{},
    methods: std.StringHashMap(ClassMethod),
    method_order: std.ArrayList([]const u8) = .empty,
    properties: std.StringHashMap(ClassProperty),
    property_order: std.ArrayList([]const u8),
    static_properties: std.StringHashMap(Value),
    /// ★F-163：类常量名 → 可见性（兼作「这个名字是常量」的权威名单）
    const_visibility: std.StringHashMap(ConstVisibility),
    /// ★F-217（R-325）：类常量**值**的独立表——与 static_properties 命名空间物理隔离
    ///（PHP 允许 `const prop` 与 `static $prop` 同名共存）。枚举 case 值也在此表。
    class_constants: std.StringHashMap(Value),
    /// ★R-344c-a（§273.2）：枚举 case **惰性实例化**登记表（case 名 → backing 标量，null=pure case）。
    ///   PHP 真值：case 对象在**首访**（`En::A` / `cases()` / `from()` / unserialize E:）时才创建
    ///   （烧对象 id）；登记期只入本表与 class_constants 的 Missing 占位，不建对象。
    ///   物化后即从本表移除（对象唯一缓存于 class_constants）。
    enum_lazy_cases: ?std.StringHashMap(?Value) = null,
    is_abstract: bool = false,
    is_final: bool = false,
    is_interface: bool = false, // 是否为接口
    is_trait: bool = false, // 是否为trait
    is_enum: bool = false, // 是否为enum
    allocator: Allocator,

    /// 魔法函数指针
    magic_construct: ?MethodFn = null,
    magic_destruct: ?MethodFn = null,
    magic_call: ?MethodFn = null,
    magic_callStatic: ?MethodFn = null,
    magic_get: ?MethodFn = null,
    magic_set: ?MethodFn = null,
    magic_isset: ?MethodFn = null,
    magic_unset: ?MethodFn = null,
    magic_toString: ?MethodFn = null,
    magic_invoke: ?MethodFn = null,
    magic_clone: ?MethodFn = null,
    magic_sleep: ?MethodFn = null,
    magic_wakeup: ?MethodFn = null,
    magic_serialize: ?MethodFn = null,
    magic_unserialize: ?MethodFn = null,
    magic_debugInfo: ?MethodFn = null,

    pub fn init(allocator: Allocator, name: []const u8) !*ClassMeta {
        const meta = try allocator.create(ClassMeta);
        errdefer allocator.destroy(meta);

        meta.* = .{
            .name = try allocator.dupe(u8, name),
            .methods = std.StringHashMap(ClassMethod).init(allocator),
            .method_order = try std.ArrayList([]const u8).initCapacity(allocator, 0),
            .properties = std.StringHashMap(ClassProperty).init(allocator),
            .property_order = try std.ArrayList([]const u8).initCapacity(allocator, 0),
            .static_properties = std.StringHashMap(Value).init(allocator),
            .const_visibility = std.StringHashMap(ConstVisibility).init(allocator),
            .class_constants = std.StringHashMap(Value).init(allocator),
            .allocator = allocator,
        };
        return meta;
    }

    pub fn deinit(self: *ClassMeta) void {
        // 先释放静态属性（可能包含对象引用）
        var iter = self.static_properties.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.release(self.allocator);
        }
        self.static_properties.deinit();
        self.const_visibility.deinit();
        // ★F-217：类常量值表同例释放
        var cc_iter = self.class_constants.iterator();
        while (cc_iter.next()) |entry| {
            entry.value_ptr.release(self.allocator);
        }
        self.class_constants.deinit();

        // 再释放其他资源
        self.methods.deinit();
        self.method_order.deinit(self.allocator);
        self.properties.deinit();
        self.property_order.deinit(self.allocator);
        self.allocator.free(self.name);
        self.allocator.destroy(self);
    }

    /// AOT-CODEGEN-012 R-138：受声明/注册序登记（addMethod 的登记内核）。
    /// 内部类（Generator/SplFixedArray/迭代器族共 28 处）原以 `methods.put` 直注 ⇒
    /// method_order 为空 ⇒ get_class_methods 于这些类被枚举成空数组（PHP 真值为注册序，
    /// 实测 SplFixedArray 15 枚 = __construct|__wakeup|__serialize|__unserialize…）。
    /// 故这些站点统一改走本入口，且刻意不触发 addMethod 的 magic_* 派发副作用。
    pub fn putMethodOrdered(self: *ClassMeta, method: ClassMethod) !void {
        // 同名覆盖保持首位 ⇒ 与 PHP「子类覆写沿用其在表中的位次」一致。
        if (!self.methods.contains(method.name)) {
            try self.method_order.append(self.allocator, method.name);
        }
        try self.methods.put(method.name, method);
    }

    /// 添加方法
    pub fn addMethod(self: *ClassMeta, method: ClassMethod) !void {
        try self.putMethodOrdered(method);
        if (std.mem.eql(u8, method.name, "__construct")) self.magic_construct = method.func;
        if (std.mem.eql(u8, method.name, "__destruct")) self.magic_destruct = method.func;
        if (std.mem.eql(u8, method.name, "__get")) self.magic_get = method.func;
        if (std.mem.eql(u8, method.name, "__set")) self.magic_set = method.func;
        if (std.mem.eql(u8, method.name, "__isset")) self.magic_isset = method.func;
        if (std.mem.eql(u8, method.name, "__unset")) self.magic_unset = method.func;
        if (std.mem.eql(u8, method.name, "__call")) self.magic_call = method.func;
        if (std.mem.eql(u8, method.name, "__callStatic")) self.magic_callStatic = method.func;
        if (std.mem.eql(u8, method.name, "__toString")) self.magic_toString = method.func;
        if (std.mem.eql(u8, method.name, "__invoke")) self.magic_invoke = method.func;
        if (std.mem.eql(u8, method.name, "__clone")) self.magic_clone = method.func;
        if (std.mem.eql(u8, method.name, "__sleep")) self.magic_sleep = method.func;
        if (std.mem.eql(u8, method.name, "__wakeup")) self.magic_wakeup = method.func;
        if (std.mem.eql(u8, method.name, "__serialize")) self.magic_serialize = method.func;
        if (std.mem.eql(u8, method.name, "__unserialize")) self.magic_unserialize = method.func;
        if (std.mem.eql(u8, method.name, "__debugInfo")) self.magic_debugInfo = method.func;
    }

    pub const MethodLookup = struct {
        owner: *const ClassMeta,
        method: *const ClassMethod,
    };

    pub fn findMethodLookup(self: *const ClassMeta, name: []const u8) ?MethodLookup {
        if (self.methods.getPtr(name)) |method| {
            return .{ .owner = self, .method = method };
        }
        if (self.parent) |parent| {
            if (parent.findMethodLookup(name)) |lookup| {
                return lookup;
            }
        }
        // ★F-156：接口方法可经 implements/extends 的接口链解析（声明类仍是接口 owner）。
        for (self.interfaces) |iface_name| {
            if (findClass(iface_name)) |iface_meta| {
                if (iface_meta.findMethodLookup(name)) |lookup| {
                    return lookup;
                }
            }
        }
        // AOT-CODEGEN-012 R-131：方法名 CI（PHP 方法名不区分大小写）——精确链全 miss 后
        // 沿继承链 CI 扫描（仅 miss 路径付出扫描成本；28 调用者一次性受益：实例分发 /
        // method_exists / 静态分发 / __call 探测 …）
        var current: ?*const ClassMeta = self;
        while (current) |meta| {
            var it = meta.methods.iterator();
            while (it.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, name)) {
                    return .{ .owner = meta, .method = entry.value_ptr };
                }
            }
            current = meta.parent;
        }
        return null;
    }

    /// 查找方法（包括继承链）
    pub fn findMethod(self: *const ClassMeta, name: []const u8) ?ClassMethod {
        if (self.methods.get(name)) |method| {
            return method;
        }
        if (self.parent) |parent| {
            if (parent.findMethod(name)) |method| {
                return method;
            }
        }
        // AOT-CODEGEN-012 R-131：方法名 CI（同 findMethodLookup）
        var current: ?*const ClassMeta = self;
        while (current) |meta| {
            var it = meta.methods.iterator();
            while (it.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, name)) {
                    return entry.value_ptr.*;
                }
            }
            current = meta.parent;
        }
        return null;
    }

    // ========================================================================
    // DateTime 扩展格式化函数 - 支持完整的 PHP date() 格式
    // ========================================================================

    /// 完整的DateTime格式化器，支持时区偏移
    const DateTimeFormatter = struct {
        timestamp: i64,
        microseconds: i64,
        timezone_offset: i32,
        timezone_name: []const u8,

        fn isLeapYear(year: i64) bool {
            return (@rem(year, 4) == 0 and @rem(year, 100) != 0) or (@rem(year, 400) == 0);
        }

        fn getDaysInMonth(year: i64, month: u32) u32 {
            return switch (month) {
                1, 3, 5, 7, 8, 10, 12 => 31,
                4, 6, 9, 11 => 30,
                2 => if (isLeapYear(year)) 29 else 28,
                else => 31,
            };
        }

        fn getDayOfYear(year: i64, month: u32, day: u32) u32 {
            var doy: u32 = 0;
            var m: u32 = 1;
            while (m < month) : (m += 1) doy += getDaysInMonth(year, m);
            return doy + day;
        }

        fn getDayOfWeek(year: i64, month: u32, day: u32) u32 {
            const y = if (month < 3) year - 1 else year;
            const m = if (month < 3) month + 12 else month;
            const w = @mod(day + @divFloor(13 * (m + 1), 5) + y + @divFloor(y, 4) - @divFloor(y, 100) + @divFloor(y, 400), 7);
            return @intCast(w);
        }

        fn getIsoWeek(year: i64, month: u32, day: u32) u32 {
            const doy = getDayOfYear(year, month, day);
            const wday = getDayOfWeek(year, month, day);
            const iso_wday = if (wday == 0) @as(i64, 7) else @as(i64, wday);
            var week = @divFloor(@as(i64, doy) - iso_wday + 10, 7);
            if (week < 1) week = if (isLeapYear(year - 1)) 53 else 52 else if (week > 52 and doy - iso_wday > 365 - (if (isLeapYear(year)) @as(i64, 1) else @as(i64, 0))) week = 1;
            return @intCast(week);
        }

        pub fn format(self: *const DateTimeFormatter, format_str: []const u8, allocator: Allocator) !Value {
            const epoch_seconds: u64 = @intCast(@max(@as(i64, 0), self.timestamp));
            const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_seconds };
            const day_seconds = epoch.getDaySeconds();
            const year_day = epoch.getEpochDay().calculateYearDay();
            const month_day = year_day.calculateMonthDay();

            const year = year_day.year;
            const month = month_day.month.numeric();
            const day = month_day.day_index + 1;
            const hour = day_seconds.getHoursIntoDay();
            const minute = day_seconds.getMinutesIntoHour();
            const second = day_seconds.getSecondsIntoMinute();

            var aw = std.Io.Writer.Allocating.initCapacity(allocator, format_str.len * 3) catch return Value.initNull();
            defer aw.deinit();

            var i: usize = 0;
            while (i < format_str.len) : (i += 1) {
                const c = format_str[i];
                switch (c) {
                    'Y' => try aw.writer.print("{d:0>4}", .{year}),
                    'y' => try aw.writer.print("{d:0>2}", .{year % 100}),
                    'L' => try aw.writer.print("{d}", .{if (isLeapYear(year)) @as(u32, 1) else @as(u32, 0)}),
                    'm' => try aw.writer.print("{d:0>2}", .{month}),
                    'n' => try aw.writer.print("{d}", .{month}),
                    'F' => try aw.writer.writeAll(switch (month) {
                        1 => "January",
                        2 => "February",
                        3 => "March",
                        4 => "April",
                        5 => "May",
                        6 => "June",
                        7 => "July",
                        8 => "August",
                        9 => "September",
                        10 => "October",
                        11 => "November",
                        12 => "December",
                        else => "Unknown",
                    }),
                    'M' => try aw.writer.writeAll(switch (month) {
                        1 => "Jan",
                        2 => "Feb",
                        3 => "Mar",
                        4 => "Apr",
                        5 => "May",
                        6 => "Jun",
                        7 => "Jul",
                        8 => "Aug",
                        9 => "Sep",
                        10 => "Oct",
                        11 => "Nov",
                        12 => "Dec",
                        else => "???",
                    }),
                    't' => try aw.writer.print("{d}", .{getDaysInMonth(year, month)}),
                    'd' => try aw.writer.print("{d:0>2}", .{day}),
                    'j' => try aw.writer.print("{d}", .{day}),
                    'S' => try aw.writer.writeAll(if (day >= 11 and day <= 13) "th" else switch (day % 10) {
                        1 => "st",
                        2 => "nd",
                        3 => "rd",
                        else => "th",
                    }),
                    'z' => try aw.writer.print("{d}", .{getDayOfYear(year, month, day) - 1}),
                    'l' => try aw.writer.writeAll(switch (getDayOfWeek(year, month, day)) {
                        0 => "Sunday",
                        1 => "Monday",
                        2 => "Tuesday",
                        3 => "Wednesday",
                        4 => "Thursday",
                        5 => "Friday",
                        6 => "Saturday",
                        else => "Unknown",
                    }),
                    'D' => try aw.writer.writeAll(switch (getDayOfWeek(year, month, day)) {
                        0 => "Sun",
                        1 => "Mon",
                        2 => "Tue",
                        3 => "Wed",
                        4 => "Thu",
                        5 => "Fri",
                        6 => "Sat",
                        else => "???",
                    }),
                    'w' => try aw.writer.print("{d}", .{getDayOfWeek(year, month, day)}),
                    'N' => {
                        const n = getDayOfWeek(year, month, day);
                        try aw.writer.print("{d}", .{if (n == 0) @as(u32, 7) else n});
                    },
                    'W' => try aw.writer.print("{d:0>2}", .{getIsoWeek(year, month, day)}),
                    'H' => try aw.writer.print("{d:0>2}", .{hour}),
                    'G' => try aw.writer.print("{d}", .{hour}),
                    'h' => {
                        const h12 = if (hour == 0) @as(u32, 12) else if (hour > 12) hour - 12 else hour;
                        try aw.writer.print("{d:0>2}", .{h12});
                    },
                    'g' => {
                        const h12 = if (hour == 0) @as(u32, 12) else if (hour > 12) hour - 12 else hour;
                        try aw.writer.print("{d}", .{h12});
                    },
                    'a' => try aw.writer.writeAll(if (hour < 12) "am" else "pm"),
                    'A' => try aw.writer.writeAll(if (hour < 12) "AM" else "PM"),
                    'i' => try aw.writer.print("{d:0>2}", .{minute}),
                    's' => try aw.writer.print("{d:0>2}", .{second}),
                    'u' => try aw.writer.print("{d:0>6}", .{self.microseconds}),
                    'v' => try aw.writer.print("{d:0>3}", .{@divFloor(self.microseconds, 1000)}),
                    'T' => try aw.writer.writeAll(self.timezone_name),
                    'O' => {
                        const oh = @divFloor(self.timezone_offset, 3600);
                        const om = @divFloor(@rem(self.timezone_offset, 3600), 60);
                        if (oh >= 0) try aw.writer.print("+{d:0>2}{d:0>2}", .{ oh, @abs(om) }) else try aw.writer.print("{d:0>3}{d:0>2}", .{ oh, @abs(om) });
                    },
                    'P' => {
                        const oh = @divFloor(self.timezone_offset, 3600);
                        const om = @divFloor(@rem(self.timezone_offset, 3600), 60);
                        if (oh >= 0) try aw.writer.print("+{d:0>2}:{d:0>2}", .{ oh, @abs(om) }) else try aw.writer.print("{d:0>3}:{d:0>2}", .{ oh, @abs(om) });
                    },
                    'Z' => try aw.writer.print("{d}", .{self.timezone_offset}),
                    'U' => try aw.writer.print("{d}", .{self.timestamp}),
                    'c' => {
                        try aw.writer.print("{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}", .{ year, month, day, hour, minute, second });
                        const oh = @divFloor(self.timezone_offset, 3600);
                        const om = @divFloor(@rem(self.timezone_offset, 3600), 60);
                        if (oh >= 0) try aw.writer.print("+{d:0>2}:{d:0>2}", .{ oh, @abs(om) }) else try aw.writer.print("{d:0>3}:{d:0>2}", .{ oh, @abs(om) });
                    },
                    'r' => {
                        const wd = switch (getDayOfWeek(year, month, day)) {
                            0 => "Sun",
                            1 => "Mon",
                            2 => "Tue",
                            3 => "Wed",
                            4 => "Thu",
                            5 => "Fri",
                            6 => "Sat",
                            else => "???",
                        };
                        const mon = switch (month) {
                            1 => "Jan",
                            2 => "Feb",
                            3 => "Mar",
                            4 => "Apr",
                            5 => "May",
                            6 => "Jun",
                            7 => "Jul",
                            8 => "Aug",
                            9 => "Sep",
                            10 => "Oct",
                            11 => "Nov",
                            12 => "Dec",
                            else => "???",
                        };
                        const oh = @divFloor(self.timezone_offset, 3600);
                        const om = @divFloor(@rem(self.timezone_offset, 3600), 60);
                        if (oh >= 0) try aw.writer.print("{s}, {d} {s} {d} {d:0>2}:{d:0>2}:{d:0>2} +{d:0>2}{d:0>2}", .{ wd, day, mon, year, hour, minute, second, oh, @abs(om) }) else try aw.writer.print("{s}, {d} {s} {d} {d:0>2}:{d:0>2}:{d:0>2} -{d:0>2}{d:0>2}", .{ wd, day, mon, year, hour, minute, second, @abs(oh), @abs(om) });
                    },
                    '\\' => {
                        i += 1;
                        if (i < format_str.len) try aw.writer.writeAll(format_str[i .. i + 1]);
                    },
                    else => try aw.writer.writeAll(&[_]u8{c}),
                }
            }
            return Value.initString(try PHPString.init(allocator, aw.written()));
        }
    };

    fn formatDateTimeWithFormat(timestamp: i64, format_str: []const u8, allocator: Allocator) !Value {
        const formatter = DateTimeFormatter{ .timestamp = timestamp, .microseconds = 0, .timezone_offset = 0, .timezone_name = "UTC" };
        return formatter.format(format_str, allocator);
    }

    fn formatDateTimeYmd(timestamp: i64, allocator: Allocator) !Value {
        return formatDateTimeWithFormat(timestamp, "Y-m-d", allocator);
    }

    fn registerStdClass(allocator: Allocator) !void {
        if (findClass("stdClass") != null) return;
        const meta = try ClassMeta.init(allocator, "stdClass");
        try registerClass(meta);
    }

    // ========================================================================
    // 时区数据库 (简化版)
    // ========================================================================

    const TimezoneInfo = struct { name: []const u8, offset_seconds: i32, abbreviation: []const u8 };
    const TIMEZONE_DATABASE: []const TimezoneInfo = &[_]TimezoneInfo{
        .{ .name = "UTC", .offset_seconds = 0, .abbreviation = "UTC" },
        .{ .name = "GMT", .offset_seconds = 0, .abbreviation = "GMT" },
        .{ .name = "America/New_York", .offset_seconds = -18000, .abbreviation = "EST" },
        .{ .name = "America/Chicago", .offset_seconds = -21600, .abbreviation = "CST" },
        .{ .name = "America/Denver", .offset_seconds = -25200, .abbreviation = "MST" },
        .{ .name = "America/Los_Angeles", .offset_seconds = -28800, .abbreviation = "PST" },
        .{ .name = "Europe/London", .offset_seconds = 0, .abbreviation = "GMT" },
        .{ .name = "Europe/Paris", .offset_seconds = 3600, .abbreviation = "CET" },
        .{ .name = "Europe/Berlin", .offset_seconds = 3600, .abbreviation = "CET" },
        .{ .name = "Europe/Moscow", .offset_seconds = 10800, .abbreviation = "MSK" },
        .{ .name = "Asia/Shanghai", .offset_seconds = 28800, .abbreviation = "CST" },
        .{ .name = "Asia/Beijing", .offset_seconds = 28800, .abbreviation = "CST" },
        .{ .name = "Asia/Hong_Kong", .offset_seconds = 28800, .abbreviation = "HKT" },
        .{ .name = "Asia/Tokyo", .offset_seconds = 32400, .abbreviation = "JST" },
        .{ .name = "Asia/Seoul", .offset_seconds = 32400, .abbreviation = "KST" },
        .{ .name = "Asia/Singapore", .offset_seconds = 28800, .abbreviation = "SGT" },
        .{ .name = "Australia/Sydney", .offset_seconds = 36000, .abbreviation = "AEST" },
    };

    fn findTimezone(name: []const u8) ?TimezoneInfo {
        for (TIMEZONE_DATABASE) |tz| if (std.mem.eql(u8, tz.name, name)) return tz;
        return null;
    }

    fn parseTimezoneOffset(tz_str: []const u8) ?i32 {
        if (findTimezone(tz_str)) |tz| return tz.offset_seconds;
        if (tz_str.len >= 3 and (tz_str[0] == '+' or tz_str[0] == '-')) {
            const sign: i32 = if (tz_str[0] == '+') 1 else -1;
            const rest = tz_str[1..];
            var hours: i32 = 0;
            var minutes: i32 = 0;
            if (rest.len == 2) hours = std.fmt.parseInt(i32, rest, 10) catch return null else if (rest.len == 4) {
                hours = std.fmt.parseInt(i32, rest[0..2], 10) catch return null;
                minutes = std.fmt.parseInt(i32, rest[2..4], 10) catch return null;
            } else if (rest.len == 5 and rest[2] == ':') {
                hours = std.fmt.parseInt(i32, rest[0..2], 10) catch return null;
                minutes = std.fmt.parseInt(i32, rest[3..5], 10) catch return null;
            }
            return sign * (hours * 3600 + minutes * 60);
        }
        return null;
    }

    // ========================================================================
    // DateTimeZone 类注册
    // ========================================================================

    fn registerDateTimeZoneClass(allocator: Allocator) !void {
        const meta = try ClassMeta.init(allocator, "DateTimeZone");
        try meta.addProperty(.{ .name = "timezone", .default_value = Value.initNull(), .is_public = false });
        try meta.addProperty(.{ .name = "__offset", .default_value = Value.initInt(0), .is_public = false });

        try meta.addMethod(.{ .name = "__construct", .func = struct {
            fn call(ctx: Value, args: []const Value, runtime_alloc: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (args.len > 0 and args[0].isString()) {
                    const tz_name = args[0].asString().data;
                    try this.setProperty("timezone", args[0]);
                    if (parseTimezoneOffset(tz_name)) |offset| try this.setProperty("__offset", Value.initInt(offset));
                } else {
                    try this.setProperty("timezone", Value.initString(try PHPString.init(runtime_alloc, "UTC")));
                }
                return Value.initNull();
            }
        }.call, .is_static = false });

        try meta.addMethod(.{ .name = "getName", .func = struct {
            fn call(ctx: Value, _: []const Value, _: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (this.getProperty("timezone")) |tz| {
                    _ = tz.retain();
                    return tz;
                }
                return Value.initString(try PHPString.init(runtime_allocator, "UTC"));
            }
        }.call, .is_static = false });

        try meta.addMethod(.{ .name = "getOffset", .func = struct {
            fn call(ctx: Value, _: []const Value, _: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (this.getProperty("__offset")) |offset| return offset;
                return Value.initInt(0);
            }
        }.call, .is_static = false });

        meta.magic_construct = meta.methods.get("__construct").?.func;
        try registerClass(meta);
    }

    // ========================================================================
    // DateInterval 类注册
    // ========================================================================

    fn registerDateIntervalClass(allocator: Allocator) !void {
        const meta = try ClassMeta.init(allocator, "DateInterval");
        try meta.addProperty(.{ .name = "y", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "m", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "d", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "h", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "i", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "s", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "f", .default_value = Value.initFloat(0.0), .is_public = true });
        try meta.addProperty(.{ .name = "invert", .default_value = Value.initInt(0), .is_public = true });
        try meta.addProperty(.{ .name = "days", .default_value = Value.initBool(false), .is_public = true });

        // __construct(string $duration) - 解析 ISO 8601 duration
        try meta.addMethod(.{ .name = "__construct", .func = struct {
            fn call(ctx: Value, args: []const Value, _: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (args.len == 0 or !args[0].isString()) return Value.initNull();
                const spec = args[0].asString().data;
                if (spec.len < 1 or spec[0] != 'P') return error.InvalidDateIntervalSpecification;

                var y: i64 = 0;
                var m: i64 = 0;
                var d: i64 = 0;
                var h: i64 = 0;
                var i: i64 = 0;
                var s: i64 = 0;
                var in_time = false;
                var pos: usize = 1;
                var num_buf: [32]u8 = undefined;
                var num_len: usize = 0;

                while (pos < spec.len) {
                    const c = spec[pos];
                    if (c >= '0' and c <= '9' or c == '.') {
                        if (num_len < 32) {
                            num_buf[num_len] = c;
                            num_len += 1;
                        }
                        pos += 1;
                    } else if (c == 'T') {
                        in_time = true;
                        pos += 1;
                        num_len = 0;
                    } else {
                        const num_str = num_buf[0..num_len];
                        const num_val = std.fmt.parseFloat(f64, num_str) catch 0;
                        switch (c) {
                            'Y' => {
                                y = @intFromFloat(num_val);
                            },
                            'M' => {
                                if (in_time) i = @intFromFloat(num_val) else m = @intFromFloat(num_val);
                            },
                            'D' => {
                                d = @intFromFloat(num_val);
                            },
                            'H' => {
                                h = @intFromFloat(num_val);
                            },
                            'S' => {
                                s = @intFromFloat(@floor(num_val));
                            },
                            else => {},
                        }
                        pos += 1;
                        num_len = 0;
                    }
                }
                try this.setProperty("y", Value.initInt(y));
                try this.setProperty("m", Value.initInt(m));
                try this.setProperty("d", Value.initInt(d));
                try this.setProperty("h", Value.initInt(h));
                try this.setProperty("i", Value.initInt(i));
                try this.setProperty("s", Value.initInt(s));
                return Value.initNull();
            }
        }.call, .is_static = false });

        // format(string $format)
        try meta.addMethod(.{ .name = "format", .func = struct {
            fn call(ctx: Value, args: []const Value, alloc: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (args.len == 0 or !args[0].isString()) return Value.initString(try PHPString.init(alloc, ""));
                const format_str = args[0].asString().data;
                var aw = std.Io.Writer.Allocating.initCapacity(alloc, format_str.len * 2) catch return Value.initString(try PHPString.init(alloc, ""));
                defer aw.deinit();

                const y = if (this.getProperty("y")) |v| v.toInt() else 0;
                const m = if (this.getProperty("m")) |v| v.toInt() else 0;
                const d = if (this.getProperty("d")) |v| v.toInt() else 0;
                const h = if (this.getProperty("h")) |v| v.toInt() else 0;
                const i = if (this.getProperty("i")) |v| v.toInt() else 0;
                const s = if (this.getProperty("s")) |v| v.toInt() else 0;
                const invert = if (this.getProperty("invert")) |v| v.toInt() else 0;

                var fi: usize = 0;
                while (fi < format_str.len) : (fi += 1) {
                    if (format_str[fi] == '%' and fi + 1 < format_str.len) {
                        fi += 1;
                        switch (format_str[fi]) {
                            'Y' => try aw.writer.print("{d:0>2}", .{y}),
                            'y' => try aw.writer.print("{d}", .{y}),
                            'M' => try aw.writer.print("{d:0>2}", .{m}),
                            'm' => try aw.writer.print("{d}", .{m}),
                            'D' => try aw.writer.print("{d:0>2}", .{d}),
                            'd' => try aw.writer.print("{d}", .{d}),
                            'H' => try aw.writer.print("{d:0>2}", .{h}),
                            'h' => try aw.writer.print("{d}", .{h}),
                            'I' => try aw.writer.print("{d:0>2}", .{i}),
                            'i' => try aw.writer.print("{d}", .{i}),
                            'S' => try aw.writer.print("{d:0>2}", .{s}),
                            's' => try aw.writer.print("{d}", .{s}),
                            'R' => try aw.writer.writeAll(if (invert == 1) "-" else "+"),
                            'r' => try aw.writer.writeAll(if (invert == 1) "-" else ""),
                            '%' => try aw.writer.writeAll("%"),
                            'a' => {
                                const days_val = if (this.getProperty("days")) |v| v.toInt() else 0;
                                try aw.writer.print("{d}", .{days_val});
                            },
                            else => {
                                try aw.writer.writeAll(&[_]u8{ '%', format_str[fi] });
                            },
                        }
                    } else {
                        try aw.writer.writeAll(&[_]u8{format_str[fi]});
                    }
                }
                return Value.initString(try PHPString.init(alloc, aw.written()));
            }
        }.call, .is_static = false });

        // createFromDateString(string $datetime)
        try meta.addMethod(.{ .name = "createFromDateString", .func = struct {
            fn call(_: Value, args: []const Value, alloc: Allocator) anyerror!Value {
                if (args.len == 0 or !args[0].isString()) return Value.initNull();
                const spec = args[0].asString().data;
                var y: i64 = 0;
                var m: i64 = 0;
                var d: i64 = 0;
                var h: i64 = 0;
                var i: i64 = 0;
                var s: i64 = 0;
                var pos: usize = 0;

                while (pos < spec.len) {
                    while (pos < spec.len and spec[pos] == ' ') pos += 1;
                    if (pos >= spec.len) break;
                    var num: i64 = 0;
                    while (pos < spec.len and spec[pos] >= '0' and spec[pos] <= '9') {
                        num = num * 10 + (spec[pos] - '0');
                        pos += 1;
                    }
                    while (pos < spec.len and spec[pos] == ' ') pos += 1;
                    const start = pos;
                    while (pos < spec.len and spec[pos] >= 'a' and spec[pos] <= 'z') pos += 1;
                    const unit = spec[start..pos];

                    if (std.mem.startsWith(u8, unit, "year")) y += num else if (std.mem.startsWith(u8, unit, "month")) m += num else if (std.mem.startsWith(u8, unit, "day")) d += num else if (std.mem.startsWith(u8, unit, "hour")) h += num else if (std.mem.startsWith(u8, unit, "minute")) i += num else if (std.mem.startsWith(u8, unit, "second")) s += num else if (std.mem.startsWith(u8, unit, "week")) d += num * 7;
                }

                const meta_ptr = findClass("DateInterval") orelse return Value.initNull();
                const obj = try PHPObject.initWithMeta(alloc, meta_ptr);
                try obj.setProperty("y", Value.initInt(y));
                try obj.setProperty("m", Value.initInt(m));
                try obj.setProperty("d", Value.initInt(d));
                try obj.setProperty("h", Value.initInt(h));
                try obj.setProperty("i", Value.initInt(i));
                try obj.setProperty("s", Value.initInt(s));
                return Value_initObject(obj);
            }
