    fn registerDatePeriodClass(allocator: Allocator) !void {
        const meta = try ClassMeta.init(allocator, "DatePeriod");
        meta.interfaces = &DATE_PERIOD_INTERFACES; // ★F-3（R-336）：PHP 8.5.8 实测传递闭包
