                                }
                            }
                            // ★F-155：registry 条目一次查找同时供名字/默认值/工厂
                            var rf_fm: ?FunctionMeta = null;
                            if (this.getPropertyDirect("__func_name")) |fname_val| {
                                if (fname_val.isString()) {
                                    if (function_meta_registry) |reg| {
                                        if (reg.get(fname_val.asString().data)) |fm| {
                                            rf_fm = fm;
                                            if (resolved_name == null and idx < fm.param_names.len) resolved_name = fm.param_names[idx];
                                        }
                                    }
                                }
                            }
                            if (resolved_name) |rn| {
                                try param_obj.setProperty("__name", Value.initString(try PHPString.init(alloc, rn)));
                            } else {
                                const param_name = try std.fmt.allocPrint(alloc, "param{d}", .{i});
                                try param_obj.setProperty("__name", Value.initString(try PHPString.init(alloc, param_name)));
                            }
                            // AOT-CODEGEN-012 F-8：ReflectionFunction 路径同口径（构造时已存 __required_params）
                            // ★F-155：变参不计入 required_params，必须按 registered 变参下标单独判 has_default
                            const rf_req = (this.getPropertyDirect("__required_params") orelse pc_val).toInt();
                            var rf_has_def = i >= rf_req;
                            var rf_is_variadic = false;
                            if (clo_meta) |clo| {
                                if (clo.variadic_index != 0xFFFF and @as(usize, clo.variadic_index) == idx) {
                                    rf_is_variadic = true;
                                    rf_has_def = false;
                                }
                            } else if (rf_fm) |fm| {
                                if (fm.variadic_index != 0xFFFF and @as(usize, fm.variadic_index) == idx) {
                                    rf_is_variadic = true;
                                    rf_has_def = false;
                                }
                            }
                            try param_obj.setProperty("__has_default", Value.initBool(rf_has_def));
                            try param_obj.setProperty("__is_optional", Value.initBool(i >= rf_req));
                            try param_obj.setProperty("__is_variadic", Value.initBool(rf_is_variadic));
                            // ★F-155：默认值面——折叠值直接装填，不可折叠的留给 getDefaultValue 现查工厂
                            if (clo_meta) |clo| {
                                if (idx < clo.param_default_known.len and clo.param_default_known[idx]) {
                                    try param_obj.setProperty("__default_value", clo.param_default_values[idx]);
                                } else if (idx < clo.param_default_factories.len and clo.param_default_factories[idx] != null) {
                                    // ★F-155-b：工厂不可折叠 ⇒ 形参反持闭包，getDefaultValue 现查工厂
                                    if (this.getPropertyDirect("__closure")) |cv| {
                                        try param_obj.setProperty("__closure", cv);
                                    }
                                }
                            } else if (rf_fm) |fm| {
                                if (this.getPropertyDirect("__func_name")) |fname_val| {
                                    if (fname_val.isString()) {
                                        const owner_fn_str = try PHPString.init(alloc, fname_val.asString().data);
                                        defer owner_fn_str.release(alloc);
                                        try param_obj.setProperty("__owner_func", Value.initString(owner_fn_str));
                                    }
                                }
                                if (idx < fm.param_default_known.len and idx < fm.param_default_values.len and fm.param_default_known[idx]) {
                                    try param_obj.setProperty("__default_value", fm.param_default_values[idx]);
                                }
                            }
                            try arr.push(alloc, Value_initObject(param_obj));
                        } else {
                            // 没注册 ReflectionParameter，返回 position 整数
                            try arr.push(alloc, Value.initInt(i));
                        }
                    }
                    return Value.initArray(arr);
                }
            }.call,
            .is_static = false,
        });
        // getReturnType() - 简化实现，返回 null
        try rf_meta.addMethod(.{
            .name = "getReturnType",
            .func = struct {
                fn call(_: Value, _: []const Value, _: Allocator) anyerror!Value {
                    return Value.initNull();
                }
            }.call,
            .is_static = false,
        });
        // hasReturnType()
        try rf_meta.addMethod(.{
            .name = "hasReturnType",
            .func = struct {
                fn call(_: Value, _: []const Value, _: Allocator) anyerror!Value {
                    return Value.initBool(false);
                }
            }.call,
            .is_static = false,
        });
        rf_meta.magic_construct = rf_meta.methods.get("__construct").?.func;
        try registerClass(rf_meta);

        // Register Fiber class
        try registerFiberClass(allocator);
    }

    /// Fiber 协程状态
    const FiberState = enum(u8) {
        created,
        running,
        suspended,
        terminated,
    };

    /// Fiber 协程上下文 (线程 + 条件变量实现)
    const FiberContext = struct {
        mutex: std.Io.Mutex = .init,
        caller_cond: std.Io.Condition = .init,
        fiber_cond: std.Io.Condition = .init,
        state: FiberState = .created,
        callback: Value = Value.initNull(),
        fiber_obj: Value = Value.initNull(),
        suspend_value: Value = Value.initNull(),
        resume_value: Value = Value.initNull(),
        return_value: Value = Value.initNull(),
        throw_exception: Value = Value.initNull(),
        thread: ?std.Thread = null,
        alloc: Allocator,

        fn init(alloc: Allocator) !*FiberContext {
            const ctx = try alloc.create(FiberContext);
            ctx.* = .{ .alloc = alloc };
            return ctx;
        }
    };

    /// 当前正在执行的 Fiber 对象（线程局部）
    threadlocal var current_fiber_obj: ?Value = null;

    fn fiberThreadMain(fctx: *FiberContext) void {
        // 在 fiber 线程中设置 threadlocal
        current_fiber_obj = fctx.fiber_obj;

        while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
        while (fctx.state != .running) {
            fctx.fiber_cond.wait(getIo(), &fctx.mutex) catch {};
        }
        fctx.mutex.unlock(getIo());

        // 通过闭包函数指针调用 fiber 回调
        const cb = fctx.callback;
        var result = Value.initNull();
        if (cb.isFunction()) {
            const closure = cb.asFunction();
            result = closure.func(
                cb,
                &[_]Value{},
                fctx.alloc,
            ) catch Value.initNull();
        }

        while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
        fctx.return_value = result;
        fctx.state = .terminated;
        fctx.caller_cond.signal(getIo());
        fctx.mutex.unlock(getIo());
    }

    /// Register built-in Fiber class
    fn registerFiberClass(allocator: Allocator) !void {
        const meta = try ClassMeta.init(allocator, "Fiber");

        // __construct(callable $callback)
        try meta.addMethod(.{
            .name = "__construct",
            .func = struct {
                fn call(
                    ctx: Value,
                    args: []const Value,
                    alloc: Allocator,
                ) anyerror!Value {
                    if (args.len == 0) return Value.initNull();
                    const this = Value_asObject(ctx);
                    _ = args[0].retain();
                    try this.setProperty("__callback", args[0]);
                    try this.setProperty(
                        "__state",
                        Value.initInt(
                            @intFromEnum(FiberState.created),
                        ),
                    );
                    // 创建 FiberContext
                    const fctx = try FiberContext.init(alloc);
                    fctx.callback = args[0];
                    try this.setProperty(
                        "__fctx_addr",
                        Value.initInt(
                            @as(i64, @intCast(@intFromPtr(fctx))),
                        ),
                    );
                    return Value.initNull();
                }
            }.call,
            .is_static = false,
        });

        // start(...$args): mixed
        try meta.addMethod(.{
            .name = "start",
            .func = struct {
                fn call(
                    ctx: Value,
                    args: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    const this = Value_asObject(ctx);
                    const fctx = getFiberCtx(this) orelse
                        return Value.initNull();
                    while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
                    if (fctx.state != .created) {
                        fctx.mutex.unlock(getIo());
                        return Value.initNull();
                    }
                    if (args.len > 0) {
                        fctx.resume_value = args[0];
                    }
                    // fiber 线程通过 threadlocal 获取
                    fctx.fiber_obj = ctx;
                    fctx.state = .running;
                    // 启动线程
                    fctx.thread = std.Thread.spawn(
                        .{},
                        fiberThreadMain,
                        .{fctx},
                    ) catch {
                        fctx.mutex.unlock(getIo());
                        return Value.initNull();
                    };
                    // 信号唤醒 fiber 线程
                    fctx.fiber_cond.signal(getIo());
                    // 等待 fiber suspend 或 terminate
                    while (fctx.state == .running) {
                        fctx.caller_cond.wait(getIo(), &fctx.mutex) catch {};
                    }
                    const result = fctx.suspend_value;
                    fctx.suspend_value = Value.initNull();
                    setFiberState(this, fctx.state);
                    fctx.mutex.unlock(getIo());
                    if (fctx.state == .terminated) {
                        if (fctx.thread) |t| t.join();
                        fctx.thread = null;
                    }
                    return result;
                }
            }.call,
            .is_static = false,
        });

        // resume($value = null): mixed
        try meta.addMethod(.{
            .name = "resume",
            .func = struct {
                fn call(
                    ctx: Value,
                    args: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    const this = Value_asObject(ctx);
                    const fctx = getFiberCtx(this) orelse
                        return Value.initNull();
                    while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
                    if (fctx.state != .suspended) {
                        fctx.mutex.unlock(getIo());
                        return Value.initNull();
                    }
                    if (args.len > 0) {
                        fctx.resume_value = args[0];
                    } else {
                        fctx.resume_value = Value.initNull();
                    }
                    fctx.state = .running;
                    fctx.fiber_cond.signal(getIo());
                    while (fctx.state == .running) {
                        fctx.caller_cond.wait(getIo(), &fctx.mutex) catch {};
                    }
                    const result = fctx.suspend_value;
                    fctx.suspend_value = Value.initNull();
                    setFiberState(this, fctx.state);
                    fctx.mutex.unlock(getIo());
                    if (fctx.state == .terminated) {
                        if (fctx.thread) |t| t.join();
                        fctx.thread = null;
                    }
                    return result;
                }
            }.call,
            .is_static = false,
        });

        // Fiber::suspend($value = null): mixed (static)
        try meta.addMethod(.{
            .name = "suspend",
            .func = struct {
                fn call(
                    _: Value,
                    args: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    // 获取当前 fiber 上下文
                    const fiber_val = current_fiber_obj orelse
                        return Value.initNull();
                    if (!Value_isObject(fiber_val))
                        return Value.initNull();
                    const this = Value_asObject(fiber_val);
                    const fctx = getFiberCtx(this) orelse
                        return Value.initNull();
                    while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
                    if (args.len > 0) {
                        fctx.suspend_value = args[0];
                    }
                    fctx.state = .suspended;
                    fctx.caller_cond.signal(getIo());
                    // 等待 resume 或 throw
                    while (fctx.state == .suspended) {
                        fctx.fiber_cond.wait(getIo(), &fctx.mutex) catch {};
                    }
                    const result = fctx.resume_value;
                    fctx.resume_value = Value.initNull();
                    // 检查是否有 throw 传入的异常
                    const thrown = fctx.throw_exception;
                    fctx.throw_exception = Value.initNull();
                    fctx.mutex.unlock(getIo());
                    // 在 fiber 线程设置异常（不返回 Zig 错误，
                    // 由生成代码的 hasException() 路由到 catch）
                    if (!thrown.isNull()) {
                        setException(thrown);
                        return Value.initNull();
                    }
                    return result;
                }
            }.call,
            .is_static = true,
        });

        // isStarted(): bool
        try meta.addMethod(.{
            .name = "isStarted",
            .func = struct {
                fn call(
                    ctx: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    const s = getFiberState(ctx);
                    return Value.initBool(s != .created);
                }
            }.call,
            .is_static = false,
        });

        // isSuspended(): bool
        try meta.addMethod(.{
            .name = "isSuspended",
            .func = struct {
                fn call(
                    ctx: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    return Value.initBool(
                        getFiberState(ctx) == .suspended,
                    );
                }
            }.call,
            .is_static = false,
        });

        // isRunning(): bool
        try meta.addMethod(.{
            .name = "isRunning",
            .func = struct {
                fn call(
                    ctx: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    return Value.initBool(
                        getFiberState(ctx) == .running,
                    );
                }
            }.call,
            .is_static = false,
        });

        // isTerminated(): bool
        try meta.addMethod(.{
            .name = "isTerminated",
            .func = struct {
                fn call(
                    ctx: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    return Value.initBool(
                        getFiberState(ctx) == .terminated,
                    );
                }
            }.call,
            .is_static = false,
        });

        // getReturn(): mixed
        try meta.addMethod(.{
            .name = "getReturn",
            .func = struct {
                fn call(
                    ctx: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    if (!Value_isObject(ctx))
                        return Value.initNull();
                    const this = Value_asObject(ctx);
                    const fctx = getFiberCtx(this) orelse
                        return Value.initNull();
                    return fctx.return_value;
                }
            }.call,
            .is_static = false,
        });

        // Fiber::getCurrent(): ?Fiber (static)
        try meta.addMethod(.{
            .name = "getCurrent",
            .func = struct {
                fn call(
                    _: Value,
                    _: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    if (current_fiber_obj) |f| return f;
                    return Value.initNull();
                }
            }.call,
            .is_static = true,
        });

        // throw(Throwable $exception): mixed
        try meta.addMethod(.{
            .name = "throw",
            .func = struct {
                fn call(
                    ctx: Value,
                    args: []const Value,
                    _: Allocator,
                ) anyerror!Value {
                    const this = Value_asObject(ctx);
                    const fctx = getFiberCtx(this) orelse
                        return Value.initNull();
                    while (!fctx.mutex.tryLock()) std.atomic.spinLoopHint();
                    if (fctx.state != .suspended) {
                        fctx.mutex.unlock(getIo());
                        return Value.initNull();
                    }
                    if (args.len > 0) {
                        fctx.throw_exception = args[0];
                    }
                    // 通过 FiberContext 传递异常
                    fctx.resume_value = Value.initNull();
                    fctx.state = .running;
                    fctx.fiber_cond.signal(getIo());
                    while (fctx.state == .running) {
                        fctx.caller_cond.wait(getIo(), &fctx.mutex) catch {};
                    }
                    const result = fctx.suspend_value;
                    fctx.suspend_value = Value.initNull();
                    setFiberState(this, fctx.state);
                    fctx.mutex.unlock(getIo());
                    if (fctx.state == .terminated) {
                        if (fctx.thread) |t| t.join();
                        fctx.thread = null;
                    }
                    return result;
                }
            }.call,
            .is_static = false,
        });

        meta.magic_construct = meta.methods.get("__construct").?.func;
        try registerClass(meta);
    }

    fn getFiberCtx(obj: *PHPObject) ?*FiberContext {
        const addr_val = obj.getPropertyDirect("__fctx_addr") orelse
            return null;
        const addr: usize = @intCast(addr_val.toInt());
        if (addr == 0) return null;
        return @ptrFromInt(addr);
    }

    fn getFiberState(ctx: Value) FiberState {
        if (!Value_isObject(ctx)) return .created;
        const this = Value_asObject(ctx);
        const sv = this.getPropertyDirect("__state") orelse
            return .created;
        return @enumFromInt(@as(u8, @intCast(sv.toInt())));
    }

    fn setFiberState(obj: *PHPObject, state: FiberState) void {
        obj.setProperty(
            "__state",
            Value.initInt(@intFromEnum(state)),
        ) catch {};
    }

    /// 添加属性定义
    pub fn addProperty(self: *ClassMeta, prop: ClassProperty) !void {
        if (!self.properties.contains(prop.name)) {
            try self.property_order.append(self.allocator, prop.name);
        }
        try self.properties.put(prop.name, prop);
    }

    /// 设置静态属性
    pub fn setStaticProperty(self: *ClassMeta, name: []const u8, value: Value) !void {
        if (self.static_properties.get(name)) |old| {
            old.release(self.allocator);
        }
        _ = value.retain();
        try self.static_properties.put(name, value);
    }

    /// ★F-163：登记类常量的可见性（注册期由发射器在写值后调用）。
    /// 键不 dupe——与 static_properties 同源（发射器静态串，长寿命）。
    pub fn setConstVisibility(self: *ClassMeta, name: []const u8, vis: ConstVisibility) !void {
        try self.const_visibility.put(name, vis);
    }

    /// ★F-217（R-325）：类常量写值+可见性一步到位（入独立 class_constants 表，
    ///   与 static_properties 命名空间隔离）。同名旧值先释放。
    pub fn setClassConst(self: *ClassMeta, name: []const u8, value: Value, vis: ConstVisibility) !void {
        if (self.class_constants.get(name)) |old| {
            old.release(self.allocator);
        }
        _ = value.retain();
        try self.class_constants.put(name, value);
        try self.const_visibility.put(name, vis);
    }

    /// 获取静态属性
    pub fn getStaticProperty(self: *const ClassMeta, name: []const u8) ?Value {
        if (self.static_properties.get(name)) |val| {
            return val;
        }
        if (self.parent) |parent| {
            if (parent.getStaticProperty(name)) |val| return val;
        }
        // 查找实现的接口中的常量
        for (self.interfaces) |iface| {
            if (class_registry) |reg| {
                if (reg.get(iface)) |iface_meta| {
                    if (iface_meta.getStaticProperty(name)) |val| return val;
                }
            }
        }
        return null;
    }

    /// 检查是否实现了接口
    pub fn implementsInterface(self: *const ClassMeta, interface_name: []const u8) bool {
        for (self.interfaces) |iface| {
            // ★F-3（R-336）：接口名 CI（PHP 类/接口名均大小写不敏感；表内存的是规范拼写）
            if (std.ascii.eqlIgnoreCase(iface, interface_name)) return true;
            // 递归检查接口的父接口（interface C extends A, B）
            if (class_registry) |reg| {
                if (reg.get(iface)) |iface_meta| {
                    if (iface_meta.implementsInterface(interface_name)) return true;
                }
            }
        }
        if (self.parent) |parent| {
            return parent.implementsInterface(interface_name);
        }
        return false;
    }

    /// 检查是否是某个类的子类
    pub fn isSubclassOf(self: *const ClassMeta, class_name: []const u8) bool {
        if (std.mem.eql(u8, self.name, class_name)) return true;
        if (self.parent) |parent| {
            return parent.isSubclassOf(class_name);
        }
        return false;
    }
};

/// 查找属性的声明类及其可见性
fn findPropertyDeclaringClass(meta: *const ClassMeta, name: []const u8) ?struct {
    class: *const ClassMeta,
    prop: *const ClassProperty,
} {
    if (meta.properties.getPtr(name)) |prop| {
        return .{ .class = meta, .prop = prop };
    }
    if (meta.parent) |parent| {
        return findPropertyDeclaringClass(parent, name);
    }
    return null;
}

/// 检查当前作用域是否可以访问属性
fn checkPropertyAccess(declaring_class: *const ClassMeta, prop: *const ClassProperty) bool {
    if (prop.is_public) return true;

    const scope = getCurrentScopeClass() orelse return false;

    // trait 方法上下文：trait 方法被复制到使用类中，trait 方法内访问使用类的 protected/private 属性应允许
    // scope 是 trait 的 ClassMeta，declaring_class 是使用类的 ClassMeta
    if (scope.is_trait) {
        // protected 属性：trait 方法可以访问
        if (prop.is_protected) return true;
        // private 属性：仅当属性由 trait 本身声明时允许（declaring_class.name == scope.name 不可能，因为 trait 不是使用类）
        // 实际上 PHP 中 trait 的 private 属性在 trait 方法中可访问
        return true;
    }

    if (prop.is_protected) {
        return scope.isSubclassOf(declaring_class.name) or
            declaring_class.isSubclassOf(scope.name);
    }

    if (prop.is_private) {
        return std.mem.eql(u8, scope.name, declaring_class.name);
    }

    return true;
}

/// 全局类注册表
pub var class_registry: ?std.StringHashMap(*ClassMeta) = null;

/// 全局对象跟踪（用于内存泄露检测和清理）
pub var global_object_registry: ?std.ArrayList(*PHPObject) = null;

/// 弱引用死亡追踪：存储已被 unset 的对象指针地址
var weak_dead_objects: ?std.AutoHashMap(usize, void) = null;

/// 标记对象为"逻辑死亡"（unset 时调用）
pub fn php_weak_mark_dead(val: Value) void {
    if (!Value_isObject(val)) return;
    const obj = Value_asObject(val);
    const addr = @intFromPtr(obj);
    if (weak_dead_objects == null) {
        weak_dead_objects = std.AutoHashMap(usize, void).init(runtime_allocator);
    }
    if (weak_dead_objects) |*set| {
        set.put(addr, {}) catch {};
    }
}

/// 已触发 __destruct 的对象集合（防止重复触发）
var destructed_objects: ?std.AutoHashMap(usize, void) = null;

/// 对象是否已经执行过 __destruct
pub fn php_is_destructed(obj: *PHPObject) bool {
    if (destructed_objects) |*set| {
        return set.contains(@intFromPtr(obj));
    }
    return false;
}

/// 标记对象已执行 __destruct
fn markDestructed(obj: *PHPObject) void {
    if (destructed_objects == null) {
        destructed_objects = std.AutoHashMap(usize, void).init(runtime_allocator);
    }
    if (destructed_objects) |*set| {
        set.put(@intFromPtr(obj), {}) catch {};
    }
}

/// 立即对对象触发 __destruct（若尚未触发），用于 unset 时 PHP 语义。
/// 不释放内存，等待真正的 refcount 归零时 deinit 再释放。
pub fn php_force_destruct_if_object(val: Value) void {
    if (!Value_isObject(val)) return;
    const obj = Value_asObject(val);
    if (php_is_destructed(obj)) return;
    if (obj.class_meta) |meta| {
        if (class_registry == null) return;
        if (meta.findMethodLookup("__destruct")) |lookup| {
            markDestructed(obj);
            const this_val = Value_initObject(obj);
            const guard = ClassContext.init(meta, lookup.owner);
            defer guard.deinit();
            _ = lookup.method.func(this_val, &.{}, obj.allocator) catch {};
        } else {
            markDestructed(obj);
        }
    }
}

/// 检查对象是否仍然存活（未被 unset 标记为死亡）
fn php_weak_is_alive(addr: usize) bool {
    if (weak_dead_objects) |*set| {
        return !set.contains(addr);
    }
    return true;
}

/// ============================================================================
/// 弱引用表（WeakReference Table）
/// ============================================================================
/// 用于存储弱引用的目标对象。当创建 WeakReference 时，目标对象会被注册到这里。
/// 注意：这是一个简化实现，真正的弱引用应该在 GC 层面实现。
/// 弱引用表：地址 -> Value（目标对象的引用）
var weakref_table: ?std.AutoHashMap(usize, Value) = null;

/// 注册弱引用目标对象
/// 不增加引用计数，仅存储对象引用
fn weakref_register(addr: usize, target: Value, allocator: Allocator) !void {
    if (weakref_table == null) {
        weakref_table = std.AutoHashMap(usize, Value).init(allocator);
    }
    if (weakref_table) |*table| {
        // 存储目标对象的引用（不增加引用计数，实现弱引用语义）
        // 但我们需要能够在对象存活时获取它，所以保留一个原始指针引用
        // 注意：这是一个妥协的实现，真正的弱引用需要 GC 支持
        try table.put(addr, target);
    }
}

/// 获取弱引用目标对象
/// 如果对象已被销毁，返回 null
fn weakref_get(addr: usize) Value {
    // 首先检查对象是否仍然存活
    if (!php_weak_is_alive(addr)) {
        return Value.initNull();
    }

    // 从弱引用表获取目标对象
    if (weakref_table) |*table| {
        if (table.get(addr)) |target| {
            // 检查目标对象是否有效
            if (Value_isObject(target)) {
                _ = target.retain();
                return target;
            }
        }
    }

    return Value.initNull();
}

/// 清理弱引用表中已死亡对象的条目
fn weakref_cleanup() void {
    if (weakref_table) |*table| {
        var iter = table.iterator();
        var to_remove = try std.ArrayList(usize).initCapacity(runtime_allocator, 0);
        defer to_remove.deinit();

        while (iter.next()) |entry| {
            if (!php_weak_is_alive(entry.key_ptr.*)) {
                to_remove.append(entry.key_ptr.*) catch {};
            }
        }

        for (to_remove.items) |addr| {
            _ = table.remove(addr);
        }
    }
}

/// @ 错误抑制运算符支持
/// 使用嵌套计数器支持 @@expr 等场景
threadlocal var error_suppress_depth: u32 = 0;

/// ★F-217（R-311）：PHP 8 的 `@expr` 会把 error_reporting **临时**改成
/// `E_ERROR|E_PARSE|E_CORE_ERROR|E_COMPILE_ERROR|E_USER_ERROR|E_RECOVERABLE_ERROR`（实测 4437），
/// 表达式结束后恢复**进入前**的级别（连处理器内部对 error_reporting 的修改也会被覆盖，PHP 实测）。
/// 旧实现只记抑制深度、不动 error_reporting ⇒ 处理器里 `error_reporting()` 读到全量掩码（30719）。
const E_SUPPRESSED: i64 = E_ERROR | E_PARSE | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR | E_RECOVERABLE_ERROR;

threadlocal var error_suppress_saved: [128]i64 = undefined;
threadlocal var error_suppress_saved_n: u32 = 0;

pub fn php_error_suppress_push() void {
    if (error_suppress_saved_n < error_suppress_saved.len) {
        error_suppress_saved[error_suppress_saved_n] = global_error_types;
        error_suppress_saved_n += 1;
    }
    error_suppress_depth += 1;
    global_error_types = E_SUPPRESSED;
}

pub fn php_error_suppress_pop() void {
    if (error_suppress_saved_n > 0) {
        error_suppress_saved_n -= 1;
        global_error_types = error_suppress_saved[error_suppress_saved_n];
    }
    if (error_suppress_depth > 0) error_suppress_depth -= 1;
}

/// F-115：异常展开跳出 `@` 作用域时清零。
/// PHP 的抑制范围止于该表达式，**异常路径也不例外**；只发 push/pop 的话，
/// 右值抛异常时 pop 被跳过 ⇒ 抑制位残留并静默吞掉之后所有本该打印的诊断（门 SUPB 的 `L1`/探针 P1 实测）。
pub fn php_error_suppress_reset() void {
    // 异常展开：恢复到**最外层** `@` 进入前的级别（PHP 语义同上），并清空整栈
    if (error_suppress_saved_n > 0) {
        global_error_types = error_suppress_saved[0];
        error_suppress_saved_n = 0;
    }
    error_suppress_depth = 0;
}

pub fn isErrorSuppressed() bool {
    return error_suppress_depth > 0;
}

pub fn getCurrentCalledClass() ?*const ClassMeta {
    const ptr = concurrency.getExecutionContext().called_class orelse return null;
    return @ptrFromInt(ptr);
}

pub fn setCurrentCalledClass(meta: ?*const ClassMeta) void {
    concurrency.getExecutionContext().called_class = if (meta) |m| @intFromPtr(m) else null;
}

pub fn getCurrentScopeClass() ?*const ClassMeta {
    const ptr = concurrency.getExecutionContext().scope_class orelse return null;
    return @ptrFromInt(ptr);
}

pub fn setCurrentScopeClass(meta: ?*const ClassMeta) void {
    concurrency.getExecutionContext().scope_class = if (meta) |m| @intFromPtr(m) else null;
}

pub const ClassContext = struct {
    prev_called: ?*const ClassMeta,
    prev_scope: ?*const ClassMeta,

    pub fn init(called: ?*const ClassMeta, scope: ?*const ClassMeta) ClassContext {
        const prev = ClassContext{
            .prev_called = getCurrentCalledClass(),
            .prev_scope = getCurrentScopeClass(),
        };
        setCurrentCalledClass(called);
        setCurrentScopeClass(scope);
        return prev;
    }

    /// ★F-141：显式类名静态属性访问的上下文 —— 只切换 called class，**不覆盖词法作用域**。
    /// 外部访问时 scope 仍为 null（private/protected 被可见性检查拒绝）；
    /// 类内访问保留方法入口的真实 scope（same-class private / 子类 protected 仍可用）。
    pub fn initStaticAccess(called: ?*const ClassMeta) ClassContext {
        const prev = ClassContext{
            .prev_called = getCurrentCalledClass(),
            .prev_scope = getCurrentScopeClass(),
        };
        setCurrentCalledClass(called);
        return prev;
    }

    pub fn deinit(self: *const ClassContext) void {
        setCurrentCalledClass(self.prev_called);
        setCurrentScopeClass(self.prev_scope);
    }
};

fn resolveSpecialClassName(class_name: []const u8) ![]const u8 {
    if (std.mem.eql(u8, class_name, "static")) {
        const meta = getCurrentCalledClass() orelse return error.ClassNotFound;
        return meta.name;
    }
    if (std.mem.eql(u8, class_name, "self")) {
        const meta = getCurrentScopeClass() orelse return error.ClassNotFound;
        return meta.name;
    }
    if (std.mem.eql(u8, class_name, "parent")) {
        const meta = getCurrentScopeClass() orelse return error.ClassNotFound;
        const parent = meta.parent orelse return error.ClassNotFound;
        return parent.name;
    }
    return class_name;
}

/// 初始化类注册表
pub fn initClassRegistry(allocator: Allocator) void {
    class_registry = std.StringHashMap(*ClassMeta).init(allocator);
    global_object_registry = std.ArrayList(*PHPObject).initCapacity(allocator, 0) catch {
        global_object_registry = null;
        return;
    };
}

/// 注册类
pub fn registerClass(meta: *ClassMeta) !void {
    if (class_registry) |*registry| {
        try registry.put(meta.name, meta);
    }
}

/// AOT-CODEGEN-012：用户类/接口/trait 注册（带声明位置）——CI 查重（PHP 类名不区分
/// 大小写 ⇒ `class Foo` 与 `class foo` 为重复声明，双声明在 PHP 侧 Fatal redeclare）。
/// 运行时内建类（stdClass/ArrayIterator/Exception 基类等）仍走无检查的 registerClass；
/// 用户类 CI 撞内建名（如 `class stdclass`）同样 Fatal（PHP 语义一致）。
pub fn registerClassWithLocation(meta: *ClassMeta, file: []const u8, line: u32) !void {
    if (class_registry) |*registry| {
        if (findClass(meta.name)) |prev_meta| {
            // 占位判定：内部类（registerZigChannel 预注册的 Mutex/Channel/Atomic 族等）
            // 不写 decl_locations ⇒ 用户同名声明**覆盖占位**（用户优先，R-124 函数侧同款原则
            // —— f173 语料合法声明自己的 Mutex 即此形态）；有位置记录 = 用户 vs 用户 ⇒ Fatal。
            const prev_is_placeholder = if (class_decl_locations) |*locations| locations.get(prev_meta.name) == null else true;
            if (!prev_is_placeholder) {
            // 报名与 prev 位置都取**首声明**（PHP 语义：报告先声明者的名字与位置）
            const prev_name = prev_meta.name;
            const noun: []const u8 = if (prev_meta.is_interface) "interface" else if (prev_meta.is_trait) "trait" else if (prev_meta.is_enum) "enum" else "class";
            var prev_file = file;
            var prev_line = line;
            if (class_decl_locations) |*locations| {
                if (locations.get(prev_name)) |loc| {
                    prev_file = loc.file;
                    prev_line = loc.line;
                }
            }
            var ebuf: [512]u8 = undefined;
            const emsg = std.fmt.bufPrint(
                &ebuf,
                "PHP Fatal error:  Cannot redeclare {s} {s} (previously declared in {s}:{d}) in {s} on line {d}\nStack trace:\n#0 {{main}}\n",
                .{ noun, prev_name, prev_file, prev_line, file, line },
            ) catch "";
            fileWriteAll(2, emsg);
            var buf: [512]u8 = undefined;
            const msg = std.fmt.bufPrint(
                &buf,
                "\nFatal error: Cannot redeclare {s} {s} (previously declared in {s}:{d}) in {s} on line {d}\nStack trace:\n#0 {{main}}\n",
                .{ noun, prev_name, prev_file, prev_line, file, line },
            ) catch "";
            fileWriteAll(1, msg);
            php_run_shutdown_functions();
            std.process.exit(255);
            }
        }
        try registry.put(meta.name, meta);
        if (class_decl_locations) |*locations| {
            try locations.put(meta.name, .{ .file = file, .line = line });
        }
    }
}

/// AOT-CODEGEN-012：完全同名重复声明（发射器跳过第二份 meta 构建，仅发本调用）——
/// 首声明必已注册，命中即按 PHP 语义 Fatal（prev 名与位置取首声明）。
pub fn registerClassRedeclare(name: []const u8, file: []const u8, line: u32) !void {
    const prev_meta = findClass(name) orelse return; // 保险：未注册则忽略
    const prev_name = prev_meta.name;
    const noun: []const u8 = if (prev_meta.is_interface) "interface" else if (prev_meta.is_trait) "trait" else if (prev_meta.is_enum) "enum" else "class";
    var prev_file = file;
    var prev_line = line;
    if (class_decl_locations) |*locations| {
        if (locations.get(prev_name)) |loc| {
            prev_file = loc.file;
            prev_line = loc.line;
        }
    }
    if (fatalDisplayEnabled()) {
        var ebuf: [512]u8 = undefined;
        const emsg = std.fmt.bufPrint(
            &ebuf,
            "PHP Fatal error:  Cannot redeclare {s} {s} (previously declared in {s}:{d}) in {s} on line {d}\nStack trace:\n#0 {{main}}\n",
            .{ noun, prev_name, prev_file, prev_line, file, line },
        ) catch "";
        fileWriteAll(2, emsg);
        var buf: [512]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "\nFatal error: Cannot redeclare {s} {s} (previously declared in {s}:{d}) in {s} on line {d}\nStack trace:\n#0 {{main}}\n",
            .{ noun, prev_name, prev_file, prev_line, file, line },
        ) catch "";
        fileWriteAll(1, msg);
    }
    php_run_shutdown_functions();
    std.process.exit(255);
}

/// AOT-CODEGEN-012 R-137：记录类的 trait 使用（class_uses 枚举数据源；发射器逐
/// `use T` 调用一次；类名经 findClass 规范化，trait 名保留声明拼写）
pub fn registerClassTraitUse(class_name: []const u8, trait_name: []const u8) !void {
    const meta = findClass(class_name) orelse return;
    if (class_trait_uses) |*map_ptr| {
        const gop = try map_ptr.getOrPut(meta.name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        for (gop.value_ptr.items) |existing| {
            if (std.ascii.eqlIgnoreCase(existing, trait_name)) return;
        }
        const copied = try runtime_allocator.dupe(u8, trait_name);
        try gop.value_ptr.append(runtime_allocator, copied);
    }
}

/// 检查 final class 继承：如果 child 类继承自 final 类，输出 fatal error 并退出
pub fn php_check_final_inheritance(child_class_name: []const u8, parent_meta: *const ClassMeta, file: []const u8, line: u32) void {
    if (parent_meta.is_final) {
        var ebuf: [512]u8 = undefined;
        const stderr_msg = std.fmt.bufPrint(
            &ebuf,
            "PHP Fatal error:  Class {s} cannot extend final class {s} in {s} on line {d}\n",
            .{ child_class_name, parent_meta.name, file, line },
        ) catch {
            std.process.exit(255);
        };
        if (fatalDisplayEnabled()) {
            fileWriteAll(2, stderr_msg);
            var buf: [512]u8 = undefined;
            const stdout_msg = std.fmt.bufPrint(
                &buf,
                "\nFatal error: Class {s} cannot extend final class {s} in {s} on line {d}\n",
                .{ child_class_name, parent_meta.name, file, line },
            ) catch {
                fileWriteAll(1, "\nFatal error: Class cannot extend final class\n");
                std.process.exit(255);
            };
            fileWriteAll(1, stdout_msg);
        }
        php_run_shutdown_functions();
        std.process.exit(255);
    }
}

/// 检查非抽象类是否实现了所有抽象方法
/// 遍历继承链收集所有抽象方法，检查是否在子类中实现
pub fn php_check_abstract_methods(child_class_name: []const u8, file: []const u8, line: u32) void {
    const meta = findClass(child_class_name) orelse return;
    // 抽象类本身不需要检查
    if (meta.is_abstract) return;

    // 收集所有未实现的抽象方法
    var unimplemented: [64][]const u8 = undefined;
    var unimplemented_owners: [64][]const u8 = undefined;
    var count: usize = 0;

    // 遍历继承链
    var current: ?*const ClassMeta = meta;
    while (current) |c| {
        var iter = c.methods.iterator();
        while (iter.next()) |entry| {
            const method = entry.value_ptr.*;
            if (method.is_abstract) {
                // 使用 findMethod 遍历整个继承链检查是否已实现（非抽象版本）
                const found = if (meta.findMethod(entry.key_ptr.*)) |impl| !impl.is_abstract else false;
                if (!found and count < 64) {
                    // 避免重复
                    var dup = false;
                    for (unimplemented[0..count]) |u| {
                        if (std.mem.eql(u8, u, entry.key_ptr.*)) {
                            dup = true;
                            break;
                        }
                    }
                    if (!dup) {
                        unimplemented[count] = entry.key_ptr.*;
                        unimplemented_owners[count] = c.name;
                        count += 1;
                    }
                }
            }
        }
        current = c.parent;
    }

    if (count == 0) return;

    // 构建错误消息
    // PHP 格式: Class B contains 1 abstract method and must therefore be declared abstract or implement the remaining methods (A::foo)
    var msg_buf: [1024]u8 = undefined;
    var pos: usize = 0;
    const prefix = std.fmt.bufPrint(msg_buf[pos..], "Class {s} contains {d} abstract method{s} and must therefore be declared abstract or implement the remaining methods (", .{ child_class_name, count, if (count == 1) @as([]const u8, "") else @as([]const u8, "s") }) catch return;
    pos += prefix.len;
    for (unimplemented[0..count], 0..) |m, i| {
        if (i > 0 and pos < msg_buf.len) {
            msg_buf[pos] = ',';
            msg_buf[pos + 1] = ' ';
            pos += 2;
        }
        const part = std.fmt.bufPrint(msg_buf[pos..], "{s}::{s}", .{ unimplemented_owners[i], m }) catch break;
        pos += part.len;
    }
    if (pos < msg_buf.len) {
        msg_buf[pos] = ')';
        pos += 1;
    }
    const full_msg = msg_buf[0..pos];

    var ebuf: [1024]u8 = undefined;
    const stderr_msg = std.fmt.bufPrint(&ebuf, "PHP Fatal error:  {s} in {s} on line {d}\n", .{ full_msg, file, line }) catch {
        std.process.exit(255);
    };
    fileWriteAll(2, stderr_msg);
    var buf: [1024]u8 = undefined;
    const stdout_msg = std.fmt.bufPrint(&buf, "\nFatal error: {s} in {s} on line {d}\n", .{ full_msg, file, line }) catch {
        fileWriteAll(1, "\nFatal error: Abstract method not implemented\n");
        std.process.exit(255);
    };
    fileWriteAll(1, stdout_msg);
    php_run_shutdown_functions();
    std.process.exit(255);
}

/// 查找类
pub fn findClass(name: []const u8) ?*ClassMeta {
    // F-26：PHP 接受**完全限定名写法**的类名实参——实测 `class_exists("\Widget")` = true、
    //   `class_exists("Widget")` = true，而类表按 `Widget` 登记 ⇒ 带前导 `\` 的名字必须剥净再查。
    //   收口放在本函数而非各调用方：`findClass(` 在本文件就有 121 处，再加内省函数、instanceof 右侧、
    //   动态类名静态调用等入口，逐处补必漏（R-150 归一经验：同语义只留一个口径，见规则 32）。
    //   热路径成本 = 一次首字符比较；无 `\` 时与改前完全同路（语料实测此类实参 = 0 处 ⇒ 行为不变）。
    var lookup_name = name;
    while (lookup_name.len > 0 and lookup_name[0] == '\\') {
        lookup_name = lookup_name[1..];
    }
    if (class_registry) |registry| {
        if (registry.get(lookup_name)) |meta| return meta;
        // AOT-CODEGEN-012：类名不区分大小写（PHP 语义）—— 精确未命中回落 CI 线性扫描。
        // 命中路径（热路径）零额外开销，仅 miss 才扫描；104 调用者一次性全族受益
        //（new / instanceof 元数据 / class_exists / 静态调用 lookup_meta / 类常量 …）。
        var it = registry.iterator();
        while (it.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, lookup_name)) return entry.value_ptr.*;
        }
    }
    return null;
}

/// 清理所有注册的类和对象
pub fn cleanupAllClasses() void {
    // 清空对象注册表（对象由global_vars cleanup处理）
    if (global_object_registry) |*registry| {
        registry.deinit(runtime_allocator);
        global_object_registry = null;
    }

    // 清理所有类
    if (class_registry) |*registry| {
        var iter = registry.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.*.deinit();
        }
        registry.deinit();
        class_registry = null;
    }
}

/// ★批次二十七：对象序号全局计数器（PHP 从 1 起递增；atomic.fetchAdd 协程安全）。
var g_object_id_counter: std.atomic.Value(u64) = std.atomic.Value(u64).init(1);

/// ★批次二十七：对象序号空闲栈（对齐 Zend objects_store 的 free_list LIFO 复用真值——
///   对象销毁后其号被**下一个**新建对象复用，故 sort_na 格「catch 释放的异常让位、
///   随后 new P 仍得 #1」。容量溢出时丢弃（该号不再复用），语义安全降级。
var g_object_id_freelist: [4096]u64 = undefined;
var g_object_id_freelist_len: usize = 0;
/// 与 profiler.zig 同款的自旋锁（Zig 0.17：std.Thread.Mutex 已收）。
var g_object_id_mutex: std.atomic.Mutex = .unlocked;

/// 分配对象序号：空闲栈 LIFO 弹出优先，空则计数器递增（Zend 同构）。
fn q4ObjectIdAlloc() u64 {
    while (!g_object_id_mutex.tryLock()) std.atomic.spinLoopHint();
    defer g_object_id_mutex.unlock();
    if (g_object_id_freelist_len > 0) {
        g_object_id_freelist_len -= 1;
        return g_object_id_freelist[g_object_id_freelist_len];
    }
    return g_object_id_counter.fetchAdd(1, .monotonic);
}

/// 归还对象序号（仅在 deinit/gcDestroyObject 销毁路径调用；溢出即弃）。
fn q4ObjectIdFree(id: u64) void {
    while (!g_object_id_mutex.tryLock()) std.atomic.spinLoopHint();
    defer g_object_id_mutex.unlock();
    if (g_object_id_freelist_len < g_object_id_freelist.len) {
        g_object_id_freelist[g_object_id_freelist_len] = id;
        g_object_id_freelist_len += 1;
    }
}

/// PHP对象类型
/// 使用引用计数管理内存，属性存储在HashMap中
pub const PHPObject = struct {
    class_meta: ?*const ClassMeta,
    class_name: []const u8,
    properties: std.StringHashMap(Value),
    ref_count: usize,
    gc_info: GCInfo,
    allocator: Allocator,
    /// ★批次二十七：对象序号（PHP `object(X)#N` 真值——全局递增从 1 起、克隆得新号、
    ///   销毁后经 q4ObjectIdFree 归还供 LIFO 复用）。var_dump/spl_object_id 统一读本字段。
    id: u64,

    /// ★批次十（i1/i2）：内建类的内部状态面（对应 Zend 的 internal object handlers）。
    /// 内部状态**不挂 properties** ⇒ get_object_vars / foreach 属性快照 / 默认 serialize
    /// 路径均不可见，与 PHP 内建对象语义对齐（真值：`get_object_vars(new SplFixedArray(2)) == []`）。
    /// 释放挂点：deinit（正常引用归零）与 gcDestroyObject（GC 收集）两处统一调 internal_dtor。
    internal_data: ?*anyopaque = null,
    internal_dtor: ?*const fn (?*anyopaque, Allocator) void = null,

    /// 创建新对象
    pub fn init(allocator: Allocator, class_name: []const u8) !*PHPObject {
        const obj = try allocator.create(PHPObject);
        errdefer allocator.destroy(obj);

        obj.class_name = try allocator.dupe(u8, class_name);
        errdefer allocator.free(obj.class_name);

        obj.properties = std.StringHashMap(Value).init(allocator);
        obj.ref_count = 1;
        obj.gc_info = .{};
        obj.allocator = allocator;
        obj.class_meta = findClass(class_name);
        obj.internal_data = null;
        obj.internal_dtor = null;
        obj.id = q4ObjectIdAlloc();

        alloc_counters.php_object_objects += 1;
        alloc_counters.php_object_live_objects += 1;
        if (alloc_counters.php_object_live_objects > alloc_counters.php_object_peak_live_objects) {
            alloc_counters.php_object_peak_live_objects = alloc_counters.php_object_live_objects;
        }

        return obj;
    }

    /// 使用类元数据创建对象
    pub fn initWithMeta(allocator: Allocator, meta: *const ClassMeta) !*PHPObject {
        const obj = try allocator.create(PHPObject);
        errdefer allocator.destroy(obj);

        obj.class_name = try allocator.dupe(u8, meta.name);
        errdefer allocator.free(obj.class_name);

        obj.properties = std.StringHashMap(Value).init(allocator);
        obj.ref_count = 1;
        obj.gc_info = .{};
        obj.allocator = allocator;
        obj.class_meta = meta;
        obj.internal_data = null;
        obj.internal_dtor = null;
        obj.id = q4ObjectIdAlloc();

        alloc_counters.php_object_objects += 1;
        alloc_counters.php_object_live_objects += 1;
        if (alloc_counters.php_object_live_objects > alloc_counters.php_object_peak_live_objects) {
            alloc_counters.php_object_peak_live_objects = alloc_counters.php_object_live_objects;
        }

        // 初始化默认属性值（包括父类），按声明顺序遍历
        var current_meta: ?*const ClassMeta = meta;
        while (current_meta) |m| {
            for (m.property_order.items) |prop_name| {
                if (m.properties.get(prop_name)) |prop_def| {
                    if (!prop_def.is_static) {
                        // readonly 属性跳过默认值初始化：由构造函数显式赋值
                        // PHP 中 readonly 属性的"默认值"实际是构造函数参数默认值
                        if (prop_def.is_readonly) continue;
                        // PHP 8: typed property 无默认值时不初始化（uninitialized 状态）
                        if (!prop_def.has_default) continue;
                        // PHP 8: 子类已声明的属性，父类默认值不覆盖
                        if (m != meta and meta.properties.get(prop_name) != null) continue;
                        if (obj.properties.get(prop_name) == null) {
                            if (prop_def.default_value) |default| {
                                if (default.isInt() and default.asInt() == -1) {
                                    const new_array = try PHPArray.init(allocator);
                                    try obj.putProperty(prop_name, Value.initArray(new_array));
                                } else if (default.isArray()) {
                                    const cloned_array = try default.asArray().cloneDeep(allocator);
                                    try obj.putProperty(prop_name, Value.initArray(cloned_array));
                                } else {
                                    _ = default.retain();
                                    try obj.putProperty(prop_name, default);
                                }
                            }
                        }
                    }
                }
            }
            current_meta = m.parent;
        }
        return obj;
    }

    /// 增加引用计数
    pub fn retain(self: *PHPObject) void {
        self.ref_count += 1;
    }

    /// 减少引用计数，必要时释放
    pub fn release(self: *PHPObject) void {
        if (self.ref_count > 1000000) {
            // 引用计数异常高（参数 retain 泄漏），不递减以避免 use-after-free
            return;
        }
        if (self.ref_count == 0) {
            return;
        }
        self.ref_count -= 1;
        if (self.ref_count == 0) {
            if (self.gc_info.buffered) {
                if (!gc_in_progress) {
                    // ★批次二十八（G1/G3）：rc==0 ⇒ 同步销毁（PHP/Zend 语义）。
                    //   旧路径「已 buffered 则留置等 GC」令 __destruct 推迟到下次 GC 阈值
                    //   （小脚本程序结束才触发、甚至随 class_registry 先清而静默跳过），
                    //   销毁时机与槽位让位全面滞后 ⇒ 先摘缓冲再即时 deinit。
                    //   GC 进行中维持旧口径：在批内则由本轮 CollectWhite 收，批外待下轮。
                    gcUnbufferObject(self);
                    self.deinit();
                }
            } else {
                self.deinit();
            }
        } else if (!gc_in_progress) {
            gcBufferObject(self);
        }
    }

    /// 释放对象
    fn deinit(self: *PHPObject) void {
        if (alloc_counters.php_object_live_objects > 0) {
            alloc_counters.php_object_live_objects -= 1;
        }

        // 调用 __destruct 魔法函数
        // 注意：在程序清理阶段，class_meta可能已被释放，需要检查
        if (self.class_meta) |meta| {
            // 简单检查：如果class_registry已被清理，跳过__destruct
            if (class_registry != null) {
                // 若已被 php_force_destruct_if_object 显式触发过，跳过
                if (!php_is_destructed(self)) {
                    if (meta.findMethodLookup("__destruct")) |lookup| {
                        // 临时增加引用计数，防止析构函数内部的retain/release导致无限递归
                        // 析构函数执行期间，对象的refcount应该保持为1
                        self.ref_count = 1;
                        const this_val = Value_initObject(self);
                        const guard = ClassContext.init(meta, lookup.owner);
                        defer guard.deinit();
                        _ = lookup.method.func(this_val, &.{}, self.allocator) catch {};
                        // 析构函数执行完毕，恢复refcount为0以继续销毁流程
                        self.ref_count = 0;
                    }
                }
                // 清理 destructed 记录
                if (destructed_objects) |*set| {
                    _ = set.remove(@intFromPtr(self));
                }
            }
        }

        if (global_object_registry) |*registry| {
            var i: usize = 0;
            while (i < registry.items.len) : (i += 1) {
                if (registry.items[i] == self) {
                    registry.items[i] = registry.items[registry.items.len - 1];
                    _ = registry.pop();
                    break;
                }
            }
        }

        // 释放所有属性值和键字符串
        var iter = self.properties.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.release(self.allocator);
            self.allocator.free(entry.key_ptr.*);
        }
        self.properties.deinit();

        // ★批次十（i1/i2）：内建类内部状态面回收（SplFixedArray 元素数组、迭代器宿主引用等）
        if (self.internal_data) |p| {
            if (self.internal_dtor) |dtor| dtor(p, self.allocator);
            self.internal_data = null;
        }

        // 释放类名
        self.allocator.free(self.class_name);

        // ★批次二十七：归还对象序号（Zend objects_store LIFO 复用；__destruct 之后、内存销毁之前）
        q4ObjectIdFree(self.id);

        // 释放对象本身
        self.allocator.destroy(self);
    }

    /// 属性写入的唯一入口：保证 properties 的键始终归本对象所有。
    ///
    /// 契约：
    ///   - 值语义与 std.StringHashMap.put 完全一致（不 retain 新值、不释放被覆盖的旧值），
    ///     调用方保留自身那份引用，行为与改造前逐位相同；
    ///   - 键语义：命中已有键则复用原自有键指针（不重复 dupe，避免每次写属性泄漏一份键），
    ///     新键 dupe 一份，由 deinit / gcDestroyObject / unsetProperty 三处统一回收。
    ///
    /// 只有全部写入走本入口，deinit 中对 key 的 allocator.free 才对任意属性都成立；
    /// 历史上 SPL 内部属性用字符串字面量直接 put、clone 与源对象共享键指针，
    /// 会让那两处释放变成 free 静态只读指针与 double free。
    pub fn putProperty(self: *PHPObject, name: []const u8, value: Value) !void {
        if (self.properties.getPtr(name)) |existing| {
            existing.* = value;
            return;
        }
        const key_copy = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(key_copy);
        try self.properties.put(key_copy, value);
    }

    /// 获取属性（支持 __get 魔法函数）
    // 防止magic method递归调用的标志
    threadlocal var in_magic_method: bool = false;

    pub fn getProperty(self: *PHPObject, name: []const u8) ?Value {
        if (self.properties.get(name)) |val| {
            _ = val.retain();
            return val;
        }
        // 防止递归调用__get
        if (in_magic_method) return null;

        // 调用 __get 魔法函数
        // PHP 语义：__get 仅对未声明的属性触发
        if (self.class_meta) |meta| {
            if (findPropertyDeclaringClass(meta, name) == null) {
                if (meta.findMethodLookup("__get")) |lookup| {
                    in_magic_method = true;
                    defer in_magic_method = false;

                    const this_val = Value_initObject(self);
                    const name_str = PHPString.init(self.allocator, name) catch return null;
                    const name_val = Value.initString(name_str);
                    defer name_val.release(self.allocator);
                    const args = [_]Value{name_val};
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    const result = lookup.method.func(this_val, &args, self.allocator) catch return null;
                    return result;
                }
            }
        }
        return null;
    }

    /// 直接获取属性（不触发__get）
    pub fn getPropertyDirect(self: *PHPObject, name: []const u8) ?Value {
        if (self.properties.get(name)) |val| {
            _ = val.retain();
            return val;
        }
        return null;
    }

    /// 设置属性（支持 __set 魔法函数）
    pub fn setProperty(self: *PHPObject, name: []const u8, value: Value) !void {
        // 防止递归调用__set
        if (!in_magic_method) {
            // 检查是否有 __set 魔法函数且属性不存在
            if (self.properties.get(name) == null) {
                if (self.class_meta) |meta| {
                    // 属性已在类中声明（即使未初始化）时，直接设置，不触发 __set
                    // PHP 语义：__set 仅对未声明的属性触发
                    if (findPropertyDeclaringClass(meta, name) == null) {
                        if (meta.findMethodLookup("__set")) |lookup| {
                            in_magic_method = true;
                            defer in_magic_method = false;

                            const this_val = Value_initObject(self);
                            const name_str = try PHPString.init(self.allocator, name);
                            const name_val = Value.initString(name_str);
                            defer name_val.release(self.allocator);
                            const args = [_]Value{ name_val, value };
                            const guard = ClassContext.init(meta, lookup.owner);
                            defer guard.deinit();
                            _ = try lookup.method.func(this_val, &args, self.allocator);
                            return;
                        }
                    }
                }
            }
        }

        // 释放旧值
        if (self.properties.get(name)) |old_value| {
            old_value.release(self.allocator);
        }

        // 保留新值
        _ = value.retain();

        // 存储属性（键所有权由 putProperty 统一负责）
        try self.putProperty(name, value);
    }

    /// 调用方法（支持 __call 魔法函数和继承）
    pub fn callMethod(self: *PHPObject, method_name: []const u8, args: []const Value) !Value {
        const this_val = Value_initObject(self);

        if (self.class_meta) |meta| {
            // 查找方法（包括继承链）
            if (meta.findMethodLookup(method_name)) |lookup| {
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                return lookup.method.func(this_val, args, self.allocator);
            }
            // 调用 __call 魔法函数
            if (meta.findMethodLookup("__call")) |lookup| {
                const name_val = Value.initString(try PHPString.init(self.allocator, method_name));
                const args_arr = try PHPArray.init(self.allocator);
                for (args) |arg| {
                    try args_arr.push(self.allocator, arg);
                }
                const call_args = [_]Value{ name_val, Value.initArray(args_arr) };
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                return lookup.method.func(this_val, &call_args, self.allocator);
            }
        }
        return error.MethodNotFound;
    }

    /// ★批次十八①：命名/展开实参的方法调用（arr 整数键＝位置、字符串键＝命名，PHP 8.1+ 语义）。
    ///   命中方法 ⇒ 共享核心按 ClassMethod 形参名绑定（overwrites/Unknown 同函数口径）；
    ///   未命中且具 __call ⇒ 收**原始关联数组**（保字符串键，M4 真值）。
    pub fn callMethodNamed(self: *PHPObject, method_name: []const u8, arr: *PHPArray) !Value {
        const this_val = Value_initObject(self);
        const allocator = self.allocator;

        if (self.class_meta) |meta| {
            if (meta.findMethodLookup(method_name)) |lookup| {
                const display = try std.fmt.allocPrint(allocator, "{s}::{s}", .{ lookup.owner.name, method_name });
                defer allocator.free(display);
                const bind = try phpBindNamedValueArray(arr, lookup.method.param_names, methodVariadicIndex(lookup.method), lookup.method.required_params, display, allocator);
                defer bind.deinit(allocator);
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                return lookup.method.func(this_val, bind.final_args, allocator);
            }
            // __call：收原始关联数组（保字符串键）
            if (meta.findMethodLookup("__call")) |lookup| {
                const name_val = Value.initString(try PHPString.init(allocator, method_name));
                defer name_val.release(allocator);
                const arr_val = Value.initArray(arr);
                _ = arr_val.retain();
                defer arr_val.release(allocator);
                const call_args = [_]Value{ name_val, arr_val };
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                return lookup.method.func(this_val, &call_args, allocator);
            }
        }
        return error.MethodNotFound;
    }

    /// 检查属性是否存在（支持 __isset 魔法函数）
    pub fn hasProperty(self: *PHPObject, name: []const u8) bool {
        if (self.properties.contains(name)) return true;
        if (self.class_meta) |meta| {
            // PHP 语义：__isset 仅对未声明的属性触发
            if (findPropertyDeclaringClass(meta, name) == null) {
                if (meta.findMethodLookup("__isset")) |lookup| {
                    const this_val = Value_initObject(self);
                    const name_val = Value.initString(PHPString.initStatic(name));
                    const args = [_]Value{name_val};
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    const result = lookup.method.func(this_val, &args, self.allocator) catch return false;
                    return result.toBool();
                }
            }
        }
        return false;
    }

    pub fn unsetProperty(self: *PHPObject, name: []const u8) !bool {
        if (self.properties.get(name)) |old_value| {
            // remove 只丢弃条目，自有键缓冲区必须显式回收
            const stored_key = self.properties.getKey(name).?;
            if (self.properties.remove(name)) {
                old_value.release(self.allocator);
                self.allocator.free(stored_key);
                return true;
            }
        }

        if (!in_magic_method) {
            if (self.class_meta) |meta| {
                // PHP 语义：__unset 仅对未声明的属性触发
                if (findPropertyDeclaringClass(meta, name) == null) {
                    if (meta.findMethodLookup("__unset")) |lookup| {
                        in_magic_method = true;
                        defer in_magic_method = false;

                        const this_val = Value_initObject(self);
                        const name_str = try PHPString.init(self.allocator, name);
                        const name_val = Value.initString(name_str);
                        defer name_val.release(self.allocator);
                        const args = [_]Value{name_val};
                        const guard = ClassContext.init(meta, lookup.owner);
                        defer guard.deinit();
                        _ = try lookup.method.func(this_val, &args, self.allocator);
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /// 转换为字符串（支持 __toString 魔法函数）
    pub fn toString(self: *PHPObject, allocator: Allocator) !*PHPString {
        if (self.class_meta) |meta| {
            if (meta.magic_toString) |to_str| {
                const this_val = Value_initObject(self);
                // 设置 calledClass 为对象实际类，确保继承的 __toString 中 static::class 正确解析（LSB）
                const __prev_called = getCurrentCalledClass();
                setCurrentCalledClass(meta);
                defer setCurrentCalledClass(__prev_called);
                const result = try to_str(this_val, &.{}, allocator);
                if (result.isString()) {
                    return result.asString();
                }
                // ★批次十（t13 族）：__toString 内部抛可捕获异常时（throwThrowable 契约 =
                //   setException + 返回异常对象**值**，非 Zig error），pending 异常不得被
                //   下面的通用 "could not be converted" Error 覆盖。归还本函数这份引用，
                //   全局那份留给 hasException 轮询分派。
                if (hasException()) {
                    result.release(allocator);
                    return PHPString.init(allocator, "");
                }
                result.release(allocator);
            }
        }
        // ★F-32（R-331）：无 __toString ⇒ 可捕获 Error「Object of class X could not be
        //   converted to string」（PHP 8.5.8 实测），不再 fail-open 返类名。
        //   与 Value.toString 的 Closure 支同构：setException 后返回空串占位，调用点
        //   hasException 轮询接管分派；echo 路径（php_echo 的对象支）有 has_to_string
        //   前置守卫、永不抵达这里 ⇒ 不受影响。
        {
            var ebuf: [256]u8 = undefined;
            const emsg = std.fmt.bufPrint(&ebuf, "Object of class {s} could not be converted to string", .{self.class_name}) catch "Object of class could not be converted to string";
            throwThrowableDiscardCatch("Error", emsg, allocator);
        }
        return PHPString.init(allocator, "");
    }
};

// ============================================================================
// Value类型扩展 - 对象支持
// ============================================================================

// 扩展Value的方法（这些方法应该添加到Value结构中）
// 由于我们不能直接修改Value结构，我们在这里提供独立的函数

/// 创建对象值
pub fn Value_initObject(obj: *PHPObject) Value {
    const addr = @intFromPtr(obj);
    return .{ .val = nanbox_abi.encodePtr(addr, Value.TYPE_OBJECT) };
}

/// 检查是否是对象
pub fn Value_isObject(self: Value) bool {
    if ((self.val & (Value.SIGN_BIT | Value.QNAN)) != Value.QNAN) return false;
    return (self.val & Value.TYPE_MASK) == Value.TYPE_OBJECT;
}

/// 获取对象指针
pub fn Value_asObject(self: Value) *PHPObject {
    return @ptrFromInt(nanbox_abi.decodePtr(self.val));
}

// 更新Value的release方法以支持对象
// 注意：这需要在Value结构的release方法中添加对象处理

// ============================================================================
// 对象操作函数
// ============================================================================

/// 创建新对象
///
/// @param allocator 内存分配器
/// @return 对象Value
pub fn php_object_new(class_name: []const u8, allocator: Allocator) !Value {
    const resolved = try resolveSpecialClassName(class_name);
    const obj = if (findClass(resolved)) |meta|
        try PHPObject.initWithMeta(allocator, meta)
    else
        try PHPObject.init(allocator, resolved);

    // 注册对象以便程序退出时清理
    if (global_object_registry) |*registry| {
        registry.append(allocator, obj) catch {};
    }

    return Value_initObject(obj);
}

/// 获取对象属性
///
/// @param obj_val 对象Value
/// @param property_name 属性名
/// @return 属性值，如果不存在返回null
/// 尝试调用 __get 魔术方法，返回 ?Value
/// 调用方负责检查返回值是否为 null
fn tryMagicGet(obj_val: Value, meta: *const ClassMeta, property_name: []const u8) !?Value {
    if (meta.findMethodLookup("__get")) |lookup| {
        const name_str = try PHPString.init(runtime_allocator, property_name);
        const name_val = Value.initString(name_str);
        defer name_val.release(runtime_allocator);
        const args = [_]Value{name_val};
        const guard = ClassContext.init(meta, lookup.owner);
        defer guard.deinit();
        return try lookup.method.func(obj_val, &args, runtime_allocator);
    }
    return null;
}

/// 尝试调用 __set 魔术方法，返回 true 表示已处理
fn tryMagicSet(obj_val: Value, meta: *const ClassMeta, property_name: []const u8, value: Value) !bool {
    if (meta.findMethodLookup("__set")) |lookup| {
        const name_str = try PHPString.init(runtime_allocator, property_name);
        const name_val = Value.initString(name_str);
        defer name_val.release(runtime_allocator);
        const args = [_]Value{ name_val, value };
        const guard = ClassContext.init(meta, lookup.owner);
        defer guard.deinit();
        _ = try lookup.method.func(obj_val, &args, runtime_allocator);
        return true;
    }
    return false;
}

/// 将 union 类型名按 PHP 语义排序（字母序）生成规范化消息
/// PHP 8.0: TypeError 消息中 union 类型按字母序排列
fn sortUnionTypeName(buf: []u8, type_name: []const u8) []const u8 {
    var parts: [16][]const u8 = undefined;
    var count: usize = 0;
    var it = std.mem.splitScalar(u8, type_name, '|');
    while (it.next()) |part| {
        if (count < 16) {
            parts[count] = part;
            count += 1;
        }
    }
    // 插入排序（字母序）
    var i: usize = 1;
    while (i < count) : (i += 1) {
        var j = i;
        while (j > 0 and std.mem.lessThan(u8, parts[j], parts[j - 1])) {
            const tmp = parts[j];
            parts[j] = parts[j - 1];
            parts[j - 1] = tmp;
            j -= 1;
        }
    }
    var pos: usize = 0;
    for (parts[0..count], 0..) |part, idx| {
        if (idx > 0) {
            if (pos < buf.len) {
                buf[pos] = '|';
                pos += 1;
            }
        }
        const len = @min(part.len, buf.len - pos);
        @memcpy(buf[pos .. pos + len], part[0..len]);
        pos += len;
    }
    return buf[0..pos];
}

/// Union 类型 coercion 优先级（PHP 8.0 语义）
/// int > float > string > bool > array > object > class
fn coercePriority(type_name: []const u8) u8 {
    if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer")) return 1;
    if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double")) return 2;
    if (std.mem.eql(u8, type_name, "string")) return 3;
    if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean")) return 4;
    if (std.mem.eql(u8, type_name, "false") or std.mem.eql(u8, type_name, "true")) return 4;
    if (std.mem.eql(u8, type_name, "array")) return 5;
    if (std.mem.eql(u8, type_name, "object")) return 6;
    if (std.mem.eql(u8, type_name, "callable") or std.mem.eql(u8, type_name, "iterable")) return 7;
    if (std.mem.eql(u8, type_name, "mixed")) return 8;
    // 类名等其他类型：最低优先级
    return 9;
}

/// 检查值是否精确匹配某个类型（不进行 coercion）
fn typeExactMatch(type_name: []const u8, value: Value) bool {
    if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer")) return value.isInt();
    if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double")) return value.isFloat();
    if (std.mem.eql(u8, type_name, "string")) return value.isString();
    if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean")) return value.isBool();
    if (std.mem.eql(u8, type_name, "array")) return value.isArray();
    if (std.mem.eql(u8, type_name, "object")) return Value_isObject(value);
    if (std.mem.eql(u8, type_name, "null")) return value.isNull();
    if (std.mem.eql(u8, type_name, "false")) return value.isBool() and !value.asBool();
    if (std.mem.eql(u8, type_name, "true")) return value.isBool() and value.asBool();
    if (std.mem.eql(u8, type_name, "mixed")) return true;
    if (std.mem.eql(u8, type_name, "callable") or std.mem.eql(u8, type_name, "iterable")) return true;
    // 类名/接口名类型：检查 instanceof（包括继承链和接口实现）
    if (findClass(type_name)) |_| {
        if (Value_isObject(value)) {
            const obj = Value_asObject(value);
            if (obj.class_meta) |meta| {
                var current: ?*const ClassMeta = meta;
                while (current) |m| {
                    if (std.mem.eql(u8, m.name, type_name)) return true;
                    current = m.parent;
                }
                if (meta.implementsInterface(type_name)) return true;
            }
        }
        return false;
    }
    return false;
}

/// 尝试将值强制转换为单个类型（不抛出异常）
/// 返回 null 表示类型不兼容，返回非 null 表示转换成功
/// F-27 共享口径：PHP 里**闭包就是 `Closure` 类的实例**（同时满足 `object`/`mixed`），而 AOT 的闭包
/// 用独立 `.function` tag 表示 ⇒ `Value_isObject` 为 false。类型检查有**三条互不复用**的链，
/// 每条都要单独过这枚谓词，否则合法值被判 TypeError（R-154 实测：只修属性位时形参位仍红）：
///   ① 属性位    tryCoerceSingleType / coercePropertyType
///   ② 形参位    checkSingleType（`object` 伪类型 + 下方的 instanceof 式类名分支）
///   ③ instanceof 运算符与 catch 派发（php_instanceof）
/// 返回值位不校验（门 V v26 ⇒ 工单 F-35），故不在本谓词覆盖面内。
/// 实测：修前 `public object $o` / `public Closure $c` / `public Closure|string $u` 三格全红
/// （`Cannot assign unknown to property …`），`?Closure` 因走 null 早退而侥幸绿。
/// 第二件事：声明类型可写成完全限定名（`\Closure`），而类表与 `class_meta.name` 都不带前导 `\`
/// ⇒ 同一个 helper 里顺手剥净（F-26 的 `findClass` 剥斜杠只解决查表，不解决名字比较）。
fn stripLeadingNamespaceSep(name: []const u8) []const u8 {
    var n = name;
    while (n.len > 0 and n[0] == '\\') n = n[1..];
    return n;
}

fn closureSatisfiesType(declared: []const u8, value: Value) bool {
    if (!value.isFunction()) return false;
    const d = stripLeadingNamespaceSep(declared);
    return std.ascii.eqlIgnoreCase(d, "Closure") or std.mem.eql(u8, d, "object") or std.mem.eql(u8, d, "mixed");
}

fn tryCoerceSingleType(type_name: []const u8, value: Value) ?Value {
    if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer")) {
        if (value.isInt()) return value;
        if (value.isFloat()) return Value.initInt(@intFromFloat(value.toFloat()));
        if (value.isBool()) return Value.initInt(if (value.asBool()) 1 else 0);
        if (value.isString()) {
            if (!isNumericString(value.asString().data)) return null;
            return Value.initInt(value.toInt());
        }
        return null;
    }
    if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double")) {
        if (value.isFloat()) return value;
        if (value.isInt()) return Value.initFloat(@floatFromInt(value.toInt()));
        if (value.isBool()) return Value.initFloat(if (value.asBool()) 1.0 else 0.0);
        if (value.isString()) {
            if (!isNumericString(value.asString().data)) return null;
            return Value.initFloat(value.toFloat());
        }
        return null;
    }
    if (std.mem.eql(u8, type_name, "string")) {
        if (value.isString()) return value;
        if (value.isInt() or value.isFloat() or value.isBool()) {
            const str = value.toString(runtime_allocator) catch return null;
            return Value.initString(str);
        }
        return null;
    }
    if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean")) {
        if (value.isBool()) return value;
        if (value.isInt() or value.isFloat() or value.isString()) return Value.initBool(value.toBool());
        return null;
    }
    if (std.mem.eql(u8, type_name, "array")) {
        if (value.isArray()) return value;
        return null;
    }
    if (std.mem.eql(u8, type_name, "mixed")) return value;
    if (std.mem.eql(u8, type_name, "object")) {
        if (Value_isObject(value) or value.isFunction()) return value; // F-27：闭包也是对象
        return null;
    }
    if (std.mem.eql(u8, type_name, "callable") or std.mem.eql(u8, type_name, "iterable")) return value;
    // DNF 中的 intersection 子类型（如 Iterator&Countable）：值必须是对象且 instanceof 所有声明类型
    if (std.mem.indexOfScalar(u8, type_name, '&') != null) {
        if (!Value_isObject(value)) return null;
        const obj = Value_asObject(value);
        if (obj.class_meta) |meta| {
            var it = std.mem.splitScalar(u8, type_name, '&');
            while (it.next()) |sub_type| {
                const trimmed = std.mem.trim(u8, sub_type, " \t()");
                var current: ?*const ClassMeta = meta;
                var found = false;
                while (current) |m| {
                    if (std.mem.eql(u8, m.name, trimmed)) {
                        found = true;
                        break;
                    }
                    current = m.parent;
                }
                if (!found) {
                    if (meta.implementsInterface(trimmed)) found = true;
                }
                if (!found) return null;
            }
            return value;
        }
        return null;
    }
    // 类名/接口名类型：只接受精确 instanceof 匹配，不做 coercion
    if (findClass(stripLeadingNamespaceSep(type_name))) |_| { // F-26/F-27：完全限定写法先剥净
        if (closureSatisfiesType(type_name, value)) return value; // F-27：闭包 instanceof Closure
        if (Value_isObject(value)) {
            const obj = Value_asObject(value);
            if (obj.class_meta) |meta| {
                var current: ?*const ClassMeta = meta;
                while (current) |m| {
                    if (std.mem.eql(u8, m.name, type_name)) return value;
                    current = m.parent;
                }
                if (meta.implementsInterface(type_name)) return value;
            }
        }
        return null;
    }
    // 未知类型：不转换
    return value;
}

/// 属性类型 coercion：根据声明的类型将值强制转换
/// 不兼容类型抛出 TypeError
/// class_name 用于错误消息
fn coercePropertyType(prop: *const ClassProperty, value: Value, class_name: []const u8) !Value {
    if (prop.type_name == null) return value;

    const type_name = prop.type_name.?;

    // mixed 类型：接受任何值（包括 null），无 coercion
    if (std.mem.eql(u8, type_name, "mixed")) return value;

    // never 类型：PHP 不允许作为属性类型，任何赋值即 TypeError
    if (std.mem.eql(u8, type_name, "never")) {
        var buf: [256]u8 = undefined;
        const val_type = if (value.isNull()) "null" else if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type never", .{ val_type, class_name, prop.name }) catch "Cannot assign to never property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    // nullable 类型且值为 null：直接返回
    if (prop.type_nullable and value.isNull()) return value;

    // null 赋给非 nullable 属性：TypeError
    if (value.isNull()) {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Cannot assign null to property {s}::${s} of type {s}", .{ class_name, prop.name, type_name }) catch "Cannot assign null to property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    // Intersection 类型（Iterator&Countable 等，不含 |）：值必须是对象且 instanceof 所有声明类型
    // DNF 类型（含 |）走 union 分支，union 中的每个子类型通过 tryCoerceSingleType 处理 intersection
    if (std.mem.indexOfScalar(u8, type_name, '&') != null and std.mem.indexOfScalar(u8, type_name, '|') == null) {
        if (!Value_isObject(value)) {
            var buf: [256]u8 = undefined;
            const val_type = if (value.isArray()) "array" else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
            const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ val_type, class_name, prop.name, type_name }) catch "Cannot assign: type mismatch";
            return throwThrowable("TypeError", msg, runtime_allocator);
        }
        const obj = Value_asObject(value);
        if (obj.class_meta) |meta| {
            var it = std.mem.splitScalar(u8, type_name, '&');
            while (it.next()) |sub_type| {
                const trimmed = std.mem.trim(u8, sub_type, " \t");
                // 检查继承链：类名匹配
                var current: ?*const ClassMeta = meta;
                var found = false;
                while (current) |m| {
                    if (std.mem.eql(u8, m.name, trimmed)) {
                        found = true;
                        break;
                    }
                    current = m.parent;
                }
                // 检查接口实现
                if (!found) {
                    if (meta.implementsInterface(trimmed)) {
                        found = true;
                    }
                }
                if (!found) {
                    var buf: [256]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ obj.class_name, class_name, prop.name, type_name }) catch "Cannot assign: type mismatch";
                    return throwThrowable("TypeError", msg, runtime_allocator);
                }
            }
            return value;
        }
        // 对象无 class_meta：TypeError
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ obj.class_name, class_name, prop.name, type_name }) catch "Cannot assign: type mismatch";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    // Union 类型（int|string, int|float|null 等）：两阶段匹配
    // Pass 1: 精确匹配（PHP 优先保留原始类型，不做不必要的 coercion）
    // Pass 2: 按 PHP coercion 优先级尝试（int > float > string > bool > array > object > class）
    if (std.mem.indexOfScalar(u8, type_name, '|') != null) {
        var it = std.mem.splitScalar(u8, type_name, '|');
        while (it.next()) |sub_type| {
            if (std.mem.eql(u8, sub_type, "null")) continue;
            if (typeExactMatch(sub_type, value)) return value;
        }
        // 收集子类型并按优先级排序
        var sub_types: [16][]const u8 = undefined;
        var sub_count: usize = 0;
        it = std.mem.splitScalar(u8, type_name, '|');
        while (it.next()) |sub_type| {
            if (std.mem.eql(u8, sub_type, "null")) continue;
            if (sub_count < 16) {
                sub_types[sub_count] = sub_type;
                sub_count += 1;
            }
        }
        var i: usize = 1;
        while (i < sub_count) : (i += 1) {
            var j = i;
            while (j > 0 and coercePriority(sub_types[j]) < coercePriority(sub_types[j - 1])) {
                const tmp = sub_types[j];
                sub_types[j] = sub_types[j - 1];
                sub_types[j - 1] = tmp;
                j -= 1;
            }
        }
        for (sub_types[0..sub_count]) |sub_type| {
            if (tryCoerceSingleType(sub_type, value)) |coerced| {
                return coerced;
            }
        }
        // 所有子类型都不匹配 → TypeError
        var buf: [256]u8 = undefined;
        var sort_buf: [256]u8 = undefined;
        const sorted_type = sortUnionTypeName(&sort_buf, type_name);
        const val_type = if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ val_type, class_name, prop.name, sorted_type }) catch "Cannot assign: type mismatch";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer")) {
        if (value.isInt()) return value;
        if (value.isFloat()) return Value.initInt(@intFromFloat(value.toFloat()));
        if (value.isBool()) return Value.initInt(if (value.asBool()) 1 else 0);
        if (value.isString()) {
            const str_data = value.asString().data;
            if (!isNumericString(str_data)) {
                var buf: [256]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Cannot assign string to property {s}::${s} of type int", .{ class_name, prop.name }) catch "Cannot assign to int property";
                return throwThrowable("TypeError", msg, runtime_allocator);
            }
            return Value.initInt(value.toInt());
        }
        // array/object → TypeError
        var buf: [256]u8 = undefined;
        const val_type = if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type int", .{ val_type, class_name, prop.name }) catch "Cannot assign to int property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double")) {
        if (value.isFloat()) return value;
        if (value.isInt()) return Value.initFloat(@floatFromInt(value.toInt()));
        if (value.isBool()) return Value.initFloat(if (value.asBool()) 1.0 else 0.0);
        if (value.isString()) {
            const str_data = value.asString().data;
            if (!isNumericString(str_data)) {
                var buf: [256]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Cannot assign string to property {s}::${s} of type float", .{ class_name, prop.name }) catch "Cannot assign to float property";
                return throwThrowable("TypeError", msg, runtime_allocator);
            }
            return Value.initFloat(value.toFloat());
        }
        var buf: [256]u8 = undefined;
        const val_type = if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type float", .{ val_type, class_name, prop.name }) catch "Cannot assign to float property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (std.mem.eql(u8, type_name, "string")) {
        if (value.isString()) return value;
        if (value.isInt() or value.isFloat() or value.isBool()) {
            const str = try value.toString(runtime_allocator);
            return Value.initString(str);
        }
        // array/object → TypeError
        var buf: [256]u8 = undefined;
        const val_type = if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type string", .{ val_type, class_name, prop.name }) catch "Cannot assign to string property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean")) {
        if (value.isBool()) return value;
        if (value.isInt() or value.isFloat() or value.isString()) return Value.initBool(value.toBool());
        // array/object → TypeError
        var buf: [256]u8 = undefined;
        const val_type = if (value.isArray()) "array" else if (Value_isObject(value)) Value_asObject(value).class_name else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type bool", .{ val_type, class_name, prop.name }) catch "Cannot assign to bool property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (std.mem.eql(u8, type_name, "array")) {
        if (value.isArray()) return value;
        // 非数组赋给 array 属性：TypeError
        var buf: [256]u8 = undefined;
        const val_type = if (Value_isObject(value)) Value_asObject(value).class_name else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type array", .{ val_type, class_name, prop.name }) catch "Cannot assign to array property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (std.mem.eql(u8, type_name, "mixed")) return value;
    if (std.mem.eql(u8, type_name, "object")) {
        // F-27：AOT 的闭包是独立 .function tag（`Value_isObject` 为 false），而 PHP 里闭包就是对象
        //   （实测 `class P1 { public object $o; } $p1->o = fn() => 1;` ⇒ 接受且 get_class = Closure）
        if (Value_isObject(value) or value.isFunction()) return value;
        var buf: [256]u8 = undefined;
        const val_type = if (value.isArray()) "array" else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type object", .{ val_type, class_name, prop.name }) catch "Cannot assign to object property";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    // 类名/接口名类型：检查 instanceof（包括继承链和接口实现）
    // F-26/F-27：声明类型可能是完全限定名，且闭包必须先按 `Closure` 实例放行
    //   （口径统一在 stripLeadingNamespaceSep / closureSatisfiesType，见其注释）。
    const declared_type = stripLeadingNamespaceSep(type_name);
    if (findClass(declared_type)) |_| {
        if (closureSatisfiesType(type_name, value)) return value;
        if (Value_isObject(value)) {
            const obj = Value_asObject(value);
            if (obj.class_meta) |meta| {
                // 检查继承链
                var current: ?*const ClassMeta = meta;
                while (current) |m| {
                    if (std.mem.eql(u8, m.name, declared_type)) return value;
                    current = m.parent;
                }
                // 检查接口实现
                if (meta.implementsInterface(declared_type)) return value;
            }
            // 类型不匹配：TypeError
            var buf: [256]u8 = undefined;
            const actual_class = if (obj.class_meta) |m| m.name else obj.class_name;
            const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ actual_class, class_name, prop.name, type_name }) catch "Cannot assign: type mismatch";
            return throwThrowable("TypeError", msg, runtime_allocator);
        }
        // 非对象赋给类名属性：TypeError（实测 PHP 报 "Closure"，故 .function 必须有名，不得落 "unknown"）
        var buf: [256]u8 = undefined;
        const val_type = if (value.isFunction()) "Closure" else if (value.isArray()) "array" else if (value.isString()) "string" else if (value.isInt()) "int" else if (value.isFloat()) "float" else if (value.isBool()) "bool" else "unknown";
        const msg = std.fmt.bufPrint(&buf, "Cannot assign {s} to property {s}::${s} of type {s}", .{ val_type, class_name, prop.name, type_name }) catch "Cannot assign: type mismatch";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }

    // 未知类型：不转换
    return value;
}

pub fn php_object_get(obj_val: Value, property_name: []const u8) !Value {
    if (!Value_isObject(obj_val)) {
        // PHP 8: 对 null 值访问属性时发出警告
        if (obj_val.isNull()) {
            var buf: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Attempt to read property \"{s}\" on null", .{property_name}) catch "Attempt to read property on null";
            emitWarning(msg);
        }
        return Value.initNull();
    }

    const obj = Value_asObject(obj_val);

    // ★批次十二：ArrayObject ARRAY_AS_PROPS 读重定向（先于可见性检查——属性名全量
    //   重定向 storage；未命中 Warning `Undefined array key` + null，PHP 真值 m5 钉死）。
    if (arrayObjectAsPropsStorage(obj)) |storage| {
        const key = ArrayKey{ .string = PHPString.initStatic(property_name) };
        // ★R-341（§269）：elements.get 直读不 retain 是借用——自有化（retain 配对），
        //   与 getProperty 契约（:33119 retain）对齐；R-336 恢复后释放配平。
        if (storage.elements.get(key)) |v| {
            _ = v.retain();
            return v;
        }
        var wbuf: [256]u8 = undefined;
        const wmsg = std.fmt.bufPrint(&wbuf, "Undefined array key \"{s}\"", .{property_name}) catch "Undefined array key";
        emitWarning(wmsg);
        return Value.initNull();
    }

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, property_name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __get 魔术方法
                if (try tryMagicGet(obj_val, meta, property_name)) |result| {
                    return result;
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, property_name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
            // PHP 8: typed property 未初始化检查
            if (decl.prop.type_name != null and !decl.prop.has_default) {
                if (obj.getPropertyDirect(property_name) == null) {
                    var buf: [256]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "Typed property {s}::${s} must not be accessed before initialization", .{ decl.class.name, property_name }) catch "Typed property must not be accessed before initialization";
                    return throwThrowable("Error", msg, runtime_allocator);
                }
            }
            // ★F-83（工单 §70.1，由门 PD2 的守卫臂 `g6` 抓到）：**声明了但未写默认值的无类型属性**，
            //   PHP 的语义是"隐式 null 默认值"⇒ 读取静默给 NULL。而 AOT 只为"有默认值"的属性建槽 ⇒
            //   槽缺失时控制流一路落到下面的"未声明属性"支，多发 `Warning: Undefined property: G6::$p`＝**多说话**方向。
            //   ★刻意只覆盖"无类型"（typed 无默认值已由上面的 Error 拦住，不能在这里变成 null）。
            if (decl.prop.type_name == null and obj.getPropertyDirect(property_name) == null) {
                return Value.initNull();
            }
        } else {
            // 属性未声明：检查动态属性，若无则尝试 __get
            if (obj.getProperty(property_name)) |val| {
                return val;
            }
            if (try tryMagicGet(obj_val, meta, property_name)) |result| {
                return result;
            }
            // AOT-CODEGEN-012 R-132：PHP 对未定义属性读发 Warning（诊断对齐，原先静默 null；
            // __get 已接管的路径不告警 ✓；@ 抑制由 emitWarning 自带 ✓）
            var wbuf: [256]u8 = undefined;
            const wmsg = std.fmt.bufPrint(&wbuf, "Undefined property: {s}::${s}", .{ meta.name, property_name }) catch "Undefined property";
            emitWarning(wmsg);
            return Value.initNull();
        }
    }

    // 无 meta（非类实例对象，如 stdClass 动态对象）——PHP 同样对未定义读告警
    if (obj.getProperty(property_name)) |val| {
        return val;
    }
    var wbuf: [256]u8 = undefined;
    const wmsg = std.fmt.bufPrint(&wbuf, "Undefined property: {s}::${s}", .{ obj.class_name, property_name }) catch "Undefined property";
    emitWarning(wmsg);
    return Value.initNull();
}

pub fn php_object_get_ref(obj_val: Value, prop_name_val: Value, allocator: Allocator) !Value {
    // 键缓冲区必须与对象自身的分配器配对（deinit/gcDestroyObject 用 self.allocator 释放），
    // 故不使用调用方传入的 allocator
    _ = allocator;
    if (!Value_isObject(obj_val)) return error.InvalidArgument;
    if (!prop_name_val.isString()) return error.InvalidArgument;

    const obj = Value_asObject(obj_val);
    const name = prop_name_val.asString().data;

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
        }
    }

    // 获取属性值指针
    const entry_ptr = obj.properties.getPtr(name) orelse blk: {
        // 属性不存在，创建一个 null 值
        // ★批次十五：PHP 8.2+ 动态属性创建发 Deprecated（与 php_object_set :26840 同口径——
        //   stdClass / #[AllowDynamicProperties] 豁免）。by-ref 实参 `byref($p->undef)` 的
        //   PHP 真值＝Deprecated + 建槽（魔术方法 __get/__set 的间接修改边界未覆盖，登记）。
        if (obj.class_meta) |meta| {
            if (findPropertyDeclaringClass(meta, name) == null and
                !std.mem.eql(u8, meta.name, "stdClass") and !hasAllowDynamicProperties(meta))
            {
                var dbuf: [256]u8 = undefined;
                const dmsg = std.fmt.bufPrint(&dbuf, "Creation of dynamic property {s}::${s} is deprecated", .{ meta.name, name }) catch "Creation of dynamic property is deprecated";
                emitDeprecated(dmsg);
            }
        }
        try obj.putProperty(name, Value.initNull());
        break :blk obj.properties.getPtr(name).?;
    };

    return Value.initRef(entry_ptr);
}

pub fn php_object_get_direct(obj_val: Value, property_name: []const u8) !Value {
    if (!Value_isObject(obj_val)) {
        return Value.initNull();
    }

    const obj = Value_asObject(obj_val);
    return obj.getPropertyDirect(property_name) orelse Value.initNull();
}

pub fn php_object_get_safe_value(obj_val: Value, prop_name_val: Value) !Value {
    if (!Value_isObject(obj_val)) {
        return Value.initNull();
    }
    if (!prop_name_val.isString()) {
        return Value.initNull();
    }
    const obj = Value_asObject(obj_val);
    const name = prop_name_val.asString().data;

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __get 魔术方法
                if (try tryMagicGet(obj_val, meta, name)) |result| {
                    return result;
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
        } else {
            // 属性未声明：检查动态属性，若无则尝试 __get
            if (obj.getProperty(name)) |val| {
                return val;
            }
            if (try tryMagicGet(obj_val, meta, name)) |result| {
                return result;
            }
            return Value.initNull();
        }
    }

    return obj.getProperty(name) orelse Value.initNull();
}

/// ★F-86：`??` 语境的属性读（PHP 8.5.8 实测）：未声明属性、**不可访问的 private/protected**、
/// typed 属性未初始化、以及非对象接收者，一律**静默返回 null**（`??` 下均不告警、不抛 Error），
/// 且未声明属性仍会尝试 `__get`。与 `php_object_get` 同契约：返回**借用**引用，调用点负责 retain。
pub fn php_object_get_coalesce(obj_val: Value, property_name: []const u8) !Value {
    if (!Value_isObject(obj_val)) return Value.initNull();
    const obj = Value_asObject(obj_val);
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, property_name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                if (try tryMagicGet(obj_val, meta, property_name)) |result| return result;
                return Value.initNull();
            }
        } else {
            if (obj.getProperty(property_name)) |val| return val;
            if (try tryMagicGet(obj_val, meta, property_name)) |result| return result;
            return Value.initNull();
        }
    }
    return obj.getProperty(property_name) orelse Value.initNull();
}

/// ★F-151-b：isset/empty 链的**属性中继**读取（PHP 语义：先 `__isset`；false ⇒ null 短路，true ⇒ 按需 `__get`）。
/// 与 `php_object_get_coalesce` 的差别：后者不调 `__isset`、直接 `__get`（`??` 语义）。
/// 返回借用引用，调用点负责 retain（与 `php_object_get` 同契约）。
pub fn php_object_get_isset_chain(obj_val: Value, property_name: []const u8) !Value {
    if (!(try objectIssetByName(obj_val, property_name))) return Value.initNull();
    return php_object_get_coalesce(obj_val, property_name);
}

pub fn php_object_get_dynamic(obj_val: Value, prop_name_val: Value) !Value {
    if (!Value_isObject(obj_val)) {
        return Value.initNull();
    }
    if (!prop_name_val.isString()) {
        return Value.initNull();
    }
    const obj = Value_asObject(obj_val);
    const prop_str = prop_name_val.asString();
    const name = prop_str.data;

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __get 魔术方法
                if (try tryMagicGet(obj_val, meta, name)) |result| {
                    return result;
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
        } else {
            // 属性未声明：先检查动态属性
            if (obj.getProperty(name)) |prop_val| {
                return prop_val;
            }
            // 尝试 __get 魔术方法
            if (try tryMagicGet(obj_val, meta, name)) |result| {
                return result;
            }
            // 无 __get：返回 [obj, method_name] 数组供 php_invoke_callable 调用
            const arr = try PHPArray.init(runtime_allocator);
            errdefer arr.release(runtime_allocator);
            try arr.push(runtime_allocator, obj_val);
            try arr.push(runtime_allocator, prop_name_val);
            return Value.initArray(arr);
        }
    }

    // 先查找属性
    if (obj.getProperty(name)) |prop_val| {
        return prop_val;
    }
    // 属性不存在时，返回 [obj, method_name] 数组供 php_invoke_callable 调用
    const arr = try PHPArray.init(runtime_allocator);
    errdefer arr.release(runtime_allocator);
    try arr.push(runtime_allocator, obj_val);
    try arr.push(runtime_allocator, prop_name_val);
    return Value.initArray(arr);
}

pub fn php_object_set_dynamic(obj_val: Value, prop_name_val: Value, value: Value) !Value {
    if (!Value_isObject(obj_val)) {
        return Value.initNull();
    }
    if (!prop_name_val.isString()) {
        return Value.initNull();
    }
    const obj = Value_asObject(obj_val);
    const prop_str = prop_name_val.asString();
    const name = prop_str.data;

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __set 魔术方法
                if (try tryMagicSet(obj_val, meta, name, value)) {
                    return Value.initNull();
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
            // readonly 属性 enforcement（__clone 上下文中允许重新初始化）
            if (decl.prop.is_readonly and obj.hasProperty(name) and !in_clone_context) {
                var buf: [256]u8 = undefined;
                // ★P2 措辞差：PHP 打**声明类**名（decl.class），非运行时类（meta.name）
                const msg = std.fmt.bufPrint(&buf, "Cannot modify readonly property {s}::${s}", .{ decl.class.name, name }) catch "Cannot modify readonly property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
            // 属性类型 coercion：将值转换为声明类型
            const coerced = try coercePropertyType(decl.prop, value, meta.name);
            try obj.setProperty(name, coerced);
            return Value.initNull();
        } else {
            // 属性未声明：尝试 __set 魔术方法
            if (try tryMagicSet(obj_val, meta, name, value)) {
                return Value.initNull();
            }
        }
    }

    try obj.setProperty(name, value);
    return Value.initNull();
}

/// 类型转换函数
pub fn php_cast_int(val: Value) !Value {
    // ★F-77：对象 ⇒ Warning＋1（修前＝`toInt()` 无对象分支 ⇒ 静默落 `return 0`，值与诊断双错）
    const probe = derefForNumberProbe(val);
    if (Value_isObject(probe)) {
        emitObjectToNumberWarning(probe, "int");
        return Value.initInt(1);
    }
    warnFloatToIntNotRepresentable(val); // ★F-69 显式站点（实测：`(int)1e19` ⇒ Warn＋-8446744073709551616；`(int)2.5` ⇒ 零诊断）
    return Value.initInt(val.toInt());
}

pub fn php_cast_float(val: Value) !Value {
    const probe = derefForNumberProbe(val);
    if (Value_isObject(probe)) {
        emitObjectToNumberWarning(probe, "float");
        return Value.initFloat(1.0);
    }
    return Value.initFloat(val.toFloat());
}

pub fn php_cast_string(val: Value) !Value {
    const str = try val.toString(runtime_allocator);
    return Value.initString(str);
}

pub fn php_cast_bool(val: Value) !Value {
    return Value.initBool(val.toBool());
}

pub fn php_cast_array(val: Value) !Value {
    const actual_val = if (val.isRef()) val.asRef().* else val;
    if (actual_val.isArray()) {
        return actual_val;
    }
    const arr = try PHPArray.init(runtime_allocator);
    if (actual_val.isNull()) {
        return Value.initArray(arr);
    }
    // 对象转数组：将属性名作为键，属性值作为数组元素
    if (Value_isObject(actual_val)) {
        const obj = Value_asObject(actual_val);
        // ★批次十一：ArrayObject/ArrayIterator 的 (array) cast 定制（对应 Zend 的 cast_object
        //   handler——该族返回**元素面**而非属性面，PHP 真值 `(array)new ArrayObject([1,x=>2])` = `[1,x=>2]`）。
        //   沿继承链判定（用户子类同语义），其余类维持属性面旧路径。
        {
            var m: ?*const ClassMeta = obj.class_meta;
            var is_spl_storage_class = false;
            while (m) |mm| : (m = mm.parent) {
                if (std.ascii.eqlIgnoreCase(mm.name, "ArrayObject") or std.ascii.eqlIgnoreCase(mm.name, "ArrayIterator")) {
                    is_spl_storage_class = true;
                    break;
                }
            }
            if (is_spl_storage_class) {
                if (obj.properties.get("storage")) |storage| {
                    if (storage.isArray()) {
                        const src = storage.asArray();
                        var it = src.elements.iterator();
                        while (it.next()) |entry| {
                            const key_val: Value = switch (entry.key_ptr.*) {
                                .integer => |i| Value.initInt(i),
                                .string => |sp| blk: {
                                    sp.retain();
                                    break :blk Value.initString(sp);
                                },
                            };
                            defer key_val.release(runtime_allocator);
                            _ = entry.value_ptr.retain();
                            try arr.setByValue(runtime_allocator, key_val, entry.value_ptr.*);
                        }
                        return Value.initArray(arr);
                    }
                }
            }
        }
        var it = obj.properties.iterator();
        while (it.next()) |entry| {
            const key_phpstr = try PHPString.init(runtime_allocator, entry.key_ptr.*);
            const key_val = Value.initString(key_phpstr);
            try arr.setByValue(runtime_allocator, key_val, entry.value_ptr.*);
            key_val.release(runtime_allocator);
        }
        return Value.initArray(arr);
    }
    // 标量转数组：包装为单元素数组
    try arr.push(runtime_allocator, actual_val);
    return Value.initArray(arr);
}

pub fn php_cast_object(val: Value) !Value {
    // 如果已经是对象，直接返回
    if (Value_isObject(val)) {
        return val;
    }

    // 数组转对象：将数组元素作为对象属性
    if (val.isArray()) {
        const obj_val = try php_object_new("stdClass", runtime_allocator);
        const obj = Value_asObject(obj_val);
        var it = val.asArray().elements.iterator();
        while (it.next()) |entry| {
            switch (entry.key_ptr.*) {
                .string => |key| {
                    try obj.setProperty(key.data, entry.value_ptr.*);
                },
                .integer => |idx| {
                    const key_str = try std.fmt.allocPrint(runtime_allocator, "{d}", .{idx});
                    defer runtime_allocator.free(key_str);
                    try obj.putProperty(key_str, entry.value_ptr.*.retain());
                },
            }
        }
        return obj_val;
    }

    // 标量类型转对象：创建 stdClass 对象，值存储在 "scalar" 属性中
    // PHP 行为：(object)"test" 创建 stdClass { scalar: "test" }
    const obj_val = try php_object_new("stdClass", runtime_allocator);
    const obj = Value_asObject(obj_val);
    try obj.setProperty("scalar", val);
    return obj_val;
}

/// 设置对象属性
///
/// @param obj_val 对象Value
/// @param property_name 属性名
/// @param value 属性值
pub fn php_object_set(obj_val: Value, property_name: []const u8, value: Value) !Value {
    if (!Value_isObject(obj_val)) {
        // PHP: 对非对象设置属性发出警告但不终止
        return Value.initNull();
    }

    const obj = Value_asObject(obj_val);

    // ★批次十二：ArrayObject ARRAY_AS_PROPS 写重定向——写 storage（不产生动态属性、
    //   不发 Creation of dynamic property Deprecated，PHP 真值 m3/m4 钉死）。
    if (arrayObjectAsPropsStorage(obj)) |storage| {
        const kstr = try PHPString.init(runtime_allocator, property_name);
        try storage.set(runtime_allocator, .{ .string = kstr }, value);
        kstr.release(runtime_allocator);
        return Value.initNull();
    }

    // 属性可见性检查
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, property_name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __set 魔术方法
                if (try tryMagicSet(obj_val, meta, property_name, value)) {
                    return Value.initNull();
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, property_name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
            // readonly 属性 enforcement：已初始化的 readonly 属性不可修改（__clone 上下文中允许重新初始化）
            if (decl.prop.is_readonly and obj.hasProperty(property_name) and !in_clone_context) {
                var buf: [256]u8 = undefined;
                // ★P2 措辞差：PHP 打**声明类**名（decl.class），非运行时类（meta.name）
                const msg = std.fmt.bufPrint(&buf, "Cannot modify readonly property {s}::${s}", .{ decl.class.name, property_name }) catch "Cannot modify readonly property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
            // 属性类型 coercion：将值转换为声明类型
            const coerced = try coercePropertyType(decl.prop, value, meta.name);
            try obj.setProperty(property_name, coerced);
            return Value.initNull();
        } else {
            // 属性未声明：尝试 __set 魔术方法
            if (try tryMagicSet(obj_val, meta, property_name, value)) {
                return Value.initNull();
            }
            // AOT-CODEGEN-012 R-132/R-133：PHP 8.2+ 动态属性创建发 Deprecated
            //（stdClass 豁免 + #[AllowDynamicProperties] 豁免）
            if (!std.mem.eql(u8, meta.name, "stdClass") and !hasAllowDynamicProperties(meta)) {
                var dbuf: [256]u8 = undefined;
                const dmsg = std.fmt.bufPrint(&dbuf, "Creation of dynamic property {s}::${s} is deprecated", .{ meta.name, property_name }) catch "Creation of dynamic property is deprecated";
                emitDeprecated(dmsg);
            }
        }
    }

    try obj.setProperty(property_name, value);
    return Value.initNull();
}

/// $obj->prop[] = value — 向对象属性数组追加元素
pub fn php_property_array_push_with_obj(obj_val: Value, prop_name: Value, value: Value, _: Value) !void {
    if (!Value_isObject(obj_val)) return;
    const obj = Value_asObject(obj_val);
    const name = if (prop_name.isString()) prop_name.asString().data else return;

    // 获取属性值
    var prop_val = obj.getPropertyDirect(name) orelse Value.initNull();

    // 如果属性不是数组，创建一个新数组
    if (!prop_val.isArray()) {
        const arr = try PHPArray.init(runtime_allocator);
        prop_val = Value.initArray(arr);
        try obj.setProperty(name, prop_val);
    }

    const arr = prop_val.asArray();
    _ = value.retain();
    try arr.push(runtime_allocator, value);
}

/// $obj->prop[key][] = value — 向对象属性子数组追加元素
pub fn php_property_array_push_key_with_obj(obj_val: Value, prop_name: Value, key: Value, value: Value, _: Value) !void {
    if (!Value_isObject(obj_val)) return;
    const obj = Value_asObject(obj_val);
    const name = if (prop_name.isString()) prop_name.asString().data else return;

    // 获取属性值
    var prop_val = obj.getPropertyDirect(name) orelse Value.initNull();

    // 如果属性不是数组，创建一个新数组
    if (!prop_val.isArray()) {
        const arr = try PHPArray.init(runtime_allocator);
        prop_val = Value.initArray(arr);
        try obj.setProperty(name, prop_val);
    }

    const arr = prop_val.asArray();
    const arr_key = normalizeArrayKeyFromValue(key);

    // 获取或创建子数组
    var sub_val = arr.get(arr_key) orelse Value.initNull();
    if (sub_val.isNull()) {
        const sub_arr = try PHPArray.init(runtime_allocator);
        sub_val = Value.initArray(sub_arr);
        try arr.set(runtime_allocator, arr_key, sub_val);
    } else if (!sub_val.isArray()) {
        // 原有值不是数组，替换为新数组
        sub_val.release(runtime_allocator);
        const sub_arr = try PHPArray.init(runtime_allocator);
        sub_val = Value.initArray(sub_arr);
        try arr.set(runtime_allocator, arr_key, sub_val);
    }

    // 追加到子数组
    const sub_arr = sub_val.asArray();
    _ = value.retain();
    try sub_arr.push(runtime_allocator, value);
}

/// $obj->prop[key1][key2][] = value — 向对象属性二级子数组追加元素
pub fn php_property_array_push_key2_with_obj(obj_val: Value, prop_name: Value, key1: Value, key2: Value, value: Value, _: Value) !void {
    if (!Value_isObject(obj_val)) return;
    const obj = Value_asObject(obj_val);
    const name = if (prop_name.isString()) prop_name.asString().data else return;

    var prop_val = obj.getPropertyDirect(name) orelse Value.initNull();
    if (!prop_val.isArray()) {
        const arr = try PHPArray.init(runtime_allocator);
        prop_val = Value.initArray(arr);
        try obj.setProperty(name, prop_val);
    }

    const arr = prop_val.asArray();
    const arr_key1 = normalizeArrayKeyFromValue(key1);

    var sub_val = arr.get(arr_key1) orelse Value.initNull();
    if (sub_val.isNull() or !sub_val.isArray()) {
        if (!sub_val.isNull()) sub_val.release(runtime_allocator);
        const sub_arr = try PHPArray.init(runtime_allocator);
        sub_val = Value.initArray(sub_arr);
        try arr.set(runtime_allocator, arr_key1, sub_val);
    }

    const sub_arr = sub_val.asArray();
    const arr_key2 = normalizeArrayKeyFromValue(key2);

    var sub2_val = sub_arr.get(arr_key2) orelse Value.initNull();
    if (sub2_val.isNull() or !sub2_val.isArray()) {
        if (!sub2_val.isNull()) sub2_val.release(runtime_allocator);
        const sub2_arr = try PHPArray.init(runtime_allocator);
        sub2_val = Value.initArray(sub2_arr);
        try sub_arr.set(runtime_allocator, arr_key2, sub2_val);
    }

    const sub2_arr = sub2_val.asArray();
    _ = value.retain();
    try sub2_arr.push(runtime_allocator, value);
}

/// $obj->prop[key1][key2] = value — 向对象属性二级子数组设置元素
pub fn php_property_array_set_key2_with_obj(obj_val: Value, prop_name: Value, key1: Value, key2: Value, value: Value, _: Value) !void {
    if (!Value_isObject(obj_val)) return;
    const obj = Value_asObject(obj_val);
    const name = if (prop_name.isString()) prop_name.asString().data else return;

    var prop_val = obj.getPropertyDirect(name) orelse Value.initNull();
    if (!prop_val.isArray()) {
        const arr = try PHPArray.init(runtime_allocator);
        prop_val = Value.initArray(arr);
        try obj.setProperty(name, prop_val);
    }

    const arr = prop_val.asArray();
    const arr_key1 = normalizeArrayKeyFromValue(key1);

    var sub_val = arr.get(arr_key1) orelse Value.initNull();
    if (sub_val.isNull() or !sub_val.isArray()) {
        if (!sub_val.isNull()) sub_val.release(runtime_allocator);
        const sub_arr = try PHPArray.init(runtime_allocator);
        sub_val = Value.initArray(sub_arr);
        try arr.set(runtime_allocator, arr_key1, sub_val);
    }

    const sub_arr = sub_val.asArray();
    const arr_key2 = normalizeArrayKeyFromValue(key2);
    _ = value.retain();
    try sub_arr.set(runtime_allocator, arr_key2, value);
}
pub fn php_property_array_set_with_obj(obj_val: Value, prop_name: Value, key: Value, value: Value, _: Value) !void {
    if (!Value_isObject(obj_val)) return;
    const obj = Value_asObject(obj_val);
    const name = if (prop_name.isString()) prop_name.asString().data else return;

    // 获取属性值
    var prop_val = obj.getPropertyDirect(name) orelse Value.initNull();

    // 如果属性不是数组，创建一个新数组
    if (!prop_val.isArray()) {
        const arr = try PHPArray.init(runtime_allocator);
        prop_val = Value.initArray(arr);
        try obj.setProperty(name, prop_val);
    }

    const arr = prop_val.asArray();
    const arr_key = normalizeArrayKeyFromValue(key);
    try arr.set(runtime_allocator, arr_key, value);
}

/// 调用对象方法
///
/// @param obj_val 对象Value
/// @param method_name 方法名
/// @param args 参数数组
/// @return 方法返回值
pub fn php_object_call(obj_val: Value, method_name: []const u8, args: []const Value) !Value {
    if (obj_val.isString()) {
        if (std.mem.eql(u8, method_name, "toUpper")) return php_strtoupper(obj_val, runtime_allocator);
        if (std.mem.eql(u8, method_name, "toLower")) return php_strtolower(obj_val, runtime_allocator);
        if (std.mem.eql(u8, method_name, "trim")) return php_trim(obj_val, Value.initNull(), runtime_allocator);
        if (std.mem.eql(u8, method_name, "length")) return php_strlen(obj_val);
        if (std.mem.eql(u8, method_name, "replace")) {
            if (args.len < 2) return error.MissingArgument;
            return php_str_replace(args[0], args[1], obj_val, Value.initNull(), runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "substring")) {
            if (args.len < 2) return error.MissingArgument;
            return php_substr(obj_val, args[0], args[1], runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "indexOf")) {
            if (args.len < 1) return error.MissingArgument;
            return php_strpos(obj_val, args[0], Value.initInt(0));
        }
        if (std.mem.eql(u8, method_name, "lastIndexOf")) {
            if (args.len < 1) return error.MissingArgument;
            return php_strrpos(obj_val, args[0], Value.initInt(0));
        }
        if (std.mem.eql(u8, method_name, "contains")) {
            if (args.len < 1) return error.MissingArgument;
            return php_str_contains(obj_val, args[0]);
        }
        if (std.mem.eql(u8, method_name, "startsWith")) {
            if (args.len < 1) return error.MissingArgument;
            return php_str_starts_with(obj_val, args[0]);
        }
        if (std.mem.eql(u8, method_name, "endsWith")) {
            if (args.len < 1) return error.MissingArgument;
            return php_str_ends_with(obj_val, args[0]);
        }
        if (std.mem.eql(u8, method_name, "repeat")) {
            if (args.len < 1) return error.MissingArgument;
            return php_str_repeat(obj_val, args[0], runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "pad")) {
            if (args.len < 1) return error.MissingArgument;
            var created_pad_str = false;
            const pad_str = if (args.len >= 2) args[1] else blk: {
                created_pad_str = true;
                break :blk Value.initString(try PHPString.init(runtime_allocator, " "));
            };
            defer if (created_pad_str) pad_str.release(runtime_allocator);
            const pad_type = if (args.len >= 3) args[2] else Value.initInt(0);
            return php_str_pad(obj_val, args[0], pad_str, pad_type, runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "reverse")) return php_strrev(obj_val, runtime_allocator);
        if (std.mem.eql(u8, method_name, "split")) {
            if (args.len < 1) return error.MissingArgument;
            return php_explode(args[0], obj_val, Value.initNull(), runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "concat")) {
            if (args.len < 1) return error.MissingArgument;
            return php_concat(obj_val, args[0], runtime_allocator);
        }
        // AOT-CODEGEN-013 F-9：原 `return error.UnknownMethod`（全仓仅此一处产生、零消费者）
        // 被调用侧 catch 成静默 null ⇒ PHP 实为可捕获 Error「Call to a member function foo() on string」。
        // 上方伪方法面（toUpper/trim/replace… 非 PHP 语义）保持原样不动，只改「未命中」的落点。
        var sbuf: [256]u8 = undefined;
        const smsg = std.fmt.bufPrint(&sbuf, "Call to a member function {s}() on string", .{method_name}) catch
            "Call to a member function on string";
        return throwThrowable("Error", smsg, runtime_allocator);
    }

    // Closure 方法调用：bindTo/call/__invoke 等
    if (obj_val.isFunction()) {
        if (std.mem.eql(u8, method_name, "bindTo") and args.len >= 1) {
            const scope_val = if (args.len >= 2) args[1] else Value.initNull();
            return php_closure_bind(obj_val, args[0], scope_val);
        }
        if (std.mem.eql(u8, method_name, "call") and args.len >= 1) {
            // Closure::call: scope 自动设为 newThis 的类
            var scope_val = Value.initNull();
            var created_scope = false;
            if (Value_isObject(args[0])) {
                const call_obj = Value_asObject(args[0]);
                if (call_obj.class_meta) |cm| {
                    scope_val = Value.initString(try PHPString.init(runtime_allocator, cm.name));
                    created_scope = true;
                }
            }
            defer if (created_scope) scope_val.release(runtime_allocator);
            const bound = try php_closure_bind(obj_val, args[0], scope_val);
            defer bound.release(runtime_allocator);
            return php_invoke_callable(bound, args[1..], runtime_allocator);
        }
        if (std.mem.eql(u8, method_name, "__invoke")) {
            return php_invoke_callable(obj_val, args, runtime_allocator);
        }
        if (findClass("Closure")) |closure_meta| {
            if (closure_meta.findMethod(method_name)) |method| {
                return method.func(obj_val, args, runtime_allocator);
            }
        }
        // AOT-CODEGEN-013 F-9：原实现「打印 PHP Fatal error 文本 + return null」⇒ 既不终止也不设异常，
        // 后续语句继续执行且进程 rc=0（f170 内 7 次 fatal 一路跑到底）。PHP 真值是可捕获 Error：
        // 「Call to undefined method Closure::nope()」。改走 throwThrowable（口径同 :20081 抽象类实例化）。
        var cbuf: [256]u8 = undefined;
        const cmsg = std.fmt.bufPrint(&cbuf, "Call to undefined method Closure::{s}()", .{method_name}) catch
            "Call to undefined method";
        return throwThrowable("Error", cmsg, runtime_allocator);
    }

    if (!Value_isObject(obj_val)) {
        // AOT-CODEGEN-013 F-9：同上。PHP 真值「Call to a member function {m}() on {type}」
        // （实测 int / null / string 形；bool 用 true/false 词，与 phpArgTypeWord 同口径）。
        var nbuf: [256]u8 = undefined;
        const nmsg = std.fmt.bufPrint(&nbuf, "Call to a member function {s}() on {s}", .{ method_name, phpArgTypeWord(obj_val) }) catch
            "Call to a member function on a non-object";
        return throwThrowable("Error", nmsg, runtime_allocator);
    }
    const obj = Value_asObject(obj_val);
    return obj.callMethod(method_name, args) catch |err| {
        if (err == error.MethodNotFound) {
            // AOT-CODEGEN-013 F-9：原实现打印 Fatal 文本后 return null ⇒ 调用方无感续跑、rc=0。
            // PHP 真值：可捕获 Error「Call to undefined method K::nopeMethod()」，未捕获则 rc=255 中止。
            const class_name = if (obj.class_meta) |m| m.name else "unknown";
            var buf: [512]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "Call to undefined method {s}::{s}()", .{ class_name, method_name }) catch
                "Call to undefined method";
            return throwThrowable("Error", msg, runtime_allocator);
        }
        return err;
    };
}

/// 动态类名实例化: new $var()
/// class_name_val 是类名（Value，通常是字符串），args 是构造函数参数
pub fn php_new_object_dynamic(class_name_val: Value, args: []const Value, allocator: Allocator) !Value {
    var class_name_buf: [256]u8 = undefined;
    var class_name: []const u8 = "";

    if (class_name_val.isString()) {
        const s = class_name_val.asString();
        if (s.length <= class_name_buf.len) {
            @memcpy(class_name_buf[0..s.length], s.data[0..s.length]);
            class_name = class_name_buf[0..s.length];
        } else {
            class_name = s.data[0..s.length];
        }
    } else {
        return error.InvalidClassName;
    }

    // 去除前导反斜杠（PHP完全限定名）
    if (class_name.len > 0 and class_name[0] == '\\') {
        class_name = class_name[1..];
    }

    return php_object_new_with_constructor(class_name, args, allocator);
}

/// ★R-344a（§269.6）：`new` 第一阶段——类解析 + 实例化性检查 + **裸分配**（对象 id 在此烧掉）。
///   PHP 的 NEW opcode 顺序：先分配（id 递增/复用），后求实参，再调构造器。
///   本函数**不调用构造器**；全部检查失败均为可捕获 Error（throwThrowable 契约）。
pub fn php_object_alloc(class_name: []const u8, allocator: Allocator) !Value {
    return phpObjectAllocImpl(class_name, allocator, true);
}

/// ★R-344c-c（§273.4）：反射面专用——四族检查+分配照旧，但**不做构造器可见性检查**
///   （反射的可见性失败抛 ReflectionException 而非 Error，由调用方按反射口径自检查）。
pub fn php_object_alloc_skip_visibility(class_name: []const u8, allocator: Allocator) !Value {
    return phpObjectAllocImpl(class_name, allocator, false);
}

fn phpObjectAllocImpl(class_name: []const u8, allocator: Allocator, check_visibility: bool) !Value {
    const resolved = try resolveSpecialClassName(class_name);
    var meta = findClass(resolved);

    // 如果找不到，尝试使用短名称（命名空间支持）
    if (meta == null) {
        if (std.mem.lastIndexOf(u8, resolved, "\\")) |last_sep| {
            const short_name = resolved[last_sep + 1 ..];
            meta = findClass(short_name);
        }
    }

    if (meta == null) {
        // ★R-344a（§269.6）：类不存在 ⇒ **可捕获** Error（throwThrowable 契约，与 R-342
        //   未定义函数同族；PHP 8.5.8 实测 `try { new NoSuch(); } catch (\Error)` 可捕获）。
        //   旧实现自印 fatal + exit(255)，绕过整条 catch 路由。
        //   未捕获时由既有未捕获通道输出（形态与 PHP 逐字一致，udf_uncaught 探针实证）。
        var nbuf: [512]u8 = undefined;
        const nmsg = std.fmt.bufPrint(&nbuf, "Class \"{s}\" not found", .{resolved}) catch "Class not found";
        return throwThrowable("Error", nmsg, allocator);
    }

    // 实例化性检查（PHP 8.5.8 实测措辞，new_checks_truth 探针逐字对参）：
    //   interface / trait / enum / abstract 四族均为可捕获 Error。
    //   ★R-344a：接口/trait/enum 为补齐项（旧只查 abstract）。
    const m0 = meta.?;
    if (m0.is_interface) {
        var msg_buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Cannot instantiate interface {s}", .{resolved}) catch "Cannot instantiate interface";
        return throwThrowable("Error", msg, allocator);
    }
    if (m0.is_trait) {
        var msg_buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Cannot instantiate trait {s}", .{resolved}) catch "Cannot instantiate trait";
        return throwThrowable("Error", msg, allocator);
    }
    if (m0.is_enum) {
        var msg_buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Cannot instantiate enum {s}", .{resolved}) catch "Cannot instantiate enum";
        return throwThrowable("Error", msg, allocator);
    }
    // abstract class 实例化检查：new AbstractClass() 抛出 Error
    if (m0.is_abstract) {
        var msg_buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Cannot instantiate abstract class {s}", .{resolved}) catch "Cannot instantiate abstract class";
        return throwThrowable("Error", msg, allocator);
    }

    // ★R-344c-b（§273.3）：构造器可见性检查移到分配**之后**——PHP 真值序：
    //   先分配对象（句柄烧掉）→ 可见性检查失败 → 销毁对象但句柄**不归还空闲栈**
    //   （php -r 钉板：`new Priv()` 的错误对象取新顶号，不弹空闲栈）。
    //   措辞不变：`Call to private|protected {声明类}::__construct() from global scope|scope {类}`。
    //   （R-344a 曾置于分配前；f-eval 仍不求值——检查在实参求值之前，oid_order 语义不受冲击）
    const obj = try PHPObject.initWithMeta(allocator, meta.?);
    const obj_val = Value_initObject(obj);
    if (check_visibility) {
        if (m0.findMethodLookup("__construct")) |lookup| {
        const ctor_m = lookup.method;
        if (ctor_m.is_private or ctor_m.is_protected) {
            const scope = getCurrentScopeClass();
            const allowed = if (ctor_m.is_private)
                (scope != null and std.mem.eql(u8, scope.?.name, lookup.owner.name))
            else
                (scope != null and (scope.?.isSubclassOf(lookup.owner.name) or lookup.owner.isSubclassOf(scope.?.name)));
            if (!allowed) {
                const vis: []const u8 = if (ctor_m.is_private) "private" else "protected";
                const msg = if (scope) |s|
                    try std.fmt.allocPrint(allocator, "Call to {s} {s}::__construct() from scope {s}", .{ vis, lookup.owner.name, s.name })
                else
                    try std.fmt.allocPrint(allocator, "Call to {s} {s}::__construct() from global scope", .{ vis, lookup.owner.name });
                defer allocator.free(msg);
                // ★R-344c-b（§273.3 定稿序）：**先**经 throwThrowable 分配 Error（取新顶号），
                //   **后**销毁失败对象并**归还句柄**（deinit 正常走 q4ObjectIdFree）——
                //   PHP 真值：失败对象的句柄在 Error 分配之后才回到空闲栈（ids2/oid 全序钉板）。
                const ex = try throwThrowable("Error", msg, allocator);
                obj_val.release(allocator);
                return ex;
            }
        }
        }
    }

    return obj_val;
}

/// ★R-344c-c（§273.4）：反射实例化组合通道——四族检查+分配（跳过可见性），
///   可见性按反射口径**无条件**检查（非公开构造器 ⇒ `ReflectionException:
///   "Access to non-public constructor of class {X}"`，措辞用被实例化类名）。
///   失败序与 `new` 面同（先分异常对象、后销毁失败对象归还句柄）。
fn reflectionNewInstanceImpl(class_name: []const u8, args: []const Value, allocator: Allocator) !Value {
    // 前导反斜杠（完全限定名）剥离，与 new 面同径
    const cname = if (class_name.len > 0 and class_name[0] == '\\') class_name[1..] else class_name;
    const obj_val = try php_object_alloc_skip_visibility(cname, allocator);
    // 四族检查/类不存在失败 ⇒ 异常对象上交（旗已置）
    if (hasException()) return obj_val;
    errdefer obj_val.release(allocator);
    if (Value_asObject(obj_val).class_meta) |m| {
        if (m.findMethodLookup("__construct")) |lookup| {
            if (lookup.method.is_private or lookup.method.is_protected) {
                var rbuf: [256]u8 = undefined;
                const rmsg = std.fmt.bufPrint(&rbuf, "Access to non-public constructor of class {s}", .{m.name}) catch "Access to non-public constructor";
                const ex = try throwThrowable("ReflectionException", rmsg, allocator);
                // 与 new 面同序：先分异常对象（取新顶号），后销毁失败对象归还句柄
                obj_val.release(allocator);
                return ex;
            }
        }
    }
    try php_object_call_ctor(obj_val, args, allocator);
    if (hasException()) {
        return error.RuntimeError;
    }
    return obj_val;
}

/// ★R-344a：`new` 第三阶段——构造器调用（invoke；可见性检查在 php_object_alloc 内、initWithMeta 之后[R-344c-b]）。
///   对象寄存器**归生成码所有**：任何失败路径都**不**归还 obj_val
///   （组合通道 php_object_new_with_constructor 经 errdefer 自行归还；直拆通道由生成码清理）。
///   失败形态：构造器 Zig error ⇒ 传播；构造器置旗（F-133 单块发射）⇒ error.RuntimeError（不归还对象）。
pub fn php_object_call_ctor(obj_val: Value, args: []const Value, allocator: Allocator) !void {
    const obj = Value_asObject(obj_val);
    if (obj.class_meta) |m| {
        if (m.findMethodLookup("__construct")) |lookup| {
            const guard = ClassContext.init(m, lookup.owner);
            defer guard.deinit();
            // ★R-344a：构造器抛错不归还对象（拆分通道对象已交出，由生成码异常清理归还）
            _ = try lookup.method.func(obj_val, args, allocator);
            // F-133: 单块发射器的 throw 只 setException 后正常返回（不走 Zig error）
            if (hasException()) {
                return error.RuntimeError;
            }
            // 注意：构造函数中的 store $this 会 retain，函数结束时会 release
            // 这是正确的引用计数行为，不需要补偿
        }
    }
}

/// 创建新对象并调用构造函数（组合通道：内部调用方兼容入口）。
///   ★R-344a：= php_object_alloc + php_object_call_ctor 组合；构造器失败经 errdefer 归还对象
///   （对象未交出 ⇒ 工厂语义与旧实现一致）。
pub fn php_object_new_with_constructor(class_name: []const u8, args: []const Value, allocator: Allocator) !Value {
    const obj_val = try php_object_alloc(class_name, allocator);
    // alloc 失败 = 可捕获 Error 已置旗且返回值即异常对象 ⇒ 直接上交（与旧实现同语义：
    //   生成码 reg 收异常对象，hasException 路由，清理链归还）
    if (hasException()) return obj_val;
    errdefer obj_val.release(allocator);
    try php_object_call_ctor(obj_val, args, allocator);
    if (hasException()) {
        return error.RuntimeError;
    }
    return obj_val;
}

/// ★R-344a：`new $dyn` 的第一阶段（类名 Value 解包 + 裸分配）。
pub fn php_object_alloc_dynamic(class_name_val: Value, allocator: Allocator) !Value {
    var class_name_buf: [256]u8 = undefined;
    var class_name: []const u8 = "";

    if (class_name_val.isString()) {
        const s = class_name_val.asString();
        if (s.length <= class_name_buf.len) {
            @memcpy(class_name_buf[0..s.length], s.data[0..s.length]);
            class_name = class_name_buf[0..s.length];
        } else {
            class_name = s.data[0..s.length];
        }
    } else {
        return error.InvalidClassName;
    }

    // 去除前导反斜杠（PHP完全限定名）
    if (class_name.len > 0 and class_name[0] == '\\') {
        class_name = class_name[1..];
    }

    return php_object_alloc(class_name, allocator);
}

/// ★批次十九②：`new` 的命名/展开实参数组通道（命名或展开 ⇒ 编译期统一改道本函数）。
///   口径（PHP 8.5.8 实测 C1-C10）：字符串键＝构造器命名实参，按 ClassMethod 元数据绑定
///  （继承构造器经 findMethodLookup 沿父链解析）；构造器缺失且含命名 ⇒
///   Error `Unknown named parameter $x`（C10；纯位置参 PHP 静默忽略，维持既有通道）；
///   纯位置 ⇒ 收编回既有实例化通道（单一口径，不另造语义）。
/// ★R-344a：`new` 命名实参通道的第三阶段——构造器元数据绑定 + 调用（对象归生成码所有，不归还）。
///   返回 null 占位（.call 发射面统一带结果寄存器；失败经旗标/Zig error 表达）。
pub fn php_object_call_ctor_named(obj_val: Value, args_array: Value, allocator: Allocator) !Value {
    const obj = Value_asObject(obj_val);
    const meta = obj.class_meta orelse return Value.initNull(); // alloc 必带 meta ⇒ 不可达防御
    const arr = args_array.asArray();
    const ctor_lookup = meta.findMethodLookup("__construct") orelse {
        // 无构造器类 + 命名实参 ⇒ Error `Unknown named parameter $x`（C10 真值）
        var first: []const u8 = "";
        var it = arr.elements.iterator();
        while (it.next()) |entry| {
            switch (entry.key_ptr.*) {
                .string => |ks| {
                    first = ks.data;
                    break;
                },
                else => {},
            }
        }
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Unknown named parameter ${s}", .{first}) catch "Unknown named parameter";
        try throwThrowableDiscard("Error", msg, allocator);
        return Value.initNull();
    };
    const ctor_display = try std.fmt.allocPrint(allocator, "{s}::__construct", .{meta.name});
    defer allocator.free(ctor_display);
    const bind = try phpBindNamedValueArray(arr, ctor_lookup.method.param_names, methodVariadicIndex(ctor_lookup.method), ctor_lookup.method.required_params, ctor_display, allocator);
    defer bind.deinit(allocator);
    try php_object_call_ctor(obj_val, bind.final_args, allocator);
    return Value.initNull();
}

pub fn php_new_object_named(class_name_val: Value, args_array: Value, allocator: Allocator) !Value {
    // 类名提取（与 php_new_object_dynamic 同径）
    var class_name_buf: [256]u8 = undefined;
    var class_name: []const u8 = "";
    if (class_name_val.isString()) {
        const s = class_name_val.asString();
        if (s.length <= class_name_buf.len) {
            @memcpy(class_name_buf[0..s.length], s.data[0..s.length]);
            class_name = class_name_buf[0..s.length];
        } else {
            class_name = s.data[0..s.length];
        }
    } else {
        return error.InvalidClassName;
    }
    if (class_name.len > 0 and class_name[0] == '\\') class_name = class_name[1..];
    if (!args_array.isArray()) return throwUnpackTypeError(args_array, allocator);

    const arr = args_array.asArray();
    if (!arr.hasStringKeys()) {
        const max_count: usize = @intCast(arr.next_index);
        const tmp = try allocator.alloc(Value, max_count);
        defer allocator.free(tmp);
        var used: usize = 0;
        var i: usize = 0;
        while (i < max_count) : (i += 1) {
            if (arr.get(.{ .integer = @intCast(i) })) |v| {
                tmp[used] = v;
                used += 1;
            }
        }
        return php_object_new_with_constructor(class_name, tmp[0..used], allocator);
    }

    // 含命名 ⇒ 实例化性检查 + 裸分配（R-344a：检查与分配先于绑定/构造）+ 绑定构造（组合形）
    const obj_val = try php_object_alloc(class_name, allocator);
    if (hasException()) return obj_val;
    errdefer obj_val.release(allocator);
    _ = try php_object_call_ctor_named(obj_val, args_array, allocator);
    if (hasException()) {
        return error.RuntimeError;
    }
    return obj_val;
}

/// 检查类是否存在
///   ★F-75：`$autoload`／`$local_only`／`$allow_string` 一类参数在 AOT 下**惰性**（模板内 `autoload` 出现 0 次
///     ⇒ 无 autoloader；`getenv` 无 SAPI 环境分层），但**必须接收**——旧状是多传一参就 `expected N argument(s),
///     found N+1` ⇒ 合法 PHP 编不过（门 ARG 注册）。缺省值由 `builtin_map` 的 `optional_defaults` 声明式补齐。
pub fn php_class_exists(class_name: Value, autoload: Value, allocator: Allocator) !Value {
    _ = allocator;
    _ = autoload;
    if (!class_name.isString()) return Value.initBool(false);
    const name = class_name.asString().data;
    return Value.initBool(findClass(name) != null);
}

pub fn class_exists(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    if (args.len < 1) return error.MissingArgument;
    return php_class_exists(args[0], if (args.len > 1) args[1] else Value.initBool(true), allocator);
}

/// 检查接口是否存在
pub fn php_interface_exists(interface_name: Value, autoload: Value, allocator: Allocator) !Value {
    _ = allocator;
    _ = autoload;
    if (!interface_name.isString()) return Value.initBool(false);
    const name = interface_name.asString().data;
    // 在class_registry中查找，检查是否为接口
    if (findClass(name)) |meta| {
        return Value.initBool(meta.is_interface);
    }
    return Value.initBool(false);
}

pub fn interface_exists(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    if (args.len < 1) return error.MissingArgument;
    return php_interface_exists(args[0], if (args.len > 1) args[1] else Value.initBool(true), allocator);
}

/// 检查trait是否存在
pub fn php_trait_exists(trait_name: Value, autoload: Value, allocator: Allocator) !Value {
    _ = allocator;
