fn quickSortIndicesByValues(indices: []usize, values: []Value, allocator: Allocator, descending: bool) !void {
    if (indices.len < 2) return;

    const pivot_idx = indices[indices.len / 2];
    const pivot = values[pivot_idx];
    var i: usize = 0;
    var j: usize = indices.len - 1;

    while (i <= j) {
        while (true) {
            const cmp = try valueCompare(values[indices[i]], pivot, allocator);
            if ((!descending and cmp < 0) or (descending and cmp > 0)) {
                i += 1;
                if (i >= indices.len) break;
                continue;
            }
            break;
        }
        while (true) {
            const cmp = try valueCompare(values[indices[j]], pivot, allocator);
            if ((!descending and cmp > 0) or (descending and cmp < 0)) {
                if (j == 0) break;
                j -= 1;
                continue;
            }
            break;
        }

        if (i <= j) {
            const tmp = indices[i];
            indices[i] = indices[j];
            indices[j] = tmp;
            i += 1;
            if (j == 0) break;
            j -= 1;
        }
    }

    if (j > 0) try quickSortIndicesByValues(indices[0 .. j + 1], values, allocator, descending);
    if (i < indices.len) try quickSortIndicesByValues(indices[i..], values, allocator, descending);
}

pub fn php_array_multisort(arrays: []const Value, allocator: Allocator) !Value {
    if (arrays.len == 0) return Value.initBool(false); // 0 参：维持旧口径（ArgumentCountError 属 F-41 arity 域）

    // ★批次十四②：PHP 契约＝**先校验后排序**——任一参数非法 ⇒ 所有数组保持原样。
    //   PHP 8.5.8 实测文案：非 array/flag ⇒ TypeError「Argument #N must be an array or a sort flag」
    //   （#1 带 ($array) 段，#1 为合法 flag 值时带「that has not already been specified」后缀）；
    //   非法 flag 值 ⇒ ValueError「Argument #N must be a valid sort flag」（#1 带 ($array) 段）；
    //   数组尺寸不一致 ⇒ ValueError「Array sizes are inconsistent」。
    //   合法 flag 集实测：v ∈ [0,6] ∪ [8,14]（SORT_FLAG_CASE=8 可与类型位或，8|7=15 非法）。
    var first_count: usize = 0;
    var first_is_array = false;
    var mbuf: [224]u8 = undefined;
    for (arrays, 0..) |arg, i| {
        if (arg.isArray()) {
            if (!first_is_array) {
                first_count = arg.asArray().count();
                first_is_array = true;
            } else if (arg.asArray().count() != first_count) {
                return throwThrowable("ValueError", "Array sizes are inconsistent", allocator);
            }
        } else if (arg.isInt()) {
            const f = arg.asInt();
            const legal = (f >= 0 and f <= 6) or (f >= 8 and f <= 14);
            if (!legal) {
                const msg = if (i == 0)
                    std.fmt.bufPrint(&mbuf, "array_multisort(): Argument #1 ($array) must be a valid sort flag", .{}) catch "must be a valid sort flag"
                else
                    std.fmt.bufPrint(&mbuf, "array_multisort(): Argument #{d} must be a valid sort flag", .{i + 1}) catch "must be a valid sort flag";
                return throwThrowable("ValueError", msg, allocator);
            }
        } else {
            const msg = if (i == 0)
                std.fmt.bufPrint(&mbuf, "array_multisort(): Argument #1 ($array) must be an array or a sort flag", .{}) catch "must be an array or a sort flag"
            else
                std.fmt.bufPrint(&mbuf, "array_multisort(): Argument #{d} must be an array or a sort flag", .{i + 1}) catch "must be an array or a sort flag";
            return throwThrowable("TypeError", msg, allocator);
        }
    }
    if (!first_is_array) {
        // #1 是合法 flag 值（参数里没有任何数组）⇒ PHP 后缀版 TypeError
        return throwThrowable("TypeError", "array_multisort(): Argument #1 ($array) must be an array or a sort flag that has not already been specified", allocator);
    }

    // 解析参数：找到第一个数组（排序键）和排序方向
    const first_arr = arrays[0].asArray();
    const n = first_arr.count();
    var descending = false;
    // ★批次十四②：SORT_DESC 常量订正——PHP 常量为 SORT_ASC=4 / SORT_DESC=3
    //   （旧硬编码 ==2 实为 SORT_STRING，DESC 永不命中，探针实测显形）
    for (arrays[1..]) |arg| {
        if (arg.isInt() and arg.asInt() == 3) {
            descending = true;
            break;
        }
    }

    var first_vals = try allocator.alloc(Value, n);
    defer allocator.free(first_vals);
    var it0 = first_arr.elements.iterator();
    var idx0: usize = 0;
    while (it0.next()) |entry| : (idx0 += 1) first_vals[idx0] = entry.value_ptr.*;

    var indices = try allocator.alloc(usize, n);
    defer allocator.free(indices);
    for (0..n) |i| indices[i] = i;

    try quickSortIndicesByValues(indices, first_vals, allocator, descending);

    // 对所有数组参数（跳过非数组的排序标志）重排
    for (arrays) |arr_val| {
        if (!arr_val.isArray()) continue; // 跳过SORT_ASC/SORT_DESC等
        const a = arr_val.asArray();
        if (a.count() != n) return Value.initBool(false);

        var vals = try allocator.alloc(Value, n);
        defer allocator.free(vals);
        var it = a.elements.iterator();
        var i: usize = 0;
        while (it.next()) |entry| : (i += 1) vals[i] = entry.value_ptr.*;

        var new_elements = std.ArrayHashMapUnmanaged(ArrayKey, Value, PHPArray.ArrayContext, true){};
        for (indices, 0..) |src, dst| {
            try new_elements.put(allocator, .{ .integer = @intCast(dst) }, vals[src]);
        }
        a.elements.deinit();
        a.elements = PHPArray.Elements.initMixed(allocator, new_elements);
        a.next_index = @intCast(n);
    }

    return Value.initBool(true);
}

fn arrayCursorGet(arr: *PHPArray) usize {
    if (array_internal_pointers) |m| {
        return m.get(arr) orelse 0;
    }
    return 0;
}

fn arrayCursorSet(arr: *PHPArray, idx: usize, allocator: Allocator) !void {
    if (array_internal_pointers) |*m| {
        try m.put(arr, idx);
    } else {
        _ = allocator;
    }
}

fn arrayEntryAt(arr: *PHPArray, idx: usize) ?KV {
    var it = arr.elements.iterator();
    var i: usize = 0;
    while (it.next()) |entry| : (i += 1) {
        if (i == idx) return .{ .key = entry.key_ptr.*, .value = entry.value_ptr.* };
    }
    return null;
}

pub fn php_current(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    const idx = arrayCursorGet(a);
    if (arrayEntryAt(a, idx)) |kv| {
        _ = kv.value.retain();
        _ = allocator;
        return kv.value;
    }
    _ = allocator;
    return Value.initBool(false);
}

pub fn php_key(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();
    const a = arr.asArray();
    const idx = arrayCursorGet(a);
    if (arrayEntryAt(a, idx)) |kv| {
        _ = allocator;
        return switch (kv.key) {
            .integer => |i| Value.initInt(i),
            .string => |s| blk: {
                s.retain();
                break :blk Value.initString(s);
            },
        };
    }
    _ = allocator;
    return Value.initNull();
}

pub fn php_reset(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    try arrayCursorSet(a, 0, allocator);
    return php_current(arr, allocator);
}

pub fn php_end(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    const n = a.count();
    if (n == 0) {
        try arrayCursorSet(a, 0, allocator);
        return Value.initBool(false);
    }
    try arrayCursorSet(a, n - 1, allocator);
    return php_current(arr, allocator);
}

pub fn php_next(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    const idx = arrayCursorGet(a) + 1;
    try arrayCursorSet(a, idx, allocator);
    return php_current(arr, allocator);
}

pub fn php_prev(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    const cur = arrayCursorGet(a);
    if (cur == 0) return Value.initBool(false);
    try arrayCursorSet(a, cur - 1, allocator);
    return php_current(arr, allocator);
}

pub fn php_each(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    const a = arr.asArray();
    const idx = arrayCursorGet(a);
    const kv = arrayEntryAt(a, idx) orelse return Value.initBool(false);

    const key_val = switch (kv.key) {
        .integer => |i| Value.initInt(i),
        .string => |s| Value.initString(s),
    };

    const out = try PHPArray.init(allocator);
    errdefer out.release(allocator);

    try out.set(allocator, .{ .integer = 0 }, kv.value);
    try out.set(allocator, .{ .integer = 1 }, key_val);
    try arraySetByString(out, allocator, "key", key_val);
    try arraySetByString(out, allocator, "value", kv.value);

    try arrayCursorSet(a, idx + 1, allocator);

    return Value.initArray(out);
}

// ============================================================================
// 扩展字符串函数
// ============================================================================

/// ord - 返回字符的ASCII值
pub fn php_ord(str: Value) !Value {
    if (!str.isString()) return Value.initInt(0);

    const php_str = str.asString();
    if (php_str.length == 0) return Value.initInt(0);

    return Value.initInt(@intCast(php_str.data[0]));
}

/// chr - 返回指定ASCII值对应的字符
pub fn php_chr(code: Value, allocator: Allocator) !Value {
    // ★F-62f 第三批：`chr(): Argument #1 ($codepoint) must be of type int, Foo given`
    const code_ok = requireNumParam("chr", 1, "codepoint", .int_param, code) orelse return Value.initNull();
    const code_int = code_ok.toInt();
    // ★F-144（R-240）：越界值（<0 或 >255）按 %256 约束，并每次调用发一条同文案 Deprecated。
    if (code_int < 0 or code_int > 255) {
        emitDeprecated("chr(): Providing a value not in-between 0 and 255 is deprecated, this is because a byte value must be in the [0, 255] interval. The value used will be constrained using % 256");
    }
    const ascii = @as(u8, @truncate(@as(u64, @intCast(code_int & 0xFF))));
    const buffer = [_]u8{ascii};
    const result = try PHPString.init(allocator, &buffer);
    return Value.initString(result);
}

pub fn php_count_chars(str: Value, mode: Value, allocator: Allocator) !Value {
    // ★F-62f 第三批：可选 #2 ($mode)，Foo ⇒ TypeError；null/省略 ⇒ 默认 0（显式 null 的 Deprecated 属 helper 既有折衷）
    const mode_ok = requireOptionalNumParam("count_chars", 2, "mode", .int_param, mode) orelse return Value.initNull();
    const mode_int = if (mode_ok.isNull()) 0 else mode_ok.toInt();
    if (!str.isString()) {
        return switch (mode_int) {
            3, 4 => Value.initString(try PHPString.init(allocator, "")),
            else => Value.initArray(try PHPArray.init(allocator)),
        };
    }

    const bytes = str.asString().data;
    var counts: [256]usize = undefined;
    @memset(&counts, 0);
    for (bytes) |b| {
        counts[b] += 1;
    }

    switch (mode_int) {
        0, 1, 2 => {
            const result = try PHPArray.init(allocator);
            errdefer result.release(allocator);
            var i: usize = 0;
            while (i < 256) : (i += 1) {
                const count = counts[i];
                if (mode_int == 1 and count == 0) continue;
                if (mode_int == 2 and count != 0) continue;
                try result.set(allocator, .{ .integer = @intCast(i) }, Value.initInt(@intCast(count)));
            }
            return Value.initArray(result);
        },
        3, 4 => {
            var buf = try std.ArrayList(u8).initCapacity(allocator, 32);
            defer buf.deinit(allocator);
            var i: usize = 0;
            while (i < 256) : (i += 1) {
                const count = counts[i];
                if (mode_int == 3 and count == 0) continue;
                if (mode_int == 4 and count != 0) continue;
                try buf.append(allocator, @as(u8, @intCast(i)));
            }
            return Value.initString(try PHPString.init(allocator, buf.items));
        },
        else => {
            const result = try PHPArray.init(allocator);
            errdefer result.release(allocator);
            var i: usize = 0;
            while (i < 256) : (i += 1) {
                try result.set(allocator, .{ .integer = @intCast(i) }, Value.initInt(@intCast(counts[i])));
            }
            return Value.initArray(result);
        },
    }
}

/// urlencode - PHP URL 编码（空格→+，其他特殊字符→%XX）
pub fn php_urlencode(input: Value, allocator: Allocator) !Value {
    if (!input.isString()) {
        const s = try input.toString(allocator);
        defer s.deinit(allocator);
        return php_urlencode(Value.initString(s), allocator);
    }
    const data = input.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, data.len);
    defer result.deinit(allocator);
    const hex = "0123456789ABCDEF";
    for (data) |c| {
        if (std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.') {
            try result.append(allocator, c);
        } else if (c == ' ') {
            try result.append(allocator, '+');
        } else {
            try result.append(allocator, '%');
            try result.append(allocator, hex[c >> 4]);
            try result.append(allocator, hex[c & 0x0F]);
        }
    }
    const str = try PHPString.init(allocator, result.items);
    return Value.initString(str);
}

/// urldecode - PHP URL 解码（+→空格，%XX→字符）
pub fn php_urldecode(input: Value, allocator: Allocator) !Value {
    if (!input.isString()) return Value.initString(try PHPString.init(allocator, ""));
    const data = input.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, data.len);
    defer result.deinit(allocator);
    var i: usize = 0;
    while (i < data.len) {
        if (data[i] == '+') {
            try result.append(allocator, ' ');
            i += 1;
        } else if (data[i] == '%' and i + 2 < data.len) {
            const hi = std.fmt.charToDigit(data[i + 1], 16) catch {
                try result.append(allocator, '%');
                i += 1;
                continue;
            };
            const lo = std.fmt.charToDigit(data[i + 2], 16) catch {
                try result.append(allocator, '%');
                i += 1;
                continue;
            };
            try result.append(allocator, (hi << 4) | lo);
            i += 3;
        } else {
            try result.append(allocator, data[i]);
            i += 1;
        }
    }
    const str = try PHPString.init(allocator, result.items);
    return Value.initString(str);
}

/// rawurlencode - RFC 3986 编码（空格→%20）
pub fn php_rawurlencode(input: Value, allocator: Allocator) !Value {
    if (!input.isString()) {
        const s = try input.toString(allocator);
        defer s.deinit(allocator);
        return php_rawurlencode(Value.initString(s), allocator);
    }
    const data = input.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, data.len);
    defer result.deinit(allocator);
    const hex = "0123456789ABCDEF";
    for (data) |c| {
        if (std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.' or c == '~') {
            try result.append(allocator, c);
        } else {
            try result.append(allocator, '%');
            try result.append(allocator, hex[c >> 4]);
            try result.append(allocator, hex[c & 0x0F]);
        }
    }
    const str = try PHPString.init(allocator, result.items);
    return Value.initString(str);
}

/// rawurldecode - RFC 3986 解码（%XX→字符，+不转换）
pub fn php_rawurldecode(input: Value, allocator: Allocator) !Value {
    if (!input.isString()) return Value.initString(try PHPString.init(allocator, ""));
    const data = input.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, data.len);
    defer result.deinit(allocator);
    var i: usize = 0;
    while (i < data.len) {
        if (data[i] == '%' and i + 2 < data.len) {
            const hi = std.fmt.charToDigit(data[i + 1], 16) catch {
                try result.append(allocator, '%');
                i += 1;
                continue;
            };
            const lo = std.fmt.charToDigit(data[i + 2], 16) catch {
                try result.append(allocator, '%');
                i += 1;
                continue;
            };
            try result.append(allocator, (hi << 4) | lo);
            i += 3;
        } else {
            try result.append(allocator, data[i]);
            i += 1;
        }
    }
    const str = try PHPString.init(allocator, result.items);
    return Value.initString(str);
}

// ============================================================================
// 网络相关函数
// ============================================================================

/// gethostbyname - 通过主机名获取IP地址
pub fn php_getenv(name_val: Value, local_only: Value, allocator: Allocator) !Value {
    _ = local_only; // ★F-75：AOT 无 SAPI 环境分层 ⇒ 惰性，但必须接收（见 `php_class_exists` 上方说明）
    if (!name_val.isString()) return Value.initBool(false);

    const name = name_val.asString().data;
    // Zig 0.17: std.process.getEnvVarOwned 已移除，使用 std.c.getenv
    const name_z = allocator.dupeSentinel(u8, name, 0) catch return Value.initBool(false);
    defer allocator.free(name_z);
    const env_val = getEnvVar(name_z.ptr) orelse return Value.initBool(false);

    return Value.initString(try PHPString.init(allocator, env_val));
}

pub fn php_gethostbyname(hostname: Value, allocator: Allocator) !Value {
    if (!hostname.isString()) return Value.initString(try PHPString.init(allocator, ""));

    const name = hostname.asString().data;

    // 使用 C 库 getaddrinfo 进行 DNS 解析
    const c_name = try allocator.dupeSentinel(u8, name, 0);
    defer allocator.free(c_name);

    var hints: std.posix.addrinfo = std.mem.zeroes(std.posix.addrinfo);
    hints.family = std.posix.AF.INET;
    hints.socktype = std.posix.SOCK.STREAM;

    var result_ptr: ?*std.posix.addrinfo = null;
    const rc = std.c.getaddrinfo(c_name.ptr, null, &hints, &result_ptr);
    if (@intFromEnum(rc) != 0 or result_ptr == null) {
        return hostname;
    }
    defer std.c.freeaddrinfo(result_ptr.?);

    const addr_in: *const std.posix.sockaddr.in = @ptrCast(@alignCast(result_ptr.?.addr.?));
    const ip_bytes = @as(*const [4]u8, @ptrCast(&addr_in.addr));
    const ip_str = try std.fmt.allocPrint(allocator, "{}.{}.{}.{}", .{ ip_bytes[0], ip_bytes[1], ip_bytes[2], ip_bytes[3] });
    defer allocator.free(ip_str);

    const result = try PHPString.init(allocator, ip_str);
    return Value.initString(result);
}

/// gethostname - 获取主机名
pub fn php_gethostname(allocator: Allocator) !Value {
    var buf: [std.posix.HOST_NAME_MAX]u8 = undefined;
    const hostname = std.posix.gethostname(&buf) catch {
        return Value.initString(try PHPString.init(allocator, "localhost"));
    };
    const result = try PHPString.init(allocator, hostname);
    return Value.initString(result);
}

/// ip2long - 将IP地址转换为长整型
pub fn php_ip2long(ip: Value) !Value {
    if (!ip.isString()) return Value.initBool(false);
    const ip_str = ip.asString().data;

    // 解析IPv4地址
    var parts = std.mem.splitScalar(u8, ip_str, '.');
    var result: u32 = 0;
    var shift: u5 = 24;

    while (parts.next()) |part| {
        const num = std.fmt.parseInt(u8, part, 10) catch return Value.initBool(false);
        result |= @as(u32, num) << shift;
        if (shift > 0) shift -= 8 else break;
    }

    return Value.initInt(@as(i64, result));
}

/// long2ip - 将长整型转换为IP地址
pub fn php_long2ip(long: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b167）：形参名实测 **`$ip`**（不是模板变量名 `long`）。
    const ip_ok = requireNumParam("long2ip", 1, "ip", .int_param, long) orelse return Value.initNull();
    // ★下面的 `@intCast(… u32)` 对 >u32 域是越界转换（实测 `long2ip(4294967296)` PHP 给 '0.0.0.0'，即 32 位掩码）
    //   ——那是独立一枚面（工单 §104.3），本批只接类型拒，不改这里的取模语义。
    // ★F-127（R-229）：long2ip 按 32 位掩码（PHP 实测 2^32+1→'0.0.0.1'、-1→'255.255.255.255'）
    const ip_bits: u64 = @bitCast(ip_ok.toInt());
    const ip_num: u32 = @truncate(ip_bits);

    const a: u8 = @intCast((ip_num >> 24) & 0xFF);
    const b: u8 = @intCast((ip_num >> 16) & 0xFF);
    const c: u8 = @intCast((ip_num >> 8) & 0xFF);
    const d: u8 = @intCast(ip_num & 0xFF);

    const ip_str = try std.fmt.allocPrint(allocator, "{}.{}.{}.{}", .{ a, b, c, d });
    const result = try PHPString.init(allocator, ip_str);
    return Value.initString(result);
}

/// parse_url - 解析URL
pub fn php_parse_url(url: Value, allocator: Allocator) !Value {
    if (!url.isString()) return Value.initBool(false);

    const url_str = url.asString().data;
    const arr = try PHPArray.init(allocator);

    // 简单的URL解析
    var rest = url_str;

    // 解析scheme
    if (std.mem.indexOf(u8, rest, "://")) |scheme_end| {
        const scheme = rest[0..scheme_end];
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "scheme") }, Value.initString(try PHPString.init(allocator, scheme)));
        rest = rest[scheme_end + 3 ..];
    }

    // 解析host和port
    if (std.mem.indexOf(u8, rest, "/")) |host_end| {
        const host_port = rest[0..host_end];
        rest = rest[host_end..];

        if (std.mem.indexOf(u8, host_port, ":")) |port_pos| {
            const host = host_port[0..port_pos];
            const port = host_port[port_pos + 1 ..];
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "host") }, Value.initString(try PHPString.init(allocator, host)));
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "port") }, Value.initInt(std.fmt.parseInt(i64, port, 10) catch 0));
        } else {
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "host") }, Value.initString(try PHPString.init(allocator, host_port)));
        }
    }

    // 解析path
    if (std.mem.indexOf(u8, rest, "?")) |path_end| {
        const path = rest[0..path_end];
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "path") }, Value.initString(try PHPString.init(allocator, path)));
        rest = rest[path_end + 1 ..];

        // 解析query
        if (std.mem.indexOf(u8, rest, "#")) |query_end| {
            const query = rest[0..query_end];
            const fragment = rest[query_end + 1 ..];
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "query") }, Value.initString(try PHPString.init(allocator, query)));
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "fragment") }, Value.initString(try PHPString.init(allocator, fragment)));
        } else {
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "query") }, Value.initString(try PHPString.init(allocator, rest)));
        }
    } else {
        if (rest.len > 0) {
            try arr.set(allocator, .{ .string = try PHPString.init(allocator, "path") }, Value.initString(try PHPString.init(allocator, rest)));
        }
    }

    return Value.initArray(arr);
}

/// http_build_query - 生成 URL 编码的查询字符串
/// `http_build_query` 的分量编码（PHP 的 `application/x-www-form-urlencoded`：字母数字与 `-._~` 原样、空格成 `+`、其余 `%XX`）
/// ★F-71：从原字符串支里抽出来，是为了让**格式化后的浮点值**走同一支（旧写只有字符串编码 ⇒ `1.0E+19` 少转成 `%2B`）
fn urlEncodeQueryComponent(writer: anytype, bytes: []const u8) !void {
    for (bytes) |c| {
        if (std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.' or c == '~') {
            try writer.writeByte(c);
        } else if (c == ' ') {
            try writer.writeByte('+');
        } else {
            try writer.print("%{X:0>2}", .{c});
        }
    }
}

pub fn php_http_build_query(data: Value, allocator: Allocator) !Value {
    if (!data.isArray()) return Value.initString(try PHPString.init(allocator, ""));

    const arr = data.asArray();
    var aw = std.Io.Writer.Allocating.initCapacity(allocator, 64) catch return Value.initNull();
    defer aw.deinit();

    // ★F-71c（R-332）：键编码/嵌套形制对齐 PHP（RFC1738：空格⇒`+`、`[]`⇒`%5B%5D`、
    //   键段先按原文拼接再整体编码）；null 值与空数组值**整对省略**；bool false⇒`0`。
    var first = true;
    try httpBuildQueryInto(&aw.writer, arr, "", &first, allocator);

    return Value.initString(try PHPString.init(allocator, aw.written()));
}

/// http_build_query 递归体：prefix＝上层键段原文（未编码），根层为空串。
/// first 跨递归共享（& 分隔符的全局序），与 PHP 的 flats 收口同序。
fn httpBuildQueryInto(writer: anytype, arr: *PHPArray, prefix: []const u8, first: *bool, allocator: Allocator) !void {
    var iter = arr.elements.iterator();
    while (iter.next()) |entry| {
        // 键段原文：根层＝键本身；嵌套＝prefix[key]
        const key_raw: []const u8 = switch (entry.key_ptr.*) {
            .integer => |i| try std.fmt.allocPrint(allocator, "{d}", .{i}),
            .string => |s| s.data,
        };
        defer if (entry.key_ptr.* == .integer) allocator.free(key_raw);

        const seg: []const u8 = if (prefix.len == 0)
            key_raw
        else
            try std.fmt.allocPrint(allocator, "{s}[{s}]", .{ prefix, key_raw });
        defer if (prefix.len != 0) allocator.free(seg);

        const val = entry.value_ptr.*;
        // null／空数组 ⇒ 整对省略（PHP 实测）
        if (val.isNull()) continue;
        if (val.isArray()) {
            const sub = val.asArray();
            if (sub.count() == 0) continue;
            try httpBuildQueryInto(writer, sub, seg, first, allocator);
            continue;
        }

        if (!first.*) try writer.writeAll("&");
        first.* = false;

        try urlEncodeQueryComponent(writer, seg);
        try writer.writeAll("=");

        if (val.isString()) {
            try urlEncodeQueryComponent(writer, val.asString().data);
        } else if (val.isInt()) {
            try writer.print("{d}", .{val.asInt()});
        } else if (val.isFloat()) {
            // ★F-71（R-173b 加封）：m1 实测两处因，缺一不可 ——
            //   ① 旧写 `{d}` 是「最短位数直出」，而 PHP 的标量值走 `(string)` ＝**显示**口径（`a=1.0E+19`、`a=0.3`、`a=1.0E-5`）；
            //   ② 旧写**不做 URL 编码**，而 PHP 对值一律编码 ⇒ `+` 必须成 `%2B`（实测 `a=1.0E%2B19`）。
            //   ⇒ 先按显示口径格式化，再走与字符串同一支编码器（`E`/`.`/`-` 都属不编码集，只有 `+` 会被转义）。
            var fbuf: [64]u8 = undefined;
            try urlEncodeQueryComponent(writer, phpFormatFloat(&fbuf, val.asFloat()));
        } else if (val.isBool()) {
            // ★F-71c（R-332）：false⇒`0`（旧支只在 true 写 `1`，false 落成空值 ⇒ `f=` 与 PHP `f=0` 分歧）
            try writer.writeAll(if (val.asBool()) "1" else "0");
        }
    }
}

/// parse_str - 将查询字符串解析到变量中
pub fn php_parse_str(str: Value, result_arr: Value, allocator: Allocator) !Value {
    if (!str.isString()) return Value.initNull();

    const query = str.asString().data;
    // ★批次十五：第二参 by-ref＝**整体替换**（PHP 8.5.8 实测：旧键不残留、空串⇒空数组、
    //   非数组原值被替换）——旧实现复用传入数组合并 ⇒ 旧键残留；非 Ref 按值形新建数组
    //   不回写 ⇒ $out 滞留未定义。Ref 形释放旧值、直写 cell（IR ref_params 已登记）。
    const arr = try PHPArray.init(allocator);

    var pairs = std.mem.splitScalar(u8, query, '&');
    while (pairs.next()) |pair| {
        if (pair.len == 0) continue;
        if (std.mem.indexOf(u8, pair, "=")) |eq_pos| {
            const key = pair[0..eq_pos];
            const val = pair[eq_pos + 1 ..];
            const key_str = try PHPString.init(allocator, key);
            const val_str = try PHPString.init(allocator, val);
            try arr.set(allocator, .{ .string = key_str }, Value.initString(val_str));
        } else {
            const key_str = try PHPString.init(allocator, pair);
            const empty_str = try PHPString.init(allocator, "");
            try arr.set(allocator, .{ .string = key_str }, Value.initString(empty_str));
        }
    }

    if (result_arr.isRef()) {
        const cell = result_arr.asRef();
        cell.release(allocator);
        cell.* = Value.initArray(arr);
        return Value.initNull();
    }
    if (!result_arr.isArray()) {
        return Value.initArray(arr);
    }
    // 按值传入的数组（IR 未 make_ref 的边界，如字面量实参）：替换式返回新数组
    return Value.initArray(arr);
}

/// glob - 查找匹配模式的文件路径
pub fn php_glob(pattern: Value, allocator: Allocator) !Value {
    if (!pattern.isString()) return Value.initArray(try PHPArray.init(allocator));

    const pat = pattern.asString().data;
    const arr = try PHPArray.init(allocator);

    // 简单实现：使用目录遍历 + 模式匹配
    // 提取目录部分和文件名模式
    const dir_path = std.fs.path.dirname(pat) orelse ".";
    const file_pattern = std.fs.path.basename(pat);

    var dir = std.Io.Dir.cwd().openDir(getIo(), dir_path, .{ .iterate = true }) catch {
        return Value.initArray(arr);
    };
    defer dir.close(getIo());

    var dir_iter = dir.iterate();
    while (dir_iter.next(getIo()) catch null) |entry| {
        if (globMatch(file_pattern, entry.name)) {
            const full_path = if (std.mem.eql(u8, dir_path, "."))
                try PHPString.init(allocator, entry.name)
            else blk: {
                const path = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir_path, entry.name });
                defer allocator.free(path);
                break :blk try PHPString.init(allocator, path);
            };
            try arr.push(allocator, Value.initString(full_path));
        }
    }

    return Value.initArray(arr);
}

/// 简单的 glob 模式匹配（支持 * 和 ?）
fn globMatch(pattern: []const u8, name: []const u8) bool {
    var pi: usize = 0;
    var ni: usize = 0;
    var star_pi: ?usize = null;
    var star_ni: usize = 0;

    while (ni < name.len) {
        if (pi < pattern.len and (pattern[pi] == name[ni] or pattern[pi] == '?')) {
            pi += 1;
            ni += 1;
        } else if (pi < pattern.len and pattern[pi] == '*') {
            star_pi = pi;
            star_ni = ni;
            pi += 1;
        } else if (star_pi) |sp| {
            pi = sp + 1;
            star_ni += 1;
            ni = star_ni;
        } else {
            return false;
        }
    }

    while (pi < pattern.len and pattern[pi] == '*') pi += 1;
    return pi == pattern.len;
}

/// stripos - 不区分大小写查找子字符串位置
pub fn php_stripos(haystack: Value, needle: Value, offset: Value) !Value {
    // ★F-62f 接线：`$offset`（可选 int）⇒ 对象/array/坏串必须 TypeError（措辞 `must be of type int` 实测）
    const offset_ok = requireOptionalNumParam("stripos", 3, "offset", .int_param, offset) orelse return Value.initNull();
    if (!haystack.isString() or !needle.isString()) return Value.initBool(false);

    const hay = haystack.asString();
    const need = needle.asString();

    if (need.length == 0 or need.length > hay.length) return Value.initBool(false);

    const off_i = offset_ok.toInt();
    const start_idx: usize = blk: {
        if (off_i >= 0) {
            break :blk @intCast(@min(off_i, @as(i64, @intCast(hay.length))));
        }
        const abs_off: usize = @intCast(@min(-off_i, @as(i64, @intCast(hay.length))));
        break :blk hay.length - abs_off;
    };

    if (start_idx > hay.length or start_idx + need.length > hay.length) return Value.initBool(false);

    var i: usize = start_idx;
    while (i <= hay.length - need.length) : (i += 1) {
        var match = true;
        var j: usize = 0;
        while (j < need.length) : (j += 1) {
            if (std.ascii.toLower(hay.data[i + j]) != std.ascii.toLower(need.data[j])) {
                match = false;
                break;
            }
        }
        if (match) return Value.initInt(@intCast(i));
    }

    return Value.initBool(false);
}

/// strrpos - 查找子字符串最后出现的位置
pub fn php_strrpos(haystack: Value, needle: Value, offset: Value) !Value {
    // ★F-62f 接线：`$offset`（可选 int）⇒ 对象/array/坏串必须 TypeError（措辞 `must be of type int` 实测）
    const offset_ok = requireOptionalNumParam("strrpos", 3, "offset", .int_param, offset) orelse return Value.initNull();
    if (!haystack.isString() or !needle.isString()) return Value.initBool(false);

    const hay = haystack.asString();
    const need = needle.asString();

    if (need.length == 0 or need.length > hay.length) return Value.initBool(false);

    var last_pos: ?usize = null;
    const off_i = offset_ok.toInt();
    const start_idx: usize = blk: {
        if (off_i >= 0) {
            break :blk @intCast(@min(off_i, @as(i64, @intCast(hay.length))));
        }
        const abs_off: usize = @intCast(@min(-off_i, @as(i64, @intCast(hay.length))));
        break :blk hay.length - abs_off;
    };

    if (start_idx > hay.length or start_idx + need.length > hay.length) return Value.initBool(false);

    var i: usize = start_idx;
    while (i <= hay.length - need.length) : (i += 1) {
        if (std.mem.eql(u8, hay.data[i .. i + need.length], need.data)) {
            last_pos = i;
        }
    }

    if (last_pos) |pos| {
        return Value.initInt(@intCast(pos));
    }
    return Value.initBool(false);
}

pub fn php_strripos(haystack: Value, needle: Value, offset: Value) !Value {
    // ★F-62f 接线：`$offset`（可选 int）⇒ 对象/array/坏串必须 TypeError（措辞 `must be of type int` 实测）
    const offset_ok = requireOptionalNumParam("strripos", 3, "offset", .int_param, offset) orelse return Value.initNull();
    if (!haystack.isString() or !needle.isString()) return Value.initBool(false);

    const hay = haystack.asString();
    const need = needle.asString();

    if (need.length == 0 or need.length > hay.length) return Value.initBool(false);

    var last_pos: ?usize = null;
    const off_i = offset_ok.toInt();
    const start_idx: usize = blk: {
        if (off_i >= 0) {
            break :blk @intCast(@min(off_i, @as(i64, @intCast(hay.length))));
        }
        const abs_off: usize = @intCast(@min(-off_i, @as(i64, @intCast(hay.length))));
        break :blk hay.length - abs_off;
    };

    if (start_idx > hay.length or start_idx + need.length > hay.length) return Value.initBool(false);

    var i: usize = start_idx;
    while (i <= hay.length - need.length) : (i += 1) {
        var match = true;
        var j: usize = 0;
        while (j < need.length) : (j += 1) {
            if (std.ascii.toLower(hay.data[i + j]) != std.ascii.toLower(need.data[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            last_pos = i;
        }
    }

    if (last_pos) |pos| {
        return Value.initInt(@intCast(pos));
    }
    return Value.initBool(false);
}

/// number_format - 格式化数字
/// ★R-179（工单 §72.5／§75）＝按**律 D′** 重写，弃旧的 i64 缩放塔。旧实现的两处硬伤一并结掉：
///   ①`@intCast(@max(0, dv.toInt()))` 把负 `decimals` 直接归零 ⇒ 门 NFM 那 22 枚 `stage_judgment` 红的直接原因；
///   ②`pow10 *= 10`（`dec>=19` 即溢出）与**无守卫**的 `@intFromFloat(num * pow10)`（越过 i64 是未定义）＝§56／F-76 的账。
/// php-src `_php_math_number_format_ex` 的顺序（照抄，不改语义）：
///   ①`value < 0` ⇒ 剥负号（★对 `-INF` 同样先取反）
///   ②`rounded = _php_math_round(|value|, dec, PHP_ROUND_HALF_UP)`——★`dec` 的**负号保留**（舍入按十位/百位…）
///   ③`rounded == 0` ⇒ 丢负号（`-0.0` 在此归一成 `+0.0`，否则 `%.{dec}f` 会把负号带进数字串）
///   ④`%.*F` **精确展开**——★打印与分节的位数用 `max(dec, 0)`
///   ⑤展开串首字符非数字（`inf`／`nan`）⇒ **原样返回**，既不分节也不补负号
///   ⑥整数段从右每 3 位插千分位；小数段＝`decimal_separator` 原串＋dec 位（★`""` ⇒ 不插点但位数照留）
/// `dec < 0` 再分两支（c075 445 行×3 形＋c099 252 行＝**697 例零失配**，见 §75）：
///   **D′-1** `|value| > PHP_INT_MAX` ⇒ 该量级 `_php_math_round` 走放弃支 ⇒ 输出该 double 的**精确整数展开**；
///   **D′-2** 否则 ⇒ 对 `value` 的**精确值**按 `10^|dec|` 做**十进制半进位（远离零）**再补零。
/// ★分隔符按**整串**输出（旧实现只取首字节、且把显式 `""` 当默认值 ⇒ `sep2`/`sep4` 那类形制必错）。
pub fn php_number_format(number: Value, decimals: Value, dec_point: Value, thousands_sep: Value, allocator: Allocator) !Value {
    // ★F-62（R-172）：`$num` 的 TypeError 文本实测是 `int|float`，而它的 Passing-null 文本实测是 `float`
    //   （`number_format(): Passing null to parameter #1 ($num) of type float is deprecated`）⇒ 用 `requireNumParamAs` 显式给出。
    //   `$decimals` 是 int；`$decimal_separator`／`$thousands_separator` 期望 `?string`（实测措辞）⇒ 与 bc 族同属
    //   「stringable／nullable-string」那道，另立 F-62b，本轮不碰 #3/#4。
    const nv = requireNumParamAs("number_format", 1, "num", .num_param, number, "float") orelse return Value.initNull();
    const dv = requireOptionalNumParam("number_format", 2, "decimals", .int_param, decimals) orelse return Value.initNull();
    const dp: []const u8 = if (dec_point.isString()) dec_point.asString().data else ".";
    const ts: []const u8 = if (thousands_sep.isString()) thousands_sep.asString().data else ",";

    var value = nv.toFloat();
    var is_negative = false;
    if (value < 0.0) { // ①
        is_negative = true;
        value = -value;
    }
    // ★`-0.0` 与 `+0.0` 相等 ⇒ ①的取反对它不执行，`%.{k}f` 会把负号带进数字串（真值资产里 `-0.0@-1` 实测期望 `0`）
    //   ⇒ 一律在此归一，两支展开都只吃非负值。
    const mag: f64 = if (value == 0.0) 0.0 else value;

    // ★`decimals` 是 `zend_long`，而 `_php_math_round` 的 places 与 `%.*F` 的精度在 PHP 侧都是 C `int`
    //   ⇒ 做**饱和**转换（与 `phpMathRoundValue` 自带的 `minInt(i32)+1` clamp 同口径）。
    //   越界 `decimals` 的耗时与缓冲上界另属 **F-65**（本批只保证不再越 i64／不再无守卫转整）。
    const d64 = dv.toInt();
    const dec_in: i32 = if (d64 > std.math.maxInt(i32))
        std.math.maxInt(i32)
    else if (d64 < std.math.minInt(i32) + 1)
        std.math.minInt(i32) + 1
    else
        @intCast(d64);
    const dec: usize = if (dec_in > 0) @intCast(dec_in) else 0; // ④打印位数＝max(dec,0)

    // ★F-65（R-329）：前置尺寸守卫——投影输出字节数超 PHPString 上限时，直接与
    //   `PHPString.init` 同路同消息（`ERROR: String too large …` + `error.StringTooLarge`）；
    //   修前 `dec=i32max` 会在下方 2GB 缓冲分配/snprintf 路径吐不透明 `error.InvalidArgument`。
    //   投影＝dec + 整数段上界 309（DBL_MAX 位数）+ 千分位分隔符（**只**作用于整数段，
    //   `每 3 位 1 枚`）+ 符号/小数点余量 ⇒ 禁把 dec 算进分隔符（75M–100M 档会被误杀）。
    //   阈值与 PHP 的 `memory_limit` fatal（默认 128MB）同区不同值——环境差异已登记，措辞不对齐（§四.3）。
    {
        const projected = dec +| 309 +| (309 / 3) +| 8;
        if (projected > PHPSTRING_MAX_BYTES) {
            std.debug.print("ERROR: String too large: {d} bytes ({d} MB)\n", .{ projected, projected / (1024 * 1024) });
            return error.StringTooLarge;
        }
    }

    const rounded = blk: { const r = phpMathRoundValue(mag, dec_in, ROUND_MODE_HALF_UP); break :blk if (r == 0.0) 0.0 else r; }; // ②③
    if (rounded == 0.0) is_negative = false; // ③

    // ★任何 double 的精确十进制展开最多 1074 位小数（最小非规格化数＝`2^-1074`），整数段最多 309 位
    //   （`DBL_MAX < 2^1024 < 10^309`）⇒ 这两个**导出**上界取代旧实现里凭空的定长缓冲。
    const exact_frac: usize = 1074;
    const int_cap: usize = 512;
    // ★D′-1 的分界＝`PHP_INT_MAX`。它本身不可被 f64 精确表示，`@floatFromInt` 会**进到 `2^63`**，
    //   而 PHP 侧比较也在 `zend_long` 溢出点上做 ⇒ 与已证的 Python 模型（`float(PHP_INT_MAX)`）逐位同口径。
    const php_int_max: f64 = @floatFromInt(std.math.maxInt(i64));
    const exact_expansion = dec_in < 0 and mag <= php_int_max; // ★D′-2 的开关（**不能**用「精度==1074」判别：`dec==1074` 会误触发）
    const bnd: usize = if (dec_in < 0) @intCast(-@as(i64, dec_in)) else 0; // 仅 D′ 支有意义

    var raw = try allocator.alloc(u8, dec +| bnd +| exact_frac +| int_cap +| 16);
    defer allocator.free(raw);
    var fmt_buf: [64:0]u8 = undefined;

    // 展开成十进制串：D′-2 需要**精确值**的全部整数位（小数位只在整数段右侧的半进位判定里起作用），
    // 其余三支（`dec>=0`、D′-1、inf/nan）都直接吃 `%.*F` 对 `rounded` 的输出。
    const prec: usize = if (exact_expansion) exact_frac else dec;
    {
        const fs = std.fmt.bufPrint(&fmt_buf, "%.{d}f", .{prec}) catch return error.InvalidArgument;
        fmt_buf[fs.len] = 0;
        const n = snprintf(raw.ptr, raw.len, &fmt_buf, if (exact_expansion) mag else rounded);
        if (n <= 0 or @as(usize, @intCast(n)) >= raw.len) return error.InvalidArgument; // ★上界算错＝宁可报错，禁静默截断
        raw.len = @intCast(n);
    }
    // ⑤inf／nan：首字符非数字 ⇒ 原样返回（PHP 此处既不分节也不补负号）
    if (!(raw[0] >= '0' and raw[0] <= '9')) return Value.initString(try PHPString.init(allocator, raw));

    // ★`%.0f` 与 inf/nan 的输出**没有小数点** ⇒ 必须 `orelse raw.len`，写 `.?` 会当场 panic
    const dot = std.mem.indexOfScalar(u8, raw, '.') orelse raw.len;
    var digits: []const u8 = raw[0..dot]; // 整数段
    var frac: []const u8 = if (dot < raw.len) raw[dot + 1 ..] else "";

    // ★D′-2 的结果缓冲**必须活到函数尾**：`digits` 会指回它。写成块内 `defer free` 会让装配阶段读已释放内存
    //   （实测 `number_format(1.234,-1)` 出 `^@`、`(-50,-2)` 出 `----`、`(995,-1)` 出 `^@,^@^@^@`＝典型 use-after-free）。
    var d2_buf: ?[]u8 = null;
    defer if (d2_buf) |b| allocator.free(b);

    if (exact_expansion) { // ★D′-2 分支：对精确值按 `10^bnd` 做十进制半进位（远离零）
        // 1) 丢弃段与阈值「'5'＋(bnd-1)×'0'」逐位比：缺位视作前导零。
        var up = false;
        var i: usize = 0;
        while (i < bnd and !up) : (i += 1) {
            const pos: isize = @as(isize, @intCast(digits.len)) - @as(isize, @intCast(bnd)) + @as(isize, @intCast(i));
            const td: u8 = if (pos < 0) '0' else digits[@intCast(pos)];
            const hd: u8 = if (i == 0) '5' else '0';
            if (td > hd) {
                up = true;
            } else if (td < hd) {
                break; // ★低于阈值必须停：漏掉这步会把 `0.11@-2` 判成进位（工单 §72.4 实测 got=100）
            } else if (i + 1 == bnd) {
                up = true; // 与阈值逐位全等＝正好一半 ⇒ HALF_UP 远离零
            }
        }
        // 2) 保留段 ＋1（含溢出）。★**绝不剥前导零**：溢出时那些 0 是有效位数
        //    （`995@-1` ⇒ 保留段 "99"＋1 ⇒ "00" 且进位 ⇒ 结果必须是 "1"+"00"+一个零＝"1000"；
        //     旧草稿剥了前导零 ⇒ got="10"，是 §75 里 Zig 等价器抓到的第一条）。
        const keep_len = if (digits.len > bnd) digits.len - bnd else 0;
        var acc = try allocator.alloc(u8, keep_len); // ★独立缓冲：与下面写 `keep` 的位置错开，禁就地覆写
        defer allocator.free(acc);
        @memcpy(acc, digits[0..keep_len]);
        var carry: u8 = if (up) 1 else 0;
        var q: usize = keep_len;
        while (q > 0 and carry == 1) {
            q -= 1;
            var d: u16 = @as(u16, acc[q]) - '0' + 1;
            if (d >= 10) {
                d -= 10;
                carry = 1;
            } else {
                carry = 0;
            }
            acc[q] = '0' + @as(u8, @intCast(d));
        }
        const keep = try allocator.alloc(u8, digits.len +| bnd +| 4);
        d2_buf = keep; // ★登记到函数作用域，随函数结束统一释放
        var kl: usize = 0;
        if (carry == 1) {
            keep[kl] = '1';
            kl += 1;
        }
        @memcpy(keep[kl .. kl + keep_len], acc);
        kl += keep_len;
        if (kl == 0) {
            keep[0] = '0';
            kl = 1;
            is_negative = false; // ★D′-3：结果为零 ⇒ 丢负号（实测 `number_format(-50,-3)`⇒`0`；`(-50,-2)` 是 `-100` 不算零）
        } else {
            var z: usize = 0;
            while (z < bnd) : (z += 1) {
                keep[kl] = '0';
                kl += 1;
            }
        }
        digits = keep[0..kl];
        frac = ""; // `dec` 已归 0 ⇒ 无小数段
    } else {
        frac = frac[0..@min(dec, frac.len)]; // `%.*F` 本就该给满 dec 位；这一刀只是防御，不改语义
    }

    // ⑥装配：符号 ＋ 分节整数段 ＋（有小数位时）`decimal_separator` 原串 ＋ 小数位
    const groups = if (digits.len > 3) (digits.len - 1) / 3 else 0;
    var total: usize = (if (is_negative) @as(usize, 1) else 0) +| digits.len +| groups *| ts.len;
    if (frac.len > 0) total +|= dp.len +| frac.len;

    var out = std.Io.Writer.Allocating.initCapacity(allocator, total +| 4) catch return error.OutOfMemory;
    defer out.deinit(); // ★与旧实现同一对 `defer`＋`return PHPString.init(..., written())` 形状（init 会拷贝，安全）
    if (is_negative) try out.writer.writeByte('-');
    for (digits, 0..) |ch, idx| {
        if (idx > 0 and (digits.len - idx) % 3 == 0 and ts.len > 0) try out.writer.writeAll(ts);
        try out.writer.writeByte(ch);
    }
    if (frac.len > 0) {
        try out.writer.writeAll(dp);
        try out.writer.writeAll(frac);
    }

    return Value.initString(try PHPString.init(allocator, out.written()));
}

/// nl2br - 将换行符转换为HTML <br>标签
pub fn php_nl2br(str: Value, is_xhtml: Value, allocator: Allocator) !Value {
    if (!str.isString()) return str;

    const php_str = str.asString();
    const tag = if (is_xhtml.toBool()) "<br />" else "<br>";

    // 计算需要的空间
    var count: usize = 0;
    for (php_str.data) |c| {
        if (c == '\n') count += 1;
    }

    const new_len = php_str.length + count * tag.len;
    const buffer = try allocator.alloc(u8, new_len);
    errdefer allocator.free(buffer);

    var write_pos: usize = 0;
    for (php_str.data) |c| {
        if (c == '\n') {
            @memcpy(buffer[write_pos .. write_pos + tag.len], tag);
            write_pos += tag.len;
        }
        buffer[write_pos] = c;
        write_pos += 1;
    }

    const result = try PHPString.init(allocator, buffer[0..write_pos]);
    allocator.free(buffer);
    return Value.initString(result);
}

pub fn php_chunk_split(body: Value, chunklen: Value, end: Value, allocator: Allocator) !Value {
    // ★F-62f 接线：`$length`（可选 int，PHP 侧默认 76）⇒ 对象/array/坏串必须 TypeError（实测 `Argument #2 ($length) must be of type int`）
    const chunklen_ok = requireOptionalNumParam("chunk_split", 2, "length", .int_param, chunklen) orelse return Value.initNull();
    const body_str = if (body.isString()) body.asString().data else "";
    const clen_i: i64 = if (chunklen_ok.isNull()) 76 else chunklen_ok.toInt();
    if (clen_i <= 0) {
        return throwThrowable("ValueError", "chunk_split(): Argument #2 ($length) must be greater than 0", allocator);
    }
    const clen: usize = @intCast(clen_i);
    const end_str = if (end.isString()) end.asString().data else "\r\n";

    const num_chunks = (body_str.len + clen - 1) / clen;
    const result_len = body_str.len + num_chunks * end_str.len;
    const result = try allocator.alloc(u8, result_len);
    defer allocator.free(result);

    var src_i: usize = 0;
    var dst_i: usize = 0;
    while (src_i < body_str.len) {
        const chunk_end = @min(src_i + clen, body_str.len);
        @memcpy(result[dst_i .. dst_i + (chunk_end - src_i)], body_str[src_i..chunk_end]);
        dst_i += chunk_end - src_i;
        @memcpy(result[dst_i .. dst_i + end_str.len], end_str);
        dst_i += end_str.len;
        src_i = chunk_end;
    }

    const php_str = try PHPString.init(allocator, result[0..dst_i]);
    return Value.initString(php_str);
}

/// strip_tags - 移除HTML和PHP标签
pub fn php_strip_tags(str: Value, allowed_tags: Value, allocator: Allocator) !Value {
    _ = allowed_tags;
    if (!str.isString()) return str;

    const php_str = str.asString();
    const buffer = try allocator.alloc(u8, php_str.length);
    errdefer allocator.free(buffer);

    var write_pos: usize = 0;
    var in_tag = false;

    for (php_str.data) |c| {
        if (c == '<') {
            in_tag = true;
        } else if (c == '>') {
            in_tag = false;
        } else if (!in_tag) {
            buffer[write_pos] = c;
            write_pos += 1;
        }
    }

    const result = try PHPString.init(allocator, buffer[0..write_pos]);
    allocator.free(buffer);
    return Value.initString(result);
}

/// strval - 获取变量的字符串值
pub fn php_strval(val: Value, allocator: Allocator) !Value {
    const str = try val.toString(allocator);
    return Value.initString(str);
}

/// gettype - 获取变量的类型
pub fn php_gettype(val: Value, allocator: Allocator) !Value {
    const type_str = if (val.isNull())
        "NULL"
    else if (val.isBool())
        "boolean"
    else if (val.isInt())
        "integer"
    else if (val.isFloat())
        "double"
    else if (val.isString())
        "string"
    else if (val.isArray())
        "array"
    else if (Value_isObject(val) or val.isFunction())
        "object"
    else if (val.isResource())
        "resource"
    else if (val.hasResourceType())
        // ★F-180：PHP 8 对**已关闭**资源给 `resource (closed)`（fclose/closedir 之后）；
        //   旧写落 "unknown type"。类型位判定（同 retain/release 的 F-180 口径）。
        "resource (closed)"
    else
        "unknown type";

    const result = try PHPString.init(allocator, type_str);
    return Value.initString(result);
}

/// settype - 改变变量的类型
/// PHP签名: settype(mixed &$var, string $type): bool
/// 第一个参数是引用，直接修改变量的值
pub fn php_settype(var_ref: Value, type_val: Value, allocator: Allocator) !Value {
    // ★批次十四④：非法 $type（非字符串/未知类型名）⇒ 可捕获 ValueError
    //   （PHP 8.5.8 实测同文案同出口；旧静默 false 缺口），变量保持原值。
    if (!type_val.isString()) {
        return throwThrowable("ValueError", "settype(): Argument #2 ($type) must be a valid type", allocator);
    }

    // 检查第一个参数是否是引用
    if (!var_ref.isRef()) {
        return Value.initBool(false);
    }

    const ptr = var_ref.asRef();
    const type_name = type_val.asString().data;

    // 保存原始值用于转换
    const old_val = ptr.*;

    // 根据类型名进行转换
    const new_val = if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean"))
        Value.initBool(old_val.toBool())
    else if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer"))
        blk: {
            // ★F-77：对象 ⇒ Warning＋1，且 `settype` **仍返回 true**（实测）
            const probe = derefForNumberProbe(old_val);
            if (Value_isObject(probe)) {
                emitObjectToNumberWarning(probe, "int");
                break :blk Value.initInt(1);
            }
            warnFloatToIntNotRepresentable(old_val); // ★F-69 显式站点（实测 `settype($v,"int")` 越界 ⇒ Warn＋回绕值）
            break :blk Value.initInt(old_val.toInt());
        }
    else if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double"))
        blk: {
            const probe = derefForNumberProbe(old_val);
            if (Value_isObject(probe)) {
                emitObjectToNumberWarning(probe, "float");
                break :blk Value.initFloat(1.0);
            }
            break :blk Value.initFloat(old_val.toFloat());
        }
    else if (std.mem.eql(u8, type_name, "string")) blk: {
        const str = try old_val.toString(allocator);
        break :blk Value.initString(str);
    } else if (std.mem.eql(u8, type_name, "array"))
        try php_cast_array(old_val)
    else if (std.mem.eql(u8, type_name, "object"))
        try php_cast_object(old_val)
    else if (std.mem.eql(u8, type_name, "null"))
        Value.initNull()
    else
        // ★批次十四④：未知类型名 ⇒ 可捕获 ValueError（变量保持原值）
        return throwThrowable("ValueError", "settype(): Argument #2 ($type) must be a valid type", allocator);

    // 释放旧值，设置新值
    ptr.release(allocator);
    _ = new_val.retain();
    ptr.* = new_val;

    // 返回 true 表示成功
    return Value.initBool(true);
}

// ============================================================================
// 文件函数
// ============================================================================

/// file_get_contents - 读取文件内容
/// file_exists - 检查文件是否存在
pub fn php_file_exists(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);

    const path = filename.asString().data;
    std.Io.Dir.cwd().access(getIo(), path, .{}) catch {
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// is_file - 检查是否是普通文件
/// mkdir - 创建目录
pub fn php_mkdir(dirname: Value, permissions: Value, recursive: Value) !Value {
    if (!dirname.isString()) return Value.initBool(false);

    const path = dirname.asString().data;
    // Zig 0.16 的 Permissions 是 `enum(mode_t)`（非穷尽）⇒ 用 @enumFromInt
    const mode_bits: std.posix.mode_t = if (permissions.isInt()) @intCast(permissions.asInt() & 0o777) else 0o777;
    const mode: std.Io.Dir.Permissions = @enumFromInt(mode_bits);
    const is_recursive = if (recursive.isBool()) recursive.asBool() else false;

    // ★R-274：原实现用 `sliceAsBytes(x) ++ &[_]u8{0}` 拼运行时 C 串 ⇒ 编译期即报
    //   「slice being concatenated must be comptime-known」；改走 Zig 0.16 的 Dir API。
    if (is_recursive) {
        std.Io.Dir.cwd().createDirPath(getIo(), path) catch |err| {
            var mbuf: [1024]u8 = undefined;
            const msg = std.fmt.bufPrint(&mbuf, "mkdir(): {s}", .{fsErrText(err)}) catch "";
            emitWarning(msg);
            return Value.initBool(false);
        };
    } else {
        std.Io.Dir.cwd().createDir(getIo(), path, mode) catch |err| {
            var mbuf: [1024]u8 = undefined;
            const msg = std.fmt.bufPrint(&mbuf, "mkdir(): {s}", .{fsErrText(err)}) catch "";
            emitWarning(msg);
            return Value.initBool(false);
        };
    }

    return Value.initBool(true);
}

/// rmdir - 删除目录
pub fn php_rmdir(dirname: Value) !Value {
    if (!dirname.isString()) return Value.initBool(false);

    const path = dirname.asString().data;
    std.Io.Dir.cwd().deleteDir(getIo(), path) catch |err| {
        var mbuf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "rmdir({s}): {s}", .{ path, fsErrText(err) }) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// rename - 重命名文件
pub fn php_rename(oldname: Value, newname: Value) !Value {
    if (!oldname.isString() or !newname.isString()) return Value.initBool(false);

    const old_path = oldname.asString().data;
    const new_path = newname.asString().data;

    std.Io.Dir.cwd().rename(old_path, std.Io.Dir.cwd(), new_path, getIo()) catch |err| {
        var mbuf: [1024]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "rename({s},{s}): {s}", .{ old_path, new_path, fsErrText(err) }) catch "";
        emitWarning(msg);
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// copy - 拷贝文件
pub fn php_copy(source: Value, dest: Value) !Value {
    if (!source.isString() or !dest.isString()) return Value.initBool(false);

    const source_path = source.asString().data;
    const dest_path = dest.asString().data;

    std.Io.Dir.cwd().copyFile(source_path, std.Io.Dir.cwd(), dest_path, getIo(), .{}) catch |err| {
        warnPf("copy", source_path, err);
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// basename - 返回路径中的文件名部分
pub fn php_basename(path: Value, suffix: Value, allocator: Allocator) !Value {
    if (!path.isString()) return Value.initString(try PHPString.init(allocator, ""));

    const path_str = path.asString().data;
    const base = std.fs.path.basename(path_str);
    // PHP basename 支持可选 suffix 参数：如果文件名以 suffix 结尾则去除
    if (suffix.isString()) {
        const suf = suffix.asString().data;
        if (suf.len > 0 and base.len > suf.len and std.mem.endsWith(u8, base, suf)) {
            return Value.initString(try PHPString.init(allocator, base[0 .. base.len - suf.len]));
        }
    }
    return Value.initString(try PHPString.init(allocator, base));
}

/// dirname - 返回路径中的目录部分，支持 levels 参数
pub fn php_dirname(path: Value, levels: Value, allocator: Allocator) !Value {
    if (!path.isString()) return Value.initString(try PHPString.init(allocator, ""));

    var path_str: []const u8 = path.asString().data;
    var lvl: u32 = 1;
    if (levels.isInt()) {
        const v = levels.asInt();
        if (v > 1) lvl = @intCast(v);
    }
    var i: u32 = 0;
    while (i < lvl) : (i += 1) {
        if (std.fs.path.dirname(path_str)) |dir| {
            path_str = dir;
        } else {
            path_str = ".";
            break;
        }
    }
    const result = try PHPString.init(allocator, path_str);
    return Value.initString(result);
}

/// getmypid - 获取当前进程ID
pub fn php_getmypid() Value {
    const pid = std.posix.system.getpid();
    return Value.initInt(@intCast(pid));
}

/// getmygid - 获取当前进程组ID
const c_getgid = @extern(*const fn () callconv(.c) u32, .{ .name = "getgid" });
pub fn php_getmygid() Value {
    return Value.initInt(@intCast(c_getgid()));
}

/// phpversion - 返回PHP版本号
pub fn php_phpversion(allocator: Allocator) !Value {
    return Value.initString(try PHPString.init(allocator, PHP_VER_STRING));
}

/// extension_loaded - 检查扩展是否加载
pub fn php_extension_loaded(name: Value) Value {
    if (!name.isString()) return Value.initBool(false);
    const ext = name.asString().data;
    // AOT 模式下模拟核心扩展已加载
    const core_exts = [_][]const u8{
        "Core",  "core",     "standard",  "date", "pcre", "json",
        "ctype", "mbstring", "tokenizer", "SPL",  "spl",
    };
    for (core_exts) |e| {
        if (std.mem.eql(u8, ext, e)) return Value.initBool(true);
    }
    return Value.initBool(false);
}

/// get_loaded_extensions - 返回已加载的扩展列表
pub fn php_get_loaded_extensions(allocator: Allocator) !Value {
    const arr = try PHPArray.init(allocator);
    const exts = [_][]const u8{ "Core", "standard", "date", "pcre", "json", "ctype", "mbstring", "SPL" };
    for (exts) |e| {
        // ★批次十七①：PHPArray 无 pushValue（门径 push/pushRaw :2842）——直调 get_loaded_extensions 此前同样编不过，登记后懒分析暴露。
        try arr.push(allocator, Value.initString(try PHPString.init(allocator, e)));
    }
    return Value.initArray(arr);
}

/// touch - 设置文件的访问和修改时间
pub fn php_touch(filename: Value) !Value {
    if (!filename.isString()) return Value.initBool(false);
    const path = filename.asString().data;

    // 如果文件不存在，创建空文件
    const file = std.Io.Dir.cwd().createFile(getIo(), path, .{ .exclusive = false, .truncate = false }) catch {
        return Value.initBool(false);
    };
    file.close(getIo());
    return Value.initBool(true);
}

/// pathinfo - 返回文件路径的信息
pub fn php_pathinfo(path_val: Value, option: Value, allocator: Allocator) !Value {
    // ★F-62f 第三批：可选 #2 ($flags)，Foo ⇒ TypeError；null/省略 ⇒ 默认 PATHINFO_ALL(15)
    //   （本运行时无法区分“省略”与显式 null ⇒ 取常用默认；显式 null 的 ""+Deprecated 已登记缺口）
    const option_ok = requireOptionalNumParam("pathinfo", 2, "flags", .int_param, option) orelse return Value.initNull();
    if (!path_val.isString()) return Value.initString(try PHPString.init(allocator, ""));

    const path = path_val.asString().data;
    const opt = if (option_ok.isNull()) 15 else option_ok.toInt();

    // PATHINFO_DIRNAME = 1, PATHINFO_BASENAME = 2, PATHINFO_EXTENSION = 4, PATHINFO_FILENAME = 8
    const dir = std.fs.path.dirname(path) orelse ".";
    const base = std.fs.path.basename(path);
    const ext_with_dot = std.fs.path.extension(path);
    const ext = if (ext_with_dot.len > 0) ext_with_dot[1..] else "";
    const filename = if (ext_with_dot.len > 0) base[0 .. base.len - ext_with_dot.len] else base;

    // ★F-62f 第三批：flags 语义实测（c210 矩阵）：15 或 0 ⇒ 关联数组；否则取**最低置位**的 1/2/4/8；
    //   未知位（16）⇒ ""；组合（3/7/-1）⇒ dirname。
    //   ★0 归 array 是**调用约定折衷**：发射器把省略的 #2 填成 int(0)，无法与显式 0 区分；
    //     省略形（`pathinfo($p)`）远多于显式 0，故取默认语义（显式 0 的 "" 已登记缺口）。
    if (opt == 15 or opt == 0) {
        const arr = try PHPArray.init(allocator);
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "dirname") }, Value.initString(try PHPString.init(allocator, dir)));
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "basename") }, Value.initString(try PHPString.init(allocator, base)));
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "extension") }, Value.initString(try PHPString.init(allocator, ext)));
        try arr.set(allocator, .{ .string = try PHPString.init(allocator, "filename") }, Value.initString(try PHPString.init(allocator, filename)));
        return Value.initArray(arr);
    }
    if ((opt & 1) != 0) return Value.initString(try PHPString.init(allocator, dir));
    if ((opt & 2) != 0) return Value.initString(try PHPString.init(allocator, base));
    if ((opt & 4) != 0) return Value.initString(try PHPString.init(allocator, ext));
    if ((opt & 8) != 0) return Value.initString(try PHPString.init(allocator, filename));
    return Value.initString(try PHPString.init(allocator, ""));
}

/// realpath - 返回规范化的绝对路径名
pub fn php_realpath(path_val: Value, allocator: Allocator) !Value {
    if (!path_val.isString()) return Value.initBool(false);
    const path = path_val.asString().data;

    // ★批次十七①：dupeSentinel 门径是 3 参（:7324 等同族），旧多传一枚 0 ⇒ 直调 realpath 此前同样编不过，登记后懒分析暴露。
    const c_path = try allocator.dupeSentinel(u8, path, 0);
    defer allocator.free(c_path);

    var buf: [std.posix.PATH_MAX]u8 = undefined;
    const resolved = std.c.realpath(c_path.ptr, &buf);
    if (resolved == null) return Value.initBool(false);

    const result_str = std.mem.span(resolved.?);
    return Value.initString(try PHPString.init(allocator, result_str));
}

/// tempnam - 创建唯一的临时文件名
pub fn php_tempnam(dir: Value, prefix: Value, allocator: Allocator) !Value {
    const dir_str = if (dir.isString()) dir.asString().data else "/tmp";
    const prefix_str = if (prefix.isString()) prefix.asString().data else "tmp";

    // 生成唯一文件名
    const ts = milliTimestamp();
    const pid = std.posix.system.getpid();
    const name = try std.fmt.allocPrint(allocator, "{s}/{s}{d}_{d}.tmp", .{ dir_str, prefix_str, pid, ts });
    defer allocator.free(name);

    return Value.initString(try PHPString.init(allocator, name));
}

/// debug_zval_dump - 输出变量的 zval 信息
pub fn php_debug_zval_dump(value: Value) !Value {
    if (value.isString()) {
        const s = value.asString();
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "string({d}) \"{s}\" refcount(1)\n", .{ s.length, s.data }) catch "string(?)\n";
        fileWriteAll(1, msg);
    } else if (value.isInt()) {
        var buf: [64]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "int({d})\n", .{value.asInt()}) catch "int(?)\n";
        fileWriteAll(1, msg);
    } else if (value.isFloat()) {
        // ★F-71（R-173b）：`debug_zval_dump` 与 `var_dump` 同属**序列化**口径（实测 `debug_zval_dump(1e19)`＝`float(1.0E+19)`、
        //   `debug_zval_dump(0.1+0.2)`＝`float(0.30000000000000004)`）⇒ 接同一核心，不补 `.0`、大写 E。
        //   ★本函数的**数组体与 refcount 面**整体不忠实（数组只印 `refcount(1){}`）⇒ 另登 F-71b，本批不设臂不顺手改。
        var num: [64]u8 = undefined;
        const fs = phpFormatFloatSerialize(&num, value.asFloat(), false, true);
        var buf: [96]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "float({s})\n", .{fs}) catch "float(?)\n";
        fileWriteAll(1, msg);
    } else if (value.isBool()) {
        fileWriteAll(1, if (value.asBool()) "bool(true)\n" else "bool(false)\n");
    } else if (value.isNull()) {
        fileWriteAll(1, "NULL\n");
    } else if (value.isArray()) {
        debugZvalDumpArray(value.asArray(), 0);
    } else {
        fileWriteAll(1, "unknown type\n");
    }
    return Value.initNull();
}

/// ★F-71b（R-332）：`debug_zval_dump` 的数组体——元素枚举／键形制／packed 标注／嵌套递归全对齐 PHP 8.5.8 实测。
///   refcount 口径：顶层（indent=0，只能由本函数入口到达）恒 3＝变量实参主流形；嵌套恒 1。
///   字符串元素尾标恒 `refcount(1)`：PHP 的 `interned` 尾标是 interned-string 池实现细节
///   （实测同长内容两形互歧："dynamic" interned vs "in_func" refcount(1)），语义不可复刻 ⇒ 登记豁免。
///   自引用／深嵌套防御：深度 >16 印 PHP 同款 `*RECURSION*` 字眼收口（防栈溢出）。
fn debugZvalDumpArray(arr: *PHPArray, indent: usize) void {
    var nbuf: [96]u8 = undefined;
    // 缩进串（每级 2 空格）
    var ibuf: [40]u8 = undefined;
    const pad_len = @min(indent * 2, ibuf.len);
    @memset(ibuf[0..pad_len], ' ');
    const pad = ibuf[0..pad_len];

    const count = arr.count();
    // packed 判定（PHP HASH_PACKED 语义）：迭代序第 i 枚键恰为整数 i
    var is_packed = true;
    {
        var i: usize = 0;
        var pit = arr.elements.iterator();
        while (pit.next()) |e| : (i += 1) {
            switch (e.key_ptr.*) {
                .integer => |k| {
                    if (k != @as(i64, @intCast(i))) {
                        is_packed = false;
                        break;
                    }
                },
                .string => {
                    is_packed = false;
                    break;
                },
            }
        }
    }

    if (count == 0) {
        // PHP 实测空数组：`array(0) interned {`（无 packed、`{` 前有空格）；
        // 头部缩进由值行调用方已印（顶层 pad="" 无差）。
        fileWriteAll(1, "array(0) interned {\n");
        fileWriteAll(1, pad);
        fileWriteAll(1, "}\n");
        return;
    }

    const head = std.fmt.bufPrint(&nbuf, "array({d}) {s}refcount({d}){{\n", .{
        count,
        if (is_packed) "packed " else "",
        if (indent == 0) @as(i64, 3) else @as(i64, 1),
    }) catch "array(?)\n";
    // 头部不再自印 pad：值行缩进由调用方（debugZvalDumpValue 的 {pad}+"  "）承担，
    // 本函数自印的只有键行／闭括号行（PHP 实测嵌套数组头与父值行同缩进）。
    fileWriteAll(1, head);

    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        // 键行：{pad}  [键]=>
        fileWriteAll(1, pad);
        fileWriteAll(1, "  ");
        switch (entry.key_ptr.*) {
            .integer => |k| {
                const ks = std.fmt.bufPrint(&nbuf, "[{d}]=>\n", .{k}) catch "[?]=>\n";
                fileWriteAll(1, ks);
            },
            .string => |s| {
                fileWriteAll(1, "[\"");
                fileWriteAll(1, s.data);
                fileWriteAll(1, "\"]=>\n");
            },
        }
        // 值行：{pad}  {渲染}
        fileWriteAll(1, pad);
        fileWriteAll(1, "  ");
        debugZvalDumpValue(entry.value_ptr.*, indent + 1);
    }
    fileWriteAll(1, pad);
    fileWriteAll(1, "}\n");
}

/// F-71b：数组元素的值渲染（顶层非标量支由 php_debug_zval_dump 既有支承担，本 helper 只服务数组体内）。
fn debugZvalDumpValue(val: Value, indent: usize) void {
    var nbuf: [96]u8 = undefined;
    if (val.isInt()) {
        const s = std.fmt.bufPrint(&nbuf, "int({d})\n", .{val.asInt()}) catch "int(?)\n";
        fileWriteAll(1, s);
    } else if (val.isFloat()) {
        var num: [64]u8 = undefined;
        const fs = phpFormatFloatSerialize(&num, val.asFloat(), false, true);
        const s = std.fmt.bufPrint(&nbuf, "float({s})\n", .{fs}) catch "float(?)\n";
        fileWriteAll(1, s);
    } else if (val.isBool()) {
        fileWriteAll(1, if (val.asBool()) "bool(true)\n" else "bool(false)\n");
    } else if (val.isNull()) {
        fileWriteAll(1, "NULL\n");
    } else if (val.isString()) {
        const s = val.asString();
        const line = std.fmt.bufPrint(&nbuf, "string({d}) \"", .{s.length}) catch "string(?)\n";
        fileWriteAll(1, line);
        fileWriteAll(1, s.data);
        fileWriteAll(1, "\" refcount(1)\n");
    } else if (val.isArray()) {
        if (indent > 16) {
            fileWriteAll(1, "*RECURSION*\n");
            return;
        }
        debugZvalDumpArray(val.asArray(), indent);
    } else {
        fileWriteAll(1, "unknown type\n");
    }
}

/// headers_list - 返回已发送的 HTTP 头列表
/// 在 CLI 模式下返回空数组
pub fn php_headers_list(allocator: Allocator) !Value {
    return Value.initArray(try PHPArray.init(allocator));
}

/// header - 发送 HTTP 头（CLI 模式下无操作）
pub fn php_header(header_str: Value, replace: Value, response_code: Value) !Value {
    _ = header_str;
    _ = replace;
    _ = response_code;
    // CLI 模式下 header() 无实际效果
    return Value.initNull();
}

/// http_response_code - 获取/设置 HTTP 响应状态码
/// ★R-207（F-131-b）真值实测（PHP 8.5.8 CLI）：未设置时 get 返回 **false**；
///   首次 set 返回 **true**（无前值），其后 set 返回前一个 int；set(0) 返回 false 且不改状态。
///   "headers already sent 时 set 失败"属输出状态跟踪，未接（已登记）。
threadlocal var current_http_response_code: i64 = 0; // 0 = 未设置
pub fn php_http_response_code(code: Value) !Value {
    if (!code.isNull() and code.isInt()) {
        const c = code.asInt();
        if (c == 0) return Value.initBool(false);
        const prev = current_http_response_code;
        current_http_response_code = c;
        return if (prev == 0) Value.initBool(true) else Value.initInt(prev);
    }
    return if (current_http_response_code == 0)
        Value.initBool(false)
    else
        Value.initInt(current_http_response_code);
}

// ============================================================================
// 输出缓冲系统
// ============================================================================

/// 输出缓冲栈
const OBLevel = struct {
    buffer: std.ArrayListUnmanaged(u8) = .empty,
    callback: ?Value = null,
};

threadlocal var ob_stack: std.ArrayListUnmanaged(OBLevel) = .empty;
threadlocal var ob_initialized: bool = false;

fn ensureObInit() void {
    if (!ob_initialized) {
        ob_stack = .empty;
        ob_initialized = true;
    }
}

/// mysqli_connect stub — AOT不支持数据库，仅供function_exists识别
pub fn php_mysqli_connect(host: Value, user: Value, password: Value, db: Value, port: Value, socket: Value, allocator: Allocator) !Value {
    _ = host;
    _ = user;
    _ = password;
    _ = db;
    _ = port;
    _ = socket;
    _ = allocator;
    return Value.initBool(false);
}

/// token_get_all stub — AOT不支持PHP tokenizer，仅供function_exists识别
pub fn php_token_get_all(source: Value, flags: Value, allocator: Allocator) !Value {
    _ = source;
    _ = flags;
    return Value.initArray(try PHPArray.init(allocator));
}

/// ob_gzhandler - zlib 输出缓冲回调
/// CLI/AOT 中不做压缩，按 PHP 回调签名原样返回 buffer
pub fn php_ob_gzhandler(buffer: Value, phase: Value, allocator: Allocator) !Value {
    _ = phase;
    if (!buffer.isString()) return Value.initString(try PHPString.init(allocator, ""));
    return Value.initString(try PHPString.init(allocator, buffer.asString().data));
}

/// ob_start - 打开输出缓冲
pub fn php_ob_start(callback: Value, allocator: Allocator) !Value {
    _ = allocator;
    ensureObInit();
    var level = OBLevel{};
    if (!callback.isNull()) {
        _ = callback.retain();
        level.callback = callback;
    }
    try ob_stack.append(runtime_allocator, level);
    return Value.initBool(true);
}

/// ob_get_contents - 返回输出缓冲区的内容
pub fn php_ob_get_contents(allocator: Allocator) !Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    const level = &ob_stack.items[ob_stack.items.len - 1];
    return Value.initString(try PHPString.init(allocator, level.buffer.items));
}

/// ob_end_clean - 清除并关闭输出缓冲区
pub fn php_ob_end_clean() !Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    var level = ob_stack.pop().?;
    level.buffer.deinit(runtime_allocator);
    if (level.callback) |cb| cb.release(runtime_allocator);
    return Value.initBool(true);
}

/// ob_get_clean - 获取缓冲区内容并关闭
pub fn php_ob_get_clean(allocator: Allocator) !Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    const contents = try PHPString.init(allocator, ob_stack.items[ob_stack.items.len - 1].buffer.items);
    var level = ob_stack.pop().?;
    level.buffer.deinit(runtime_allocator);
    if (level.callback) |cb| cb.release(runtime_allocator);
    return Value.initString(contents);
}

/// ob_get_level - 返回输出缓冲区嵌套级别
pub fn php_ob_get_level() Value {
    ensureObInit();
    return Value.initInt(@intCast(ob_stack.items.len));
}

/// ob_flush - 刷新输出缓冲区
pub fn php_ob_flush() !Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    const level = &ob_stack.items[ob_stack.items.len - 1];
    if (level.buffer.items.len > 0) {
        fileWriteAll(1, level.buffer.items);
        level.buffer.clearRetainingCapacity();
    }
    return Value.initBool(true);
}

/// ob_end_flush - 刷新并关闭输出缓冲区
pub fn php_ob_end_flush() !Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    var level = ob_stack.pop().?;
    if (level.buffer.items.len > 0) {
        fileWriteAll(1, level.buffer.items);
    }
    level.buffer.deinit(runtime_allocator);
    if (level.callback) |cb| cb.release(runtime_allocator);
    return Value.initBool(true);
}

/// ob_get_length - 返回输出缓冲区内容的长度
pub fn php_ob_get_length() Value {
    ensureObInit();
    if (ob_stack.items.len == 0) return Value.initBool(false);
    const level = &ob_stack.items[ob_stack.items.len - 1];
    return Value.initInt(@intCast(level.buffer.items.len));
}

/// ob_get_status - 获取输出缓冲区的状态
pub fn php_ob_get_status(full_status: Value, allocator: Allocator) !Value {
    ensureObInit();
    if (full_status.toBool()) {
        // 返回所有级别的状态数组
        const result = try PHPArray.init(allocator);
        for (ob_stack.items, 0..) |_, i| {
            const level_arr = try PHPArray.init(allocator);
            const k_level = try PHPString.init(allocator, "level");
            try level_arr.set(allocator, ArrayKey{ .string = k_level }, Value.initInt(@intCast(i + 1)));
            const k_name = try PHPString.init(allocator, "name");
            try level_arr.set(allocator, ArrayKey{ .string = k_name }, Value.initString(try PHPString.init(allocator, "default output handler")));
            const k_buf = try PHPString.init(allocator, "buffer_size");
            try level_arr.set(allocator, ArrayKey{ .string = k_buf }, Value.initInt(0));
            try result.push(allocator, Value.initArray(level_arr));
        }
        return Value.initArray(result);
    }
    // 返回当前级别的状态
    if (ob_stack.items.len == 0) return Value.initArray(try PHPArray.init(allocator));
    const level_arr = try PHPArray.init(allocator);
    const k_level = try PHPString.init(allocator, "level");
    try level_arr.set(allocator, ArrayKey{ .string = k_level }, Value.initInt(@intCast(ob_stack.items.len)));
    const k_name = try PHPString.init(allocator, "name");
    try level_arr.set(allocator, ArrayKey{ .string = k_name }, Value.initString(try PHPString.init(allocator, "default output handler")));
    const k_buf = try PHPString.init(allocator, "buffer_size");
    try level_arr.set(allocator, ArrayKey{ .string = k_buf }, Value.initInt(0));
    return Value.initArray(level_arr);
}

/// ob_implicit_flush - 打开/关闭隐式刷新
pub fn php_ob_implicit_flush(flag: Value) Value {
    _ = flag;
    return Value.initNull();
}

/// get_resource_id - 返回资源的整数标识符
pub fn php_get_resource_id(val: Value) !Value {
    // AOT 中没有真正的资源类型，返回 0
    _ = val;
    return Value.initInt(0);
}

// ============================================================================
// JSON函数
// ============================================================================

/// json_encode - 将PHP值编码为JSON字符串
pub fn php_json_encode(value: Value, flags: Value, depth: Value, allocator: Allocator) !Value {
    // 解析flags（可选，默认0）
    const flags_int = if (flags.isInt()) flags.asInt() else 0;

    // 解析depth（可选，默认512）
    const depth_int = if (depth.isInt()) depth.asInt() else 512;
    _ = depth_int;

    var buffer = std.ArrayListUnmanaged(u8).empty;
    defer buffer.deinit(allocator);

    const pretty = (flags_int & 128) != 0; // JSON_PRETTY_PRINT
    // ★F-63（R-173）：非有限浮点 ⇒ PHP 的 `json_encode` 返回 **false**（不是字符串 `"false"`、不是抛错）
    if (pretty) {
        jsonEncodeValuePretty(value, &buffer, allocator, flags_int, 0) catch |err| switch (err) {
            error.JsonInfOrNan => return Value.initBool(false),
            error.JsonPureEnum => {
                last_json_error_code = json_error_non_backed_enum;
                return Value.initBool(false);
            },
            else => return err,
        };
    } else {
        jsonEncodeValue(value, &buffer, allocator, flags_int) catch |err| switch (err) {
            error.JsonInfOrNan => return Value.initBool(false),
            error.JsonPureEnum => {
                last_json_error_code = json_error_non_backed_enum;
                return Value.initBool(false);
            },
            else => return err,
        };
    }

    const result = try PHPString.init(allocator, buffer.items);
    return Value.initString(result);
}

fn jsonEncodeValue(value: Value, buffer: *std.ArrayListUnmanaged(u8), allocator: Allocator, flags: i64) !void {
    if (value.isNull()) {
        try buffer.appendSlice(allocator, "null");
    } else if (value.isBool()) {
        try buffer.appendSlice(allocator, if (value.asBool()) "true" else "false");
    } else if (value.isInt()) {
        const formatted = try std.fmt.allocPrint(allocator, "{d}", .{value.asInt()});
        defer allocator.free(formatted);
        try buffer.appendSlice(allocator, formatted);
    } else if (value.isFloat()) {
        // ★F-63（R-173）：json 属序列化口径但用**小写 e**（实测 `1.0e+17`／`1.0e-5`），且
        //   INF/-INF/NAN 让整个 encode **返回 false**（实测顶层与嵌套都 false，`JSON_PARTIAL_OUTPUT_ON_ERROR`
        //   也救不回来，`json_last_error()=7 "Inf and NaN cannot be JSON encoded"`）
        //   ⇒ 这里以 error 上抛，由 `php_json_encode` 收成 `false`。旧写 `{d}` 直出 20 位小数且非有限值出 `inf`。
        const f = value.asFloat();
        if (std.math.isNan(f) or std.math.isInf(f)) return error.JsonInfOrNan;
        var buf: [64]u8 = undefined;
        try buffer.appendSlice(allocator, phpFormatFloatSerialize(&buf, f, false, false));
    } else if (value.isString()) {
        const str = value.asString();
        try buffer.append(allocator, '"');
        const unescape_unicode = (flags & 256) != 0; // JSON_UNESCAPED_UNICODE
        const unescape_slashes = (flags & 64) != 0; // JSON_UNESCAPED_SLASHES
        var i: usize = 0;
        while (i < str.data.len) {
            const c = str.data[i];
            switch (c) {
                '"' => {
                    if ((flags & 8) != 0) { // JSON_HEX_QUOT
                        try buffer.appendSlice(allocator, "\\u0022");
                    } else {
                        try buffer.appendSlice(allocator, "\\\"");
                    }
                },
                '\\' => try buffer.appendSlice(allocator, "\\\\"),
                '\n' => try buffer.appendSlice(allocator, "\\n"),
                '\r' => try buffer.appendSlice(allocator, "\\r"),
                '\t' => try buffer.appendSlice(allocator, "\\t"),
                '/' => {
                    if (unescape_slashes) {
                        try buffer.append(allocator, '/');
                    } else {
                        try buffer.appendSlice(allocator, "\\/");
                    }
                },
                0x08 => try buffer.appendSlice(allocator, "\\b"),
                0x0c => try buffer.appendSlice(allocator, "\\f"),
                else => {
                    if (c < 0x20) {
                        // 控制字符用 \uXXXX 转义
                        const hex = try std.fmt.allocPrint(allocator, "\\u{x:0>4}", .{c});
                        defer allocator.free(hex);
                        try buffer.appendSlice(allocator, hex);
                    } else if (c < 0x80) {
                        // ASCII 可打印字符
                        try buffer.append(allocator, c);
                    } else {
                        // 多字节 UTF-8 字符
                        if (unescape_unicode) {
                            // 直接输出 UTF-8 字节
                            try buffer.append(allocator, c);
                            i += 1;
                            while (i < str.data.len and (str.data[i] & 0xC0) == 0x80) {
                                try buffer.append(allocator, str.data[i]);
                                i += 1;
                            }
                            continue;
                        } else {
                            // 解码 UTF-8 并转义为 \uXXXX
                            var cp: u21 = 0;
                            var consumed: usize = 0;
                            if (c & 0xE0 == 0xC0) {
                                // 2字节
                                if (i + 1 < str.data.len) {
                                    cp = (@as(u21, c & 0x1F) << 6) | @as(u21, str.data[i + 1] & 0x3F);
                                    consumed = 2;
                                } else consumed = 1;
                            } else if (c & 0xF0 == 0xE0) {
                                // 3字节
                                if (i + 2 < str.data.len) {
                                    cp = (@as(u21, c & 0x0F) << 12) | (@as(u21, str.data[i + 1] & 0x3F) << 6) | @as(u21, str.data[i + 2] & 0x3F);
                                    consumed = 3;
                                } else consumed = 1;
                            } else if (c & 0xF8 == 0xF0) {
                                // 4字节
                                if (i + 3 < str.data.len) {
                                    cp = (@as(u21, c & 0x07) << 18) | (@as(u21, str.data[i + 1] & 0x3F) << 12) | (@as(u21, str.data[i + 2] & 0x3F) << 6) | @as(u21, str.data[i + 3] & 0x3F);
                                    consumed = 4;
                                } else consumed = 1;
                            } else {
                                consumed = 1;
                                cp = c;
                            }
                            if (cp <= 0xFFFF) {
                                const hex = try std.fmt.allocPrint(allocator, "\\u{x:0>4}", .{cp});
                                defer allocator.free(hex);
                                try buffer.appendSlice(allocator, hex);
                            } else {
                                // 代理对
                                const adj = cp - 0x10000;
                                const hi = 0xD800 + (adj >> 10);
                                const lo = 0xDC00 + (adj & 0x3FF);
                                const hex = try std.fmt.allocPrint(allocator, "\\u{x:0>4}\\u{x:0>4}", .{ hi, lo });
                                defer allocator.free(hex);
                                try buffer.appendSlice(allocator, hex);
                            }
                            i += consumed;
                            continue;
                        }
                    }
                },
            }
            i += 1;
        }
        try buffer.append(allocator, '"');
    } else if (value.isArray()) {
        const arr = value.asArray();
        var is_list = true;
        var expected_index: i64 = 0;

        // 检查是否是纯索引数组
        var it = arr.elements.iterator();
        while (it.next()) |entry| {
            switch (entry.key_ptr.*) {
                .integer => |k| {
                    if (k != expected_index) is_list = false;
                    expected_index += 1;
                },
                .string => is_list = false,
            }
            if (!is_list) break;
        }

        if (is_list) {
            try buffer.append(allocator, '[');
            var first = true;
            it = arr.elements.iterator();
            while (it.next()) |entry| {
                if (!first) try buffer.append(allocator, ',');
                try jsonEncodeValue(entry.value_ptr.*, buffer, allocator, flags);
                first = false;
            }
            try buffer.append(allocator, ']');
        } else {
            try buffer.append(allocator, '{');
            var first = true;
            it = arr.elements.iterator();
            while (it.next()) |entry| {
                if (!first) try buffer.append(allocator, ',');

                // 写入键
                switch (entry.key_ptr.*) {
                    .integer => |k| {
                        try buffer.append(allocator, '"');
                        const key_str = try std.fmt.allocPrint(allocator, "{d}", .{k});
                        defer allocator.free(key_str);
                        try buffer.appendSlice(allocator, key_str);
                        try buffer.append(allocator, '"');
                    },
                    .string => |k| {
                        try buffer.append(allocator, '"');
                        for (k.data) |c| {
                            switch (c) {
                                '"' => try buffer.appendSlice(allocator, "\\\""),
                                '\\' => try buffer.appendSlice(allocator, "\\\\"),
                                '\n' => try buffer.appendSlice(allocator, "\\n"),
                                '\r' => try buffer.appendSlice(allocator, "\\r"),
                                '\t' => try buffer.appendSlice(allocator, "\\t"),
                                else => try buffer.append(allocator, c),
                            }
                        }
                        try buffer.append(allocator, '"');
                    },
                }
                try buffer.appendSlice(allocator, ":");

                // 写入值
                try jsonEncodeValue(entry.value_ptr.*, buffer, allocator, flags);
                first = false;
            }
            try buffer.append(allocator, '}');
        }
    } else if (Value_isObject(value)) {
        // 对象序列化为JSON对象
        const obj = Value_asObject(value);
        // ★F-218（R-325）：枚举序列化口径（PHP 8.5.8 实测）——backed enum ⇒ backing value
        //   直接序列化；纯 enum ⇒ 整个 encode 返回 false（error 上抛由顶层收，last_error=11）。
        if (obj.class_meta) |meta| {
            if (meta.is_enum) {
                if (obj.getPropertyDirect("value")) |backing| {
                    return jsonEncodeValue(backing, buffer, allocator, flags);
                }
                return error.JsonPureEnum;
            }
            // ★批次十（t13）：JsonSerializable 契约——json_encode 命中该接口的对象时
            //   编码其 jsonSerialize() 返回值，而非公开属性面（PHP 8.5.8 真值：
            //   `class P implements \JsonSerializable {…return [1,2];}` ⇒ `JSON=[1,2]`）。
            if (meta.implementsInterface("JsonSerializable")) {
                if (meta.findMethodLookup("jsonSerialize")) |lookup| {
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    const ret = try lookup.method.func(value, &.{}, allocator);
                    defer ret.release(allocator);
                    return jsonEncodeValue(ret, buffer, allocator, flags);
                }
            }
        }
        try buffer.append(allocator, '{');
        var first = true;
        var it = obj.properties.iterator();
        while (it.next()) |entry| {
            if (!first) try buffer.append(allocator, ',');

            // 写入键
            try buffer.append(allocator, '"');
            for (entry.key_ptr.*) |c| {
                switch (c) {
                    '"' => try buffer.appendSlice(allocator, "\\\""),
                    '\\' => try buffer.appendSlice(allocator, "\\\\"),
                    '\n' => try buffer.appendSlice(allocator, "\\n"),
                    '\r' => try buffer.appendSlice(allocator, "\\r"),
                    '\t' => try buffer.appendSlice(allocator, "\\t"),
                    else => try buffer.append(allocator, c),
                }
            }
            try buffer.append(allocator, '"');
            try buffer.appendSlice(allocator, ":");

            // 写入值
            try jsonEncodeValue(entry.value_ptr.*, buffer, allocator, flags);
            first = false;
        }
        try buffer.append(allocator, '}');
    } else {
        try buffer.appendSlice(allocator, "null");
    }
}

fn jsonEncodeValuePretty(value: Value, buffer: *std.ArrayListUnmanaged(u8), allocator: Allocator, flags: i64, indent: usize) !void {
    const indent_str = "    ";
    if (value.isNull()) {
        try buffer.appendSlice(allocator, "null");
    } else if (value.isBool()) {
        try buffer.appendSlice(allocator, if (value.asBool()) "true" else "false");
    } else if (value.isInt()) {
        const formatted = try std.fmt.allocPrint(allocator, "{d}", .{value.asInt()});
        defer allocator.free(formatted);
        try buffer.appendSlice(allocator, formatted);
    } else if (value.isFloat()) {
        // ★F-63（R-173）：json 属序列化口径但用**小写 e**（实测 `1.0e+17`／`1.0e-5`），且
        //   INF/-INF/NAN 让整个 encode **返回 false**（实测顶层与嵌套都 false，`JSON_PARTIAL_OUTPUT_ON_ERROR`
        //   也救不回来，`json_last_error()=7 "Inf and NaN cannot be JSON encoded"`）
        //   ⇒ 这里以 error 上抛，由 `php_json_encode` 收成 `false`。旧写 `{d}` 直出 20 位小数且非有限值出 `inf`。
        const f = value.asFloat();
        if (std.math.isNan(f) or std.math.isInf(f)) return error.JsonInfOrNan;
        var buf: [64]u8 = undefined;
        try buffer.appendSlice(allocator, phpFormatFloatSerialize(&buf, f, false, false));
    } else if (value.isString()) {
        // 复用 jsonEncodeValue 的字符串编码逻辑
        try jsonEncodeValue(value, buffer, allocator, flags);
    } else if (value.isArray()) {
        const arr = value.asArray();
        var is_list = true;
        var expected_index: i64 = 0;
        var it = arr.elements.iterator();
        while (it.next()) |entry| {
            switch (entry.key_ptr.*) {
                .integer => |k| {
                    if (k != expected_index) is_list = false;
                    expected_index += 1;
                },
                .string => is_list = false,
            }
            if (!is_list) break;
        }
        if (is_list) {
            var count: usize = 0;
            it = arr.elements.iterator();
            while (it.next()) |_| count += 1;
            if (count == 0) {
                try buffer.appendSlice(allocator, "[]");
                return;
            }
            try buffer.appendSlice(allocator, "[\n");
            var first = true;
            it = arr.elements.iterator();
            while (it.next()) |entry| {
                if (!first) try buffer.appendSlice(allocator, ",\n");
                for (0..indent + 1) |_| try buffer.appendSlice(allocator, indent_str);
                try jsonEncodeValuePretty(entry.value_ptr.*, buffer, allocator, flags, indent + 1);
                first = false;
            }
            try buffer.appendSlice(allocator, "\n");
            for (0..indent) |_| try buffer.appendSlice(allocator, indent_str);
            try buffer.appendSlice(allocator, "]");
        } else {
            var count: usize = 0;
            it = arr.elements.iterator();
            while (it.next()) |_| count += 1;
            if (count == 0) {
                try buffer.appendSlice(allocator, "{}");
                return;
            }
            try buffer.appendSlice(allocator, "{\n");
            var first = true;
            it = arr.elements.iterator();
            while (it.next()) |entry| {
                if (!first) try buffer.appendSlice(allocator, ",\n");
                for (0..indent + 1) |_| try buffer.appendSlice(allocator, indent_str);
                // 写入键
                switch (entry.key_ptr.*) {
                    .integer => |k| {
                        try buffer.append(allocator, '"');
                        const key_str = try std.fmt.allocPrint(allocator, "{d}", .{k});
                        defer allocator.free(key_str);
                        try buffer.appendSlice(allocator, key_str);
                        try buffer.append(allocator, '"');
                    },
                    .string => |k| {
                        try jsonEncodeValue(Value.initString(k), buffer, allocator, flags);
                    },
                }
                try buffer.appendSlice(allocator, ": ");
                try jsonEncodeValuePretty(entry.value_ptr.*, buffer, allocator, flags, indent + 1);
                first = false;
            }
            try buffer.appendSlice(allocator, "\n");
            for (0..indent) |_| try buffer.appendSlice(allocator, indent_str);
            try buffer.appendSlice(allocator, "}");
        }
    } else if (Value_isObject(value)) {
        const obj = Value_asObject(value);
        // ★F-218（R-325）：枚举序列化口径同 jsonEncodeValue
        if (obj.class_meta) |meta| {
            if (meta.is_enum) {
                if (obj.getPropertyDirect("value")) |backing| {
                    return jsonEncodeValuePretty(backing, buffer, allocator, flags, indent);
                }
                return error.JsonPureEnum;
            }
            // ★批次十（t13）：JsonSerializable 契约同 jsonEncodeValue（pretty 面递归带缩进）。
            if (meta.implementsInterface("JsonSerializable")) {
                if (meta.findMethodLookup("jsonSerialize")) |lookup| {
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    const ret = try lookup.method.func(value, &.{}, allocator);
                    defer ret.release(allocator);
                    return jsonEncodeValuePretty(ret, buffer, allocator, flags, indent);
                }
            }
        }
        var count: usize = 0;
        var it = obj.properties.iterator();
        while (it.next()) |_| count += 1;
        if (count == 0) {
            try buffer.appendSlice(allocator, "{}");
            return;
        }
        try buffer.appendSlice(allocator, "{\n");
        var first = true;
        it = obj.properties.iterator();
        while (it.next()) |entry| {
            if (!first) try buffer.appendSlice(allocator, ",\n");
            for (0..indent + 1) |_| try buffer.appendSlice(allocator, indent_str);
            // 写入键
            try buffer.append(allocator, '"');
            for (entry.key_ptr.*) |c| {
                switch (c) {
                    '"' => try buffer.appendSlice(allocator, "\\\""),
                    '\\' => try buffer.appendSlice(allocator, "\\\\"),
                    else => try buffer.append(allocator, c),
                }
            }
            try buffer.append(allocator, '"');
            try buffer.appendSlice(allocator, ": ");
            try jsonEncodeValuePretty(entry.value_ptr.*, buffer, allocator, flags, indent + 1);
            first = false;
        }
        try buffer.appendSlice(allocator, "\n");
        for (0..indent) |_| try buffer.appendSlice(allocator, indent_str);
        try buffer.appendSlice(allocator, "}");
    } else {
        try buffer.appendSlice(allocator, "null");
    }
}

const json_error_none: i32 = 0;
const json_error_depth: i32 = 1;
const json_error_syntax: i32 = 4;
const json_error_utf8: i32 = 5;
/// ★F-218：纯 enum json_encode ⇒ PHP 的 JSON_ERROR_NON_BACKED_ENUM = 11
const json_error_non_backed_enum: i32 = 11;

threadlocal var last_json_error_code: i32 = json_error_none;

pub fn php_json_last_error() Value {
    return Value.initInt(last_json_error_code);
}

pub fn php_json_last_error_msg(allocator: Allocator) !Value {
    const msg = switch (last_json_error_code) {
        json_error_none => "No error",
        json_error_depth => "Maximum stack depth exceeded",
        json_error_syntax => "Syntax error",
        else => "Unknown error",
    };
    return Value.initString(try PHPString.init(allocator, msg));
}

/// json_decode - 解析JSON字符串为PHP值
pub fn php_json_decode(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return error.InvalidArgumentCount;

    const json = args[0];
    if (!json.isString()) {
        last_json_error_code = json_error_syntax;
        return Value.initNull();
    }

    // ★F-149（R-238）：#2 ?bool $associative（null 合法 ⇒ 返回对象；标量按 PHP 真值）
    const assoc_ok = if (args.len >= 2) blk: {
        const v = requireNullableBoolParam("json_decode", 2, "associative", args[1]) orelse return Value.initNull();
        break :blk v;
    } else Value.initBool(false);
    // ★F-62f 第三批：#3 $depth / #4 $flags 为可选 int，Foo ⇒ TypeError；null ⇒ 默认值
    const depth_val = if (args.len >= 3) blk: {
        const v = requireOptionalNumParam("json_decode", 3, "depth", .int_param, args[2]) orelse return Value.initNull();
        break :blk if (v.isNull()) Value.initInt(512) else v;
    } else Value.initInt(512);
    if (args.len >= 4) {
        _ = requireOptionalNumParam("json_decode", 4, "flags", .int_param, args[3]) orelse return Value.initNull();
    }
    const is_assoc = if (assoc_ok.isNull()) false else assoc_ok.toBool();
    const json_str = json.asString().data;
    var pos: usize = 0;
    const depth_i64 = @max(depth_val.toInt(), 1);
    const depth: usize = @intCast(depth_i64);

    const result = jsonDecodeValue(json_str, &pos, is_assoc, depth, allocator) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.MaxDepthExceeded => {
            last_json_error_code = json_error_depth;
            return Value.initNull();
        },
        else => {
            last_json_error_code = json_error_syntax;
            return Value.initNull();
        },
    };

    skipWhitespace(json_str, &pos);
    if (pos != json_str.len) {
        result.release(allocator);
        last_json_error_code = json_error_syntax;
        return Value.initNull();
    }

    last_json_error_code = json_error_none;
    return result;
}

const JsonError = error{
    InvalidJson,
    UnexpectedEnd,
    OutOfMemory,
    StringTooLarge,
    MaxDepthExceeded,
};

fn jsonDecodeValue(json: []const u8, pos: *usize, assoc: bool, depth: usize, allocator: Allocator) JsonError!Value {
    skipWhitespace(json, pos);

    if (pos.* >= json.len) return error.UnexpectedEnd;

    const c = json[pos.*];

    if (c == 'n' and pos.* + 4 <= json.len and std.mem.eql(u8, json[pos.* .. pos.* + 4], "null")) {
        pos.* += 4;
        return Value.initNull();
    }

    if (c == 't' and pos.* + 4 <= json.len and std.mem.eql(u8, json[pos.* .. pos.* + 4], "true")) {
        pos.* += 4;
        return Value.initBool(true);
    }

    if (c == 'f' and pos.* + 5 <= json.len and std.mem.eql(u8, json[pos.* .. pos.* + 5], "false")) {
        pos.* += 5;
        return Value.initBool(false);
    }

    if (c == '"') {
        return jsonDecodeString(json, pos, allocator);
    }

    if (c == '[') {
        if (depth == 0) return error.MaxDepthExceeded;
        return jsonDecodeArray(json, pos, assoc, depth - 1, allocator);
    }

    if (c == '{') {
        if (depth == 0) return error.MaxDepthExceeded;
        return jsonDecodeObject(json, pos, assoc, depth - 1, allocator);
    }

    if (c == '-' or (c >= '0' and c <= '9')) {
        return jsonDecodeNumber(json, pos);
    }

    return error.InvalidJson;
}

fn jsonDecodeString(json: []const u8, pos: *usize, allocator: Allocator) !Value {
    pos.* += 1; // 跳过开头的引号

    var buffer = std.ArrayListUnmanaged(u8).empty;
    defer buffer.deinit(allocator);

    while (pos.* < json.len and json[pos.*] != '"') {
        if (json[pos.*] == '\\' and pos.* + 1 < json.len) {
            pos.* += 1;
            switch (json[pos.*]) {
                'n' => try buffer.append(allocator, '\n'),
                'r' => try buffer.append(allocator, '\r'),
                't' => try buffer.append(allocator, '\t'),
                '"' => try buffer.append(allocator, '"'),
                '\\' => try buffer.append(allocator, '\\'),
                else => try buffer.append(allocator, json[pos.*]),
            }
        } else {
            try buffer.append(allocator, json[pos.*]);
        }
        pos.* += 1;
    }

    if (pos.* < json.len) pos.* += 1; // 跳过结尾的引号

    const result = try PHPString.init(allocator, buffer.items);
    return Value.initString(result);
}

fn jsonDecodeNumber(json: []const u8, pos: *usize) JsonError!Value {
    const start = pos.*;
    var is_float = false;

    if (json[pos.*] == '-') pos.* += 1;

    while (pos.* < json.len) {
        const c = json[pos.*];
        if (c >= '0' and c <= '9') {
            pos.* += 1;
        } else if (c == '.' or c == 'e' or c == 'E') {
            is_float = true;
            pos.* += 1;
        } else if (c == '+' or c == '-') {
            pos.* += 1;
        } else {
            break;
        }
    }

    const num_str = json[start..pos.*];

    if (is_float) {
        const f = std.fmt.parseFloat(f64, num_str) catch return Value.initFloat(0);
        return Value.initFloat(f);
    } else {
        const i = std.fmt.parseInt(i64, num_str, 10) catch return Value.initInt(0);
        return Value.initInt(i);
    }
}

fn jsonDecodeArray(json: []const u8, pos: *usize, assoc: bool, depth: usize, allocator: Allocator) JsonError!Value {
    pos.* += 1; // 跳过 '['

    const arr = try PHPArray.init(allocator);

    skipWhitespace(json, pos);

    if (pos.* < json.len and json[pos.*] == ']') {
        pos.* += 1;
        return Value.initArray(arr);
    }

    while (pos.* < json.len) {
        const value = try jsonDecodeValue(json, pos, assoc, depth, allocator);
        try arr.push(allocator, value);
        value.release(allocator);

        skipWhitespace(json, pos);

        if (pos.* < json.len and json[pos.*] == ',') {
            pos.* += 1;
            skipWhitespace(json, pos);
        } else {
            break;
        }
    }

    if (pos.* < json.len and json[pos.*] == ']') pos.* += 1;

    return Value.initArray(arr);
}

fn jsonDecodeObject(json: []const u8, pos: *usize, assoc: bool, depth: usize, allocator: Allocator) JsonError!Value {
    pos.* += 1; // 跳过 '{'

    const arr = try PHPArray.init(allocator);

    skipWhitespace(json, pos);

    if (pos.* < json.len and json[pos.*] == '}') {
        pos.* += 1;
        return Value.initArray(arr);
    }

    while (pos.* < json.len) {
        skipWhitespace(json, pos);

        // 解析键
        if (json[pos.*] != '"') return error.InvalidJson;
        const key = try jsonDecodeString(json, pos, allocator);

        skipWhitespace(json, pos);

        if (pos.* >= json.len or json[pos.*] != ':') return error.InvalidJson;
        pos.* += 1;

        // 解析值
        const value = try jsonDecodeValue(json, pos, assoc, depth, allocator);

        // 添加到数组
        if (key.isString()) {
            const key_str = key.asString();
            const array_key = ArrayKey{ .string = key_str };
            try arr.set(allocator, array_key, value);
        }
        key.release(allocator);
        value.release(allocator);

        skipWhitespace(json, pos);

        if (pos.* < json.len and json[pos.*] == ',') {
            pos.* += 1;
        } else {
            break;
        }
    }

    if (pos.* < json.len and json[pos.*] == '}') pos.* += 1;

    if (assoc) {
        return Value.initArray(arr);
    }

    const obj_val = php_object_new("stdClass", allocator) catch return error.OutOfMemory;
    const obj = Value_asObject(obj_val);
    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        switch (entry.key_ptr.*) {
            .string => |k| obj.setProperty(k.data, entry.value_ptr.*) catch return error.OutOfMemory,
            .integer => |k| {
                var key_buf: [32]u8 = undefined;
                const key_str = std.fmt.bufPrint(&key_buf, "{d}", .{k}) catch return error.OutOfMemory;
                obj.setProperty(key_str, entry.value_ptr.*) catch return error.OutOfMemory;
            },
        }
    }

    return obj_val;
}

fn skipWhitespace(json: []const u8, pos: *usize) void {
    while (pos.* < json.len and (json[pos.*] == ' ' or json[pos.*] == '\t' or json[pos.*] == '\n' or json[pos.*] == '\r')) {
        pos.* += 1;
    }
}

// ============================================================================
// 杂项函数
// ============================================================================

/// strtotime - 将字符串转换为时间戳
pub fn php_strtotime(time_str: Value, now: Value, allocator: Allocator) !Value {
    _ = allocator;

    if (!time_str.isString()) return Value.initBool(false);
    const str = time_str.asString().data;
    const base_ts: i64 = if (now.isInt()) now.asInt() else unixTimestamp();

    // 相对时间："+N unit" 或 "-N unit" 或 "next X"
    if (str.len > 0 and (str[0] == '+' or str[0] == '-')) {
        const sign: i64 = if (str[0] == '+') 1 else -1;
        var i: usize = 1;
        while (i < str.len and str[i] == ' ') i += 1;
        var num: i64 = 0;
        while (i < str.len and str[i] >= '0' and str[i] <= '9') : (i += 1) {
            num = num * 10 + (str[i] - '0');
        }
        while (i < str.len and str[i] == ' ') i += 1;
        const unit = str[i..];

        // month 和 year 使用日历计算（非固定秒数）
        if (std.mem.startsWith(u8, unit, "month") or std.mem.startsWith(u8, unit, "year")) {
            const month_delta: i64 = if (std.mem.startsWith(u8, unit, "year")) sign * num * 12 else sign * num;
            // 分解 base_ts 为年月日时分秒
            const epoch_secs_u64: u64 = @intCast(@max(@as(i64, 0), base_ts));
            const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_secs_u64 };
            const day_secs = epoch.getDaySeconds();
            const epoch_day = epoch.getEpochDay();
            const year_day = epoch_day.calculateYearDay();
            const month_day = year_day.calculateMonthDay();
            var year: i64 = @intCast(@as(i32, year_day.year));
            var month: i64 = @intCast(month_day.month.numeric());
            const day: i64 = @intCast(month_day.day_index + 1);
            const hour: i64 = @intCast(day_secs.getHoursIntoDay());
            const min: i64 = @intCast(day_secs.getMinutesIntoHour());
            const sec: i64 = @intCast(day_secs.getSecondsIntoMinute());

            // 日历月加法
            var total_months = month + month_delta;
            while (total_months > 12) {
                total_months -= 12;
                year += 1;
            }
            while (total_months < 1) {
                total_months += 12;
                year -= 1;
            }
            month = total_months;

            // 限制 day 在目标月份的有效范围内
            const dim: i64 = switch (@as(u32, @intCast(month))) {
                1, 3, 5, 7, 8, 10, 12 => 31,
                4, 6, 9, 11 => 30,
                2 => if (isLeapYearTop(year)) 29 else 28,
                else => 30,
            };
            const clamped_day = @min(day, dim);

            // Julian Day 公式转回时间戳
            const y2 = if (month <= 2) year - 1 else year;
            const m2 = if (month <= 2) month + 12 else month;
            const jd = 365 * y2 + @divFloor(y2, 4) - @divFloor(y2, 100) + @divFloor(y2, 400) + @divFloor(306 * (m2 + 1), 10) + clamped_day - 719591;
            return Value.initInt(jd * 86400 + hour * 3600 + min * 60 + sec);
        }

        const secs: i64 = if (std.mem.startsWith(u8, unit, "second")) num else if (std.mem.startsWith(u8, unit, "minute")) num * 60 else if (std.mem.startsWith(u8, unit, "hour")) num * 3600 else if (std.mem.startsWith(u8, unit, "day")) num * 86400 else if (std.mem.startsWith(u8, unit, "week")) num * 604800 else 0;
        return Value.initInt(base_ts + sign * secs);
    }

    // 尝试解析 "YYYY-MM-DD HH:MM:SS" 或 "YYYY-MM-DD"
    if (str.len >= 10 and str[4] == '-' and str[7] == '-') {
        const year = std.fmt.parseInt(i64, str[0..4], 10) catch return Value.initBool(false);
        const month = std.fmt.parseInt(i64, str[5..7], 10) catch return Value.initBool(false);
        const day = std.fmt.parseInt(i64, str[8..10], 10) catch return Value.initBool(false);
        var hour: i64 = 0;
        var min: i64 = 0;
        var sec: i64 = 0;
        if (str.len >= 19 and str[10] == ' ') {
            hour = std.fmt.parseInt(i64, str[11..13], 10) catch 0;
            min = std.fmt.parseInt(i64, str[14..16], 10) catch 0;
            sec = std.fmt.parseInt(i64, str[17..19], 10) catch 0;
        }
        // 简单计算时间戳（Zeller公式近似）
        const y = if (month <= 2) year - 1 else year;
        const m = if (month <= 2) month + 12 else month;
        const jd = 365 * y + @divFloor(y, 4) - @divFloor(y, 100) + @divFloor(y, 400) + @divFloor(306 * (m + 1), 10) + day - 719591;
        const ts: i64 = jd * 86400 + hour * 3600 + min * 60 + sec;
        return Value.initInt(ts);
    }

    // "next Monday" / "last Sunday" 等相对日期
    if (std.mem.startsWith(u8, str, "next ") or std.mem.startsWith(u8, str, "last ")) {
        const is_next = str[0] == 'n';
        const day_name = std.mem.trim(u8, str[5..], " ");
        const target_dow: i64 = blk: {
            if (std.ascii.eqlIgnoreCase(day_name, "sunday")) break :blk 0;
            if (std.ascii.eqlIgnoreCase(day_name, "monday")) break :blk 1;
            if (std.ascii.eqlIgnoreCase(day_name, "tuesday")) break :blk 2;
            if (std.ascii.eqlIgnoreCase(day_name, "wednesday")) break :blk 3;
            if (std.ascii.eqlIgnoreCase(day_name, "thursday")) break :blk 4;
            if (std.ascii.eqlIgnoreCase(day_name, "friday")) break :blk 5;
            if (std.ascii.eqlIgnoreCase(day_name, "saturday")) break :blk 6;
            break :blk -1;
        };
        if (target_dow >= 0) {
            const epoch_secs_u64: u64 = @intCast(@max(@as(i64, 0), base_ts));
            const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_secs_u64 };
            const epoch_day = epoch.getEpochDay();
            const current_dow: i64 = @intCast(@mod(@as(i64, @intCast(epoch_day.day)) + 4, 7));
            var delta: i64 = if (is_next)
                @mod(target_dow - current_dow + 7, 7)
            else
                @mod(current_dow - target_dow + 7, 7);
            if (delta == 0) delta = 7;
            const signed_delta: i64 = if (is_next) delta else -delta;
            return Value.initInt(base_ts + signed_delta * 86400);
        }
    }

    // 返回当前时间戳作为fallback
    return Value.initInt(base_ts);
}

extern "c" fn sleep(seconds: c_uint) c_uint;
extern "c" fn usleep(usec: c_uint) c_int;

/// sleep - 延迟执行（秒）
pub fn php_sleep(seconds: Value) !Value {
    // ★F-62f 接线（门 BLT 段 H b168/b169）：实测 `sleep(): Argument #1 ($seconds) must be of type int, Foo given`。
    //   ★位置在 `sleep()` 系统调用**之前** ⇒ 对象入参不再有机会把 `toInt()` 的 0 当成「睡 0 秒」静默放过。
    const secs_ok = requireNumParam("sleep", 1, "seconds", .int_param, seconds) orelse return Value.initNull();
    const secs_raw = secs_ok.toInt();
    // ★F-127（R-229）：负数 ValueError；正数按 32 位折叠（PHP 实测 sleep(2^32)=0）
    if (secs_raw < 0) {
        return throwThrowable("ValueError", "sleep(): Argument #1 ($seconds) must be greater than or equal to 0", runtime_allocator);
    }
    const secs_bits: u64 = @bitCast(secs_raw);
    const secs: c_uint = @truncate(secs_bits);
    // ★Go 式协程 M1（D5=A）：协程内自动让出（定时器挂起），main 内真阻塞——面不变，行为按上下文分流。
    // ★G14（多协程能力加固）：main 侧 sleep/usleep 也改走调度器（sleepNs 无调度器时内部分流为
    //   nanosleep，与真阻塞等价）。旧口径下 main 睡多久，就绪协程就饿多久——「go 后 sleep 让 worker
    //   跑」的 Go 式用法完全失效（worker 直到 main 触达 channel/join/wait_all 才开始执行）。
    //   改后 main 挂定时器让出，dispatcher 在睡眠窗口内调度 worker；无协程时墙钟语义不变。
    concurrency.sleepNs(@as(u64, secs) * std.time.ns_per_s);
    return Value.initInt(0);
}

/// usleep - 延迟执行（微秒）
pub fn php_usleep(microseconds: Value) !Value {
    // ★F-62f 接线（门 BLT 段 H b169）：`usleep(): Argument #1 ($microseconds) must be of type int, Foo given`。
    const usecs_ok = requireNumParam("usleep", 1, "microseconds", .int_param, microseconds) orelse return Value.initNull();
    const usecs_raw = usecs_ok.toInt();
    // ★F-127（R-229）：负数 ValueError；正数按 32 位折叠
    if (usecs_raw < 0) {
        return throwThrowable("ValueError", "usleep(): Argument #1 ($microseconds) must be greater than or equal to 0", runtime_allocator);
    }
    const usecs_bits: u64 = @bitCast(usecs_raw);
    const usecs: c_uint = @truncate(usecs_bits);
    // ★Go 式协程 M1（D5=A）：协程内自动让出，main 内真阻塞。
    // ★G14：main 侧同样经调度器让出（见 php_sleep 注释）；无协程时等价 nanosleep。
    concurrency.sleepNs(@as(u64, usecs) * std.time.ns_per_us);
    return Value.initNull();
}

/// exit/die - 终止程序执行
/// ★F-96：register_shutdown_function 注册表（注册序执行；fatal/exit/正常出口统一触发）。
const ShutdownEntry = struct { callable: Value, args: []Value };
var shutdown_entries: ?std.ArrayList(ShutdownEntry) = null;
var shutdown_done: bool = false;
var shutdown_running: bool = false;

/// ★F-1-b：类名限定符解析（`self`/`parent`/`static` 按当前类作用域；其余常规类查找）。
///   `is_callable`/`is_callable_no_invoke` 与 go() spawn 校验共用同一口径。
fn resolveClassQualifierName(name: []const u8) ?*const ClassMeta {
    if (std.ascii.eqlIgnoreCase(name, "self")) {
        return getCurrentScopeClass() orelse getCurrentCalledClass();
    }
    if (std.ascii.eqlIgnoreCase(name, "static")) {
        return getCurrentCalledClass() orelse getCurrentScopeClass();
    }
    if (std.ascii.eqlIgnoreCase(name, "parent")) {
        const scope = getCurrentScopeClass() orelse return null;
        return scope.parent;
    }
    return findClass(name);
}

/// ★F-1-b：把 `self|static|parent::method` 的可调用形式改写为「具体类名」形式。
///   协程体不继承调用方的 class scope 快照 ⇒ 限定符必须在 spawn 点固化。
///   支持两种形态：字符串 `'self::m'` 与可调用数组 `['self','m']`。
///   返回 null 表示无需改写（非可调用形 / 非作用域限定符 / 当前无作用域可解析）。
fn q4ResolveScopeCallable(callable: Value, allocator: Allocator) ?Value {
    if (callable.isString()) {
        const nm = callable.asString().data;
        const sep = std.mem.indexOf(u8, nm, "::") orelse return null;
        if (sep == 0 or sep + 2 >= nm.len) return null;
        const meta = q4ScopeMetaOf(nm[0..sep]) orelse return null;
        var buf: [512]u8 = undefined;
        const full = std.fmt.bufPrint(&buf, "{s}::{s}", .{ meta.name, nm[sep + 2 ..] }) catch return null;
        const str = PHPString.init(allocator, full) catch return null;
        return Value.initString(str);
    }
    if (callable.isArray()) {
        const arr = callable.asArray();
        if (arr.elements.count() != 2) return null;
        const e0 = arr.elements.get(ArrayKey{ .integer = 0 }) orelse return null;
        const e1 = arr.elements.get(ArrayKey{ .integer = 1 }) orelse return null;
        if (!e0.isString() or !e1.isString()) return null;
        const meta = q4ScopeMetaOf(e0.asString().data) orelse return null;
        const new_cls = PHPString.init(allocator, meta.name) catch return null;
        defer new_cls.release(allocator);
        const new_arr = PHPArray.init(allocator) catch return null;
        defer new_arr.release(allocator);
        new_arr.push(allocator, Value.initString(new_cls)) catch return null;
        new_arr.push(allocator, e1) catch return null;
        _ = new_arr.retain();
        return Value.initArray(new_arr);
    }
    return null;
}

/// `self|static|parent` ⇒ 当前作用域类；其余名字返回 null（仅限作用域限定符改写）。
fn q4ScopeMetaOf(name: []const u8) ?*const ClassMeta {
    if (!std.ascii.eqlIgnoreCase(name, "self") and
        !std.ascii.eqlIgnoreCase(name, "static") and
        !std.ascii.eqlIgnoreCase(name, "parent"))
    {
        return null;
    }
    return resolveClassQualifierName(name);
}

/// ★F-96：无副作用可调用判定（`php_is_callable` 的 AOT hook 会**执行**可调用体，注册场景不可用）。
fn isCallableNoInvoke(val: Value) bool {
    const v = if (val.isRef()) val.asRef().* else val;
    if (v.isFunction()) return true;
    if (v.isString()) {
        const name = v.asString().data;
        if (lookupBuiltinFunction(name) != null) return true;
        if (lookupUserFunctionCI(name) != null) return true;
        if (std.mem.indexOf(u8, name, "::")) |sep| {
            const meta = resolveClassQualifierName(name[0..sep]) orelse return false;
            return meta.findMethodLookup(name[sep + 2 ..]) != null;
        }
        return false;
    }
    if (v.isArray()) {
        const arr = v.asArray();
        if (arr.elements.count() != 2) return false;
        const e0 = arr.elements.get(ArrayKey{ .integer = 0 }) orelse return false;
        const e1 = arr.elements.get(ArrayKey{ .integer = 1 }) orelse return false;
        if (!e1.isString()) return false;
        const m = e1.asString().data;
        if (Value_isObject(e0)) {
            const meta = Value_asObject(e0).class_meta orelse return false;
            return meta.findMethodLookup(m) != null;
        }
        if (e0.isString()) {
            // ★F-1-b：作用域限定符（self/parent/static）与常规类名同口径解析
            const meta = resolveClassQualifierName(e0.asString().data) orelse return false;
            return meta.findMethodLookup(m) != null;
        }
        return false;
    }
    // 闭包对象：交给 invoke 处理
    return Value_isObject(v);
}

pub fn php_register_shutdown_function(callable: Value, rest: []const Value, allocator: Allocator) !Value {
    _ = allocator;
    if (!isCallableNoInvoke(callable)) {
        var buf: [512]u8 = undefined;
        const msg = if (callable.isString())
            std.fmt.bufPrint(&buf, "register_shutdown_function(): Argument #1 ($callback) must be a valid callback, function \"{s}\" not found or invalid function name", .{callable.asString().data}) catch "register_shutdown_function(): Argument #1 ($callback) must be a valid callback"
        else
            "register_shutdown_function(): Argument #1 ($callback) must be a valid callback";
        return throwThrowable("TypeError", msg, runtime_allocator);
    }
    if (shutdown_entries == null) shutdown_entries = std.ArrayList(ShutdownEntry).empty;
    const copied = try runtime_allocator.alloc(Value, rest.len);
    for (rest, 0..) |raw, i| {
        var v = raw;
        _ = v.retain();
        copied[i] = v;
    }
    var cb = callable;
    _ = cb.retain();
    try shutdown_entries.?.append(runtime_allocator, .{ .callable = cb, .args = copied });
    return Value.initNull();
}

/// 执行注册的 shutdown 回调（注册序）。回调内抛异常 ⇒ 走未捕获 fatal 并停止后续回调（PHP 实测）。
pub fn php_run_shutdown_functions() void {
    if (shutdown_done or shutdown_running) return;
    shutdown_running = true;
    defer shutdown_done = true;
    if (shutdown_entries) |*list| {
        var i: usize = 0;
        while (i < list.items.len) : (i += 1) {
            const entry = list.items[i];
            const ret = php_invoke_callable(entry.callable, entry.args, runtime_allocator) catch Value.initNull();
            ret.release(runtime_allocator);
            if (hasException()) php_handle_uncaught_exception();
        }
        for (list.items) |entry| {
            entry.callable.release(runtime_allocator);
            for (entry.args) |raw| {
                var v = raw;
                v.release(runtime_allocator);
            }
            runtime_allocator.free(entry.args);
        }
        list.deinit(runtime_allocator);
        shutdown_entries = null;
    }
}

pub fn php_exit(status: Value) !noreturn {
    if (status.isString()) {
        fileWriteAll(1, status.asString().data);
        php_run_shutdown_functions();
        std.process.exit(0);
    }
    php_run_shutdown_functions();
    const code: u8 = if (status.isInt())
        @truncate(@as(u64, @intCast(status.asInt() & 0xFF)))
    else
        0;
    std.process.exit(code);
}

/// php_empty_val - 纯 bool 版本的 empty 检查（不返回 Value，不触发错误）
/// ★F-142-b：`empty($arr[$k])` —— 缺失/不可见/非数组都静默返回 true；有值复用 php_empty_val。
///   读路径复用 coalesce（ArrayAccess 走 offsetExists→offsetGet；非 ArrayAccess 对象按 PHP 抛 Error）。
pub fn php_array_empty(arr_val: Value, key_val: Value, allocator: Allocator) !Value {
    const v = try php_array_get_coalesce(arr_val, key_val, allocator);
    defer v.release(allocator);
    return Value.initBool(php_empty_val(v));
}

pub fn php_empty_val(val: Value) bool {
    if (val.isNull()) return true;
    if (val.isBool()) return !val.asBool();
    if (val.isInt()) return val.asInt() == 0;
    if (val.isFloat()) return val.asFloat() == 0;
    if (val.isString()) return val.asString().length == 0 or std.mem.eql(u8, val.asString().data, "0");
    if (val.isArray()) return val.asArray().count() == 0;
    return false;
}

/// empty - 检查变量是否为空
pub fn php_empty(val: Value) !Value {
    if (val.isNull()) return Value.initBool(true);
    if (val.isBool()) return Value.initBool(!val.asBool());
    if (val.isInt()) return Value.initBool(val.asInt() == 0);
    if (val.isFloat()) return Value.initBool(val.asFloat() == 0);
    if (val.isString()) return Value.initBool(val.asString().length == 0 or std.mem.eql(u8, val.asString().data, "0"));
    if (val.isArray()) return Value.initBool(val.asArray().count() == 0);
    return Value.initBool(false);
}

/// isset - 检查变量是否已设置且非null（支持多个参数）
pub fn php_isset(args: []const Value) !Value {
    // isset()需要至少1个参数
    if (args.len == 0) return Value.initBool(false);

    // 所有参数都必须非null才返回true
    for (args) |val| {
        if (val.isNull()) return Value.initBool(false);
    }

    return Value.initBool(true);
}

pub fn empty(val: Value) !Value {
    return php_empty(val);
}

pub fn isset(val: Value) !Value {
    // 单参数版本的包装器
    return Value.initBool(!val.isNull());
}

// ============================================================================
// PCNTL / POSIX / IPC 函数
// ============================================================================

// libc 外部声明
extern "c" fn fork() std.posix.pid_t;
extern "c" fn waitpid(
    pid: std.posix.pid_t,
    status: *c_int,
    options: c_int,
) std.posix.pid_t;
extern "c" fn kill(
    pid: std.posix.pid_t,
    sig: c_int,
) c_int;
extern "c" fn alarm(seconds: c_uint) c_uint;
extern "c" fn getpid() std.posix.pid_t;
extern "c" fn signal(
    sig: c_int,
    handler: ?*const fn (c_int) callconv(.c) void,
) ?*const fn (c_int) callconv(.c) void;
extern "c" fn mkfifo(
    path: [*:0]const u8,
    mode: std.posix.mode_t,
) c_int;
extern "c" fn socketpair(
    domain: c_int,
    sock_type: c_int,
    protocol: c_int,
    sv: *[2]c_int,
) c_int;
extern "c" fn close(fd: c_int) c_int;

// System V IPC 外部声明
extern "c" fn msgget(key: c_int, msgflg: c_int) c_int;
extern "c" fn msgctl(
    msqid: c_int,
    cmd: c_int,
    buf: ?*anyopaque,
) c_int;
extern "c" fn semget(
    key: c_int,
    nsems: c_int,
    semflg: c_int,
) c_int;
extern "c" fn semctl(
    semid: c_int,
    semnum: c_int,
    cmd: c_int,
) c_int;
extern "c" fn shmget(
    key: c_int,
    size: usize,
    shmflg: c_int,
) c_int;
extern "c" fn shmctl(
    shmid: c_int,
    cmd: c_int,
    buf: ?*anyopaque,
) c_int;

const IPC_CREAT = 0o1000;
const IPC_RMID = 0;
const MAX_SIGNALS = 32;

var signal_handlers: [MAX_SIGNALS]Value = blk: {
    var arr: [MAX_SIGNALS]Value = undefined;
    for (0..MAX_SIGNALS) |i| arr[i] = Value.initNull();
    break :blk arr;
};
var pending_signals: [MAX_SIGNALS]bool = blk: {
    var arr: [MAX_SIGNALS]bool = undefined;
    for (0..MAX_SIGNALS) |i| arr[i] = false;
    break :blk arr;
};
var last_wait_status: c_int = 0;

/// C 信号处理函数（仅设置标志位）
fn pcntl_c_signal_handler(sig: c_int) callconv(.c) void {
    const s: usize = @intCast(@max(0, sig));
    if (s < MAX_SIGNALS) {
        pending_signals[s] = true;
    }
}

/// pcntl_fork - 创建子进程
pub fn php_pcntl_fork() !Value {
    const pid = fork();
    return Value.initInt(@intCast(pid));
}

/// pcntl_waitpid - 等待指定子进程
pub fn php_pcntl_waitpid(
    pid_val: Value,
    _: Value,
    _: Allocator,
) !Value {
    const pid: std.posix.pid_t = @intCast(pid_val.toInt());
    var status: c_int = 0;
    const result = waitpid(pid, &status, 0);
    last_wait_status = status;
    return Value.initInt(@intCast(result));
}

/// pcntl_wait - 等待任意子进程
pub fn php_pcntl_wait(_: Value, _: Allocator) !Value {
    var status: c_int = 0;
    const result = waitpid(-1, &status, 0);
    last_wait_status = status;
    return Value.initInt(@intCast(result));
}

/// pcntl_wexitstatus - 提取子进程退出码
pub fn php_pcntl_wexitstatus(_: Value) !Value {
    const exit_code = (last_wait_status >> 8) & 0xFF;
    return Value.initInt(@intCast(exit_code));
}

/// pcntl_signal - 注册信号处理器
pub fn php_pcntl_signal(
    signo_val: Value,
    handler_val: Value,
    _: Allocator,
) !Value {
    const signo: usize = @intCast(
        @max(0, signo_val.toInt()),
    );
    if (signo >= MAX_SIGNALS) return Value.initBool(false);
    _ = handler_val.retain();
    signal_handlers[signo].release(runtime_allocator);
    signal_handlers[signo] = handler_val;
    _ = signal(
        @intCast(signo),
        pcntl_c_signal_handler,
    );
    return Value.initBool(true);
}

/// pcntl_signal_dispatch - 分派待处理信号
pub fn php_pcntl_signal_dispatch(_: Allocator) !Value {
    for (0..MAX_SIGNALS) |i| {
        if (pending_signals[i]) {
            pending_signals[i] = false;
            const handler = signal_handlers[i];
            if (!handler.isNull() and handler.isFunction()) {
                const closure = handler.asFunction();
                _ = closure.func(
                    handler,
                    &[_]Value{Value.initInt(@intCast(i))},
                    runtime_allocator,
                ) catch {};
            }
        }
    }
    return Value.initBool(true);
}

/// pcntl_alarm - 设置闹钟信号
pub fn php_pcntl_alarm(seconds_val: Value) !Value {
    const secs: c_uint = @intCast(
        @max(0, seconds_val.toInt()),
    );
    const prev = alarm(secs);
    return Value.initInt(@intCast(prev));
}

/// pcntl_sigprocmask - 设置信号屏蔽字
pub fn php_pcntl_sigprocmask(
    _: Value,
    _: Value,
    _: Allocator,
) !Value {
    return Value.initBool(true);
}

/// posix_getpid - 获取当前进程 ID
pub fn php_posix_getpid() !Value {
    return Value.initInt(@intCast(getpid()));
}

/// posix_kill - 向进程发送信号
pub fn php_posix_kill(
    pid_val: Value,
    sig_val: Value,
) !Value {
    const pid: std.posix.pid_t = @intCast(
        pid_val.toInt(),
    );
    const sig: c_int = @intCast(sig_val.toInt());
    const ret = kill(pid, sig);
    return Value.initBool(ret == 0);
}

/// posix_mkfifo - 创建 FIFO 特殊文件
pub fn php_posix_mkfifo(
    path_val: Value,
    mode_val: Value,
    allocator: Allocator,
) !Value {
    const path_str = try path_val.toString(allocator);
    defer path_str.release(allocator);
    const mode: std.posix.mode_t = @intCast(
        @max(0, mode_val.toInt()),
    );
    // ★批次十七①：dupeSentinel 门径是 3 参（:7324 同族），旧多传一枚 0 ⇒ 直调 posix_mkfifo 此前同样编不过，登记后懒分析暴露。
    const path_z = try allocator.dupeSentinel(u8, path_str.data, 0);
    defer allocator.free(path_z);
    const ret = mkfifo(path_z, mode);
    return Value.initBool(ret == 0);
}

/// ftok - 生成 System V IPC 键值
pub fn php_ftok(
    path_val: Value,
    proj_val: Value,
    allocator: Allocator,
) !Value {
    const path_str = try path_val.toString(allocator);
    defer path_str.release(allocator);
    const proj_str = try proj_val.toString(allocator);
    defer proj_str.release(allocator);
    const proj_id: i64 = if (proj_str.data.len > 0)
        @intCast(proj_str.data[0])
    else
        0;
    // 简化 ftok: 使用路径哈希 + proj_id
    var hash: u32 = 0;
    for (path_str.data) |c| {
        hash = hash *% 31 +% @as(u32, c);
    }
    const key = (@as(i64, proj_id) << 24) |
        @as(i64, hash & 0xFFFFFF);
    return Value.initInt(key);
}

/// msg_get_queue - 获取消息队列
pub fn php_msg_get_queue(
    key_val: Value,
    allocator: Allocator,
) !Value {
    const key: c_int = @intCast(key_val.toInt());
    const id = msgget(key, IPC_CREAT | 0o666);
    if (id < 0) return Value.initBool(false);
    _ = allocator;
    return Value.initInt(@intCast(id));
}

/// msg_remove_queue - 删除消息队列
pub fn php_msg_remove_queue(queue_val: Value) !Value {
    const id: c_int = @intCast(queue_val.toInt());
    const ret = msgctl(id, IPC_RMID, null);
    return Value.initBool(ret == 0);
}

/// sem_get - 获取信号量
pub fn php_sem_get(
    key_val: Value,
    max_val: Value,
    allocator: Allocator,
) !Value {
    _ = allocator;
    const key: c_int = @intCast(key_val.toInt());
    const nsems: c_int = @intCast(
        @max(1, max_val.toInt()),
    );
    const id = semget(key, nsems, IPC_CREAT | 0o666);
    if (id < 0) return Value.initBool(false);
    return Value.initInt(@intCast(id));
}

/// sem_remove - 删除信号量
pub fn php_sem_remove(sem_val: Value) !Value {
    const id: c_int = @intCast(sem_val.toInt());
    const ret = semctl(id, 0, IPC_RMID);
    return Value.initBool(ret == 0);
}

/// shmop_open - 打开共享内存段
pub fn php_shmop_open(
    key_val: Value,
    flags_val: Value,
    mode_val: Value,
    size_val: Value,
    allocator: Allocator,
) !Value {
    _ = allocator;
    _ = flags_val;
    const key: c_int = @intCast(key_val.toInt());
    const mode: c_int = @intCast(
        @max(0, mode_val.toInt()),
    );
    const size: usize = @intCast(
        @max(1, size_val.toInt()),
    );
    const id = shmget(key, size, IPC_CREAT | mode);
    if (id < 0) return Value.initBool(false);
    return Value.initInt(@intCast(id));
}

/// shmop_close - 关闭共享内存段
pub fn php_shmop_close(_: Value) !Value {
    return Value.initBool(true);
}

/// socket_create_pair - 创建套接字对
pub fn php_socket_create_pair(
    domain_val: Value,
    type_val: Value,
    protocol_val: Value,
    _: Value,
    allocator: Allocator,
) !Value {
    const domain: c_int = @intCast(domain_val.toInt());
    const sock_type: c_int = @intCast(
        type_val.toInt(),
    );
    const protocol: c_int = @intCast(
        protocol_val.toInt(),
    );
    var sv: [2]c_int = .{ -1, -1 };
    const ret = socketpair(
        domain,
        sock_type,
        protocol,
        &sv,
    );
    if (ret != 0) return Value.initBool(false);
    const arr = try PHPArray.init(allocator);
    try arr.push(allocator, Value.initInt(sv[0]));
    try arr.push(allocator, Value.initInt(sv[1]));
    return Value.initArray(arr);
}

/// socket_close - 关闭套接字
pub fn php_socket_close(fd_val: Value) !Value {
    const fd: c_int = @intCast(fd_val.toInt());
    _ = close(fd);
    return Value.initBool(true);
}

// ============================================================================
// 高阶数组函数
// ============================================================================

/// array_map - 对一个或多个数组的每个元素应用回调函数
pub fn php_array_map(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return error.InvalidArgumentCount;

    const callback = args[0];
    const arrays = args[1..];
    for (arrays) |arr| {
        if (!arr.isArray()) return error.InvalidArgument;
    }

    const result_arr = try PHPArray.init(allocator);

    if (callback.isNull()) {
        if (arrays.len == 1) {
            const src = arrays[0].asArray();
            var src_iter = src.elements.iterator();
            while (src_iter.next()) |entry| {
                try result_arr.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
            }
            return Value.initArray(result_arr);
        }

        var max_count: i64 = 0;
        for (arrays) |arr| {
            const cur = arr.asArray();
            if (cur.next_index > max_count) max_count = cur.next_index;
        }

        var idx: i64 = 0;
        while (idx < max_count) : (idx += 1) {
            const tuple_arr = try PHPArray.init(allocator);
            const key = ArrayKey{ .integer = idx };

            for (arrays) |arr| {
                const cur = arr.asArray();
                const val = cur.get(key) orelse Value.initNull();
                try tuple_arr.push(allocator, val);
            }

            try result_arr.push(allocator, Value.initArray(tuple_arr));
        }

        return Value.initArray(result_arr);
    }

    const primary = arrays[0].asArray();

    // 预提取所有数组的值列表（按位置索引）
    // PHP array_map 多数组语义：按位置而非键匹配
    const all_values = try allocator.alloc([]Value, arrays.len);
    defer {
        for (all_values) |vals| allocator.free(vals);
        allocator.free(all_values);
    }
    for (arrays, 0..) |arr, ai| {
        const cur = arr.asArray();
        const vals = try allocator.alloc(Value, cur.count());
        var ci: usize = 0;
        var it = cur.elements.iterator();
        while (it.next()) |e| : (ci += 1) {
            vals[ci] = e.value_ptr.*;
        }
        all_values[ai] = vals;
    }

    var iter = primary.elements.iterator();
    var pos: usize = 0;
    while (iter.next()) |entry| {
        var callback_args = try allocator.alloc(Value, arrays.len);
        defer allocator.free(callback_args);

        for (arrays, 0..) |_, ai| {
            if (ai < all_values.len and pos < all_values[ai].len) {
                callback_args[ai] = all_values[ai][pos];
            } else {
                callback_args[ai] = Value.initNull();
            }
        }

        const result_value = try php_invoke_callable(callback, callback_args, allocator);
        try result_arr.set(allocator, entry.key_ptr.*, result_value);
        result_value.release(allocator);
        pos += 1;
    }

    return Value.initArray(result_arr);
}

/// array_filter - 过滤数组元素
/// mode: 0 = 只传值, 1 = 传值和键 (ARRAY_FILTER_USE_BOTH), 2 = 传键 (ARRAY_FILTER_USE_KEY)
pub fn php_array_filter(arr: Value, callback: Value, mode: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);
    const mode_int: u32 = if (mode.isInt()) @intCast(@max(mode.asInt(), 0)) else 0;

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const should_keep = if (callback.isNull()) blk: {
            // 无回调时，检查值是否为真
            break :blk entry.value_ptr.*.toBool();
        } else blk: {
            // 根据mode决定传参方式
            const result = switch (mode_int) {
                0 => blk2: {
                    // ARRAY_FILTER_USE_VALUE (默认) - 只传值
                    const args = [_]Value{entry.value_ptr.*};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                1 => blk2: {
                    // ARRAY_FILTER_USE_BOTH - 传值和键
                    const key_val = switch (entry.key_ptr.*) {
                        .integer => |k| Value.initInt(k),
                        .string => |s| blk_s: {
                            s.retain(); // 增加引用计数
                            break :blk_s Value.initString(s);
                        },
                    };
                    const args = [_]Value{ entry.value_ptr.*, key_val };
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                2 => blk2: {
                    // ARRAY_FILTER_USE_KEY - 只传键
                    const key_val = switch (entry.key_ptr.*) {
                        .integer => |k| Value.initInt(k),
                        .string => |s| blk_s: {
                            s.retain(); // 增加引用计数
                            break :blk_s Value.initString(s);
                        },
                    };
                    const args = [_]Value{key_val};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                else => blk2: {
                    // 默认行为：只传值
                    const args = [_]Value{entry.value_ptr.*};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
            };
            defer result.release(allocator);
            break :blk result.toBool();
        };

        if (should_keep) {
            try result_arr.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        }
    }

    return Value.initArray(result_arr);
}

/// array_reduce - 使用回调函数迭代地将数组简化为单一值
pub fn php_array_reduce(arr: Value, callback: Value, initial: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    var carry = initial.retain();

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{ carry, entry.value_ptr.* };
        const new_carry = try php_invoke_callable(callback, &args, allocator);
        carry.release(allocator);
        carry = new_carry;
    }

    return carry;
}

/// array_find - 查找数组中第一个满足回调条件的元素 (PHP 8.4+)
pub fn php_array_find(arr: Value, callback: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();

    const php_arr = arr.asArray();
    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{entry.value_ptr.*};
        const result = try php_invoke_callable(callback, &args, allocator);
        defer result.release(allocator);
        if (result.toBool()) {
            return entry.value_ptr.*.retain();
        }
    }
    return Value.initNull();
}

/// array_find_key - PHP 8.4: 返回第一个满足回调的元素的键
pub fn php_array_find_key(arr: Value, callback: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();
    const php_arr = arr.asArray();
    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{entry.value_ptr.*};
        const result = try php_invoke_callable(callback, &args, allocator);
        defer result.release(allocator);
        if (result.toBool()) {
            return switch (entry.key_ptr.*) {
                // ★批次十六③：ArrayKey 成员名是 .integer（:2324），旧写 .int 永不可达——变量表登记后 Zig 懒分析才暴露；直调 array_find_key 此前同样编不过。
                .integer => |k| Value.initInt(k),
                .string => |s| Value.initString(try PHPString.init(allocator, s.data)),
            };
        }
    }
    return Value.initNull();
}

/// array_chunk - 将数组分割成指定大小的块
/// array_chunk - 将数组分割成指定大小的块
pub fn php_array_chunk(arr: Value, size: Value, preserve_keys: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b161）：形参名实测是 **`$length`**（不是模板变量名 `size`）——
    //   `array_chunk(): Argument #2 ($length) must be of type int, Foo given`。
    //   ★本臂是 R-194 修前**唯一 `zig_escape=1`** 的来源：修前对象先被 `size.toInt()` 折成 0，
    //   再撞上下面 `chunk_size < 1` 的 `return error.InvalidArgument` ⇒ Zig 错误外逸成 PHP 不可见的失败。
    //   接线的正确位置在早退**之前**，于是 b161 与 escape 同时消失；而 `<1` 那条分支自身是另一枚面（ValueError，工单 §104.3），本批不动。
    const size_ok = requireNumParam("array_chunk", 2, "length", .int_param, size) orelse return Value.initNull();
    if (!arr.isArray()) return error.InvalidArgument;

    const chunk_size = size_ok.toInt();
    // ★F-126（R-229）：length<1 是 ValueError（原先 error.InvalidArgument 外逸）
    if (chunk_size < 1) {
        return throwThrowable("ValueError", "array_chunk(): Argument #2 ($length) must be greater than 0", runtime_allocator);
    }

    const preserve = preserve_keys.toBool();
    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);

    var current_chunk = try PHPArray.init(allocator);
    var count: i64 = 0;
    var new_index: i64 = 0;

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        if (preserve) {
            try current_chunk.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        } else {
            try current_chunk.push(allocator, entry.value_ptr.*);
        }
        count += 1;

        if (count >= chunk_size) {
            try result_arr.set(allocator, .{ .integer = new_index }, Value.initArray(current_chunk));
            new_index += 1;
            current_chunk = try PHPArray.init(allocator);
            count = 0;
        }
    }

    if (count > 0) {
        try result_arr.set(allocator, .{ .integer = new_index }, Value.initArray(current_chunk));
    } else {
        current_chunk.release(allocator);
    }

    return Value.initArray(result_arr);
}

/// array_column - 返回数组中指定列的值
pub fn php_array_column(arr: Value, column_key: Value, index_key: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const row = entry.value_ptr.*;
        if (!row.isArray()) continue;

        const row_arr = row.asArray();

        // 获取列值
        const col_value = if (column_key.isInt()) blk: {
            break :blk row_arr.get(.{ .integer = column_key.asInt() });
        } else if (column_key.isString()) blk: {
            break :blk arrayGetByString(row_arr, column_key.asString().data);
        } else blk: {
            break :blk null;
        };

        if (col_value) |val| {
            // 确定索引
            if (index_key.isNull()) {
                try result_arr.push(allocator, val);
            } else {
                const idx_value = if (index_key.isInt()) blk: {
                    break :blk row_arr.get(.{ .integer = index_key.asInt() });
                } else if (index_key.isString()) blk: {
                    break :blk arrayGetByString(row_arr, index_key.asString().data);
                } else blk: {
                    break :blk null;
                };

                if (idx_value) |idx| {
                    if (idx.isInt()) {
                        try result_arr.set(allocator, .{ .integer = idx.asInt() }, val);
                    } else if (idx.isString()) {
                        try arraySetByString(result_arr, allocator, idx.asString().data, val);
                    } else {
                        try result_arr.push(allocator, val);
                    }
                } else {
                    try result_arr.push(allocator, val);
                }
            }
        }
    }

    return Value.initArray(result_arr);
}

/// array_walk - 对数组中的每个元素应用用户自定义函数
/// @enhancement AOT超越PHP: 首参数允许数组字面量(PHP解释器报Fatal Error: could not be passed by reference)
pub fn php_array_walk(arr: Value, callback: Value, userdata: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        // 构建回调参数：value(by-ref), key, userdata
        const key_val = switch (entry.key_ptr.*) {
            .integer => |k| Value.initInt(k),
            .string => |k| Value.initString(k),
        };

        // array_walk 的回调第一个参数按引用传递（PHP 规范）
        // 直接用 entry.value_ptr 构造 Ref，使回调内对 $value 的赋值写回数组槽位
        // iterator 返回 *const Value，此处需要可写指针以实现引用语义
        var args_buf: [3]Value = undefined;
        // AOT-REF-002 R-1b：引用装槽（make_ref）而非直接锚住迭代期容器槽地址——
        // 回调内扩容会搬迁桶数组，槽地址随之悬垂；装槽后容器槽自身存 Ref，
        // 单元地址恒不变，回调写回经该单元落到容器。
        args_buf[0] = try make_ref(@constCast(entry.value_ptr), allocator);
        args_buf[1] = key_val;
        const arg_count: usize = if (userdata.isNull()) 2 else blk: {
            args_buf[2] = userdata;
            break :blk 3;
        };

        const result = try php_invoke_callable(callback, args_buf[0..arg_count], allocator);
        result.release(allocator);
    }

    return Value.initBool(true);
}

fn php_array_walk_recursive_inner(arr: *PHPArray, callback: Value, userdata: Value, allocator: Allocator) !void {
    var iter = arr.elements.iterator();
    while (iter.next()) |entry| {
        const value = entry.value_ptr.*;
        if (value.isArray()) {
            try php_array_walk_recursive_inner(value.asArray(), callback, userdata, allocator);
            continue;
        }

        const key_val = switch (entry.key_ptr.*) {
            .integer => |k| Value.initInt(k),
            .string => |k| Value.initString(k),
        };

        var args_buf: [3]Value = undefined;
        // ★批次十四⑥：叶子首参 by-ref 装槽（AOT-REF-002 R-1b 同 php_array_walk 成例）——
        //   旧形按值拷贝传参，回调对 &$v 的赋值落不到容器槽（实测回调整体不生效）；
        //   make_ref 后容器槽自身存 Ref，回调写回经 cell 落到容器。数组值语义不受装槽影响。
        args_buf[0] = try make_ref(@constCast(entry.value_ptr), allocator);
        args_buf[1] = key_val;
        const arg_count: usize = if (userdata.isNull()) 2 else blk: {
            args_buf[2] = userdata;
            break :blk 3;
        };

        const result = try php_invoke_callable(callback, args_buf[0..arg_count], allocator);
        result.release(allocator);
    }
}

/// @enhancement AOT超越PHP: 首参数允许数组字面量(PHP解释器报Fatal Error: could not be passed by reference)
pub fn php_array_walk_recursive(arr: Value, callback: Value, userdata: Value, allocator: Allocator) !Value {
    // ★批次十四⑥：非数组首参 ⇒ 可捕获 TypeError（PHP 8.5.8 口径；旧裸 error.InvalidArgument
    //   无挂起异常 ⇒ 顶层 Uncaught RuntimeError 文案失真）
    if (!arr.isArray()) return throwArgTypeError("array_walk_recursive", 1, "array", "array", arr, allocator);
    try php_array_walk_recursive_inner(arr.asArray(), callback, userdata, allocator);
    return Value.initBool(true);
}

// ============================================================================
// 字符串高级函数
// ============================================================================

/// 格式化浮点数到指定精度（用于 sprintf %f）
/// 使用 C 的 snprintf 以匹配 PHP 的浮点舍入行为
extern fn snprintf(buf: [*]u8, size: usize, fmt: [*:0]const u8, ...) c_int;
fn formatFloatPrecision(buf: []u8, val: f64, precision: usize) []const u8 {
    var fmt_buf: [16]u8 = undefined;
    const fmt_str = std.fmt.bufPrintSentinel(&fmt_buf, "%.{d}f", .{precision}, 0) catch "%.6f";
    const len = snprintf(buf.ptr, buf.len, fmt_str.ptr, val);
    if (len > 0 and @as(usize, @intCast(len)) < buf.len) {
        return buf[0..@intCast(len)];
    }
    return std.fmt.bufPrint(buf, "{d:.6}", .{val}) catch "0";
}

/// ★F-165（R-316）：sprintf 浮点 `%f/%F/%e/%E` 的非有限值拼写。
/// PHP 8.5.8 实测：INF ⇒ `INF`／`-INF` ⇒ `-INF`／NAN ⇒ `NaN`（与 echo 的 `NAN` 大小写不同）。
/// 旧实现：`%f` 走 C `snprintf` ⇒ 输出小写 `inf`/`nan`；`%e` 的规格化循环对 INF **永不收敛**
///（`INF/10 == INF`）⇒ 死循环（探针 rc=124）。
fn phpFmtSpecialFloat(val: f64) ?[]const u8 {
    if (std.math.isNan(val)) return "NaN";
    if (std.math.isInf(val)) return if (val < 0) "-INF" else "INF";
    return null;
}

/// ★F-166（R-317）：`snprintf("%.*e")` 归一化取尾数与十进制指数（%g 的判定基础）。
fn formatFloatExpNorm(buf: []u8, val: f64, prec: usize) []const u8 {
    var fmt_buf: [16]u8 = undefined;
    const fmt_str = std.fmt.bufPrintSentinel(&fmt_buf, "%.{d}e", .{prec}, 0) catch "%.6e";
    const len = snprintf(buf.ptr, buf.len, fmt_str.ptr, val);
    if (len > 0 and @as(usize, @intCast(len)) < buf.len) return buf[0..@intCast(len)];
    return "0e+0";
}

/// ★F-166（R-317）：PHP 的 `%g`（C 语义 + PHP 两处特化，均由 8.5.8 实测钉死）：
///   · 精度 P＝有效数字位数（默认 6；`%.0g` 视作 1）→ 先按 `%.{P-1}e` 取**舍入后**的尾数与指数
///     （进位会改指数：999999.5 ⇒ 1.0e+6）；
///   · `exp < -4 或 exp >= P` ⇒ 指数形，尾数**去尾零但至少保留一位小数**（1.0e-5、1.0e+6）；
///   · 否则定点形，小数位＝`P-1-exp`，去尾零并去孤点（0.0001、123456、1.5、0）。
fn formatG(buf: []u8, val: f64, prec_req: usize, upper: bool) []const u8 {
    const p: usize = if (prec_req == 0) 1 else prec_req;
    var ebuf: [96]u8 = undefined;
    const estr = formatFloatExpNorm(&ebuf, val, p - 1);
    const epos = std.mem.indexOfScalar(u8, estr, 'e') orelse return estr;
    var mant = estr[0..epos];
    const exp_val = std.fmt.parseInt(i32, estr[epos + 1 ..], 10) catch 0;
    // 尾数去尾零（保留至少一位小数）
    if (std.mem.indexOfScalar(u8, mant, '.')) |dot| {
        var end = mant.len;
        while (end > dot + 2 and mant[end - 1] == '0') end -= 1;
        mant = mant[0..end];
    }
    if (exp_val < -4 or exp_val >= @as(i32, @intCast(p))) {
        // PHP 特化：指数形的尾数**至少保留一位小数**（`%.1g` ⇒ `1.0e+6`，而 C 给 `1e+06`）
        var mbuf2: [80]u8 = undefined;
        var mant_out: []const u8 = mant;
        if (std.mem.indexOfScalar(u8, mant, '.') == null) {
            mant_out = std.fmt.bufPrint(&mbuf2, "{s}.0", .{mant}) catch mant;
        }
        const sign_str: []const u8 = if (exp_val < 0) "-" else "+";
        const exp_abs: u32 = @intCast(if (exp_val < 0) -exp_val else exp_val);
        return std.fmt.bufPrint(buf, "{s}{c}{s}{d}", .{
            mant_out,
            if (upper) @as(u8, 'E') else @as(u8, 'e'),
            sign_str,
            exp_abs,
        }) catch mant_out;
    }
    const decimals_i: i32 = @as(i32, @intCast(p - 1)) - exp_val;
    const decimals: usize = if (decimals_i < 0) 0 else @intCast(decimals_i);
    var fbuf: [128]u8 = undefined;
    const fstr = formatFloatPrecision(&fbuf, val, decimals);
    var fend = fstr.len;
    while (fend > 1 and fstr[fend - 1] == '0' and std.mem.indexOfScalar(u8, fstr[0..fend], '.') != null) fend -= 1;
    if (fend > 1 and fstr[fend - 1] == '.') fend -= 1;
    const out = fstr[0..fend];
    if (out.len <= buf.len) {
        @memcpy(buf[0..out.len], out);
        return buf[0..out.len];
    }
    return out;
}

/// sprintf - 格式化字符串
pub fn php_sprintf(format: Value, args: []const Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;

    const fmt = format.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var arg_idx: usize = 0;
    var i: usize = 0;

    while (i < fmt.len) {
        if (fmt[i] == '%' and i + 1 < fmt.len) {
            i += 1;
            if (fmt[i] == '%') {
                try result.append(allocator, '%');
                i += 1;
                continue;
            }

            // 解析位置参数 (n$)
            var explicit_arg_idx: ?usize = null;
            if (i < fmt.len and fmt[i] >= '1' and fmt[i] <= '9') {
                var pos: usize = 0;
                const num_start = i;
                while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                    pos = pos * 10 + (fmt[i] - '0');
                    i += 1;
                }
                if (i < fmt.len and fmt[i] == '$') {
                    explicit_arg_idx = pos - 1; // 转为 0-based
                    i += 1;
                } else {
                    // 不是位置参数，回退
                    i = num_start;
                }
            }

            // 解析标志
            var flag_minus = false;
            var flag_plus = false;
            var flag_zero = false;
            var pad_char: u8 = ' ';
            while (i < fmt.len) {
                switch (fmt[i]) {
                    '-' => flag_minus = true,
                    '+' => flag_plus = true,
                    // ★F-167（R-319）：PHP 8.5.8 实测**忽略**空格标志（`% f`⇒`1.250000`、
                    //   `% 5d`⇒`    3`、`% 05d`⇒`00003`、`% 10s`⇒8 空格+值），只消费不生效。
                    ' ' => {},
                    '0' => flag_zero = true,
                    '#' => return throwThrowable("ValueError", "Unknown format specifier \"#\"", allocator),
                    '\'' => {
                        // PHP custom pad char: %'x10s
                        i += 1;
                        if (i < fmt.len) {
                            pad_char = fmt[i];
                        }
                    },
                    else => break,
                }
                i += 1;
            }
            if (flag_zero and !flag_minus) pad_char = '0';

            // 解析宽度
            var width: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                width = width * 10 + (fmt[i] - '0');
                i += 1;
            }

            // 解析精度
            var precision: ?usize = null;
            if (i < fmt.len and fmt[i] == '.') {
                i += 1;
                var prec_val: usize = 0;
                while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                    prec_val = prec_val * 10 + (fmt[i] - '0');
                    i += 1;
                }
                precision = prec_val;
            }

            if (i >= fmt.len) break;

            const specifier = fmt[i];
            i += 1;

            // 使用位置参数或顺序参数
            const use_idx = explicit_arg_idx orelse arg_idx;
            if (explicit_arg_idx == null) arg_idx += 1;
            if (use_idx >= args.len) continue;
            const arg = args[use_idx];

            // Format the value into a temporary buffer, then apply width/padding
            var tmp_buf = try std.ArrayList(u8).initCapacity(allocator, 0);
            defer tmp_buf.deinit(allocator);

            switch (specifier) {
                's' => {
                    if (arg.isString()) {
                        const sdata = arg.asString().data;
                        if (precision) |prec| {
                            const len = @min(prec, sdata.len);
                            try tmp_buf.appendSlice(allocator, sdata[0..len]);
                        } else {
                            try tmp_buf.appendSlice(allocator, sdata);
                        }
                    } else {
                        const str = try arg.toString(allocator);
                        defer str.release(allocator);
                        if (precision) |prec| {
                            const len = @min(prec, str.data.len);
                            try tmp_buf.appendSlice(allocator, str.data[0..len]);
                        } else {
                            try tmp_buf.appendSlice(allocator, str.data);
                        }
                    }
                },
                'd', 'i' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    if (flag_plus and val >= 0) try tmp_buf.append(allocator, '+');
                    const str = try std.fmt.allocPrint(allocator, "{d}", .{val});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'f', 'F' => {
                    const val = arg.toFloat();
                    if (phpFmtSpecialFloat(val)) |sp| {
                        try tmp_buf.appendSlice(allocator, sp);
                    } else {
                        if (flag_plus and val >= 0) try tmp_buf.append(allocator, '+');
                        const prec = precision orelse 6;
                        var fbuf: [128]u8 = undefined;
                        const fstr = formatFloatPrecision(&fbuf, val, prec);
                        try tmp_buf.appendSlice(allocator, fstr);
                    }
                },
                'x' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{x}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'X' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{X}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'c' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    // ★F-81（工单 §64.2，根因已由"吞 NUL"改写为此条）：PHP 的 `%c` **恒发 1 字节＝低 8 位**，
                    //   与符号/范围无关（9 枚实测：`0→00`、`65→41`、`255→ff`、`256→00`、`321→41`、`-1→ff`、
                    //   `-255→01`、`-8446744073709551616→00`、`9223372036854775807→ff`）。
                    //   旧守卫 `val >= 0 and val <= 255` 的问题是对范围外**整字节丢弃**；NUL 本身 PHPString 保得住
                    //   （`:1483` 按 `str.len` 全量 memcpy）。★此处一处修四入口：printf/vprintf/vsprintf 都委托 php_sprintf。
                    try tmp_buf.append(allocator, @truncate(@as(u64, @bitCast(val))));
                },
                'u' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const uval: u64 = @bitCast(val);
                    const str = try std.fmt.allocPrint(allocator, "{d}", .{uval});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'o' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{o}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'b' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{b}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'g', 'G' => {
                    const val = arg.toFloat();
                    if (phpFmtSpecialFloat(val)) |sp| {
                        try tmp_buf.appendSlice(allocator, sp);
                    } else {
                        var gbuf: [160]u8 = undefined;
                        try tmp_buf.appendSlice(allocator, formatG(&gbuf, val, precision orelse 6, specifier == 'G'));
                    }
                },
                'e', 'E' => {
                    const val = arg.toFloat();
                    if (phpFmtSpecialFloat(val)) |sp| {
                        try tmp_buf.appendSlice(allocator, sp);
                    } else {
                    const prec = precision orelse 6;
                    // PHP %e 格式：[-]d.dddddde[+-]dd
                    var ebuf: [128]u8 = undefined;
                    const abs_val = if (val < 0) -val else val;
                    var exp: i32 = 0;
                    var mantissa = abs_val;
                    if (abs_val >= 1.0) {
                        while (mantissa >= 10.0) : (mantissa /= 10.0) exp += 1;
                    } else if (abs_val > 0.0) {
                        while (mantissa < 1.0) : (mantissa *= 10.0) exp -= 1;
                    }
                    // 格式化尾数
                    var fbuf: [64]u8 = undefined;
                    const fstr = formatFloatPrecision(&fbuf, mantissa, prec);
                    const sign_str = if (val < 0) "-" else if (flag_plus) "+" else "";
                    const exp_sign = if (exp >= 0) "+" else "-";
                    const exp_abs: u32 = @intCast(if (exp >= 0) exp else -exp);
                    const e_char: u8 = if (specifier == 'E') 'E' else 'e';
                    const formatted = std.fmt.bufPrint(&ebuf, "{s}{s}{c}{s}{d}", .{ sign_str, fstr, e_char, exp_sign, exp_abs }) catch "0";
                    try tmp_buf.appendSlice(allocator, formatted);
                    }
                },
                else => {
                    try result.append(allocator, '%');
                    try result.append(allocator, specifier);
                    continue;
                },
            }

            // Apply width padding
            const content = tmp_buf.items;
            if (width > 0 and content.len < width) {
                const padding = width - content.len;
                if (flag_minus) {
                    // Left-align: content first, then padding
                    try result.appendSlice(allocator, content);
                    for (0..padding) |_| try result.append(allocator, pad_char);
                } else {
                    // Right-align: padding first, then content
                    // For zero-padding with sign, put sign before zeros
                    if (pad_char == '0' and content.len > 0 and (content[0] == '-' or content[0] == '+' or content[0] == ' ')) {
                        try result.append(allocator, content[0]);
                        for (0..padding) |_| try result.append(allocator, '0');
                        try result.appendSlice(allocator, content[1..]);
                    } else {
                        for (0..padding) |_| try result.append(allocator, pad_char);
                        try result.appendSlice(allocator, content);
                    }
                }
            } else {
                try result.appendSlice(allocator, content);
            }
        } else {
            try result.append(allocator, fmt[i]);
            i += 1;
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// vsprintf - 格式化字符串（参数为数组）
pub fn php_vsprintf(format: Value, args_arr: Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    // 将数组参数展开为切片
    if (args_arr.isArray()) {
        const arr = args_arr.asArray();
        const count = arr.count();
        const args = try allocator.alloc(Value, count);
        defer allocator.free(args);
        var iter = arr.elements.iterator();
        var i: usize = 0;
        while (iter.next()) |entry| {
            if (i < count) {
                args[i] = entry.value_ptr.*;
                i += 1;
            }
        }
        return php_sprintf(format, args[0..i], allocator);
    }
    return php_sprintf(format, &[_]Value{}, allocator);
}

/// sscanf 直调面入口（★P0 批次二十四续：切片签名，php_fprintf/php_fscanf 同族打包；
///   旧定参实现（仅 %d/%s、无 by-ref、无 EOF 口径）由共享核 q4FscanfParse 全量替代）。
pub fn php_sscanf(args: []const Value, allocator: Allocator) !Value {
    return wrapBuiltin_sscanf(Value.initNull(), args, allocator);
}

/// preg_match / preg_match_all 的 offset 形参折算（PHP 8.5.8 实测）：
///   null 或 <=0 视为 0；超出 subject 长度时调用返回 false 且 matches 置空数组。
fn pcreSearchOffset(offset: Value, subject_len: usize) struct { start: usize, out_of_range: bool } {
    if (offset.isNull()) return .{ .start = 0, .out_of_range = false };
    const raw = offset.toInt();
    if (raw <= 0) return .{ .start = 0, .out_of_range = false };
    const as_len: usize = @intCast(raw);
    if (as_len > subject_len) return .{ .start = as_len, .out_of_range = true };
    return .{ .start = as_len, .out_of_range = false };
}

/// ★批次十二：by-ref matches 槽覆盖写——先释放槽内旧值再赋新值。
///   temp_reg 槽经 val_assign copy-in 独立持有一份 retain（nlk 调用方已 release+retain
///   抵消）⇒ `matches.* = X` 裸覆盖会净漏旧值一份引用；对 null/int 旧值 release 为 no-op。
inline fn pregMatchesAssign(matches: *Value, new_val: Value, allocator: Allocator) void {
    matches.*.release(allocator);
    matches.* = new_val;
}

pub fn php_preg_match(pattern: Value, subject: Value, matches: *Value, flags: Value, offset: Value, allocator: Allocator) !Value {
    // ★F-62f 余量（R-232）：#4 flags／#5 offset 必为 int（Foo ⇒ TypeError，先于 PREG_* 域检查）
    const flags_ok = requireOptionalNumParam("preg_match", 4, "flags", .int_param, flags) orelse return Value.initBool(false);
    const offset_ok = requireOptionalNumParam("preg_match", 5, "offset", .int_param, offset) orelse return Value.initBool(false);
    const flags_val: i64 = if (flags_ok.isNull()) 0 else flags_ok.toInt();
    if (pregMatchFlagsInvalid(flags_val)) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        throwThrowableDiscardCatch("ValueError", "preg_match(): Argument #4 ($flags) must be a PREG_* constant", allocator);
        return Value.initBool(false);
    }
    const offset_capture = (flags_val & PREG_OFFSET_CAPTURE_BIT) != 0;
    const unmatched_as_null = (flags_val & PREG_UNMATCHED_AS_NULL_BIT) != 0;

    if (!pattern.isString() or !subject.isString()) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initInt(0);
    }

    const pattern_str = pattern.asString();
    const subject_str = subject.asString();
    const parsed = parsePHPRegexPattern(pattern_str.data);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 false，不进 PCRE。
    // ★F-53（R-331）：编译前失败路径保留调用者预置值（不写即保留；同 preg_match_with_matches 支）。
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_match", parsed);
        return Value.initBool(false);
    }

    // 使用缓存获取编译后的正则
    // ★F-79d：本文件内另有 `preg_match` 的孪生实现（builtin_map 重复键，工单 §66.2-2/§70.2）⇒
    //   **两侧必须同语义**，否则"哪一行活着"会决定这里是否报警。
    // ★F-53（R-331）：编译失败同属编译前路径 ⇒ 保留预置值。
    const re = compileRegexOrWarn("preg_match", parsed, allocator) orelse {
        return Value.initBool(false);
    };

    const off = pcreSearchOffset(offset_ok, subject_str.length);
    if (off.out_of_range) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initBool(false);
    }

    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initInt(0);
    };
    defer pcre2_match_data_free_8(match_data);

    const rc = pcre2_match_8(
        re,
        subject_str.data.ptr,
        subject_str.length,
        @intCast(off.start),
        0,
        match_data,
        null,
    );
    recordPcreMatchResult(rc);

    if (rc == PCRE2_ERROR_NOMATCH) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initInt(0);
    }
    // ★F-90（R-184）：孪生支同语义 ⇒ 真错误 false，出参槽装空数组。
    if (rc < 0) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initBool(false);
    }

    // 填充matches数组
    const matches_arr = try PHPArray.init(allocator);
    const ovec = pcre2_get_ovector_pointer_8(match_data);

    // PHP 口径：默认只到「最高已捕获组」（PCRE2 的 rc 即此值），其间未匹配的组补 ""/null；
    // 带 PREG_UNMATCHED_AS_NULL 时一路补到模式的全部组（实测尾部未匹配组给 null 而非省略）。
    const used_groups: usize = @intCast(rc);
    const group_span = if (unmatched_as_null) pcreGroupSpan(re, used_groups) else used_groups;

    var i: usize = 0;
    while (i < group_span) : (i += 1) {
        const start = ovec[i * 2];
        const end = ovec[i * 2 + 1];
        const unset = start > subject_str.length or end > subject_str.length or start > end;

        // 命名组键在 PHP 里紧随「上一数字键」之后、本组数字键之前（实测序：0, name1, 1, name2, 2）
        if (i > 0) {
            if (pcreGroupNameForGroup(re, i)) |gname| {
                const name_str = try PHPString.init(allocator, gname);
                const named_entry = try pcreCaptureEntry(allocator, subject_str.data, start, end, unset, offset_capture, unmatched_as_null);
                try matches_arr.set(allocator, .{ .string = name_str }, named_entry);
            }
        }
        const entry = try pcreCaptureEntry(allocator, subject_str.data, start, end, unset, offset_capture, unmatched_as_null);
        try matches_arr.push(allocator, entry);
    }

    pregMatchesAssign(matches, Value.initArray(matches_arr), allocator);
    return Value.initInt(1);
}

/// 单次匹配里一个捕获组的原始跨度：先只留偏移，渲染阶段统一走 pcreCaptureEntry，
/// 避免 preg_match 与 preg_match_all 各存一份「未匹配怎么表示」的真相。
const PcreCaptureSpan = struct {
    start: usize,
    end: usize,
    unset: bool,
};

/// preg_split 的一片入表：no_empty 只过滤空文本片；offset_capture 时包成 [文本, 起始下标]。
/// 返回是否真的入表 —— limit 计数沿用既有口径（只计实际产出的片）。
/// `arr` 取 PHPArray.init 的返回值本身（该构造函数返回 `*PHPArray`，故此处形参即指针）。
fn pregSplitPushPiece(
    arr: *PHPArray,
    allocator: Allocator,
    text: []const u8,
    at: usize,
    no_empty: bool,
    offset_capture: bool,
) !bool {
    if (no_empty and text.len == 0) return false;
    if (offset_capture) {
        const pair = try PHPArray.init(allocator);
        try pair.push(allocator, Value.initString(try PHPString.init(allocator, text)));
        try pair.push(allocator, Value.initInt(@intCast(at)));
        try arr.push(allocator, Value.initArray(pair));
    } else {
        try arr.push(allocator, Value.initString(try PHPString.init(allocator, text)));
    }
    return true;
}

/// PREG_PATTERN_ORDER 下某一组的全匹配列（命名键与数字键在 PHP 里是两份独立副本，故各建一次）
fn pcreGroupColumn(
    allocator: Allocator,
    subject: []const u8,
    all_matches: []const std.ArrayListUnmanaged(PcreCaptureSpan),
    group: usize,
    offset_capture: bool,
    unmatched_as_null: bool,
) !*PHPArray {
    const group_arr = try PHPArray.init(allocator);
    for (all_matches) |spans| {
        const span: PcreCaptureSpan = if (group < spans.items.len)
            spans.items[group]
        else
            .{ .start = 0, .end = 0, .unset = true };
        try group_arr.push(allocator, try pcreCaptureEntry(allocator, subject, span.start, span.end, span.unset, offset_capture, unmatched_as_null));
    }
    return group_arr;
}

pub fn php_preg_match_all(pattern: Value, subject: Value, matches: *Value, flags: Value, offset: Value, allocator: Allocator) !Value {
    // ★F-62f 余量（R-232）：#4 flags／#5 offset 必为 int（Foo ⇒ TypeError，先于 PREG_* 域检查）
    const flags_ok = requireOptionalNumParam("preg_match_all", 4, "flags", .int_param, flags) orelse return Value.initBool(false);
    const offset_ok = requireOptionalNumParam("preg_match_all", 5, "offset", .int_param, offset) orelse return Value.initBool(false);
    const flags_val: i64 = if (flags_ok.isNull()) 0 else flags_ok.toInt();
    if (pregMatchAllFlagsInvalid(flags_val)) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        throwThrowableDiscardCatch("ValueError", "preg_match_all(): Argument #4 ($flags) must be a PREG_* constant", allocator);
        return Value.initBool(false);
    }
    const offset_capture = (flags_val & PREG_OFFSET_CAPTURE_BIT) != 0;
    const unmatched_as_null = (flags_val & PREG_UNMATCHED_AS_NULL_BIT) != 0;
    const is_set_order = (flags_val & PREG_SET_ORDER_BIT) != 0;

    if (!pattern.isString() or !subject.isString()) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initInt(0);
    }

    const pattern_str = pattern.asString();
    const subject_str = subject.asString();
    const parsed = parsePHPRegexPattern(pattern_str.data);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 false，不进 PCRE。
    // ★F-53（R-331）：编译前失败路径保留调用者预置值（不写即保留；同 php_preg_match 支）。
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_match_all", parsed);
        return Value.initBool(false);
    }

    // 使用缓存获取编译后的正则
    // ★F-79d：同 `preg_match` 孪生支 ⇒ 两侧同语义（§66.2-2 的重复键未决项不因本批改变）
    // ★F-53（R-331）：编译失败同属编译前路径 ⇒ 保留预置值（不写即保留）。
    const re = compileRegexOrWarn("preg_match_all", parsed, allocator) orelse {
        return Value.initBool(false);
    };

    const off = pcreSearchOffset(offset_ok, subject_str.length);
    if (off.out_of_range) {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initBool(false);
    }

    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        pregMatchesAssign(matches, Value.initArray(try PHPArray.init(allocator)), allocator);
        return Value.initInt(0);
    };
    defer pcre2_match_data_free_8(match_data);

    // 存储所有匹配（临时）
    var all_matches = std.ArrayListUnmanaged(std.ArrayListUnmanaged(PcreCaptureSpan)).empty;
    defer {
        for (all_matches.items) |*spans| {
            spans.deinit(allocator);
        }
        all_matches.deinit(allocator);
    }

    var match_offset: usize = off.start;
    var match_count: i64 = 0;

    // 循环匹配所有
    while (match_offset <= subject_str.length) {
        const rc = pcre2_match_8(
            re,
            subject_str.data.ptr,
            subject_str.length,
            @intCast(match_offset),
            0,
            match_data,
            null,
        );
        recordPcreMatchResult(rc);

        if (rc == PCRE2_ERROR_NOMATCH) break;
        // ★F-90（R-184）：孪生支同语义（§66.2-2 口径）——真错误 ⇒ 整调用 false。
        //   ★早退安全：`match_data`/`all_matches` 均挂 `defer`。
        if (rc < 0) return Value.initBool(false);

        match_count += 1;
        const ovec = pcre2_get_ovector_pointer_8(match_data);

        // 保存当前匹配的所有组偏移
        var spans = std.ArrayListUnmanaged(PcreCaptureSpan).empty;
        var i: usize = 0;
        while (i < @as(usize, @intCast(rc))) : (i += 1) {
            const start = ovec[i * 2];
            const end = ovec[i * 2 + 1];
            try spans.append(allocator, .{
                .start = start,
                .end = end,
                .unset = start > subject_str.length or end > subject_str.length or start > end,
            });
        }
        try all_matches.append(allocator, spans);

        // 移动到下一个位置
        const match_end = ovec[1];
        if (match_end == match_offset) {
            match_offset += 1; // 避免空匹配无限循环
        } else {
            match_offset = match_end;
        }
    }

    // PREG_SET_ORDER=2: matches[i] = [full_match, group1, group2, ...]
    // PREG_PATTERN_ORDER=1 (默认): matches[0] = [all full matches], matches[1] = [all group1], ...
    const group_span = pcreGroupSpan(re, 1);

    const matches_arr = try PHPArray.init(allocator);

    if (is_set_order) {
        // PREG_SET_ORDER: 每个元素是一个匹配的所有组。
        // 实测：默认按本次匹配实际用到的组数截断（尾部未匹配组省略）；
        //       带 PREG_UNMATCHED_AS_NULL 时补到模式全组数并给 null。
        for (all_matches.items) |spans| {
            const set_arr = try PHPArray.init(allocator);
            const set_span: usize = if (unmatched_as_null) group_span else spans.items.len;
            var g: usize = 0;
            while (g < set_span) : (g += 1) {
                const span: PcreCaptureSpan = if (g < spans.items.len)
                    spans.items[g]
                else
                    .{ .start = 0, .end = 0, .unset = true };
                const entry = try pcreCaptureEntry(allocator, subject_str.data, span.start, span.end, span.unset, offset_capture, unmatched_as_null);
                if (g > 0) {
                    if (pcreGroupNameForGroup(re, g)) |gname| {
                        const name_str = try PHPString.init(allocator, gname);
                        const named_copy = try pcreCaptureEntry(allocator, subject_str.data, span.start, span.end, span.unset, offset_capture, unmatched_as_null);
                        try set_arr.set(allocator, .{ .string = name_str }, named_copy);
                    }
                }
                try set_arr.push(allocator, entry);
            }
            try matches_arr.push(allocator, Value.initArray(set_arr));
        }
    } else {
        // PREG_PATTERN_ORDER：恒按「模式全组数」出行，零匹配也给出 [[], [], ...]（实测）
        var g: usize = 0;
        while (g < group_span) : (g += 1) {
            if (g > 0) {
                if (pcreGroupNameForGroup(re, g)) |gname| {
                    const name_str = try PHPString.init(allocator, gname);
                    const named_column = try pcreGroupColumn(allocator, subject_str.data, all_matches.items, g, offset_capture, unmatched_as_null);
                    try matches_arr.set(allocator, .{ .string = name_str }, Value.initArray(named_column));
                }
            }
            const numeric_column = try pcreGroupColumn(allocator, subject_str.data, all_matches.items, g, offset_capture, unmatched_as_null);
            try matches_arr.push(allocator, Value.initArray(numeric_column));
        }
    }

    pregMatchesAssign(matches, Value.initArray(matches_arr), allocator);
    return Value.initInt(match_count);
}

pub fn php_preg_replace(pattern: Value, replacement: Value, subject: Value, allocator: Allocator) !Value {
    if (!pattern.isString() or !replacement.isString() or !subject.isString())
        return Value.initBool(false);

    const pat = pattern.asString().data;
    const repl = replacement.asString().data;
    const subj = subject.asString().data;

    if (pat.len < 3) return Value.initString(try PHPString.init(allocator, try allocator.dupe(u8, subj)));
    const actual_pat = pat[1 .. pat.len - 1];

    // 简单替换
    var result = try std.ArrayList(u8).initCapacity(allocator, subj.len);
    defer result.deinit(allocator);

    var pos: usize = 0;
    while (pos < subj.len) {
        if (std.mem.indexOf(u8, subj[pos..], actual_pat)) |idx| {
            try result.appendSlice(allocator, subj[pos .. pos + idx]);
            try result.appendSlice(allocator, repl);
            pos += idx + actual_pat.len;
        } else {
            try result.appendSlice(allocator, subj[pos..]);
            break;
        }
    }

    const output = try PHPString.init(allocator, try result.toOwnedSlice(allocator));
    return Value.initString(output);
}

pub fn php_preg_replace_callback(pattern: Value, callback: Value, subject: Value, limit_val: Value, count_out: Value, allocator: Allocator) !Value {
    // ★批次十四⑤：补 limit/$count 形参（旧 4 形参 ⇒ 发射器 5+1 实参 arity 编译失败）。
    //   PHP 8.5.8 实测契约：$count 入口即清零（非法 pattern/无匹配 ⇒ 0）；
    //   回调 throw 时保留**已处理数**（增量计数）；limit<0 ⇒ 无限，limit>=0 ⇒ 上限。
    if (count_out.isRef()) {
        count_out.asRef().* = Value.initInt(0);
    }
    const limit: usize = if (limit_val.isInt() and limit_val.asInt() >= 0) @intCast(limit_val.asInt()) else std.math.maxInt(usize);
    var replace_count: usize = 0;
    // 回调 throw（error 上抛）时按增量语义写回已处理数
    errdefer if (count_out.isRef()) {
        count_out.asRef().* = Value.initInt(@intCast(replace_count));
    };
    defer if (count_out.isRef()) {
        count_out.asRef().* = Value.initInt(@intCast(replace_count));
    };

    if (!pattern.isString() or !subject.isString())
        return Value.initBool(false);

    const pattern_str = pattern.asString().data;
    const subject_str = subject.asString().data;

    // 解析 PHP 正则模式
    const parsed = parsePHPRegexPattern(pattern_str);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 null（实测），不进 PCRE
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_replace_callback", parsed);
        return Value.initNull();
    }

    // 编译正则表达式
    // ★F-79d：实测 PHP `preg_replace_callback` 编译失败 ⇒ `null` ＋ Warning（旧返回未替换的 subject）
    const re = compileRegexOrWarn("preg_replace_callback", parsed, allocator) orelse return Value.initNull();

    // 创建匹配数据
    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        return Value.initString(try PHPString.init(allocator, try allocator.dupe(u8, subject_str)));
    };
    defer pcre2_match_data_free_8(match_data);

    // 准备输出缓冲区
    var result = try std.ArrayList(u8).initCapacity(allocator, subject_str.len * 2);
    defer result.deinit(allocator);

    var subject_offset: usize = 0;

    while (subject_offset < subject_str.len and replace_count < limit) {
        const rc = pcre2_match_8(
            re,
            subject_str.ptr,
            subject_str.len,
            @as(c_int, @intCast(subject_offset)),
            0,
            match_data,
            null,
        );
        recordPcreMatchResult(rc);

        if (rc == PCRE2_ERROR_NOMATCH) break;
        // ★F-90（R-184）：真错误 ⇒ 整调用 **null**（`preg_replace_callback` 实测契约）。
        //   ★早退安全：`result` 挂 `defer result.deinit(allocator)`，循环内 `matches_arr` 自挂 defer。
        if (rc < 0) return Value.initNull();

        const ovec = pcre2_get_ovector_pointer_8(match_data);
        const match_start = ovec[0];
        const match_end = ovec[1];

        // 添加匹配前的内容
        if (match_start > subject_offset) {
            try result.appendSlice(allocator, subject_str[subject_offset..match_start]);
        }

        // 构建匹配数组
        const matches_arr = try PHPArray.init(allocator);
        defer matches_arr.release(allocator);

        // 添加所有捕获组
        var i: usize = 0;
        while (i < @as(usize, @intCast(rc))) : (i += 1) {
            const start = ovec[i * 2];
            const end = ovec[i * 2 + 1];
            const match_str = subject_str[start..end];
            const php_str = try PHPString.init(allocator, try allocator.dupe(u8, match_str));
            try matches_arr.push(allocator, Value.initString(php_str));
        }

        // 调用回调函数
        // ★批次十四⑤：回调 throw ⇒ Style-A（挂起异常 + 返 null）交还调用点 hasException 路由——
        //   PHP 契约＝异常传播且 $count 保留已处理数（defer 已写 Ref cell；error 上抛旧形会跳过
        //   发射器 ref_params 异常写回块，$count 滞留旧值）。
        const callback_result = php_invoke_callable(callback, &[_]Value{Value.initArray(matches_arr)}, allocator) catch |err| {
            if (hasException()) return Value.initNull();
            return err;
        };
        defer callback_result.release(allocator);

        // 将回调结果添加到输出
        if (callback_result.isString()) {
            try result.appendSlice(allocator, callback_result.asString().data);
        } else if (callback_result.isInt()) {
            // 处理整数返回值
            const int_val = callback_result.asInt();
            var buf: [32]u8 = undefined;
            const int_str = try std.fmt.bufPrint(&buf, "{d}", .{int_val});
            try result.appendSlice(allocator, int_str);
        } else {
            const str_result = try callback_result.toString(allocator);
            defer str_result.release(allocator);
            try result.appendSlice(allocator, str_result.data);
        }

        subject_offset = match_end;
        replace_count += 1;
    }

    // 添加剩余内容
    if (subject_offset < subject_str.len) {
        try result.appendSlice(allocator, subject_str[subject_offset..]);
    }

    const output = try PHPString.init(allocator, try result.toOwnedSlice(allocator));
    return Value.initString(output);
}

pub fn php_preg_split(pattern: Value, subject: Value, limit_val: Value, flags_val: Value, allocator: Allocator) !Value {
    // 转发到 PCRE2 实现
    return preg_split(pattern, subject, limit_val, flags_val, allocator);
}

/// filter_var - 使用特定的过滤器过滤一个变量
pub fn php_filter_var(value: Value, filter: Value, options: Value, allocator: Allocator) !Value {
    if (!filter.isInt()) return Value.initBool(false);

    const filter_type = filter.asInt();

    // FILTER_VALIDATE_EMAIL = 274
    if (filter_type == 274) {
        if (!value.isString()) return Value.initBool(false);

        const email = value.asString().data;

        // 简单的邮箱验证：必须包含 @ 和 .，且格式合理
        if (email.len < 3) return Value.initBool(false);

        // 查找 @
        const at_pos = std.mem.indexOf(u8, email, "@") orelse return Value.initBool(false);
        if (at_pos == 0 or at_pos == email.len - 1) return Value.initBool(false);

        // @ 后面必须有 .
        const domain = email[at_pos + 1 ..];
        const dot_pos = std.mem.indexOf(u8, domain, ".") orelse return Value.initBool(false);
        if (dot_pos == 0 or dot_pos == domain.len - 1) return Value.initBool(false);

        // 检查是否有多个 @
        if (std.mem.indexOf(u8, email[at_pos + 1 ..], "@") != null) return Value.initBool(false);

        // 验证通过，返回原值
        return value;
    }

    // FILTER_VALIDATE_URL = 273
    if (filter_type == 273) {
        if (!value.isString()) return Value.initBool(false);
        const url = value.asString().data;
        if (url.len < 8) return Value.initBool(false);
        // 必须以 http:// 或 https:// 或 ftp:// 开头
        if (std.mem.startsWith(u8, url, "http://") or std.mem.startsWith(u8, url, "https://") or std.mem.startsWith(u8, url, "ftp://")) {
            // 协议后必须有至少一个字符（域名）
            const scheme_end = std.mem.indexOf(u8, url, "://").? + 3;
            if (scheme_end >= url.len) return Value.initBool(false);
            // 域名部分不能包含空格
            if (std.mem.indexOf(u8, url[scheme_end..], " ") != null) return Value.initBool(false);
            return value;
        }
        return Value.initBool(false);
    }

    // FILTER_VALIDATE_IP = 275
    if (filter_type == 275) {
        if (!value.isString()) return Value.initBool(false);
        const ip = value.asString().data;
        // IPv4 验证：4 段数字，每段 0-255
        var parts = std.mem.splitScalar(u8, ip, '.');
        var count: usize = 0;
        while (parts.next()) |part| {
            count += 1;
            if (count > 4) return Value.initBool(false);
            if (part.len == 0 or part.len > 3) return Value.initBool(false);
            const num = std.fmt.parseInt(u16, part, 10) catch return Value.initBool(false);
            if (num > 255) return Value.initBool(false);
        }
        if (count != 4) return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_INT = 257
    if (filter_type == 257) {
        if (!value.isString() and !value.isInt()) return Value.initBool(false);
        if (value.isInt()) return value;
        const s = value.asString().data;
        _ = std.fmt.parseInt(i64, s, 10) catch return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_FLOAT = 259
    if (filter_type == 259) {
        if (!value.isString() and !value.isFloat() and !value.isInt()) return Value.initBool(false);
        if (value.isFloat() or value.isInt()) return value;
        const s = value.asString().data;
        _ = std.fmt.parseFloat(f64, s) catch return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_BOOLEAN = 258
    if (filter_type == 258) {
        if (value.isBool()) return value;
        if (value.isInt()) return Value.initBool(value.asInt() != 0);
        if (!value.isString()) return Value.initBool(false);
        const s = value.asString().data;
        if (std.ascii.eqlIgnoreCase(s, "true") or std.ascii.eqlIgnoreCase(s, "yes") or std.mem.eql(u8, s, "1") or std.ascii.eqlIgnoreCase(s, "on")) {
            return Value.initBool(true);
        }
        if (std.ascii.eqlIgnoreCase(s, "false") or std.ascii.eqlIgnoreCase(s, "no") or std.mem.eql(u8, s, "0") or std.ascii.eqlIgnoreCase(s, "off") or std.mem.eql(u8, s, "")) {
            return Value.initBool(false);
        }
        return Value.initNull();
    }

    // FILTER_VALIDATE_REGEXP = 272
    if (filter_type == 272) {
        if (!value.isString()) return Value.initBool(false);
        // 从 options 中提取 regexp
        if (options.isNull() or !options.isArray()) return Value.initBool(false);
        const opts_arr = options.asArray();
        const opts_entry = opts_arr.getByValue(Value.initString(PHPString.initStatic("options"))) orelse return Value.initBool(false);
        defer opts_entry.release(runtime_allocator);
        if (!opts_entry.isArray()) return Value.initBool(false);
        const inner_arr = opts_entry.asArray();
        const regexp_entry = inner_arr.getByValue(Value.initString(PHPString.initStatic("regexp"))) orelse return Value.initBool(false);
        defer regexp_entry.release(runtime_allocator);
        if (!regexp_entry.isString()) return Value.initBool(false);
        // 使用 preg_match 进行匹配
        var dummy_matches: Value = Value.initNull();
        const match_result = try preg_match(regexp_entry, value, &dummy_matches, Value.initNull(), Value.initInt(0), allocator);
        if (match_result.isInt() and match_result.asInt() > 0) return value;
        return Value.initBool(false);
    }

    // 其他过滤器类型暂不支持
    return Value.initBool(false);
}

/// htmlspecialchars - 将特殊字符转换为HTML实体
pub fn php_htmlspecialchars(str: Value, flags: Value, encoding: Value, double_encode: Value, allocator: Allocator) !Value {
    _ = flags;
    _ = encoding;
    _ = double_encode;
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    for (input) |c| {
        switch (c) {
            '&' => try result.appendSlice(allocator, "&amp;"),
            '"' => try result.appendSlice(allocator, "&quot;"),
            '\'' => try result.appendSlice(allocator, "&#039;"),
            '<' => try result.appendSlice(allocator, "&lt;"),
            '>' => try result.appendSlice(allocator, "&gt;"),
            else => try result.append(allocator, c),
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// htmlentities - 将所有适用的字符转换为HTML实体
pub fn php_htmlentities(str: Value, flags: Value, encoding: Value, double_encode: Value, allocator: Allocator) !Value {
    return php_htmlspecialchars(str, flags, encoding, double_encode, allocator);
}

/// htmlspecialchars_decode - 将HTML实体转换回字符
pub fn php_htmlspecialchars_decode(str: Value, flags: Value, allocator: Allocator) !Value {
    _ = flags;
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var i: usize = 0;
    while (i < input.len) {
        if (input[i] == '&') {
            if (i + 4 <= input.len and std.mem.eql(u8, input[i .. i + 4], "&lt;")) {
                try result.append(allocator, '<');
                i += 4;
            } else if (i + 4 <= input.len and std.mem.eql(u8, input[i .. i + 4], "&gt;")) {
                try result.append(allocator, '>');
                i += 4;
            } else if (i + 5 <= input.len and std.mem.eql(u8, input[i .. i + 5], "&amp;")) {
                try result.append(allocator, '&');
                i += 5;
            } else if (i + 6 <= input.len and std.mem.eql(u8, input[i .. i + 6], "&quot;")) {
                try result.append(allocator, '"');
                i += 6;
            } else if (i + 6 <= input.len and std.mem.eql(u8, input[i .. i + 6], "&#039;")) {
                try result.append(allocator, '\'');
                i += 6;
            } else {
                try result.append(allocator, input[i]);
                i += 1;
            }
        } else {
            try result.append(allocator, input[i]);
            i += 1;
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

fn wordwrapNextWordLen(input: []const u8, from: usize) usize {
    var i = from;
    while (i < input.len and input[i] == ' ') : (i += 1) {}
    var n: usize = 0;
    while (i < input.len and input[i] != ' ' and input[i] != '\n') : (i += 1) n += 1;
    return n;
}

/// ★F-150：按 PHP 口径硬切超宽段；inclusive 区分“空格/换行处”（切满也发 break）
/// 与“串尾”（恰好宽度不发 break）。返回是否发生过切分。
fn wordwrapCutFlush(
    result: *std.ArrayList(u8),
    allocator: Allocator,
    input: []const u8,
    line_start: *usize,
    end: usize,
    width: usize,
    break_chars: []const u8,
    enabled: bool,
    inclusive: bool,
) !bool {
    if (!enabled) return false;
    var moved = false;
    while (true) {
        const seg = end - line_start.*;
        const hit = if (inclusive) seg >= width else seg > width;
        if (!hit) break;
        try result.appendSlice(allocator, input[line_start.* .. line_start.* + width]);
        try result.appendSlice(allocator, break_chars);
        line_start.* += width;
        moved = true;
    }
    return moved;
}

/// wordwrap - 将字符串按指定长度换行
/// ★F-150（R-239）：按 PHP 8.5.8 实测重写——保留原有空格/空行/换行，cut 时按宽度硬切。
pub fn php_wordwrap(str: Value, width: Value, break_str: Value, cut: Value, allocator: Allocator) !Value {
    // ★F-62f 接线：`$width`（可选 int，PHP 侧默认 75）⇒ 对象/array/坏串必须 TypeError（实测 `Argument #2 ($width) must be of type int`）
    const width_ok = requireOptionalNumParam("wordwrap", 2, "width", .int_param, width) orelse return Value.initNull();
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    const wrap_width: usize = @intCast(@max(1, width_ok.toInt()));
    const break_chars = if (break_str.isString()) break_str.asString().data else "\n";
    // ★F-149（R-238）：#4 bool $cut_long_words（注意 PHP 形参名不是 $cut）
    const cut_ok = requireBoolParam("wordwrap", 4, "cut_long_words", cut) orelse return Value.initNull();
    const force_cut = cut_ok.toBool();

    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var line_start: usize = 0;
    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        if (input[i] == '\n') {
            _ = try wordwrapCutFlush(&result, allocator, input, &line_start, i, wrap_width, break_chars, force_cut, true);
            try result.appendSlice(allocator, input[line_start..i]);
            // 已有换行原样保留（不受 $break 影响；实测 PHP 如此）
            try result.append(allocator, '\n');
            line_start = i + 1;
        } else if (input[i] == ' ') {
            const moved = try wordwrapCutFlush(&result, allocator, input, &line_start, i, wrap_width, break_chars, force_cut, true);
            if (moved and line_start == i) {
                // 恰好切满：该空格被丢弃
                line_start = i + 1;
            } else if (i + 1 >= input.len or input[i + 1] != ' ') {
                const seg = i - line_start;
                const next_len = wordwrapNextWordLen(input, i + 1);
                if (seg > 0 and seg + 1 + next_len > wrap_width) {
                    try result.appendSlice(allocator, input[line_start..i]);
                    try result.appendSlice(allocator, break_chars);
                    line_start = i + 1;
                }
            }
        }
    }

    _ = try wordwrapCutFlush(&result, allocator, input, &line_start, input.len, wrap_width, break_chars, force_cut, false);
    try result.appendSlice(allocator, input[line_start..]);

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

pub fn php_printf(format: Value, args: []const Value, allocator: Allocator) !Value {
    const out = try php_sprintf(format, args, allocator);
    defer out.release(allocator);
    try php_echo(out);
    if (out.isString()) return Value.initInt(@intCast(out.asString().length));
    return Value.initInt(0);
}

pub fn php_bin2hex(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;
    const input = str.asString().data;
    const hex_len = input.len * 2;
    const hex_str = try allocator.alloc(u8, hex_len);
    defer allocator.free(hex_str);

    const hex_chars = "0123456789abcdef";
    for (input, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, hex_str);
    return Value.initString(php_str);
}

/// 解析十进制字符串为 (负数标记, 整数值, 小数位数)
/// value * 10^(-scale) 即为原始数值
fn parseBcNumber(s: []const u8) struct { neg: bool, value: i128, scale: u32 } {
    var i: usize = 0;
    var neg = false;
    if (i < s.len and (s[i] == '+' or s[i] == '-')) {
        neg = s[i] == '-';
        i += 1;
    }
    var int_part: i128 = 0;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
        int_part = int_part * 10 + @as(i128, s[i] - '0');
    }
    var scale: u32 = 0;
    var frac_value: i128 = 0;
    if (i < s.len and s[i] == '.') {
        i += 1;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
            frac_value = frac_value * 10 + @as(i128, s[i] - '0');
            scale += 1;
        }
    }
    // 合并整数和小数部分
    var total = int_part;
    var j: u32 = 0;
    while (j < scale) : (j += 1) {
        total = total * 10;
    }
    total += frac_value;
    if (neg) total = -total;
    return .{ .neg = neg, .value = total, .scale = scale };
}

/// 将 bc 数值格式化为字符串，截断到指定小数位
fn formatBcNumber(value: i128, orig_scale: u32, target_scale: u32, allocator: Allocator) !Value {
    // 调整精度：如果 target_scale < orig_scale，需要截断
    var v = value;
    var cur_scale = orig_scale;
    if (target_scale < cur_scale) {
        const diff = cur_scale - target_scale;
        var divisor: i128 = 1;
        var k: u32 = 0;
        while (k < diff) : (k += 1) divisor *= 10;
        v = @divTrunc(v, divisor);
        cur_scale = target_scale;
    } else if (target_scale > cur_scale) {
        const diff = target_scale - cur_scale;
        var multiplier: i128 = 1;
        var k: u32 = 0;
        while (k < diff) : (k += 1) multiplier *= 10;
        v = v * multiplier;
        cur_scale = target_scale;
    }

    var neg = false;
    if (v < 0) {
        neg = true;
        v = -v;
    }

    // 将整数转为字符串
    var buf: [64]u8 = undefined;
    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return Value.initNull();
    const digits = written;

    // 分割整数和小数部分
    var int_str: []const u8 = digits;
    var frac_str: []const u8 = "";
    var frac_buf: [64]u8 = undefined;
    if (cur_scale > 0) {
        if (digits.len > cur_scale) {
            int_str = digits[0 .. digits.len - cur_scale];
            frac_str = digits[digits.len - cur_scale ..];
        } else {
            int_str = "0";
            const leading_zeros = cur_scale - digits.len;
            var pos: usize = 0;
            var z: u32 = 0;
            while (z < leading_zeros) : (z += 1) {
                frac_buf[pos] = '0';
                pos += 1;
            }
            @memcpy(frac_buf[pos .. pos + digits.len], digits);
            pos += digits.len;
            frac_str = frac_buf[0..pos];
        }
    }

    // 组装最终字符串
    var result_buf: [80]u8 = undefined;
    var pos: usize = 0;
    if (neg and v != 0) {
        result_buf[pos] = '-';
        pos += 1;
    }
    @memcpy(result_buf[pos .. pos + int_str.len], int_str);
    pos += int_str.len;
    if (cur_scale > 0) {
        result_buf[pos] = '.';
        pos += 1;
        @memcpy(result_buf[pos .. pos + frac_str.len], frac_str);
        pos += frac_str.len;
    }

    return Value.initString(try PHPString.init(allocator, result_buf[0..pos]));
}

pub fn php_bcadd(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(a.scale, b.scale);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    const result = av + bv;
    return formatBcNumber(result, max_scale, s, allocator);
}

pub fn php_bcsub(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(a.scale, b.scale);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    const result = av - bv;
    return formatBcNumber(result, max_scale, s, allocator);
}

pub fn php_bcmul(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const result = a.value * b.value;
    const result_scale = a.scale + b.scale;
    return formatBcNumber(result, result_scale, s, allocator);
}

pub fn php_bcdiv(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    if (b.value == 0) return Value.initNull();
    // (a.value / 10^a.scale) / (b.value / 10^b.scale) = (a.value * 10^b.scale) / (b.value * 10^a.scale)
    // 要得到 s 位小数: result = (a.value * 10^(s + b.scale)) / (b.value * 10^a.scale)
    const scale_diff: i32 = @as(i32, @intCast(s)) + @as(i32, @intCast(b.scale)) - @as(i32, @intCast(a.scale));
    var av = a.value;
    var bv = b.value;
    if (scale_diff >= 0) {
        var multiplier: i128 = 1;
        var k: i32 = 0;
        while (k < scale_diff) : (k += 1) multiplier *= 10;
        av = av * multiplier;
    } else {
        var divisor: i128 = 1;
        var k: i32 = 0;
        while (k < -scale_diff) : (k += 1) divisor *= 10;
        bv = bv * divisor;
    }
    const result = @divTrunc(av, bv);
    return formatBcNumber(result, s, s, allocator);
}

pub fn php_bcmod(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const av = @divTrunc(a.value, bcPow10(a.scale));
    const bv = @divTrunc(b.value, bcPow10(b.scale));
    if (bv == 0) return Value.initNull();
    const result = @rem(av, bv);
    var buf: [64]u8 = undefined;
    const written = std.fmt.bufPrint(&buf, "{d}", .{result}) catch return Value.initNull();
    return Value.initString(try PHPString.init(allocator, written));
}

pub fn php_bcpow(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const e = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const exp_int = @divTrunc(e.value, bcPow10(e.scale));
    if (exp_int < 0) return Value.initNull();
    var result: i128 = 1;
    var i: i128 = 0;
    while (i < exp_int) : (i += 1) {
        result = result * a.value;
    }
    const result_scale = a.scale * @as(u32, @intCast(exp_int));
    return formatBcNumber(result, result_scale, s, allocator);
}

pub fn php_bcsqrt(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const s: u32 = if (args.len >= 2 and args[1].isInt()) @intCast(@max(0, args[1].asInt())) else 0;
    if (a.value < 0) return Value.initNull();
    const scaled = scaleBcValue(a.value, a.scale, s * 2);
    if (scaled == 0) return formatBcNumber(0, 0, s, allocator);
    var x: i128 = scaled;
    var prev: i128 = 0;
    var iter: u32 = 0;
    while (iter < 100) : (iter += 1) {
        prev = x;
        x = @divTrunc(x + @divTrunc(scaled, x), 2);
        if (x == prev) break;
    }
    return formatBcNumber(x, s, s, allocator);
}

pub fn php_bccomp(args: []const Value, _: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(@max(a.scale, b.scale), s);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    if (av < bv) return Value.initInt(-1);
    if (av > bv) return Value.initInt(1);
    return Value.initInt(0);
}

fn bcPow10(n: u32) i128 {
    var result: i128 = 1;
    var i: u32 = 0;
    while (i < n) : (i += 1) result *= 10;
    return result;
}

fn scaleBcValue(value: i128, from_scale: u32, to_scale: u32) i128 {
    if (to_scale <= from_scale) {
        const diff = from_scale - to_scale;
        return @divTrunc(value, bcPow10(diff));
    }
    const diff = to_scale - from_scale;
    return value * bcPow10(diff);
}

/// pack - 将数据打包为二进制字符串
pub fn php_pack(format: Value, args: []const Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    const fmt = format.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);
    var arg_idx: usize = 0;
    var i: usize = 0;
    while (i < fmt.len) {
        const code = fmt[i];
        i += 1;
        // 解析重复次数
        var repeat: ?usize = null;
        if (i < fmt.len and fmt[i] == '*') {
            repeat = null; // 使用所有剩余参数
            i += 1;
        } else if (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
            var n: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                n = n * 10 + (fmt[i] - '0');
                i += 1;
            }
            repeat = n;
        }
        switch (code) {
            'a' => {
                // NUL 填充字符串
                const n = repeat orelse 0;
                if (arg_idx < args.len) {
                    const str = try args[arg_idx].toString(allocator);
                    defer str.release(allocator);
                    const data = str.data;
                    const write_len = if (n > 0) @min(data.len, n) else data.len;
                    try result.appendSlice(allocator, data[0..write_len]);
                    if (n > write_len) {
                        try result.appendNTimes(allocator, 0, n - write_len);
                    }
                    arg_idx += 1;
                } else if (n > 0) {
                    try result.appendNTimes(allocator, 0, n);
                }
            },
            'A' => {
                // 空格填充字符串
                const n = repeat orelse 0;
                if (arg_idx < args.len) {
                    const str = try args[arg_idx].toString(allocator);
                    defer str.release(allocator);
                    const data = str.data;
                    const write_len = if (n > 0) @min(data.len, n) else data.len;
                    try result.appendSlice(allocator, data[0..write_len]);
                    if (n > write_len) {
                        try result.appendNTimes(allocator, ' ', n - write_len);
                    }
                    arg_idx += 1;
                } else if (n > 0) {
                    try result.appendNTimes(allocator, ' ', n);
                }
            },
            'C', 'c' => {
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u8 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFF);
                    try result.append(allocator, val);
                    arg_idx += 1;
                }
            },
            'n' => {
                // 16-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u16 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFF);
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast(val & 0xFF));
                    arg_idx += 1;
                }
            },
            'v' => {
                // 16-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u16 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFF);
                    try result.append(allocator, @intCast(val & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    arg_idx += 1;
                }
            },
            'N' => {
                // 32-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u32 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFFFFFF);
                    try result.append(allocator, @intCast((val >> 24) & 0xFF));
                    try result.append(allocator, @intCast((val >> 16) & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast(val & 0xFF));
                    arg_idx += 1;
                }
            },
            'V' => {
                // 32-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u32 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFFFFFF);
                    try result.append(allocator, @intCast(val & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast((val >> 16) & 0xFF));
                    try result.append(allocator, @intCast((val >> 24) & 0xFF));
                    arg_idx += 1;
                }
            },
            'J' => {
                // 64-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u64 = @bitCast(args[arg_idx].toInt());
                    var b: i32 = 56;
                    while (b >= 0) : (b -= 8) {
                        try result.append(allocator, @intCast((val >> @intCast(b)) & 0xFF));
                    }
                    arg_idx += 1;
                }
            },
            'P' => {
                // 64-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u64 = @bitCast(args[arg_idx].toInt());
                    var b: i32 = 0;
                    while (b < 64) : (b += 8) {
                        try result.append(allocator, @intCast((val >> @intCast(b)) & 0xFF));
                    }
                    arg_idx += 1;
                }
            },
            'f' => {
                // 32-bit float (平台字节序)
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: f32 = @floatCast(args[arg_idx].toFloat());
                    const bytes: [4]u8 = @bitCast(val);
                    try result.appendSlice(allocator, &bytes);
                    arg_idx += 1;
                }
            },
            'd' => {
                // 64-bit double (平台字节序)
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: f64 = args[arg_idx].toFloat();
                    const bytes: [8]u8 = @bitCast(val);
                    try result.appendSlice(allocator, &bytes);
                    arg_idx += 1;
                }
            },
            'x' => {
                // NUL 字节
                const count = repeat orelse 1;
                try result.appendNTimes(allocator, 0, count);
            },
            else => {},
        }
    }
    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// unpack - 从二进制字符串解包数据
pub fn php_unpack(format: Value, data: Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    if (!data.isString()) return error.InvalidArgument;
    const fmt = format.asString().data;
    const input = data.asString().data;
    const result = try PHPArray.init(allocator);
    var offset: usize = 0;
    var out_idx: usize = 1;
    var i: usize = 0;
    while (i < fmt.len) {
        const code = fmt[i];
        i += 1;
        var repeat: ?usize = null;
        if (i < fmt.len and fmt[i] == '*') {
            repeat = null;
            i += 1;
        } else if (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
            var n: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                n = n * 10 + (fmt[i] - '0');
                i += 1;
            }
            repeat = n;
        }
        switch (code) {
            'A' => {
                const n = repeat orelse (input.len - offset);
                if (offset + n <= input.len) {
                    var slice = input[offset .. offset + n];
                    // 去除尾部空格/NUL
                    while (slice.len > 0 and (slice[slice.len - 1] == 0 or slice[slice.len - 1] == ' ')) {
                        slice = slice[0 .. slice.len - 1];
                    }
                    const php_str = try PHPString.init(allocator, slice);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initString(php_str));
                    out_idx += 1;
                    offset += n;
                }
            },
            'a' => {
                const n = repeat orelse (input.len - offset);
                if (offset + n <= input.len) {
                    var slice = input[offset .. offset + n];
                    while (slice.len > 0 and slice[slice.len - 1] == 0) {
                        slice = slice[0 .. slice.len - 1];
                    }
                    const php_str = try PHPString.init(allocator, slice);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initString(php_str));
                    out_idx += 1;
                    offset += n;
                }
            },
            'C', 'c' => {
                const count = repeat orelse (input.len - offset);
                for (0..count) |_| {
                    if (offset >= input.len) break;
                    const b = input[offset];
                    const val: i64 = if (code == 'c') (if (b & 0x80 != 0) @as(i64, b) - 256 else b) else b;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 1;
                }
            },
            'n' => {
                const count = repeat orelse ((input.len - offset) / 2);
                for (0..count) |_| {
                    if (offset + 2 > input.len) break;
                    const val: u16 = (@as(u16, input[offset]) << 8) | input[offset + 1];
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 2;
                }
            },
            'v' => {
                const count = repeat orelse ((input.len - offset) / 2);
                for (0..count) |_| {
                    if (offset + 2 > input.len) break;
                    const val: u16 = input[offset] | (@as(u16, input[offset + 1]) << 8);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 2;
                }
            },
            'N' => {
                const count = repeat orelse ((input.len - offset) / 4);
                for (0..count) |_| {
                    if (offset + 4 > input.len) break;
                    const val: u32 = (@as(u32, input[offset]) << 24) | (@as(u32, input[offset + 1]) << 16) | (@as(u32, input[offset + 2]) << 8) | input[offset + 3];
                    // PHP 的 N 格式返回有符号 int（如果最高位为 1 则为负数）
                    const sval: i64 = @intCast(val);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(sval));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'V' => {
                const count = repeat orelse ((input.len - offset) / 4);
                for (0..count) |_| {
                    if (offset + 4 > input.len) break;
                    const val: u32 = input[offset] | (@as(u32, input[offset + 1]) << 8) | (@as(u32, input[offset + 2]) << 16) | (@as(u32, input[offset + 3]) << 24);
                    const sval: i64 = @intCast(val);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(sval));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'J' => {
                const count = repeat orelse ((input.len - offset) / 8);
                for (0..count) |_| {
                    if (offset + 8 > input.len) break;
                    var val: u64 = 0;
                    var b: i32 = 56;
                    while (b >= 0) : (b -= 8) {
                        val = (val << 8) | input[offset + @as(usize, @intCast(@divTrunc(56 - b, 8)))];
                    }
                    offset += 8;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(@bitCast(val)));
                    out_idx += 1;
                }
            },
            'P' => {
                const count = repeat orelse ((input.len - offset) / 8);
                for (0..count) |_| {
                    if (offset + 8 > input.len) break;
                    var val: u64 = 0;
                    var b: i32 = 0;
                    while (b < 64) : (b += 8) {
                        val |= @as(u64, input[offset + @as(usize, @intCast(@divTrunc(b, 8)))]) << @intCast(b);
                    }
                    offset += 8;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(@bitCast(val)));
                    out_idx += 1;
                }
            },
            'f' => {
                if (offset + 4 <= input.len) {
                    const bytes: [4]u8 = input[offset .. offset + 4][0..4].*;
                    const val: f32 = @bitCast(bytes);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initFloat(val));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'd' => {
                if (offset + 8 <= input.len) {
                    const bytes: [8]u8 = input[offset .. offset + 8][0..8].*;
                    const val: f64 = @bitCast(bytes);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initFloat(val));
                    out_idx += 1;
                    offset += 8;
                }
            },
            else => {},
        }
    }
    return Value.initArray(result);
}

/// decbin - 十进制转二进制
pub fn php_decbin(num: Value, allocator: Allocator) !Value {
    const n = if (num.isInt()) num.asInt() else @as(i64, @intFromFloat(num.asFloat()));
    if (n == 0) {
        const php_str = try PHPString.init(allocator, "0");
        return Value.initString(php_str);
    }

    var abs_n: u64 = if (n < 0) @intCast(-n) else @intCast(n);
    var buf: [64]u8 = undefined;
    var len: usize = 0;

    while (abs_n > 0) : (abs_n >>= 1) {
        buf[63 - len] = if (abs_n & 1 == 1) '1' else '0';
        len += 1;
    }

    const result = buf[64 - len ..];
    const php_str = try PHPString.init(allocator, result);
    return Value.initString(php_str);
}

fn hexCharToInt(c: u8) ?u8 {
    if (c >= '0' and c <= '9') return c - '0';
    if (c >= 'a' and c <= 'f') return c - 'a' + 10;
    if (c >= 'A' and c <= 'F') return c - 'A' + 10;
    return null;
}

pub fn php_hex2bin(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;
    const input = str.asString().data;
    if (input.len % 2 != 0) return Value.initBool(false);

    const bin_len = input.len / 2;
    const bin_str = try allocator.alloc(u8, bin_len);
    defer allocator.free(bin_str);

    for (0..bin_len) |i| {
        const high = hexCharToInt(input[i * 2]) orelse return Value.initBool(false);
        const low = hexCharToInt(input[i * 2 + 1]) orelse return Value.initBool(false);
        bin_str[i] = (high << 4) | low;
    }

    const php_str = try PHPString.init(allocator, bin_str);
    return Value.initString(php_str);
}

// ============================================================================
// 哈希函数
// ============================================================================

/// md5 - 计算字符串的MD5哈希值
pub fn php_md5(str: Value, raw_output: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [16]u8 = undefined;
    std.crypto.hash.Md5.hash(input, &hash, .{});

    if (raw_output.toBool()) {
        const php_str = try PHPString.init(allocator, &hash);
        return Value.initString(php_str);
    }

    // 转换为十六进制字符串
    var hex_str: [32]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// sha1 - 计算字符串的SHA1哈希值
pub fn php_sha1(str: Value, raw_output: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [20]u8 = undefined;
    std.crypto.hash.Sha1.hash(input, &hash, .{});

    if (raw_output.toBool()) {
        const php_str = try PHPString.init(allocator, &hash);
        return Value.initString(php_str);
    }

    // 转换为十六进制字符串
    var hex_str: [40]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// password_hash - 创建密码哈希
/// 签名: password_hash(password, algo, options = []) — bcrypt（`options['cost']` 生效）
pub fn php_password_hash(password: Value, algo: Value, options_val: Value, allocator: Allocator) !Value {
    const pass_ok = requireStringParamWeak("password_hash", 1, "password", password) orelse return Value.initNull();
    const algo_ok = requireStringOrIntOrNullParam("password_hash", 2, "algo", algo) orelse return Value.initNull();
    const options_ok = requireArrayParam("password_hash", 3, "options", options_val) orelse return Value.initNull();

    // ★F-62f（R-261）／F-168（R-263）：合法算法 = 2y / argon2i / argon2id；bcrypt 与 argon 双实现
    const kind = passwordAlgoKind(algo_ok);
    if (kind == .invalid) {
        return throwThrowable("ValueError", "password_hash(): Argument #2 ($algo) must be a valid password hashing algorithm", runtime_allocator);
    }
    if (kind != .bcrypt) {
        const ap = passwordArgon2Params(options_ok);
        // ★PHP 实测文案与边界：memory ≥8 且 ≥8*p；time ≥1；threads 1..0xFFFFFF
        if (ap.m < 8 or ap.m > 0xFFFFFFFF or ap.m < 8 * ap.p) {
            return throwThrowable("ValueError", "Memory cost is outside of allowed memory range", runtime_allocator);
        }
        if (ap.t < 1 or ap.t > 0xFFFFFFFF) {
            return throwThrowable("ValueError", "Time cost is outside of allowed time range", runtime_allocator);
        }
        if (ap.p < 1 or ap.p > 0xFFFFFF) {
            return throwThrowable("ValueError", "Invalid number of threads", runtime_allocator);
        }

        const pwd_php_argon = try pass_ok.toString(allocator);
        defer pwd_php_argon.release(allocator);
        const mode: std.crypto.pwhash.argon2.Mode = if (kind == .argon2i) .argon2i else .argon2id;
        var argon_buf: [512]u8 = undefined;
        const argon_hash = std.crypto.pwhash.argon2.strHash(pwd_php_argon.data, .{
            .allocator = allocator,
            .params = .{ .t = @intCast(ap.t), .m = @intCast(ap.m), .p = @intCast(ap.p) },
            .mode = mode,
            .encoding = .phc,
        }, &argon_buf, getIo()) catch
            return throwThrowable("ValueError", "password_hash(): Failed to hash password", runtime_allocator);
        return Value.initString(try PHPString.init(allocator, argon_hash));
    }

    // ★PHP 实测：4..31 之外 ⇒ `Invalid bcrypt cost parameter specified: N`（非数值 ⇒ 0）；缺省 12
    const cost_raw = passwordBcryptCost(options_ok);
    if (cost_raw < 4 or cost_raw > 31) {
        var msg_buf: [96]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Invalid bcrypt cost parameter specified: {d}", .{cost_raw}) catch
            return throwThrowable("ValueError", "Invalid bcrypt cost parameter specified", runtime_allocator);
        return throwThrowable("ValueError", msg, runtime_allocator);
    }
    const cost: u6 = @intCast(cost_raw);

    const pwd_php = try pass_ok.toString(allocator);
    defer pwd_php.release(allocator);
    const pwd = pwd_php.data;

    var hash_buf: [128]u8 = undefined;
    const hash_result = try std.crypto.pwhash.bcrypt.strHash(pwd, .{
        .allocator = allocator,
        .params = .{ .rounds_log = cost, .silently_truncate_password = true },
        .encoding = .crypt,
    }, &hash_buf, getIo());

    // Zig生成$2b$前缀，PHP使用$2y$前缀，替换以保持兼容
    var result_buf: [128]u8 = undefined;
    const result_str = blk: {
        if (hash_result.len >= 4 and hash_result[0] == '$' and hash_result[1] == '2' and hash_result[2] == 'b' and hash_result[3] == '$') {
            result_buf[0] = '$';
            result_buf[1] = '2';
            result_buf[2] = 'y';
            @memcpy(result_buf[3..hash_result.len], hash_result[3..]);
            break :blk result_buf[0..hash_result.len];
        }
        break :blk hash_result;
    };

    const php_str = try PHPString.init(allocator, result_str);
    return Value.initString(php_str);
}

/// password_verify - 验证密码是否匹配哈希
pub fn php_password_verify(password: Value, hash: Value, allocator: Allocator) !Value {
    if (!password.isString() or !hash.isString()) {
        return Value.initBool(false);
    }

    const pwd = password.asString().data;
    const hash_str = hash.asString().data;

    // ★F-168（R-263）：argon2i/id（PHC 编码）走 std 校验
    if (std.mem.startsWith(u8, hash_str, "$argon2i$") or std.mem.startsWith(u8, hash_str, "$argon2id$")) {
        std.crypto.pwhash.argon2.strVerify(hash_str, pwd, .{ .allocator = allocator }, getIo()) catch
            return Value.initBool(false);
        return Value.initBool(true);
    }

    // PHP使用$2y$前缀，Zig期望$2b$前缀，需要转换
    var converted_buf: [128]u8 = undefined;
    const verify_str = blk: {
        if (hash_str.len >= 4 and hash_str[0] == '$' and hash_str[1] == '2' and hash_str[2] == 'y' and hash_str[3] == '$') {
            converted_buf[0] = '$';
            converted_buf[1] = '2';
            converted_buf[2] = 'b';
            if (hash_str.len <= converted_buf.len) {
                @memcpy(converted_buf[3..hash_str.len], hash_str[3..]);
                break :blk converted_buf[0..hash_str.len];
            }
        }
        break :blk hash_str;
    };

    // 使用bcrypt验证
    std.crypto.pwhash.bcrypt.strVerify(verify_str, pwd, .{
        .silently_truncate_password = true,
    }) catch {
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// password_get_info - 返回密码哈希的相关信息
pub fn php_password_get_info(hash_val: Value, allocator: Allocator) !Value {
    if (!hash_val.isString()) {
        // 返回未知算法的空info
        const arr = try PHPArray.init(allocator);
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initNull());
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "unknown")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(try PHPArray.init(allocator)));
        return Value.initArray(arr);
    }

    const hash_str = hash_val.asString().data;

    // 检测bcrypt格式: $2y$XX$ 或 $2b$XX$ 或 $2a$XX$
    if (hash_str.len >= 7 and hash_str[0] == '$' and hash_str[1] == '2' and
        (hash_str[2] == 'y' or hash_str[2] == 'b' or hash_str[2] == 'a') and hash_str[3] == '$')
    {
        // 提取cost值: $2y$XX$...
        const cost_str = hash_str[4..6];
        var cost: i64 = 0;
        for (cost_str) |c| {
            if (c >= '0' and c <= '9') {
                cost = cost * 10 + @as(i64, c - '0');
            }
        }

        const options_arr = try PHPArray.init(allocator);
        try options_arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "cost")), Value.initInt(cost));

        const arr = try PHPArray.init(allocator);
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initString(try PHPString.init(allocator, "2y")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "bcrypt")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(options_arr));
        return Value.initArray(arr);
    }

    // 未知算法
    const arr = try PHPArray.init(allocator);
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initNull());
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "unknown")));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(try PHPArray.init(allocator)));
    return Value.initArray(arr);
}

/// password_needs_rehash - 检查哈希是否需要重新生成
/// password_needs_rehash(hash, algo, options=[])
pub fn php_password_needs_rehash(hash_val: Value, algo: Value, options_val: Value, allocator: Allocator) !Value {
    const hash_ok = requireStringParamWeak("password_needs_rehash", 1, "hash", hash_val) orelse return Value.initNull();
    const algo_ok = requireStringOrIntOrNullParam("password_needs_rehash", 2, "algo", algo) orelse return Value.initNull();
    const options_ok = requireArrayParam("password_needs_rehash", 3, "options", options_val) orelse return Value.initNull();

    const hash_php = try hash_ok.toString(allocator);
    defer hash_php.release(allocator);
    const hash_str = hash_php.data;

    // ★F-62f（R-261）PHP 实测：无效算法 ⇒ false；F-168（R-263）：argon 比较模式与参数
    const kind = passwordAlgoKind(algo_ok);
    if (kind == .invalid) return Value.initBool(false);
    if (kind != .bcrypt) {
        if (kind == .argon2i) {
            if (!std.mem.startsWith(u8, hash_str, "$argon2i$")) return Value.initBool(true);
        } else {
            if (!std.mem.startsWith(u8, hash_str, "$argon2id$")) return Value.initBool(true);
        }
        const stored = passwordArgon2StoredParams(hash_str) orelse return Value.initBool(true);
        const want = passwordArgon2Params(options_ok);
        return Value.initBool(stored.m != want.m or stored.t != want.t or stored.p != want.p);
    }

    // needs_rehash 的 cost **不校验值域**（PHP 实测 3/100/"abc" 均只是 ⇒ true）
    const target_cost = passwordBcryptCost(options_ok);

    // 检查是否是bcrypt格式
    if (hash_str.len >= 7 and hash_str[0] == '$' and hash_str[1] == '2' and
        (hash_str[2] == 'y' or hash_str[2] == 'b' or hash_str[2] == 'a') and hash_str[3] == '$')
    {
        // 提取cost值
        var cost: i64 = 0;
        if (hash_str[4] >= '0' and hash_str[4] <= '9') cost = cost * 10 + @as(i64, hash_str[4] - '0');
        if (hash_str[5] >= '0' and hash_str[5] <= '9') cost = cost * 10 + @as(i64, hash_str[5] - '0');
        return Value.initBool(cost != target_cost);
    }
    // 不是bcrypt格式，需要rehash
    return Value.initBool(true);
}

pub fn php_uniqid(prefix: Value, more_entropy: Value, allocator: Allocator) !Value {
    const prefix_str = if (prefix.isString()) prefix.asString().data else "";
    const ent = more_entropy.toBool();

    // PHP uniqid format: prefix + 8 hex chars (seconds) + 5 hex chars (microseconds/100)
    const timestamp = nanoTimestamp();
    const now_us = @divTrunc(timestamp, 1000); // nanoseconds to microseconds
    const seconds = @as(u64, @intCast(@divTrunc(now_us, 1_000_000)));
    const microseconds = @as(u64, @intCast(@rem(now_us, 1_000_000)));
    // PHP uses microseconds/100 for the last 5 hex chars
    const usec_part = @divTrunc(microseconds, 10);

    var result_buf: [64]u8 = undefined;
    const formatted = if (ent) blk: {
        // With more_entropy: add .XXXXXXXX (8 random decimal digits)
        var rand_bytes: [4]u8 = undefined;
        getRandomBytes(&rand_bytes);
        const rand_val = @as(u32, rand_bytes[0]) * 16777216 + @as(u32, rand_bytes[1]) * 65536 + @as(u32, rand_bytes[2]) * 256 + rand_bytes[3];
        break :blk try std.fmt.bufPrint(&result_buf, "{s}{x}{x:0>5}.{d:0>8}", .{ prefix_str, seconds, usec_part, rand_val % 100000000 });
    } else try std.fmt.bufPrint(&result_buf, "{s}{x}{x:0>5}", .{ prefix_str, seconds, usec_part });

    const php_str = try PHPString.init(allocator, formatted);
    return Value.initString(php_str);
}

/// sha256 - 计算字符串的SHA256哈希值
pub fn php_sha256(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(input, &hash, .{});

    // 转换为十六进制字符串
    var hex_str: [64]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// hash - 生成哈希值
// ============================================================================
// ★F-170（R-266）：RIPEMD-160 / RIPEMD-128（Bosselaers 规范；PHP hash/hmac/pbkdf2 同源）
// ============================================================================
