    128, 127, 93,  154, 90,  144, 50,  39,  53,  62,  204, 231, 191, 247, 151, 3,
    255, 25,  48,  179, 72,  165, 181, 209, 215, 94,  146, 42,  172, 86,  170, 198,
    79,  184, 56,  210, 150, 164, 125, 182, 118, 252, 107, 226, 156, 116, 4,   241,
    69,  157, 112, 89,  100, 113, 135, 32,  134, 91,  207, 101, 230, 45,  168, 2,
    27,  96,  37,  173, 174, 176, 185, 246, 28,  70,  97,  105, 52,  64,  126, 15,
    85,  71,  163, 35,  221, 81,  175, 58,  195, 92,  249, 206, 186, 197, 234, 38,
    44,  83,  13,  110, 133, 40,  132, 9,   211, 223, 205, 244, 65,  129, 77,  82,
    106, 220, 55,  200, 108, 193, 171, 250, 36,  225, 123, 8,   12,  189, 177, 74,
    120, 136, 149, 139, 227, 99,  232, 109, 233, 203, 213, 254, 59,  0,   29,  57,
    242, 239, 183, 14,  102, 88,  208, 228, 166, 119, 114, 248, 235, 117, 75,  10,
    49,  68,  80,  180, 143, 237, 31,  26,  219, 153, 141, 51,  159, 17,  131, 20,
};

fn md2Transform(state: *[16]u8, checksum: *[16]u8, block: *const [16]u8) void {
    var x: [48]u8 = undefined;
    @memcpy(x[0..16], state);
    @memcpy(x[16..32], block);
    for (0..16) |i| x[32 + i] = x[i] ^ block[i];
    var t: u8 = 0;
    for (0..18) |round| {
        for (0..48) |j| {
            x[j] ^= MD2_PI_SUBST[t];
            t = x[j];
        }
        t = t +% @as(u8, @intCast(round));
    }
    @memcpy(state, x[0..16]);
    t = checksum[15];
    for (0..16) |i| {
        checksum[i] ^= MD2_PI_SUBST[block[i] ^ t];
        t = checksum[i];
    }
}

fn md2Hash(input: []const u8) [16]u8 {
    var state: [16]u8 = @as([16]u8, @splat(0));
    var checksum: [16]u8 = @as([16]u8, @splat(0));
    var block: [16]u8 = undefined;
    var count: usize = 0;
    for (input) |b| {
        block[count] = b;
        count += 1;
        if (count == 16) {
            md2Transform(&state, &checksum, &block);
            count = 0;
        }
    }
    // RFC 1319 §3.1：恒补 1..16 字节、值即补长（含整倍数时再补一整块 16×16）
    const pad_len: u8 = @intCast(16 - count);
    while (count < 16) : (count += 1) block[count] = pad_len;
    md2Transform(&state, &checksum, &block);
    // 校验和作为最终块（先拷出避免 block 与 checksum 别名）
    const cblock: [16]u8 = checksum;
    md2Transform(&state, &checksum, &cblock);
    return state;
}
const WP_RC = [11]u64{
