/// ★F-170 尾（whirlpool 族）：Whirlpool 哈希（Barreto & Rijmen 参考实现 / php-src
///   ext/hash/php_hash_whirlpool_tables.h 逐字取表：WP_RC + WP_C0..C7；轮函数结构同
///   php-src hash_whirlpool.c 的 WhirlpoolTransform）。Miyaguchi-Preneel 压缩，512 位摘要。
///   L[i] 通式：XOR_{j=0..7} WP_Cj[(K[(i+8-j)%8] >> (56-8j)) & 0xff]，第 0 字加 WP_RC[r]。
fn whirlpoolTransform(state: *[8]u64, buffer: *const [64]u8) void {
    var K: [8]u64 = undefined;
    var block: [8]u64 = undefined;
    var cipher: [8]u64 = undefined;
    var L: [8]u64 = undefined;
    for (0..8) |i| block[i] = std.mem.readInt(u64, buffer[i * 8 ..][0..8], .big);
    for (0..8) |i| {
        K[i] = state[i];
        cipher[i] = block[i] ^ K[i];
    }
    const cts = [8]*const [256]u64{ &WP_C0, &WP_C1, &WP_C2, &WP_C3, &WP_C4, &WP_C5, &WP_C6, &WP_C7 };
    var r: usize = 1;
    while (r <= 10) : (r += 1) {
        for (0..8) |i| {
            var v: u64 = 0;
            for (0..8) |j| {
                const idx: u8 = @truncate(K[(i + 8 - j) % 8] >> @intCast(56 - 8 * j));
                v ^= cts[j][idx];
            }
            L[i] = v;
        }
        L[0] ^= WP_RC[r];
        K = L;
        for (0..8) |i| {
            var v: u64 = 0;
            for (0..8) |j| {
                const idx: u8 = @truncate(cipher[(i + 8 - j) % 8] >> @intCast(56 - 8 * j));
                v ^= cts[j][idx];
            }
            L[i] = v ^ K[i];
        }
        cipher = L;
    }
    // Miyaguchi-Preneel：H ^= cipher ^ block
    for (0..8) |i| state[i] ^= cipher[i] ^ block[i];
}

fn whirlpoolHash(input: []const u8) [64]u8 {
    var state: [8]u64 = @as([8]u64, @splat(0));
    var i: usize = 0;
    while (i + 64 <= input.len) : (i += 64) {
        whirlpoolTransform(&state, input[i..][0..64]);
    }
    // 填充：补 0x80，补零到末 32 字节前，最后 32 字节为位长（256 位大端）
    var block: [64]u8 = @as([64]u8, @splat(0));
    const rem = input[i..];
    @memcpy(block[0..rem.len], rem);
    block[rem.len] = 0x80;
    if (rem.len + 1 > 64 - 32) {
        whirlpoolTransform(&state, &block);
        block = @as([64]u8, @splat(0));
    }
    std.mem.writeInt(u256, block[32..64], @as(u256, input.len) * 8, .big);
    whirlpoolTransform(&state, &block);
    var digest: [64]u8 = undefined;
    for (state, 0..) |s, k| std.mem.writeInt(u64, digest[k * 8 ..][0..8], s, .big);
    return digest;
}
