/// ★F-170 尾（tiger 族）：Tiger 哈希（Anderson & Biham, FSE'96；表取自 php-src
///   ext/hash/php_hash_tiger_tables.h 的 table[4*256] 逐字拆为 TIGER_T1..T4，轮函数结构同
///   php-src hash_tiger.c）。块 64 字节小端 split；3 轮（passes=0：mul 5/7/9）或 4 轮
///   （passes=1：+mul 9 额外 pass）；填充 0x01 + 补零到 8 倍数 + 56 字节位小端位长；
///   摘要小端截取 out_len ∈ {16,20,24}。
fn tigerRound(a: *u64, b: *u64, c: *u64, x: u64, comptime mul: u64) void {
    c.* ^= x;
    a.* -%= TIGER_T1[@as(u8, @truncate(c.*))] ^
        TIGER_T2[@as(u8, @truncate(c.* >> 16))] ^
        TIGER_T3[@as(u8, @truncate(c.* >> 32))] ^
        TIGER_T4[@as(u8, @truncate(c.* >> 48))];
    b.* +%= TIGER_T4[@as(u8, @truncate(c.* >> 8))] ^
        TIGER_T3[@as(u8, @truncate(c.* >> 24))] ^
        TIGER_T2[@as(u8, @truncate(c.* >> 40))] ^
        TIGER_T1[@as(u8, @truncate(c.* >> 56))];
    b.* *%= mul;
}

fn tigerKeySchedule(x: *[8]u64) void {
    x[0] -%= x[7] ^ 0xA5A5A5A5A5A5A5A5;
    x[1] ^= x[0];
    x[2] +%= x[1];
    x[3] -%= x[2] ^ (~x[1] << 19);
    x[4] ^= x[3];
    x[5] +%= x[4];
    x[6] -%= x[5] ^ (~x[4] >> 23);
    x[7] ^= x[6];
    x[0] +%= x[7];
    x[1] -%= x[0] ^ (~x[7] << 19);
    x[2] ^= x[1];
    x[3] +%= x[2];
    x[4] -%= x[3] ^ (~x[2] >> 23);
    x[5] ^= x[4];
    x[6] +%= x[5];
    x[7] -%= x[6] ^ 0x0123456789ABCDEF;
}

fn tigerPass(a: *u64, b: *u64, c: *u64, x: *const [8]u64, comptime mul: u64) void {
    tigerRound(a, b, c, x[0], mul);
    tigerRound(b, c, a, x[1], mul);
    tigerRound(c, a, b, x[2], mul);
    tigerRound(a, b, c, x[3], mul);
    tigerRound(b, c, a, x[4], mul);
    tigerRound(c, a, b, x[5], mul);
    tigerRound(a, b, c, x[6], mul);
    tigerRound(b, c, a, x[7], mul);
}

fn tigerCompress(comptime extra_passes: u32, block: *const [64]u8, state: *[3]u64) void {
    var x: [8]u64 = undefined;
    for (0..8) |i| x[i] = std.mem.readInt(u64, block[i * 8 ..][0..8], .little);
    var a = state[0];
    var b = state[1];
    var c = state[2];
    const aa = a;
    const bb = b;
    const cc = c;
    tigerPass(&a, &b, &c, &x, 5);
    tigerKeySchedule(&x);
    tigerPass(&c, &a, &b, &x, 7);
    tigerKeySchedule(&x);
    tigerPass(&b, &c, &a, &x, 9);
    for (0..extra_passes) |_| {
        tigerKeySchedule(&x);
        tigerPass(&a, &b, &c, &x, 9);
        const tmpa = a;
        a = c;
        c = b;
        b = tmpa;
    }
    a ^= aa;
    b -%= bb;
    c +%= cc;
    state[0] = a;
    state[1] = b;
    state[2] = c;
}

fn tigerHash(comptime extra_passes: u32, comptime out_len: usize, input: []const u8) [out_len]u8 {
    var state = [3]u64{ 0x0123456789ABCDEF, 0xFEDCBA9876543210, 0xF096A5B4C3B2E187 };
    var i: usize = 0;
    while (i + 64 <= input.len) : (i += 64) {
        tigerCompress(extra_passes, input[i..][0..64], &state);
    }
    var block: [64]u8 = @as([64]u8, @splat(0));
    const rem = input[i..];
    @memcpy(block[0..rem.len], rem);
    var length: usize = rem.len;
    block[length] = 0x01;
    length += 1;
    if (length % 8 != 0) length += 8 - length % 8;
    if (length > 56) {
        tigerCompress(extra_passes, &block, &state);
        block = @as([64]u8, @splat(0));
    }
    std.mem.writeInt(u64, block[56..64], @as(u64, input.len) * 8, .little);
    tigerCompress(extra_passes, &block, &state);
    var digest: [out_len]u8 = undefined;
    for (0..out_len) |k| digest[k] = @truncate(state[k / 8] >> @intCast(8 * (k % 8)));
    return digest;
}

fn tiger128_3(input: []const u8) [16]u8 { return tigerHash(0, 16, input); }
fn tiger160_3(input: []const u8) [20]u8 { return tigerHash(0, 20, input); }
fn tiger192_3(input: []const u8) [24]u8 { return tigerHash(0, 24, input); }
fn tiger128_4(input: []const u8) [16]u8 { return tigerHash(1, 16, input); }
fn tiger160_4(input: []const u8) [20]u8 { return tigerHash(1, 20, input); }
fn tiger192_4(input: []const u8) [24]u8 { return tigerHash(1, 24, input); }
