/// ★F-170 尾（haval 族）：HAVAL（Zheng-Pieprzyk-Seberry；常量与轮结构取自 php-src
///   ext/hash/hash_haval.c：HAVAL_K2..K5 / I2..I5 / M0..M7 / D0 逐字）。块 128 字节，
///   3/4/5 轮 × 128/160/192/224/256 截尾折叠共 15 形。HMAC 块长 = 128。
const HAVAL_M = [8][32]u8{ HAVAL_M0, HAVAL_M1, HAVAL_M2, HAVAL_M3, HAVAL_M4, HAVAL_M5, HAVAL_M6, HAVAL_M7 };

fn havalF(comptime f: u8, x6: u32, x5: u32, x4: u32, x3: u32, x2: u32, x1: u32, x0: u32) u32 {
    return switch (f) {
        1 => (x1 & x4) ^ (x2 & x5) ^ (x3 & x6) ^ (x0 & x1) ^ x0,
        2 => (x1 & x2 & x3) ^ (x2 & x4 & x5) ^ (x1 & x2) ^ (x1 & x4) ^ (x2 & x6) ^ (x3 & x5) ^ (x4 & x5) ^ (x0 & x2) ^ x0,
        3 => (x1 & x2 & x3) ^ (x1 & x4) ^ (x2 & x5) ^ (x3 & x6) ^ (x0 & x3) ^ x0,
        4 => (x1 & x2 & x3) ^ (x2 & x4 & x5) ^ (x3 & x4 & x6) ^ (x1 & x4) ^ (x2 & x6) ^ (x3 & x4) ^ (x3 & x5) ^ (x3 & x6) ^ (x4 & x5) ^ (x4 & x6) ^ (x0 & x4) ^ x0,
        5 => (x1 & x4) ^ (x2 & x5) ^ (x3 & x6) ^ (x0 & x1 & x2 & x3) ^ (x0 & x5) ^ x0,
        else => unreachable,
    };
}

const HavalPassSpec = struct {
    f: u8,
    perm: [7]u8, // F 参数 (x6,x5,x4,x3,x2,x1,x0) 各自取 E[M_k[i]] 的 M 表编号
    feed: u8, // 加项 ROTR(E[M_feed[i]], 11) 的 M 表编号（恒 7）
    idx: ?[]const u8, // x 索引表（pass1 为 null 恒等）
    k: ?[]const u32, // 轮常数表（pass1 为 null）
};

fn havalSpecs(comptime passes: u32) []const HavalPassSpec {
    return switch (passes) {
        3 => &.{
            .{ .f = 1, .perm = .{ 1, 0, 3, 5, 6, 2, 4 }, .feed = 7, .idx = null, .k = null },
            .{ .f = 2, .perm = .{ 4, 2, 1, 0, 5, 3, 6 }, .feed = 7, .idx = &HAVAL_I2, .k = &HAVAL_K2 },
            .{ .f = 3, .perm = .{ 6, 1, 2, 3, 4, 5, 0 }, .feed = 7, .idx = &HAVAL_I3, .k = &HAVAL_K3 },
        },
        4 => &.{
            .{ .f = 1, .perm = .{ 2, 6, 1, 4, 5, 3, 0 }, .feed = 7, .idx = null, .k = null },
            .{ .f = 2, .perm = .{ 3, 5, 2, 0, 1, 6, 4 }, .feed = 7, .idx = &HAVAL_I2, .k = &HAVAL_K2 },
            .{ .f = 3, .perm = .{ 1, 4, 3, 6, 0, 2, 5 }, .feed = 7, .idx = &HAVAL_I3, .k = &HAVAL_K3 },
            .{ .f = 4, .perm = .{ 6, 4, 0, 5, 2, 1, 3 }, .feed = 7, .idx = &HAVAL_I4, .k = &HAVAL_K4 },
        },
        5 => &.{
            .{ .f = 1, .perm = .{ 3, 4, 1, 0, 5, 2, 6 }, .feed = 7, .idx = null, .k = null },
            .{ .f = 2, .perm = .{ 6, 2, 1, 0, 3, 4, 5 }, .feed = 7, .idx = &HAVAL_I2, .k = &HAVAL_K2 },
            .{ .f = 3, .perm = .{ 2, 6, 0, 4, 3, 1, 5 }, .feed = 7, .idx = &HAVAL_I3, .k = &HAVAL_K3 },
            .{ .f = 4, .perm = .{ 1, 5, 3, 2, 0, 4, 6 }, .feed = 7, .idx = &HAVAL_I4, .k = &HAVAL_K4 },
            .{ .f = 5, .perm = .{ 2, 5, 0, 6, 4, 3, 1 }, .feed = 7, .idx = &HAVAL_I5, .k = &HAVAL_K5 },
        },
        else => unreachable,
    };
}

fn havalTransform(comptime passes: u32, state: *[8]u32, block: *const [128]u8) void {
    var x: [32]u32 = undefined;
    for (0..32) |j| x[j] = std.mem.readInt(u32, block[j * 4 ..][0..4], .little);
    var E = state.*;
    inline for (comptime havalSpecs(passes)) |sp| {
        for (0..32) |i| {
            const xv = if (sp.idx) |ix| x[ix[i]] else x[i];
            const kv: u32 = if (sp.k) |kk| kk[i] else 0;
            E[7 - (i % 8)] = std.math.rotr(u32, havalF(sp.f, E[HAVAL_M[sp.perm[0]][i]], E[HAVAL_M[sp.perm[1]][i]], E[HAVAL_M[sp.perm[2]][i]], E[HAVAL_M[sp.perm[3]][i]], E[HAVAL_M[sp.perm[4]][i]], E[HAVAL_M[sp.perm[5]][i]], E[HAVAL_M[sp.perm[6]][i]]), 7) +%
                std.math.rotr(u32, E[HAVAL_M[sp.feed][i]], 11) +% xv +% kv;
        }
    }
    for (0..8) |j| state[j] +%= E[j];
}

fn havalHash(comptime passes: u32, comptime out_bits: u32, input: []const u8) [out_bits / 8]u8 {
    var state = HAVAL_D0;
    var i: usize = 0;
    while (i + 128 <= input.len) : (i += 128) {
        havalTransform(passes, &state, input[i..][0..128]);
    }
    // 填充：0x01 后补零到 118 (mod 128)，再 10 字节尾（版本|轮数|摘要长 + 位长 u64 小端）
    var tail: [256]u8 = @as([256]u8, @splat(0));
    const rem = input[i..];
    @memcpy(tail[0..rem.len], rem);
    tail[rem.len] = 0x01;
    const index = rem.len % 128;
    const pad_len: usize = if (index < 118) 118 - index else 246 - index;
    const end = index + pad_len;
    tail[end] = 0x01 | (@as(u8, passes) << 3) | (@as(u8, @truncate(out_bits & 0x03)) << 6);
    tail[end + 1] = @truncate(out_bits >> 2);
    std.mem.writeInt(u64, tail[end + 2 ..][0..8], @as(u64, input.len) * 8, .little);
    const total = end + 10;
    havalTransform(passes, &state, tail[0..128]);
    if (total == 256) havalTransform(passes, &state, tail[128..256]);

    // 截尾折叠（Finalize folding，按摘要位长）
    switch (out_bits) {
        128 => {
            state[3] +%= (state[7] & 0xFF000000) | (state[6] & 0x00FF0000) | (state[5] & 0x0000FF00) | (state[4] & 0x000000FF);
            state[2] +%= (((state[7] & 0x00FF0000) | (state[6] & 0x0000FF00) | (state[5] & 0x000000FF)) << 8) | ((state[4] & 0xFF000000) >> 24);
            state[1] +%= (((state[7] & 0x0000FF00) | (state[6] & 0x000000FF)) << 16) | (((state[5] & 0xFF000000) | (state[4] & 0x00FF0000)) >> 16);
            state[0] +%= ((state[7] & 0x000000FF) << 24) | (((state[6] & 0xFF000000) | (state[5] & 0x00FF0000) | (state[4] & 0x0000FF00)) >> 8);
        },
        160 => {
            state[4] +%= ((state[7] & 0xFE000000) | (state[6] & 0x01F80000) | (state[5] & 0x0007F000)) >> 12;
            state[3] +%= ((state[7] & 0x01F80000) | (state[6] & 0x0007F000) | (state[5] & 0x00000FC0)) >> 6;
            state[2] +%= (state[7] & 0x0007F000) | (state[6] & 0x00000FC0) | (state[5] & 0x0000003F);
            state[1] +%= std.math.rotr(u32, (state[7] & 0x00000FC0) | (state[6] & 0x0000003F) | (state[5] & 0xFE000000), 25);
            state[0] +%= std.math.rotr(u32, (state[7] & 0x0000003F) | (state[6] & 0xFE000000) | (state[5] & 0x01F80000), 19);
        },
        192 => {
            state[5] +%= ((state[7] & 0xFC000000) | (state[6] & 0x03E00000)) >> 21;
            state[4] +%= ((state[7] & 0x03E00000) | (state[6] & 0x001F0000)) >> 16;
            state[3] +%= ((state[7] & 0x001F0000) | (state[6] & 0x0000FC00)) >> 10;
            state[2] +%= ((state[7] & 0x0000FC00) | (state[6] & 0x000003E0)) >> 5;
            state[1] +%= (state[7] & 0x000003E0) | (state[6] & 0x0000001F);
            state[0] +%= std.math.rotr(u32, (state[7] & 0x0000001F) | (state[6] & 0xFC000000), 26);
        },
        224 => {
            state[6] +%= state[7] & 0x0000000F;
            state[5] +%= (state[7] >> 4) & 0x0000001F;
            state[4] +%= (state[7] >> 9) & 0x0000000F;
            state[3] +%= (state[7] >> 13) & 0x0000001F;
            state[2] +%= (state[7] >> 18) & 0x0000000F;
            state[1] +%= (state[7] >> 22) & 0x0000001F;
            state[0] +%= (state[7] >> 27) & 0x0000001F;
        },
        256 => {},
        else => unreachable,
    }
    var digest: [out_bits / 8]u8 = undefined;
    for (0..(out_bits / 8)) |j| digest[j] = @truncate(state[j / 4] >> @intCast(8 * (j % 4)));
    return digest;
}

fn haval128_3(input: []const u8) [16]u8 { return havalHash(3, 128, input); }
fn haval160_3(input: []const u8) [20]u8 { return havalHash(3, 160, input); }
fn haval192_3(input: []const u8) [24]u8 { return havalHash(3, 192, input); }
fn haval224_3(input: []const u8) [28]u8 { return havalHash(3, 224, input); }
fn haval256_3(input: []const u8) [32]u8 { return havalHash(3, 256, input); }
fn haval128_4(input: []const u8) [16]u8 { return havalHash(4, 128, input); }
fn haval160_4(input: []const u8) [20]u8 { return havalHash(4, 160, input); }
fn haval192_4(input: []const u8) [24]u8 { return havalHash(4, 192, input); }
fn haval224_4(input: []const u8) [28]u8 { return havalHash(4, 224, input); }
fn haval256_4(input: []const u8) [32]u8 { return havalHash(4, 256, input); }
fn haval128_5(input: []const u8) [16]u8 { return havalHash(5, 128, input); }
fn haval160_5(input: []const u8) [20]u8 { return havalHash(5, 160, input); }
fn haval192_5(input: []const u8) [24]u8 { return havalHash(5, 192, input); }
fn haval224_5(input: []const u8) [28]u8 { return havalHash(5, 224, input); }
fn haval256_5(input: []const u8) [32]u8 { return havalHash(5, 256, input); }
