    haval128_5,
    haval160_5,
    haval192_5,
    haval224_5,
    haval256_5,
    snefru,
    snefru256,
};

fn pbkdf2AlgoFromName(name: []const u8) ?Pbkdf2Algo {
    if (std.mem.eql(u8, name, "sha1")) return .sha1;
    if (std.mem.eql(u8, name, "sha224")) return .sha224;
    if (std.mem.eql(u8, name, "sha256")) return .sha256;
    if (std.mem.eql(u8, name, "sha384")) return .sha384;
    if (std.mem.eql(u8, name, "sha512")) return .sha512;
    if (std.mem.eql(u8, name, "sha512/224") or std.mem.eql(u8, name, "sha512-224")) return .sha512_224;
    if (std.mem.eql(u8, name, "sha512/256") or std.mem.eql(u8, name, "sha512-256")) return .sha512_256;
    if (std.mem.eql(u8, name, "sha3-224")) return .sha3_224;
    if (std.mem.eql(u8, name, "sha3-256")) return .sha3_256;
    if (std.mem.eql(u8, name, "sha3-384")) return .sha3_384;
    if (std.mem.eql(u8, name, "sha3-512")) return .sha3_512;
    if (std.mem.eql(u8, name, "md5")) return .md5;
    if (std.mem.eql(u8, name, "ripemd160")) return .ripemd160;
    if (std.mem.eql(u8, name, "ripemd128")) return .ripemd128;
    if (std.mem.eql(u8, name, "ripemd256")) return .ripemd256;
    if (std.mem.eql(u8, name, "ripemd320")) return .ripemd320;
    if (std.mem.eql(u8, name, "md4")) return .md4;
    if (std.mem.eql(u8, name, "md2")) return .md2;
    if (std.mem.eql(u8, name, "whirlpool")) return .whirlpool;
    if (std.mem.eql(u8, name, "tiger128,3")) return .tiger128_3;
    if (std.mem.eql(u8, name, "tiger160,3")) return .tiger160_3;
    if (std.mem.eql(u8, name, "tiger192,3")) return .tiger192_3;
    if (std.mem.eql(u8, name, "tiger128,4")) return .tiger128_4;
    if (std.mem.eql(u8, name, "tiger160,4")) return .tiger160_4;
    if (std.mem.eql(u8, name, "tiger192,4")) return .tiger192_4;
    if (std.mem.eql(u8, name, "gost")) return .gost;
    if (std.mem.eql(u8, name, "gost-crypto")) return .gost_crypto;
    if (std.mem.eql(u8, name, "haval128,3")) return .haval128_3;
    if (std.mem.eql(u8, name, "haval160,3")) return .haval160_3;
    if (std.mem.eql(u8, name, "haval192,3")) return .haval192_3;
    if (std.mem.eql(u8, name, "haval224,3")) return .haval224_3;
    if (std.mem.eql(u8, name, "haval256,3")) return .haval256_3;
    if (std.mem.eql(u8, name, "haval128,4")) return .haval128_4;
    if (std.mem.eql(u8, name, "haval160,4")) return .haval160_4;
    if (std.mem.eql(u8, name, "haval192,4")) return .haval192_4;
    if (std.mem.eql(u8, name, "haval224,4")) return .haval224_4;
    if (std.mem.eql(u8, name, "haval256,4")) return .haval256_4;
    if (std.mem.eql(u8, name, "haval128,5")) return .haval128_5;
    if (std.mem.eql(u8, name, "haval160,5")) return .haval160_5;
    if (std.mem.eql(u8, name, "haval192,5")) return .haval192_5;
    if (std.mem.eql(u8, name, "haval224,5")) return .haval224_5;
    if (std.mem.eql(u8, name, "haval256,5")) return .haval256_5;
    if (std.mem.eql(u8, name, "snefru")) return .snefru;
    if (std.mem.eql(u8, name, "snefru256")) return .snefru256;
    return null;
}

fn pbkdf2AlgoHlen(kind: Pbkdf2Algo) usize {
    return switch (kind) {
        .sha1 => 20,
        .sha224, .sha512_224, .sha3_224 => 28,
        .sha256, .sha512_256, .sha3_256 => 32,
        .sha384, .sha3_384 => 48,
        .sha512, .sha3_512 => 64,
        .md5, .ripemd128 => 16,
        .ripemd160 => 20,
        .ripemd256 => 32,
        .ripemd320 => 40,
        .md4 => 16,
        .md2 => 16,
        .whirlpool => 64,
        .tiger128_3, .tiger128_4 => 16,
        .tiger160_3, .tiger160_4 => 20,
        .tiger192_3, .tiger192_4 => 24,
        .gost, .gost_crypto => 32,
        .haval128_3 => 16,
        .haval160_3 => 20,
        .haval192_3 => 24,
        .haval224_3 => 28,
        .haval256_3 => 32,
        .haval128_4 => 16,
        .haval160_4 => 20,
        .haval192_4 => 24,
        .haval224_4 => 28,
        .haval256_4 => 32,
        .haval128_5 => 16,
        .haval160_5 => 20,
        .haval192_5 => 24,
        .haval224_5 => 28,
        .haval256_5 => 32,
        .snefru, .snefru256 => 32,
    };
}

/// ★F-169（R-262）：PBKDF2 主循环（HMAC 取 std 同名哈希；`dk.len` 决定块数）。
fn pbkdf2Fill(comptime Hash: type, password: []const u8, salt_str: []const u8, iterations: u32, dk: []u8, allocator: Allocator) !void {
    const Hlen = Hash.digest_length;
    const Hmac = std.crypto.auth.hmac.Hmac(Hash);
    const num_blocks: usize = (dk.len + Hlen - 1) / Hlen;

    var block_index: u32 = 1;
    while (block_index <= num_blocks) : (block_index += 1) {
        // U1 = HMAC(password, salt || INT_32_BE(block_index))
        var salt_block = try allocator.alloc(u8, salt_str.len + 4);
        defer allocator.free(salt_block);
        @memcpy(salt_block[0..salt_str.len], salt_str);
        salt_block[salt_str.len] = @intCast((block_index >> 24) & 0xFF);
        salt_block[salt_str.len + 1] = @intCast((block_index >> 16) & 0xFF);
        salt_block[salt_str.len + 2] = @intCast((block_index >> 8) & 0xFF);
        salt_block[salt_str.len + 3] = @intCast(block_index & 0xFF);

        var u_prev: [Hlen]u8 = undefined;
        var u_curr: [Hlen]u8 = undefined;
        var hmac = Hmac.init(password);
        hmac.update(salt_block);
        hmac.final(&u_prev);

        // T = U1
        const offset = (block_index - 1) * Hlen;
        @memcpy(dk[offset .. offset + Hlen], &u_prev);

        // U2...Uc, XOR into T
        var iter: u32 = 1;
        while (iter < iterations) : (iter += 1) {
            var hm = Hmac.init(password);
            hm.update(&u_prev);
            hm.final(&u_curr);
            for (0..Hlen) |j| dk[offset + j] ^= u_curr[j];
            u_prev = u_curr;
        }
    }
}

/// hash_pbkdf2 - PBKDF2 密钥派生函数
pub fn php_hash_pbkdf2(algo: Value, password: Value, salt: Value, iterations: Value, length: Value, raw_output: Value, options_val: Value, allocator: Allocator) !Value {
    // ★F-62f 接线第四批（门 BLT 段 I b179/b180，R-195）：#4 `$iterations`／#5 `$length` 实测都是**裸 `int`**（工单 §104.5）。
    //   ★同样置于下面三枚 string 早退**之上**：PHP 的参数类型检查先于函数体 ⇒ `hash_pbkdf2("x","y","z",$o)` 必须抛而不是返回 false。
    //   ★**只接类型拒**：`@max(1,…)`／`@max(0,…)` 两处夹取是另一枚面——实测 PHP 给
    //   `ValueError: hash_pbkdf2(): Argument #4 ($iterations) must be greater than 0`（`-1`／`0` 都抛）与
    //   `Argument #5 ($length) must be greater than or equal to 0`（`-1` 抛），
    //   而 ★`length=0` 是**合法哨兵**（PHP 返回整个摘要＝64 位十六进制，门臂 b206）⇒ 禁当越界夹掉；两形都属 F-126（#142）。
    // ★F-62f（R-261）：#1/#2/#3 是 string 槽（weak 接受标量）；#1 的「非已知算法」是 ValueError
    const algo_ok = requireStringParamWeak("hash_pbkdf2", 1, "algo", algo) orelse return Value.initNull();
    const password_ok = requireStringParamWeak("hash_pbkdf2", 2, "password", password) orelse return Value.initNull();
    const salt_ok = requireStringParamWeak("hash_pbkdf2", 3, "salt", salt) orelse return Value.initNull();
    const iterations_ok = requireNumParam("hash_pbkdf2", 4, "iterations", .int_param, iterations) orelse return Value.initNull();
    const length_ok = requireNumParam("hash_pbkdf2", 5, "length", .int_param, length) orelse return Value.initNull();
    // ★F-62f（R-261）：#7 `$options` 是严格 array（显式 null 也拒）；内容 PHP 实测忽略
    const options_ok = requireArrayParam("hash_pbkdf2", 7, "options", options_val) orelse return Value.initNull();
    _ = options_ok;

    // ★F-126（R-229）：iterations<=0／length<0 是 ValueError；length=0 仍是“整摘要”哨兵
    const iterations_raw = iterations_ok.toInt();
    if (iterations_raw <= 0) {
        return throwThrowable("ValueError", "hash_pbkdf2(): Argument #4 ($iterations) must be greater than 0", runtime_allocator);
    }
    const length_raw = length_ok.toInt();
    if (length_raw < 0) {
        return throwThrowable("ValueError", "hash_pbkdf2(): Argument #5 ($length) must be greater than or equal to 0", runtime_allocator);
    }

    const algo_php = try algo_ok.toString(allocator);
    defer algo_php.release(allocator);
    const password_php = try password_ok.toString(allocator);
    defer password_php.release(allocator);
    const salt_php = try salt_ok.toString(allocator);
    defer salt_php.release(allocator);
    var algo_name_buf: [128]u8 = undefined;
    const algo_str = hashAlgoLower(algo_php.data, &algo_name_buf);
    const password_str = password_php.data;
    const salt_str = salt_php.data;
    const iterations_count: u32 = @truncate(@as(u64, @bitCast(iterations_raw)));
    const dklen: usize = @intCast(length_raw);
    const raw = raw_output.toBool();

    // ★F-169（R-262）：算法族与摘要长度。★F-172-b（R-268）已把「不支持」的处置改成分诊（见下）。
    // ★F-172-b（R-268）：先按 PHP 注册表分诊——不在 `hash_hmac_algos()` 里的名字才抛 ValueError；
    //   PHP 认可但 AOT 未实现的（whirlpool/tiger/gost/haval/snefru/md2/md4/ripemd256/320）**不能抛**
    //   （PHP 会返回派生值，抛错＝过度致命）⇒ 返回 false，缺口登记 F-170 尾。
    const kind = pbkdf2AlgoFromName(algo_str) orelse {
        if (!hashAlgoInList(algo_str, &HASH_CRYPTO_ALGOS)) {
            return throwThrowable("ValueError", "hash_pbkdf2(): Argument #1 ($algo) must be a valid cryptographic hashing algorithm", runtime_allocator);
        }
        return Value.initBool(false);
    };
    const hlen = pbkdf2AlgoHlen(kind);

    // PHP: length 参数在 binary=false 时是十六进制字符串长度，实际字节数为 length/2
    // 在 binary=true 时是原始字节长度
    const raw_dklen: usize = if (dklen == 0) hlen else if (raw) dklen else (dklen + 1) / 2;
    const actual_dklen = raw_dklen;

    // PBKDF2 算法（按哈希类型泛化）
    const num_blocks: usize = (actual_dklen + hlen - 1) / hlen;
    var dk = try allocator.alloc(u8, num_blocks * hlen);
    defer allocator.free(dk);

    const Sha2 = std.crypto.hash.sha2;
    const Sha3 = std.crypto.hash.sha3;
    switch (kind) {
        .sha1 => try pbkdf2Fill(std.crypto.hash.Sha1, password_str, salt_str, iterations_count, dk, allocator),
        .sha224 => try pbkdf2Fill(Sha2.Sha224, password_str, salt_str, iterations_count, dk, allocator),
        .sha256 => try pbkdf2Fill(Sha2.Sha256, password_str, salt_str, iterations_count, dk, allocator),
        .sha384 => try pbkdf2Fill(Sha2.Sha384, password_str, salt_str, iterations_count, dk, allocator),
        .sha512 => try pbkdf2Fill(Sha2.Sha512, password_str, salt_str, iterations_count, dk, allocator),
        .sha512_224 => try pbkdf2Fill(Sha2.Sha512_224, password_str, salt_str, iterations_count, dk, allocator),
        .sha512_256 => try pbkdf2Fill(Sha2.Sha512_256, password_str, salt_str, iterations_count, dk, allocator),
        .sha3_224 => try pbkdf2Fill(Sha3.Sha3_224, password_str, salt_str, iterations_count, dk, allocator),
        .sha3_256 => try pbkdf2Fill(Sha3.Sha3_256, password_str, salt_str, iterations_count, dk, allocator),
        .sha3_384 => try pbkdf2Fill(Sha3.Sha3_384, password_str, salt_str, iterations_count, dk, allocator),
        .sha3_512 => try pbkdf2Fill(Sha3.Sha3_512, password_str, salt_str, iterations_count, dk, allocator),
        .md5 => try pbkdf2Fill(std.crypto.hash.Md5, password_str, salt_str, iterations_count, dk, allocator),
        .ripemd160 => try pbkdf2FillCustom(20, 64, ripemd160Hash, password_str, salt_str, iterations_count, dk, allocator),
        .ripemd128 => try pbkdf2FillCustom(16, 64, ripemd128Hash, password_str, salt_str, iterations_count, dk, allocator),
        .ripemd256 => try pbkdf2FillCustom(32, 64, ripemd256Hash, password_str, salt_str, iterations_count, dk, allocator),
        .ripemd320 => try pbkdf2FillCustom(40, 64, ripemd320Hash, password_str, salt_str, iterations_count, dk, allocator),
        .md4 => try pbkdf2FillCustom(16, 64, md4Hash, password_str, salt_str, iterations_count, dk, allocator),
        .md2 => try pbkdf2FillCustom(16, 16, md2Hash, password_str, salt_str, iterations_count, dk, allocator),
        .whirlpool => try pbkdf2FillCustom(64, 64, whirlpoolHash, password_str, salt_str, iterations_count, dk, allocator),
        .tiger128_3 => try pbkdf2FillCustom(16, 64, tiger128_3, password_str, salt_str, iterations_count, dk, allocator),
        .tiger160_3 => try pbkdf2FillCustom(20, 64, tiger160_3, password_str, salt_str, iterations_count, dk, allocator),
        .tiger192_3 => try pbkdf2FillCustom(24, 64, tiger192_3, password_str, salt_str, iterations_count, dk, allocator),
        .tiger128_4 => try pbkdf2FillCustom(16, 64, tiger128_4, password_str, salt_str, iterations_count, dk, allocator),
        .tiger160_4 => try pbkdf2FillCustom(20, 64, tiger160_4, password_str, salt_str, iterations_count, dk, allocator),
        .tiger192_4 => try pbkdf2FillCustom(24, 64, tiger192_4, password_str, salt_str, iterations_count, dk, allocator),
        .gost => try pbkdf2FillCustom(32, 32, gostTest, password_str, salt_str, iterations_count, dk, allocator),
        .gost_crypto => try pbkdf2FillCustom(32, 32, gostCrypto, password_str, salt_str, iterations_count, dk, allocator),
        .haval128_3 => try pbkdf2FillCustom(16, 128, haval128_3, password_str, salt_str, iterations_count, dk, allocator),
        .haval160_3 => try pbkdf2FillCustom(20, 128, haval160_3, password_str, salt_str, iterations_count, dk, allocator),
        .haval192_3 => try pbkdf2FillCustom(24, 128, haval192_3, password_str, salt_str, iterations_count, dk, allocator),
        .haval224_3 => try pbkdf2FillCustom(28, 128, haval224_3, password_str, salt_str, iterations_count, dk, allocator),
        .haval256_3 => try pbkdf2FillCustom(32, 128, haval256_3, password_str, salt_str, iterations_count, dk, allocator),
        .haval128_4 => try pbkdf2FillCustom(16, 128, haval128_4, password_str, salt_str, iterations_count, dk, allocator),
        .haval160_4 => try pbkdf2FillCustom(20, 128, haval160_4, password_str, salt_str, iterations_count, dk, allocator),
        .haval192_4 => try pbkdf2FillCustom(24, 128, haval192_4, password_str, salt_str, iterations_count, dk, allocator),
        .haval224_4 => try pbkdf2FillCustom(28, 128, haval224_4, password_str, salt_str, iterations_count, dk, allocator),
        .haval256_4 => try pbkdf2FillCustom(32, 128, haval256_4, password_str, salt_str, iterations_count, dk, allocator),
        .haval128_5 => try pbkdf2FillCustom(16, 128, haval128_5, password_str, salt_str, iterations_count, dk, allocator),
        .haval160_5 => try pbkdf2FillCustom(20, 128, haval160_5, password_str, salt_str, iterations_count, dk, allocator),
        .haval192_5 => try pbkdf2FillCustom(24, 128, haval192_5, password_str, salt_str, iterations_count, dk, allocator),
        .haval224_5 => try pbkdf2FillCustom(28, 128, haval224_5, password_str, salt_str, iterations_count, dk, allocator),
        .haval256_5 => try pbkdf2FillCustom(32, 128, haval256_5, password_str, salt_str, iterations_count, dk, allocator),
        .snefru, .snefru256 => try pbkdf2FillCustom(32, 32, snefruHash, password_str, salt_str, iterations_count, dk, allocator),
    }

    if (raw) {
        const result = try allocator.alloc(u8, actual_dklen);
        @memcpy(result, dk[0..actual_dklen]);
        const php_str = try PHPString.init(allocator, result);
        allocator.free(result);
        return Value.initString(php_str);
    }

    // 十六进制输出
    const hex_len = actual_dklen * 2;
    const hex_str = try allocator.alloc(u8, hex_len);
    defer allocator.free(hex_str);
    const hex_chars = "0123456789abcdef";
    for (dk[0..actual_dklen], 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    return Value.initString(try PHPString.init(allocator, hex_str));
}

/// crc32 - 计算字符串的CRC32校验值
pub fn php_crc32(str: Value) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    const crc = std.hash.Crc32.hash(input);
    // PHP 64-bit: crc32() 返回无符号32位整数（0 to 4294967295）
    return Value.initInt(@intCast(crc));
}

/// ★F-172-b（R-268）：PHP 8.5.8 `hash_algos()` 的注册表（**原序**，非字母序）。
///   本表只回答「PHP 认不认这个名字」，不代表 AOT 已实现；未实现的（whirlpool/tiger/gost/haval/
///   snefru/md2/md4/fnv*/joaat/xxh*/murmur3/ripemd256/320）走 false，缺口登记在 F-170 尾。
const HASH_ALGOS = [_][]const u8{
    "md2",         "md4",         "md5",       "sha1",        "sha224",      "sha256",
    "sha384",      "sha512/224",  "sha512/256", "sha512",     "sha3-224",    "sha3-256",
    "sha3-384",    "sha3-512",    "ripemd128", "ripemd160",   "ripemd256",   "ripemd320",
    "whirlpool",   "tiger128,3",  "tiger160,3", "tiger192,3", "tiger128,4",  "tiger160,4",
    "tiger192,4",  "snefru",      "snefru256", "gost",        "gost-crypto", "adler32",
    "crc32",       "crc32b",      "crc32c",    "fnv132",      "fnv1a32",     "fnv164",
    "fnv1a64",     "joaat",       "murmur3a",  "murmur3c",    "murmur3f",    "xxh32",
    "xxh64",       "xxh3",        "xxh128",    "haval128,3",  "haval160,3",  "haval192,3",
    "haval224,3",  "haval256,3",  "haval128,4", "haval160,4", "haval192,4",  "haval224,4",
    "haval256,4",  "haval128,5",  "haval160,5", "haval192,5", "haval224,5",  "haval256,5",
};

/// ★F-172-b（R-268）：`hash_hmac_algos()` 的注册表（原序）；`hash_hmac`/`hash_pbkdf2` 只认这一集
///   ——非加密算法（adler32/crc32*/crc32c/fnv*/joaat/murmur*/xxh*）实测都抛 ValueError。
const HASH_CRYPTO_ALGOS = [_][]const u8{
    "md2",        "md4",        "md5",        "sha1",       "sha224",      "sha256",
    "sha384",     "sha512/224", "sha512/256", "sha512",     "sha3-224",    "sha3-256",
    "sha3-384",   "sha3-512",   "ripemd128",  "ripemd160",  "ripemd256",   "ripemd320",
    "whirlpool",  "tiger128,3", "tiger160,3", "tiger192,3", "tiger128,4",  "tiger160,4",
    "tiger192,4", "snefru",     "snefru256",  "gost",       "gost-crypto", "haval128,3",
    "haval160,3", "haval192,3", "haval224,3", "haval256,3", "haval128,4",  "haval160,4",
    "haval192,4", "haval224,4", "haval256,4", "haval128,5", "haval160,5",  "haval192,5",
    "haval224,5", "haval256,5",
};

fn hashAlgoInList(name: []const u8, list: []const []const u8) bool {
    for (list) |algo| {
        if (std.mem.eql(u8, algo, name)) return true;
    }
    return false;
}

fn hashAlgosToArray(algos: []const []const u8, allocator: Allocator) !Value {
    const arr = try PHPArray.init(allocator);
    for (algos) |algo| {
        try arr.push(allocator, Value.initString(try PHPString.init(allocator, algo)));
    }
    return Value.initArray(arr);
}

/// hash_algos - 返回 PHP 认可的哈希算法列表（原序）
pub fn php_hash_algos(allocator: Allocator) !Value {
    return hashAlgosToArray(&HASH_ALGOS, allocator);
}

/// hash_hmac_algos - 返回 PHP 认可的加密哈希算法列表（原序）
pub fn php_hash_hmac_algos(allocator: Allocator) !Value {
    return hashAlgosToArray(&HASH_CRYPTO_ALGOS, allocator);
}

/// base64_encode - 使用MIME base64编码数据
pub fn php_base64_encode(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    const encoder = std.base64.standard;
    const encoded_len = encoder.Encoder.calcSize(input.len);
    const encoded = try allocator.alloc(u8, encoded_len);
    defer allocator.free(encoded);

    _ = encoder.Encoder.encode(encoded, input);

    const php_str = try PHPString.init(allocator, encoded);
    return Value.initString(php_str);
}

/// base64_decode - 对使用MIME base64编码的数据进行解码
pub fn php_base64_decode(str: Value, strict: Value, allocator: Allocator) !Value {
    _ = strict;
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    const decoder = std.base64.standard;

    const decoded_max_len = decoder.Decoder.calcSizeForSlice(input) catch return Value.initBool(false);
    const decoded = try allocator.alloc(u8, decoded_max_len);
    defer allocator.free(decoded);

    decoder.Decoder.decode(decoded, input) catch return Value.initBool(false);

    const php_str = try PHPString.init(allocator, decoded[0..decoded_max_len]);
    return Value.initString(php_str);
}

// ============================================================================
// Concurrency Support
// ============================================================================

// ★Go 式协程 M1（设计稿 §3.4）：每协程私有全局态快照。
//   覆盖：异常旗与 pending 异常、@抑制深度（含保存栈）、src_file/src_line、
//   实参链（current_call_args + call_args_owned_stack）、q4 未定义 FIFO、last_throw 帧。
//   全局共享（不随快照）：堆与 RC、类表、分配器、对象 id 计数器（设计稿 §3.4 表）。
const CoroutineStateSnapshot = struct {
    has_exception: bool,
    current_exception: Value,
    error_suppress_depth: u32,
    error_suppress_saved_n: u32,
    error_suppress_saved: [128]i64,
    src_file: []const u8,
    src_line: u32,
    current_call_args: ?[]const Value,
    call_args_owned_stack: std.ArrayListUnmanaged(?[]Value),
    q4_undef_fifo: [16][]const u8,
    q4_undef_head: usize,
    q4_undef_tail: usize,
    ltf_active: bool,
    ltf_len: usize,
    ltf_buf: [512]u8,
};

comptime {
    std.debug.assert(@sizeOf(CoroutineStateSnapshot) <= concurrency.STATE_SNAPSHOT_CAPACITY);
}

fn coroSnap(buf: [*]u8) *CoroutineStateSnapshot {
    return @ptrCast(@alignCast(buf));
}

fn coroStateInit(buf: [*]u8) void {
    const s = coroSnap(buf);
    s.* = .{
        .has_exception = false,
        .current_exception = Value.initNull(),
        .error_suppress_depth = 0,
        .error_suppress_saved_n = 0,
        .error_suppress_saved = undefined,
        .src_file = "",
        .src_line = 0,
        .current_call_args = null,
        .call_args_owned_stack = .empty,
        .q4_undef_fifo = undefined,
        .q4_undef_head = 0,
        .q4_undef_tail = 0,
        .ltf_active = false,
        .ltf_len = 0,
        .ltf_buf = undefined,
    };
}

fn coroStateSave(buf: [*]u8) void {
    const s = coroSnap(buf);
    s.has_exception = has_exception;
    s.current_exception = current_exception;
    s.error_suppress_depth = error_suppress_depth;
    s.error_suppress_saved_n = error_suppress_saved_n;
    s.error_suppress_saved = error_suppress_saved;
    s.src_file = src_file;
    s.src_line = src_line;
    s.current_call_args = current_call_args;
    // 实参链栈：所有权随快照搬移（restore 时清空快照侧标记，防双重释放）。
    s.call_args_owned_stack = call_args_owned_stack;
    s.q4_undef_fifo = q4_undef_fifo;
    s.q4_undef_head = q4_undef_head;
    s.q4_undef_tail = q4_undef_tail;
    if (last_throw_frame) |frame| {
        s.ltf_active = true;
        s.ltf_len = frame.len;
        @memcpy(s.ltf_buf[0..frame.len], frame);
    } else {
        s.ltf_active = false;
        s.ltf_len = 0;
    }
}

fn coroStateRestore(buf: [*]const u8) void {
    const s: *const CoroutineStateSnapshot = @ptrCast(@alignCast(buf));
    has_exception = s.has_exception;
    current_exception = s.current_exception;
    error_suppress_depth = s.error_suppress_depth;
    error_suppress_saved_n = s.error_suppress_saved_n;
    error_suppress_saved = s.error_suppress_saved;
    src_file = s.src_file;
    src_line = s.src_line;
    current_call_args = s.current_call_args;
    call_args_owned_stack = s.call_args_owned_stack;
    // 快照内堆持有标记清空：所有权已移回全局（见 hooks 所有权纪律注释）。
    coroSnapMut(buf).call_args_owned_stack = .empty;
    q4_undef_fifo = s.q4_undef_fifo;
    q4_undef_head = s.q4_undef_head;
    q4_undef_tail = s.q4_undef_tail;
    if (s.ltf_active) {
        @memcpy(last_throw_frame_buf[0..s.ltf_len], s.ltf_buf[0..s.ltf_len]);
        last_throw_frame = last_throw_frame_buf[0..s.ltf_len];
    } else {
        last_throw_frame = null;
    }
}

fn coroSnapMut(buf: [*]const u8) *CoroutineStateSnapshot {
    return @ptrCast(@alignCast(@constCast(buf)));
}

fn coroStateDeinit(buf: [*]u8) void {
    const s = coroSnap(buf);
    // 仅释放快照仍持有的实参链栈缓冲（元素所有权语义与主路径一致：进程期不回收）。
    if (s.call_args_owned_stack.capacity > 0) {
        s.call_args_owned_stack.deinit(runtime_allocator);
        s.call_args_owned_stack = .empty;
    }
}

/// ★M2-1（D1=B 可选面）：协程异常记录表（id → Throwable + 抛出帧副本）。
///   仅在 go_join_error 未收取前驻留；go_join / go_wait_all / 进程收尾按 D1=A 兜底致命。
const CoroErrorRecord = struct {
    ex: Value,
    /// runtime_allocator 所有的抛出帧文本副本（null = 无帧）。
    frame: ?[]u8,
};

var coroutine_errors: std.AutoHashMapUnmanaged(u64, CoroErrorRecord) = .empty;

/// 捕获钩子：PHP 异常 ⇒ 记入表并正常返回（协程按 finished 收尾）；非 PHP 异常 ⇒ false 走致命。
fn coCaptureCoroutineError(coro_id: u64, _: anyerror) bool {
    if (!has_exception) return false;
    const ex = getException(); // 转移所有权并清旗（异常态不再留给快照）
    var frame_copy: ?[]u8 = null;
    if (last_throw_frame) |frame| {
        frame_copy = runtime_allocator.dupe(u8, frame) catch {
            ex.release(runtime_allocator);
            return false;
        };
    }
    coroutine_errors.put(runtime_allocator, coro_id, .{ .ex = ex, .frame = frame_copy }) catch {
        ex.release(runtime_allocator);
        if (frame_copy) |fc| runtime_allocator.free(fc);
        return false;
    };
    return true;
}

fn takeCoroError(coro_id: u64) ?CoroErrorRecord {
    return if (coroutine_errors.fetchRemove(coro_id)) |kv| kv.value else null;
}

/// D1=A 门禁：仍有未收取的协程异常 ⇒ 取最小 id 按未捕获致命（join / wait_all / 收尾共用）。
fn fatalOnUnobservedCoroutineErrors() void {
    if (coroutine_errors.count() == 0) return;
    var min_id: u64 = std.math.maxInt(u64);
    var it = coroutine_errors.iterator();
    while (it.next()) |entry| {
        if (entry.key_ptr.* < min_id) min_id = entry.key_ptr.*;
    }
    const rec = takeCoroError(min_id).?;
    coroutineFatalWithException(min_id, rec.ex, rec.frame);
}

fn coroutineErrorsDeinit() void {
    var it = coroutine_errors.iterator();
    while (it.next()) |entry| {
        entry.value_ptr.ex.release(runtime_allocator);
        if (entry.value_ptr.frame) |fc| runtime_allocator.free(fc);
    }
    coroutine_errors.deinit(runtime_allocator);
    coroutine_errors = .empty;
}

/// 未捕获协程异常的统一致命文案（立即路径与延迟到 join/wait_all 的路径共用）。
/// frame 为抛出帧文本（null ⇒ `#0 {coroutine}`）。
fn coroutineFatalWithException(coro_id: u64, ex: Value, frame: ?[]const u8) noreturn {
    var class_name: []const u8 = "Exception";
    var message: []const u8 = "";
    var ex_file: []const u8 = src_file;
    var ex_line: i64 = src_line;
    if (Value_isObject(ex)) {
        const obj = Value_asObject(ex);
        class_name = obj.class_name;
        if (obj.getProperty("message")) |msg_val| {
            if (msg_val.isString()) message = msg_val.asString().data;
        }
        if (obj.getProperty("file")) |fv| {
            if (fv.isString()) ex_file = fv.asString().data;
        }
        if (obj.getProperty("line")) |lv| {
            if (lv.isInt()) ex_line = lv.asInt();
        }
    } else if (ex.isString()) {
        message = ex.asString().data;
    }

    var trace_buf: [768]u8 = undefined;
    const trace: []const u8 = if (frame) |f|
        std.fmt.bufPrint(&trace_buf, "#0 {s}({d}): {s}\n#1 {{coroutine}}", .{ ex_file, ex_line, f }) catch "#0 {coroutine}"
    else
        "#0 {coroutine}";

    var ebuf: [1536]u8 = undefined;
    const emsg = std.fmt.bufPrint(
        &ebuf,
        "PHP Fatal error:  uncaught {s}: {s} in coroutine #{d}\n" ++
            "Stack trace:\n{s}\n" ++
            "  thrown in {s} on line {d}\n",
        .{ class_name, message, coro_id, trace, ex_file, ex_line },
    ) catch "";
    fileWriteAll(2, emsg);
    var buf: [1536]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "\nFatal error: uncaught {s}: {s} in coroutine #{d}\n" ++
            "Stack trace:\n{s}\n" ++
            "  thrown in {s} on line {d}\n",
        .{ class_name, message, coro_id, trace, ex_file, ex_line },
    ) catch "";
    fileWriteAll(1, msg);

    php_run_shutdown_functions();
    std.process.exit(255);
}

/// ★Go 式协程 M1（设计 D1=A）：协程内未捕获异常 ⇒ 整程序致命，文案含协程 id，rc=255。
/// ★M2-1：PHP 异常若已被捕获记录（go_join_error 面），此钩子不会被调用；
///   本钩子仅服务「立即致命」路径（非异常错误，或捕获失败）。
fn phpCoroutineUncaught(coro_id: u64, err: anyerror) noreturn {
    if (has_exception) {
        const ex = getException();
        coroutineFatalWithException(coro_id, ex, last_throw_frame);
    } else {
        // 非异常错误（OOM 等）逃逸协程体：同样整程序致命（D1=A）。
        var ebuf: [256]u8 = undefined;
        const emsg = std.fmt.bufPrint(
            &ebuf,
            "PHP Fatal error:  coroutine #{d} failed with error {s}\n",
            .{ coro_id, @errorName(err) },
        ) catch "";
        fileWriteAll(2, emsg);
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "\nFatal error: coroutine #{d} failed with error {s}\n",
            .{ coro_id, @errorName(err) },
        ) catch "";
        fileWriteAll(1, msg);
    }
    php_run_shutdown_functions();
    std.process.exit(255);
}

const CoroutineContext = struct {
    callable: Value,
    args: []Value,
    allocator: Allocator,
};

fn php_coroutine_entry(context: ?*anyopaque) anyerror!void {
    if (context) |ptr| {
        const ctx = @as(*CoroutineContext, @ptrCast(@alignCast(ptr)));
        defer ctx.allocator.destroy(ctx);
        defer ctx.allocator.free(ctx.args);

        // Ensure values are released when we are done
        defer {
            ctx.callable.release(ctx.allocator);
            for (ctx.args) |arg| {
                arg.release(ctx.allocator);
            }
        }

        // Execute the callable
        // ★Go 式协程 M1：错误一律向上抛给调度跳板，由 reportCoroutineError →
        //   phpCoroutineUncaught 按 D1=A 整程序致命（不再就地按 main 文案处理）。
        // ★G13（多协程能力加固）：协程体走完整 PHP 可调用矩阵——
        //   闭包 / 函数名字符串 / 'Class::method' / [obj, method] / [class, method] / __invoke 对象。
        //   旧实现只认「闭包」与「用户函数名字符串」两支，其余合法 callable 静默跳过协程体
        //   （go() 返回 id、join 立即完成、无任何报错——调用面静默失效）。可调用性已在
        //   php_go spawn 点校验，此处按形态分派：静态方法串走 php_call_static（php_invoke_callable
        //   的字符串支只查函数表，不含 '::' 解析），其余统一走 php_invoke_callable。
        const callable = if (ctx.callable.isRef()) ctx.callable.asRef().* else ctx.callable;
        const static_sep = if (callable.isString())
            std.mem.indexOf(u8, callable.asString().data, "::")
        else
            null;
        if (static_sep) |sep| {
            const name = callable.asString().data;
            if (sep > 0 and sep + 2 < name.len) {
                _ = try php_call_static(name[0..sep], name[sep + 2 ..], ctx.args, ctx.allocator);
            }
        } else {
            _ = try php_invoke_callable(callable, ctx.args, ctx.allocator);
        }
        // ★D1=A：正常返回但异常旗仍立 ⇒ 协程内未捕获异常（throw 走「返值+旗」通道
        //   而非 Zig 错误通道），按未捕获处理——抛特征错误，由跳板钩子打印并 exit(255)。
        if (has_exception) return error.UncaughtCoroutineException;
    }
}

pub fn php_go(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    if (args.len < 1) return error.MissingArgument;

    const callable = args[0];
    // ★G13：spawn 点校验可调用性（与 call_user_func 同口径，php_is_callable 无副作用）。
    //   旧实现不在 spawn 点校验：未定义函数 / 非法数组 / 无 __invoke 对象会被静默接受，
    //   协程体空跑（go() 看似成功、实际什么也没做）。此处改为可捕获错误：
    //   字符串未定义函数 ⇒ Error「Call to undefined function f()」（PHP 8 文案）；
    //   其余非法 callable ⇒ TypeError。调用方可 try/catch，杜绝静默失效。
    if (!(try php_is_callable(callable)).toBool()) {
        var cbuf: [512]u8 = undefined;
        if (callable.isString()) {
            const msg = std.fmt.bufPrint(&cbuf, "Call to undefined function {s}()", .{callable.asString().data}) catch "Call to undefined function";
            return try throwThrowable("Error", msg, allocator);
        }
        return try throwThrowable("TypeError", "go(): Argument #1 ($callable) must be a valid callback", allocator);
    }

    // ★F-1-b：作用域限定符在 spawn 点固化——协程体不继承调用方的 class scope 快照，
    //   `go self::m(...)` 的字符串若原样进协程，body 内会因「no class scope」致命。
    //   此处把 `self|static|parent::m` 改写为「具体类名::m」的新字符串（协程体持有其份额）。
    var coro_callable = callable;
    var coro_callable_owned = false;
    if (q4ResolveScopeCallable(callable, allocator)) |resolved| {
        coro_callable = resolved;
        coro_callable_owned = true;
    }
    // 后续任一步失败：改写串的 1 份份额由本守卫释放（成功路径已转交协程）。
    errdefer if (coro_callable_owned) coro_callable.release(allocator);

    const coro_args = try allocator.alloc(Value, args.len - 1);
    for (args[1..], 0..) |arg, i| {
        coro_args[i] = arg;
        _ = arg.retain();
    }

    const context = try allocator.create(CoroutineContext);
    context.* = .{
        .callable = coro_callable,
        .args = coro_args,
        .allocator = allocator,
    };
    // 改写串自带的 1 份份额直接转交协程；未改写 ⇒ 常规 retain 一份。
    if (!coro_callable_owned) _ = coro_callable.retain();

    const scheduler = try concurrency.getScheduler(allocator);
    const coro_id = try scheduler.spawn(php_coroutine_entry, context);

    return Value.initInt(@intCast(coro_id));
}

pub fn php_go_wait_all(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = args;
    _ = allocator;
    _ = concurrency.drainScheduler(null);
    // ★M2-1：wait_all 是同步点 ⇒ 未收取的协程异常按 D1=A 致命（go_join_error 收走的不再触发）。
    fatalOnUnobservedCoroutineErrors();
    return Value.initNull();
}

pub fn php_go_join(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = allocator;
    if (args.len == 0 or args[0].isNull()) {
        _ = concurrency.drainScheduler(null);
        fatalOnUnobservedCoroutineErrors();
        return Value.initNull();
    }
    const id = @as(u64, @intCast(args[0].toInt()));
    const scheduler = try concurrency.getScheduler(runtime_allocator);
    try scheduler.join(id);
    // ★M2-1：go_join 不收异常（M1 口径）⇒ 目标带未收取异常时在 join 点按 D1=A 致命。
    if (takeCoroError(id)) |rec| {
        coroutineFatalWithException(id, rec.ex, rec.frame);
    }
    return Value.initNull();
}

/// ★M2-1（D1=B 可选面）：`go_join_error(?int $id): ?Throwable`
///   等待 id 结束并返回其未捕获 Throwable（**收取后清除**，二次调用返回 null）；
///   正常结束 / 未知 id ⇒ null。异常收取后不再触发 D1=A 致命。
pub fn php_go_join_error(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = allocator;
    if (args.len == 0 or args[0].isNull()) return Value.initNull();
    const id = @as(u64, @intCast(args[0].toInt()));
    const scheduler = try concurrency.getScheduler(runtime_allocator);
    try scheduler.join(id);
    if (takeCoroError(id)) |rec| {
        if (rec.frame) |fc| runtime_allocator.free(fc);
        return rec.ex;
    }
    return Value.initNull();
}

pub fn go_spawn(func_name: []const u8, args: []const Value, allocator: Allocator) !Value {
    const callable = Value.initString(try PHPString.init(allocator, func_name));
    const full_args = try allocator.alloc(Value, args.len + 1);
    full_args[0] = callable;
    @memcpy(full_args[1..], args);
    defer allocator.free(full_args);

    return php_go(Value.initNull(), full_args, allocator);
}

pub const PHPMutex = struct {
    mutex: std.atomic.Mutex,
    lock_count: std.atomic.Value(u32),
    allocator: Allocator,

    pub fn init(allocator: Allocator) !*PHPMutex {
        const self = try allocator.create(PHPMutex);
        self.* = .{
            .mutex = .unlocked,
            .lock_count = std.atomic.Value(u32).init(0),
            .allocator = allocator,
        };
        return self;
    }

    pub fn deinit(self: *PHPMutex) void {
        self.allocator.destroy(self);
    }

    pub fn lock(self: *PHPMutex) void {
        spinLock(&self.mutex);
        _ = self.lock_count.fetchAdd(1, .monotonic);
    }

    pub fn unlock(self: *PHPMutex) void {
        _ = self.lock_count.fetchSub(1, .monotonic);
        self.mutex.unlock();
    }

    pub fn tryLock(self: *PHPMutex) bool {
        if (self.mutex.tryLock()) {
            _ = self.lock_count.fetchAdd(1, .monotonic);
            return true;
        }
        return false;
    }

    pub fn getLockCount(self: *const PHPMutex) u32 {
        return self.lock_count.load(.monotonic);
    }
};

pub const PHPAtomic = struct {
    value: std.atomic.Value(i64),
    allocator: Allocator,

    pub fn init(allocator: Allocator, initial: i64) !*PHPAtomic {
        const self = try allocator.create(PHPAtomic);
        self.* = .{
            .value = std.atomic.Value(i64).init(initial),
            .allocator = allocator,
        };
        return self;
    }

    pub fn deinit(self: *PHPAtomic) void {
        self.allocator.destroy(self);
    }

    pub fn load(self: *const PHPAtomic) i64 {
        return self.value.load(.monotonic);
    }

    pub fn store(self: *PHPAtomic, v: i64) void {
        self.value.store(v, .monotonic);
    }

    pub fn increment(self: *PHPAtomic) i64 {
        return self.value.fetchAdd(1, .monotonic) +% 1;
    }

    pub fn decrement(self: *PHPAtomic) i64 {
        return self.value.fetchSub(1, .monotonic) -% 1;
    }

    /// ★D-3 裁决（2026-11-09）：add/sub 返**新值**（与 increment/decrement 一致；
    ///   对齐 Go `atomic.AddInt64`）。溢出按原子回绕语义（+%/-%）。
    pub fn add(self: *PHPAtomic, delta: i64) i64 {
        return self.value.fetchAdd(delta, .monotonic) +% delta;
    }

    pub fn sub(self: *PHPAtomic, delta: i64) i64 {
        return self.value.fetchSub(delta, .monotonic) -% delta;
    }

    pub fn swap(self: *PHPAtomic, new_value: i64) i64 {
        return self.value.swap(new_value, .monotonic);
    }

    pub fn compareAndSwap(self: *PHPAtomic, expected: i64, new_value: i64) bool {
        return self.value.cmpxchgStrong(expected, new_value, .monotonic, .monotonic) == null;
    }
};

pub const PHPRWLock = struct {
    mutex: std.atomic.Mutex,
    readers: std.atomic.Value(i32),
    writer: std.atomic.Value(bool),
    allocator: Allocator,

    pub fn init(allocator: Allocator) !*PHPRWLock {
        const self = try allocator.create(PHPRWLock);
        self.* = .{
            .mutex = .unlocked,
            .readers = std.atomic.Value(i32).init(0),
            .writer = std.atomic.Value(bool).init(false),
            .allocator = allocator,
        };
        return self;
    }

    pub fn deinit(self: *PHPRWLock) void {
        self.allocator.destroy(self);
    }

    pub fn lockRead(self: *PHPRWLock) void {
        spinLock(&self.mutex);
        _ = self.readers.fetchAdd(1, .monotonic);
        self.mutex.unlock();
    }

    pub fn unlockRead(self: *PHPRWLock) void {
        spinLock(&self.mutex);
        _ = self.readers.fetchSub(1, .monotonic);
        self.mutex.unlock();
    }

    pub fn lockWrite(self: *PHPRWLock) void {
        spinLock(&self.mutex);
        self.writer.store(true, .monotonic);
    }

    pub fn unlockWrite(self: *PHPRWLock) void {
        self.writer.store(false, .monotonic);
        self.mutex.unlock();
    }

    pub fn getReaderCount(self: *const PHPRWLock) i32 {
        return self.readers.load(.monotonic);
    }

    pub fn getWriterCount(self: *const PHPRWLock) i32 {
        return if (self.writer.load(.monotonic)) 1 else 0;
    }
};

pub const PHPSharedData = struct {
    data: std.StringHashMap([]const u8),
    mutex: std.atomic.Mutex,
    allocator: Allocator,
    access_count: std.atomic.Value(u64),

    pub fn init(allocator: Allocator) !*PHPSharedData {
        const self = try allocator.create(PHPSharedData);
        self.* = .{
            .data = std.StringHashMap([]const u8).init(allocator),
            .mutex = .unlocked,
            .allocator = allocator,
            .access_count = std.atomic.Value(u64).init(0),
        };
        return self;
    }

    pub fn deinit(self: *PHPSharedData) void {
        var iter = self.data.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.data.deinit();
        self.allocator.destroy(self);
    }

    pub fn get(self: *PHPSharedData, key: []const u8) ?[]const u8 {
        _ = self.access_count.fetchAdd(1, .monotonic);
        spinLock(&self.mutex);
        defer self.mutex.unlock();
        return self.data.get(key);
    }

    pub fn set(self: *PHPSharedData, key: []const u8, value: []const u8) !void {
        spinLock(&self.mutex);
        defer self.mutex.unlock();

        if (self.data.fetchRemove(key)) |kv| {
            self.allocator.free(kv.key);
            self.allocator.free(kv.value);
        }

        const key_copy = try self.allocator.dupe(u8, key);
        errdefer self.allocator.free(key_copy);
        const value_copy = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(value_copy);

        try self.data.put(key_copy, value_copy);
    }

    pub fn remove(self: *PHPSharedData, key: []const u8) bool {
        spinLock(&self.mutex);
        defer self.mutex.unlock();

        if (self.data.fetchRemove(key)) |kv| {
            self.allocator.free(kv.key);
            self.allocator.free(kv.value);
            return true;
        }
        return false;
    }

    pub fn has(self: *PHPSharedData, key: []const u8) bool {
        spinLock(&self.mutex);
        defer self.mutex.unlock();
        return self.data.contains(key);
    }

    pub fn size(self: *PHPSharedData) usize {
        spinLock(&self.mutex);
        defer self.mutex.unlock();
        return self.data.count();
    }

    pub fn clear(self: *PHPSharedData) void {
        spinLock(&self.mutex);
        defer self.mutex.unlock();

        var iter = self.data.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.data.clearRetainingCapacity();
    }

    pub fn getAccessCount(self: *const PHPSharedData) u64 {
        return self.access_count.load(.monotonic);
    }
};

pub fn channel_new(capacity: i64, allocator: Allocator) !Value {
    const obj = try php_object_new("Channel", allocator);
    const channel = try concurrency.Channel(Value).init(allocator, @intCast(capacity));
    const ptr_val = Value.initInt(@intCast(@intFromPtr(channel)));
    try Value_asObject(obj).setProperty("_ptr", ptr_val);
    return obj;
}

pub fn channel_send(ch: Value, val: Value) !void {
    if (!Value_isObject(ch)) return error.InvalidChannel;
    const obj = Value_asObject(ch);
    if (obj.getProperty("_ptr")) |ptr_val| {
        const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));
        _ = val.retain();
        channel.send(val) catch |err| {
            // ★Go 式协程 M1：close 后 send ⇒ 可捕获 Error「send on closed channel」（设计稿 §3.3）。
            val.release(runtime_allocator);
            if (err == error.ChannelClosed) {
                _ = throwThrowable("Error", "send on closed channel", runtime_allocator);
            }
            return err;
        };
    }
}

pub fn channel_recv(ch: Value) !Value {
    if (!Value_isObject(ch)) return error.InvalidChannel;
    const obj = Value_asObject(ch);
    if (obj.getProperty("_ptr")) |ptr_val| {
        const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));
        return channel.recv() catch |err| {
            if (err == error.ChannelClosed) return Value.initNull();
            return err;
        };
    }
    return Value.initNull();
}

pub fn channel_close(ch: Value) void {
    if (!Value_isObject(ch)) return;
    const obj = Value_asObject(ch);
    if (obj.getProperty("_ptr")) |ptr_val| {
        const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));
        channel.close();
    }
}

fn registerChannelClassNamed(allocator: Allocator, class_name: []const u8) !void {
    const meta = try ClassMeta.init(allocator, class_name);

    try meta.addMethod(.{
        .name = "__construct",
        .func = struct {
            fn call(ctx: Value, args: []const Value, runtime_alloc: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                var capacity: usize = 0;
                if (args.len > 0) {
                    capacity = @intCast(args[0].toInt());
                }
                const channel = try concurrency.Channel(Value).init(runtime_alloc, capacity);
                const ptr_val = Value.initInt(@intCast(@intFromPtr(channel)));
                try this.setProperty("_ptr", ptr_val);
                return Value.initNull();
            }
        }.call,
        .is_static = false,
    });

    try meta.addMethod(.{
        .name = "send",
        .func = struct {
            fn call(ctx: Value, args: []const Value, runtime_alloc: Allocator) anyerror!Value {
                const this = Value_asObject(ctx);
                if (args.len < 1) return error.MissingArgument;

                const ptr_val = this.getProperty("_ptr") orelse return error.InvalidChannel;
                const channel = @as(*concurrency.Channel(Value), @ptrFromInt(@as(usize, @intCast(ptr_val.asInt()))));

                const val = args[0];
                _ = val.retain();
                channel.send(val) catch |err| {
                    // ★Go 式协程 M1：close 后 send ⇒ 可捕获 Error「send on closed channel」（设计稿 §3.3）。
                    val.release(runtime_alloc);
                    if (err == error.ChannelClosed) {
                        return throwThrowable("Error", "send on closed channel", runtime_alloc);
                    }
                    return err;
                };
                return Value.initNull();
            }
