// ============================================================================
// 新增缺失的内置函数
// ============================================================================

/// rewind - 倒回文件指针的位置
/// ★R-274：原实现把句柄当**整数指针**（`handle.isInt()`），与 AOT 的 resource 模型不符 ⇒ 恒 false；
///   改为 resource 版：lseek 到 0 并清除 EOF。
pub fn php_rewind(handle: Value) !Value {
    if (!handle.isResource()) return Value.initBool(false);
    const res = handle.asResource();
    const fh = res.file_handle orelse return Value.initBool(false);
    // ★M2-2：socket 对流不可 seek（PHP 8.5.8 实测：Warning + false）
    if (res.sock) {
        emitWarning("rewind(): Stream does not support seeking");
        return Value.initBool(false);
    }
    _ = streamLseek(fh, 0, 0) catch return Value.initBool(false);
    res.eof = false;
    return Value.initBool(true);
}

/// gethostbyaddr - 获取指定IP地址对应的主机名
pub fn php_gethostbyaddr(ip: Value, allocator: Allocator) !Value {
    if (!ip.isString()) return Value.initBool(false);
    const ip_str = ip.asString().data;
    // 简化实现：对于本地地址直接返回
    if (std.mem.eql(u8, ip_str, "127.0.0.1")) {
        return Value.initString(try PHPString.init(allocator, "localhost"));
    }
    // 其他地址返回原 IP（模拟 PHP 在无法反解时的行为）
    return Value.initString(try PHPString.init(allocator, ip_str));
}

/// hash_file - 使用给定文件的内容生成哈希值
/// ★R-269：文件读取失败的统一告警（PHP 措辞：`{fn}({path}): Failed to open stream: {reason}`）。
fn warnOpenStream(func_name: []const u8, fname: []const u8, err: anyerror) void {
    var mbuf: [1024]u8 = undefined;
    const reason: []const u8 = switch (err) {
        error.FileNotFound => "No such file or directory",
        error.AccessDenied => "Permission denied",
        else => @errorName(err),
    };
    const msg = std.fmt.bufPrint(&mbuf, "{s}({s}): Failed to open stream: {s}", .{ func_name, fname, reason }) catch return;
    emitWarning(msg);
}

/// hash_file - 计算文件内容的哈希（PHP 契约：algo, filename, binary=false, options=[]）
///   ★R-269：原实现只收 2 形参且内部调用 `php_hash` 少传 `raw_output`（任何调用都会编译失败）；
///   且算法名校验必须**先于开文件**（PHP 实测：文件不存在 + 算法非法 ⇒ ValueError 而不是 Warning）。
pub fn php_hash_file(algo: Value, filename: Value, binary: Value, options_val: Value, allocator: Allocator) !Value {
    _ = options_val; // PHP 实测忽略 options 内容
    if (!algo.isString() or !filename.isString()) return Value.initBool(false);

    var algo_buf: [128]u8 = undefined;
    const algo_str = hashAlgoLower(algo.asString().data, &algo_buf);
    if (!hashAlgoInList(algo_str, &HASH_ALGOS)) {
        return throwThrowable("ValueError", "hash_file(): Argument #1 ($algo) must be a valid hashing algorithm", runtime_allocator);
    }
    const fname = filename.asString().data;

    const content = std.Io.Dir.cwd().readFileAlloc(getIo(), fname, allocator, .limited(10 * 1024 * 1024)) catch |err| {
        warnOpenStream("hash_file", fname, err);
        return Value.initBool(false);
    };
    defer allocator.free(content);

    return hashBytes(algo_str, content, binary.toBool(), allocator);
}

/// get_resource_type - 返回资源类型
/// get_resource_type - ★批次二十九：废止恒 "Unknown" 桩（红线同类——静默假数据）。
///   PHP 语义：返回资源类型名（AOT 资源自带 type_name 单一事实源）；非资源 ⇒ ZPP TypeError。
pub fn php_get_resource_type(res: Value, allocator: Allocator) !Value {
    if (!res.isResource() and !res.hasResourceType()) {
        const tname = if (Value_isObject(res)) Value_asObject(res).class_name else valueTypeName(res);
        return throwThrowable("TypeError", std.fmt.bufPrint(&q4_te_buf, "get_resource_type(): Argument #1 ($resource) must be of type resource, {s} given", .{tname}) catch "", runtime_allocator);
    }
    const r = res.asResource();
    return Value.initString(try PHPString.init(allocator, r.type_name));
}

/// stream_register_wrapper - 注册一个用 PHP 类实现的 URL 封装协议
pub fn php_stream_register_wrapper(protocol: Value, classname: Value, allocator: Allocator) !Value {
    _ = allocator;
    _ = classname;
    // ★批次二十九（红线）：废止「收下参数静默 return true」假成功桩。
    //   用户自定义包装器需要 stream_open/read/write/close/eof/… 全协议方法回调派发桥，
    //   真实现为大工程（已报老铁方案与成本）；在此之前诚实失败（PHP 失败形：Warning+false）。
    const proto: []const u8 = if (protocol.isString()) protocol.asString().data else "?";
    var mbuf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&mbuf, "stream_wrapper_register(): AOT does not support user-defined stream wrapper '{s}://' (protocol dispatch bridge not implemented)", .{proto}) catch "stream_wrapper_register(): not supported in AOT";
    emitWarning(msg);
    return Value.initBool(false);
}
